# UI helper: compact width / height / font row + download button for the
# tab 1.1 figure exports. Defined at TOP LEVEL because ui is constructed
# outside server(), so a server-scoped helper would not be visible here.
.v1_pdf_controls <- function(prefix, dl_id, default_fs = 14, extra = NULL) {
  tagList(
    tags$hr(),
    tags$b("Export figure as PDF", style = "font-size:13px;"),
    tags$p(tags$small(
      "Re-renders the figure at the chosen size, independent of the panel on screen."),
      style = "color:grey;font-size:11px;margin-bottom:4px;"),
    fluidRow(
      column(3, numericInput(paste0(prefix, "_pdf_w"),  "Width (in):",  value = 8,
                             min = 2, max = 30, step = 0.5)),
      column(3, numericInput(paste0(prefix, "_pdf_h"),  "Height (in):", value = 6,
                             min = 2, max = 30, step = 0.5)),
      column(3, numericInput(paste0(prefix, "_pdf_fs"), "Font (pt):",   value = default_fs,
                             min = 6, max = 36, step = 1)),
      column(3, extra)
    ),
    downloadButton(dl_id, "\u2b07 Download PDF", class = "btn-success",
                   style = "width:100%;")
  )
}

# ── Per-plot layer selector (⑫) ───────────────────────────────────────────────
# One builder, three call sites, so the three controls cannot drift apart. The
# default differs by plot on purpose: a violin should show the values the test
# used, whereas a feature plot overlaid on the embedding should match the
# embedding. Only shown for the NA-aware routes, where the two layers differ.
# ── Shared UI for the two new marker plots (Heatmap, Abundance trajectory) ────
# Top level, because ui is built outside server(). `p` is the control-id prefix:
# "s_mk" for the ⑨ Markers tab, "i_mk" for ⑫ Integrated Markers. Both tabs get
# byte-identical controls this way, and the server builders read them back by
# the same prefix.
.mk_layer_choices <- c(
  "data \u2014 as tested"                      = "data",
  "data \u2014 observed only"                  = "data_obs",
  "scale.data \u2014 covariates regressed out" = "scale.data")

.mk_heatmap_controls <- function(p) {
  tagList(
    tags$p(tags$small(
      "Select features by hand and draw them as a heatmap, with metadata strips above the ",
      "columns. Columns are either every cell or one column per cluster (the cluster mean), ",
      "and rows can be z-scored so features on different abundance scales are comparable."),
      style="color:grey;margin-top:6px;"),
    uiOutput(paste0(p, "_hm_genes_ui")),
    fluidRow(
      column(3, radioButtons(paste0(p, "_hm_cols"), "Columns are:",
               choices=c("One per cell" = "cell", "One per cluster (mean)" = "cluster"),
               selected="cluster")),
      column(3, radioButtons(paste0(p, "_hm_scale"), "Row values:",
               choices=c("Raw (as in the layer)" = "none",
                         "Z-score per protein"   = "row"),
               selected="row")),
      column(3,
        numericInput(paste0(p, "_hm_breaks"), "Colour breaks:", value=7, min=3, max=21, step=2),
        numericInput(paste0(p, "_hm_limit"), "Symmetric cap (0 = auto):",
                     value=0, min=0, max=20, step=0.5)),
      column(3,
        checkboxInput(paste0(p, "_hm_clust_rows"), "Cluster rows (dendrogram order)", value=TRUE),
        checkboxInput(paste0(p, "_hm_clust_cols"), "Cluster columns", value=FALSE),
        checkboxInput(paste0(p, "_hm_rownames"),  "Show protein names", value=TRUE))
    ),
    uiOutput(paste0(p, "_hm_anno_ui")),
    radioButtons(paste0(p, "_hm_src"), "Values from which layer?", inline=TRUE,
                 choices=.mk_layer_choices, selected="data"),
    tags$p(tags$small(
      "Z-scoring per feature is computed across the columns actually drawn, so a row scaled ",
      "over cluster means is not the same as the same row scaled over single cells. ",
      "With ", tags$b("one per cell"), " and a z-scored row, a not-detected cell on the ",
      "data layer sits at the low end; on scale.data it sits at the centre, where it is ",
      "indistinguishable from an average cell."),
      style="color:#7f8c8d;font-size:11px;"),
    withSpinner(plotOutput(paste0(p, "_hm_plot"), height="600px"))
  )
}

.mk_traj_controls <- function(p) {
  tagList(
    tags$p(tags$small(
      "Abundance of selected feature across clusters plotted together as a group or individual cells. ",
      "Multiple features can be plotted individually or all together."),
      style="color:grey;margin-top:6px;"),
    uiOutput(paste0(p, "_tj_genes_ui")),
    fluidRow(
      column(3, radioButtons(paste0(p, "_tj_mode"), "Show:",
               choices=c("Cluster mean \u00b1 band" = "mean",
                         "Every cell + mean line"  = "cells"),
               selected="mean")),
      column(3, radioButtons(paste0(p, "_tj_band"), "Band shows:",
               choices=c("Standard error" = "se", "Standard deviation" = "sd",
                         "None" = "none"),
               selected="se")),
      column(3, radioButtons(paste0(p, "_tj_center"), "Protein values:",
               choices=c("Raw (as in the layer)"            = "none",
                         "Centred per protein"              = "center",
                         "Z-scored per protein"             = "z"),
               selected="z")),
      column(3,
        checkboxInput(paste0(p, "_tj_facet"), "One panel per protein", value=FALSE),
        numericInput(paste0(p, "_tj_pt"), "Point size:", value=1.6, min=0, max=6, step=0.2))
    ),
    uiOutput(paste0(p, "_tj_ptcol_ui")),
    uiOutput(paste0(p, "_tj_order_ui")),
    radioButtons(paste0(p, "_tj_src"), "Values from which layer?", inline=TRUE,
                 choices=.mk_layer_choices, selected="data"),
    tags$p(tags$small(
      "Centring and z-scoring are done across the CLUSTER MEANS, not across cells, so every ",
      "profile crosses zero somewhere and the lines compare shape rather than level. ",
      "The x axis is a sequence of clusters, not a measured quantity \u2014 the connecting ",
      "lines are a visual aid, not an interpolation, so reorder the clusters below if they ",
      "have a meaningful order."),
      style="color:#7f8c8d;font-size:11px;"),
    withSpinner(plotOutput(paste0(p, "_tj_plot"), height="520px"))
  )
}

.i_layer_radio <- function(id, default) {
  conditionalPanel(
    "input.s_norm_method == 'vsn' || input.s_norm_method == 'scpmed' || input.s_norm_method == 'log2'",
    radioButtons(id, "Plot which layer?", inline=TRUE,
      choices=c("data \u2014 as tested"="data",
                "data \u2014 observed only"="data_obs",
                "scale.data \u2014 covariates regressed out"="scale.data"),
      selected=default),
    tags$p(tags$small(
      tags$b("data"), " is the matrix the integrated markers were tested on, so group ",
      "medians correspond to the reported effects. ",
      tags$b("data \u2014 observed only"), " drops the not-detected cells instead of drawing them ",
      "as a spike, so the violin shows the distribution the test was fitted on; it changes ",
      "nothing on the dot plot or the feature plot, where not-detected is already excluded or ",
      "already at the bottom of the scale. ",
      tags$b("scale.data"), " has the \u2465 covariates regressed out and is z-scored per ",
      "protein, so it matches the embedding \u2014 but not-detected sits at 0, the centre of ",
      "the scale, so missingness and average abundance look alike there."),
      style="color:grey;font-size:11px;margin:0 0 6px 0;"))
}

# ── Static assets ────────────────────────────────────────────────────────────
# Shiny serves files from a www/ subfolder at the web root and nowhere else, so
# an image sitting NEXT TO the script is not reachable by src="scpviz.png".
# Expose the script's own directory under a virtual prefix so both layouts work:
#
#   app_folder/www/scpviz.png   -> served at "scpviz.png"           (Shiny default)
#   app_folder/scpviz.png       -> served at "appfiles/scpviz.png"  (this block)
#
# The app directory is resolved rather than assumed: getwd() is correct when the
# app is launched by runApp() or the Run App button, but not when the file is
# sourced, in which case the path is on `ofile` in one of the calling frames.
.app_dir <- local({
  of <- NULL
  for (fr in sys.frames()) if (!is.null(fr$ofile)) of <- fr$ofile
  if (!is.null(of)) dirname(normalizePath(of, mustWork = FALSE)) else getwd()
})
try(shiny::addResourcePath("appfiles", .app_dir), silent = TRUE)

# Prefer www/ when present, fall back to the sibling file, and resolve to NULL if
# neither exists so a missing logo is simply absent rather than a broken-image box.
.logo_src <- local({
  if (file.exists(file.path(.app_dir, "www", "scpviz.png"))) "scpviz.png"
  else if (file.exists(file.path(.app_dir, "scpviz.png")))   "appfiles/scpviz.png"
  else {
    message("scpviz.png not found in ", .app_dir,
            " or its www/ subfolder \u2014 the logo will be omitted.")
    NULL
  }
})

# ── Bundled example datasets ────────────────────────────────────────────────
# Resolved against .app_dir, not the working directory. EXAMPLE_FILE was a bare
# relative path, so it only loaded when the cwd happened to be the app folder;
# launching from anywhere else gave "example_data.csv not found".
#
# Layout searched, first hit wins per subfolder:
#   app_folder/csv_example_sets/*.csv    -> SCP-Viz 1.1 tab
#   app_folder/RData_example_sets/*.RData -> Seurat analysis tab
# A loose file sitting next to the script is still accepted as a fallback, so
# existing single-file installs keep working.
.example_dirs <- function(sub) {
  cands <- c(file.path(.app_dir, sub), file.path(getwd(), sub))
  cands[dir.exists(cands)][1]
}

# Named vector: display name -> absolute path. Empty when nothing is found.
.example_sets <- function(sub, exts, legacy = character(0)) {
  d <- .example_dirs(sub)
  out <- character(0)
  if (!is.na(d) && !is.null(d)) {
    pat <- paste0("\\.(", paste(exts, collapse="|"), ")$")
    f <- list.files(d, pattern = pat, ignore.case = TRUE, full.names = TRUE)
    if (length(f)) out <- stats::setNames(f, tools::file_path_sans_ext(basename(f)))
  }
  # Legacy loose files beside the script, listed after anything in the subfolder.
  for (lf in legacy) {
    p <- file.path(.app_dir, lf)
    if (file.exists(p) && !(normalizePath(p, mustWork=FALSE) %in%
                            normalizePath(out, mustWork=FALSE)))
      out <- c(out, stats::setNames(p, paste0(basename(lf), "  (app folder)")))
  }
  out[order(names(out))]
}

.CSV_EXAMPLES   <- .example_sets("csv_example_sets",   c("csv","tsv","txt"),
                                 legacy = EXAMPLE_FILE)
.RDATA_EXAMPLES <- .example_sets("RData_example_sets", c("RData","Rdata","rdata","rds"),
                                 legacy = EXAMPLE_RDATA)

if (!length(.CSV_EXAMPLES))
  message("No CSV example sets found in ", file.path(.app_dir, "csv_example_sets"),
          " or beside the script \u2014 the 1.1 example picker will be empty.")
if (!length(.RDATA_EXAMPLES))
  message("No RData example sets found in ", file.path(.app_dir, "RData_example_sets"),
          " or beside the script \u2014 the Seurat example picker will be empty.")

# The 1.1 tab prefills keyword / feature / conditions for the ORIGINAL bundled
# example only. Any other set is loaded without those assumptions, because its
# column names and conditions are unknown.
.is_builtin_csv_example <- function(path) {
  !is.null(path) && nzchar(path) &&
    identical(tolower(basename(path)), tolower(EXAMPLE_FILE))
}

# ── Downloadable user guides ────────────────────────────────────────────────
# Edit these two filenames to match your PDFs.
GUIDE_SHORT_FILE <- "SCP-Viz_User_Guide_Short.pdf"
GUIDE_LONG_FILE  <- "SCP-Viz_User_Guide_Full.pdf"

# Resolved against .app_dir, not the working directory, for the same reason the
# logo is: getwd() is only the app folder when launched with runApp(). Looks in
# user_guides/ first, then www/, then beside the script, so any of the three
# layouts works. Returns NULL when the file is absent, which is what lets the
# UI omit the button instead of offering a broken download.
.guide_path <- function(fname) {
  cands <- c(file.path(.app_dir, "user_guides", fname),
             file.path(.app_dir, "www",         fname),
             file.path(.app_dir,                fname))
  hit <- cands[file.exists(cands)]
  if (length(hit)) normalizePath(hit[1], mustWork = FALSE) else NULL
}

.GUIDE_SHORT <- .guide_path(GUIDE_SHORT_FILE)
.GUIDE_LONG  <- .guide_path(GUIDE_LONG_FILE)

if (is.null(.GUIDE_SHORT) && is.null(.GUIDE_LONG))
  message("No user-guide PDFs found in ", file.path(.app_dir, "user_guides"),
          " (or www/, or beside the script) \u2014 the download buttons will be omitted.")

# Human-readable size, so the button says what it is about to hand over.
.guide_size <- function(p) {
  if (is.null(p)) return("")
  kb <- file.size(p) / 1024
  if (!is.finite(kb)) return("")
  if (kb >= 1024) sprintf("  (%.1f MB)", kb / 1024) else sprintf("  (%.0f KB)", kb)
}

