                   tags$b("Subpopulation Labeling"),
                   tags$p(tags$small("Select bars on the plot, type a label, then click Assign."),
                          style = "color: grey;"),
                   textInput("subpop_label_bar", "New Subpopulation Label:", value = ""),
                   fluidRow(
                     column(6, actionButton("assign_label_bar", "Assign to Selected",
                                            class = "btn-success", style = "width:100%")),
                     column(6, actionButton("clear_labels_bar", "Clear All Labels",
                                            class = "btn-danger",  style = "width:100%"))
                   ),
                   tags$br(),
                   uiOutput("download_subpop_bar_ui")),
          tabPanel("Box Plot",
                   radioButtons("log2_choice_box", "Choose Scale:",
                                choices = c("Original" = "original", "Log2" = "log2")),
                   uiOutput("box_order_ui"),
                   plotOutput("box_plot"),
                   .v1_pdf_controls("box", "download_box_pdf", 14)),
          tabPanel("Histogram",
                   radioButtons("log2_choice_hist", "Choose Scale:",
                                choices = c("Original" = "original", "Log2" = "log2")),
                   sliderInput("bin_height", "Choose Number of Bins:", min = 5, max = 250, value = 50),
                   plotlyOutput("hist_plot")),
          tabPanel("Density Plot",
                   radioButtons("log2_choice_dens", "Choose Scale:",
                                choices = c("Original" = "original", "Log2" = "log2")),
                   plotOutput("density_plot")),
          tabPanel("Violin Plot",
                   radioButtons("log2_choice_violin", "Choose Scale:",
                                choices = c("Original" = "original", "Log2" = "log2")),
                   plotlyOutput("violin_plot")),
          tabPanel("Dimensionality Reduction",
                   radioButtons("dimred_method", "Choose Method:",
                                choices = c("PCA", "UMAP", "t-SNE"), inline = TRUE),
                   radioButtons("log2_choice_pca", "Choose Scale:",
                                choices = c("Original" = "original", "Log2" = "log2")),
                   conditionalPanel(
                     condition = "input.dimred_method == 't-SNE'",
                     sliderInput("tsne_perplexity", "t-SNE Perplexity:", min = 5, max = 50, value = 30)),
                   conditionalPanel(
                     condition = "input.dimred_method == 'UMAP'",
                     sliderInput("umap_neighbors", "UMAP N Neighbors:", min = 2, max = 50, value = 15)),
                   sliderInput("pca_min_detect",
                               "Min % of cells a feature must be quantified in:",
                               min = 0, max = 100, value = 70, step = 5),
                   tags$p(tags$small(
                     "Features below this detection rate are dropped; remaining gaps are ",
                     "filled with the feature mean. Set to 100% for complete cases only."),
                     style = "color:grey;font-size:11px;"),
                   withSpinner(plotlyOutput("pca_plot")),
                   uiOutput("download_pca_plot_button_ui"),
                   .v1_pdf_controls("dimred", "download_dimred_pdf", 14,
                     extra = numericInput("dimred_pdf_pt", "Point size:",
                                          value = 3, min = 0.25, max = 12, step = 0.25)),
                   tags$hr(),
                   tags$b("Subpopulation Labeling"),
                   tags$p(tags$small("Select points on the plot, type a label, then click Assign."),
                          style = "color: grey;"),
                   textInput("subpop_label", "New Subpopulation Label:", value = ""),
                   fluidRow(
                     column(6, actionButton("assign_label", "Assign to Selected",
                                            class = "btn-success", style = "width:100%")),
                     column(6, actionButton("clear_labels", "Clear All Labels",
                                            class = "btn-danger",  style = "width:100%"))
                   ),
                   tags$br(),
                   uiOutput("download_subpop_ui")),
          tabPanel("Volcano Plot",
                   tags$p(tags$small(
                     "Compare any two groups — including subpopulations you've labeled on other tabs."),
                     style = "color: grey; margin-top: 8px;"),
                   fluidRow(
                     column(4, selectInput("volcano_group_a", "Group A:", choices = NULL)),
                     column(4, selectInput("volcano_group_b", "Group B:", choices = NULL)),
                     column(4,
                            numericInput("volcano_fc",   "Min |log2 FC|:", value = 1,    min = 0, step = 0.1),
                            numericInput("volcano_pval", "Max p-value:",   value = 0.05, min = 0, max = 1, step = 0.01))
                   ),
                   fluidRow(
                     column(4,
                       numericInput("volcano_xmin", "X-axis min (blank = auto):",
                                    value = NA, step = 0.5),
                       numericInput("volcano_xmax", "X-axis max (blank = auto):",
                                    value = NA, step = 0.5)),
                     column(4,
                       selectInput("volcano_label_mode", "Label points:",
                         choices = c("None"                              = "none",
                                     "Top by p-value"                    = "pval",
                                     "Top by |log2FC|"                   = "fc",
                                     "Outermost (log2FC + p-value)"      = "both"),
                         selected = "none"),
                       numericInput("volcano_label_n", "How many to label:",
                                    value = 10, min = 0, max = 200, step = 1),
                       selectizeInput("volcano_pick", "Or label specific features (max 30):",
                                      choices = NULL, multiple = TRUE,
                                      options = list(maxItems = 30,
                                                     placeholder = "Run the volcano first\u2026"))),
                     column(4,
                       checkboxInput("volcano_label_sig_only",
                                     "Only label significant points", value = TRUE),
                       tags$p(tags$small(
                         "Axis limits only change the view \u2014 no points are removed, so the ",
                         "table and counts are unaffected. 'Outermost' scales each axis to unit ",
                         "range before ranking by distance from the origin, so neither axis wins ",
                         "on units alone."),
                         style = "color:grey;font-size:11px;"))
                   ),
                   actionButton("run_volcano", "Run Volcano", class = "btn-primary"),
                   tags$br(), tags$br(),
                   withSpinner(plotlyOutput("volcano_plot", height = "600px")),
                   uiOutput("download_volcano_ui"),
                   .v1_pdf_controls("volcano", "download_volcano_pdf", 14,
                     extra = numericInput("volcano_pdf_pt", "Point size:",
                                          value = 2, min = 0.25, max = 12, step = 0.25)))
        )
      )
    )
  ),

  # ══════════════════════════════════════════════════════════════════════════
  #  TAB 1.5 — SCP-QC  (all IDs prefixed "q_")
  # ══════════════════════════════════════════════════════════════════════════
  tabPanel("SCP-QC",
    fluidPage(
      fluidRow(column(12,
        div(class="s-card",style="margin-top:10px;background:#f0f8ff;border-color:#aed6f1;",
          tags$h4("SCP-QC — Single Cell Proteomics Quality Control", style="color:#2c3e50;margin:0 0 4px 0;"),
          tags$p(tags$small(
            "Load 1 or 2 RData files (prt.int + meta.samples). Optionally merge datasets. ",
            "Filter cells by abundance outliers, assess feature detection per cell, ",
            "compare groups statistically (Kruskal-Wallis + Dunn), and apply sparsity reduction."),
            style="color:grey;margin:0;")
        )
      )),

      tabsetPanel(id="q_tabs",

        # ── Q1: Load Data ───────────────────────────────────────────────────
        tabPanel("① Load Data",
          fluidRow(
            column(4, div(class="s-card",style="margin-top:12px;",
              tags$h5("Dataset 1"),
              fileInput("q_rdata1","Upload .RData (prt.int + meta.samples)",accept=c(".RData",".Rdata",".rds")),
              textInput("q_label1","Dataset 1 label:","Dataset1"),
              actionButton("q_load1","▶  Load Dataset 1",class="btn-primary",style="width:100%;")
            )),
            column(4, div(class="s-card",style="margin-top:12px;",
              tags$h5("Dataset 2 (optional — for merging)"),
              fileInput("q_rdata2","Upload .RData (prt.int + meta.samples)",accept=c(".RData",".Rdata",".rds")),
              textInput("q_label2","Dataset 2 label:","Dataset2"),
              checkboxInput("q_merge_enable","Merge with Dataset 1",FALSE),
              actionButton("q_load2","▶  Load & Merge",class="btn-info",style="width:100%;")
            )),
            column(4, div(class="s-card",style="margin-top:12px;",
              tags$h5("Load status"),
              uiOutput("q_load_status"),
              tags$hr(),
              tags$h5("Meta.samples preview"),
              DTOutput("q_meta_preview")
            ))
          )
        ),

        # ── Q2: Merged Matrix ───────────────────────────────────────────────
        tabPanel("② Merged Matrix",
          fluidRow(
            column(3, div(class="s-card",style="margin-top:12px;",
              tags$h5("Matrix summary"),
              uiOutput("q_matrix_summary"),
              tags$hr(),
              downloadButton("q_dl_prt","⬇ Download prt.int (.csv)",class="btn-default",style="width:100%;margin-bottom:4px;"),
              downloadButton("q_dl_meta","⬇ Download meta.samples (.csv)",class="btn-default",style="width:100%;")
            )),
            column(9, div(class="s-card",style="margin-top:12px;",
              tags$h5("prt.int matrix (first 200 features × 20 cells)"),
              tags$p(tags$small("NA = feature not detected. Rows = features, Columns = cells."),style="color:grey;"),
              DTOutput("q_prt_preview")
            ))
          )
        ),

        # ── Q3: Cell QC ─────────────────────────────────────────────────────
        tabPanel("③ Cell QC",
          fluidRow(
            column(3, div(class="s-card",style="margin-top:12px;",
              tags$h5("Abundance metrics"),
              tags$p(tags$small(
                "Computes per-cell: total intensity, median intensity, mean intensity, ",
                "and number of quantified features. Matches qc-sparsity-reduction.R abundance table."),
                style="color:grey;font-size:11px;"),
              uiOutput("q_groupby_ui"),
              tags$hr(),
              tags$h5("Cell filters"),
              tags$p(tags$small("Both filters can be active simultaneously. Click Apply to execute."),
                     style="color:grey;font-size:11px;"),

              # Filter 1: min proteins
              checkboxInput("q_minprot_enable","Remove cells with fewer than N features",FALSE),
              conditionalPanel("input.q_minprot_enable",
                uiOutput("q_minprot_ui")
              ),

              # Filter 2: abundance outliers
              checkboxInput("q_outlier_enable","Remove cells outside ±N SD (total intensity)",FALSE),
              conditionalPanel("input.q_outlier_enable",
                sliderInput("q_outlier_sd","SD cutoff:",min=1,max=4,value=2,step=0.5),
                uiOutput("q_outlier_cond_ui")
              ),

              tags$hr(style="margin:10px 0;"),
              tags$p(tags$small("After cells are removed, features with no remaining values are ",
                "always dropped. Optionally also require a per-condition detection threshold ",
                "(Seurat min.cells analogue)."),
                style="color:grey;font-size:11px;"),
              checkboxInput("q_prot_cond_enable",
                "Re-evaluate features per condition", FALSE),
              conditionalPanel("input.q_prot_cond_enable",
                uiOutput("q_prot_cond_col_ui"),
                numericInput("q_prot_min_cells","Min cells detecting (per group):",
                             value=1, min=1, step=1),
                selectInput("q_prot_cond_mode","Retain feature when threshold is met in:",
                  choices=c("every group (present in all conditions)"="all",
                            "any one group (present in ≥1 condition)"="any"),
                  selected="all"),
                tags$p(tags$small(tags$b("every group"), " requires the threshold in all ",
                  "conditions; ", tags$b("any one group"), " keeps a feature detected in ",
                  "at least one condition even if absent from the others (retains ",
                  "condition-specific features)."),
                  style="color:grey;font-size:11px;")
              ),

              tags$br(),
              actionButton("q_apply_filter","▶  Apply cell filters",class="btn-warning",style="width:100%;"),
              tags$br(),tags$br(),
              uiOutput("q_filter_status")
            )),
            column(9,
              tabsetPanel(
                tabPanel("Boxplot per cell",
                  tags$p(tags$small(
                    "Each box = one cell ordered by ID. Colored by group. Matches the script's prt.abundance boxplot."),
                    style="color:grey;margin-top:6px;"),
                  selectInput("q_box_metric","Metric:",
                              choices=c("log2(Abundance)"="log2_abund",
                                        "Total intensity"="total",
                                        "Median intensity"="median",
                                        "Mean intensity"="mean",
                                        "N features quantified"="n_prot"),
                              selected="log2_abund"),
                  withSpinner(plotOutput("q_cell_boxplot",height="380px"))),
                tabPanel("Total intensity distribution",
                  tags$p(tags$small("Frequency histogram of log2(total intensity) per cell. Red lines = SD cutoff if enabled."),
                         style="color:grey;margin-top:6px;"),
                  withSpinner(plotOutput("q_total_hist",height="360px"))),
                tabPanel("Bar chart (total intensity)",
                  withSpinner(plotOutput("q_total_bar",height="360px"))),
                tabPanel("Summary table",
                  DTOutput("q_abundance_table"))
              )
            )
          )
        ),

        # ── Q4: Protein & Intensity QC ──────────────────────────────────────
        tabPanel("④ Statistical Comparisons",
          fluidRow(
            column(3, div(class="s-card",style="margin-top:12px;",
              tags$h5("Group comparison"),
              tags$p(tags$small(
                "Kruskal-Wallis + Dunn post-hoc within each facet group. ",
                "Use nesting to compare e.g. control vs treated within each SPD condition."),
                style="color:grey;font-size:11px;"),
              tags$hr(),
              tags$b("Metric"),
              selectInput("q_stat_metric","Compare by:",
                          choices=c("N features quantified"="n_prot",
                                    "Total intensity"="total",
                                    "Median intensity"="median",
                                    "Mean intensity"="mean"),
                          selected="n_prot"),
              checkboxInput("q_stat_log2","Apply log2 transformation to abundance metric",FALSE),
              tags$hr(),
              tags$b("Grouping"),
              uiOutput("q_stat_groupby_ui"),
              tags$hr(),
              tags$b("Nesting (optional)"),
              tags$p(tags$small(
                "Nest the comparison within an outer variable. ",
                "E.g. outer = SPD condition (80 SPD, 60 SPD), inner = treatment group. ",
                "KW + Dunn run separately within each outer level."),
                style="color:grey;font-size:11px;"),
              checkboxInput("q_stat_nest_enable","Enable nested comparison",FALSE),
              conditionalPanel("input.q_stat_nest_enable",
                uiOutput("q_stat_nest_ui")
              ),
              tags$hr(),
              selectInput("q_stat_padj","P-value adjustment:",
                          choices=c("Bonferroni"="bonferroni","BH (FDR)"="BH","Holm"="holm","None"="none"),
                          selected="bonferroni"),
              actionButton("q_run_stat","▶  Run comparison",class="btn-primary",style="width:100%;"),
              tags$br(),tags$br(),
              uiOutput("q_kw_result_ui")
            )),
            column(9,
              tabsetPanel(
                tabPanel("Boxplot by group",
                  tags$p(tags$small(
                    "Boxplot with jitter. n= counts shown. Significance brackets from Dunn test. ",
                    "When nested, each outer level becomes a facet panel."),
                    style="color:grey;margin-top:6px;"),
                  withSpinner(plotOutput("q_stat_boxplot",height="520px"))),
                tabPanel("Dunn test table",
                  DTOutput("q_dunn_table")),
                tabPanel("Cell count by group",
                  withSpinner(plotOutput("q_cell_count_bar",height="380px")))
              )
            )
          )
        ),

        # ── Q5: Sparsity Reduction ──────────────────────────────────────────
        tabPanel("⑤ Sparsity Reduction",
          fluidRow(
            column(3, div(class="s-card",style="margin-top:12px;",
              tags$h5("Sparsity filter"),
              tags$p(tags$small(
                "Removes features quantified in fewer than X% of cells. ",
                "Matches: prt.int[rowSums(!is.na(prt.int)) >= min_non_na, ]"),
                style="color:grey;font-size:11px;"),
              sliderInput("q_sparsity_pct",
                          "Keep features detected in AT LEAST this % of cells:",
                          min=10,max=100,value=50,step=5),
              tags$p(tags$small(
                "A setting of 20 keeps a feature seen in 20% of cells or more, i.e. missing ",
                "in up to 80% \u2014 it is a floor on detection, not a ceiling on missingness. ",
                "Raising it keeps fewer, better-measured features."),
                style="color:#7f8c8d;font-size:11px;"),
              uiOutput("q_sparsity_cond_ui"),
              actionButton("q_apply_sparsity","▶  Apply sparsity filter",class="btn-warning",style="width:100%;"),
              tags$br(),tags$br(),
              uiOutput("q_sparsity_status")
            )),
            column(9,
              tabsetPanel(
                tabPanel("Before vs After",
                  withSpinner(plotOutput("q_sparsity_bar",height="360px"))),
                tabPanel("Detection rate distribution",
                  tags$p(tags$small(
                    "Detection rate is the share of cells in which a feature was quantified. ",
                    "Computed across all cells it describes the matrix as a whole; computed ",
                    "WITHIN a metadata variable each level gets its own denominator, so a ",
                    "feature seen in every cell of a small dataset reads as 100% there and as ",
                    "a low rate overall. The two answer different questions and the filter ",
                    "slider on the left always applies to the pooled rate."),
                    style="color:grey;margin-top:6px;"),
                  fluidRow(
                    column(5, uiOutput("q_detect_split_ui")),
                    column(4, radioButtons("q_detect_disp", "Draw as:",
                             choices=c("Overlaid density"   = "density",
                                       "Overlaid histogram" = "overlay",
                                       "Faceted histograms" = "facet",
                                       "Bars: above vs below threshold" = "bars"),
                             selected="density")),
                    column(3,
                      numericInput("q_detect_bins", "Histogram bins:",
                                   value=50, min=10, max=200, step=10),
                      sliderInput("q_detect_alpha", "Fill transparency:",
                                  min=0.05, max=1, value=0.45, step=0.05))
                  ),
                  checkboxInput("q_detect_drop0",
                    "Restrict each group to features detected in \u22651 of its own cells",
                    value=TRUE),
                  tags$p(tags$small(
                    "On (recommended): a group's distribution is computed from its own cell ",
                    "columns AND only the features it actually detected, so the zero spike is ",
                    "that group's own poorly-covered features rather than features belonging ",
                    "to the other groups. Off: every group is evaluated over all ",
                    "features, which makes the groups share a denominator but fills the low ",
                    "end with features the group never saw."),
                    style="color:#7f8c8d;font-size:11px;"),
                  uiOutput("q_detect_col_ui"),
                  uiOutput("q_detect_summary"),
                  withSpinner(plotOutput("q_detect_hist",height="420px"))),
                tabPanel("Venn diagram",
                  tags$p(tags$small(
                    "Two independent choices. The ", tags$b("universe"),
                    " decides which features are eligible at all; the ",
                    tags$b("set membership"), " threshold decides which of those count as ",
                    "present in each group of the split variable. Leaving the universe at ",
                    "'All features' reproduces the old behaviour. Requires ggVennDiagram."),
                    style="color:grey;margin-top:6px;"),
                  fluidRow(
                    column(5,
                      radioButtons("q_venn_universe", "Universe (which features are eligible):",
                        choices=c("All features"                                  = "all",
                                  "Detected in ≥X% of ALL cells combined"          = "pooled",
                                  "Detected in ≥X% of one chosen group (anchor)"   = "anchor"),
                        selected="all"),
                      conditionalPanel("input.q_venn_universe == 'pooled'",
                        numericInput("q_venn_pool_pct", "Pooled detection ≥ (%):",
                                     value=25, min=0, max=100, step=5)),
                      conditionalPanel("input.q_venn_universe == 'anchor'",
                        uiOutput("q_venn_anchor_ui"),
                        numericInput("q_venn_anchor_pct", "Anchor detection ≥ (%):",
                                     value=25, min=0, max=100, step=5))),
                    column(7,
                      uiOutput("q_venn_cond_ui"),
                      numericInput("q_venn_pct", "Set membership: detected in ≥ (%) of each group:",
                                   value=50, min=0, max=100, step=5),
                      tags$p(tags$small(
                        "Set 0 to mean 'detected in at least one cell of that group'. ",
                        "The anchor option answers questions of the form: take the features ",
                        "reaching 25% detection in dataset 1, then how do those overlap across ",
                        "conditions — anchor on dataset, split by condition."),
                        style="color:#7f8c8d;font-size:11px;"),
                      radioButtons("q_venn_view", "Draw as:",
                        choices=c("Venn diagram"                    = "venn",
                                  "Bar plot of regions"             = "bars"),
                        selected="venn", inline=TRUE),
                      conditionalPanel("input.q_venn_view == 'bars'",
                        fluidRow(
                          column(6, radioButtons("q_venn_bar_mode", "Bars:",
                            choices=c("One bar per region (broken out)" = "dodge",
                                      "Single stacked bar (composition)" = "stack"),
                            selected="dodge")),
                          column(6, radioButtons("q_venn_bar_denom", "Percentages of:",
                            choices=c("Union of the sets" = "union",
                                      "Universe"          = "universe"),
                            selected="union"))
                        )),
                      conditionalPanel("input.q_venn_view == 'venn'",
                      radioButtons("q_venn_label", "Region labels show:",
                        choices=c("Count only"                     = "count",
                                  "Count + % of the union"         = "both",
                                  "% of the union only"            = "percent",
                                  "No labels"                      = "none"),
                        selected="count", inline=TRUE)),
                      actionButton("q_run_venn","▶  Draw Venn",class="btn-info",style="width:100%;"))
                  ),
                  uiOutput("q_venn_summary"),
                  uiOutput("q_venn_bar_col_ui"),
                  withSpinner(plotOutput("q_venn_plot",height="420px")),
                  tags$hr(),
                  tags$h5("Region breakdown"),
                  tags$p(tags$small(
                    "The percentages drawn inside the circles are shares of the UNION of the ",
                    "sets, which is what ggVennDiagram computes. The table gives every region ",
                    "against both denominators, because \"39% of the overlap\" means something ",
                    "different depending on whether it is measured against the union or ",
                    "against the universe you defined."),
                    style="color:grey;"),
                  DTOutput("q_venn_region_tbl"),
                  tags$br(),
                  uiOutput("q_venn_dl_ui")),
                tabPanel("Features per cell (post-filter)",
                  withSpinner(plotOutput("q_postfilter_boxplot",height="400px")))
              )
            )
          )
        ),

        # ── Q6: Export ──────────────────────────────────────────────────────
        tabPanel("⑥ Export",
          fluidRow(
            column(4, div(class="s-card",style="margin-top:12px;",
              tags$h5("📊 Export for SCP-Viz 1.1"),
              tags$p(tags$small(
                "Converts prt.int to the wide CSV format expected by the SCP-Viz 1.1 tab. ",
                "Features are rows; each cell column is prefixed with a keyword so ",
                "'Text used for quan columns' can find them."),
                style="color:grey;"),
              textInput("q_scpviz_keyword","Column keyword prefix:","Intensity"),
              tags$p(tags$small(
                "Set this to match the 'Text used for quan columns' field in SCP-Viz 1.1 ",
                "(e.g. 'Intensity', 'Abundance', 'PG.Quantity')."),
                style="color:grey;font-size:11px;"),
              selectInput("q_scpviz_prot_col","Feature ID column name (written as the CSV header):",
                          choices=c("Protein","protein","Accession","Gene","Feature","feature"),
                          selected="Protein"),
              checkboxInput("q_scpviz_use_sparse","Use sparsity-filtered matrix (if applied)",TRUE),
              downloadButton("q_dl_scpviz","⬇ Export for SCP-Viz 1.1 (.csv)",
                             class="btn-warning",style="width:100%;")
            )),
            column(4, div(class="s-card",style="margin-top:12px;",
              tags$h5("📄 Download plots as PDF"),
              tags$p(tags$small("Re-renders the selected plot at the chosen size."),style="color:grey;"),
              selectInput("q_pdf_plot","Plot:",
                # Nested list -> optgroup headers. Do NOT flatten these back
                # into a single vector: separator entries become selectable
                # values and the first one silently becomes the default.
                choices=list(
                  "Cell QC" = c(
                    "Boxplot per cell"                  = "q_cell_boxplot",
                    "Total intensity histogram"         = "q_total_hist",
                    "Bar chart (total intensity)"       = "q_total_bar"),
                  "Statistical Comparisons" = c(
                    "Statistical boxplot"               = "q_stat_boxplot",
                    "Cell count by group"               = "q_cell_count_bar"),
                  "Sparsity" = c(
                    "Sparsity bar (features per cell)"  = "q_sparsity_bar",
                    "Detection rate histogram"          = "q_detect_hist",
                    "Venn diagram"                      = "q_venn_plot",
                    "Features per cell (post-filter)"   = "q_postfilter_boxplot")
                ),
                selected = "q_cell_boxplot"
              ),
              fluidRow(
                column(6, numericInput("q_pdf_w","Width (in):", value=8, min=2,max=30,step=0.5)),
                column(6, numericInput("q_pdf_h","Height (in):",value=6, min=2,max=30,step=0.5))
              ),
              numericInput("q_pdf_fs","Base font size (pt):",value=13,min=8,max=24,step=1),
              downloadButton("q_dl_pdf","⬇ Download PDF",class="btn-success",style="width:100%;")
            )),
            column(4, div(class="s-card",style="margin-top:12px;",
              tags$h5("Export filtered data"),
              tags$p(tags$small(
                "Exports the current (QC-filtered + sparsity-reduced) prt.int and meta.samples. ",
                "These can be loaded directly into the Seurat Analysis tab."),
                style="color:grey;"),
              downloadButton("q_dl_prt_filtered","⬇ prt.int (filtered) .csv",class="btn-primary",style="width:100%;margin-bottom:6px;"),
              downloadButton("q_dl_meta_filtered","⬇ meta.samples (filtered) .csv",class="btn-primary",style="width:100%;margin-bottom:6px;"),
              downloadButton("q_dl_map_filtered","⬇ prt.map (aligned) .csv",class="btn-primary",style="width:100%;margin-bottom:6px;"),
              downloadButton("q_dl_rdata","⬇ Save as .RData",class="btn-success",style="width:100%;")
            )),
            column(3, div(class="s-card",style="margin-top:12px;",
              tags$h5("Activity log"),
              verbatimTextOutput("q_log")
            ))
          )
        )
      ) # end q_tabs
    ) # end fluidPage
  ), # end SCP-QC tab

  # ══════════════════════════════════════════════════════════════════════════
  #  TAB 3 — SEURAT ANALYSIS SUITE  (all IDs prefixed "s_")
  # ══════════════════════════════════════════════════════════════════════════
  tabPanel("Seurat Analysis",
    fluidPage(
      fluidRow(column(12,
        div(class = "s-card", style = "margin-top:10px;",
          tags$h4("Seurat Analysis Suite", style = "color:#2c3e50; margin:0 0 4px 0;"),
          tags$p(tags$small(
            "Upload prt.int + meta.samples + prt.map as an .RData file. ",
            "Work through the steps left-to-right: Load → QC → Select covariates and colors → ",
            "Explained Variation (on raw data) → Create Seurat object → Normalize and evaluate PCA",
            "Embeddings → Clustering → Differential abundance (many feature plots)",
            "Alternative path options with Integration of datasets, ",
            "Pathway analysis, Enrichment annotation of cell types, trajectory analyses, ",
            "Export figures and files → Save analysis session and reupload later."),
            style = "color:grey; margin:0;")
        )
      )),

      # ── Global identity selector — propagates to all Seurat plots ───────────
      fluidRow(column(12,
        div(class="s-card", style="padding:10px 16px; margin-bottom:6px; background:#eaf4fb; border-color:#aed6f1;",
          fluidRow(
            column(4,
              tags$b("Global plot identity (Idents):"),
              tags$p(tags$small(
                "Sets Seurat::Idents() for all group-by plots (Violin, DimPlot, FindMarkers, DotPlot). ",
                "Build the Seurat object first, then choose your identity here."),
                style="color:#5d6d7e; margin:0; font-size:11px;")
            ),
            column(4, uiOutput("s_global_ident_ui")),
            column(4, uiOutput("s_global_ident_status"))
          )
        )
      )),

      tabsetPanel(id = "s_tabs",

        # ── S1: Load Data ───────────────────────────────────────────────────
        tabPanel("① Load Data",
          fluidRow(
            column(5, div(class="s-card s-stripe", style="margin-top:12px;",
              tags$h5("Data source"),
              radioButtons("s_input_type", NULL,
                           choices=c("RData / RDS file"="rdata",
                                     "Three CSV files"="excel"),
                           selected="rdata", inline=TRUE),

              # ── RData panel ──────────────────────────────────────────────
              conditionalPanel("input.s_input_type == 'rdata'",
                tags$p(tags$small(
                  "Must contain: ", tags$b("prt.int"), " (features × cells matrix), ",
                  tags$b("meta.samples"), " (data.frame, rownames = cell IDs), ",
                  tags$b("prt.map"), " (optional, maps IDs to gene symbols)."),
                  style="color:grey;"),
                fileInput("s_rdata_upload", "Upload .RData / .rds",
                          accept=c(".RData",".Rdata",".rds")),
                if (length(.RDATA_EXAMPLES))
                  tagList(
                    selectInput("s_example_set", "Example dataset:",
                                choices = c("— choose —" = "", .RDATA_EXAMPLES),
                                selected = ""),
                    actionButton("s_load_example","📂 Load Example Data",
                                 class="btn-info",style="width:100%;margin-bottom:4px;"),
                    tags$p(tags$small(paste0(
                      length(.RDATA_EXAMPLES), " set(s) found in RData_example_sets/")),
                      style="color:grey;font-size:11px;"))
                else
                  tags$p(tags$small(
                    "No example sets found. Put .RData files in an RData_example_sets/ ",
                    "folder next to this script."),
                    style="color:#B9770E;font-size:11px;"),
                tags$hr(),
                actionButton("s_parse_rdata","▶  Load Data",
                             class="btn-primary",style="width:100%;")
              ),

              # ── CSV panel ─────────────────────────────────────────────────
              conditionalPanel("input.s_input_type == 'excel'",
                tags$p(tags$small(
                  "Upload three separate CSV files. ",
                  tags$b("prt.int"), ": proteins × cells (first column = feature IDs, remaining columns = cells). ",
                  tags$b("meta.samples"), ": metadata (first column = cell IDs). ",
                  tags$b("prt.map"), ": optional feature map (first column = accession IDs)."),
                  style="color:grey;"),
                fileInput("s_csv_prt",  "① prt.int CSV (features × cells):",
                          accept=c(".csv",".txt",".tsv")),
                fileInput("s_csv_meta", "② meta.samples CSV (cells × metadata):",
                          accept=c(".csv",".txt",".tsv")),
                fileInput("s_csv_map",  "③ prt.map CSV (optional feature map):",
                          accept=c(".csv",".txt",".tsv")),
                tags$hr(),
                actionButton("s_parse_csv","▶  Load CSVs",
                             class="btn-primary",style="width:100%;")
              ),

              tags$hr(),

              # ── Feature ID selector ───────────────────────────────────────
              tags$h5("Feature identifier"),
              uiOutput("s_feature_col_ui"),
              tags$p(tags$small(
                "Select which column in prt.map to use as feature IDs in Seurat. ",
                tags$b("ProteinGroups"), " = accession IDs (default), ",
                tags$b("Genes"), " = gene symbols, ",
                tags$b("Peptides"), " = peptide sequences. ",
                "If prt.map is absent, row names of prt.int are used as-is."),
                style="color:grey;font-size:11px;"),
              uiOutput("s_assay_name_ui")
            )),

            column(7, div(class="s-card", style="margin-top:12px;",
              tags$h5("Loaded data summary"),
              uiOutput("s_load_summary"),
              tags$br(),
              uiOutput("s_feature_preview_ui")
            ))
          )
        ),

        # ── S2: Quality Control ─────────────────────────────────────────────
        tabPanel("② Quality Control",
          div(class = "s-card", style = "margin-top:12px;",
            tags$h5("Four optional filter steps — all downstream tabs use the filtered data"),
            fluidRow(
              column(4, div(class = "s-stripe",
                checkboxInput("s_qc_cells","① Remove cells with < N proteins",FALSE),
                conditionalPanel("input.s_qc_cells",
                  numericInput("s_qc_min_prot","Min proteins per cell:",value=500,min=1))
              )),
              column(4, div(class = "s-stripe",
                checkboxInput("s_qc_outlier","② Remove abundance outliers (±SD)",FALSE),
                conditionalPanel("input.s_qc_outlier",
                  sliderInput("s_qc_sd","SD cutoff:",min=1,max=4,value=2,step=0.5),
                  checkboxInput("s_qc_outlier_per_cond",
                                "Apply cutoff per condition group",
                                value=FALSE),
                  conditionalPanel("input.s_qc_outlier_per_cond",
                    uiOutput("s_qc_cond_col_ui"),
                    tags$p(tags$small(
                      "Outliers are defined relative to the mean ± SD within each ",
                      "condition level, not across all cells. This avoids removing ",
                      "cells that are only outliers because of biological or known experimental differences."),
                      style="color:grey;font-size:11px;")
                  )
                )
              )),
              column(4, div(class = "s-stripe",
                checkboxInput("s_qc_sparse","③ Sparsity reduction",FALSE),
                conditionalPanel("input.s_qc_sparse",
                  sliderInput("s_qc_pct","Min % cells detecting protein:",min=10,max=100,value=60,step=5))
              ))
            ),
            fluidRow(
              column(12, div(class = "s-stripe",
                checkboxInput("s_qc_prot_cond",
                  "④ Re-evaluate proteins per condition", FALSE),
                conditionalPanel("input.s_qc_prot_cond",
                  fluidRow(
                    column(4, uiOutput("s_qc_prot_cond_col_ui")),
                    column(4, numericInput("s_qc_prot_min_cells",
                      "Min cells detecting (per group):", value=1, min=1, step=1)),
                    column(4, selectInput("s_qc_prot_cond_mode","Retain protein when threshold is met in:",
                      choices=c("every group (present in all conditions)"="all",
                                "any one group (present in ≥1 condition)"="any"),
                      selected="all"))
                  ),
                  tags$p(tags$small(
                    "Optional, conservative filter. After cells are filtered, each protein's ",
                    "detection is counted within each condition group. Set the per-group ",
                    "threshold, then choose the ",
                    "rule: ", tags$b("every group"), " keeps a protein only if it clears the ",
                    "threshold in all conditions (guarantees data in both groups for clean ",
                    "contrasts); ", tags$b("any one group"), " keeps a protein if it clears the ",
                    "threshold in at least one condition (retains condition-specific proteins ",
                    "even if absent elsewhere). Note this is not required for Seurat's default ",
                    "marker tests, which already skip untestable features rather than erroring; ",
                    "it mainly avoids one-group NaN fold changes in mean-based or model-based ",
                    "tests (limma/proDA) and produces cleaner inputs."),
                    style="color:grey;font-size:11px;")
                )
              ))
            )
          ),
          div(class = "s-card",
            uiOutput("s_qc_boxes"),
            tags$br(),
            tabsetPanel(
              tabPanel("Features per cell",      plotlyOutput("s_qc_prot_hist",  height="250px")),
              tabPanel("Features per cell (bar)",plotlyOutput("s_qc_prot_bar",   height="250px")),
              tabPanel("Abundance distribution", plotlyOutput("s_qc_abund_hist", height="250px")),
              tabPanel("Detection rate",         plotlyOutput("s_qc_detect_hist",height="250px"))
            )
          ),

          # ── Optional: Reference protein normalization ───────────────────────
          div(class="s-card",style="margin-top:8px;border-color:#F39C12;",
            tags$h5("④ Reference feature normalization",
                    tags$span("(optional)", style="color:#F39C12;font-size:12px;font-weight:normal;margin-left:8px;")),
            tags$p(tags$small(
              "Applied ", tags$b("after"), " the filters above to the filtered matrix. ",
              "Divides each cell's intensities by a selected reference feature ",
              "(e.g. a housekeeping protein like Histone H4) to correct for loading differences or inferred cell size. ",
              "Only enable if your data is not already normalized."),
              style="color:grey;"),
            checkboxInput("s_refnorm_enable","Enable reference feature normalization",FALSE),
            conditionalPanel("input.s_refnorm_enable",
              fluidRow(
                column(4,
                  uiOutput("s_refnorm_prot_ui"),
                  selectInput("s_refnorm_scale","Rescale after normalization:",
                              choices=c("Median (preserves intensity scale)"="median",
                                        "×10000 (TIC-style)"="10000",
                                        "None (raw ratio)"="none"),
                              selected="median"),
                  actionButton("s_apply_refnorm","▶  Apply reference normalization",
                               class="btn-warning",style="width:100%;"),
                  tags$br(),tags$br(),
                  actionButton("s_reset_refnorm","↺  Reset to filtered prt.int",
                               class="btn-default",style="width:100%;"),
                  tags$br(),tags$br(),
                  uiOutput("s_refnorm_status")
                ),
                column(8,
                  tabsetPanel(
                    tabPanel("Detection rate",
                      tags$p(tags$small("% cells detecting the reference feature. Aim for >80%."),
                             style="color:grey;margin-top:4px;"),
                      withSpinner(plotlyOutput("s_refnorm_detect", height="280px"))),
                    tabPanel("Intensity distribution",
                      tags$p(tags$small("Reference feature intensity in detected cells."),
                             style="color:grey;margin-top:4px;"),
                      withSpinner(plotlyOutput("s_refnorm_dist",   height="280px"))),
                    tabPanel("Before vs After",
                      tags$p(tags$small("log2(total intensity) per cell before and after normalization."),
                             style="color:grey;margin-top:4px;"),
                      withSpinner(plotOutput("s_refnorm_compare",  height="320px")))
                  )
                )
              )
            )
          )
        ),

        # ── S3: Covariate Manager ───────────────────────────────────────────
        tabPanel("③ Covariates",
          div(class="s-card", style="margin-top:12px;",
            tags$h5("meta.samples — first 5 rows"),
            tags$p(tags$small("Verify your metadata loaded correctly before classifying."), style="color:grey;"),
            DTOutput("s_cov_meta_preview")
          ),
          fluidRow(
            column(6, div(class = "s-card",
              tags$h5("Classify metadata columns"),
              tags$p(tags$small(
                "Categorical = biological grouping (sex, cell type, condition). ",
                "Technical = batch / run, plate, effects to be optionally regressed. ",
                "Ignored = not used."),
                style = "color:grey;"),
              uiOutput("s_cov_ui")
            )),
            column(6,
              div(class = "s-card",
                tags$h5("Active assignments"),
                tableOutput("s_cov_tbl")
              ),
              div(class = "s-card",
                tags$h5("Default cluster palette"),
                tags$p(tags$small(
                  "Applies wherever clusters are coloured and no explicit per-level palette ",
                  "has been set below \u2014 UMAP, violins, silhouette, cluster \u00d7 metadata, and ",
                  "every PDF export. Okabe\u2013Ito is the default because ggplot2's standard ",
                  "hue scale is not colourblind-safe and re-colours every cluster whenever the ",
                  "cluster count changes."),
                  style="color:grey;"),
                selectInput("s_cluster_pal_family", NULL,
                  choices=list(
                    "Qualitative \u2014 best for unordered clusters" = c(
                      "Okabe\u2013Ito \u2014 colourblind-safe (up to 8)" = "okabe",
                      "Tol muted \u2014 colourblind-safe (up to 9)"      = "tol",
                      "Polychrome \u2014 max separation (up to 36)"      = "polychrome"),
                    "Viridis family \u2014 perceptually uniform, any n" = c(
                      "Viridis \u2014 colourblind-safe"                 = "viridis",
                      "Cividis \u2014 optimised for deuteranopia"       = "cividis",
                      "Mako \u2014 colourblind-safe"                    = "mako",
                      "Plasma \u2014 colourblind-safe"                  = "plasma",
                      "Turbo \u2014 high contrast, NOT colourblind-safe" = "turbo"),
                    "Other" = c(
                      "ggplot2 hue \u2014 Seurat/ggplot default (not CVD-safe)" = "hue")),
                  selected="okabe"),
                uiOutput("s_cluster_pal_preview"),
                tags$p(tags$small(CVD_OVERFLOW_NOTE), style="color:#7f8c8d;font-size:11px;"),
                tags$p(tags$small(VIRIDIS_CAT_NOTE), style="color:#7f8c8d;font-size:11px;")
              ),
              div(class = "s-card",
                tags$h5("Color palette per covariate"),
                tags$p(tags$small(
                  "Assign custom hex colors to the levels of any categorical covariate. ",
                  "These colors are used in all DimPlot and VlnPlot calls. ",
                  "Select a covariate, then assign a color to each level."),
                  style="color:grey;"),
                uiOutput("s_palette_cov_ui"),
                uiOutput("s_palette_levels_ui"),
                uiOutput("s_palette_order_ui"),
                actionButton("s_palette_apply","Apply colors",
                             class="btn-info", style="width:100%;margin-top:6px;"),
                actionButton("s_palette_reset","Reset to defaults",
                             class="btn-default", style="width:100%;margin-top:4px;"),
                tags$br(),
                uiOutput("s_palette_preview_ui")
              )
            )
          )
        ),

        # ── S4: Explained Variation (raw) ───────────────────────────────────
        tabPanel("④ Explained Variation",
          div(class = "s-card", style = "margin-top:12px;",
            tags$h5("Explained Variation on raw | QC filtered | Transformed log₂ data"),
            tags$p(tags$small(
              "Global variance is first assessed after dimensionality reduction and then on a per feature basis. ",
              "PCA is run on log₂(raw counts + 1).Each selected covariate is correlated with each individual PC score ",
              "using a linear model (lm) and represented as a heatmap. ",
              "The bar chart shows each covariate's PCA variance-weighted total r² across the ",
              "assessed PCs, plus a residual bar (variance not explained by any tested ",
              "covariate). ",
              "The ", tags$b("'Per-feature variance'"), " tab below ",
              "adds the BatchQC-inspired per-feature view alongside the PC-based one.",
              "Use this to identify which technical variables dominate the data ",
              "before running normalization."),
              style = "color:grey;")
          ),
          fluidRow(
            column(4, div(class = "s-card",
              tags$h5("Settings"),
              uiOutput("s_ev_cov_ui"),
              sliderInput("s_ev_npcs","Number of PCs to assess:",min=2,max=30,value=10),
              actionButton("s_run_ev","▶  Compute",
                           class="btn-primary",style="width:100%;")
            )),
            column(8,
              tabsetPanel(
                tabPanel("Heatmap (r² per PC)",  withSpinner(plotlyOutput("s_ev_heatmap",height="420px"))),
                tabPanel("Bar plot (total r², PCA variance-weighted)", withSpinner(plotlyOutput("s_ev_bar",height="420px"))),
                tabPanel("Per-feature variance (boxplot)",
                  tags$p(tags$small("'Individual Variable' distibution boxplots: ",
                    tags$b("Explained"), " is the r\u00b2 of ", tags$b("all selected covariates fit together"),
                    " in one joint model, per feature; ", tags$b("Unexplained"), " is its exact ",
                    "complement (residual) — the two always sum to 100% per feature since they come from ",
                    "the same model. The covariates in between show each variable's own r\u00b2 fit ",
                    "separately against every feature."),
                    style="color:grey;margin-bottom:6px;"),
                  withSpinner(plotlyOutput("s_ev_feature_box",height="420px"))),
                tabPanel("Per-feature table",
                  tags$div(style="margin:8px 0 10px 0;",
                    downloadButton("s_dl_ev_feature",
                                   "⬇ Download per-feature table (.csv)",
                                   class="btn-default")),
                  tags$p(tags$small(
                    "One row per feature, one column per covariate, plus the joint-model ",
                    "Explained / Unexplained pair. Values are r\u00b2 as a percentage; blank ",
                    "means the fit was not estimable for that feature."),
                    style="color:grey;font-size:11px;"),
                  DTOutput("s_ev_feature_tbl")),
                tabPanel("Per-PC table",         DTOutput("s_ev_tbl"))
              )
            )
          )
        ),

        # ── S5: Seurat Object ───────────────────────────────────────────────
        tabPanel("⑤ Seurat Object",
          fluidRow(
            column(4, div(class = "s-card", style = "margin-top:12px;",
              tags$h5("Build Seurat object"),
              tags$p(tags$b(
                "Value must match Seurat assay name: in Load Data tab"),
                style="color:grey;font-size:11px;margin-bottom:6px;"),
              textInput("s_assay",   "Assay name:",   value="Protein"),
              textInput("s_project", "Project name:", value="SCPViz"),
              textInput("s_mt_pat",  "Mitochondrial prefix:", value="Mt-"),
              tags$hr(),
              tags$b("Matrix input"),
              tags$p(tags$small(
                "The Seurat object is created from the QC filtered matrix ",
                "with reference normalization applied if the option in the QC tab is enabled."),
                style="color:grey;font-size:11px;margin-bottom:6px;"),
              tags$hr(),
              actionButton("s_build_seu","▶  Build",
                           class="btn-primary",style="width:100%;"),
              tags$br(),tags$br(),
              uiOutput("s_seu_status"),
              tags$hr(),
              tags$b("Plot identity controls"),
              uiOutput("s_vln_grp_ui"),
              uiOutput("s_feat_x_ui"),
              uiOutput("s_feat_y_ui"),
              uiOutput("s_feat_grp_ui")
            )),
            column(8,
              tabsetPanel(
                tabPanel("Violin QC",
                  plotOutput("s_vln_plot",height="360px")),
                tabPanel("Feature Scatter",
                  plotOutput("s_feat_scatter",height="360px")),
                tabPanel("Metadata",
                  DTOutput("s_meta_tbl")),
                tabPanel("Distribution Diagnostics",
                  div(style="margin-top:8px;",
                    tags$p(tags$small(
                      "Assesses how well the raw count data fits a negative-binomial (NB) distribution ",
                      "relative to Poisson and log-normal models. Run before SCTransform to decide ",
                      "whether SCTransform is appropriate for your data."),
                      style="color:grey;"),
                    fluidRow(
                      column(4,
                        selectInput("s_diag_source","Data source:",
                          choices=c("Raw non-integer, NAs present"="raw_na",
                                    "Raw non-integer, NAs→0"="raw_zero",
                                    "Integer counts with 0s (SCT input)"="int_zero"),
                          selected="raw_na"),
                        tags$p(tags$small(
                          "Three views of the RAW uploaded data, to see how it transforms into ",
                          "the count pipeline: the original non-integer intensities with NAs, the ",
                          "same with NAs replaced by 0, and the ceiling'd integer matrix with 0s ",
                          "that actually feeds SCTransform. Compare how each changes the ",
                          "NB-fit distribution."),
                          style="color:grey;font-size:11px;margin-bottom:6px;"),
                        sliderInput("s_diag_sample_n","Proteins to sample for QQ plots:",
                                    min=4,max=40,value=16,step=4),
                        actionButton("s_run_diag","▶  Run diagnostics",
                                     class="btn-info",style="width:100%;")
                      ),
                      column(8, uiOutput("s_diag_summary_ui"))
                    ),
                    uiOutput("s_diag_source_note"),
                    tags$br(),
                    tabsetPanel(
                      tabPanel("Mean–Variance",
                        tags$p(tags$small(
                          "Log(variance) vs log(mean) per feature. ",
                          "Poisson distribution: slope = 1 (blue). NB or Lognorm: slope ≈ 2 (red)."),
                          style="color:grey;margin-top:6px;"),
                        withSpinner(plotlyOutput("s_diag_mv",   height="400px"))),
                      tabPanel("CV² vs Mean",
                        tags$p(tags$small(
                          "For NB: CV² decreases with mean (1/μ + 1/r). ",
                          "For log-normal: CV² is roughly constant. ",
                          "Useful for distinguishing the two models."),
                          style="color:grey;margin-top:6px;"),
                        withSpinner(plotlyOutput("s_diag_cv",   height="400px"))),
                      tabPanel("Dispersion",
                        tags$p(tags$small(
                          "Dispersion \u03b1 = 1/r per feature against its mean. Lower = more ",
                          "Poisson-like; higher = more overdispersed. ",
                          tags$b("Two readings, both useful. "),
                          tags$b("Cloud width"), " (grey dashed quartile bands; IQR in the title) ",
                          "is how heterogeneous your features are \u2014 and how hard SCTransform's ",
                          "dispersion regularization must work, since it shrinks every per-feature ",
                          "estimate toward a fitted trend. A wide cloud means the \u03b8 values SCT ",
                          "actually uses are mostly prior rather than data. ",
                          tags$b("Trend vs reference"), " (dark LOESS against the purple dashed curve) ",
                          "tests the NB assumption. The purple curve is \u03b1 = median(CV\u00b2) \u2212 1/\u03bc, ",
                          "the rise you would see from constant CV alone \u2014 so judge the LOESS ",
                          "against it, not against flat. On the curve = constant multiplicative error; ",
                          "flat where the curve rises = genuine NB; above it at low mean = additive ",
                          "noise floor (favors VSN); above it at high mean = super-quadratic variance ",
                          "no transform in this family removes. ",
                          "Colored by whether Poisson is rejected (overdispersion test)."),
                          style="color:grey;margin-top:6px;"),
                        withSpinner(plotlyOutput("s_diag_disp", height="400px"))),
                      tabPanel("Zero fraction",
                        tags$p(tags$small(
                          "Observed zero fraction per protein vs NB-predicted zero fraction. ",
                          "Points above the diagonal have more zeros than NB predicts ",
                          "(possible zero-inflation — less relevant after sparsity reduction)."),
                          style="color:grey;margin-top:6px;"),
                        withSpinner(plotlyOutput("s_diag_zero", height="400px"))),
                      tabPanel("QQ sample",
                        tags$p(tags$small(
                          "Observed vs theoretical NB quantiles for a random sample of proteins. ",
                          "Points on the diagonal = good NB fit. Systematic departure = poor fit."),
                          style="color:grey;margin-top:6px;"),
                        withSpinner(plotOutput("s_diag_qq",    height="500px")))
                    )
                  )
                )
              )
            )
          )
        ),

        # ── S6: Normalization + PCA ─────────────────────────────────────────
        tabPanel("⑥ Normalization + PCA",
          fluidRow(
            column(12,
              div(style=paste0("margin-top:12px;padding:12px 14px;border-left:5px solid #E67E22;",
                               "background:#FDF6E3;border-radius:4px;"),
                tags$p(tags$b("Comparing normalization methods? Rebuild the object first."),
                       style="margin:0 0 4px 0;color:#8A6D3B;font-size:14px;"),
                tags$p(tags$small(
                  "Each method writes into the object rather than replacing it. SCTransform ",
                  "creates a separate ", tags$code("SCT"), " assay that is never removed, and ",
                  "downstream tabs prefer ", tags$code("SCT"), " whenever it exists \u2014 so running ",
                  "SCTransform and then VSN, scp-median or LogNormalize leaves the plots and ",
