        # ── S9: Marker Discovery ────────────────────────────────────────────
        tabPanel("⑨ Markers",
          fluidRow(
            column(4,
              div(class="s-card",style="margin-top:12px;",
                tags$h5("FindMarkers / FindAllMarkers"),
                radioButtons("s_mk_mode","Mode:",
                             choices=c("All clusters"="all","Two groups"="two"),inline=TRUE),
                uiOutput("s_mk_grpby_ui"),
                conditionalPanel("input.s_mk_mode=='two'",
                  uiOutput("s_mk_id1_ui"), uiOutput("s_mk_id2_ui")),
                selectInput("s_mk_test","Test:",
                            choices=c("Wilcoxon"="wilcox","ROC"="roc",
                                      "t-test"="t",
                                      "LR (logistic, covariate-capable)"="LR",
                                      "MAST (hurdle, covariate-capable)"="MAST",
                                      "Negative binomial (counts only)"="negbinom",
                                      "Poisson (counts only)"="poisson")),
                tags$p(tags$small(
                  "Only ", tags$b("LR"), ", ", tags$b("MAST"), ", negbinom and poisson accept ",
                  "covariates \u2014 Wilcoxon, ROC and t-test have no design matrix, so there ",
                  "is nowhere for \u201chold batch constant\u201d to live. negbinom and poisson ",
                  "assume raw counts and are inappropriate for intensities. ",
                  tags$b("LR"), " regresses group membership on expression plus the ",
                  "covariates and compares to a null without expression; ", tags$b("MAST"),
                  " fits a hurdle model separating detection from magnitude, and its own ",
                  "convention is to include the cellular detection rate (i.e. nFeature) as ",
                  "a covariate. Note that with LR the reported fold change is computed ",
                  "separately from the model, so the effect size is unadjusted even though ",
                  "the p-value is."),
                  style="color:#7f8c8d;font-size:11px;margin:2px 0 6px 0;"),
                # ── VSN / scp-median NA-aware marker testing ────────────────
                conditionalPanel("input.s_norm_method == 'vsn' || input.s_norm_method == 'scpmed' || input.s_norm_method == 'log2'",
                  div(style="background:#f4f8fc;border:1px solid #cfe0f0;border-radius:3px;padding:6px;margin:6px 0;",
                    tags$p(tags$b("Intensity-native marker test"),
                           style="font-size:12px;margin:0 0 4px 0;color:#1a4b7a;"),
                    tags$p(tags$small(
                      "For VSN/scp-median the app uses an NA-aware test on the un-regressed ",
                      "normalized matrix instead of Seurat's FindMarkers (which can mishandle ",
                      "NAs). This overrides the Test selector above."),
                      style="color:#5a6b7a;font-size:11px;margin:0 0 6px 0;"),
                    radioButtons("s_mk_namethod","Method:",
                      choices=c("proDA (models missingness)"="proda",
                                "limma (eBayes, missing-at-random)"="limma",
                                "Complete-case Wilcoxon"="ccwilcox",
                                "Seurat FindMarkers (NA→0)"="na_zero"),
                      selected="proda"),
                    conditionalPanel("input.s_mk_namethod == 'limma'",
                      tags$p(tags$small(
                        "limma fits ", tags$code("~ group + covariate"), " with empirical-Bayes ",
                        "moderation and supports covariates like proDA. It treats NAs as ",
                        tags$b("missing-at-random"), " (per-protein), NOT left-censored — so for ",
                        "detection-limit missingness proDA is more appropriate. Faster and widely ",
                        "used; good as a cross-check."),
                        style="color:#7f8c8d;font-size:11px;margin-top:4px;")),
                    conditionalPanel("input.s_mk_namethod == 'na_zero'",
                      tags$p(tags$small(
                        tags$b("Caution: "), "substitutes 0 for every not-detected value, then ",
                        "runs the standard Seurat test selected above (works in both Two-group ",
                        "and All-clusters mode). This treats 'not detected' as 'abundance zero', ",
                        "which biases fold-changes when detection rates differ between groups. ",
                        "Provided for comparison — proDA is the statistically correct choice."),
                        style="color:#9c5700;font-size:11px;margin-top:4px;")),
                    conditionalPanel("input.s_mk_namethod == 'proda'",
                      numericInput("s_mk_proda_nsub",
                        "proDA n_subsample (0 = all features):",
                        value=500, min=0, step=100),
                      checkboxInput("s_mk_proda_verbose",
                        "Print proDA progress to the R console", value=TRUE),
                      fluidRow(
                        column(6, numericInput("s_mk_proda_maxit", "max_iter:",
                                               value=20, min=3, max=200, step=1)),
                        column(6, numericInput("s_mk_proda_eps", "epsilon:",
                                               value=0.001, min=1e-6, max=0.1, step=1e-3))
                      ),
                      tags$p(tags$small(
                        "proDA has no parallel backend \u2014 it is single-threaded, so these are ",
                        "the only speed controls. ", tags$b("n_subsample"),
                        " caps the features used for the hyperparameter step, which dominates ",
                        "the run; every feature is still tested. ", tags$b("max_iter"),
                        " caps the EM loop and ", tags$b("epsilon"),
                        " is its tolerance \u2014 lowering max_iter to 8\u201310 or raising epsilon to ",
                        "0.01 cuts the time roughly in proportion, at the cost of less precise ",
                        "variance and dropout-curve estimates. Leave the moderation on: ",
                        "location moderation is what handles a protein unobserved in one ",
                        "condition entirely, which is common here, and variance moderation is ",
                        "where the power comes from. It runs once per cluster, so a 10-cluster ",
                        "one-vs-rest is ten full fits \u2014 slow rather than stuck; the progress ",
                        "bar names the cluster and the matrix size, and each fit's duration is ",
                        "written to the log. For a first pass, limma with the same design is far ",
                        "faster and still gives variance moderation, at the cost of proDA's ",
                        "explicit missingness model."),
                        style="color:#7f8c8d;font-size:11px;"),
                      tags$p(tags$small(
                        "proDA fits a per-feature model ", tags$b("and"), " estimates a dropout ",
                        "curve, so a run takes roughly an order of magnitude longer than limma ",
                        "\u2014 and it runs once per cluster, so a 10-cluster one-vs-rest is ten ",
                        "full fits. It is slow rather than stuck; the progress bar now names ",
                        "the cluster and the matrix size, and each fit's duration is written to ",
                        "the log. Setting n_subsample (e.g. 500) caps the features used for the ",
                        "hyperparameter step, which is the dominant cost; every feature is still ",
                        "tested. If you only need a first pass, limma with the same design is ",
                        "far faster and gives variance moderation, at the cost of proDA's ",
                        "explicit missingness model."),
                        style="color:#7f8c8d;font-size:11px;")),
                    conditionalPanel("input.s_mk_namethod == 'proda' || input.s_mk_namethod == 'limma'",
                      checkboxInput("s_mk_vf_only",
                        "Test variable features only (faster)", value=FALSE),
                      tags$p(tags$small(
                        "Restricts the test to the \u2465 variable-feature set. The single biggest ",
                        "speed lever, because runtime scales with the feature count \u2014 but it ",
                        "changes the multiple-testing universe, so a p-adjusted value is not ",
                        "comparable with a run over all features, and a real effect in an ",
                        "unselected feature is invisible rather than non-significant. Reasonable ",
                        "for exploration; state it if the numbers are reported."),
                        style="color:#7f8c8d;font-size:11px;"),
                      uiOutput("s_mk_proda_cov_ui"),
                      tags$p(tags$small(
                        "Nuisance covariates (e.g. lcbatch, total intensity) enter the model ",
                        "design as ", tags$code("~ group + covariate"), " — the statistically ",
                        "correct one-stage adjustment (proDA and limma both support this). The ",
                        "test reads the ", tags$b("un-regressed"), " normalized matrix, so a ",
                        "covariate you also regressed out pre-PCA is fine to include here — the ",
                        "two corrections act on different matrices and don't stack. Only rule: ",
                        "never select the grouping variable you're testing."),
                        style="color:#7f8c8d;font-size:11px;margin-top:4px;")),
                    conditionalPanel("input.s_mk_namethod == 'ccwilcox'",
                      tags$p(tags$small(
                        "Per-protein: drops NA cells, then Wilcoxon on observed cells only. ",
                        "Cannot adjust for covariates — use proDA if batch adjustment is needed."),
                        style="color:#7f8c8d;font-size:11px;margin-top:4px;"))
                  )
                ),
                conditionalPanel(
                  paste0("input.s_mk_test == 'MAST' || input.s_mk_test == 'LR' || ",
                         "input.s_mk_test == 'negbinom' || input.s_mk_test == 'poisson'"),
                  uiOutput("s_mk_latent_ui"),
                  tags$p(tags$small(
                    "Included as covariates in the test's own model, so the correction ",
                    "reaches the p-value rather than only the embedding. This is the ",
                    "counterpart to the \u2465 regression: \u2465 subtracts a covariate from the ",
                    "values that feed PCA and heatmaps, whereas this holds it constant ",
                    "inside the test while leaving the data untouched. Adjusting inside ",
                    "the test is the statistically preferable route \u2014 testing residuals ",
                    "from a prior regression understates uncertainty, because the test ",
                    "does not know degrees of freedom were already spent."),
                    style="color:#7f8c8d;font-size:11px;margin-top:4px;")
                ),
                    uiOutput("s_mk_interact_ui"),
                    conditionalPanel(
                      "input.s_norm_method == 'vsn' || input.s_norm_method == 'scpmed' || input.s_norm_method == 'log2'",
                      div(style=paste0("background:#eef4fb;border-left:4px solid #2980B9;",
                                       "border-radius:3px;padding:8px;margin-bottom:8px;"),
                        tags$p(tags$b("Covariate shape in the test design"),
                               style="margin:0 0 3px 0;font-size:12px;color:#1F4E79;"),
                        fluidRow(
                          column(6, numericInput("s_mk_spline_df",
                            "Spline df (blank = match \u2465):", value=NA, min=1, max=6, step=1)),
                          column(6, div(style="margin-top:26px;",
                            checkboxInput("s_mk_cov_linear",
                              "Force linear covariates", value=FALSE)))
                        ),
                        tags$p(tags$small(
                          "Continuous covariates selected below enter the proDA / limma design ",
                          "as a natural cubic spline basis, using the same df as the \u2465 ",
                          "embedding regression unless overridden here. This matters because a ",
                          "covariate is only adjusted for to the extent the model can describe ",
                          "it: a straight line leaves curvature in the residual, which inflates ",
                          "residual variance and can bias the group coefficient when depth is ",
                          "unbalanced across groups. The contrast of interest is unchanged \u2014 ",
                          "spline terms are nuisance columns and the tested coefficient is still ",
                          "the single group effect."),
                          style="margin:0;color:#1F4E79;font-size:11px;")
                      )),
                numericInput("s_mk_logfc", "Min log2FC:",  value=0.25,min=0,step=0.05),
                numericInput("s_mk_minpct","Min pct:",     value=0.1, min=0,max=1,step=0.05),
                checkboxInput("s_mk_posonly","Only positive markers",FALSE),
                # ── Build a combined factor here ─────────────────────────────
                # Crossing two metadata columns (cluster x sex) is needed for the
                # follow-up contrast after an omnibus interaction test, and having
                # to return to \u2462 to do it means re-running nothing but still
                # losing your place.
                div(style=paste0("background:#eef7ee;border-left:4px solid #27AE60;",
                                 "border-radius:3px;padding:8px;margin:8px 0;"),
                  tags$p(tags$b("Combine two variables into one factor"),
                         style="margin:0 0 4px 0;font-size:12px;color:#1A5C38;"),
                  fluidRow(
                    column(6, uiOutput("s_mk_combo_a_ui")),
                    column(6, uiOutput("s_mk_combo_b_ui"))
                  ),
                  textInput("s_mk_combo_name", "New column name:", value=""),
                  actionButton("s_mk_combo_go", "Create combined factor",
                               class="btn-success", style="width:100%;"),
                  tags$p(tags$small(
                    "Creates a metadata column of the form ", tags$code("A_B"),
                    " and selects it as the Identity class. Use it for the follow-up after an ",
                    "omnibus interaction: interact Sex with seurat_clusters to ask whether the ",
                    "sex effect is cluster-specific, then group by ", tags$code("seurat_clusters_Sex"),
                    " and contrast e.g. ", tags$code("2_F"), " vs ", tags$code("2_M"),
                    " for direction and magnitude in one cluster. ",
                    tags$b("Comparing two such contrasts is not an interaction test"),
                    " \u2014 the omnibus screen is what establishes that the effect differs."),
                    style="margin:4px 0 0 0;color:#1A5C38;font-size:11px;")
                ),
                uiOutput("s_mk_model_ui"),
                actionButton("s_run_mk","▶  Find Markers",
                             class="btn-primary",style="width:100%;")
              ),
              uiOutput("s_mk_status")
            ),
            column(8,
              tabsetPanel(
                tabPanel("Table",
                  DTOutput("s_mk_tbl"),
                  tags$br(), uiOutput("s_mk_dl_ui")),
                tabPanel("P-value histogram",
                  tags$p(tags$small(
                    "Distribution of raw p-values across all tested proteins. A well-calibrated ",
                    "test gives a roughly UNIFORM spread with a spike near 0 (true positives). ",
                    "A skew toward 1, or a bimodal shape, signals a miscalibrated test — e.g. ",
                    "confounding, an ill-fitting model, or missingness handled wrongly."),
                    style="color:grey;margin-top:6px;"),
                  fluidRow(
                    column(4, uiOutput("s_ph_cluster_ui")),
                    column(4, numericInput("s_ph_bins","Bins:",value=20,min=5,max=100,step=5))
                  ),
                  withSpinner(plotOutput("s_mk_phist",height="360px"))),
                tabPanel("Volcano",
                  fluidRow(
                    column(4,
                      uiOutput("s_vol_cluster_ui")
                    ),
                    column(4,
                      numericInput("s_vol_fc","Min |log2FC|:",value=0.5,min=0,step=0.1),
                      numericInput("s_vol_p", "Max p-adj:",   value=0.05,min=0,max=1,step=0.01),
                      numericInput("s_vol_cap","Hide |log2FC| above (0 = no cap):",
                                   value=0, min=0, step=1),
                      tags$p(tags$small(
                        "A coefficient in the tens or hundreds is not a real fold change \u2014 it ",
                        "means the design could not be estimated for that protein. Features ",
                        "without enough observations for the design are already excluded, but a ",
                        "near-collinear design can still produce a few, and one such point ",
                        "compresses every real effect into the centre of the axis. Capping ",
                        "affects the PLOT only; the table and the exported results keep every ",
                        "feature. Check n_obs.1 / n_obs.2 in the table for anything hidden."),
                        style="color:#7f8c8d;font-size:11px;")
                    ),
                    column(4,
                      numericInput("s_vol_nlabel","Label top N features (0 = none):",
                                   value=0, min=0, max=100, step=1),
                      selectizeInput("s_vol_pick", "Or label specific features (max 30):",
                                     choices=NULL, multiple=TRUE,
                                     options=list(maxItems=30, placeholder="Type to search features\u2026")),
                      tags$p(tags$small(
                        "Picked features are always labelled \u2014 they ignore the mode, the top-N ",
                        "cap and the significance cutoffs, so a known marker can be shown even ",
                        "where it is NS. Picks are added to the top-N labels, not a replacement ",
                        "for them. Max 30."),
                        style="color:#7f8c8d;font-size:11px;"),
                      selectInput("s_vol_label_mode","Rank labels by:",
                        choices=c("Significance (p-value)"        = "pval",
                                  "Effect size (|log2FC|)"        = "fc",
                                  "Outermost (log2FC + p-value)"  = "both"),
                        selected="pval"),
                      fluidRow(
                        column(6, numericInput("s_vol_xmin","X-axis min (blank = auto):",
