                    "independent of the Volcano tab's."),
                    style="color:grey;margin-top:6px;"),
                  fluidRow(
                    column(3,
                      numericInput("s_ov_p",  "Max p-adj:",   value=0.05, min=0, max=1, step=0.01),
                      numericInput("s_ov_fc", "Min |log2FC|:", value=0.5,  min=0, step=0.1)),
                    column(3,
                      numericInput("s_ov_minpct","Min pct.1 (0 = off):", value=0, min=0, max=1, step=0.05),
                      radioButtons("s_ov_dir","Direction:",
                        choices=c("Up in cluster"="up","Down in cluster"="down","Either"="either"),
                        selected="up")),
                    column(3,
                      radioButtons("s_ov_type","Plot:",
                        choices=c("Auto"="auto","Venn (2\u20135 clusters)"="venn",
                                  "Exclusivity barplots"="excl","UpSet"="upset"),
                        selected="auto"),
                      tags$p(tags$small(
                        "A Venn becomes unreadable past 4\u20135 sets, and impossible past 7. Auto ",
                        "draws a Venn for \u22644 clusters and the barplots above that. UpSet needs ",
                        "the UpSetR package."),
                        style="color:#7f8c8d;font-size:11px;")),
                    column(3, uiOutput("s_ov_clusters_ui"))
                  ),
                  withSpinner(plotOutput("s_mk_overlap", height="420px")),
                  uiOutput("s_ov_summary"),
                  tags$br(),
                  DTOutput("s_mk_overlap_tbl"),
                  tags$br(), uiOutput("s_ov_dl_ui")),
