                tags$hr(),
                # ORA-specific cutoffs
                conditionalPanel("input.pw_method == 'ORA'",
                  tags$p(tags$b("Gene-selection cutoffs (ORA)"), style="font-size:12px;margin:4px 0;"),
                  radioButtons("pw_sig_type","Select genes by:",
                               choices=c("Adjusted p (FDR)"="padj",
                                         "Raw p-value"="pval",
                                         "Top N by significance"="topn"),
                               selected="padj"),
                  conditionalPanel("input.pw_sig_type != 'topn'",
                    numericInput("pw_p_cut","p / FDR threshold:",value=0.05,min=0,max=1,step=0.01)),
                  conditionalPanel("input.pw_sig_type == 'topn'",
                    numericInput("pw_topn","Top N genes:",value=50,min=5,max=1000,step=5)),
                  numericInput("pw_lfc_cut","Min |log2FC|:",value=0,min=0,step=0.1),
                  checkboxInput("pw_pos_only","Positive log2FC only (up-regulated)",value=FALSE),
                  tags$hr(),
                  tags$p(tags$b("Background (reference set)"), style="font-size:12px;margin:4px 0;"),
                  radioButtons("pw_bg","Background:",
