        # ── S14: Cell-type Annotation (CellMarker 2.0 / custom reference) ────
        tabPanel("⑭ Annotation",
          fluidRow(
            column(4,
              div(class="s-card", style="margin-top:12px;",
                tags$h5("Cell-type annotation (reference marker sets)"),
                tags$p(tags$small(
                  "Annotate clusters against a reference marker database (CellMarker 2.0) ",
                  "or any custom marker table. Two complementary methods: Fisher's exact ",
                  "over-representation (per cluster's DE markers) and AddModuleScore activity ",
                  "(per cell / cluster). Gene symbols must match your data's organism."),
                  style="color:grey;font-size:11px;"),
                tags$hr(),
                tags$p(tags$b("Reference marker sets"), style="font-size:12px;margin:4px 0;"),
                radioButtons("ann_ref_fmt","Reference format:",
                  choices=c("CellMarker 2.0 table (.txt/.tsv/.xlsx)"="cellmarker",
                            "Custom: cell type + gene columns"="twocol",
                            "GMT (one set per line)"="gmt"),
                  selected="cellmarker"),
                fileInput("ann_ref_file","Upload reference file:",
