                  uiOutput("ann_filter_ui")),
                checkboxInput("ann_ignore_case",
                  "Case-insensitive gene matching (UPPERCASE both sides)", value=TRUE),
                tags$p(tags$small("CellMarker mixes human (MERTK) and mouse (Mertk) symbol case. ",
                  "Uppercasing both the reference and your data's symbols lets them match ",
                  "regardless of species-style casing. Applied to interest, background, and signatures."),
                  style="color:grey;font-size:11px;margin:2px 0 4px 0;"),
                actionButton("ann_load_ref","Load reference sets",
                             class="btn-default", style="width:100%;margin-top:4px;"),
                uiOutput("ann_ref_status"),
                tags$hr(),
                tags$p(tags$b("Cluster markers to annotate"), style="font-size:12px;margin:4px 0;"),
                selectInput("ann_src","Marker source:",
                            choices=c("Markers tab (⑨)"="markers",
                                      "Integrated Markers (⑫)"="int_markers")),
                uiOutput("ann_idcol_ui2"),
                tags$hr(),
                tags$p(tags$b("Fisher enrichment settings"), style="font-size:12px;margin:4px 0;"),
                fluidRow(
                  column(6, numericInput("ann_p_cut","Marker p/FDR cutoff:",value=0.05,min=0,max=1,step=0.01)),
                  column(6, selectInput("ann_p_type","Cutoff on:",
                                        choices=c("Adjusted p"="p_val_adj","Raw p"="p_val")))
                ),
                fluidRow(
                  column(6, numericInput("ann_lfc_cut","Min log2FC (>0 = up):",value=0,min=-5,max=5,step=0.1)),
                  column(6, selectInput("ann_alt","Alternative:",
                                        choices=c("greater (enrichment)"="greater","two.sided"="two.sided")))
                ),
                selectInput("ann_universe","Gene universe:",
                            choices=c("All features in this object"="tested",
                                      "Only features present in the reference"="refonly")),
                tags$p(tags$small(
                  "The universe is the denominator of every Fisher test, so it decides the ",
                  "answer as much as the marker list does. ",
                  tags$b("All features in this object"),
                  " asks \u201camong the proteins I measured, are this cluster's markers ",
                  "enriched for this cell type?\u201d ",
                  tags$b("Only features present in the reference"),
                  " restricts to annotatable proteins, which is the more conservative ",
                  "question and avoids crediting enrichment to proteins the reference could ",
                  "never have listed. Genes absent from your data are never added \u2014 an ",
                  "unmeasured protein cannot be a marker of your cluster."),
                  style="color:#7f8c8d;font-size:11px;"),
                actionButton("ann_run_fisher","▶  Run Fisher enrichment",
                             class="btn-success", style="width:100%;margin-top:4px;"),
                tags$hr(),
                tags$p(tags$b("Activity scoring (AddModuleScore)"), style="font-size:12px;margin:4px 0;"),
                tags$p(tags$small("Scores each cell for every reference cell-type signature, then ",
                  "summarizes per cluster. Complements Fisher: absolute signature activity, not ",
                  "over-representation."), style="color:grey;font-size:11px;"),
                actionButton("ann_run_score","▶  Compute activity scores",
                             class="btn-warning", style="width:100%;"),
                uiOutput("ann_status")
              )
            ),
            column(8,
              div(class="s-card", style="margin-top:12px;",
                tabsetPanel(
                  tabPanel("Fisher heatmap",
                    tags$p(tags$small("log2(OR+1); stars = BH-FDR (*<0.05, **<0.01, ***<0.001). ",
                      "Cluster × reference cell type."), style="color:grey;font-size:11px;margin-top:6px;"),
                    withSpinner(plotOutput("ann_fisher_hm", height="520px"))),
                  tabPanel("Fisher table",
                    tags$p(tags$small("Full 2×2 contingency counts, odds ratio, p and BH-FDR per pair."),
                      style="color:grey;font-size:11px;margin-top:6px;"),
                    withSpinner(DTOutput("ann_fisher_tbl")),
                    tags$br(), downloadButton("ann_dl_fisher","⬇ Download Fisher results (.csv)",class="btn-primary")),
                  tabPanel("Best call per cluster",
                    withSpinner(DTOutput("ann_best_tbl"))),
                  tabPanel("Activity scores",
                    tags$p(tags$small("Mean AddModuleScore per cluster × cell-type signature (z-like). ",
                      "Higher = stronger signature activity."), style="color:grey;font-size:11px;margin-top:6px;"),
                    withSpinner(plotOutput("ann_score_hm", height="520px"))),
                  tabPanel("Reference sets",
                    withSpinner(DTOutput("ann_ref_tbl")))
                )
              )
            )
          )
        ),
        # ── S15: Trajectory / Pseudotime (Slingshot) ───────────────────────────
        tabPanel("⑮ Trajectory",
          fluidRow(
            column(4,
              div(class="s-card", style="margin-top:12px;",
                tags$h5("Trajectory / pseudotime (Slingshot)"),
                tags$p(tags$small(
                  "Orders cells along a continuous progression by fitting principal ",
                  "curves through your reduced-dimension space. Reuses an existing ",
                  "embedding + cluster labels — no complete matrix or imputation needed."),
                  style="color:grey;font-size:11px;"),
                tags$hr(),
                radioButtons("traj_obj","Object:",
                  choices=c("Main (⑨ clusters)"="main","Integrated (⑫ clusters)"="int"),
                  selected="main"),
                selectInput("traj_reduc","Embedding to fit on:",
                  choices=c("PCA (NA-aware)"="pca","UMAP (2-D)"="umap",
                            "Integrated (integrated.cca)"="integrated.cca"),
                  selected="pca"),
                tags$p(tags$small("PCA is the most faithful (uses many dims); UMAP is 2-D and ",
                  "most interpretable but least faithful; integrated uses the batch-corrected ",
                  "reduction (integrated object only)."), style="color:grey;font-size:11px;"),
                conditionalPanel("input.traj_reduc == 'pca' || input.traj_reduc == 'integrated.cca'",
                  numericInput("traj_dims","PCs to use (dims):",value=10,min=2,max=50,step=1)),
                uiOutput("traj_cluster_ui"),
                uiOutput("traj_start_ui"),
                uiOutput("traj_end_ui"),
                tags$hr(),
                actionButton("traj_run","▶  Fit trajectory (Slingshot)",
                             class="btn-success", style="width:100%;"),
                uiOutput("traj_status"),
                tags$hr(),
                tags$p(tags$b("Gene along pseudotime"), style="font-size:12px;margin:4px 0;"),
                tags$p(tags$small("Validate the trajectory: a real progression should show ",
                  "known markers changing monotonically along it — not a flat or noisy line."),
                  style="color:grey;font-size:11px;"),
                uiOutput("traj_gene_ui"),
                uiOutput("traj_lineage_ui")
              )
            ),
            column(8,
              div(class="s-card", style="margin-top:12px;",
                tags$div(style="background:#FDF3E7;border:1px solid #E8C39E;border-radius:6px;padding:8px 12px;margin-bottom:10px;",
                  tags$b("Interpret with care. ", style="color:#B9770E;"),
                  tags$span(tags$small(
                    "Slingshot returns an ordering even when no true trajectory exists — it can ",
                    "rank cells along a technical/nFeature axis or simply connect distinct cell ",
                    "types. Confirm the pseudotime tracks real biology (marker dynamics below) ",
                    "before interpreting it as a lineage.", style="color:#7A5B2E;"))),
                tabsetPanel(
                  tabPanel("Trajectory on embedding",
                    tags$p(tags$small("Cells colored by pseudotime with the fitted curve(s) overlaid ",
                      "on the 2-D embedding."), style="color:grey;font-size:11px;margin-top:6px;"),
                    withSpinner(plotOutput("traj_curve_plot", height="520px"))),
                  tabPanel("Pseudotime on UMAP",
                    withSpinner(plotOutput("traj_umap_pt", height="520px"))),
                  tabPanel("Gene vs pseudotime",
                    withSpinner(plotOutput("traj_gene_plot", height="440px"))),
                  tabPanel("Lineage table",
                    tags$p(tags$small("Per-cell pseudotime for each lineage, plus cluster."),
                      style="color:grey;font-size:11px;margin-top:6px;"),
                    withSpinner(DTOutput("traj_tbl")),
                    tags$br(), downloadButton("traj_dl","⬇ Download pseudotime (.csv)",class="btn-primary"))
                )
              )
            )
          )
        ),

        # ── S16: Correlations ────────────────────────────────────────────────
        tabPanel("⑯ Correlations",
          div(class="s-card", style="margin-top:12px;",
            tags$h5("Correlate metadata, per-cell summaries and individual features"),
            tags$p(tags$small(
              "Answers questions of the form \u201cis this covariate actually independent of that ",
              "one?\u201d \u2014 e.g. do the cell-cycle scores track total intensity, is the per-cell ",
              "median a different quantity from the detection count, did regressing depth ",
              "actually remove it. Every per-cell summary and feature value is computed from ",
              "the matrix you pick below, so the same pair of variables can be correlated ",
              "before and after a transformation and the two answers compared."),
              style="color:grey;")
          ),
          fluidRow(
            column(4,
              div(class="s-card",
                tags$h5("① Matrix"),
                selectInput("s_cor_src", "Compute summaries and feature values from:",
                  choices=c(
                    "Raw intensities, NAs present"                     = "raw_na",
                    "Raw intensities, NA\u21920"                           = "raw_zero",
                    "counts layer (integer, zeros)"                    = "counts",
                    "data layer \u2014 normalized, un-regressed (as tested)" = "norm_tested",
                    "regressed, interpretable scale (recomputed)"      = "norm_adj",
                    "scale.data \u2014 regressed + z-scored, NA\u21920"        = "scaled"),
                  selected="norm_tested"),
                tags$p(tags$small(
                  "The first three are stored inputs. ", tags$b("data layer"),
                  " is what the tests read. ", tags$b("regressed"),
                  " is recomputed from the last \u2465 run's settings \u2014 it is not stored, ",
                  "because the data layer deliberately holds the measurement and ",
                  tags$b("scale.data"), " holds the correction. Comparing ",
                  tags$b("data layer"), " against ", tags$b("regressed"),
                  " is the like-for-like test of whether a covariate was removed: same ",
                  "scale, same features, only the regression differs."),
                  style="color:grey;font-size:11px;"),
                uiOutput("s_cor_src_note"),
                tags$hr(),
                tags$h5("② Variables"),
                uiOutput("s_cor_meta_ui"),
                uiOutput("s_cor_derived_ui"),
                uiOutput("s_cor_feat_ui"),
                tags$hr(),
                tags$h5("③ Method"),
                radioButtons("s_cor_method", NULL, inline=TRUE,
                  choices=c("Spearman (rank)"="spearman", "Pearson (linear)"="pearson"),
                  selected="spearman"),
                tags$p(tags$small(
                  "Spearman is the safer default here: intensity distributions are skewed and ",
                  "a single extreme cell can dominate a Pearson coefficient. Use Pearson when ",
                  "you specifically want the strength of a LINEAR relationship \u2014 for example ",
                  "when deciding whether a covariate needs a spline term (compare the two: a ",
                  "high Spearman with a low Pearson means monotone but curved)."),
                  style="color:grey;font-size:11px;"),
                checkboxInput("s_cor_group_split", "Compute within each group separately", value=FALSE),
                conditionalPanel("input.s_cor_group_split == true",
                  uiOutput("s_cor_group_ui")),
                tags$hr(),
                actionButton("s_run_cor", "\u25b6 Compute correlations",
                             class="btn-primary", style="width:100%;"),
                tags$p(tags$small("Pairs are computed on complete observations only \u2014 no imputation."),
                  style="color:grey;font-size:11px;margin-top:6px;")
              )
            ),
            column(8,
              tabsetPanel(
                tabPanel("Heatmap",
                  tags$p(tags$small(
                    "Pairwise correlation of every selected variable. Read the sign as well as ",
                    "the magnitude: two depth proxies correlating at 0.9 means they are ",
                    "interchangeable and you should regress only one."),
                    style="color:grey;margin-top:6px;"),
                  withSpinner(plotOutput("s_cor_heatmap", height="480px"))),
                tabPanel("Scatter",
                  fluidRow(
                    column(5, uiOutput("s_cor_x_ui")),
                    column(5, uiOutput("s_cor_y_ui")),
                    column(2, div(style="margin-top:26px;",
                      checkboxInput("s_cor_logx", "log10 X", value=FALSE)))
                  ),
                  withSpinner(plotOutput("s_cor_scatter", height="420px"))),
                tabPanel("Table",
                  tags$p(tags$small(
                    "One row per pair, with n (complete pairs), the coefficient, and the ",
                    "p-value from cor.test(). Sorted by |coefficient|."),
                    style="color:grey;margin-top:6px;"),
                  withSpinner(DTOutput("s_cor_tbl")),
                  tags$br(),
                  downloadButton("s_cor_dl", "\u2b07 Download correlations (.csv)",
                                 class="btn-primary")),
                tabPanel("Notes",
                  uiOutput("s_cor_notes"))
              )
            )
          )
        )
      ) # end s_tabs tabsetPanel
    ) # end fluidPage
  ),

  # ── User Guide ──────────────────────────────────────────────────────────────
  tabPanel("User Guide",
    tags$h2("SCP-Viz — User Guide"),
    if (!is.null(.GUIDE_SHORT) || !is.null(.GUIDE_LONG))
      div(class = "s-card", style = "margin-bottom:14px;",
        tags$h5("\U0001F4C4 Download this guide as a PDF"),
        tags$p(tags$small(
          "The short guide is a one-pass walkthrough of a typical session. The full ",
          "guide documents every tab, control and export, including the statistical ",
          "choices behind each test."),
          style = "color:grey;"),
        fluidRow(
          column(6,
            if (!is.null(.GUIDE_SHORT))
              downloadButton("dl_guide_short",
                             paste0("\u2b07 Short guide", .guide_size(.GUIDE_SHORT)),
                             class = "btn-info", style = "width:100%;")
            else
              tags$p(tags$small(paste0("Short guide not found (", GUIDE_SHORT_FILE, ")")),
                     style = "color:#B9770E;font-size:11px;")),
          column(6,
            if (!is.null(.GUIDE_LONG))
              downloadButton("dl_guide_long",
                             paste0("\u2b07 Full guide", .guide_size(.GUIDE_LONG)),
                             class = "btn-success", style = "width:100%;")
            else
              tags$p(tags$small(paste0("Full guide not found (", GUIDE_LONG_FILE, ")")),
                     style = "color:#B9770E;font-size:11px;"))
        ),
        tags$p(tags$small(
          "Put the PDFs in a user_guides/ folder next to this script (www/ or the ",
          "script folder itself also work)."),
          style = "color:#7f8c8d;font-size:11px;margin-top:6px;")
      )
    else NULL,
    tags$h3("SCP-Viz 1.1 (original)"),
    tags$p("Upload a wide-format CSV. Set the quantification keyword and protein ID column. ",
           "Enter protein ID and condition keywords. Click 'Unleash the Analysis'."),
    tags$ul(
      tags$li(tags$b("Summary Table / Selected Columns:"), " confirm the data parsed correctly."),
      tags$li(tags$b("Bar / Box / Histogram / Density / Violin:"), " single-protein plots."),
      tags$li(tags$b("Dimensionality Reduction:"), " PCA, UMAP, t-SNE across all proteins; lasso-select cells to create subpopulations."),
      tags$li(tags$b("Volcano:"), " all-protein fold-change test between any two groups or labeled subpopulations.")
    ),
    tags$h3("Seurat Analysis (tab 2)"),
    tags$p("Work through the numbered sub-tabs in order:"),
    tags$ol(
      tags$li(tags$b("① Load Data:"), " upload .RData with prt.int + meta.samples (+ optional prt.map). Click the example button to load the bundled Farris hepatocyte dataset."),
      tags$li(tags$b("② Quality Control:"), " toggle cell filter, abundance outlier removal, and protein sparsity reduction. All downstream steps use the filtered matrix."),
      tags$li(tags$b("③ Covariates:"), " classify each metadata column as Categorical (biology) or Technical (batch). Technical covariates become available for SCTransform regression."),
      tags$li(tags$b("④ Explained Variation:"), " run PCA on raw log₂ data; R² heatmap shows which covariates drive each PC before any normalization."),
      tags$li(tags$b("⑤ Seurat Object:"), " CreateSeuratObject → PercentageFeatureSet → VlnPlot / FeatureScatter QC."),
      tags$li(tags$b("⑥ SCTransform:"), " full Seurat SCTransform (v2) with chosen covariates regressed out; variable feature plot, elbow, PCA, PC heatmaps. Optional integration-mode splits by a categorical variable."),
      tags$li(tags$b("⑦ Embeddings:"), " RunUMAP + RunTSNE on SCTransform PCs; color by biology, feature, or any technical variable."),
      tags$li(tags$b("⑧ Clustering:"), " FindNeighbors + FindClusters (Louvain/Leiden, configurable resolution); cluster UMAP and composition plots."),
      tags$li(tags$b("⑨ Markers:"), " FindAllMarkers or FindMarkers (Wilcoxon/ROC/t-test/MAST); volcano, violin, FeaturePlot, DotPlot."),
      tags$li(tags$b("⑪ Integration:"), " anchor-based integration via SplitObject → SCTransform per group → FindIntegrationAnchors → IntegrateData → UMAP."),
      tags$li(tags$b("⑫ Export:"), " Seurat .rds (unintegrated or integrated), matrices, metadata, markers, PCA/UMAP embeddings, explained variation.")
    )
  )
)


# ════════════════════════════════════════════════════════════════════════════
#  SERVER
# ════════════════════════════════════════════════════════════════════════════
server <- function(input, output, session) {

  # ══ Tab 1.1 PDF export ═════════════════════════════════════════════════════
  # Tab 1.1 previously had no figure export at all — its download buttons only
  # emitted CSVs of plotly-selected points. The Box Plot and Dimensionality
  # Reduction panels now build their figure through a STATIC builder, which the
  # on-screen output and the PDF handler both call, so the exported file matches
  # what is on screen rather than being re-derived.
  #
  # Builders signal "nothing to draw" by stop()ing with a readable message; both
  # consumers catch it, so a missing selection never yields a blank page.
  .v1_pdf_handler <- function(builder, prefix, default_fs = 14) {
    downloadHandler(
      filename = function() paste0("scpviz1_", prefix, "_", Sys.Date(), ".pdf"),
      content  = function(file) {
        w  <- max(2, min(30, .num(input[[paste0(prefix, "_pdf_w")]],  8)))
        h  <- max(2, min(30, .num(input[[paste0(prefix, "_pdf_h")]],  6)))
        fs <- max(6, min(36, .num(input[[paste0(prefix, "_pdf_fs")]], default_fs)))
        p  <- tryCatch(builder(fs), error = function(e) e)
        if (inherits(p, "error")) {
          # req(FALSE) upstream raises a shiny.silent.error carrying no message,
          # which would otherwise render as a bare "Plot error:" page.
          msg <- conditionMessage(p)
          if (!nzchar(trimws(msg)))
            msg <- paste0("A required input is missing.\n",
                          "Load data, enter a Protein ID, and click\n",
                          "'Unleash the Analysis' before exporting.")
          .pdf_open(file, w, h)
          graphics::plot.new()
          graphics::text(0.5, 0.5, paste0("Plot error:\n", msg),
                         col = "red", cex = 1)
          grDevices::dev.off()
          return(invisible(NULL))
        }
        # ggsave renders to a fresh device, which is more reliable than print()
        # on combined objects; fall back to a device + print if it refuses.
        ok <- tryCatch({
          ggplot2::ggsave(file, plot = p, width = w, height = h,
                          device = .pdf_dev(), limitsize = FALSE); TRUE
        }, error = function(e) FALSE)
        if (!ok) {
          .pdf_open(file, w, h)
          tryCatch(print(p), error = function(e) {
            graphics::plot.new()
            graphics::text(0.5, 0.5, paste0("Render error:\n", conditionMessage(e)),
                           col = "red")
          })
          grDevices::dev.off()
        }
      }
    )
  }

  # ── NA-safe numeric input ───────────────────────────────────────────────────
  # A cleared numericInput returns NA, which `%||%` does not catch, so the NA
  # propagates into comparisons and if() calls. Use this wherever a typed number
  # feeds computation rather than display.
  .num <- function(x, default) {
    x <- suppressWarnings(as.numeric(x))
    if (length(x) != 1 || !is.finite(x)) default else x
  }

  options(shiny.maxRequestSize = Inf)
  `%||%` <- function(a, b) if (!is.null(a)) a else b
  # NA/NULL-safe numeric fallback for slider and numericInput values
  .num_pct <- function(x, default) {
    if (is.null(x) || length(x) == 0) return(default)
    x <- suppressWarnings(as.numeric(x[1]))
    if (!is.finite(x)) default else x
  }

  # ── ROC-aware marker helpers ────────────────────────────────────────────────
  # Seurat's ROC test returns myAUC / avg_diff / power instead of p_val /
  # p_val_adj. These helpers let the Markers, Integrated Markers, Pathway, and
  # Annotation tabs treat ROC results uniformly:
  #   .mk_is_roc(df)     TRUE if the frame is ROC-style (myAUC present, no p_val)
  #   .mk_sig_col(df)    the column to filter/rank significance on:
  #                      "power" for ROC, else "p_val_adj" (fallback "p_val")
  #   .mk_sig_better(df) "high" if larger = better (ROC power/myAUC), else "low"
  #   .mk_effect(df)     effect-size column: "avg_log2FC" if present, else
  #                      "avg_diff" (ROC), used for up/down direction & volcano x
  #   .mk_rank_score(df) a signed score for GSEA-style ranking that works for both:
  #                      sign(effect) * (-log10 p)   OR   sign(avg_diff) * power
  .mk_is_roc <- function(df) {
    !is.null(df) && ("myAUC" %in% names(df)) && !("p_val" %in% names(df))
  }
  .mk_sig_col <- function(df) {
    if (.mk_is_roc(df)) "power"
    else if ("p_val_adj" %in% names(df)) "p_val_adj" else "p_val"
  }
  .mk_sig_better <- function(df) if (.mk_is_roc(df)) "high" else "low"
  .mk_effect <- function(df) {
    if ("avg_log2FC" %in% names(df)) "avg_log2FC"
    else if ("avg_diff" %in% names(df)) "avg_diff" else NA_character_
  }
  # filter a marker frame by the significance cutoff, ROC-aware.
  # cut is interpreted as: p <= cut (non-ROC) OR power >= cut (ROC).
  .mk_filter_sig <- function(df, cut) {
    if (is.null(df) || !nrow(df)) return(df)
    sc <- .mk_sig_col(df); if (!(sc %in% names(df))) return(df)
    v <- df[[sc]]
    if (.mk_sig_better(df) == "high") df[!is.na(v) & v >= cut, , drop=FALSE]
    else df[!is.na(v) & v <= cut, , drop=FALSE]
  }
  # order a marker frame best-first, ROC-aware.
  .mk_order <- function(df) {
    if (is.null(df) || !nrow(df)) return(df)
    sc <- .mk_sig_col(df); if (!(sc %in% names(df))) return(df)
    if (.mk_sig_better(df) == "high") df[order(-df[[sc]]), , drop=FALSE]
    else df[order(df[[sc]]), , drop=FALSE]
  }
  # top-N markers per cluster, best-first, ROC-aware. Returns unique gene vector.
  .mk_top_per_cluster <- function(df, n) {
    if (is.null(df) || !nrow(df) || !("cluster" %in% names(df))) return(character(0))
    sc <- .mk_sig_col(df); if (!(sc %in% names(df))) return(unique(df$gene))
    hi <- (.mk_sig_better(df) == "high")
    parts <- lapply(split(df, df$cluster), function(d) {
      o <- if (hi) order(-d[[sc]]) else order(d[[sc]])
      utils::head(d[o, , drop=FALSE]$gene, n)
    })
    unique(unlist(parts, use.names=FALSE))
  }

  # signed ranking score for GSEA (works for p-value or ROC frames).
  .mk_rank_score <- function(df) {
    eff <- .mk_effect(df)
    if (.mk_is_roc(df)) {
      s <- if (!is.na(eff)) sign(df[[eff]]) else sign(df$myAUC - 0.5)
      s * (df$power)
    } else {
      pv <- df$p_val; pv[is.na(pv) | pv <= 0] <- .Machine$double.xmin
      s <- if (!is.na(eff)) sign(df[[eff]]) else 1
      s * (-log10(pv))
    }
  }


  # ══════════════════════════════════════════════════════════════════════════
  #  SCP-QC SERVER  (all reactiveValues and outputs prefixed q_)
  # ══════════════════════════════════════════════════════════════════════════
  q <- reactiveValues(
    prt        = NULL,
    prt_orig   = NULL,
    prt_sparse = NULL,
    meta       = NULL,
    meta_orig  = NULL,
    pmap       = NULL,
    abundance  = NULL,
    dunn_res   = NULL,
    kw_res     = NULL,
    kw_list    = NULL,   # named list for nested KW results
    stat_df    = NULL,
    stat_gb    = NULL,
    stat_met   = NULL,
    stat_nest  = NULL,   # "Nest" or NULL
    stat_log2  = FALSE,  # whether log2 was applied
    log        = character()
  )

  q_log <- function(msg) q$log <- c(q$log, paste0(format(Sys.time(),"%H:%M:%S"), "  ", msg))

  # ── helpers ────────────────────────────────────────────────────────────────
  # Align a prt.map to a target set of protein IDs (the rownames of the final
  # prt.int). prt.map's OWN rownames are often not the accessions (they may be
  # integers or a different key) while the accession lives in a COLUMN — so
  # matching by rownames drops most proteins. This finds the map column whose
  # values best overlap the target IDs, matches on that (leading accession of a
  # ';'-joined group), and returns one row per target protein (left join), so the
  # exported map always has the same protein set/dimension as prt.int.
  q_align_pmap <- function(pmap, target_ids) {
    if (is.null(pmap) || nrow(pmap) == 0 || length(target_ids) == 0) return(NULL)
    pm <- as.data.frame(pmap, stringsAsFactors=FALSE)
    lead <- function(x) sub(";.*", "", as.character(x))
    tgt  <- lead(target_ids)
    # candidate keys: rownames + every column; pick the one matching the most targets
    cand <- c(list(rowname = lead(rownames(pm))),
              setNames(lapply(names(pm), function(cn) lead(pm[[cn]])), names(pm)))
    hits <- vapply(cand, function(k) sum(tgt %in% k), integer(1))
    best <- names(hits)[which.max(hits)]
    key  <- cand[[best]]
    idx  <- match(tgt, key)                       # one map row per target protein
    out  <- pm[idx, , drop=FALSE]
    rownames(out) <- target_ids                    # keep full target set as rownames
    # ensure an explicit accession column exists for downstream use
    if (!"ProteinGroups" %in% names(out)) out$ProteinGroups <- target_ids
    attr(out, "match_col")   <- best
    attr(out, "n_unmatched") <- sum(is.na(idx))
    out
  }

  q_load_rdata <- function(path) {
    env <- new.env(parent=emptyenv()); load(path, envir=env)
    prt  <- if("prt.int"      %in% ls(env)) get("prt.int",     envir=env) else stop("prt.int missing")
    meta <- if("meta.samples" %in% ls(env)) get("meta.samples",envir=env) else stop("meta.samples missing")
    pmap <- if("prt.map"      %in% ls(env)) get("prt.map",     envir=env) else NULL
    if (!is.matrix(prt)) prt <- as.matrix(prt)
    list(prt=prt, meta=as.data.frame(meta), pmap=pmap)
  }

  q_build_abundance <- function(prt, meta) {
    cells <- intersect(colnames(prt), rownames(meta))
    prt_s <- prt[, cells, drop=FALSE]
    ab <- data.frame(
      ID              = cells,
      total_intensity = colSums(prt_s, na.rm=TRUE),
      median_intensity= apply(prt_s, 2, median, na.rm=TRUE),
      mean_intensity  = apply(prt_s, 2, mean,   na.rm=TRUE),
      n_prot          = colSums(!is.na(prt_s)),
      stringsAsFactors= FALSE
    )
    # join meta — use rownames as the join key, drop any existing ID column
    # in meta to avoid duplication (ab already has ID from cells)
    meta_sub <- meta[cells, , drop=FALSE]
    meta_sub <- meta_sub[, setdiff(names(meta_sub), "ID"), drop=FALSE]
    meta_sub$ID <- rownames(meta_sub)
    dplyr::left_join(ab, meta_sub, by="ID")
  }

  # ── ① Load ─────────────────────────────────────────────────────────────────
  observeEvent(input$q_load1, {
    req(input$q_rdata1)
    tryCatch({
      d1 <- q_load_rdata(input$q_rdata1$datapath)
      prt  <- d1$prt; meta <- d1$meta
      # label cells from dataset 1
      if (!is.null(input$q_label1) && input$q_label1 != "")
        meta$dataset <- input$q_label1
      # remove all-NA protein rows
      prt <- prt[rowSums(!is.na(prt)) > 0, , drop=FALSE]
      q$prt_orig <- prt; q$prt <- prt
      q$meta_orig <- meta; q$meta <- meta
      q$pmap <- d1$pmap
      q$abundance <- q_build_abundance(prt, meta)
      q_log(paste0("Dataset 1 loaded: ", nrow(prt), " features × ", ncol(prt), " cells"))
      showNotification(paste0("Loaded: ", nrow(prt), " features × ", ncol(prt), " cells"),
                       type="message", duration=5)
    }, error=function(e) showNotification(paste0("Load error: ", e$message), type="error", duration=10))
  })

  observeEvent(input$q_load2, {
    req(input$q_rdata1)
    tryCatch({
      d1 <- q_load_rdata(input$q_rdata1$datapath)
      if (!is.null(input$q_label1) && input$q_label1 != "") d1$meta$dataset <- input$q_label1

      if (isTRUE(input$q_merge_enable) && !is.null(input$q_rdata2)) {
        d2 <- q_load_rdata(input$q_rdata2$datapath)
        if (!is.null(input$q_label2) && input$q_label2 != "") d2$meta$dataset <- input$q_label2

        # ── Merge prt.int: union of proteins, NA for missing ─────────────────
        all_prots <- union(rownames(d1$prt), rownames(d2$prt))
        # Extend each matrix to the full protein set
        add_rows <- function(mat, all_prots) {
          missing <- setdiff(all_prots, rownames(mat))
          if (length(missing) > 0) {
            pad <- matrix(NA, nrow=length(missing), ncol=ncol(mat),
                          dimnames=list(missing, colnames(mat)))
            mat <- rbind(mat, pad)
          }
          mat[all_prots, , drop=FALSE]
        }
        prt_merged <- cbind(add_rows(d1$prt, all_prots), add_rows(d2$prt, all_prots))
        prt_merged <- prt_merged[rowSums(!is.na(prt_merged)) > 0, , drop=FALSE]

        # ── Merge meta.samples: union of columns, "none" for missing ────────
        all_cols <- union(names(d1$meta), names(d2$meta))
        fill_meta <- function(meta, all_cols) {
          missing <- setdiff(all_cols, names(meta))
          for (col in missing) meta[[col]] <- "none"
          meta[, all_cols, drop=FALSE]
        }
        meta_merged <- rbind(fill_meta(d1$meta, all_cols), fill_meta(d2$meta, all_cols))

        prt_final  <- prt_merged; meta_final <- meta_merged

        # ── Merge prt.map: union by accession, aligned to prt_final ───────────
        pmap_merged <- NULL
        if (!is.null(d1$pmap) || !is.null(d2$pmap)) {
          pm1 <- if(!is.null(d1$pmap)) as.data.frame(d1$pmap) else data.frame()
          pm2 <- if(!is.null(d2$pmap)) as.data.frame(d2$pmap) else data.frame()
          if (nrow(pm1) > 0 && nrow(pm2) > 0) {
            all_map_cols <- union(names(pm1), names(pm2))
            for (col in setdiff(all_map_cols, names(pm1))) pm1[[col]] <- NA
            for (col in setdiff(all_map_cols, names(pm2))) pm2[[col]] <- NA
            combined <- rbind(pm1[, all_map_cols, drop=FALSE], pm2[, all_map_cols, drop=FALSE])
            # align to the final protein set by accession column (not rownames),
            # de-duplicating so each protein maps to one row
            pmap_merged <- q_align_pmap(combined, rownames(prt_final))
          } else if (nrow(pm1) > 0) {
            pmap_merged <- q_align_pmap(pm1, rownames(prt_final))
          } else {
            pmap_merged <- q_align_pmap(pm2, rownames(prt_final))
          }
          if (!is.null(pmap_merged))
            q_log(paste0("prt.map aligned to ", nrow(pmap_merged), " features (matched on '",
                         attr(pmap_merged,"match_col"), "', ",
                         attr(pmap_merged,"n_unmatched"), " without a map entry)"))
        }
        q_log(paste0("Merged: ", nrow(prt_final), " features × ", ncol(prt_final), " cells (",
                     input$q_label1, " + ", input$q_label2, ")"))
      } else {
        prt_final  <- d1$prt[rowSums(!is.na(d1$prt)) > 0, , drop=FALSE]
        meta_final <- d1$meta
        q_log(paste0("Loaded (single): ", nrow(prt_final), " features × ", ncol(prt_final), " cells"))
      }

      q$prt_orig <- prt_final; q$prt <- prt_final
      q$meta_orig <- meta_final; q$meta <- meta_final
      q$pmap <- if(isTRUE(input$q_merge_enable) && exists("pmap_merged")) pmap_merged else d1$pmap
      q$abundance <- q_build_abundance(prt_final, meta_final)
      showNotification(paste0("Ready: ", nrow(prt_final), " features × ", ncol(prt_final), " cells"),
                       type="message", duration=5)
    }, error=function(e) showNotification(paste0("Load/merge error: ", e$message), type="error", duration=10))
  })

  output$q_load_status <- renderUI({
    if (is.null(q$prt)) return(tags$p("No data loaded.", style="color:grey;"))
    n_ds <- length(unique(q$meta$dataset))
    has_merge <- !is.null(q$meta$dataset) && n_ds > 1
    tagList(
      tags$p(paste0("✓ ", nrow(q$prt), " features × ", ncol(q$prt), " cells"),
             style="color:#27AE60;font-weight:600;"),
      if (has_merge) tags$p(paste0("Merged ", n_ds, " datasets"), style="color:#2980B9;font-size:12px;")
    )
  })

  output$q_meta_preview <- renderDT({
    req(q$meta)
    datatable(head(q$meta, 5), options=list(pageLength=5, scrollX=TRUE, dom="t"))
  })

  # ── ② Merged Matrix ─────────────────────────────────────────────────────────
  output$q_matrix_summary <- renderUI({
    req(q$prt)
    n_na  <- sum(is.na(q$prt))
    n_tot <- length(q$prt)
    tagList(
      tags$p(paste0(nrow(q$prt), " features"), style="font-weight:600;"),
      tags$p(paste0(ncol(q$prt), " cells")),
      tags$p(paste0(round(n_na/n_tot*100, 1), "% missing (NA)"), style="color:#E74C3C;")
    )
  })
  output$q_prt_preview <- renderDT({
    req(q$prt)
    mat <- q$prt[seq_len(min(200, nrow(q$prt))), seq_len(min(20, ncol(q$prt))), drop=FALSE]
    df  <- as.data.frame(mat)
    datatable(df, options=list(pageLength=10, scrollX=TRUE))
  })
  output$q_dl_prt <- downloadHandler(
    filename=function() paste0("prt_int_", Sys.Date(), ".csv"),
    content=function(file) {
      req(q$prt)
      readr::write_csv(tibble::rownames_to_column(as.data.frame(q$prt),"protein"), file)
    })
  output$q_dl_meta <- downloadHandler(
    filename=function() paste0("meta_samples_", Sys.Date(), ".csv"),
    content=function(file) {
      req(q$meta)
      readr::write_csv(tibble::rownames_to_column(q$meta[,setdiff(names(q$meta),"ID"),drop=FALSE],"ID"), file)
    })

  # ── ③ Cell QC ────────────────────────────────────────────────────────────────
  # Group-by selector for QC plots
  q_meta_cols <- reactive({
    req(q$meta)
    cols <- names(q$meta)
    cols[sapply(cols, function(c) {
      v <- q$meta[[c]]
      (is.character(v)||is.factor(v)) && length(unique(v[!is.na(v)])) <= 30
    })]
  })
  output$q_groupby_ui <- renderUI({
    cols <- q_meta_cols()
    if (!length(cols)) return(tags$p("No categorical columns.", style="color:grey;"))
    # guess Condition
    def <- cols[grep("condition|Condition|group|Group", cols)[1]]
    if (is.na(def)) def <- cols[1]
    selectInput("q_groupby","Group cells by:",choices=cols, selected=def)
  })
  output$q_outlier_cond_ui <- renderUI({
    cols <- q_meta_cols()
    tagList(
      checkboxInput("q_outlier_per_cond","Per condition (recommended)",TRUE),
      conditionalPanel("input.q_outlier_per_cond",
        selectInput("q_outlier_cond_col","Split by:",choices=cols,
                    selected=if(length(cols))cols[1] else NULL))
    )
  })

  output$q_prot_cond_col_ui <- renderUI({
    cols <- q_meta_cols()
    def  <- if (any(grepl("condition|group|sex|lobe|treat", tolower(cols))))
              cols[grep("condition|group|sex|lobe|treat", tolower(cols))[1]]
            else if (length(cols)) cols[1] else NULL
    selectInput("q_prot_cond_col","Condition column:", choices=cols, selected=def)
  })

  q_palette <- reactive({
    req(q$meta, input$q_groupby, input$q_groupby %in% names(q$meta))
    levs <- sort(unique(as.character(q$meta[[input$q_groupby]][!is.na(q$meta[[input$q_groupby]])])))
    pal  <- scales::hue_pal()(length(levs)); names(pal) <- levs; pal
  })

  # Rebuild abundance table when data changes
  observe({
    req(q$prt, q$meta)
    q$abundance <- q_build_abundance(q$prt, q$meta)
  })

  output$q_cell_boxplot <- renderPlot({
    req(q$abundance, input$q_groupby, input$q_groupby %in% names(q$abundance))
    ab  <- q$abundance
    gb  <- input$q_groupby
    pal <- q_palette()

    y_var <- switch(input$q_box_metric,
      "log2_abund" = NULL,   # special case
      "total"      = "total_intensity",
      "median"     = "median_intensity",
      "mean"       = "mean_intensity",
      "n_prot"     = "n_prot")

    if (input$q_box_metric == "log2_abund") {
      # boxplot of all protein intensities per cell — long format
      # use prt.int pivoted, colored by group
      prt_long <- as.data.frame(q$prt) %>%
        tibble::rownames_to_column("protein") %>%
        tidyr::pivot_longer(-protein, names_to="ID", values_to="Abundance") %>%
        dplyr::filter(!is.na(Abundance)) %>%
        dplyr::left_join(q$meta %>% { m <- .; m[, setdiff(names(m),"ID"),drop=FALSE] } %>% tibble::rownames_to_column("ID"), by="ID")
      if (gb %in% names(prt_long)) {
        ggplot(prt_long, aes(x=ID, y=log2(Abundance), fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
          geom_boxplot(outlier.size=0.3, alpha=0.8) +
          scale_fill_manual(values=pal) +
          scale_color_manual(values=darken_pal(pal)) +
          theme_classic(base_size=12) +
          labs(title="Raw feature intensity values", x="Single Cell", y="log2(Feature Abundance)") +
          theme(axis.text.x=element_blank(), legend.position="top")
      }
    } else {
      ggplot(ab, aes(x=reorder(ID, !!rlang::sym("ID")), y=!!rlang::sym(y_var),
                     fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
        geom_bar(alpha=0.75, stat="identity") +
        scale_fill_manual(values=pal) +
        scale_color_manual(values=darken_pal(pal)) +
        theme_classic(base_size=12) +
        labs(title=paste0(input$q_box_metric, " per cell"), x="Single Cell", y=input$q_box_metric) +
        theme(axis.text.x=element_blank(), legend.position="top")
    }
  })

  # helper: darken palette for outlines
  darken_pal <- function(pal) {
    sapply(pal, function(col) {
      rgb_v <- col2rgb(col)/255
      rgb(pmax(0, rgb_v[1]-0.3), pmax(0, rgb_v[2]-0.3), pmax(0, rgb_v[3]-0.3))
    })
  }

  output$q_total_hist <- renderPlot({
    req(q$abundance, input$q_groupby, input$q_groupby %in% names(q$abundance))
    ab  <- q$abundance; gb <- input$q_groupby; pal <- q_palette()
    mean_v <- mean(log2(ab$total_intensity), na.rm=TRUE)
    sd_v   <- sd(log2(ab$total_intensity),   na.rm=TRUE)
    lo <- mean_v - input$q_outlier_sd * sd_v
    hi <- mean_v + input$q_outlier_sd * sd_v
    p  <- ggplot(ab, aes(x=log2(total_intensity), fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
      geom_histogram(alpha=0.7, binwidth=0.1, position="identity") +
      scale_fill_manual(values=pal) +
      scale_color_manual(values=darken_pal(pal)) +
      labs(title="Distribution of total abundance per cell",
           x="log2(Total Intensity)", y="Frequency") +
      theme_bw(base_size=13) + theme(legend.position="top")
    if (isTRUE(input$q_outlier_enable))
      p <- p + geom_vline(xintercept=c(lo,hi), color="red", linetype="dashed", linewidth=1)
    print(p)
  })

  output$q_total_bar <- renderPlot({
    req(q$abundance, input$q_groupby, input$q_groupby %in% names(q$abundance))
    ab  <- q$abundance %>%
      tidyr::pivot_longer(cols=dplyr::contains("intensity"), names_to="Group", values_to="Abundance")
    gb  <- input$q_groupby; pal <- q_palette()
    ggplot(ab, aes(x=reorder(ID,ID), y=log2(Abundance),
                   fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
      geom_bar(alpha=0.7, stat="identity") +
      scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
      labs(title="Total abundance per single cell", x="Single Cell", y="log2(Abundance)") +
      theme_bw(base_size=12) + theme(axis.text.x=element_blank(), legend.position="top") +
      facet_wrap(~Group, ncol=1)
  })

  output$q_abundance_table <- renderDT({
    req(q$abundance)
    fmt_cols <- c("total_intensity","median_intensity","mean_intensity")
    ab <- q$abundance
    for (col in intersect(fmt_cols, names(ab))) ab[[col]] <- round(ab[[col]], 2)
    datatable(ab, filter="top", options=list(pageLength=15, scrollX=TRUE))
  })

  output$q_minprot_ui <- renderUI({
    req(q$prt_orig)
    # Show distribution hint: median proteins per cell
    med_prot <- median(colSums(!is.na(q$prt_orig)), na.rm=TRUE)
    tagList(
      numericInput("q_minprot_n","Min features per cell:",
                   value=500, min=1, max=max(1, round(med_prot*1.5)), step=50),
      tags$p(tags$small(paste0("Median features per cell: ", round(med_prot))),
             style="color:grey;font-size:11px;")
    )
  })

  # Cell filter — applies min-proteins and/or SD outlier in one step
  observeEvent(input$q_apply_filter, {
    req(q$prt_orig, q$meta_orig)
    prt  <- q$prt_orig
    meta <- q$meta_orig

    cells <- colnames(prt)  # start with all cells

    # ── Filter 1: min proteins per cell ──────────────────────────────────────
    if (isTRUE(input$q_minprot_enable) && !is.null(input$q_minprot_n)) {
      n_prot_per_cell <- colSums(!is.na(prt))
      cells_pass <- names(n_prot_per_cell[n_prot_per_cell >= input$q_minprot_n])
      n_removed  <- length(cells) - length(cells_pass)
      cells      <- intersect(cells, cells_pass)
      q_log(paste0("Min features filter (≥", input$q_minprot_n, "): removed ",
                   n_removed, " cells, ", length(cells), " remaining"))
    }

    # ── Filter 2: abundance outlier removal ──────────────────────────────────
    if (isTRUE(input$q_outlier_enable)) {
      prt_sub <- prt[, cells, drop=FALSE]
      ti       <- log2(colSums(prt_sub, na.rm=TRUE) + 1)
      per_cond <- isTRUE(input$q_outlier_per_cond) && !is.null(input$q_outlier_cond_col) &&
                  input$q_outlier_cond_col %in% names(meta) &&
                  all(cells %in% rownames(meta))

      if (per_cond) {
        cond_vec <- meta[cells, input$q_outlier_cond_col]
        keep <- setNames(logical(length(cells)), cells)
        for (grp in unique(cond_vec[!is.na(cond_vec)])) {
          idx   <- !is.na(cond_vec) & cond_vec == grp
          ti_g  <- ti[cells[idx]]
          mn    <- mean(ti_g, na.rm=TRUE); sv <- sd(ti_g, na.rm=TRUE)
          keep[cells[idx]] <- ti_g >= mn - input$q_outlier_sd*sv &
                              ti_g <= mn + input$q_outlier_sd*sv
        }
        keep[is.na(keep)] <- TRUE
        cells_pass <- cells[keep[cells]]
      } else {
        mn    <- mean(ti, na.rm=TRUE); sv <- sd(ti, na.rm=TRUE)
        cells_pass <- cells[ti >= mn - input$q_outlier_sd*sv &
                            ti <= mn + input$q_outlier_sd*sv]
      }
      n_removed <- length(cells) - length(cells_pass)
      cells     <- cells_pass
      q_log(paste0("SD outlier filter (±", input$q_outlier_sd, " SD): removed ",
                   n_removed, " cells, ", length(cells), " remaining"))
    }

    prt_filt  <- prt[, cells, drop=FALSE]
    meta_filt <- meta[rownames(meta) %in% cells, , drop=FALSE]

    # ── Re-evaluate proteins after cell removal ──────────────────────────────
    # Any protein with no detected values across the retained cells is dropped
    # (it is all-NA/all-zero now and is uninformative / breaks normalization).
    n_prot_before <- nrow(prt_filt)
    det_any <- rowSums(!is.na(prt_filt) & prt_filt > 0) > 0
    prt_filt <- prt_filt[det_any, , drop=FALSE]

    # Optional Seurat-style per-condition check: keep a protein only if detected
    # in >= min cells within every condition group ("all") or at least one
    # ("any"). Removes features that became absent from an entire condition.
    if (isTRUE(input$q_prot_cond_enable) &&
        !is.null(input$q_prot_cond_col) &&
        input$q_prot_cond_col %in% names(meta_filt) &&
        all(colnames(prt_filt) %in% rownames(meta_filt))) {
      cond <- as.character(meta_filt[colnames(prt_filt), input$q_prot_cond_col])
      grps <- unique(cond[!is.na(cond)])
      if (length(grps) >= 1) {
        minc <- max(1, as.integer(.num(input$q_prot_min_cells, 1)))
        det_by_grp <- vapply(grps, function(g) {
          cg <- colnames(prt_filt)[!is.na(cond) & cond == g]
          if (!length(cg)) return(rep(0L, nrow(prt_filt)))
          as.integer(rowSums(!is.na(prt_filt[, cg, drop=FALSE]) & prt_filt[, cg, drop=FALSE] > 0))
        }, integer(nrow(prt_filt)))
        if (is.null(dim(det_by_grp))) det_by_grp <- matrix(det_by_grp, nrow=nrow(prt_filt))
        pass_grp <- det_by_grp >= minc
        keep_p <- if ((input$q_prot_cond_mode %||% "all") == "all")
                    rowSums(pass_grp) == ncol(pass_grp) else rowSums(pass_grp) >= 1
        prt_filt <- prt_filt[keep_p, , drop=FALSE]
      }
    }
    n_prot_removed <- n_prot_before - nrow(prt_filt)
    if (n_prot_removed > 0)
      q_log(paste0("Feature re-evaluation: removed ", n_prot_removed,
                   " feature(s) with no values after cell removal",
                   if (isTRUE(input$q_prot_cond_enable)) " (incl. per-condition check)" else "",
                   "; ", nrow(prt_filt), " features remaining"))

    q$prt       <- prt_filt
    q$meta      <- meta_filt
    q$abundance <- q_build_abundance(prt_filt, meta_filt)
    q_log(paste0("Filters applied: ", length(cells), " / ", ncol(q$prt_orig), " cells retained; ",
                 nrow(prt_filt), " / ", nrow(q$prt_orig), " features retained"))
    showNotification(paste0(length(cells), " / ", ncol(q$prt_orig), " cells and ",
                            nrow(prt_filt), " / ", nrow(q$prt_orig), " features retained after filtering."),
                     type="message", duration=6)
  })

  output$q_filter_status <- renderUI({
    if (is.null(q$prt_orig)) return(NULL)
    n_orig <- ncol(q$prt_orig); n_curr <- ncol(q$prt)
    col <- if(n_curr == n_orig)"#27AE60" else "#F39C12"
    p_orig <- nrow(q$prt_orig); p_curr <- nrow(q$prt)
    pcol <- if(p_curr == p_orig)"#27AE60" else "#F39C12"
    tagList(
      tags$p(paste0(n_curr, " / ", n_orig, " cells"), style=paste0("color:",col,";font-weight:600;font-size:13px;margin-bottom:2px;")),
      tags$p(paste0(p_curr, " / ", p_orig, " features"), style=paste0("color:",pcol,";font-weight:600;font-size:13px;margin-top:0;"))
    )
  })

  # ── ④ Statistical Comparisons ───────────────────────────────────────────────
  output$q_stat_groupby_ui <- renderUI({
    cols <- q_meta_cols()
    def  <- cols[grep("condition|Condition|group|Group|treat|Treat", cols)[1]]
    if (is.na(def)) def <- cols[1]
    selectInput("q_stat_groupby","Inner group (x-axis):",choices=cols,selected=def)
  })

  output$q_stat_nest_ui <- renderUI({
    cols <- q_meta_cols()
    # exclude the inner group from nest options
    excl <- input$q_stat_groupby %||% ""
    nest_cols <- setdiff(cols, excl)
    if (!length(nest_cols)) return(tags$p("No other categorical columns available.",style="color:grey;font-size:12px;"))
    selectInput("q_stat_nest_col","Outer / nesting variable (facets):",
                choices=nest_cols, selected=nest_cols[1])
  })

  observeEvent(input$q_run_stat, {
    req(q$abundance, input$q_stat_groupby, input$q_stat_groupby %in% names(q$abundance))
    gb  <- input$q_stat_groupby
    met_col <- switch(input$q_stat_metric,
      "n_prot" = "n_prot",
      "total"  = "total_intensity",
      "median" = "median_intensity",
      "mean"   = "mean_intensity",
      "n_prot")
    if (!met_col %in% names(q$abundance)) {
      showNotification(paste0("Column '", met_col, "' not found."), type="error", duration=8); return()
    }

    ab   <- q$abundance
    nest <- isTRUE(input$q_stat_nest_enable) && !is.null(input$q_stat_nest_col) &&
            input$q_stat_nest_col %in% names(ab)
    nest_col <- if (nest) input$q_stat_nest_col else NULL

    # Select relevant columns
    keep_cols <- unique(c("ID", gb, met_col, if (!is.null(nest_col)) nest_col))
    df <- ab[, intersect(keep_cols, names(ab)), drop=FALSE]
    names(df)[names(df) == gb]      <- "Group"
    names(df)[names(df) == met_col] <- "Value"
    if (!is.null(nest_col)) names(df)[names(df) == nest_col] <- "Nest"

    # Apply log2 transform if requested (only for intensity metrics, not n_prot)
    apply_log2 <- isTRUE(input$q_stat_log2) && input$q_stat_metric != "n_prot"
    if (apply_log2) {
      df$Value <- log2(pmax(df$Value, 1e-10))   # avoid log(0)
    }

    df <- df[!is.na(df$Group) & !is.na(df$Value), ]

    tryCatch({
      if (!is.null(nest_col)) {
        # ── Nested: run KW + Dunn within each outer level ──────────────────
        nest_levels <- sort(unique(as.character(df$Nest[!is.na(df$Nest)])))
        kw_list  <- list()
        dnn_list <- list()
        for (lvl in nest_levels) {
          sub <- df[!is.na(df$Nest) & df$Nest == lvl, ]
          if (length(unique(sub$Group)) < 2) next
          kw_list[[lvl]]  <- tryCatch(rstatix::kruskal_test(sub, Value ~ Group), error=function(e) NULL)
          dnn_list[[lvl]] <- tryCatch(
            rstatix::dunn_test(sub, Value ~ Group, p.adjust.method=input$q_stat_padj) %>%
              rstatix::add_xy_position(x="Group") %>%
              dplyr::mutate(Nest=lvl),
            error=function(e) NULL)
        }
        q$dunn_res  <- dplyr::bind_rows(Filter(Negate(is.null), dnn_list))
        q$kw_res    <- kw_list[[1]]   # show first level in KW summary
        q$kw_list   <- kw_list
        q$stat_df   <- df
        q$stat_gb   <- "Group"
        q$stat_met  <- met_col
        q$stat_nest <- "Nest"
        q$stat_log2 <- apply_log2
        q_log(paste0("Nested KW: ", gb, " within ", nest_col, " ~ ", met_col,
                     if(apply_log2)" [log2]" else ""))
      } else {
        # ── Simple (no nesting) ──────────────────────────────────────────────
        kw  <- rstatix::kruskal_test(df, Value ~ Group)
        dnn <- rstatix::dunn_test(df, Value ~ Group, p.adjust.method=input$q_stat_padj)
        q$dunn_res  <- rstatix::add_xy_position(dnn, x="Group")
        q$kw_res    <- kw
        q$kw_list   <- NULL
        q$stat_df   <- df
        q$stat_gb   <- "Group"
        q$stat_met  <- met_col
        q$stat_nest <- NULL
        q$stat_log2 <- apply_log2
        q_log(paste0("KW test: ", gb, " ~ ", met_col,
                     if(apply_log2)" [log2]" else "",
                     " | p=", signif(kw$p, 3)))
      }
    }, error=function(e) showNotification(paste0("Stat error: ", e$message), type="error", duration=10))
  })

  output$q_kw_result_ui <- renderUI({
    req(q$kw_res)
    kw <- q$kw_res
    col <- if(kw$p < 0.05) "#E74C3C" else "#27AE60"
    nest_info <- if (!is.null(q$kw_list) && length(q$kw_list) > 1) {
      paste0(" (showing first of ", length(q$kw_list), " levels)")
    } else ""
    tagList(
      tags$p(tags$b(paste0("Kruskal-Wallis", nest_info, ":")), style="font-size:12px;margin:4px 0 2px 0;"),
      tags$p(paste0("χ²=", round(kw$statistic,2), ", df=", kw$df, ", p=", signif(kw$p,3)),
             style=paste0("color:",col,";font-size:13px;font-weight:600;"))
    )
  })

  output$q_stat_boxplot <- renderPlot({
    req(q$stat_df, q$dunn_res)
    df  <- q$stat_df
    met <- q$stat_met
    log2_label <- if (isTRUE(q$stat_log2)) paste0("log2(", met, ")") else met
    nested <- !is.null(q$stat_nest) && "Nest" %in% names(df)

    # Build palette from the inner Group levels
    levs <- sort(unique(as.character(df$Group[!is.na(df$Group)])))
    pal  <- scales::hue_pal()(length(levs)); names(pal) <- levs

    p <- ggplot(df, aes(x=Group, y=Value)) +
      geom_boxplot(alpha=0.9, outlier.shape=NA) +
      geom_jitter(aes(fill=Group, color=Group), shape=21, width=0.2, size=2.5, stroke=0.8) +
      scale_fill_manual(values=pal) +
      scale_color_manual(values=darken_pal(pal)) +
      geom_text(aes(label=paste0("n=", after_stat(count))), stat="count",
                y=min(df$Value, na.rm=TRUE), hjust=0.5, vjust=2, size=3.5) +
      labs(title=paste0(log2_label, " by group"),
           x="", y=log2_label) +
      theme_classic(base_size=13) + theme(legend.position="top")

    if (nested) {
      # Add significance brackets per facet level
      dnn <- q$dunn_res
      if (!is.null(dnn) && nrow(dnn) > 0 && "Nest" %in% names(dnn)) {
        p <- p + ggpubr::stat_pvalue_manual(
          dnn, label="p.adj.signif", tip.length=0.01, step.increase=0.05)
      }
      p <- p + facet_wrap(~Nest) +
        theme(strip.background=element_rect(fill="#eaf4fb"),
              strip.text=element_text(face="bold", size=12))
    } else {
      stat_res <- tryCatch(q$dunn_res, error=function(e) NULL)
      if (!is.null(stat_res) && nrow(stat_res) > 0)
        p <- p + ggpubr::stat_pvalue_manual(stat_res, label="p.adj.signif",
                                             tip.length=0.01, step.increase=0.05)
    }
    print(p)
  })

