  # Per-level colour pickers for the overlaid views. Seeded from whichever
  # palette would be used anyway, so leaving them untouched changes nothing;
  # editing a hex overrides that level only.
  # Level order must match the PLOT's order, which comes from .lvl_factor (and
  # therefore honours any drag-to-order set in ③). The colour fields are indexed
  # by position, so deriving them from a plain sort() here would misassign every
  # colour as soon as a custom order existed.
  .q_detect_levels <- function(split_by) {
    if (identical(split_by, "__all__") || is.null(split_by) ||
        is.null(q$meta) || !split_by %in% names(q$meta)) return("All cells")
    levels(.lvl_factor(q$meta[[split_by]], split_by))
  }

  .q_detect_default_cols <- function(split_by, lv) {
    if (identical(split_by, "__all__")) return(stats::setNames("#3498DB", lv))
    pal <- .pal_for(split_by, lv)
    if (!is.null(pal) && all(lv %in% names(pal))) return(pal[lv])
    stats::setNames(.cluster_pal_cols(length(lv),
                                      input$s_cluster_pal_family %||% "okabe"), lv)
  }

  output$q_detect_col_ui <- renderUI({
    req(q$prt)
    sp <- input$q_detect_split %||% "__all__"
    lv <- .q_detect_levels(sp)
    if (length(lv) > 12)
      return(tags$p(tags$small(paste0(
        length(lv), " levels \u2014 too many for individual colour fields. The palette ",
        "set for '", sp, "' in \u2462 Covariates is used instead.")),
        style="color:#7f8c8d;font-size:11px;"))
    def <- .q_detect_default_cols(sp, lv)
    tagList(
      tags$p(tags$small("Fill colours (hex or R colour name; clear a box to restore the default):"),
             style="color:#7f8c8d;margin-bottom:2px;"),
      fluidRow(lapply(seq_along(lv), function(i)
        column(2, textInput(paste0("q_detect_col_", i), lv[i],
                            value = unname(def[i])))))
    )
  })

  # Resolved colours: the manual field when it parses as a colour, else the
  # default. col2rgb() is the check, so an unfinished hex does not blank a level.
  .q_detect_cols <- function(split_by, lv) {
    def <- .q_detect_default_cols(split_by, lv)
    ui_lv <- .q_detect_levels(split_by)
    if (length(ui_lv) > 12) return(def)
    # Matched by NAME against the field order, not by position in `lv`, so the
    # two cannot drift even if the plot is drawing a subset or a different order.
    for (j in seq_along(lv)) {
      i <- match(lv[j], ui_lv)
      if (is.na(i)) next
      v <- input[[paste0("q_detect_col_", i)]]
      if (!is.null(v) && nzchar(trimws(v)) &&
          !inherits(try(grDevices::col2rgb(trimws(v)), silent=TRUE), "try-error"))
        def[j] <- trimws(v)
    }
    def
  }

  # Per-feature detection rate, either pooled or one row per (feature, level).
  # Returns a long frame with columns Protein / Group / Pct / NCells.
  # Per-feature detection rate. A split restricts the matrix TWICE: to that
  # level's cell columns, and (when drop-undetected is on) to the feature rows
  # seen in at least one of those cells.
  #
  # The row restriction matters more than it looks. Without it every feature
  # absent from a level still contributes a 0% row to that level's distribution,
  # so the spike at zero is largely features that belong to the other datasets.
  # That makes the levels look far sparser than they are and makes the shapes
  # non-comparable, since the zero mass is driven by how different the OTHER
  # levels' feature spaces are rather than by this level's coverage.
  .q_detect_df <- function(split_by = "__all__", drop_undetected = TRUE) {
    if (is.null(q$prt)) stop("Load a matrix first.", call.=FALSE)
    m <- q$prt
    if (identical(split_by, "__all__") || is.null(split_by) ||
        is.null(q$meta) || !split_by %in% names(q$meta)) {
      n_det <- rowSums(!is.na(m))
      keep  <- if (isTRUE(drop_undetected)) n_det > 0 else rep(TRUE, nrow(m))
      return(data.frame(Feature = rownames(m)[keep], Group = "All cells",
                        Pct = n_det[keep] / ncol(m) * 100,
                        NCells = ncol(m), NFeat = sum(keep),
                        NFeatAll = nrow(m), stringsAsFactors = FALSE))
    }
    gv <- as.character(q$meta[colnames(m), split_by])
    lv <- sort(unique(gv[!is.na(gv)]))
    if (!length(lv)) stop("No non-missing levels in '", split_by, "'.", call.=FALSE)
    do.call(rbind, lapply(lv, function(L) {
      cols <- which(gv == L)
      if (!length(cols)) return(NULL)
      sub   <- m[, cols, drop = FALSE]          # restrict to this level's cells
      n_det <- rowSums(!is.na(sub))
      keep  <- if (isTRUE(drop_undetected)) n_det > 0 else rep(TRUE, nrow(sub))
      if (!any(keep)) return(NULL)
      # Each level is its OWN denominator on both axes: its own cell count below,
      # and its own feature count via NFeat.
      data.frame(Feature = rownames(sub)[keep], Group = L,
                 Pct = n_det[keep] / length(cols) * 100,
                 NCells = length(cols), NFeat = sum(keep),
                 NFeatAll = nrow(m), stringsAsFactors = FALSE)
    }))
  }

  .build_q_detect_hist <- function(fs = 13) {
    sp  <- input$q_detect_split %||% "__all__"
    drop0 <- isTRUE(input$q_detect_drop0 %||% TRUE)
    df  <- .q_detect_df(sp, drop0)
    if (is.null(df) || !nrow(df)) stop("No detection rates to plot.", call.=FALSE)
    pooled <- identical(sp, "__all__")
    cutoff <- .num(input$q_sparsity_pct, 50)
    # Pooled has a single series, so density vs overlay is the only real choice;
    # faceting one series is pointless, hence the fallback.
    disp   <- input$q_detect_disp %||% "density"
    if (pooled && identical(disp, "facet")) disp <- "overlay"
    bins   <- max(10, .num(input$q_detect_bins, 50))
    alpha  <- min(1, max(0.05, .num(input$q_detect_alpha, 0.45)))
    df$Group <- .lvl_factor(df$Group, if (pooled) NULL else sp)

    lv  <- levels(df$Group)
    pal <- .q_detect_cols(sp, lv)

    # Label carries BOTH denominators, since a split now varies the feature
    # count per level as well as the cell count.
    ncell_lab <- paste(paste0(lv, " (", 
                              vapply(lv, function(L)
                                df$NCells[match(L, df$Group)], numeric(1)), " cells, ",
                              vapply(lv, function(L)
                                df$NFeat[match(L, df$Group)], numeric(1)), " features)"),
                       collapse = ",  ")
    nfeat_all <- df$NFeatAll[1]

    # ── Bars: how many features clear the threshold, per level ─────────────
    # Aggregated rather than binned, so it answers "how many in / how many out"
    # directly instead of leaving it to be read off a distribution. Counted with
    # the SAME >= comparison the sparsity filter uses, so the Above bar for the
    # pooled view is exactly what the filter would retain.
    if (identical(disp, "bars")) {
      agg <- do.call(rbind, lapply(lv, function(L) {
        z <- df[df$Group == L, , drop = FALSE]
        data.frame(Group = L,
                   Status = c(paste0("≥", cutoff, "%"),
                              paste0("< ", cutoff, "%")),
                   N = c(sum(z$Pct >= cutoff), sum(z$Pct < cutoff)),
                   Total = nrow(z), NCells = z$NCells[1],
                   stringsAsFactors = FALSE)
      }))
      agg$Group  <- factor(agg$Group, levels = lv)
      agg$Status <- factor(agg$Status,
                           levels = c(paste0("≥", cutoff, "%"),
                                      paste0("< ", cutoff, "%")))
      agg$Pct_of_level <- ifelse(agg$Total > 0, 100 * agg$N / agg$Total, NA_real_)

      # fill = Group keeps the user's per-level colours; alpha separates the two
      # sides of the threshold without needing a second colour scale.
      return(
        ggplot2::ggplot(agg, ggplot2::aes(x = Group, y = N,
                                          fill = Group, alpha = Status)) +
          ggplot2::geom_col(position = ggplot2::position_dodge(width = 0.8),
                            width = 0.75, colour = "grey30", linewidth = 0.3) +
          ggplot2::geom_text(
            ggplot2::aes(label = paste0(format(N, big.mark = ","), "\n",
                                        round(Pct_of_level), "%")),
            position = ggplot2::position_dodge(width = 0.8),
            vjust = -0.25, size = fs/3.6, colour = "black", show.legend = FALSE) +
          ggplot2::scale_fill_manual(values = pal, guide = "none") +
          ggplot2::scale_alpha_manual(values = stats::setNames(
            c(1, 0.35), levels(agg$Status))) +
          ggplot2::scale_y_continuous(expand = ggplot2::expansion(mult = c(0, 0.12))) +
          ggplot2::theme_classic(base_size = fs) +
          ggplot2::labs(
            x = if (pooled) NULL else sp, y = "Features", alpha = NULL,
            title = paste0("Features above vs below the ", cutoff, "% threshold",
                           if (!pooled) paste0(", by ", sp) else ""),
            subtitle = paste0(
              "Percentages are of each group's own feature total",
              if (drop0) " (features it detected at least once)" else
                paste0(" (all ", nfeat_all, " matrix features)"),
              if (!pooled) paste0("  |  ", ncell_lab,
                                  "  |  the filter uses the POOLED rate, not these")
              else "  |  this is exactly what the filter keeps and drops"))
      )
    }

    base <- ggplot2::ggplot(df, ggplot2::aes(x = Pct))
    g <- switch(disp,
      "density" = base +
        ggplot2::geom_density(ggplot2::aes(colour = Group, fill = Group),
                              alpha = alpha, linewidth = 0.8) +
        ggplot2::scale_colour_manual(values = pal) +
        ggplot2::scale_fill_manual(values = pal),
      # Overlaid, NOT stacked: position="identity" is what makes the bars sit on
      # top of one another so each level's full distribution stays readable.
      # Stacking summed them, which made the taller series look like it extended
      # the shorter one rather than overlapping it.
      "overlay" = base +
        ggplot2::geom_histogram(ggplot2::aes(fill = Group, colour = Group),
                                bins = bins, position = "identity",
                                alpha = alpha, linewidth = 0.3) +
        ggplot2::scale_fill_manual(values = pal) +
        ggplot2::scale_colour_manual(values = pal),
      base +
        ggplot2::geom_histogram(ggplot2::aes(fill = Group), bins = bins,
                                colour = "white", alpha = alpha) +
        ggplot2::scale_fill_manual(values = pal, guide = "none") +
        ggplot2::facet_wrap(~Group, scales = "free_y"))

    g +
      ggplot2::geom_vline(xintercept = cutoff, colour = "red",
                          linetype = "dashed", linewidth = 1) +
      ggplot2::theme_classic(base_size = fs) +
      ggplot2::labs(
        x = "% cells detecting feature",
        y = if (identical(disp, "density")) "Density" else "Count",
        colour = NULL, fill = NULL,
        title = if (pooled)
                  paste0("Feature detection rate across ", ncol(q$prt), " cells")
                else paste0("Feature detection rate within each ", sp),
        subtitle = paste0(
          "Dashed red = the ", cutoff, "% filter on the left",
          if (identical(disp, "overlay")) "  |  bars overlaid, not stacked" else "",
          if (drop0) "  |  each group restricted to features it detected"
          else paste0("  |  all ", nfeat_all, " features in every group"),
          if (!pooled) paste0(
            "  |  ", ncell_lab,
            "  |  the filter uses the POOLED rate, not these") else ""))
  }

  output$q_detect_hist <- renderPlot({
    req(q$prt)
    p <- tryCatch(.build_q_detect_hist(13), error = function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    print(p)
  })

  output$q_detect_summary <- renderUI({
    req(q$prt)
    sp <- input$q_detect_split %||% "__all__"
    drop0 <- isTRUE(input$q_detect_drop0 %||% TRUE)
    df <- tryCatch(.q_detect_df(sp, drop0), error = function(e) NULL)
    if (is.null(df)) return(NULL)
    cutoff <- .num(input$q_sparsity_pct, 50)
    pooled <- identical(sp, "__all__")

    # The per-level counts below are NOT what the filter retains unless the view
    # is pooled: the filter thresholds the pooled rate over every cell, while a
    # split view thresholds each level against its own denominator. Labelling
    # these "features clearing the filter threshold" conflated the two, so the
    # heading now names the per-level quantity and the actual filter result is
    # shown beside it for comparison.
    n_keep_pooled <- sum(rowSums(!is.na(q$prt)) >= round(ncol(q$prt) * cutoff/100))

    rows <- lapply(split(df, df$Group), function(z) {
      tags$li(tags$b(as.character(z$Group[1])), ": ",
              sum(z$Pct >= cutoff), " / ", nrow(z),
              " features at ", "\u2265", cutoff, "% of its own ",
              z$NCells[1], " cells",
              if (drop0 && nrow(z) < z$NFeatAll[1])
                paste0("  (", z$NFeatAll[1] - nrow(z),
                       " of the ", z$NFeatAll[1],
                       " matrix features are absent from this group and excluded)")
              else "")
    })
    tagList(
      tags$p(tags$small(
        if (pooled) paste0("Features detected in ", "\u2265", cutoff,
                           "% of all cells \u2014 this is exactly what the filter keeps:")
        else paste0("Features reaching ", "\u2265", cutoff,
                    "% detection WITHIN each ", sp, " (own denominator):")),
        style="color:#7f8c8d;margin-bottom:2px;"),
      tags$ul(rows, style="color:#7f8c8d;font-size:12px;margin-top:0;"),
      if (!pooled) tags$p(tags$small(paste0(
        "Applying the filter would keep ", n_keep_pooled, " / ", nrow(q$prt),
        " features \u2014 it thresholds the POOLED rate over all ", ncol(q$prt),
        " cells, so it is not the union or the intersection of the counts above.")),
        style="color:#B9770E;font-size:11px;margin-top:2px;")
    )
  })

  output$q_postfilter_boxplot <- renderPlot({
    req(q$prt_sparse, q$meta, input$q_groupby, input$q_groupby %in% names(q$meta))
    gb  <- input$q_groupby; pal <- q_palette()
    ab  <- q_build_abundance(q$prt_sparse, q$meta)
    rng <- range(ab$n_prot, na.rm=TRUE)
    p   <- ggplot(ab, aes(x=!!rlang::sym(gb), y=n_prot)) +
      geom_boxplot(alpha=0.9) +
      geom_jitter(aes(fill=!!rlang::sym(gb), color=!!rlang::sym(gb)),
                  shape=21, width=0.2, size=2.5, stroke=0.8) +
      scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
      geom_text(aes(label=paste0("n=", after_stat(count))), stat="count",
                y=rng[1], hjust=0.5, vjust=1.5, size=4) +
      labs(title="Features per cell after sparsity filter",
           subtitle=paste0("Range: ", rng[1], " to ", rng[2]),
           x="", y="N features quantified") +
      theme_classic(base_size=13) + theme(legend.position="top")
    print(p)
  })

