    selectInput("q_venn_cond_col","Split by:", choices=cols, selected=if(!is.na(def))def else cols[1])
  })

  q_venn_data <- reactiveVal(NULL)   # stores list(prot_list, title) after Draw Venn

  # Anchor group picker: which level of which variable defines the universe.
  output$q_venn_anchor_ui <- renderUI({
    cols <- q_meta_cols()
    if (!length(cols)) return(tags$p("No categorical columns.", style="color:grey;"))
    sel  <- input$q_venn_anchor_col %||% cols[1]
    lvls <- if (sel %in% names(q$meta))
              sort(unique(as.character(q$meta[[sel]][!is.na(q$meta[[sel]])]))) else character(0)
    tagList(
      selectInput("q_venn_anchor_col", "Anchor variable:", choices=cols, selected=sel),
      selectInput("q_venn_anchor_lvl", "Anchor group:", choices=lvls,
                  selected=if (length(lvls)) lvls[1] else NULL)
    )
  })

  # Detection rate per protein over a given set of columns. Shared by the
  # universe step and the per-group membership step so both use one definition.
  .q_det_rate <- function(cols) {
    if (!length(cols)) return(stats::setNames(rep(0, nrow(q$prt)), rownames(q$prt)))
    rowSums(!is.na(q$prt[, cols, drop=FALSE])) / length(cols)
  }

  observeEvent(input$q_run_venn, {
    req(q$prt, q$meta, input$q_venn_cond_col, input$q_venn_cond_col %in% names(q$meta))
    tryCatch({
      if (!requireNamespace("ggVennDiagram", quietly=TRUE))
        stop("ggVennDiagram package required. Install with: install.packages('ggVennDiagram')")
      m    <- q$prt
      meta <- q$meta
      scol <- input$q_venn_cond_col
      gv   <- as.character(meta[colnames(m), scol])

      # ── Step 1: universe ──────────────────────────────────────────────────
      uni_mode <- input$q_venn_universe %||% "all"
      universe <- rownames(m); uni_desc <- "all features"
      if (identical(uni_mode, "pooled")) {
        thr <- .num(input$q_venn_pool_pct, 25) / 100
        universe <- rownames(m)[.q_det_rate(seq_len(ncol(m))) >= thr]
        uni_desc <- paste0("detected in ≥", round(thr*100), "% of all ",
                           ncol(m), " cells")
      } else if (identical(uni_mode, "anchor")) {
        acol <- input$q_venn_anchor_col; alvl <- input$q_venn_anchor_lvl
        if (is.null(acol) || !acol %in% names(meta) || is.null(alvl))
          stop("Pick an anchor variable and group.", call.=FALSE)
        acols <- which(as.character(meta[colnames(m), acol]) == alvl)
        if (!length(acols))
          stop("No cells in anchor group '", alvl, "'.", call.=FALSE)
        thr <- .num(input$q_venn_anchor_pct, 25) / 100
        universe <- rownames(m)[.q_det_rate(acols) >= thr]
        uni_desc <- paste0("detected in ≥", round(thr*100), "% of the ",
                           length(acols), " cells where ", acol, " = ", alvl)
      }
      if (!length(universe))
        stop("The universe filter left no features — lower the threshold.", call.=FALSE)

      # ── Step 2: membership within each group of the split variable ────────
      set_thr <- .num(input$q_venn_pct, 50) / 100
      lv <- sort(unique(gv[!is.na(gv)]))
      if (length(lv) < 2) stop("Need at least two groups in '", scol, "'.", call.=FALSE)
      if (length(lv) > 7)
        stop("A Venn with ", length(lv), " sets is unreadable. Pick a variable with ",
             "fewer groups, or use the cluster-overlap plots in the Markers tabs.",
             call.=FALSE)
      # When the anchor variable IS the split variable, the anchor level is one
      # of the Venn sets, and the universe was defined by thresholding that very
      # level. Re-applying the membership threshold to it double-filters: with a
      # 10% anchor and a 25% membership threshold the anchor set came out as the
      # 25% subset of its own 10% universe, which is why SCP showed 2099 instead
      # of the 3809 that defines the universe. The anchor level therefore keeps
      # its anchor threshold; the other levels are evaluated at the membership
      # threshold inside that universe.
      anchor_is_split <- identical(uni_mode, "anchor") &&
                         identical(input$q_venn_anchor_col, scol)
      anchor_lvl <- if (anchor_is_split) input$q_venn_anchor_lvl else NULL

      prot_list <- lapply(lv, function(L) {
        cols <- which(gv == L)
        r <- .q_det_rate(cols)
        thr_L <- if (!is.null(anchor_lvl) && identical(L, anchor_lvl))
                   .num(input$q_venn_anchor_pct, 25) / 100 else set_thr
        # > 0 rather than >= 0 when the threshold is 0, so "0%" reads as
        # "seen at least once" rather than trivially including everything.
        keep <- if (thr_L <= 0) r > 0 else r >= thr_L
        intersect(rownames(m)[keep], universe)
      })
      names(prot_list) <- lv

      q_venn_data(list(
        prot_list  = prot_list,
        universe   = universe,
        universe_n = length(universe),
        uni_desc   = uni_desc,
        split_col  = scol,
        anchor_lvl = anchor_lvl,
        set_thr    = set_thr,
        anchor_thr = .num(input$q_venn_anchor_pct, 25) / 100,
        title      = paste0("Overlap by ", scol, " — ",
                           if (set_thr <= 0) "detected" else
                             paste0("≥", round(set_thr*100), "% per group"),
                           if (!is.null(anchor_lvl))
                             paste0("  (", anchor_lvl, " kept at its anchor ",
                                    round(.num(input$q_venn_anchor_pct, 25)), "%)")
                           else "",
                           "  |  universe: ", uni_desc,
                           " (", length(universe), " features)")
      ))
      q_log(paste0("Venn: universe = ", uni_desc, " (", length(universe),
                   " features); split by ", scol, " at ",
                   if (set_thr <= 0) "detected" else paste0("≥", round(set_thr*100), "%"),
                   " — ",
                   paste(names(prot_list), vapply(prot_list, length, integer(1)),
                         sep="=", collapse=", ")))
    }, error=function(e) showNotification(paste0("Venn error: ", e$message), type="error", duration=12))
  })

  output$q_venn_summary <- renderUI({
    d <- q_venn_data(); if (is.null(d)) return(NULL)
    pl <- d$prot_list
    inter <- if (length(pl) >= 2) length(Reduce(intersect, pl)) else NA_integer_
    union_n <- length(unique(unlist(pl, use.names=FALSE)))
    tagList(
      tags$p(tags$small(paste0(
        "Universe: ", d$uni_desc, " — ", d$universe_n, " features.  ",
        "Set sizes: ",
        paste(names(pl), vapply(pl, length, integer(1)), sep=" = ", collapse=",  "),
        ".  Union = ", union_n,
        if (is.finite(inter)) paste0(",  shared by all sets = ", inter, ".") else ".")),
        style="color:#7f8c8d;"),
      if (!is.null(d$anchor_lvl))
        tags$p(tags$small(paste0(
          "'", d$anchor_lvl, "' is the anchor group, so its set is the universe itself ",
          "(≥", round(d$anchor_thr*100), "% within that group) rather than being ",
          "re-filtered at the ", round(d$set_thr*100), "% membership threshold — it should ",
          "therefore equal ", d$universe_n, ". The other groups are evaluated at ",
          round(d$set_thr*100), "% inside that universe.")),
          style="color:#1E8449;font-size:11px;margin-top:-6px;")
      else
        tags$p(tags$small(
          "Set sizes are counted AFTER intersecting with the universe, so they can be ",
          "smaller than the same threshold would give on the unrestricted matrix."),
          style="color:#7f8c8d;font-size:11px;margin-top:-6px;")
    )
  })

  # Exact region counts, computed from the sets rather than read back off the
  # plot. Every cell of the Venn is one combination of "in set / not in set",
  # so the regions partition the union exactly and the counts must sum to it.
  q_venn_regions <- reactive({
    d <- q_venn_data(); if (is.null(d)) return(NULL)
    pl <- d$prot_list; if (length(pl) < 2) return(NULL)
    uni  <- unique(unlist(pl, use.names=FALSE))
    if (!length(uni)) return(NULL)
    memb <- vapply(pl, function(s) uni %in% s, logical(length(uni)))
    if (is.null(dim(memb))) memb <- matrix(memb, nrow=length(uni))
    colnames(memb) <- names(pl)
    key <- apply(memb, 1, function(r) paste(names(pl)[r], collapse=" & "))
    key[!nzchar(key)] <- "(none)"
    tb <- as.data.frame(table(Region=key), stringsAsFactors=FALSE)
    names(tb) <- c("Region", "Features")
    tb <- tb[tb$Region != "(none)", , drop=FALSE]
    tb$N_sets <- vapply(strsplit(tb$Region, " & ", fixed=TRUE), length, integer(1))
    # NB: the column is named "Features"; referring to it as tb$Proteins gave
    # NULL, and -NULL is the "invalid argument to unary operator" error.
    tb <- tb[order(-tb$N_sets, -tb$Features), , drop=FALSE]
    union_n <- length(uni)
    uni_n   <- d$universe_n %||% union_n
    tb$Pct_of_union    <- round(100 * tb$Features / union_n, 1)
    tb$Pct_of_universe <- if (is.finite(uni_n) && uni_n > 0)
                            round(100 * tb$Features / uni_n, 1) else NA_real_
    attr(tb, "union_n") <- union_n
    attr(tb, "universe_n") <- uni_n
    tb
  })

  output$q_venn_region_tbl <- renderDT({
    tb <- q_venn_regions()
    validate(need(!is.null(tb), "Draw a Venn first."))
    datatable(tb, rownames=FALSE, options=list(pageLength=10, dom="tip"),
              caption=paste0("Union = ", attr(tb, "union_n"),
                             " features;  universe = ", attr(tb, "universe_n"),
                             " features. Regions are mutually exclusive and sum to the union."))
  })

  output$q_venn_dl_ui <- renderUI({
    req(q_venn_regions())
    downloadButton("q_venn_dl", "\u2b07 Region table + membership (.csv)",
                   class="btn-success")
  })
  output$q_venn_dl <- downloadHandler(
    filename=function() paste0("sparsity_venn_regions_", Sys.Date(), ".csv"),
    content=function(file){
      d <- q_venn_data(); tb <- q_venn_regions()
      req(!is.null(d), !is.null(tb))
      pl  <- d$prot_list
      uni <- sort(unique(unlist(pl, use.names=FALSE)))
      # Per-protein membership alongside the region summary, so the exact
      # feature lists behind each region are recoverable.
      memb <- as.data.frame(vapply(pl, function(s) uni %in% s, logical(length(uni))))
      names(memb) <- names(pl)
      out <- cbind(protein=uni, memb,
                   region=apply(memb, 1, function(r)
                     paste(names(pl)[as.logical(r)], collapse=" & ")))
      readr::write_csv(out, file)
    })

  # Per-region colour fields for the bar view. Regions come from the same
  # reactive the table uses, so the two always agree on what a region is.
  output$q_venn_bar_col_ui <- renderUI({
    if (!identical(input$q_venn_view %||% "venn", "bars")) return(NULL)
    tb <- q_venn_regions(); if (is.null(tb) || !nrow(tb)) return(NULL)
    if (nrow(tb) > 15)
      return(tags$p(tags$small(paste0(
        nrow(tb), " regions \u2014 too many for individual colour fields; the palette ",
        "family from \u2462 Covariates is used.")),
        style="color:#7f8c8d;font-size:11px;"))
    def <- .q_venn_bar_default_cols(tb$Region)
    tagList(
      tags$p(tags$small("Region fill colours (hex or R colour name; clear to restore):"),
             style="color:#7f8c8d;margin-bottom:2px;"),
      fluidRow(lapply(seq_len(nrow(tb)), function(i)
        column(3, textInput(paste0("q_venn_col_", i), tb$Region[i],
                            value = unname(def[i])))))
    )
  })

  .q_venn_bar_default_cols <- function(regions) {
    cols <- .cluster_pal_cols(length(regions), input$s_cluster_pal_family %||% "okabe")
    stats::setNames(cols, regions)
  }

  # Matched by region NAME against the field order, so a change in region count
  # or ordering cannot shift colours onto the wrong region.
  .q_venn_bar_cols <- function(regions) {
    def <- .q_venn_bar_default_cols(regions)
    tb <- q_venn_regions()
    if (is.null(tb) || nrow(tb) > 15) return(def)
    for (j in seq_along(regions)) {
      i <- match(regions[j], tb$Region)
      if (is.na(i)) next
      v <- input[[paste0("q_venn_col_", i)]]
      if (!is.null(v) && nzchar(trimws(v)) &&
          !inherits(try(grDevices::col2rgb(trimws(v)), silent=TRUE), "try-error"))
        def[j] <- trimws(v)
    }
    def
  }

  # One builder for both the screen and the PDF, and for both views. Previously
  # the Venn was written out twice; the bar view would have made that three
  # copies of the same labelling rules.
  .build_q_venn <- function(fs = 13) {
    d <- q_venn_data()
    if (is.null(d)) stop("Select options and click 'Draw Venn'.", call.=FALSE)

    if (identical(input$q_venn_view %||% "venn", "bars")) {
      tb <- q_venn_regions()
      if (is.null(tb) || !nrow(tb)) stop("No regions to draw.", call.=FALSE)
      denom_u <- identical(input$q_venn_bar_denom %||% "union", "union")
      tb$Pct  <- if (denom_u) tb$Pct_of_union else tb$Pct_of_universe
      # Regions ordered most-shared first, matching the table, so the stacked
      # bar reads top-down in the same order the breakdown lists them.
      tb$Region <- factor(tb$Region, levels = rev(tb$Region))
      pal <- .q_venn_bar_cols(levels(tb$Region))
      stacked <- identical(input$q_venn_bar_mode %||% "dodge", "stack")
      den_lab <- if (denom_u) paste0("union (", attr(tb, "union_n"), ")")
                 else paste0("universe (", attr(tb, "universe_n"), ")")

      g <- if (stacked) {
        ggplot2::ggplot(tb, ggplot2::aes(x = "All regions", y = Features,
                                         fill = Region)) +
          ggplot2::geom_col(width = 0.5, colour = "grey30", linewidth = 0.3) +
          ggplot2::geom_text(ggplot2::aes(
              label = paste0(format(Features, big.mark = ","), "  (",
                             round(Pct, 1), "%)")),
            position = ggplot2::position_stack(vjust = 0.5),
            size = fs/3.8, colour = "black") +
          ggplot2::labs(x = NULL)
      } else {
        ggplot2::ggplot(tb, ggplot2::aes(x = Region, y = Features, fill = Region)) +
          ggplot2::geom_col(width = 0.75, colour = "grey30", linewidth = 0.3) +
          ggplot2::geom_text(ggplot2::aes(
              label = paste0(format(Features, big.mark = ","), "\n",
                             round(Pct, 1), "%")),
            hjust = -0.1, size = fs/3.8, colour = "black") +
          ggplot2::coord_flip() +
          ggplot2::scale_y_continuous(expand = ggplot2::expansion(mult = c(0, 0.18))) +
          ggplot2::labs(x = NULL)
      }
      return(
        g +
          ggplot2::scale_fill_manual(values = pal) +
          ggplot2::theme_classic(base_size = fs) +
          ggplot2::theme(legend.position = if (stacked) "right" else "none") +
          ggplot2::labs(
            y = "Features", fill = NULL, title = d$title,
            subtitle = paste0(
              "Regions are mutually exclusive and sum to the union. ",
              "Percentages are of the ", den_lab, "."))
      )
    }

    lab <- input$q_venn_label %||% "count"
    ggVennDiagram::ggVennDiagram(d$prot_list, label_alpha = 0, label = lab,
                                 label_percent_digit = 1) +
      ggplot2::scale_fill_gradient(low = "grey90", high = "#5ec962") +
      ggplot2::labs(title = d$title, fill = "Feature count",
                    subtitle = if (lab %in% c("both", "percent"))
                      "Percentages are shares of the UNION of the sets, not of the universe"
                    else NULL) +
      ggplot2::theme(legend.position = "bottom", text = ggplot2::element_text(size = fs))
  }

  output$q_venn_plot <- renderPlot({
    p <- tryCatch(.build_q_venn(13), error = function(e) e)
    if (inherits(p, "error")) {
      plot(0, type="n", axes=FALSE, xlab="", ylab="")
      text(0, 0, conditionMessage(p), cex=1.1, col="grey50")
      return(invisible(NULL))
    }
    p
  })

  # ── ⑥ Export — PDF download ────────────────────────────────────────────────
  # Human-readable stems for exported PDFs (keys = output IDs)
  .q_pdf_labels <- c(
    q_cell_boxplot       = "cellQC_boxplot_per_cell",
    q_total_hist         = "cellQC_total_intensity_histogram",
    q_total_bar          = "cellQC_total_intensity_bar",
    q_stat_boxplot       = "stats_boxplot_by_group",
    q_cell_count_bar     = "stats_cell_count_by_group",
    q_sparsity_bar       = "sparsity_features_per_cell",
    q_detect_hist        = "sparsity_detection_rate_histogram",
    q_venn_plot          = "sparsity_venn",
    q_postfilter_boxplot = "sparsity_features_per_cell_postfilter"
  )

  output$q_dl_pdf <- downloadHandler(
    filename = function() {
      key  <- input$q_pdf_plot %||% ""
      stem <- if (key %in% names(.q_pdf_labels)) .q_pdf_labels[[key]] else "plot"
      if (identical(key, "q_cell_boxplot"))
        stem <- paste0(stem, "_", input$q_box_metric %||% "log2_abund")
      paste0("scpqc_", stem, "_", Sys.Date(), ".pdf")
    },
    content  = function(file) {
      w  <- max(2, min(30, .num(input$q_pdf_w, 8)))
      h  <- max(2, min(30, .num(input$q_pdf_h, 6)))
      fs <- max(8, min(24, .num(input$q_pdf_fs, 13)))
      .pdf_open(file, w, h)
      tryCatch({
        key <- input$q_pdf_plot
        p   <- switch(key,

          "q_cell_boxplot" = {
            req(q$abundance, input$q_groupby,
                input$q_groupby %in% names(q$abundance))
            ab  <- q$abundance; gb <- input$q_groupby; pal <- q_palette()
            met <- input$q_box_metric %||% "log2_abund"

            if (identical(met, "log2_abund")) {
              # Mirrors output$q_cell_boxplot: a genuine boxplot of every
              # protein intensity within each cell, from prt.int in long form.
              req(q$prt, q$meta)
              prt_long <- as.data.frame(q$prt) %>%
                tibble::rownames_to_column("protein") %>%
                tidyr::pivot_longer(-protein, names_to="ID", values_to="Abundance") %>%
                dplyr::filter(!is.na(Abundance)) %>%
                dplyr::left_join(
                  q$meta %>% { m <- .; m[, setdiff(names(m),"ID"), drop=FALSE] } %>%
                    tibble::rownames_to_column("ID"),
                  by="ID")
              req(gb %in% names(prt_long))
              ggplot(prt_long, aes(x=ID, y=log2(Abundance),
                                   fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
                geom_boxplot(outlier.size=0.3, alpha=0.8) +
                scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
                labs(title="Raw feature intensity values",
                     x="Single Cell", y="log2(Feature Abundance)") +
                theme_classic(base_size=fs) +
                theme(axis.text.x=element_blank(), legend.position="top")
            } else {
              y_var <- switch(met,
                "total"="total_intensity","median"="median_intensity",
                "mean"="mean_intensity","n_prot"="n_prot")
              req(!is.null(y_var), y_var %in% names(ab))
              ggplot(ab, aes(x=reorder(ID,ID), y=!!rlang::sym(y_var),
                             fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
                geom_bar(alpha=0.75, stat="identity") +
                scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
                labs(title=paste0(met," per cell"), x="Single Cell", y=met) +
                theme_classic(base_size=fs) +
                theme(axis.text.x=element_blank(), legend.position="top")
            }
          },

          "q_total_hist" = {
            req(q$abundance, input$q_groupby,
                input$q_groupby %in% names(q$abundance))
            ab <- q$abundance; gb <- input$q_groupby; pal <- q_palette()
            mn <- mean(log2(ab$total_intensity), na.rm=TRUE)
            sv <- sd(log2(ab$total_intensity),   na.rm=TRUE)
            p  <- ggplot(ab, aes(x=log2(total_intensity),
                                 fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
              geom_histogram(alpha=0.7, binwidth=0.1, position="identity") +
              scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
              labs(title="Distribution of total abundance per cell",
                   x="log2(Total Intensity)", y="Frequency") +
              theme_bw(base_size=fs) + theme(legend.position="top")
            if (isTRUE(input$q_outlier_enable)) {
              lo <- mn - input$q_outlier_sd*sv; hi <- mn + input$q_outlier_sd*sv
              p  <- p + geom_vline(xintercept=c(lo,hi), color="red", linetype="dashed")
            }
            p
          },

          "q_total_bar" = {
            req(q$abundance, input$q_groupby,
                input$q_groupby %in% names(q$abundance))
            ab  <- q$abundance %>%
              tidyr::pivot_longer(cols=dplyr::contains("intensity"), names_to="Group", values_to="Abundance")
            gb  <- input$q_groupby; pal <- q_palette()
            ggplot(ab, aes(x=reorder(ID,ID), y=log2(Abundance),
                           fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
              geom_bar(alpha=0.7, stat="identity") +
              scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
              labs(title="Total abundance per single cell", x="Single Cell", y="log2(Abundance)") +
              theme_bw(base_size=fs) + theme(axis.text.x=element_blank(), legend.position="top") +
              facet_wrap(~Group, ncol=1)
          },

          "q_stat_boxplot" = {
            req(q$stat_df, q$dunn_res)
            df  <- q$stat_df; met <- q$stat_met
            log2_label <- if(isTRUE(q$stat_log2)) paste0("log2(",met,")") else met
            nested <- !is.null(q$stat_nest) && "Nest" %in% names(df)
            levs <- sort(unique(as.character(df$Group[!is.na(df$Group)])))
            pal  <- scales::hue_pal()(length(levs)); names(pal) <- levs
            p <- ggplot(df, aes(x=Group, y=Value)) +
              geom_boxplot(alpha=0.9, outlier.shape=NA) +
              geom_jitter(aes(fill=Group,color=Group), shape=21, width=0.2, size=2.5, stroke=0.8) +
              scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
              geom_text(aes(label=paste0("n=",after_stat(count))), stat="count",
                        y=min(df$Value,na.rm=TRUE), hjust=0.5, vjust=2, size=3.5) +
              labs(title=paste0(log2_label," by group"), x="", y=log2_label) +
              theme_classic(base_size=fs) + theme(legend.position="top")
            if (nested) {
              dnn <- q$dunn_res
              if (!is.null(dnn) && nrow(dnn)>0 && "Nest" %in% names(dnn))
                p <- p + ggpubr::stat_pvalue_manual(dnn, label="p.adj.signif",
                                                     tip.length=0.01, step.increase=0.05)
              p <- p + facet_wrap(~Nest) +
                theme(strip.background=element_rect(fill="#eaf4fb"),
                      strip.text=element_text(face="bold",size=fs-1))
            } else {
              if (!is.null(q$dunn_res) && nrow(q$dunn_res)>0)
                p <- p + ggpubr::stat_pvalue_manual(q$dunn_res, label="p.adj.signif",
                                                     tip.length=0.01, step.increase=0.05)
            }
            p
          },

          "q_cell_count_bar" = {
            req(q$abundance, input$q_stat_groupby)
            ab  <- q$abundance; gb <- input$q_stat_groupby; pal <- q_palette()
            ggplot(ab, aes(x=forcats::fct_rev(!!rlang::sym(gb)),
                           fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
              geom_bar(stat="count") +
              scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
              labs(title="Single cells per group", x="", y="Cell count") +
              coord_flip() + theme_bw(base_size=fs) + theme(legend.position="none") +
              geom_text(aes(label=after_stat(count)), stat="count", hjust=-0.2, size=fs/3)
          },

          "q_sparsity_bar" = {
            req(q$prt, q$abundance, input$q_groupby,
                input$q_groupby %in% names(q$abundance))
            gb  <- input$q_groupby; pal <- q_palette()
            prt_use <- if(!is.null(q$prt_sparse)) q$prt_sparse else q$prt
            ab <- q_build_abundance(prt_use, q$meta)
            ggplot(ab, aes(x=reorder(ID,ID), y=n_prot,
                           fill=!!rlang::sym(gb), color=!!rlang::sym(gb))) +
              geom_bar(alpha=0.75, stat="identity") +
              scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
              labs(title="Features per cell (post-sparsity)", x="Single Cell", y="N features") +
              theme_classic(base_size=fs) + theme(axis.text.x=element_blank(), legend.position="top")
          },

          # Delegates to the panel builder so the split variable, display mode
          # and bin count all carry into the export.
          "q_detect_hist" = { req(q$prt); .build_q_detect_hist(fs) },

          # Same builder as the panel, so the Venn/bar choice, labels, region
          # colours and percentage denominator all carry into the export.
          "q_venn_plot" = {
            p <- tryCatch(.build_q_venn(fs), error = function(e) NULL)
            if (is.null(p)) {
              plot(0, type="n", axes=FALSE)
              text(0, 0, "Run \u25b6 Draw Venn first.", cex=1.1, col="grey50")
              NULL
            } else p
          },
          "q_postfilter_boxplot" = {
            req(q$prt_sparse, q$meta, input$q_groupby,
                input$q_groupby %in% names(q$meta))
            gb  <- input$q_groupby; pal <- q_palette()
            ab  <- q_build_abundance(q$prt_sparse, q$meta)
            rng <- range(ab$n_prot, na.rm=TRUE)
            ggplot(ab, aes(x=!!rlang::sym(gb), y=n_prot)) +
              geom_boxplot(alpha=0.9) +
              geom_jitter(aes(fill=!!rlang::sym(gb), color=!!rlang::sym(gb)),
                          shape=21, width=0.2, size=2.5, stroke=0.8) +
              scale_fill_manual(values=pal) + scale_color_manual(values=darken_pal(pal)) +
              geom_text(aes(label=paste0("n=",after_stat(count))), stat="count",
                        y=rng[1], hjust=0.5, vjust=1.5, size=3.5) +
              labs(title="Features per cell after sparsity filter", x="", y="N features") +
              theme_classic(base_size=fs) + theme(legend.position="top")
          },

          { plot(0,type="n",axes=FALSE); text(0,0,"Select a plot.",col="grey"); NULL }
        )
        if (!is.null(p)) print(p)
      }, error=function(e) {
        msg <- conditionMessage(e)
        if (inherits(e, "shiny.silent.error") || !nzchar(msg))
          msg <- paste0("This plot is not ready to export yet. Generate it on its own ",
                        "tab first, and check the grouping column is still valid.")
        plot(0, type="n", axes=FALSE)
        text(0, 0, paste0("Could not export: ", msg), col="red", cex=0.9)
      })
      dev.off()
      q_log(paste0("PDF exported: ", input$q_pdf_plot, " (", w, "×", h, " in)"))
    }
  )

  # ── SCP-Viz 1.1 format export ────────────────────────────────────────────────
  output$q_dl_scpviz <- downloadHandler(
    filename = function() paste0("scpviz_", Sys.Date(), ".csv"),
    content  = function(file) {
      # Choose matrix: sparsity-filtered if available and requested, else current filtered
      prt_out <- if (isTRUE(input$q_scpviz_use_sparse) && !is.null(q$prt_sparse))
        q$prt_sparse else q$prt
      req(prt_out)

      keyword  <- if (!is.null(input$q_scpviz_keyword) && nchar(input$q_scpviz_keyword) > 0)
        input$q_scpviz_keyword else "Intensity"
      prot_col <- input$q_scpviz_prot_col %||% "Protein"

      # Build wide-format data frame:
      # Row = protein, Column 1 = protein ID, remaining columns = one per cell
      # Cell column names = "<keyword>_<cell_ID>" so SCP-Viz keyword search finds them
      df <- as.data.frame(prt_out, stringsAsFactors=FALSE)
      # Replace 0 (not-detected after ceiling) back to NA for SCP-Viz imputation options
      df[df == 0] <- NA
      colnames(df) <- paste0(keyword, "_", colnames(df))
      df[[prot_col]] <- rownames(prt_out)
      # Put protein ID column first
      df <- df[, c(prot_col, setdiff(names(df), prot_col)), drop=FALSE]

      readr::write_csv(df, file)
      q_log(paste0("Exported SCP-Viz 1.1 CSV: ", nrow(df), " features × ",
                   ncol(df)-1, " cells | keyword='", keyword, "', prot_col='", prot_col, "'"))
    }
  )

  # ── ⑥ Export — data downloads ──────────────────────────────────────────────
  output$q_dl_prt_filtered <- downloadHandler(
    filename=function() paste0("prt_int_filtered_", Sys.Date(), ".csv"),
    content=function(file) {
      prt_out <- if(!is.null(q$prt_sparse)) q$prt_sparse else q$prt
      readr::write_csv(tibble::rownames_to_column(as.data.frame(prt_out),"protein"), file)
      q_log("Exported filtered prt.int")
    })
  output$q_dl_meta_filtered <- downloadHandler(
    filename=function() paste0("meta_samples_filtered_", Sys.Date(), ".csv"),
    content=function(file) {
      prt_out <- if(!is.null(q$prt_sparse)) q$prt_sparse else q$prt
      cells   <- intersect(colnames(prt_out), rownames(q$meta))   # align to exported cells
      meta_out <- q$meta[cells, setdiff(names(q$meta),"ID"), drop=FALSE]
      readr::write_csv(tibble::rownames_to_column(meta_out,"ID"), file)
      q_log(paste0("Exported filtered meta.samples: ", nrow(meta_out), " cells"))
    })
  output$q_dl_map_filtered <- downloadHandler(
    filename=function() paste0("prt_map_filtered_", Sys.Date(), ".csv"),
    content=function(file) {
      prt_out <- if(!is.null(q$prt_sparse)) q$prt_sparse else q$prt
      pmap <- q_align_pmap(q$pmap, rownames(prt_out))
      if (is.null(pmap)) {
        showNotification("No prt.map available to export.", type="warning", duration=6)
        pmap <- data.frame(ProteinGroups=rownames(prt_out))
        rownames(pmap) <- rownames(prt_out)
      }
      readr::write_csv(tibble::rownames_to_column(as.data.frame(pmap),"protein"), file)
      q_log(paste0("Exported filtered prt.map: ", nrow(pmap), " features"))
    })
  output$q_dl_rdata <- downloadHandler(
    filename=function() paste0("scp_qc_", Sys.Date(), ".RData"),
    content=function(file) {
      prt.int      <- if(!is.null(q$prt_sparse)) q$prt_sparse else q$prt
      meta.samples <- q$meta[colnames(prt.int), , drop=FALSE]   # align meta to exported cells
      # Align prt.map to the FINAL protein set by accession (not rownames), so it
      # has exactly one row per protein in prt.int — fixes the dimension mismatch.
      prt.map      <- q_align_pmap(q$pmap, rownames(prt.int))
      prt.int_OG   <- q$prt_orig
      has_map <- !is.null(prt.map) && nrow(prt.map) > 0
      save(prt.int, prt.int_OG, meta.samples, prt.map, file=file)
      q_log(paste0("Exported .RData: ", nrow(prt.int), " features × ", ncol(prt.int),
                   " cells | meta.samples: ", nrow(meta.samples), " cells",
                   " | prt.map: ", if(has_map) paste0(nrow(prt.map), " rows (matched on '",
                     attr(prt.map,"match_col"), "')") else "not available",
                   " | prt.int_OG: ", nrow(prt.int_OG), " features"))
    })
  output$q_log <- renderText({
    if (!length(q$log)) "No activity yet." else paste(q$log, collapse="\n")
  })

  # ══════════════════════════════════════════════════════════════════════════
  #  ORIGINAL SCP-VIZ 1.1 SERVER  (identical to scp_viz_110.r)
  # ══════════════════════════════════════════════════════════════════════════
  use_example <- reactiveVal(FALSE)
  # Absolute path of the example currently loaded, so data() does not have to
  # re-resolve it and a later change of selection does not silently swap the
  # data under an analysis that has already been run.
  example_path <- reactiveVal(NULL)

  data <- reactive({
    if (use_example()) {
      p <- example_path()
      req(!is.null(p), file.exists(p))
      file <- switch(tolower(tools::file_ext(p)),
        "csv" = read_csv(p, show_col_types = FALSE),
        "tsv" = read_delim(p, delim = "\t", show_col_types = FALSE),
        "txt" = read_delim(p, delim = "\t", show_col_types = FALSE),
        read_csv(p, show_col_types = FALSE))
    } else {
      req(input$data_upload)
      filepath <- input$data_upload$datapath
      fileext  <- tools::file_ext(filepath)
      if (fileext == "csv") {
        file <- read_csv(filepath, show_col_types = FALSE)
      } else if (fileext == "tsv") {
        file <- read_delim(filepath, delim = "\t", show_col_types = FALSE)
        write_csv(file, "newfile.csv"); file <- read_csv("newfile.csv", show_col_types = FALSE)
      } else if (fileext %in% c("xlsx", "xls")) {
        file <- read_excel(filepath)
        write_csv(file, "newfile.csv"); file <- read_csv("newfile.csv", show_col_types = FALSE)
      } else stop("Invalid file type")
    }
    janitor::clean_names(file)
  })

  observeEvent(input$load_example, {
    p <- input$example_set
    if (is.null(p) || !nzchar(p)) {
      showNotification("Pick an example dataset from the list first.",
                       type="warning", duration=6); return()
    }
    if (!file.exists(p)) {
      showNotification(paste0("Example file not found: ", p), type="error", duration=10); return()
    }
    example_path(p)
    use_example(TRUE)
    file <- tryCatch(data(), error = function(e) e)
    if (inherits(file, "error")) {
      use_example(FALSE); example_path(NULL)
      showNotification(paste0("Could not read that example: ", conditionMessage(file)),
                       type="error", duration=12); return()
    }

    if (.is_builtin_csv_example(p)) {
      # Only the original bundled set has known column names and conditions.
      updateTextInput(session, "sample_keyword", value = EXAMPLE_KEYWORD)
      updateTextInput(session, "protein",        value = EXAMPLE_PROTEIN_ID)
      updateNumericInput(session, "num_conditions", value = EXAMPLE_N_COND)
      updateSelectInput(session, "protein_col",
                        choices  = names(file),
                        selected = janitor::make_clean_names(EXAMPLE_PROTEIN_COL))
      for (i in seq_along(EXAMPLE_CONDITIONS))
        updateTextInput(session, paste0("condition_", i), value = EXAMPLE_CONDITIONS[i])
      showNotification("Example data loaded. Hit 'Unleash the Analysis' to run.",
                       type = "message", duration = 5)
    } else {
      # Any other set: populate the column list and guess the intensity keyword
      # from the column names, but leave the conditions blank rather than
      # carrying over values from a different dataset.
      updateSelectInput(session, "protein_col", choices = names(file))
      guess <- grep("quantity|intensity|abundance|lfq|area",
                    names(file), ignore.case = TRUE, value = TRUE)
      if (length(guess)) {
        # Longest common-looking token: use the first match's suffix as the key.
        updateTextInput(session, "sample_keyword", value = guess[1])
      }
      showNotification(paste0(
        "Loaded '", basename(p), "' (", nrow(file), " rows, ", ncol(file), " columns). ",
        "Set the feature-ID column, sample keyword and conditions, then run."),
        type = "message", duration = 10)
    }
  })

  observeEvent(input$data_upload, {
    use_example(FALSE); example_path(NULL)
    updateSelectInput(session, "protein_col", choices = names(data()))
  })

  input_summary <- reactive({
    req(input$submit, df_long())
    long <- df_long(); protein_col <- input$protein_col
    per_cell <- long %>%
      filter(!is.na(Intensity), Intensity > 0) %>%
      group_by(Samples) %>%
      summarise(n_detected = n_distinct(!!sym(protein_col)), .groups = "drop")
    nd <- per_cell$n_detected
    list(n_cells=n_distinct(long$Samples), n_molecules=n_distinct(long[[protein_col]]),
         mean_per_cell=if(length(nd)) round(mean(nd,na.rm=TRUE),1) else NA,
         sd_per_cell=if(length(nd)>1) round(sd(nd,na.rm=TRUE),1) else NA,
         min_per_cell=if(length(nd)) min(nd,na.rm=TRUE) else NA,
         max_per_cell=if(length(nd)) max(nd,na.rm=TRUE) else NA, per_cell_tbl=per_cell)
  })

  # ── Condition groups reactive — builds named list from sidebar condition inputs ──
  condition_groups <- reactive({
    req(input$num_conditions)
    grps <- list()
    for (i in seq_len(input$num_conditions)) {
      val <- input[[paste0("condition_", i)]]
      if (!is.null(val) && nchar(trimws(val)) > 0) {
        # Split on " or " to match the original condition matching logic
        terms <- trimws(unlist(strsplit(tolower(val), split=" or ", fixed=TRUE)))
        grps[[val]] <- terms
      }
    }
    grps
  })

  # ── Populate condition split selectors ────────────────────────────────────────
  observe({
    req(input$submit, nchar(trimws(input$sample_keyword %||% "")) > 0, condition_groups())
    grp_names <- names(condition_groups())
    choices <- c("All cells (combined)" = "none", setNames(grp_names, grp_names))
    updateSelectInput(session, "summary_split", choices = choices)
    updateSelectInput(session, "bar_split",
                      choices = c("None (all cells)" = "none", setNames(grp_names, grp_names)))
  })

  output$data_summary_ui <- renderUI({
    req(input_summary())
    split_by <- input$summary_split %||% "none"

    # If a condition is selected, filter the long data to that condition's cells
    if (split_by != "none") {
      cg       <- condition_groups()
      req(split_by %in% names(cg))
      keywords <- cg[[split_by]]
      tbl_full <- input_summary()$per_cell_tbl
      tbl      <- tbl_full %>%
        filter(grepl(paste(keywords, collapse = "|"), Samples, ignore.case = TRUE))
      n_cells       <- nrow(tbl)
      mean_per_cell <- round(mean(tbl$n_detected, na.rm = TRUE), 1)
      sd_per_cell   <- round(sd(tbl$n_detected, na.rm = TRUE), 1)
      min_per_cell  <- min(tbl$n_detected, na.rm = TRUE)
      max_per_cell  <- max(tbl$n_detected, na.rm = TRUE)
      n_molecules   <- input_summary()$n_molecules
      subtitle      <- paste0("Condition: ", split_by)
    } else {
      s             <- input_summary()
      n_cells       <- s$n_cells
      n_molecules   <- s$n_molecules
      mean_per_cell <- s$mean_per_cell
      sd_per_cell   <- s$sd_per_cell
      min_per_cell  <- s$min_per_cell
      max_per_cell  <- s$max_per_cell
      tbl           <- s$per_cell_tbl
      subtitle      <- "Based on the full uploaded dataset and if applicable, after imputation and normalization."
    }

    tagList(
      tags$h3("Input Data Summary", style = "margin-top: 20px;"),
      tags$p(tags$small(subtitle), style = "color: grey;"),
      tags$hr(),
      fluidRow(
        column(4, tags$div(style="background:#2980B9;color:white;border-radius:8px;padding:20px;text-align:center;",
                           tags$h2(n_cells,      style="margin:0;"),tags$p("Total Cells",style="margin:0;font-size:14px;"))),
        column(4, tags$div(style="background:#27AE60;color:white;border-radius:8px;padding:20px;text-align:center;",
                           tags$h2(n_molecules,  style="margin:0;"),tags$p("Unique Molecules (Study-wide)",style="margin:0;font-size:14px;"))),
        column(4, tags$div(style="background:#8E44AD;color:white;border-radius:8px;padding:20px;text-align:center;",
                           tags$h2(mean_per_cell,style="margin:0;"),tags$p("Avg Molecules per Cell",style="margin:0;font-size:14px;")))
      ),
      tags$br(),
      tags$h4("Molecules Detected per Cell"),
      fluidRow(
        column(3,tags$div(style="border:1px solid #ddd;border-radius:6px;padding:14px;text-align:center;",tags$h4(mean_per_cell,style="margin:0;color:#2980B9;"),tags$p("Mean",style="margin:0;color:grey;"))),
        column(3,tags$div(style="border:1px solid #ddd;border-radius:6px;padding:14px;text-align:center;",tags$h4(sd_per_cell,  style="margin:0;color:#2980B9;"),tags$p("Std Dev",style="margin:0;color:grey;"))),
        column(3,tags$div(style="border:1px solid #ddd;border-radius:6px;padding:14px;text-align:center;",tags$h4(min_per_cell, style="margin:0;color:#2980B9;"),tags$p("Min",style="margin:0;color:grey;"))),
        column(3,tags$div(style="border:1px solid #ddd;border-radius:6px;padding:14px;text-align:center;",tags$h4(max_per_cell, style="margin:0;color:#2980B9;"),tags$p("Max",style="margin:0;color:grey;")))
      ),
      tags$br(),
      tags$h4("Distribution of Molecules Detected per Cell"),
      plotlyOutput("summary_hist", height = "300px"),
      tags$br(),
      tags$h4("Per-Cell Detection Table"),
      DTOutput("summary_per_cell_tbl")
    )
  })

  output$summary_hist <- renderPlotly({
    req(input_summary())
    tbl      <- input_summary()$per_cell_tbl
    split_by <- input$summary_split %||% "none"
    if (split_by != "none") {
      cg       <- condition_groups()
      keywords <- cg[[split_by]]
      tbl      <- tbl %>%
        filter(grepl(paste(keywords, collapse="|"), Samples, ignore.case=TRUE))
    }
    ggplotly(ggplot(tbl, aes(x=n_detected)) +
               geom_histogram(bins=40, fill="#2980B9", color="white", alpha=0.85) +
               theme_classic(base_size=13) +
               labs(title=if(split_by!="none") paste0("Condition: ",split_by) else NULL,
                    x="Molecules Detected", y="Number of Cells"))
  })

  output$summary_per_cell_tbl <- renderDT({
    req(input_summary())
    tbl      <- input_summary()$per_cell_tbl
    split_by <- input$summary_split %||% "none"
    if (split_by != "none") {
      cg       <- condition_groups()
      keywords <- cg[[split_by]]
      tbl      <- tbl %>%
        filter(grepl(paste(keywords, collapse="|"), Samples, ignore.case=TRUE))
    }
    datatable(tbl %>%
                rename(Cell=Samples, `Molecules Detected`=n_detected) %>%
                arrange(desc(`Molecules Detected`)),
              options=list(pageLength=10))
  })

  # ── Quantitative column matcher ───────────────────────────────────────────
  # Column names are cleaned by janitor on import ("PG.Quantity" -> "pg_quantity"),
  # so a literal keyword will often miss. Try regex, then a punctuation-
  # insensitive form of the keyword, then a plain fixed match.
  quan_cols <- reactive({
    req(input$sample_keyword, nchar(trimws(input$sample_keyword)) > 0)
    req(use_example() || !is.null(input$data_upload))
    nm <- names(data())
    kw <- trimws(input$sample_keyword)
    hits <- tryCatch(grep(kw, nm, ignore.case = TRUE, value = TRUE),
                     error = function(e) character(0))
    if (!length(hits)) {
      kw2  <- gsub("_+", "_", gsub("[^a-z0-9]+", "_", tolower(kw)))
      hits <- grep(kw2, nm, ignore.case = TRUE, fixed = TRUE, value = TRUE)
    }
    if (!length(hits))
      hits <- grep(kw, nm, ignore.case = TRUE, fixed = TRUE, value = TRUE)
    setdiff(hits, input$protein_col %||% character(0))
  })

  selected_columns <- reactive({ data.frame(column_name = quan_cols()) })
  output$selected_columns <- renderDT({ selected_columns() })

  organized_data <- reactive({
    req(input$protein_col, input$sample_keyword, nchar(trimws(input$sample_keyword)) > 0)
    cols <- quan_cols()
    if (!length(cols)) {
      showNotification(paste0(
        "No quantitative columns matched '", input$sample_keyword, "'. Column names are ",
        "cleaned on import (e.g. 'PG.Quantity' becomes 'pg_quantity'). Check the ",
        "Selected Columns tab and try a shorter keyword such as 'quantity'."),
        type = "error", duration = 12)
      req(FALSE)
    }
    data() %>% select(all_of(c(input$protein_col, cols)))
  })
  df <- reactive({ data.frame(organized_data()) })

  df_long <- reactive({
    req(input$protein_col, input$sample_keyword, nchar(trimws(input$sample_keyword)) > 0)
    selected_col <- input$protein_col
    long_data <- df() %>%
      pivot_longer(cols=-all_of(selected_col), names_to="Samples", values_to="Intensity")
    if (input$impute_zeros) {
      if (input$imputation_method=="zeros")
        long_data <- long_data %>% mutate(Intensity=ifelse(is.na(Intensity),0,Intensity))
      else if (input$imputation_method=="background_noise")
        long_data <- long_data %>% mutate(Intensity=ifelse(is.na(Intensity),input$background_noise_level,Intensity))
    }
    long_data <- switch(input$normalization_method,
      "median" = { gm <- median(long_data$Intensity, na.rm=TRUE)
                   long_data %>% group_by(Samples) %>%
                     mutate(Intensity=Intensity/median(Intensity,na.rm=TRUE)*gm) %>% ungroup() },
      "median_group" = {
        grp_list <- tryCatch(median_group_list(), error=function(e) list())
        if (length(grp_list) == 0) {
          showNotification("No groups defined for median per group normalization — using global median.",
                           type="warning", duration=8)
          gm <- median(long_data$Intensity, na.rm=TRUE)
          long_data %>% group_by(Samples) %>%
            mutate(Intensity=Intensity/median(Intensity,na.rm=TRUE)*gm) %>% ungroup()
        } else {
          # Tag each sample with its group
          long_data$norm_group <- NA_character_
          for (grp_name in names(grp_list)) {
            terms   <- grp_list[[grp_name]]
            pattern <- paste(terms, collapse="|")
            long_data$norm_group[grepl(pattern, long_data$Samples, ignore.case=TRUE)] <- grp_name
          }
          # Compute global median per group (across all proteins × samples in group)
          grp_medians <- long_data %>%
            filter(!is.na(norm_group)) %>%
            group_by(norm_group) %>%
            summarise(grp_med=median(Intensity, na.rm=TRUE), .groups="drop")
          # Normalize within each sample using that sample's group median as target
          long_data %>%
            left_join(grp_medians, by="norm_group") %>%
            group_by(Samples) %>%
            mutate(Intensity=Intensity / median(Intensity,na.rm=TRUE) *
                     ifelse(!is.na(grp_med[1]), grp_med[1],
                            median(long_data$Intensity, na.rm=TRUE))) %>%
            ungroup() %>%
            select(-norm_group, -grp_med)
        }
      },
      "tic"    = { mt <- mean((long_data %>% group_by(Samples) %>%
                                 summarise(t=sum(Intensity,na.rm=TRUE)))$t)
                   long_data %>% group_by(Samples) %>%
                     mutate(Intensity=Intensity/sum(Intensity,na.rm=TRUE)*mt) %>% ungroup() },
      "seurat" = { long_data %>% group_by(Samples) %>%
                     mutate(Intensity=log1p(Intensity/sum(Intensity,na.rm=TRUE)*10000)) %>% ungroup() },
      "ref_protein" = {
        ref_id   <- trimws(input$ref_protein_id)
        prot_col <- input$protein_col
        ref_vals <- long_data %>%
          filter(!!sym(prot_col) == ref_id) %>%
          select(Samples, ref_intensity = Intensity)
        if (nrow(ref_vals) == 0) {
          showNotification(paste0("Reference protein '", ref_id, "' not found in data."),
                           type="error", duration=8)
          long_data
        } else {
          # Divide each cell by its reference protein intensity
          normed <- long_data %>%
            left_join(ref_vals, by="Samples") %>%
            filter(!is.na(ref_intensity), ref_intensity > 0) %>%
            mutate(Intensity = Intensity / ref_intensity) %>%
            select(-ref_intensity)

          # Rescale
          scale_choice <- input$ref_protein_scale %||% "median"
          if (scale_choice == "median") {
            # Global median of reference intensities
            sf <- median(ref_vals$ref_intensity, na.rm=TRUE)
            normed <- normed %>% mutate(Intensity = Intensity * sf)

          } else if (scale_choice == "median_group") {
            # Per-group median — each group's cells are rescaled to that group's median
            grp_list <- tryCatch(ref_group_list(), error=function(e) list())
            if (length(grp_list) == 0) {
              # Fallback to global median if no groups defined
              sf <- median(ref_vals$ref_intensity, na.rm=TRUE)
              normed <- normed %>% mutate(Intensity = Intensity * sf)
            } else {
              # Tag each sample with its group
              normed$ref_group <- NA_character_
              for (grp_name in names(grp_list)) {
                terms   <- grp_list[[grp_name]]
                pattern <- paste(terms, collapse="|")
                matches <- grepl(pattern, normed$Samples, ignore.case=TRUE)
                normed$ref_group[matches] <- grp_name
              }
              # Compute median reference intensity per group from ref_vals
              ref_tagged <- ref_vals
              ref_tagged$ref_group <- NA_character_
              for (grp_name in names(grp_list)) {
                terms   <- grp_list[[grp_name]]
                pattern <- paste(terms, collapse="|")
                ref_tagged$ref_group[grepl(pattern, ref_tagged$Samples, ignore.case=TRUE)] <- grp_name
              }
              grp_medians <- ref_tagged %>%
                filter(!is.na(ref_group)) %>%
                group_by(ref_group) %>%
                summarise(grp_sf = median(ref_intensity, na.rm=TRUE), .groups="drop")
              normed <- normed %>%
                left_join(grp_medians, by="ref_group") %>%
                mutate(Intensity = ifelse(!is.na(grp_sf), Intensity * grp_sf,
                                          Intensity * median(ref_vals$ref_intensity, na.rm=TRUE))) %>%
                select(-ref_group, -grp_sf)
            }

          } else if (scale_choice == "10000") {
            normed <- normed %>% mutate(Intensity = Intensity * 10000)
          }
          # "none": no rescaling, raw ratio
          normed
        }
      },
      long_data)
    long_data
  })

  df_filtered <- reactive({
    req(input$protein_col)
    col_name <- input$protein_col
    target   <- trimws(input$protein %||% "")
    if (!nzchar(target)) {
      showNotification(paste0(
        "Enter a Protein/Peptide ID in the sidebar — the Bar, Box, Histogram, ",
        "Density and Violin tabs all plot a single feature."),
        type = "message", duration = 8)
      req(FALSE)
    }
    out <- df_long() %>%
      filter(trimws(as.character(!!as.name(col_name))) == target)
    if (nrow(out) == 0) {
      showNotification(paste0("'", target, "' was not found in column '", col_name,
                              "'. Check the ID and the selected ID column."),
                       type = "error", duration = 12)
      req(FALSE)
    }
    if (all(is.na(out$Intensity))) {
      showNotification(paste0("'", target, "' is NA in every cell, so there is nothing ",
                              "to plot. Enable imputation or choose another ID."),
                       type = "warning", duration = 12)
      req(FALSE)
    }
    out
  }) |> bindEvent(input$submit, ignoreNULL=FALSE, ignoreInit=FALSE)

