  # Helper: get ref group keywords list (mirrors condition_groups logic)
  ref_group_list <- reactive({
    req(input$num_ref_groups)
    grps <- list()
    for (i in seq_len(input$num_ref_groups)) {
      val <- input[[paste0("ref_group_", i)]]
      if (!is.null(val) && nchar(trimws(val)) > 0) {
