  })

  output$conditions_input <- renderUI({
    lapply(1:input$num_conditions, function(i) {
      current_val <- isolate(input[[paste0("condition_",i)]])
      textInput(paste0("condition_",i), paste0("Condition ",i),
                value=if(!is.null(current_val)) current_val else "")
    })
  })

  get_sample_type <- function(Samples, num_conditions, input) {
    conditions <- sapply(1:num_conditions, function(i) {
      condition_terms <- trimws(unlist(strsplit(tolower(input[[paste0("condition_",i)]]),split=" or ",fixed=TRUE)))
      any(sapply(condition_terms,function(x) grepl(paste0(x),Samples,ignore.case=TRUE)))
    })
    matched_condition <- match(TRUE,conditions,nomatch=NA)
    if (!is.na(matched_condition)) return(input[[paste0("condition_",matched_condition)]])
    return(NA)
  }

  df_filtered_with_color <- reactive({
    df_filtered() %>% rowwise() %>%
      mutate(Group=get_sample_type(Samples,input$num_conditions,input)) %>% ungroup()
  })

  condition_names <- reactive({ unique(na.omit(df_filtered_with_color()$Group)) })

  output$summary_table <- renderDT({
    if (input$summary_choice=="group") {
      summary_data <- df_filtered_with_color() %>% group_by(Group) %>%
        summarise(min=min(Intensity,na.rm=TRUE),max=max(Intensity,na.rm=TRUE),
                  median=round(median(Intensity,na.rm=TRUE),2),mean=round(mean(Intensity,na.rm=TRUE),2),
                  SD=round(sd(Intensity,na.rm=TRUE),2),n_total=length(Intensity),
                  n_missing=sum(is.na(Intensity)),
                  pct_missing=round(sum(is.na(Intensity))/length(Intensity),3),
                  n_values=sum(!is.na(Intensity)))
    } else {
      summary_data <- df_filtered() %>% group_by(Samples) %>% summarise(Abundance=sum(Intensity,na.rm=TRUE))
    }
    datatable(summary_data)
  })

  df_wide_with_color <- reactive({
    req(input$protein_col)
    prot <- input$protein_col
    df_wide <- df_long() %>%
      group_by(Samples, !!sym(prot)) %>% slice(1) %>% ungroup() %>%
      pivot_wider(names_from = !!sym(prot), values_from = Intensity)

    # Detection-rate filter + feature-mean fill. The previous version used
    # select_if(~!any(is.na(.))), which discards any feature with a single
    # missing value — in single-cell data that removes nearly everything.
    min_frac <- (.num_pct(input$pca_min_detect, 70)) / 100
    val  <- df_wide %>% select(-Samples)
    val  <- val[, vapply(val, is.numeric, logical(1)), drop = FALSE]
    if (!ncol(val)) {
      showNotification("No numeric feature columns available for dimensionality reduction.",
                       type = "error", duration = 12)
      req(FALSE)
    }
    keep <- vapply(val, function(x) mean(!is.na(x)) >= min_frac, logical(1))
    if (!any(keep)) {
      best <- round(100 * max(vapply(val, function(x) mean(!is.na(x)), numeric(1))))
      showNotification(paste0(
        "No feature is quantified in at least ", round(min_frac * 100), "% of cells ",
        "(best is ", best, "%). Lower the detection threshold on this tab."),
        type = "error", duration = 12)
      req(FALSE)
    }
    val <- val[, which(keep), drop = FALSE]
    val[] <- lapply(val, function(x) {
      m <- mean(x, na.rm = TRUE)
      if (!is.finite(m)) m <- 0
      x[is.na(x)] <- m
      x
    })
    df_wide <- dplyr::bind_cols(df_wide["Samples"], val)

    if (input$log2_choice_pca == "log2")
      df_wide <- df_wide %>% mutate(across(-Samples, ~log2(pmax(as.numeric(.), 0) + 1)))
    df_wide %>%
      mutate(Group = sapply(Samples, function(s) get_sample_type(s, input$num_conditions, input)),
             UniqueID = row_number())
  }) |> bindEvent(input$submit, ignoreNULL=FALSE, ignoreInit=FALSE)

  subpop_labels <- reactiveVal(data.frame(Samples=character(),Subpopulation=character()))

  apply_subpop_colors <- function(plot_data) {
    labels <- subpop_labels()
    if (nrow(labels)>0) {
      plot_data <- plot_data %>% left_join(labels,by="Samples") %>%
        mutate(ColorBy=ifelse(is.na(Subpopulation),Group,Subpopulation))
      list(data=plot_data,title="Subpopulation")
    } else { plot_data$ColorBy <- plot_data$Group; list(data=plot_data,title="Group") }
  }

  assign_labels <- function(samples,label) {
    new_labels <- data.frame(Samples=samples,Subpopulation=label,stringsAsFactors=FALSE)
    updated <- subpop_labels() %>% filter(!Samples %in% new_labels$Samples) %>% bind_rows(new_labels)
    subpop_labels(updated)
    showNotification(paste0(length(samples)," cell(s) labeled as '",label,"'"),type="message",duration=3)
  }

  observeEvent(input$assign_label,     { req(input$subpop_label);     sd<-event_data("plotly_selected",source="pcaPlot"); req(sd); assign_labels(sd$customdata,input$subpop_label) })
  observeEvent(input$assign_label_bar, { req(input$subpop_label_bar); sd<-event_data("plotly_selected",source="barPlot"); req(sd); assign_labels(sd$customdata,input$subpop_label_bar) })
  observeEvent(input$clear_labels,     { subpop_labels(data.frame(Samples=character(),Subpopulation=character())); showNotification("All subpopulation labels cleared.",type="warning",duration=3) })
  observeEvent(input$clear_labels_bar, { subpop_labels(data.frame(Samples=character(),Subpopulation=character())); showNotification("All subpopulation labels cleared.",type="warning",duration=3) })

  all_groups <- reactive({ unique(c(unique(na.omit(condition_names())),unique(na.omit(subpop_labels()$Subpopulation)))) })
  observe({
    grps <- all_groups()
    updateSelectInput(session,"volcano_group_a",choices=grps,selected=grps[1])
    updateSelectInput(session,"volcano_group_b",choices=grps,selected=grps[min(2,length(grps))])
  })

  # TRUE when the active tab-1.1 normalization leaves Intensity on a LOG scale.
  # Only "Seurat Cell Size" does: it returns log1p(relative abundance x 1e4).
  # Every other option (median, median per group, TIC, reference protein) stays
  # on a linear intensity scale.
  .v1_log_norm <- reactive({
    identical(input$normalization_method %||% "none", "seurat")
  })

  volcano_data <- reactive({
    req(input$volcano_group_a, input$volcano_group_b)
    req(input$volcano_group_a != input$volcano_group_b)
    grp_a <- input$volcano_group_a
    grp_b <- input$volcano_group_b

    # Build sample → FinalGroup mapping using df_filtered_with_color
    # which already has Group assigned correctly via get_sample_type
    labels <- subpop_labels()
    fc     <- df_filtered_with_color() %>%
      select(Samples, Group) %>% distinct() %>%
      left_join(labels, by="Samples") %>%
      mutate(FinalGroup=ifelse(!is.na(Subpopulation), Subpopulation, Group))

    samples_a <- fc %>% filter(FinalGroup == grp_a) %>% pull(Samples)
    samples_b <- fc %>% filter(FinalGroup == grp_b) %>% pull(Samples)

    if (length(samples_a) < 2)
      { showNotification(paste0("Group '",grp_a,"' has fewer than 2 samples."),type="error",duration=8); req(FALSE) }
    if (length(samples_b) < 2)
      { showNotification(paste0("Group '",grp_b,"' has fewer than 2 samples."),type="error",duration=8); req(FALSE) }

    long <- df_long(); protein_col <- input$protein_col
    is_log <- .v1_log_norm()

    result <- long %>%
      filter(Samples %in% c(samples_a, samples_b)) %>%
      mutate(FinalGroup=ifelse(Samples %in% samples_a, grp_a, grp_b),
             # Linear-scale copy used for the FOLD CHANGE ONLY.
             #
             # log2((mean_a + 1) / (mean_b + 1)) assumes linear intensity. Under
             # "Seurat Cell Size" the Intensity column is already log1p(...), so
             # that expression returned log2 of a ratio of LOGS — not a fold
             # change — and the "+ 1" pseudocount, negligible against raw
             # intensities of 1e4–1e8, badly distorted log1p values in the
             # 0–10 range. expm1() inverts log1p exactly, so the fold change
             # now means the same thing on every normalization route.
             #
             # This mirrors how Seurat itself computes avg_log2FC on LogNormalize
             # data: un-log with expm1, take the arithmetic mean, then log2.
             #
             # The p-value is untouched: Wilcoxon is rank-based and log1p is
             # monotonic, so ranks (and therefore p) are identical either way.
             IntensityLin = if (is_log) expm1(Intensity) else Intensity) %>%
      group_by(!!sym(protein_col)) %>%
      summarise(
        # Group means on the ACTIVE scale, for reference in the exported table.
        mean_a  = mean(Intensity[FinalGroup==grp_a], na.rm=TRUE),
        mean_b  = mean(Intensity[FinalGroup==grp_b], na.rm=TRUE),
        n_a     = sum(Intensity[FinalGroup==grp_a] > 0, na.rm=TRUE),
        n_b     = sum(Intensity[FinalGroup==grp_b] > 0, na.rm=TRUE),
        # Fold change always computed on the linear scale.
        lin_a   = mean(IntensityLin[FinalGroup==grp_a], na.rm=TRUE),
        lin_b   = mean(IntensityLin[FinalGroup==grp_b], na.rm=TRUE),
        log2FC  = log2((lin_a + 1) / (lin_b + 1)),
        p_value = tryCatch(
          wilcox.test(na.omit(Intensity[FinalGroup==grp_a]),
                      na.omit(Intensity[FinalGroup==grp_b]),
                      exact=FALSE)$p.value,
          error=function(e) NA_real_),
        .groups="drop"
      )

    n_total  <- nrow(result)
    n_tested <- sum(!is.na(result$p_value))
    if (n_total - n_tested > 0)
      showNotification(paste0(n_tested, " / ", n_total, " proteins tested. ",
                               n_total - n_tested, " dropped (identical values in both groups)."),
                       type="message", duration=8)

    result %>%
      filter(!is.na(p_value)) %>%
      mutate(
        p_adj       = p.adjust(p_value, method="BH"),
        neg_log10_p = -log10(p_value),
        Significant = abs(log2FC) >= input$volcano_fc & p_value <= input$volcano_pval,
        Direction   = case_when(
          Significant & log2FC > 0 ~ paste0("Up in ", grp_a),
          Significant & log2FC < 0 ~ paste0("Up in ", grp_b),
          TRUE                     ~ "Not significant"
        )
      )
  }) |> bindEvent(input$run_volcano)

  # Which points get a gene label. Returns the rows to label, or an empty frame.
  #
  #   pval  the classic volcano choice: strongest evidence, regardless of effect
  #         size, so it favours abundant well-measured proteins
  #   fc    largest |log2FC|, which at the extremes is dominated by low-coverage
  #         features with wide error
  #   both  rank by distance from the origin in (log2FC, -log10 p) space after
  #         scaling each axis to unit range, so neither axis dominates purely
  #         because of its units. This is the "outermost points" option.
  .v1_volcano_labels <- function(vdf, protein_col) {
    mode   <- input$volcano_label_mode %||% "none"
    n      <- max(0, min(200, as.integer(.num(input$volcano_label_n, 10))))
    picked <- input$volcano_pick
    if (!nrow(vdf)) return(vdf[0, , drop=FALSE])
    # Hand-picked rows bypass the mode / N / significance filters entirely,
    # matching the Markers volcanoes.
    man <- if (length(picked))
             vdf[as.character(vdf[[protein_col]]) %in% as.character(picked), , drop=FALSE]
           else vdf[0, , drop=FALSE]
    if (identical(mode, "none") || n == 0) return(man)
    d <- vdf
    # which() rather than a bare logical, so an NA in Significant cannot pull in
    # a row of NAs the way logical indexing would.
    if (isTRUE(input$volcano_label_sig_only) && "Significant" %in% names(d))
      d <- d[which(d$Significant %in% TRUE), , drop=FALSE]
    d <- d[is.finite(d$log2FC) & is.finite(d$neg_log10_p), , drop=FALSE]
    # Return the picks, not the empty candidate set: nothing clearing the
    # significance filter must not silently drop hand-picked labels too.
    if (!nrow(d)) return(man)
    ord <- switch(mode,
      "pval" = order(-d$neg_log10_p),
      "fc"   = order(-abs(d$log2FC)),
      "both" = {
        # Unit-range scale each axis before taking the radius, or the axis with
        # the larger numeric spread decides the ranking on its own.
        rx <- diff(range(d$log2FC));      if (!is.finite(rx) || rx == 0) rx <- 1
        ry <- diff(range(d$neg_log10_p)); if (!is.finite(ry) || ry == 0) ry <- 1
        order(-sqrt((abs(d$log2FC)/rx)^2 + (d$neg_log10_p/ry)^2))
      },
      order(-d$neg_log10_p))
    auto <- d[head(ord, n), , drop=FALSE]
    if (!nrow(man)) return(auto)
    out <- rbind(man, auto)
    out[!duplicated(as.character(out[[protein_col]])), , drop=FALSE]
  }

  # Static volcano for the PDF. Same data, limits and labels as the panel; the
  # plotly-only `text` aesthetic is dropped and ggrepel is used for the labels.
  .v1_build_volcano <- function(fs = 14) {
    vdf <- tryCatch(volcano_data(), error=function(e) NULL)
    if (is.null(vdf) || !nrow(vdf))
      stop("No volcano results yet. Pick two groups and click 'Run Volcano'.", call.=FALSE)
    protein_col <- input$protein_col
    color_vals <- c("grey70","#E74C3C","#2E86C1")
    names(color_vals) <- c("Not significant",
                           paste0("Up in ",input$volcano_group_a),
                           paste0("Up in ",input$volcano_group_b))
    lab <- .v1_volcano_labels(vdf, protein_col)
    p <- ggplot(vdf, aes(x=log2FC, y=neg_log10_p)) +
      geom_point(aes(fill=Direction), shape=21, colour="black", stroke=0.25,
                 size=.num(input$volcano_pdf_pt, 2), alpha=0.75) +
      scale_fill_manual(values=color_vals) +
      geom_vline(xintercept=c(-input$volcano_fc,input$volcano_fc),linetype="dashed",color="grey40") +
      geom_hline(yintercept=-log10(input$volcano_pval),linetype="dashed",color="grey40") +
      { .v1_volcano_xlim() } +
      theme_classic(base_size=fs) +
      labs(title=paste0("Volcano: ",input$volcano_group_a," vs ",input$volcano_group_b),
           subtitle=.v1_volcano_subtitle(),
           x=paste0("log2 FC (",input$volcano_group_a," / ",input$volcano_group_b,")"),
           y="-log10(p-value)", fill="")
    p <- p + .vol_repel(lab, "log2FC", "neg_log10_p", protein_col, fs)
    p
  }

  # coord_cartesian (not scale_x_continuous) so clipping the view never drops
  # rows: the dashed FC lines and the point set stay intact when zoomed in.
  .v1_volcano_xlim <- function() {
    lo <- .num(input$volcano_xmin, NA_real_)
    hi <- .num(input$volcano_xmax, NA_real_)
    if (!is.finite(lo) && !is.finite(hi)) return(NULL)
    if (is.finite(lo) && is.finite(hi) && lo >= hi) return(NULL)
    ggplot2::coord_cartesian(xlim=c(if (is.finite(lo)) lo else NA,
                                    if (is.finite(hi)) hi else NA))
  }

  .v1_volcano_subtitle <- function() {
    if (.v1_log_norm())
      "Seurat Cell Size normalization \u2014 fold change computed on expm1() back-transformed values"
    else NULL
  }

  # Tab 1.1 picker: driven by the volcano result, whose feature-id column is
  # whichever column the user nominated as the protein ID.
  observe({
    vdf <- tryCatch(volcano_data(), error=function(e) NULL)
    pc  <- input$protein_col
    ch  <- if (is.null(vdf) || !nrow(vdf) || is.null(pc) || !pc %in% names(vdf))
             character(0)
           else sort(unique(as.character(vdf[[pc]])))
    updateSelectizeInput(session, "volcano_pick", choices=ch,
                         selected=intersect(input$volcano_pick, ch), server=TRUE)
  })

  output$volcano_plot <- renderPlotly({
    req(volcano_data()); vdf <- volcano_data(); protein_col <- input$protein_col
    color_vals <- c("grey70","#E74C3C","#2E86C1")
    names(color_vals) <- c("Not significant",paste0("Up in ",input$volcano_group_a),paste0("Up in ",input$volcano_group_b))
    lab <- .v1_volcano_labels(vdf, protein_col)
    p <- ggplot(vdf,aes(x=log2FC,y=neg_log10_p,
                        text=paste0("Protein: ",!!sym(protein_col),"<br>log2FC: ",round(log2FC,3),"<br>p-value: ",signif(p_value,3))))+
      geom_point(aes(fill=Direction), shape=21, colour="black", stroke=0.25,
                 size=2, alpha=0.75)+
      scale_fill_manual(values=color_vals)+
      geom_vline(xintercept=c(-input$volcano_fc,input$volcano_fc),linetype="dashed",color="grey40")+
      geom_hline(yintercept=-log10(input$volcano_pval),linetype="dashed",color="grey40")+
      { .v1_volcano_xlim() }+
      theme_classic(base_size=14)+
      labs(title=paste0("Volcano: ",input$volcano_group_a," vs ",input$volcano_group_b),
           subtitle=.v1_volcano_subtitle(),
           x=paste0("log2 FC (",input$volcano_group_a," / ",input$volcano_group_b,")"),
           y="-log10(p-value)",fill="")
    .vol_annotate(.vol_outline(ggplotly(p, tooltip="text")),
                  lab, "log2FC", "neg_log10_p", protein_col)
  })

  output$download_volcano_pdf <- .v1_pdf_handler(.v1_build_volcano, "volcano", 14)
  output$download_volcano_ui <- renderUI({ req(volcano_data()); downloadButton("download_volcano_csv","⬇ Download Volcano Results") })
  output$download_volcano_csv <- downloadHandler(
    filename=function() paste0("volcano_",input$volcano_group_a,"_vs_",input$volcano_group_b,".csv"),
    content=function(file) write_csv(volcano_data(),file)
  )

  selected_pca_plot_points <- reactiveVal(data.frame())

  pca_data <- reactive({
    wide       <- df_wide_with_color()
    df_for_pca <- wide %>% select(-Group, -UniqueID)
    mat <- as.matrix(df_for_pca[, -1, drop = FALSE])
    storage.mode(mat) <- "numeric"

    # NA-safe, non-constant feature selection. var() on a vector containing NA
    # returns NA, and mat[, NA] yields NA columns that break prcomp/umap/Rtsne.
    keep <- apply(mat, 2, function(x) {
      v <- suppressWarnings(stats::var(x, na.rm = TRUE))
      is.finite(v) && v > 0
    })
    mat <- mat[, which(keep), drop = FALSE]
    if (anyNA(mat))
      mat[is.na(mat)] <- 0

    if (nrow(mat) < 3 || ncol(mat) < 2) {
      showNotification(paste0(
        "Not enough variable features for dimensionality reduction (", nrow(mat),
        " cells x ", ncol(mat), " features). Lower the detection threshold."),
        type = "error", duration = 12)
      req(FALSE)
    }

    method <- input$dimred_method
    if (method == "PCA") {
      res <- prcomp(mat, center = TRUE, scale. = TRUE)
      if (ncol(res$x) < 2) {
        showNotification("PCA returned fewer than 2 components.", type = "error", duration = 10)
        req(FALSE)
      }
      coords <- res$x[, 1:2]; axis_labels <- c("PC1", "PC2")
    } else if (method == "UMAP") {
      cfg <- umap.defaults
      cfg$n_neighbors <- max(2, min(.num_pct(input$umap_neighbors, 15), nrow(mat) - 1))
      res <- umap(mat, config = cfg); coords <- res$layout[, 1:2]
      axis_labels <- c("UMAP1", "UMAP2")
    } else {
      perp <- floor((nrow(mat) - 1) / 3)
      perp <- max(1, min(.num_pct(input$tsne_perplexity, 30), perp))
      res  <- Rtsne(mat, dims = 2, perplexity = perp,
                    check_duplicates = FALSE, normalize = TRUE)
      coords <- res$Y; axis_labels <- c("tSNE1", "tSNE2")
    }
    data.frame(Samples = df_for_pca$Samples, Dim1 = coords[, 1], Dim2 = coords[, 2],
               Group = wide$Group, UniqueID = wide$UniqueID,
               axis1_lab = axis_labels[1], axis2_lab = axis_labels[2])
  })

  # Static embedding plot, shared by the on-screen plotly version and the PDF.
  # customdata= is deliberately omitted here: it exists only to carry sample IDs
  # into plotly's selection events and is not a real ggplot aesthetic, so it
  # warns on a plain device.
  .v1_build_dimred <- function(fs = 14) {
    pd <- tryCatch(pca_data(), error = function(e) NULL)
    if (is.null(pd) || !nrow(pd))
      stop("No embedding to draw yet. Click 'Unleash the Analysis', and check the\n",
           "detection-rate slider is not filtering out every feature.", call. = FALSE)
    colored <- apply_subpop_colors(pd)
    ggplot(colored$data, aes(x=Dim1, y=Dim2, color=ColorBy)) +
      geom_point(alpha=0.7, size=.num(input$dimred_pdf_pt, 3)) +
      theme_classic(base_size=fs) +
      labs(title=paste(input$dimred_method,"Plot"), color=colored$title,
           x=pd$axis1_lab[1], y=pd$axis2_lab[1])
  }

