  # Static box plot, shared by the on-screen output and the PDF export so the
  # exported figure carries the same ordering, colors and significance brackets.
  .v1_build_box <- function(fs = 14) {
    plot_data <- if(input$log2_choice_box=="log2") df_filtered_with_color()%>%mutate(Intensity=log2(Intensity+1)) else df_filtered_with_color()
    colored   <- apply_subpop_colors(plot_data)

    # Apply user-defined x-axis order based on Group (condition names)
    ord <- input$box_order
    if (!is.null(ord) && length(ord) >= 1) {
      all_grps <- unique(na.omit(colored$data$Group))
      full_ord <- c(ord, setdiff(all_grps, ord))
      colored$data$Group   <- factor(colored$data$Group,   levels=full_ord)
      colored$data$ColorBy <- factor(colored$data$ColorBy,
                                     levels=levels(colored$data$Group))
    }

    colored$data <- colored$data %>% filter(!is.na(Intensity), !is.na(Group))
    if (nrow(colored$data) == 0)
      stop("No non-missing values left to plot for this feature.", call. = FALSE)
    # Only compare groups with >= 2 observations; wilcox.test errors otherwise
    viable <- colored$data %>% count(Group) %>% filter(n >= 2) %>%
      pull(Group) %>% as.character()
    current_groups <- intersect(levels(factor(colored$data$Group)), viable)
    my_comparisons <- if(length(current_groups)>=2) combn(current_groups,2,simplify=FALSE) else list()

    box_plot <- ggplot(colored$data, aes(x=Group, y=Intensity, fill=Group)) +
      geom_boxplot(width=0.5) + geom_jitter(width=0.2) +
      theme_classic(base_size=fs) +
      labs(x="Group", fill=colored$title,
           y=paste("Intensity", unique(df_filtered()$protein_id)))
    if(length(my_comparisons)>0)
      box_plot <- box_plot + ggpubr::stat_compare_means(comparisons=my_comparisons, method="wilcox.test")
    box_plot
  }

  output$box_plot <- renderPlot({
    p <- tryCatch(.v1_build_box(14), error = function(e) e)
    if (inherits(p, "error")) {
      showNotification(conditionMessage(p), type = "warning", duration = 8)
      req(FALSE)
    }
    print(p)
  })

