  output$violin_plot <- renderPlotly({
    req(df_filtered_with_color())
    plot_data <- if(input$log2_choice_violin=="log2") df_filtered_with_color()%>%mutate(Intensity=log2(Intensity+1)) else df_filtered_with_color()
    plot_data <- plot_data %>% filter(!is.na(Intensity), !is.na(Group))
    if (nrow(plot_data) == 0) {
      showNotification("No non-missing values left to plot for this feature.",
                       type = "warning", duration = 8)
      req(FALSE)
    }
    mean_sdl <- function(x,mult=1) {
      x <- x[is.finite(x)]
      if (!length(x)) return(data.frame(y=NA_real_,ymin=NA_real_,ymax=NA_real_))
      m <- mean(x); s <- if (length(x) > 1) sd(x) else 0
      data.frame(y=m,ymin=m-s*mult,ymax=m+s*mult)
    }
    p_violin <- ggplot(plot_data,aes(x=Group,y=Intensity,fill=Group))+geom_violin()+
      stat_summary(fun.data=mean_sdl,fun.args=list(mult=1),geom="pointrange",color="black",shape=18,size=0.75,position=position_dodge(width=0.9))+
      labs(title="Violin Plot",x="Conditions",y=ifelse(input$log2_choice_violin=="log2","Log2 Intensity","Intensity"))+
      theme_minimal()+theme(text=element_text(size=14),axis.title=element_text(size=14),axis.text=element_text(size=14),plot.title=element_text(size=14,hjust=0.5))
    ggplotly(p_violin)
  })

  # ══════════════════════════════════════════════════════════════════════════
  #  SEURAT ANALYSIS SUITE SERVER  (all reactive values and outputs prefixed s_)
  # ══════════════════════════════════════════════════════════════════════════
  s <- reactiveValues(
    prt_int       = NULL,
    prt_int_orig      = NULL,   # saved before reference normalization
    refnorm_prot_used = NULL,
    js_result         = NULL,   # Jackstraw result
    sweep_plots       = NULL,   # UMAP sweep
    sil_grid          = NULL,   # silhouette grid
    clustree_seu      = NULL,   # clustree object
    clustree_res       = NULL,  # resolutions the stored tree was built from
    sil_result        = NULL,   # silhouette scores at current clustering
    i_sil_grid        = NULL,   # integration: silhouette grid
    i_clustree_seu    = NULL,   # integration: clustree object
    i_clustree_res     = NULL,  # integration: resolutions behind the stored tree
    i_sil_result      = NULL,   # integration: silhouette scores
    pw_result         = NULL,   # pathway analysis result table
    pw_meta           = NULL,   # pathway run metadata (method, db, label)
    ann_ref           = NULL,   # CellMarker/other reference: list(cell_type -> genes)
    ann_ref_meta      = NULL,   # reference metadata (source, organism, tissue, n sets)
    ann_fisher        = NULL,   # Fisher enrichment results (long)
    ann_scores        = NULL,   # AddModuleScore activity matrix (cluster x cell type)
    traj_sds          = NULL,   # slingshot result (SlingshotDataSet)
    traj_pt           = NULL,   # per-cell pseudotime matrix (cells x lineages)
    traj_meta         = NULL,   # trajectory run metadata (reduction, cluster col, start)
    meta          = NULL,
    prt_map       = NULL,
    seu           = NULL,
    seu_int       = NULL,
    markers       = NULL,
    int_markers   = NULL,
    int_data_snapshot = NULL,   # NA-aware data layer held across the RPCA anchor prep
    last_mk_mode  = NULL,
    last_mk_grp   = NULL,
    last_mk_comp  = NULL,
    last_i_mk_comp = NULL,
    ev_mat        = NULL,
    ev_pc_weights = NULL,   # per-PC eigenvalue share of total variance (PVCA weights)
    ev_feature_mat = NULL,  # per-feature R² per covariate (BatchQC-style, non-PCA)
    ev_feature_cov_order = NULL,  # covariate order for the per-feature boxplot
    palette       = list(),
    level_order   = list(),   # covariate → ordered character vector of levels
    log           = character(),
    # Integration step intermediates
    int_feats     = NULL,   # Step 2: selected features
    int_obj_list  = NULL,   # Step 3: PrepSCTIntegration result
    int_anchors   = NULL,   # Step 4: FindIntegrationAnchors result
    # Step status flags
    cc_scored     = FALSE,
    cc_gene_counts = NULL,   # S/G2M phase genes found in the data
    cc_diff_done  = FALSE,
    int_step1_done = FALSE,   # LogNorm per-group (LogNorm path only)
    int_step2_done = FALSE,
    int_step3_done = FALSE,
    int_step4_done = FALSE,
    int_step5_done = FALSE,
    int_step6_done = FALSE,
    int_step7_done = FALSE,
    int_step8_done = FALSE,
    int_step9_done = FALSE
  )

  s_log <- function(msg) s$log <- c(s$log, paste0(format(Sys.time(),"%H:%M:%S"), "  ", msg))

  # ── The NA-aware normalization family ───────────────────────────────────────
  # Methods that read s$prt_int_raw, keep missing values as NA, regress with
  # regress_out_na(), and reduce with pcaMethods rather than Seurat::RunPCA.
  # Everything downstream branches on membership of this vector, so a new method
  # joins the family by being added here rather than at ~26 separate call sites.
  .NA_AWARE <- c("vsn", "scpmed", "log2")

  # ── Selector choice sanitiser ────────────────────────────────────────────────
  # WHY THIS EXISTS: shiny normalizes a `choices` vector by assigning names to the
  # unnamed entries — roughly `names(ch)[nms == ""] <- as.character(ch)[nms == ""]`.
  # If any entry is NA, that comparison yields NA, the index contains NA, and the
  # widget fails to render with
  #     "Error: NAs are not allowed in subscripted assignments"
  # shown in place of the control. The control then never appears, so its input is
  # NULL and the panel it feeds silently stays blank — the failure looks like a
  # plotting problem when it is a naming problem.
  #
  # An NA or empty feature name can arrive from an ID map with missing entries, a
  # feature-name column with blank cells, or a transform that dropped rows and
  # left the row names ragged. Rather than tracking down every producer, every
  # selector built from feature or metadata names is filtered here, and the drop
  # is reported once so the upstream cause is still visible.
  # Messages are de-duplicated through this environment: selectors re-render often
  # and an unconditional s_log() here grew the activity log without bound, which
  # then invalidated the log output on every render and made selector-heavy tabs
  # feel slow.
  .opt_seen <- new.env(parent = emptyenv())
  .opt_clean <- function(x, what = "options") {
    if (is.null(x)) return(character(0))
    x <- as.character(x)
    bad <- is.na(x) | !nzchar(trimws(x))
    if (any(bad)) {
      n   <- sum(bad)
      key <- paste0(what, ":", n)
      if (!exists(key, envir = .opt_seen, inherits = FALSE)) {
        assign(key, TRUE, envir = .opt_seen)
        s_log(paste0("Selector: dropped ", n, " NA/empty ", what,
                     " from a choice list \u2014 check the feature ID column in \u2460."))
      }
    }
    unique(x[!bad])
  }

  # ── Features that actually carry values (cached) ─────────────────────────────
  # Used by the feature selectors. Being a reactive, it is computed once per
  # change of s$seu rather than once per re-render of every selector that needs
  # it. It also avoids densifying a sparse layer: sparse storage has no NA slot,
  # so on the count-based routes every feature has values by construction and the
  # row scan can be skipped entirely.
  s_feats_with_values <- reactive({
    req(s$seu)
    all_f <- .opt_clean(rownames(s$seu), "features")
    assay <- if (input$s_assay %in% names(s$seu@assays)) input$s_assay
             else SeuratObject::DefaultAssay(s$seu)
    lay <- tryCatch(SeuratObject::LayerData(s$seu@assays[[assay]], layer="data"),
                    error=function(e) NULL)
    if (is.null(lay)) return(all_f)
    # Sparse: no NAs possible, so nothing to filter.
    if (methods::is(lay, "sparseMatrix")) return(all_f)
    keep <- rownames(lay)[rowSums(!is.na(lay)) > 0]
    if (length(keep) < 3) return(all_f)      # degenerate: do not hide everything
    n_hidden <- length(setdiff(all_f, keep))
    list(features = intersect(all_f, keep), hidden = n_hidden)
  })

  # Small helper so callers get a plain vector either way.
  .feat_choices <- function() {
    z <- s_feats_with_values()
    if (is.list(z)) z$features else z
  }

  # ── Global identity selector ───────────────────────────────────────────────
  output$s_global_ident_ui <- renderUI({
    req(s$seu)
    all_cols <- names(s$seu@meta.data)
    # Also offer metadata from the integrated object (e.g. its seurat_clusters,
    # which live on s$seu_int, not the main object) so integration-derived
    # clusters are selectable here as well. Tag integration-only columns.
    int_only <- character(0)
    if (!is.null(s$seu_int)) {
      int_cols <- names(s$seu_int@meta.data)
      int_only <- setdiff(int_cols, all_cols)
    }
    # Guess a good default: prefer seurat_clusters, then sex/condition
    combined <- c(all_cols, int_only)
    default_ident <- if ("seurat_clusters" %in% combined) "seurat_clusters"
                     else if (any(grepl("sex|condition|group", tolower(combined)))) {
                       combined[grep("sex|condition|group", tolower(combined))[1]]
                     } else combined[1]
    choices <- all_cols
    if (length(int_only))
      choices <- c(stats::setNames(all_cols, all_cols),
                   stats::setNames(int_only, paste0(int_only, "  (integrated)")))
    selectInput("s_global_ident", "Set Idents() to:",
                choices = choices, selected = default_ident)
  })

  output$s_global_ident_status <- renderUI({
    req(s$seu)
    if (is.null(input$s_global_ident)) return(NULL)
    id <- input$s_global_ident
    # the selected ident may live on the main object OR only on the integrated
    # object (e.g. integration-derived seurat_clusters) — check both.
    if (id %in% names(s$seu@meta.data)) {
      n_levels <- length(unique(s$seu@meta.data[[id]]))
      tags$p(paste0("✓ ", n_levels, " identity levels"),
             style = "color:#27AE60; font-size:12px; margin-top:22px;")
    } else if (!is.null(s$seu_int) && id %in% names(s$seu_int@meta.data)) {
      n_levels <- length(unique(s$seu_int@meta.data[[id]]))
      tags$p(paste0("✓ ", n_levels, " levels (integrated object)"),
             style = "color:#27AE60; font-size:12px; margin-top:22px;")
    } else NULL
  })

  # Apply global ident whenever the selector changes — returns updated seu
  # Apply any stored level ordering (from the palette/order UI) to a Seurat
  # object's metadata as FACTOR LEVELS. This is the single point where order is
  # enforced: because palettes are name-keyed (level → color), setting factor
  # levels changes only the plot/axis order — each level keeps its own color and
  # the value→group mapping is preserved. Levels present in the data but absent
  # from the stored order are appended (alphabetically) so nothing is dropped.
  .apply_level_order <- function(seu) {
    lo <- s$level_order
    if (is.null(lo) || !length(lo)) return(seu)
    for (cov in names(lo)) {
      if (!cov %in% names(seu@meta.data)) next
      want <- lo[[cov]]
      present <- unique(as.character(seu@meta.data[[cov]]))
      lv <- c(want[want %in% present], sort(setdiff(present, want)))
      if (length(lv) >= 1)
        seu@meta.data[[cov]] <- factor(as.character(seu@meta.data[[cov]]), levels=lv)
    }
    seu
  }

  s_seu_with_ident <- reactive({
    req(s$seu)
    seu <- .apply_level_order(s$seu)
    if (!is.null(input$s_global_ident) &&
        input$s_global_ident %in% names(seu@meta.data)) {
      Seurat::Idents(seu) <- input$s_global_ident
      # If the ident column has a stored order, carry it onto Idents so the axis
      # and legend follow the chosen order (and thus the palette by name).
      if (!is.null(s$level_order[[input$s_global_ident]])) {
        lv <- levels(seu@meta.data[[input$s_global_ident]])
        if (!is.null(lv)) Seurat::Idents(seu) <- factor(Seurat::Idents(seu), levels=lv)
      }
    }
    seu
  })

  # ── helpers ────────────────────────────────────────────────────────────────
  s_cat_cols  <- reactive({ roles <- s_cov_roles(); names(roles)[unlist(roles)=="categorical"] })
  s_tech_cols <- reactive({ roles <- s_cov_roles(); names(roles)[unlist(roles)=="technical"] })

  s_cov_roles <- reactive({
    req(s$meta)
    roles <- list()
    for (col in names(s$meta)) {
      v <- input[[paste0("s_cov_",col)]]
      roles[[col]] <- if (is.null(v)) "ignore" else v
    }
    roles
  })

  # ── QC helpers ─────────────────────────────────────────────────────────────

  output$s_qc_cond_col_ui <- renderUI({
    req(s$meta)
    # Offer categorical columns that are useful for splitting
    cols <- names(s$meta)
    cat_cols_qc <- cols[sapply(cols, function(c) {
      v <- s$meta[[c]]
      (is.character(v) || is.factor(v)) && length(unique(v[!is.na(v)])) <= 20
    })]
    if (!length(cat_cols_qc)) return(tags$p("No suitable condition columns found.",style="color:grey;font-size:12px;"))
    selectInput("s_qc_cond_col", "Split outlier detection by:",
                choices=cat_cols_qc,
                selected=if(any(grepl("sex|condition|group|lobe",tolower(cat_cols_qc))))
                  cat_cols_qc[grep("sex|condition|group|lobe",tolower(cat_cols_qc))[1]]
                else cat_cols_qc[1])
  })

  # condition-column picker for ④ conditional protein re-evaluation
  output$s_qc_prot_cond_col_ui <- renderUI({
    req(s$meta)
    cats <- names(s$meta)[vapply(s$meta, function(v)
      (is.factor(v) || is.character(v)) && length(unique(v[!is.na(v)])) >= 2 &&
      length(unique(v[!is.na(v)])) <= 50, logical(1))]
    if (!length(cats)) return(tags$p("No suitable condition columns found.",
                                     style="color:grey;font-size:12px;"))
    sel <- if (any(grepl("sex|condition|group|lobe", tolower(cats))))
             cats[grep("sex|condition|group|lobe", tolower(cats))[1]] else cats[1]
    selectInput("s_qc_prot_cond_col","Condition column:", choices=cats, selected=sel)
  })

  s_pass_cells <- reactive({
    req(s$prt_int); cells <- colnames(s$prt_int)

    # ① Min proteins per cell
    if (isTRUE(input$s_qc_cells)) {
      cnts  <- colSums(s$prt_int > 0)
      cells <- cells[cnts[cells] >= input$s_qc_min_prot]
    }

    # ② Abundance outlier removal — global or per-condition
    if (isTRUE(input$s_qc_outlier)) {
      ti <- log2(colSums(s$prt_int[, cells, drop=FALSE]) + 1)

      per_cond <- isTRUE(input$s_qc_outlier_per_cond) &&
                  !is.null(input$s_qc_cond_col) &&
                  input$s_qc_cond_col %in% names(s$meta) &&
                  all(cells %in% rownames(s$meta))

      if (per_cond) {
        # Apply ±SD cutoff within each condition group separately
        cond_vec <- s$meta[cells, input$s_qc_cond_col]
        keep <- logical(length(cells))
        names(keep) <- cells
        for (grp in unique(cond_vec[!is.na(cond_vec)])) {
          grp_cells <- cells[!is.na(cond_vec) & cond_vec == grp]
          ti_grp    <- ti[grp_cells]
          mn <- mean(ti_grp, na.rm=TRUE); sv <- sd(ti_grp, na.rm=TRUE)
          keep[grp_cells] <- ti_grp >= mn - input$s_qc_sd * sv &
                             ti_grp <= mn + input$s_qc_sd * sv
        }
        # Cells in NA condition groups pass through unchanged
        na_cells <- cells[is.na(cond_vec)]
        keep[na_cells] <- TRUE
        cells <- cells[keep[cells]]
      } else {
        # Global outlier removal across all cells
        mn    <- mean(ti, na.rm=TRUE); sv <- sd(ti, na.rm=TRUE)
        cells <- cells[ti >= mn - input$s_qc_sd * sv &
                       ti <= mn + input$s_qc_sd * sv]
      }
    }
    cells
  })

  s_pass_prots <- reactive({
    req(s$prt_int); pc <- s_pass_cells(); tc <- length(pc)
    sub   <- s$prt_int[,pc,drop=FALSE]
    prots <- rownames(sub)
    if (isTRUE(input$s_qc_sparse))
      prots <- prots[rowSums(sub>0)/tc*100 >= input$s_qc_pct]
    # Always remove proteins with no detected values across passing cells,
    # regardless of sparsity filter setting — these break SCTransform and
    # are uninformative in all downstream steps.
    sub2  <- sub[prots, , drop=FALSE]
    prots <- prots[rowSums(!is.na(sub2) & sub2 > 0) > 0]

    # ④ Conditional re-evaluation (Seurat-style min.cells, per condition group).
    # After cell filtering, require each protein to be detected in >= min cells
    # within every group ("all") or at least one group ("any"). A protein absent
    # from an entire condition is dropped, avoiding all-NA-in-a-group features.
    if (isTRUE(input$s_qc_prot_cond) &&
        !is.null(input$s_qc_prot_cond_col) &&
        input$s_qc_prot_cond_col %in% names(s$meta) &&
        all(pc %in% rownames(s$meta))) {
      cond <- as.character(s$meta[pc, input$s_qc_prot_cond_col])
      grps <- unique(cond[!is.na(cond)])
      if (length(grps) >= 1) {
        minc <- max(1, as.integer(.num(input$s_qc_prot_min_cells, 1)))
        m    <- sub[prots, , drop=FALSE]
        # detected counts per protein within each group
        det_by_grp <- vapply(grps, function(g) {
          cg <- pc[!is.na(cond) & cond == g]
          if (!length(cg)) return(rep(0L, length(prots)))
          as.integer(rowSums(!is.na(m[, cg, drop=FALSE]) & m[, cg, drop=FALSE] > 0))
        }, integer(length(prots)))
        if (is.null(dim(det_by_grp))) det_by_grp <- matrix(det_by_grp, nrow=length(prots))
        pass_grp <- det_by_grp >= minc
        keep <- if ((input$s_qc_prot_cond_mode %||% "all") == "all")
                  rowSums(pass_grp) == ncol(pass_grp)   # detected in EVERY group
                else rowSums(pass_grp) >= 1              # detected in AT LEAST ONE group
        prots <- prots[keep]
      }
    }
    prots
  })

  s_mat_filt <- reactive({
    req(s$prt_int, s$meta)
    pc <- s_pass_prots()
    cc <- s_pass_cells()
    cc_aligned <- intersect(cc, rownames(s$meta))
    mat <- s$prt_int[pc, cc_aligned, drop=FALSE]

    # ── Optional: reference protein normalization (applied after filters) ────
    # Scope and per-cell usability come from s_refnorm_scope(), so the protein
    # list, the status text, the diagnostic plots and this operation all agree on
    # exactly which cells the reference can normalize.
    #
    # Behavior: cells with no usable reference value (0 or NA) CANNOT be
    # normalized. Leaving them undivided would put them on a different scale from
    # every other cell — they would read as extreme outliers and dominate PCA —
    # so they are DROPPED from the returned matrix. The loss is never silent: it
    # is reported in the ② status text, named in the before/after plot subtitle,
    # announced on Apply, and flagged per cell as `refnorm_applied` in
    # s_meta_filt(). Consumers must therefore align to colnames(s_mat_filt()),
    # which can be narrower than rownames(s_meta_filt()).
    if (isTRUE(input$s_refnorm_enable)) {
      sc <- tryCatch(s_refnorm_scope(), error=function(e) NULL)
      if (!is.null(sc) && isTRUE(sc$ref_ok) && sc$ref %in% rownames(mat)) {
        good <- sc$good[colnames(mat)]
        good[is.na(good)] <- FALSE
        ref_vec <- as.numeric(mat[sc$ref, ])
        if (any(good)) {
          mat_g <- sweep(mat[, good, drop=FALSE], 2, ref_vec[good], "/")
          sf <- switch(input$s_refnorm_scale %||% "median",
            "median" = median(ref_vec[good], na.rm=TRUE),
            "10000"  = 10000,
            "none"   = 1)
          mat <- mat_g * sf
        }
        # any(good) == FALSE: the reference was detected in no filtered cell.
        # Leave the matrix untouched rather than returning an empty one — ②
        # flags this state in red.
      }
    }

    # Re-enforce integer after any operations that may have converted to double
    # (subsetting, sweep, arithmetic all reset storage mode)
    if (!is.null(input$s_norm_method) && input$s_norm_method == "sct") {
      mat <- ceiling(mat)
      mat[is.na(mat) | is.nan(mat) | is.infinite(mat)] <- 0
      mat[mat < 0] <- 0
      storage.mode(mat) <- "integer"
    }

    mat
  })

  s_meta_filt <- reactive({
    req(s$meta); pc <- s_pass_cells()
    # Always subset to exactly the passing cells — never return full meta
    # when a filtered matrix will have fewer columns
    common <- intersect(pc, rownames(s$meta))
    if (length(common) < length(pc)) {
      # Some passing cells have no metadata row — use what we can align
      missing <- setdiff(pc, rownames(s$meta))
      message(paste0("s_meta_filt: ", length(missing),
                     " cells in filtered matrix have no metadata row — excluded"))
    }
    if (length(common) == 0) return(s$meta)   # fallback: no alignment possible
    out <- s$meta[common, , drop=FALSE]

    # ── Audit flag for reference protein normalization ─────────────────────────
    # s_mat_filt() DROPS cells with no usable reference value, so this frame can
    # be wider than the filtered matrix. `refnorm_applied` records which of the
    # QC-passing cells survived that step, making the loss visible whenever the
    # metadata is inspected or exported. Note that within the built Seurat object
    # every cell is TRUE by construction (the FALSE ones are gone), so this
    # column is for auditing — not for covariate testing in ③/④.
    if (isTRUE(input$s_refnorm_enable)) {
      sc <- tryCatch(s_refnorm_scope(), error=function(e) NULL)
      if (!is.null(sc) && isTRUE(sc$ref_ok)) {
        flag <- sc$good[rownames(out)]
        flag[is.na(flag)] <- FALSE
        out$refnorm_applied <- as.logical(flag)
      }
    }
    out
  })

  # ── ① Load Data ────────────────────────────────────────────────────────────
  load_rdata <- function(path) {
    env  <- new.env(parent=emptyenv()); load(path, envir=env)

    prt  <- if ("prt.int" %in% ls(env)) get("prt.int", envir=env) else stop("prt.int missing")
    meta <- if ("meta.samples" %in% ls(env)) get("meta.samples", envir=env) else stop("meta.samples missing")
    pmap <- if ("prt.map" %in% ls(env)) get("prt.map", envir=env) else NULL

    if (!is.matrix(prt)) prt <- as.matrix(prt)

    # >>> INTENSITY-NATIVE: untouched copy, NAs + floats intact, pre-coercion <<<
    prt_raw_intensity <- prt

    # ── Process matrix: ceiling → NA→0 → numeric storage ────────────────────
    # Always applied regardless of data source. Ceiling on integers is a no-op.
    # Storage must be numeric (double) — dgCMatrix @x requires double, not integer.
    prt <- ceiling(prt)
    prt[is.na(prt) | is.nan(prt) | is.infinite(prt)] <- 0
    prt[prt < 0] <- 0
    storage.mode(prt) <- "double"  # preserve floats — SCTransform path handles integer conversion

    n_before <- nrow(prt)

    # ── Gene name assignment ──────────────────────────────────────────────────
    # Only reassign if prt.map is available AND rownames look like accessions
    # (not already gene names). Skip if rownames are already gene-name style.
    #
    # PEPTIDE-LEVEL DATA: if features are peptides (many peptides per gene), do
    # NOT rename to Genes — that collapses distinct peptides onto shared gene
    # symbols (e.g. 221 PLEC peptides), which cannot be reversed and breaks the
    # raw-intensity alignment used by VSN/scp-median. Detect peptide data by a
    # peptide-level column in the map, or by rows greatly exceeding unique genes,
    # and keep the peptide rownames as feature names.
    is_peptide <- !is.null(pmap) &&
      (any(c("StrippedSequence","ModifiedSequence","PeptidePosition","PrecursorId") %in% names(pmap)) ||
       ("Genes" %in% names(pmap) && nrow(pmap) > 0 &&
        length(unique(pmap$Genes)) < 0.6 * nrow(pmap)))
    needs_gene_names <- !is.null(pmap) && "Genes" %in% names(pmap) &&
                        nrow(pmap) > 0 && length(unique(pmap$Genes)) > 1 &&
                        !is_peptide

    if (is_peptide)
      s_log(paste0("Peptide-level data detected (", nrow(prt), " features, ",
                   if("Genes" %in% names(pmap)) length(unique(pmap$Genes)) else NA,
                   " unique genes) — keeping peptide IDs as feature names ",
                   "(not collapsing to gene symbols)."))

    if (needs_gene_names) {
      if (nrow(pmap) == nrow(prt)) {
        genes <- pmap$Genes
        genes[is.na(genes) | genes == ""] <- rownames(prt)[is.na(genes) | genes == ""]
        dups <- duplicated(genes)
        if (any(dups)) genes[dups] <- paste0(genes[dups], "_dup")
        rownames(prt) <- genes
      } else {
        # Different row counts — use intersection of accession IDs
        shared <- intersect(rownames(prt), rownames(pmap))
        if (length(shared) > 0) {
          prt   <- prt[shared, , drop=FALSE]
          # keep raw copy row-synced with prt so VSN/scpmed align cleanly later
          if (exists("prt_raw_intensity"))
            prt_raw_intensity <- prt_raw_intensity[shared, , drop=FALSE]
          genes <- pmap[shared, "Genes"]
          genes[is.na(genes) | genes == ""] <- shared[is.na(genes) | genes == ""]
          dups  <- duplicated(genes); genes[dups] <- paste0(genes[dups], "_dup")
          rownames(prt) <- genes
        }
        # If no intersection (e.g. rownames are already gene names), leave as-is
      }
    }
    n_after <- nrow(prt)

    # ── Build coldata — set rownames from ID column ───────────────────────────
    coldata <- as.data.frame(meta)

    # Ensure rownames are set from ID column (handles merged datasets where
    # rbind may have reset rownames to 1,2,3...)
    if ("ID" %in% names(coldata)) {
      rownames(coldata) <- as.character(coldata[["ID"]])
    }

    # ── Align cell IDs between prt.int columns and coldata rownames ───────────
    if (!identical(rownames(coldata), colnames(prt))) {
      common <- intersect(rownames(coldata), colnames(prt))
      if (length(common) > 0) {
        prt     <- prt[, common, drop=FALSE]
        coldata <- coldata[common, , drop=FALSE]
        message(paste0("Cell ID alignment: ", length(common), " / ", ncol(prt),
                       " cells matched"))
      } else {
        # Last resort: try trimming whitespace from IDs
        rownames(coldata) <- trimws(rownames(coldata))
        colnames(prt)     <- trimws(colnames(prt))
        common <- intersect(rownames(coldata), colnames(prt))
        if (length(common) > 0) {
          prt     <- prt[, common, drop=FALSE]
          coldata <- coldata[common, , drop=FALSE]
        } else {
          stop(paste0("Cannot align cell IDs between prt.int (colnames: '",
                      paste(head(colnames(prt),3), collapse="','"), "...') and ",
                      "meta.samples (rownames: '",
                      paste(head(rownames(coldata),3), collapse="','"), "...'). ",
                      "Check that meta.samples ID column matches prt.int column names."))
        }
      }
    }

    mapping_note <- if (n_after < n_before)
      paste0(" (", n_before - n_after, " proteins dropped during gene mapping)")
    else ""

    list(prt=prt, meta=coldata, pmap=pmap, prt_raw=prt_raw_intensity,
         n_before=n_before, n_after=n_after, mapping_note=mapping_note)
  }

  finalize_load <- function(loaded) {
    prt  <- loaded$prt
    meta <- loaded$meta

    # Convert any factor columns to character (avoids issues with "none" levels
    # from merged datasets interfering with Seurat metadata handling)
    for (col in names(meta)) {
      if (is.factor(meta[[col]])) meta[[col]] <- as.character(meta[[col]])
    }

    # Add per-cell QC metrics
    cell_ids <- rownames(meta)
    shared   <- intersect(cell_ids, colnames(prt))
    if (length(shared) > 0) {
      meta[shared, "nFeature_raw"]         <- as.numeric(colSums(prt[, shared, drop=FALSE] > 0))
      meta[shared, "log2_total_intensity"] <- round(as.numeric(log2(colSums(prt[, shared, drop=FALSE]) + 1)), 3)

      # ── log2_median_intensity — a third, complementary depth proxy ───────────
      # nFeature counts detection events; total intensity sums them and is
      # therefore dominated by a handful of abundant features. The MEDIAN of a
      # cell's DETECTED features is robust to both: it is unaffected by how many
      # features cleared the limit of detection and by the few most abundant ones,
      # so it isolates the multiplicative "how much material" component of depth.
      # It is also the divisor the scp-median route uses, which makes it the right
      # covariate for asking whether that normalization removed what it targeted.
      # Computed on the raw NA-containing matrix when available so that
      # not-detected is excluded rather than counted as a zero.
      med_src <- loaded$prt_raw
      med_ok  <- !is.null(med_src) && all(shared %in% colnames(med_src))
      med_vec <- if (med_ok) {
        apply(med_src[, shared, drop=FALSE], 2, function(x) {
          x <- x[!is.na(x) & x > 0]
          if (length(x)) stats::median(x) else NA_real_
        })
      } else {
        # Fallback: zero-filled matrix, zeros excluded so the median still means
        # "typical detected abundance" rather than "typical cell".
        apply(prt[, shared, drop=FALSE], 2, function(x) {
          x <- x[is.finite(x) & x > 0]
          if (length(x)) stats::median(x) else NA_real_
        })
      }
      meta[shared, "log2_median_intensity"] <- round(log2(as.numeric(med_vec) + 1), 3)
      if (!med_ok)
        message("log2_median_intensity computed from the zero-filled matrix (raw copy unavailable)")
    }

    note <- loaded$mapping_note %||% ""
    s$prt_int <- prt

    # >>> INTENSITY-NATIVE: store raw NA-containing matrix aligned to final prt <<<
    raw0 <- loaded$prt_raw
    if (!is.null(raw0)) {
      if (nrow(raw0) == nrow(prt) && ncol(raw0) >= ncol(prt)) {
        raw0 <- raw0[, colnames(prt), drop=FALSE]   # drop cells lost in alignment
        rownames(raw0) <- rownames(prt)             # inherit final (gene) names
      } else {
        common_c <- intersect(colnames(raw0), colnames(prt))
        raw0 <- raw0[, common_c, drop=FALSE]
      }
      s$prt_int_raw <- raw0
    } else {
      s$prt_int_raw <- NULL
    }

    # Confirm the raw NA-containing matrix survived load (VSN/scpmed rely on this)
    if (!is.null(s$prt_int_raw)) {
      n_na  <- sum(is.na(s$prt_int_raw))
      n_tot <- length(s$prt_int_raw)
      s_log(paste0("Raw intensity matrix captured for VSN/scp-median: ",
                   n_na, " NA / ", n_tot, " values (",
                   round(100*n_na/max(n_tot,1),1), "% missing preserved)."))
    }

    s$meta    <- meta
    s$prt_map <- if (!is.null(loaded$pmap)) loaded$pmap else if (!is.null(loaded$map)) loaded$map else NULL
    showNotification(paste0("prt_map set: ", if(!is.null(s$prt_map)) paste0(nrow(s$prt_map)," rows") else "NULL"),
                     type="message", duration=5)
    s_log(paste0("Loaded: ", nrow(prt), " proteins × ", ncol(prt), " cells",
                 note,
                 " | meta columns: ", ncol(meta)))
    showNotification(
      paste0("Loaded: ", nrow(prt), " proteins × ", ncol(prt), " cells", note),
      type="message", duration=7)
  }

  observeEvent(input$s_parse_rdata, {
    req(input$s_rdata_upload)
    tryCatch({ finalize_load(load_rdata(input$s_rdata_upload$datapath)) },
             error=function(e) showNotification(paste("Error:",e$message),type="error",duration=10))
  })

  # ── CSV load ───────────────────────────────────────────────────────────────
  observeEvent(input$s_parse_csv, {
    req(input$s_csv_prt, input$s_csv_meta)
    tryCatch({
      read_csv_safe <- function(path) {
        df <- read.csv(path, header=TRUE, check.names=FALSE,
                       stringsAsFactors=FALSE, na.strings=c("","NA","NaN"),
                       row.names=NULL)
        # If first column has no name (blank header in Excel export),
        # R names it "X" or "" — rename to "ID" so we can use it as rownames
        if (names(df)[1] %in% c("", "X", "X.1", NA)) names(df)[1] <- "ID"
        df
      }

      # ── prt.int ────────────────────────────────────────────────────────
      prt_df  <- read_csv_safe(input$s_csv_prt$datapath)
      id_col  <- names(prt_df)[1]
      rn      <- as.character(prt_df[[id_col]])
      prt_df  <- prt_df[, -1, drop=FALSE]
      prt.int <- as.matrix(prt_df)
      prt.int[prt.int == 0 & !is.na(prt.int)] <- NA
      rownames(prt.int) <- rn
      storage.mode(prt.int) <- "double"
      showNotification(paste0("prt.int: ", nrow(prt.int), " features × ",
                               ncol(prt.int), " cells"),
                       type="message", duration=5)

      # ── meta.samples ───────────────────────────────────────────────────
      meta_df      <- read_csv_safe(input$s_csv_meta$datapath)
      id_col_m     <- names(meta_df)[1]
      rn_m         <- as.character(meta_df[[id_col_m]])
      meta_df      <- meta_df[, -1, drop=FALSE]
      meta.samples <- as.data.frame(meta_df)
      rownames(meta.samples) <- rn_m
      showNotification(paste0("meta.samples: ", nrow(meta.samples), " cells × ",
                               ncol(meta.samples), " columns"),
                       type="message", duration=5)

      # ── prt.map (optional) ─────────────────────────────────────────────
      prt.map <- if (!is.null(input$s_csv_map)) {
        tryCatch({
          mp <- read_csv_safe(input$s_csv_map$datapath)
          showNotification(paste0("prt.map: ", nrow(mp), " rows, ",
                                   ncol(mp), " cols"),
                           type="message", duration=5)
          as.data.frame(mp)
        }, error=function(e) { 
          showNotification(paste0("prt.map load failed: ", e$message),
                           type="warning", duration=8)
          NULL 
        })
      } else NULL

      # ── Validate and clean rownames before saving ──────────────────────
      # Duplicate or NA rownames cause load_rdata to fail
      rn <- make.unique(as.character(rn), sep="_")
      rn[is.na(rn) | nchar(trimws(rn)) == 0] <- paste0("Feature_", seq_along(rn[is.na(rn) | nchar(trimws(rn)) == 0]))
      rownames(prt.int) <- rn

      rn_m <- make.unique(as.character(rn_m), sep="_")
      rn_m[is.na(rn_m) | nchar(trimws(rn_m)) == 0] <- paste0("Cell_", seq_along(rn_m[is.na(rn_m) | nchar(trimws(rn_m)) == 0]))
      rownames(meta.samples) <- rn_m

      # ── Save as RData then load through standard pipeline ──────────────
      tmp_rdata <- tempfile(fileext=".RData")
      save(prt.int, meta.samples, prt.map, file=tmp_rdata)
      finalize_load(load_rdata(tmp_rdata))
      showNotification("CSV data loaded successfully.", type="message", duration=5)

    }, error=function(e) showNotification(paste("CSV load error:", e$message),
                                          type="error", duration=12))
  })

  observeEvent(input$s_load_example, {
    p <- input$s_example_set
    if (is.null(p) || !nzchar(p)) {
      showNotification("Pick an example dataset from the list first.",
                       type="warning", duration=6); return()
    }
    if (!file.exists(p)) {
      showNotification(paste0("Example file not found: ", p), type="error", duration=10); return()
    }
    tryCatch({
      finalize_load(load_rdata(p))
      s_log(paste0("Example dataset loaded: ", basename(p)))
      showNotification(paste0("Loaded example '", basename(p), "'."),
                       type="message", duration=5)
    }, error=function(e) showNotification(
         paste0("Could not load '", basename(p), "': ", conditionMessage(e)),
         type="error", duration=12))
  })

  output$s_feature_col_ui <- renderUI({
    # Choices: rownames (as-is) + any columns in prt.map
    map_cols <- if (!is.null(s$prt_map)) names(s$prt_map) else character(0)
    choices  <- c("Row names (as-is)"="rownames", setNames(map_cols, map_cols))
    # Sensible defaults
    def <- if ("Genes" %in% map_cols) "Genes"
           else if ("Gene" %in% map_cols) "Gene"
           else if ("ProteinGroups" %in% map_cols) "ProteinGroups"
           else "rownames"
    selectInput("s_feature_col","Feature ID column:",
                choices=choices, selected=def)
  })

