  # ── Apply feature ID selection when building Seurat object ─────────────────
  # This is called in s_build_seu to rename rownames of the matrix
  get_feature_ids <- function(mat) {
    fc <- isolate(input$s_feature_col) %||% "rownames"
    if (fc == "rownames" || is.null(s$prt_map) || !fc %in% names(s$prt_map)) {
      return(rownames(mat))
    }
    # Map from current rownames to selected column
    map_df  <- s$prt_map
    # Try to find which prt.map column matches current rownames
    id_cols <- names(map_df)[sapply(names(map_df), function(col) {
      any(rownames(mat) %in% as.character(map_df[[col]]))
    })]
    if (length(id_cols) == 0) return(rownames(mat))
    id_col <- id_cols[1]
    # Build lookup: current_id → new_id
    lookup <- setNames(as.character(map_df[[fc]]), as.character(map_df[[id_col]]))
    new_ids <- lookup[rownames(mat)]
    # Replace NA or missing with original rowname
    new_ids[is.na(new_ids) | new_ids == ""] <- rownames(mat)[is.na(new_ids) | new_ids == ""]
    # Deduplicate — append suffix if duplicate gene names
    dupes <- duplicated(new_ids) | duplicated(new_ids, fromLast=TRUE)
    if (any(dupes)) {
      new_ids[dupes] <- make.unique(new_ids[dupes], sep="_")
      showNotification(paste0(sum(dupes), " duplicate feature IDs deduplicated with suffix."),
                       type="warning", duration=8)
    }
    new_ids
  }

