  # ── ② QC outputs ───────────────────────────────────────────────────────────
  output$s_qc_boxes <- renderUI({
    req(s$prt_int)
    no<-ncol(s$prt_int);np<-length(s_pass_cells())
    po<-nrow(s$prt_int);pp<-length(s_pass_prots())
    pc<-round(np/no*100,1);pr<-round(pp/po*100,1)
    cc<-if(pc>=80)"s-pass"else if(pc>=50)"s-warn"else"s-fail"
    rc<-if(pr>=80)"s-pass"else if(pr>=50)"s-warn"else"s-fail"

    # Median detected features among RETAINED cells, counted over RETAINED
    # features, so the number matches what every downstream tab receives.
    # NA-safe: prt_int may carry NA on the NA-aware normalization paths.
    med_feat <- if (np > 0 && pp > 0) {
      sub_med <- s$prt_int[s_pass_prots(), s_pass_cells(), drop=FALSE]
      stats::median(colSums(!is.na(sub_med) & sub_med > 0), na.rm=TRUE)
    } else NA_real_
    med_lbl <- if (is.finite(med_feat)) format(round(med_feat), big.mark=",") else "\u2014"

    # Five boxes no longer divide evenly into Bootstrap's 12 columns, so this
    # is a flex row instead of fluidRow(column(3, ...)). Same .s-stat styling.
    .qc_box <- function(inner) div(style="flex:1 1 0;min-width:130px;", inner)
    div(style="display:flex;gap:8px;flex-wrap:wrap;align-items:stretch;",
      .qc_box(div(class=paste("s-stat",cc),tags$h3(np,style="margin:0;"),tags$p(paste0("Cells / ",no),style="margin:0;font-size:12px;"))),
      .qc_box(div(class=paste("s-stat",rc),tags$h3(pp,style="margin:0;"),tags$p(paste0("Features / ",po),style="margin:0;font-size:12px;"))),
      .qc_box(div(class="s-stat",style="background:#2980B9;",tags$h3(paste0(pc,"%"),style="margin:0;"),tags$p("Cells retained",style="margin:0;font-size:12px;"))),
      .qc_box(div(class="s-stat",style="background:#8E44AD;",tags$h3(paste0(pr,"%"),style="margin:0;"),tags$p("Proteins retained",style="margin:0;font-size:12px;"))),
      .qc_box(div(class="s-stat",style="background:#16A085;",
                  title="Median number of detected features per retained cell, counted over retained features only.",
                  tags$h3(med_lbl,style="margin:0;"),
                  tags$p("Median features / cell",style="margin:0;font-size:12px;")))
    )
  })

  s_qc_hist <- function(vals, xlab, title, cutoff=NULL, col="#2980B9") {
    p <- ggplot(data.frame(v=vals),aes(x=v))+
      geom_histogram(bins=40,fill=col,color="white",alpha=0.85)+
      theme_classic(base_size=13)+labs(x=xlab,y="Count",title=title)
    if (!is.null(cutoff)) p <- p+geom_vline(xintercept=cutoff,color="red",linetype="dashed",linewidth=1)
    ggplotly(p)
  }

  output$s_qc_prot_hist  <- renderPlotly({ req(s$prt_int); s_qc_hist(colSums(s$prt_int>0),"Features per cell","Feature detection",if(isTRUE(input$s_qc_cells))input$s_qc_min_prot else NULL,"#2980B9") })
  # One bar per cell, ranked by detected feature count. Retained vs removed is
  # shaded so the effect of filter (1) is visible; the red dashed line is the
  # min-features cutoff and the teal line is the retained-cell median, i.e. the
  # value shown in the "Median features / cell" box above.
  output$s_qc_prot_bar <- renderPlotly({
    req(s$prt_int)
    cnts <- colSums(!is.na(s$prt_int) & s$prt_int > 0)
    keep <- colnames(s$prt_int) %in% s_pass_cells()
    df <- data.frame(cell   = colnames(s$prt_int),
                     n      = as.numeric(cnts),
                     status = ifelse(keep, "retained", "removed"),
                     stringsAsFactors = FALSE)
    df <- df[order(-df$n), , drop=FALSE]
    df$cell <- factor(df$cell, levels = df$cell)   # lock the ranked order
    med <- stats::median(df$n[df$status == "retained"], na.rm=TRUE)

    p <- ggplot(df, aes(x=cell, y=n, fill=status,
                        text=paste0(cell, "<br>", n, " features<br>", status))) +
      geom_col(width=1) +
      scale_fill_manual(values=c(retained="#2980B9", removed="#BDC3C7"), name=NULL) +
      theme_classic(base_size=13) +
      theme(axis.text.x=element_blank(), axis.ticks.x=element_blank()) +
      labs(x=paste0("Cell (ranked by detected features, n=", nrow(df), ")"),
           y="Detected features", title="Detected features per cell")
    if (isTRUE(input$s_qc_cells))
      p <- p + geom_hline(yintercept=.num(input$s_qc_min_prot, 0),
                          color="red", linetype="dashed", linewidth=1)
    if (is.finite(med))
      p <- p + geom_hline(yintercept=med, color="#16A085", linewidth=0.7)
    suppressWarnings(ggplotly(p, tooltip="text"))
  })
  output$s_qc_abund_hist <- renderPlotly({
    req(s$prt_int)
    cells <- s_pass_cells()
    # Use all cells (pre-filter) for the histogram, mark the cutoffs
    all_cells <- colnames(s$prt_int)
    ti_all    <- log2(colSums(s$prt_int) + 1)

    per_cond <- isTRUE(input$s_qc_outlier_per_cond) &&
                !is.null(input$s_qc_cond_col) &&
                input$s_qc_cond_col %in% names(s$meta) &&
                all(all_cells %in% rownames(s$meta))

    if (per_cond) {
      cond_vec <- s$meta[all_cells, input$s_qc_cond_col]
      df_ti <- data.frame(cell=all_cells, log2_total=ti_all,
                          Condition=as.character(cond_vec),
                          stringsAsFactors=FALSE)
      p <- ggplot(df_ti, aes(x=log2_total, fill=Condition)) +
        geom_histogram(bins=40, color="white", alpha=0.75, position="identity") +
        theme_classic(base_size=13) +
        labs(x="log₂(total intensity)", y="Count", title="Abundance distribution (per condition)")

      if (isTRUE(input$s_qc_outlier)) {
        # Add per-group cutoff lines
        cutoffs <- do.call(rbind, lapply(unique(cond_vec[!is.na(cond_vec)]), function(grp) {
          grp_cells <- all_cells[!is.na(cond_vec) & cond_vec == grp]
          ti_grp    <- ti_all[grp_cells]
          mn <- mean(ti_grp, na.rm=TRUE); sv <- sd(ti_grp, na.rm=TRUE)
          data.frame(Condition=grp,
                     lo=mn - input$s_qc_sd * sv,
                     hi=mn + input$s_qc_sd * sv,
                     stringsAsFactors=FALSE)
        }))
        p <- p +
          geom_vline(data=cutoffs, aes(xintercept=lo, color=Condition), linetype="dashed", linewidth=0.8) +
          geom_vline(data=cutoffs, aes(xintercept=hi, color=Condition), linetype="dashed", linewidth=0.8)
      }
    } else {
      ti <- ti_all
      mn <- mean(ti, na.rm=TRUE); sv <- sd(ti, na.rm=TRUE)
      p  <- ggplot(data.frame(v=ti), aes(x=v)) +
        geom_histogram(bins=40, fill="#27AE60", color="white", alpha=0.85) +
        theme_classic(base_size=13) +
        labs(x="log₂(total intensity)", y="Count", title="Abundance distribution")
      if (isTRUE(input$s_qc_outlier))
        p <- p +
          geom_vline(xintercept=mn - input$s_qc_sd * sv, color="red", linetype="dashed", linewidth=1) +
          geom_vline(xintercept=mn + input$s_qc_sd * sv, color="red", linetype="dashed", linewidth=1)
    }
    ggplotly(p)
  })
