  # ── ④ Explained Variation (raw log2) ───────────────────────────────────────
  output$s_ev_cov_ui <- renderUI({
    req(s$meta)
    # Only offer covariates actively classified in ③ Covariates (categorical or
    # technical) — columns left as "ignore" (or never classified) are excluded,
    # so this list stays relevant instead of listing every raw metadata column.
    roles <- tryCatch(s_cov_roles(), error=function(e) list())
    opts  <- names(s$meta)[sapply(names(s$meta), function(cn)
      (roles[[cn]] %||% "ignore") %in% c("categorical","technical"))]
    if (!length(opts))
      return(tags$p("No active covariates yet — set roles in ③ Covariates first.",
                    style="color:#E74C3C;font-size:12px;"))
    checkboxGroupInput("s_ev_covs","Covariates to test:",choices=opts,
                       selected=opts[seq_len(min(3,length(opts)))])
  })

  # Per-feature r² (BatchQC-style "Individual Variable" view): r² of a
  # covariate against EVERY feature's expression directly, not via PCA.
  # Vectorized to avoid one lm() call per feature (could be thousands) — loops
  # only over covariate LEVELS (few) for factors, or does a single matrix-
  # vector correlation for numeric covariates.
  .per_feature_r2 <- function(mat, x) {
    keep <- !is.na(x)
    if (sum(keep) < 3) return(rep(NA_real_, nrow(mat)))
    x   <- if (is.factor(x)) droplevels(x[keep]) else x[keep]
    mat <- mat[, keep, drop=FALSE]
    row_mean <- rowMeans(mat)
    ss_tot   <- rowSums((mat - row_mean)^2)
    if (is.factor(x)) {
      lv <- levels(x)
      if (length(lv) < 2) return(rep(NA_real_, nrow(mat)))
      ss_within <- numeric(nrow(mat))
      for (g in lv) {
        idx <- which(x == g); if (!length(idx)) next
        sub <- mat[, idx, drop=FALSE]
        gm  <- if (length(idx) > 1) rowMeans(sub) else sub[,1]
        ss_within <- ss_within + rowSums((sub - gm)^2)
      }
      r2 <- ifelse(ss_tot > 0, 1 - ss_within/ss_tot, NA_real_)
    } else {
      xn <- as.numeric(x)
      if (var(xn) == 0) return(rep(NA_real_, nrow(mat)))
      xc  <- xn - mean(xn)
      mc  <- mat - row_mean
      num <- as.numeric(mc %*% xc)
      den <- sqrt(rowSums(mc^2) * sum(xc^2))
      r2  <- ifelse(den > 0, (num/den)^2, NA_real_)
    }
    r2[!is.finite(r2)] <- NA_real_
    round(pmax(pmin(r2,1),0)*100, 2)
  }

  s_ev_result <- reactiveVal(NULL)
  s_ev_feature_result <- reactiveVal(NULL)

  observeEvent(input$s_run_ev, {
    req(s$prt_int, input$s_ev_covs)
    withProgress(message="Explained variation...", value=0, {
      mat    <- s_mat_filt()
      mat[is.na(mat)] <- 0
      log_mat <- log2(mat+1)
      log_mat <- log_mat[,apply(log_mat,2,var)>0,drop=FALSE]
      log_mat <- log_mat[apply(log_mat,1,var)>0,,drop=FALSE]
      incProgress(0.3,detail="PCA")
      pr     <- prcomp(t(log_mat),center=TRUE,scale.=TRUE)
      n_pcs  <- min(input$s_ev_npcs,ncol(pr$x))
      pc_mat <- pr$x[,1:n_pcs,drop=FALSE]
      cells  <- rownames(pc_mat)

      incProgress(0.5,detail="Building covariate matrix")
      meta_sub <- s_meta_filt()
      # Use a list, not a data.frame column, so categorical covariates can stay
      # genuine factors (data.frame(..., stringsAsFactors=FALSE) would otherwise
      # force everything to a single coercible type). Character/factor columns
      # are kept as factor() so lm() dummy-codes each level (proper between-
      # group R², like BatchQC's lm(y ~ factor(x))) — NOT recoded to
      # as.numeric(factor(x)), which falsely imposes an ordered/linear scale on
      # unordered categories (e.g. batch A/B/C/D treated as if A→B→C→D were an
      # even numeric progression). Numeric covariates are left as numeric.
      cov_list <- list()
      for (cov in input$s_ev_covs) {
        if (!cov %in% names(meta_sub)) next
        x <- meta_sub[cells,cov]
        cov_list[[cov]] <- if (is.character(x) || is.factor(x)) factor(x) else as.numeric(x)
      }

      incProgress(0.7,detail="Fitting models")
      r2_mat <- matrix(NA,nrow=length(cov_list),ncol=n_pcs,
                       dimnames=list(names(cov_list),paste0("PC",seq_len(n_pcs))))
      for (cov in names(cov_list)) {
        x <- cov_list[[cov]]
        if (all(is.na(x))) next
        if (is.factor(x)) {
          if (length(unique(x[!is.na(x)])) < 2) next   # need \u22652 levels to fit a factor term
        } else if (var(x, na.rm=TRUE) == 0) next        # zero-variance numeric guard
        for (pc in seq_len(n_pcs))
          r2_mat[cov,pc] <- tryCatch(round(summary(lm(pc_mat[,pc]~x))$r.squared*100,2),error=function(e)NA_real_)
      }
      s_ev_result(r2_mat); s$ev_mat <- r2_mat
      # PVCA-style weights: each PC's share of TOTAL data variance (its
      # eigenvalue / sum of all eigenvalues — i.e. the same "lambda" the Elbow
      # Plot and PCA % axes are built from), normalized across the PCs actually
      # tested here so weighted totals sum sensibly. Used by the "Total
      # Explained Variation" bar to weight each PC's R² by how much it actually
      # matters to the data — otherwise a covariate that only explains a minor,
      # low-variance PC ranks equally with one explaining PC1, which is why the
      # unweighted total previously disagreed with the eigenvalue/lambda view.
      lam_all <- pr$sdev^2
      lam_pve <- lam_all[seq_len(n_pcs)] / sum(lam_all)   # true share of TOTAL variance
      s$ev_pc_weights <- setNames(lam_pve / sum(lam_pve), paste0("PC",seq_len(n_pcs)))

      incProgress(0.85,detail="Per-feature variance")
      # log_mat is features (rows) × cells (columns), same cell order as cells/
      # cov_list (both derived from the same prcomp() run), so no realignment
      # needed. Computed directly on features — no PCA involved — matching
      # BatchQC's "Individual Variable" explained-variation view.
      feat_r2 <- data.frame(row.names=rownames(log_mat))
      for (cov in names(cov_list))
        feat_r2[[cov]] <- .per_feature_r2(log_mat, cov_list[[cov]])

      # "Explained" / "Unexplained" bookends (matches BatchQC's boxplot, which
      # flanks the individual-covariate boxes with the FULL joint model's R²
      # and its exact complement). Unlike the per-covariate boxes above (each
      # fit separately) or the PC-based Residual bar (an approximation from
      # summed univariate fits), these two are exact complements of ONE joint
      # model — no double-counting ambiguity, because they come from a single
      # fit of ALL selected covariates together.
      good_covs <- names(cov_list)[sapply(cov_list, function(x)
        if (is.factor(x)) length(unique(x[!is.na(x)])) >= 2 else var(x, na.rm=TRUE) > 0)]
      if (length(good_covs) >= 1) {
        design_df <- as.data.frame(cov_list[good_covs])
        complete_idx <- stats::complete.cases(design_df)
        if (sum(complete_idx) > length(good_covs) + 2) {   # need more cells than model params
          joint_ok <- tryCatch({
            X   <- stats::model.matrix(~., data=design_df[complete_idx, , drop=FALSE])
            Ysub<- log_mat[, complete_idx, drop=FALSE]
            fit <- stats::lm.fit(x=X, y=t(Ysub))              # ONE QR decomposition, all features at once
            rss <- colSums(fit$residuals^2)
            tss <- colSums(scale(t(Ysub), scale=FALSE)^2)
            r2j <- ifelse(tss > 0, 1 - rss/tss, NA_real_)
            r2j <- pmax(pmin(r2j, 1), 0)
            feat_r2[["Explained"]]   <- round(r2j * 100, 2)
            feat_r2[["Unexplained"]] <- round((1 - r2j) * 100, 2)
            TRUE
          }, error=function(e) { s_log(paste0("Joint EV model failed: ", conditionMessage(e))); FALSE })
        }
      }
      # remember the covariate order (pre-Explained/Unexplained) for plot ordering
      s$ev_feature_cov_order <- good_covs
      s_ev_feature_result(feat_r2); s$ev_feature_mat <- feat_r2

      s_log(paste0("Explained variation computed on QC filtered log2 data (", n_pcs," PCs, ",length(input$s_ev_covs)," covariates)"))
    })
    showNotification("Explained variation computed.",type="message",duration=4)
  })

  make_ev_heatmap <- function(r2) {
    df_h <- as.data.frame(r2) %>% tibble::rownames_to_column("Covariate") %>%
      tidyr::pivot_longer(-Covariate,names_to="PC",values_to="R2")
    df_h$PC <- factor(df_h$PC,levels=paste0("PC",seq_len(ncol(r2))))
    p <- ggplot(df_h,aes(x=PC,y=Covariate,fill=R2,
                         text=paste0(Covariate," × ",PC,"\nR² = ",round(R2,2),"%")))+
      geom_tile(color="white")+
      scale_fill_gradient2(low="white",mid="#3498DB",high="#E74C3C",midpoint=25,na.value="grey90",name="r² (%)")+
      theme_minimal(base_size=13)+theme(axis.text.x=element_text(angle=45,hjust=1))+
      labs(title="Explained Variation — log₂ data",x="PC",y="")
    ggplotly(p,tooltip="text")
  }

  output$s_ev_heatmap <- renderPlotly({ req(s_ev_result()); make_ev_heatmap(s_ev_result()) })
  output$s_ev_bar <- renderPlotly({
    req(s_ev_result()); r2<-s_ev_result()
    # Weight each PC's R² by that PC's own share of TOTAL data variance (its
    # eigenvalue/lambda, normalized across the tested PCs) before summing —
    # true PVCA weighting. Without this, a covariate that only explains a
    # minor, low-variance PC counts equally with one explaining PC1, which is
    # why an unweighted sum can disagree with the Elbow/PVE (lambda) view.
    w <- s$ev_pc_weights
    if (!is.null(w) && length(w) == ncol(r2) && all(colnames(r2) %in% names(w))) {
      w   <- w[colnames(r2)]
      tot <- as.numeric(r2 %*% w)          # weighted sum across PCs, per covariate
      names(tot) <- rownames(r2)
      ylab <- "Weighted average r² sum of total explained variance"
    } else {
      # Fallback if weights weren't stored (e.g. results from before this fix)
      tot <- rowSums(r2,na.rm=TRUE)
      ylab <- "Sum r² (%, unweighted — re-run for PVCA-weighted totals)"
    }
    # Residual bar: variance not explained by ANY tested covariate. This is
    # 100% minus the sum of each covariate's weighted contribution — the
    # standard PVCA-plot convention. Caveat: this treats each covariate's
    # contribution as non-overlapping, which holds exactly for a joint model
    # but is an APPROXIMATION here since each covariate was fit separately
    # (univariate per PC). If your tested covariates are themselves correlated
    # (e.g. batch confounded with condition), their individual R² can overlap,
    # so the bars may sum to >100% — the Residual is clipped at 0 in that case
    # rather than shown as negative, which understates true unexplained
    # variance when covariates are collinear.
    resid <- max(0, 100 - sum(tot, na.rm=TRUE))
    tot   <- c(tot, "Residual" = resid)
    df_b<-data.frame(Covariate=names(tot),Total_R2=tot)%>%arrange(desc(Total_R2))
    df_b$Covariate<-factor(df_b$Covariate,levels=rev(df_b$Covariate))
    ggplotly(ggplot(df_b,aes(x=Total_R2,y=Covariate,fill=Total_R2,
                              text=paste0(Covariate,"\nTotal R² = ",round(Total_R2,1),"%")))+
               geom_bar(stat="identity",alpha=0.85)+
               scale_fill_gradient(low="#85C1E9",high="#E74C3C", name="total r² (%)")+
               theme_classic(base_size=13)+labs(x=ylab,y="",title="Total Explained Variation"),
             tooltip="text")
  })
  output$s_ev_tbl <- renderDT({ req(s_ev_result()); datatable(as.data.frame(s_ev_result())%>%tibble::rownames_to_column("Covariate"),options=list(pageLength=15,scrollX=TRUE)) })

  # ── Per-feature variance (BatchQC-inspired "Individual Variable" view) ────────
  # Static builder shared by the on-screen plotly panel and the PDF export, so
  # the exported boxplot keeps the same covariate ORDER as the screen. That order
  # is deliberate (joint-model bookends flanking the per-covariate boxes) and is
  # not recoverable from the data alone, which is why both paths read it from the
  # same place rather than each deriving it.
  .build_ev_feature_box <- function(fs = 13) {
    fr <- tryCatch(s_ev_feature_result(), error=function(e) NULL)
    if (is.null(fr))
      stop("No per-feature explained variation computed yet — run the Explained\n",
           "Variation tab with at least one covariate selected.", call.=FALSE)
    df_fb <- fr %>% tibble::rownames_to_column("Feature") %>%
      tidyr::pivot_longer(-Feature, names_to="Covariate", values_to="R2") %>%
      dplyr::filter(!is.na(R2))
    if (!nrow(df_fb))
      stop("No estimable per-feature r\u00b2 values to plot.", call.=FALSE)
    # Order: "Explained" first, individual covariates in their original
    # selection order, "Unexplained" last — matches BatchQC's own layout
    # (joint-model bookends flanking the per-covariate boxes), rather than
    # sorting by median.
    cov_ord <- s$ev_feature_cov_order %||% setdiff(unique(df_fb$Covariate), c("Explained","Unexplained"))
    lv <- c(intersect("Explained", unique(df_fb$Covariate)),
            intersect(cov_ord, unique(df_fb$Covariate)),
            intersect("Unexplained", unique(df_fb$Covariate)))
    df_fb$Covariate <- factor(df_fb$Covariate, levels=lv)
    ggplot(df_fb, aes(x=Covariate, y=R2, fill=Covariate)) +
      geom_boxplot(outlier.size=0.5, alpha=0.8) +
      theme_classic(base_size=fs) + theme(legend.position="none") +
      labs(title="Distribution of Variance Explained by Sources on a per Feature Basis",
           x="", y="Percent Explained Variation")
  }

  output$s_ev_feature_box <- renderPlotly({
    req(s_ev_feature_result())
    p <- tryCatch(.build_ev_feature_box(13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    ggplotly(p, tooltip=c("y"))
  })
  # Per-feature EV table, columns ordered as in the boxplot: Explained first,
  # then each covariate in the order it was selected, then Unexplained.
  .s_ev_feature_df <- function() {
    fr <- s_ev_feature_result()
    if (is.null(fr)) return(NULL)
    df <- as.data.frame(fr)
    if (!nrow(df) || !ncol(df)) return(NULL)
    bookends <- c("Explained", "Unexplained")
    cov_ord  <- s$ev_feature_cov_order %||% setdiff(names(df), bookends)
    ord <- c(intersect("Explained",   names(df)),
             intersect(cov_ord,       names(df)),
             intersect("Unexplained", names(df)))
    ord <- unique(c(ord, setdiff(names(df), ord)))
    tibble::rownames_to_column(df[, ord, drop=FALSE], "Feature")
  }

  output$s_ev_feature_tbl <- renderDT({
    df <- .s_ev_feature_df()
    req(df)
    datatable(df, options=list(pageLength=15, scrollX=TRUE))
  })

  .s_ev_feature_write <- function(file) {
    df <- .s_ev_feature_df()
    if (is.null(df)) {
      showNotification(paste0("No per-feature explained variation to export yet. ",
                              "Select covariates and click Compute on this tab first."),
                       type = "error", duration = 8)
      req(FALSE)
    }
    readr::write_csv(df, file)
    s_log(paste0("Per-feature explained variation exported: ", nrow(df),
                 " features x ", ncol(df) - 1, " columns"))
  }
  .s_ev_feature_name <- function() paste0("exp_var_per_feature_", Sys.Date(), ".csv")

  # Two buttons (EV tab and Export tab) need two distinct output IDs; they
  # share the same filename and content functions.
  output$s_dl_ev_feature <- downloadHandler(filename = .s_ev_feature_name,
                                            content  = .s_ev_feature_write)
  output$s_dl_ev_feature_exp <- downloadHandler(filename = .s_ev_feature_name,
                                                content  = .s_ev_feature_write)

  # ── ⑤ Seurat Object ─────────────────────────────────────────────────────────
  observeEvent(input$s_build_seu, {
    req(s_mat_filt())
    withProgress(message="Building Seurat object...", value=0, {
      mat  <- s_mat_filt(); meta <- s_meta_filt()

      # Explicit alignment check — matrix columns MUST match meta rows exactly
      shared <- intersect(colnames(mat), rownames(meta))
      if (length(shared) == 0)
        { showNotification("No cells match between matrix and metadata — check IDs.",
                           type="error", duration=12); return() }
      if (length(shared) < ncol(mat)) {
        showNotification(paste0(ncol(mat)-length(shared),
                                " cells dropped: present in matrix but missing from metadata."),
                         type="warning", duration=8)
        s_log(paste0("Cell alignment: using ", length(shared), " of ", ncol(mat), " cells"))
      }
      mat  <- mat[, shared, drop=FALSE]
      meta <- meta[shared, , drop=FALSE]

      # ── Encode metadata by its classification BEFORE building the object ──────
      # Categorical columns (from the ③ Classify tab) -> factor.
      # Technical columns -> numeric where possible.
      # This is the robust way to keep character covariates: a properly typed,
      # cell-aligned data.frame is accepted by CreateSeuratObject without the
      # silent column-dropping seen when types are ambiguous.
      roles <- tryCatch(s_cov_roles(), error=function(e) list())
      for (cn in names(meta)) {
        role <- roles[[cn]] %||% "ignore"
        v <- meta[[cn]]
        if (role == "categorical") {
          meta[[cn]] <- factor(as.character(v))
        } else if (role == "technical") {
          num <- suppressWarnings(as.numeric(as.character(v)))
          # keep numeric only if the coercion didn't destroy the column
          meta[[cn]] <- if (sum(is.na(num)) <= sum(is.na(v))) num else factor(as.character(v))
        } else {
          # ignore/unclassified: preserve as-is but ensure character (not factor
          # with stale levels) so nothing is dropped at build
          if (is.factor(v)) meta[[cn]] <- as.character(v)
        }
      }
      # Guarantee rownames are the cell IDs and exactly match the matrix columns.
      rownames(meta) <- shared

      # ── Sanitize counts before CreateSeuratObject ────────────────────────
      # SCTransform requires non-negative, finite, integer-valued numbers.
      # Storage type must be numeric (double) — dgCMatrix @x slot is double.
      # NA values (not-detected proteins) become 0.
      mat <- as.matrix(mat)
      mat[is.na(mat) | is.nan(mat) | is.infinite(mat)] <- 0
      mat <- ceiling(mat)
      mat[mat < 0] <- 0
      storage.mode(mat) <- "integer"

      # ── Apply feature ID selection ─────────────────────────────────────────
      # Rename matrix rows to the user-selected identifier (ProteinGroups/Genes/Peptides)
      new_feat_ids <- tryCatch(get_feature_ids(mat), error=function(e) rownames(mat))
      if (!is.null(new_feat_ids) && length(new_feat_ids) == nrow(mat))
        rownames(mat) <- new_feat_ids

      # Use user-specified assay label (Protein, Gene, Peptide, etc.)
      assay_use <- if (!is.null(input$s_assay_label) && nchar(trimws(input$s_assay_label)) > 0)
        trimws(input$s_assay_label) else input$s_assay

      # Keep colnames of the matrix aligned to the metadata rownames.
      colnames(mat) <- shared

      incProgress(0.4, detail="CreateSeuratObject")
      seu <- Seurat::CreateSeuratObject(counts=mat, meta.data=meta,
                                        project=input$s_project, assay=assay_use)

      # Safety net: if any classified column still failed to attach, add it now.
      miss <- setdiff(names(meta), names(seu@meta.data))
      if (length(miss) > 0) {
        tryCatch({
          add_df <- meta[colnames(seu), miss, drop=FALSE]
          seu <- Seurat::AddMetaData(seu, metadata = add_df, col.name = miss)
        }, error=function(e) {
          # per-column fallback avoids version quirks with multi/single-col frames
          for (cn in miss) {
            vals <- meta[colnames(seu), cn]
            tryCatch(seu[[cn]] <<- vals, error=function(e2) NULL)
          }
        })
      }
      s_log(paste0("Metadata attached: ", ncol(seu@meta.data), " columns incl. ",
                   sum(vapply(seu@meta.data, function(x) is.factor(x)||is.character(x), logical(1))),
                   " categorical."))


      incProgress(0.6,detail="PercentageFeatureSet")
      seu[["percent.mt"]] <- Seurat::PercentageFeatureSet(seu, pattern=input$s_mt_pat, assay=input$s_assay)

      # ── Load-time depth metrics ─────────────────────────────────────────────
      # Three complementary proxies, all computed in finalize_load() on the full
      # pre-QC matrix:
      #   nFeature_raw          detection events  (threshold channel of depth)
      #   log2_total_intensity  summed signal     (dominated by abundant features)
      #   log2_median_intensity median of DETECTED features (multiplicative
      #                         channel only; the divisor scp-median uses)
      # finalize_load() skips them when rownames(meta) does not intersect
      # colnames(prt), and a partial intersect leaves unmatched cells NA, so the
      # violin panels that use them would vanish without a word. Recompute here
      # from the stored matrices when a column is absent or entirely NA.
      raw_src <- if (!is.null(s$prt_int_raw)) s$prt_int_raw else s$prt_int
      .needs  <- function(nm) !(nm %in% names(meta)) || all(is.na(meta[[nm]]))
      .fill   <- function(fun) {
        v  <- rep(NA_real_, length(shared)); names(v) <- shared
        cc <- intersect(shared, colnames(raw_src))
        if (length(cc)) v[cc] <- fun(raw_src[, cc, drop=FALSE])
        list(v=v, n=length(cc))
      }
      .med_col <- function(m) round(log2(apply(m, 2, function(x) {
                    x <- x[!is.na(x) & x > 0]
                    if (length(x)) stats::median(x) else NA_real_
                  }) + 1), 3)

      if (.needs("nFeature_raw")) {
        r <- .fill(function(m) as.numeric(colSums(m > 0, na.rm=TRUE)))
        seu[["nFeature_raw"]] <- r$v
        s_log(paste0("nFeature_raw absent/all-NA in metadata — recomputed at build for ",
                     r$n, " of ", length(shared), " cells."))
      } else seu[["nFeature_raw"]] <- meta[shared,"nFeature_raw"]

      if (.needs("log2_total_intensity")) {
        r <- .fill(function(m) round(log2(colSums(m, na.rm=TRUE) + 1), 3))
        seu[["log2_total_intensity"]] <- r$v
        s_log(paste0("log2_total_intensity absent/all-NA in metadata — recomputed at build for ",
                     r$n, " of ", length(shared), " cells."))
      } else seu[["log2_total_intensity"]] <- meta[shared,"log2_total_intensity"]

      if (.needs("log2_median_intensity")) {
        r <- .fill(.med_col)
        seu[["log2_median_intensity"]] <- r$v
        s_log(paste0("log2_median_intensity absent/all-NA in metadata — recomputed at build for ",
                     r$n, " of ", length(shared), " cells."))
      } else seu[["log2_median_intensity"]] <- meta[shared,"log2_median_intensity"]

      # Set Idents to ID for readable plot labels
      if ("ID" %in% names(seu@meta.data))
        Seurat::Idents(seu) <- "ID"

      seu   <- seu
      s$seu <- seu

      # ── Invalidate everything derived from the PREVIOUS object ──────────────
      # A rebuilt object is a new object: CreateSeuratObject returns only the
      # original assay, so any SCT assay, normalized layer, reduction, cluster
      # or marker result from the previous build is gone from s$seu. The
      # SEPARATELY STORED results are not, and several consumers read them
      # without checking freshness:
      #   * s$intensity_diag  — the VSN/scp-median normalized matrix, read by the
      #                         Mean-SD panel, the NA-aware marker tests and the
      #                         norm_na / norm_zero exports
      #   * s$sct_list        — per-group objects; s_sct_active() returns one of
      #                         these INSTEAD of s$seu whenever the view selector
      #                         holds a group name, so a stale entry silently
      #                         redirects every downstream tab
      #   * markers / integration / cell-cycle / pathway / annotation /
      #     trajectory / diagnostic results — all computed against cells,
      #     clusters or embeddings that no longer exist
      # Clearing them here is what makes "rebuild to start clean" true rather
      # than aspirational.
      n_cleared <- sum(!vapply(list(s$intensity_diag, s$sct_list, s$markers,
                                    s$seu_int, s$int_markers, s$pw_result,
                                    s$ann_fisher, s$ann_scores, s$traj_sds,
                                    s$js_result, s$sil_result, s$clustree_seu),
                               is.null, logical(1)))

      # Selector-warning de-duplication is per object; a rebuild should report again.
      rm(list = ls(envir = .opt_seen), envir = .opt_seen)

      # ⑥ normalization products
      s$intensity_diag <- NULL      # VSN / scp-median normalized matrix + selection stats
      s$sct_list       <- NULL      # per-group objects from integration mode

      # ⑧ / ⑨ clustering diagnostics and markers
      s$js_result      <- NULL
      s$sweep_plots    <- NULL
      s$sil_grid       <- NULL
      s$sil_result     <- NULL
      s$clustree_seu   <- NULL
      s$markers        <- NULL
      s$last_mk_mode   <- NULL
      s$last_mk_grp    <- NULL
      s$last_mk_comp   <- NULL

      # ⑪ / ⑫ integration
      s$seu_int        <- NULL
      s$int_markers    <- NULL
      s$int_data_snapshot <- NULL
      s$last_i_mk_comp <- NULL
      s$int_feats      <- NULL
      s$int_obj_list   <- NULL
      s$int_anchors    <- NULL
      s$i_sil_grid     <- NULL
      s$i_sil_result   <- NULL
      s$i_clustree_seu <- NULL
      s$int_step1_done <- FALSE; s$int_step2_done <- FALSE; s$int_step3_done <- FALSE
      s$int_step4_done <- FALSE; s$int_step5_done <- FALSE; s$int_step6_done <- FALSE
      s$int_step7_done <- FALSE; s$int_step8_done <- FALSE; s$int_step9_done <- FALSE

      # ⑩ cell cycle
      s$cc_scored      <- FALSE
      s$cc_gene_counts <- NULL
      s$cc_diff_done   <- FALSE

      # ⑬ / ⑭ / ⑮ pathway, annotation, trajectory
      s$pw_result      <- NULL
      s$pw_meta        <- NULL
      s$ann_fisher     <- NULL
      s$ann_scores     <- NULL
      s$traj_sds       <- NULL
      s$traj_pt        <- NULL
      s$traj_meta      <- NULL
      # NOTE: s$ann_ref / s$ann_ref_meta are a loaded REFERENCE, not a result of
      # this object, so they are deliberately kept. Same for palette and
      # level_order, which are display preferences.

      s_log(paste0("Seurat object built: ", ncol(seu), " cells × ", nrow(seu), " features",
                   " | assay=", input$s_assay,
                   " | project=", input$s_project))
      if (n_cleared > 0)
        s_log(paste0("Rebuild cleared ", n_cleared, " stored result set(s) derived from the ",
                     "previous object (normalization, markers, integration, ",
                     "cell cycle, pathway, annotation, trajectory)."))
    })
    showNotification(paste0("Seurat object: ",ncol(s$seu)," cells × ",nrow(s$seu)," features",
                            ". Downstream results (normalization, markers, integration, ",
                            "cell cycle, pathway, annotation, trajectory) have been cleared ",
                            "\u2014 re-run \u2465 onward."),
                     type="message", duration=9)
  })

  output$s_seu_status <- renderUI({
    if(is.null(s$seu)) return(tags$p("No Seurat object.",style="color:#E74C3C;font-size:13px;"))
    tags$p(paste0("✓ ",ncol(s$seu)," cells × ",nrow(s$seu)," features"),style="color:#27AE60;font-size:13px;font-weight:600;")
  })

  # Toggleable identity controls for Violin and FeatureScatter
  output$s_vln_grp_ui <- renderUI({
    req(s$seu); cols <- names(s$seu@meta.data)
    selectInput("s_vln_grp","Violin — group by:",choices=cols,
                selected=if("sex" %in% tolower(cols)) cols[tolower(cols)=="sex"][1] else cols[1])
  })
  output$s_feat_x_ui <- renderUI({
    req(s$seu); assay_nm <- input$s_assay
    opts <- names(s$seu@meta.data)
    selectInput("s_feat_x","Scatter X:",choices=opts,
                selected=if(paste0("nCount_",assay_nm) %in% opts) paste0("nCount_",assay_nm) else opts[1])
  })
  output$s_feat_y_ui <- renderUI({
    req(s$seu); assay_nm <- input$s_assay
    opts <- names(s$seu@meta.data)
    # second scatter Y
    selectInput("s_feat_y","Scatter Y:",choices=opts,
                selected=if(paste0("nFeature_",assay_nm) %in% opts) paste0("nFeature_",assay_nm) else opts[min(2,length(opts))])
  })
  output$s_feat_grp_ui <- renderUI({
    req(s$seu); cols <- names(s$seu@meta.data)
    selectInput("s_feat_grp","Scatter color / group by:",choices=c("(none)"="none",cols),
                selected=if("sex" %in% tolower(cols)) cols[tolower(cols)=="sex"][1] else "none")
  })

  output$s_vln_plot <- renderPlot({
    req(s_seu_with_ident(), input$s_vln_grp)
    assay_nm <- input$s_assay
    feats <- intersect(c(paste0("nFeature_",assay_nm), paste0("nCount_",assay_nm),
                         "percent.mt","nFeature_raw","log2_total_intensity","log2_median_intensity"),
                       names(s_seu_with_ident()@meta.data))
    # Apply custom palette if set for the grouping variable. Via .pal_seu so the
    # vector is subset and ordered to the levels actually present — Seurat's cols=
    # matches by POSITION, so an unsubset palette shifts every color when a level
    # is absent from the current object.
    pal <- .pal_seu(s_seu_with_ident(), input$s_vln_grp)
    p   <- Seurat::VlnPlot(s_seu_with_ident(), features=feats,
                            group.by=input$s_vln_grp, pt.size=1.5, ncol=3,
                            cols=if(!is.null(pal)) pal else NULL)
    print(p)
