  output$s_feat_scatter <- renderPlot({
    req(s$seu, input$s_feat_x, input$s_feat_y)
    gb  <- if(!is.null(input$s_feat_grp) && input$s_feat_grp != "none") input$s_feat_grp else NULL
    seu <- s$seu

    # FeatureScatter colors from Idents(); set them to the group variable
    # then optionally override with the custom palette via a ggplot layer
    if (!is.null(gb) && gb %in% names(seu@meta.data))
      Seurat::Idents(seu) <- gb

    pal_scale <- if (!is.null(gb)) s_get_scale_color(gb) else NULL

    p1 <- Seurat::FeatureScatter(seu, feature1=input$s_feat_x,
                                  feature2=input$s_feat_y, pt.size=2)
    if (!is.null(pal_scale)) p1 <- p1 + pal_scale

    assay_nm   <- input$s_assay
    ncount_col <- paste0("nCount_", assay_nm)
    if (input$s_feat_x != ncount_col && ncount_col %in% names(seu@meta.data)) {
      p2 <- Seurat::FeatureScatter(seu, feature1=ncount_col,
                                    feature2=input$s_feat_y, pt.size=2)
      if (!is.null(pal_scale)) p2 <- p2 + pal_scale
      print(p1 + p2)
    } else {
      print(p1)
    }
  })
  output$s_meta_tbl <- renderDT({ req(s$seu); datatable(s$seu@meta.data,options=list(pageLength=10,scrollX=TRUE)) })

  # ── Distribution Diagnostics ───────────────────────────────────────────────
  s_diag <- reactiveVal(NULL)

  observeEvent(input$s_run_diag, {
    src <- input$s_diag_source %||% "raw_na"
    # Resolve the source matrix. All three are views of the RAW uploaded data,
    # aligned to the same filtered cells/features so they're directly comparable.
    if (src == "int_zero") {
      req(s_mat_filt())
      mat0 <- s_mat_filt()                 # ceiling'd integer matrix with 0s (SCT input)
      na_aware <- FALSE
    } else {
      # raw_na / raw_zero: original non-integer intensities
      if (is.null(s$prt_int_raw)) {
        showNotification("Raw intensity matrix not found — reload data so the raw copy is captured.",
                         type="error", duration=10); return()
      }
      mat0 <- as.matrix(s$prt_int_raw)
      # align to the same cells/features the filtered matrix uses, when available
      fm <- tryCatch(s_mat_filt(), error=function(e) NULL)
      if (!is.null(fm)) {
        cf <- intersect(rownames(fm), rownames(mat0))
        cc <- intersect(colnames(fm), colnames(mat0))
        if (length(cf) > 1 && length(cc) > 1) mat0 <- mat0[cf, cc, drop=FALSE]
      }
      na_aware <- (src == "raw_na")        # raw_na keeps NAs; raw_zero fills them
    }
    withProgress(message="Running distribution diagnostics...", value=0, {
      mat <- mat0
      if (!na_aware) mat[is.na(mat)] <- 0     # raw_zero and int_zero: zero-fill

      incProgress(0.1, detail="Computing per-protein stats")
      if (na_aware) {
        # keep proteins with >=1 observed value; stats over observed cells only
        nobs <- rowSums(!is.na(mat))
        mat  <- mat[nobs > 0, , drop=FALSE]
        n_cells    <- ncol(mat)
        prot_means <- rowMeans(mat, na.rm=TRUE)
        prot_vars  <- apply(mat, 1, stats::var, na.rm=TRUE)
        prot_zeros <- rowMeans(is.na(mat))    # "zero fraction" = NA (not-detected) fraction
      } else {
        # Remove all-zero proteins
        mat <- mat[rowSums(mat) > 0, , drop=FALSE]
        n_cells    <- ncol(mat)
        prot_means <- rowMeans(mat)
        prot_vars  <- apply(mat, 1, var)
        prot_zeros <- rowSums(mat == 0) / n_cells
      }

      # ── NB size and dispersion (method of moments on var = mu + mu²/r) ──────
      # TWO distinct quantities, previously conflated under the name "disp":
      #   prot_size  = r      — the shape/size parameter. This is what qnbinom()
      #                         and the zero-probability formula require.
      #   prot_alpha = 1/r    — the DISPERSION. This is what the panels report,
      #                         for three reasons: (a) the NB assumption is that
      #                         dispersion is a smooth function of the mean, and
      #                         CV² = 1/mu + alpha makes alpha the asymptote, so
      #                         "does NB hold?" is "is alpha flat in mu?";
      #                         (b) r diverges as var -> mu from above, so its
      #                         median is dominated by features sitting near the
      #                         Poisson boundary, while alpha passes smoothly
      #                         through 0 there; (c) alpha is the squared
      #                         biological CV once sampling noise is removed, so
      #                         sqrt(alpha) is directly interpretable.
      # Features with var <= mu have no valid NB moment estimate and return NA in
      # both — their COUNT is itself diagnostic (see the Dispersion panel title).
      prot_size  <- ifelse(prot_vars > prot_means,
                           prot_means^2 / (prot_vars - prot_means),
                           NA_real_)
      prot_alpha <- ifelse(prot_vars > prot_means,
                           (prot_vars - prot_means) / prot_means^2,
                           NA_real_)

      # ── Overdispersion test: compare observed variance to Poisson expectation ──
      # chi² statistic = sum((x - mu)²) / mu  follows chi²(n-1) under Poisson.
      # (Meaningful for counts; for normalized data this is shown but not a valid
      #  NB assessment — the source label flags that in the summary.)
      overdispersed <- apply(mat, 1, function(x) {
        x <- x[!is.na(x)]
        if (length(x) < 2) return(FALSE)
        mu <- mean(x)
        if (mu == 0) return(FALSE)
        chisq <- sum((x - mu)^2) / mu
        pchisq(chisq, df=length(x)-1, lower.tail=FALSE) < 0.05
      })

      # ── NB predicted zero fraction: P(X=0) = (r/(r+mu))^r ──
      nb_zero_pred <- mapply(function(mu, r) {
        if (is.na(r) || r <= 0) return(NA_real_)
        (r / (r + mu))^r
      }, prot_means, prot_size)   # size (r), NOT dispersion (1/r)

      incProgress(0.6, detail="Computing CV²")
      prot_cv2 <- prot_vars / (prot_means^2 + 1e-10)

      # ── Sample proteins for QQ ──
      set.seed(42)
      n_qq <- min(input$s_diag_sample_n, nrow(mat))
      qq_prots <- sample(rownames(mat), n_qq)

      s_diag(list(
        means        = prot_means,
        vars         = prot_vars,
        zeros        = prot_zeros,
        disp         = prot_alpha,   # dispersion alpha = 1/r (what panels plot)
        size         = prot_size,    # NB size r (what qnbinom/zero-pred need)
        overdispersed = overdispersed,
        nb_zero_pred = nb_zero_pred,
        cv2          = prot_cv2,
        qq_prots     = qq_prots,
        mat          = mat[qq_prots, , drop=FALSE],
        n_cells      = n_cells,
        n_prots      = nrow(mat),
        source       = src,
        na_aware     = na_aware
      ))
      s_log(paste0("Distribution diagnostics: ", nrow(mat), " proteins, ",
                   sum(overdispersed, na.rm=TRUE), " overdispersed (",
                   round(mean(overdispersed, na.rm=TRUE)*100, 1), "%)"))
    })
    showNotification("Diagnostics complete.", type="message", duration=4)
  })

  output$s_diag_summary_ui <- renderUI({
    d <- s_diag(); if (is.null(d)) return(tags$p("Click 'Run diagnostics' to start.",style="color:grey;"))
    pct_od  <- round(mean(d$overdispersed, na.rm=TRUE)*100, 1)
    # Median DISPERSION (alpha = 1/r), not the size parameter. sqrt(alpha) is the
    # residual (biological) CV once the Poisson sampling term is removed, which
    # is the interpretable form of the same number.
    med_alpha <- median(d$disp, na.rm=TRUE)
    med_disp  <- round(med_alpha, 3)
    med_cv    <- if (is.finite(med_alpha) && med_alpha > 0)
                   round(100*sqrt(med_alpha)) else NA_real_
    pct_zeroOK <- round(mean(abs(d$zeros - d$nb_zero_pred) < 0.1, na.rm=TRUE)*100, 1)
    od_col  <- if (pct_od > 70) "#27AE60" else if (pct_od > 40) "#F39C12" else "#E74C3C"
    fluidRow(
      column(4, div(class="s-stat", style=paste0("background:",od_col,";"),
        tags$h3(paste0(pct_od,"%"), style="margin:0;"),
        tags$p("Features overdispersed (NB or Lognormal > Poisson)", style="margin:0;font-size:11px;"))),
      column(4, div(class="s-stat", style="background:#2980B9;",
        tags$h3(med_disp, style="margin:0;"),
        tags$p(if (is.na(med_cv))
                 "Median NB dispersion \u03b1 = 1/r"
               else sprintf("Median NB dispersion \u03b1 = 1/r (residual CV %d%%)", med_cv),
               style="margin:0;font-size:11px;"))),
      column(4, div(class="s-stat", style="background:#8E44AD;",
        tags$h3(paste0(pct_zeroOK,"%"), style="margin:0;"),
        tags$p("Features with zero fraction ≈ NB predicted (±10%)", style="margin:0;font-size:11px;")))
    )
  })

  output$s_diag_source_note <- renderUI({
    d <- s_diag(); req(d)
    msg <- switch(d$source %||% "raw_na",
      "raw_na" = paste0("Source: raw non-integer intensities with NAs present. Stats are computed ",
             "over observed (non-NA) values; the 'zero fraction' panel shows the NA (not-detected) ",
             "fraction. This is the data as uploaded, before any count coercion. NB-specific ",
             "readouts assume counts — treat them as descriptive here, not as a valid NB fit."),
      "raw_zero" = paste0("Source: raw non-integer intensities with NAs replaced by 0. Same float ",
             "values as the NA-aware view, but not-detected proteins now read as 0 — compare the ",
             "zero fraction and mean-variance shape against the NA-aware view to see what the ",
             "substitution does before any integer rounding."),
      "int_zero" = paste0("Source: ceiling'd integer matrix with 0s — exactly what feeds ",
             "SCTransform. Compare against the two raw views to see the combined effect of NA→0 ",
             "and integer rounding on the NB-fit distribution."),
      NULL)
    if (is.null(msg)) return(NULL)
    bg <- if (identical(d$source,"int_zero")) "#eafaf1" else "#fdf6e3"
    bd <- if (identical(d$source,"int_zero")) "#27AE60" else "#f0ad4e"
    tc <- if (identical(d$source,"int_zero")) "#1a5c38" else "#8a6d3b"
    div(style=paste0("background:",bg,";border:1px solid ",bd,";border-radius:4px;padding:6px;margin:6px 0;"),
        tags$small(msg, style=paste0("color:",tc,";")))
  })

  output$s_diag_mv <- renderPlotly({
    d <- s_diag(); req(d)
    df <- data.frame(
      gene    = names(d$means),
      log_mean = log10(d$means + 1),
      log_var  = log10(d$vars  + 1),
      overdispersed = d$overdispersed
    )
    # Reference lines
    x_seq <- seq(min(df$log_mean), max(df$log_mean), length.out=100)
    ref_poisson <- data.frame(x=x_seq, y=x_seq,               lab="Poisson (slope=1)")
    ref_nb      <- data.frame(x=x_seq, y=2*x_seq-median(df$log_mean),
                              lab="NB-like (slope≈2)")
    p <- ggplot(df, aes(x=log_mean, y=log_var, color=overdispersed,
                        text=paste0(gene, "\nlog10(mean)=", round(log_mean,3),
                                    "\nlog10(var)=", round(log_var,3)))) +
      geom_point(size=1.5, alpha=0.6) +
      scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                         labels=c("Poisson-like","Overdispersed (NB)")) +
      geom_line(data=ref_poisson, aes(x=x,y=y,text=NULL), color="#2980B9",
                linetype="dashed", linewidth=1, inherit.aes=FALSE) +
      geom_line(data=ref_nb, aes(x=x,y=y,text=NULL), color="#E74C3C",
                linetype="dashed", linewidth=1, inherit.aes=FALSE) +
      theme_classic(base_size=13) +
      labs(title="Mean–Variance relationship",
           x="log10(mean + 1)", y="log10(variance + 1)", color="")
    ggplotly(p, tooltip="text")
  })

  output$s_diag_cv <- renderPlotly({
    d <- s_diag(); req(d)
    df <- data.frame(
      gene     = names(d$means),
      log_mean = log10(d$means + 1),
      cv2      = d$cv2,
      overdispersed = d$overdispersed
    )
    p <- ggplot(df, aes(x=log_mean, y=log10(cv2+1e-6), color=overdispersed,
                        text=paste0(gene,"\nCV²=",round(cv2,3)))) +
      geom_point(size=1.5, alpha=0.6) +
      scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                         labels=c("Poisson-like","Overdispersed")) +
      geom_hline(yintercept=median(log10(df$cv2+1e-6), na.rm=TRUE),
                 color="#8E44AD", linetype="dashed") +
      theme_classic(base_size=13) +
      labs(title="CV² vs Mean  (flat = log-normal; decreasing = NB)",
           x="log10(mean + 1)", y="log10(CV²)", color="")
    ggplotly(p, tooltip="text")
  })

  output$s_diag_disp <- renderPlotly({
    d <- s_diag(); req(d)
    # Dispersion alpha = 1/r per feature. The panel supports TWO readings, which
    # answer different questions, so both are made measurable rather than one
    # being privileged over the other:
    #
    #   CLOUD WIDTH  = how heterogeneous the features are. This is the larger
    #     component of the plot (typically 1.5-2 log units of vertical spread
    #     against ~1 log unit of trend) and it is what SCTransform's dispersion
    #     REGULARIZATION has to fight: SCT does not use per-feature alpha
    #     directly, it shrinks each estimate toward a fitted trend. A wide cloud
    #     therefore means the theta values SCT ends up using are mostly prior
    #     rather than data. Quantified by the IQR in the title and by the
    #     quartile bands.
    #
    #   TREND vs REFERENCE = whether the NB dispersion assumption holds. NB
    #     requires alpha independent of the mean, but a NAIVE reading of the
    #     trend is misleading, because alpha = CV^2 - 1/mu: even perfectly
    #     constant CV^2 produces a rising alpha at low mean purely as
    #     arithmetic. The dashed reference curve draws exactly that expectation,
    #     alpha = median(CV^2) - 1/mu, so the LOESS is judged against the
    #     constant-CV null instead of against a flat line.
    #       LOESS on the reference       -> constant multiplicative error
    #                                       (log-normal regime; LogNormalize,
    #                                        VSN or scp-median)
    #       LOESS flat where the ref rises -> genuine NB, SCTransform warranted
    #       LOESS above the ref at low mu  -> additive noise floor, favors VSN
    #       LOESS above the ref at high mu -> super-quadratic variance; residual
    #                                       heterogeneity among abundant
    #                                       features that no variance-
    #                                       stabilizing transform removes
    n_na <- sum(is.na(d$disp))
    df <- data.frame(
      gene     = names(d$means),
      mu_val   = d$means,
      log_mean = log10(d$means + 1),
      disp     = d$disp,
      overdispersed = d$overdispersed
    ) %>% filter(!is.na(disp) & disp > 0)
    validate(need(nrow(df) > 2,
                  "Too few features have var > mean to estimate NB dispersion."))
    df$log_disp <- log10(df$disp)

    # ── Spread of alpha: the shrinkage-severity readout ───────────────────────
    iqr_ld <- stats::IQR(df$log_disp, na.rm=TRUE)
    fold_iqr <- 10^iqr_ld     # interquartile spread as a fold-change in alpha

    # ── Constant-CV² reference: alpha = median(CV²) - 1/mu ────────────────────
    # Drawn over the observed mean range. Where median(CV²) - 1/mu <= 0 (very
    # low mean) the reference is undefined on a log axis and is simply omitted.
    med_cv2 <- stats::median(d$cv2, na.rm=TRUE)
    ref <- NULL
    if (is.finite(med_cv2) && med_cv2 > 0) {
      mu_seq  <- 10^seq(log10(max(min(df$mu_val, na.rm=TRUE), 1e-6)),
                        log10(max(df$mu_val, na.rm=TRUE)), length.out = 200)
      ref_a   <- med_cv2 - 1/mu_seq
      keep    <- is.finite(ref_a) & ref_a > 0
      if (sum(keep) > 1)
        ref <- data.frame(log_mean = log10(mu_seq[keep] + 1),
                          log_disp = log10(ref_a[keep]))
    }

    p <- ggplot(df, aes(x=log_mean, y=log_disp)) +
      geom_point(aes(color=overdispersed,
                     text=paste0(gene,
                                 "\nalpha (1/r) = ", signif(disp, 4),
                                 "\nresidual CV = ", round(100*sqrt(disp)), "%",
                                 "\nmean = ", signif(mu_val, 4))),
                 size=1.5, alpha=0.55)

    # Quartile bands: the width between them IS the cloud-width measurement,
    # so it is drawn rather than left to the eye.
    # Computed by binning rather than geom_quantile(), which would pull in
    # quantreg/SparseM as new dependencies.
    nb   <- max(4, min(14, floor(nrow(df) / 25)))
    brks <- unique(stats::quantile(df$log_mean, seq(0, 1, length.out = nb + 1),
                                   na.rm = TRUE))
    bands <- NULL
    if (length(brks) > 2) {
      df$.bin <- cut(df$log_mean, breaks = brks, include.lowest = TRUE)
      bands <- do.call(rbind, lapply(split(df, df$.bin), function(z) {
        if (nrow(z) < 5) return(NULL)
        data.frame(log_mean = stats::median(z$log_mean, na.rm = TRUE),
                   q25 = stats::quantile(z$log_disp, 0.25, na.rm = TRUE),
                   q75 = stats::quantile(z$log_disp, 0.75, na.rm = TRUE))
      }))
    }
    if (!is.null(bands) && nrow(bands) > 1) {
      p <- p +
        geom_line(data=bands, aes(x=log_mean, y=q25), inherit.aes=FALSE,
                  color="#7F8C8D", linewidth=0.5, linetype="dashed") +
        geom_line(data=bands, aes(x=log_mean, y=q75), inherit.aes=FALSE,
                  color="#7F8C8D", linewidth=0.5, linetype="dashed")
    }
    p <- p + geom_smooth(method="loess", formula=y ~ x, se=FALSE,
                         color="#2C3E50", linewidth=1.0)

    if (!is.null(ref))
      p <- p + geom_line(data=ref, aes(x=log_mean, y=log_disp),
                         inherit.aes=FALSE, color="#8E44AD",
                         linewidth=0.9, linetype="longdash")

    p <- p +
      scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                         labels=c("Not overdispersed","Overdispersed")) +
      theme_classic(base_size=13) +
      labs(title=sprintf(paste0("NB dispersion \u03b1 = 1/r  |  IQR = %.2f log\u2081\u2080 units ",
                                "(%.1f-fold spread)  |  %d of %d features have var \u2264 mean"),
                         iqr_ld, fold_iqr, n_na, length(d$disp)),
           x="log10(mean + 1)",
           y="log10(\u03b1)   [higher = more overdispersed]",
           color="")
    ggplotly(p, tooltip="text")
  })

  output$s_diag_zero <- renderPlotly({
    d <- s_diag(); req(d)
    df <- data.frame(
      gene      = names(d$zeros),
      obs_zero  = d$zeros,
      pred_zero = d$nb_zero_pred
    ) %>% filter(!is.na(pred_zero))
    p <- ggplot(df, aes(x=pred_zero, y=obs_zero,
                        text=paste0(gene,
                                    "\nObserved=",round(obs_zero,3),
                                    "\nNB predicted=",round(pred_zero,3)))) +
      geom_point(size=1.5, alpha=0.6, color="#3498DB") +
      geom_abline(slope=1, intercept=0, color="red", linetype="dashed") +
      theme_classic(base_size=13) +
      labs(title="Zero fraction: observed vs NB-predicted",
           x="NB-predicted zero fraction", y="Observed zero fraction")
    ggplotly(p, tooltip="text")
  })

  output$s_diag_qq <- renderPlot({
    d <- s_diag(); req(d)
    mat_qq <- d$mat
    n      <- d$n_cells
    n_plt  <- nrow(mat_qq)
    ncol_qq <- min(4, n_plt)
    nrow_qq <- ceiling(n_plt / ncol_qq)
    par(mfrow=c(nrow_qq, ncol_qq), mar=c(3,3,2,1), oma=c(0,0,2,0))
    for (gene in rownames(mat_qq)) {
      x    <- mat_qq[gene, ]
      x    <- x[!is.na(x)]              # NA-aware source keeps missing values
      if (length(x) < 3) { plot.new(); title(main=paste0(gene, " (too few values)"),
                                             cex.main=0.9); next }
      mu   <- mean(x); v <- var(x)
      r    <- if (is.finite(v) && is.finite(mu) && v > mu && mu > 0)
                mu^2 / (v - mu) else 10
      r    <- max(0.1, r)
      obs_q  <- quantile(x, probs=seq(0.05, 0.95, length.out=50))
      theo_q <- qnbinom(seq(0.05, 0.95, length.out=50), mu=mu, size=r)
      plot(theo_q, obs_q, pch=16, cex=0.7, col="#3498DB",
           xlab="Theoretical NB", ylab="Observed",
           main=gene, cex.main=0.9)
      abline(0, 1, col="red", lty=2)
    }
    mtext("QQ plots: Observed vs Theoretical NB quantiles", outer=TRUE, cex=1.1)
  })
