        tags$p(tags$b("✓ Cell cycle scores available: "),
               paste(cc_avail, collapse=", "),
               tags$br(),
               tags$small("Select S.Score + G2M.Score to remove all phase variation, ",
                          "or Score_Diff only to preserve cycling vs non-cycling signal."),
               style="font-size:11px;margin:0;color:#1a5c38;"))
    else NULL
    tagList(
      cc_notice,
      tags$p(tags$b("Regress out (ScaleData vars.to.regress):"),
             style="font-size:12px;margin-bottom:4px;"),
      checkboxGroupInput("s_ln_regress", label=NULL,
                         choices=all_cols, selected=NULL),
      tags$p(tags$small("Optional. Character/factor columns are handled as in SCTransform path."),
             style="color:#7f8c8d;font-size:11px;")
    )
  })

  output$s_sct_regress_ui <- renderUI({
    req(s$seu)
    all_cols <- setdiff(names(s$seu@meta.data), "orig.ident")
    if (!length(all_cols))
      return(tags$p("No metadata columns available.", style="color:grey;"))
    cc_avail  <- intersect(c("S.Score","G2M.Score","Score_Diff"), all_cols)
    cc_notice <- if (length(cc_avail) > 0)
      div(style="background:#eafaf1;border:1px solid #27AE60;border-radius:3px;padding:6px;margin-bottom:6px;",
        tags$p(tags$b("✓ Cell cycle scores available: "),
               paste(cc_avail, collapse=", "),
               tags$br(),
               tags$small("Select S.Score + G2M.Score to remove all phase variation, ",
                          "or Score_Diff only to preserve cycling vs non-cycling signal."),
               style="font-size:11px;margin:0;color:#1a5c38;"))
    else NULL
    tagList(
      cc_notice,
      checkboxGroupInput("s_sct_regress", "Regress out (vars.to.regress):",
                         choices=all_cols, selected=NULL),
      tags$p(tags$small(
        "Select any metadata column. Character/factor columns (e.g. batch) are ",
        "passed directly to SCTransform which handles them via dummy coding internally."),
        style="color:#7f8c8d;font-size:11px;margin-top:4px;")
    )
  })
  output$s_ln_split_ui <- renderUI({
    req(s$seu)
    meta_cols <- names(s$seu@meta.data)
    cc <- meta_cols[sapply(meta_cols, function(c) {
      v <- s$seu@meta.data[[c]]
      (is.character(v)||is.factor(v)) && length(unique(v[!is.na(v)])) >= 2 &&
        length(unique(v[!is.na(v)])) <= 20
    })]
    if (!length(cc)) return(tags$p("No categorical columns with 2–20 groups found.",style="color:grey;"))
    def <- if("sex"%in%cc)"sex" else if("Sex"%in%cc)"Sex" else cc[1]
    selectInput("s_ln_split_var","Split by:",choices=cc,selected=def)
  })

  output$s_sct_split_ui <- renderUI({
    req(s$seu); cc<-s_cat_cols()
    if(length(cc)==0) return(tags$p("No categorical covariates assigned.",style="color:grey;"))
    selectInput("s_sct_split_var","Split by:",choices=cc)
  })

  # ── VSN / scpmed regress + split UI (intensity-native, NA-aware) ─────────────
  # Matches the SCT/LogNorm regress UI so categorical covariate regression is
  # available and consistent across ALL normalization paths.
  .mk_regress_ui <- function(input_id) {
    renderUI({
      req(s$seu)
      md <- s$seu@meta.data
      all_cols <- setdiff(names(md), "orig.ident")
      if (!length(all_cols))
        return(tags$p("No metadata columns available.", style="color:grey;"))

      # Classify columns by type so categoricals are explicitly surfaced.
      is_cat <- vapply(all_cols, function(c) {
        v <- md[[c]]; is.character(v) || is.factor(v) ||
          (is.numeric(v) && length(unique(v[!is.na(v)])) <= 10)
      }, logical(1))
      cat_cols <- all_cols[is_cat]
      num_cols <- all_cols[!is_cat]

      cc_avail  <- intersect(c("S.Score","G2M.Score","Score_Diff"), all_cols)
      cc_notice <- if (length(cc_avail) > 0)
        div(style="background:#eafaf1;border:1px solid #27AE60;border-radius:3px;padding:6px;margin-bottom:6px;",
          tags$p(tags$b("✓ Cell cycle scores available: "),
                 paste(cc_avail, collapse=", "),
                 tags$br(),
                 tags$small("Select S.Score + G2M.Score to remove all phase variation, ",
                            "or Score_Diff only to preserve cycling vs non-cycling signal."),
                 style="font-size:11px;margin:0;color:#1a5c38;"))
      else NULL

      tagList(
        cc_notice,
        tags$p(tags$b("Regress out (NA-aware, pre-PCA):"),
               style="font-size:12px;margin:6px 0 4px 0;"),
        if (length(cat_cols)) tagList(
          tags$p(tags$small(tags$b("Categorical: "),
                            length(cat_cols), " column(s)"),
                 style="color:#2c3e50;font-size:11px;margin:2px 0;"),
          selectizeInput(input_id, label=NULL, choices=cat_cols, selected=NULL,
                         multiple=TRUE,
                         options=list(placeholder="Type to search categorical..."))
        ) else tags$p(tags$small("No categorical columns detected in metadata."),
                      style="color:#c0392b;font-size:11px;"),
        if (length(num_cols)) tagList(
          tags$p(tags$small(tags$b("Numeric: "),
                            paste(num_cols, collapse=", ")),
                 style="color:#7f8c8d;font-size:11px;margin:6px 0 2px 0;"),
          selectizeInput(paste0(input_id,"_num"), label=NULL,
                         choices=num_cols, selected=NULL, multiple=TRUE,
                         options=list(placeholder="Type to search numeric..."))
        ) else NULL,

        # A protein used as a covariate IS a numeric covariate, so it belongs
        # directly under the numeric list and must be visible before any numeric
        # covariate exists.
        uiOutput(paste0(input_id, "_featcov_ui")),

        tags$p(tags$small(
          "Each selected covariate is fitted per protein via an NA-aware linear fit. ",
          "In SCP, total protein content is partly biological \u2014 do NOT regress a depth ",
          "covariate that tracks cell type. Leave empty to skip modeling entirely."),
          style="color:#7f8c8d;font-size:11px;margin-top:6px;"),

        # ── Add back (scplainer reconstruction) ────────────────────────────────
        # Always visible, so the distinction between "fitted" and "removed" is
        # apparent before anything is chosen rather than appearing only after a
        # covariate is ticked. Every modeled variable is offered; the ones ticked
        # here are fitted and then ADDED BACK, the rest are fitted and REMOVED.
        tags$hr(style="margin:8px 0;"),
        tags$p(tags$b("Add effect(s) back after fitting:"),
               style="font-size:12px;margin:6px 0 4px 0;"),
        selectizeInput(paste0(input_id, "_keep"), label=NULL,
                       choices=all_cols, selected=NULL, multiple=TRUE,
                       options=list(placeholder="Type to search variables to add back...")),
        tags$p(tags$small(
          "Ticking a variable here means it is fitted ", tags$b("alongside"),
          " the others and its fitted contribution is then added back, so the ",
          "output is ", tags$b("intercept + retained effect + residual"),
          " (Vanderaa & Gatto, Genome Biology 2025). This matters only when the ",
          "retained variable is correlated with a removed one: a nuisance-only fit ",
          "assigns their shared variance entirely to the nuisance term and the ",
          "biological contrast is shrunk. Fitting both partitions it properly. ",
          tags$b("Applies to scale.data"), " \u2014 the heatmaps and the optional display ",
          "source. The PCA input stays nuisance-only, because adding a grouping ",
          "effect back before computing the embedding you cluster on writes the ",
          "answer into the input."),
          style="color:#7f8c8d;font-size:11px;"),

        # ── The model, printed ────────────────────────────────────────────────
        uiOutput(paste0(input_id, "_formula"))
      )
    })
  }

  # Renders the model actually being fitted, so the spline expansion and the
  # fitted/removed/retained split are visible without reading the code.
  .mk_formula_ui <- function(input_id, spline_input) {
    renderUI({
      req(s$seu)
      cats <- input[[input_id]]              %||% character(0)
      nums <- input[[paste0(input_id,"_num")]]  %||% character(0)
      keep <- input[[paste0(input_id,"_keep")]] %||% character(0)
      sdf  <- suppressWarnings(as.integer(input[[spline_input]] %||% 1))
      if (!is.finite(sdf) || sdf < 1) sdf <- 1

      # A protein covariate is a numeric term like any other. It is named
      # prot_<feature> in metadata and only exists after a run, so it is added to
      # the printed formula here rather than read back from the object.
      fc <- input[[paste0(input_id, "_featcov")]]
      fc <- if (is.null(fc) || identical(fc, "__none__") || !nzchar(fc)) NULL else fc
      fc_col <- if (!is.null(fc)) paste0("prot_", make.names(fc)) else NULL
      if (!is.null(fc_col)) nums <- c(nums, fc_col)

      modeled <- c(cats, nums)
      if (!length(modeled) && !length(keep))
        return(tags$p(tags$small("No covariates selected \u2014 no model is fitted and the ",
                                 "matrix passes through unchanged."),
                      style="color:grey;font-size:11px;margin-top:6px;"))

      # Numeric terms get a spline basis when df > 1; factors never do.
      .term <- function(v) if (v %in% nums && sdf > 1)
                             paste0("ns(", v, ", df=", sdf, ")") else v
      # A variable ticked for add-back is fitted but not removed.
      retained <- intersect(keep, union(modeled, keep))
      removed  <- setdiff(modeled, retained)
      rhs <- vapply(c(removed, retained), .term, character(1))

      div(style=paste0("background:#eef4fb;border-left:4px solid #2980B9;",
                       "border-radius:3px;padding:8px;margin-top:8px;"),
        tags$p(tags$b("Model fitted per protein"),
               style="margin:0 0 3px 0;font-size:12px;color:#1F4E79;"),
        tags$p(paste0("y ~ ", if (length(rhs)) paste(rhs, collapse=" + ") else "1"),
               style=paste0("margin:0 0 4px 0;font-family:Consolas,monospace;",
                            "font-size:12px;color:#1F4E79;")),
        tags$p(tags$small(
          tags$b("Removed: "),
          if (length(removed)) paste(removed, collapse=", ") else "nothing", tags$br(),
          tags$b("Retained (added back): "),
          if (length(retained)) paste(retained, collapse=", ") else "nothing", tags$br(),
          tags$b("scale.data = "),
          if (length(retained)) "intercept + retained effect + residual, z-scored"
          else "intercept + residual, z-scored", tags$br(),
          tags$b("PCA input = "),
          if (length(retained)) "the same, restricted to the PCA feature set"
          else "residual only, restricted to the PCA feature set", tags$br(),
          tags$b("Parameters = "),
          {
            # prot_<feature> is created at run time, so .model_df cannot see it in
            # the current metadata; add its cost (spline df, or 1 when linear).
            .p <- .model_df(s$seu@meta.data, setdiff(c(removed, retained), fc_col), sdf) +
                  (if (!is.null(fc_col)) max(1L, sdf) else 0L)
            sprintf("%d (incl. intercept); a protein needs at least %d observed cells to be fitted",
                    .p, .p + 2L)
          }),
          style="margin:0;color:#1F4E79;font-size:11px;"),
        tags$p(tags$small(
          "Factors cost one parameter per level beyond the first; numeric terms cost ",
          "the spline df (1 when linear). Proteins observed in fewer cells than that ",
          "are left unregressed and are excluded from variable-feature selection, so ",
          "raising the df narrows the analysable feature set. A protein covariate ",
          "narrows it twice over: it costs a parameter, and cells where that protein ",
          "was not detected drop out of every feature's fit."),
          style="margin:3px 0 0 0;color:#7f8c8d;font-size:11px;"),
        if (length(retained))
          tags$p(tags$small(tags$b("Note: "),
                 "the embedding will contain the retained effect by design, so clusters ",
                 "computed from it are partly defined by ",
                 paste(retained, collapse=", "),
                 ". Do not test those variables on the resulting clusters. Untick the ",
                 "add-back boxes for a discovery embedding."),
                 style="margin:4px 0 0 0;color:#8A6D3B;font-size:11px;")
        else NULL,
        if (length(setdiff(retained, modeled)))
          tags$p(tags$small(paste0("Note: ",
                 paste(setdiff(retained, modeled), collapse=", "),
                 " is ticked for add-back but not selected above. It will be fitted ",
                 "for that purpose \u2014 tick it above as well if you also intend it to be ",
                 "part of the nuisance model.")),
                 style="margin:4px 0 0 0;color:#8A6D3B;font-size:11px;")
        else NULL
      )
    })
  }
  output$s_vsn_regress_ui    <- .mk_regress_ui("s_vsn_regress")
  output$s_scpmed_regress_ui <- .mk_regress_ui("s_scpmed_regress")
  # ── A protein as a continuous covariate ─────────────────────────────────────
  # Puts a single feature's own abundance into the model as a covariate. This is
  # reference-protein normalization expressed as a MODEL TERM instead of a
  # division: rather than dividing every value by H4C1 and hoping the ratio is
  # meaningful, the fit estimates how much of each protein's variation tracks
  # H4C1 and removes that much. Two consequences worth knowing.
  #
  # First, the covariate must be near-complete. regress_out_na keeps only cells
  # where `complete.cases(md)` holds, so a cell in which the chosen protein was
  # not detected is dropped from EVERY feature's fit — pick a sparse protein and
  # you silently shrink the whole analysis to its detected cells. The dropdown is
  # therefore ranked by detection rate and labeled with it.
  #
  # Second, this only makes sense if the protein actually tracks the thing you
  # want removed. That is an empirical question, so the note points at the
  # ⑯ Correlations tab, where the candidate can be correlated against
  # log2_Total__mat and nFeature_raw before it is trusted.
  .mk_featcov_ui <- function(input_id) {
    renderUI({
      req(s$seu)
      # Read the RAW store, matching where the covariate's values come from, so
      # the list and the detection percentages describe the same matrix that will
      # be used — and so the control works before any normalization has been run.
      mm <- s$prt_int_raw %||% s$prt_int
      if (is.null(mm))
        return(tags$p(tags$small("Load data first to offer protein covariates."),
                      style="color:grey;font-size:11px;"))
      det <- rowSums(!is.na(mm) & mm > 0) / ncol(mm) * 100
      ord <- order(det, decreasing=TRUE)
      nm  <- .opt_clean(rownames(mm)[ord], "features")
      det <- det[ord][seq_along(nm)]
      choices <- setNames(nm, sprintf("%s  \u2014  %.0f%% of cells", nm, det))
      tagList(
        tags$p(tags$b("Protein as a continuous covariate:"),
               style="font-size:12px;margin:6px 0 4px 0;"),
        selectizeInput(paste0(input_id, "_featcov"), label=NULL,
                       choices=c("(none)"="__none__", choices), selected="__none__",
                       options=list(maxOptions=200, placeholder="Search proteins...")),
        tags$p(tags$small(
          "The selected protein's ", tags$b("raw"), " abundance is taken from the raw ",
          "matrix and ", tags$b("log2-transformed"), ", then enters the model as a numeric ",
          "covariate \u2014 reference-protein normalization done as a model term rather ",
          "than a division. It is logged because the response is on a log scale: a loading ",
          "control shifts the response by a constant per DOUBLING, which is linear in ",
          "log2 and curved in raw intensity. Values \u2264 0 become NA. ",
          tags$b("Pick a near-complete protein: "),
          "cells where it was not detected are dropped from every feature's fit, so a ",
          "protein detected in 60% of cells shrinks the whole analysis to those cells. ",
          "Percentages in the list are detection rates. ",
          tags$b("Check it first in \u246f Correlations: "),
          "correlate the candidate against log2_Total__mat and nFeature_raw. A protein ",
          "that tracks total intensity is acting as a depth proxy and is a reasonable ",
          "loading control; one that does not is removing something else, possibly ",
          "biology. Histones (H4C1, H2A, H3) are the usual choices because their ",
          "abundance scales with cell content rather than cell state \u2014 but verify ",
          "rather than assume, since that scaling can fail in polyploid or ",
          "cycling-heterogeneous populations."),
          style="color:#7f8c8d;font-size:11px;")
      )
    })
  }
  output$s_vsn_regress_featcov_ui    <- .mk_featcov_ui("s_vsn_regress")
  output$s_scpmed_regress_featcov_ui <- .mk_featcov_ui("s_scpmed_regress")

  output$s_vsn_regress_formula    <- .mk_formula_ui("s_vsn_regress",    "s_vsn_spline_df")
  output$s_scpmed_regress_formula <- .mk_formula_ui("s_scpmed_regress", "s_scpmed_spline_df")






  .mk_split_ui <- function(input_id) {
    renderUI({
      req(s$seu)
      cat_cols <- names(s$seu@meta.data)[sapply(s$seu@meta.data, function(x)
        is.character(x) || is.factor(x))]
      cat_cols <- setdiff(cat_cols, "orig.ident")
      if (!length(cat_cols))
        return(tags$p("No categorical columns to split on.", style="color:grey;"))
      selectInput(input_id, "Split by:", choices=cat_cols, selected=cat_cols[1])
    })
  }
  output$s_vsn_split_ui    <- .mk_split_ui("s_vsn_split_var")
  output$s_scpmed_split_ui <- .mk_split_ui("s_scpmed_split_var")

  # ── ② QC: Reference protein normalization (optional, post-filter) ────────────

  # Shared scope — the SINGLE SOURCE OF TRUTH for every s_refnorm_* view and for
  # the normalization itself in s_mat_filt(). It defines:
  #   * prots  — the QC-filtered feature set (s_pass_prots)
  #   * cells  — the QC-filtered cell set, aligned exactly as s_mat_filt() aligns
  #              it (passing cells ∩ matrix columns ∩ metadata rownames)
  #   * ref_ok — whether the selected reference is in the FILTERED feature set
  #   * good   — per-cell logical: does this cell have a usable reference value?
  # Previously each output computed its own scope (the protein list used filtered
  # features but unfiltered cells; the status text validated the reference
  # against unfiltered rownames), so the selector, the status text, the plots and
  # the applied operation could all describe different matrices.
  # Kept deliberately light — one matrix row, no submatrix copy — because
  # s_meta_filt() reads it too.
  s_refnorm_scope <- reactive({
    req(s$prt_int, s$meta)
    prots <- s_pass_prots(); if (!length(prots)) prots <- rownames(s$prt_int)
    cells <- intersect(intersect(s_pass_cells(), colnames(s$prt_int)),
                       rownames(s$meta))
    if (!length(cells)) cells <- intersect(colnames(s$prt_int), rownames(s$meta))

    ref    <- input$s_refnorm_prot
    # Validate against the FILTERED feature set, not rownames(s$prt_int). A
    # protein that has been filtered out cannot be used, and s_mat_filt() would
    # silently skip normalization while the status text still showed a green ✓.
    ref_ok <- length(ref) == 1 && !is.na(ref) && nzchar(ref) && ref %in% prots

    ref_vec <- if (ref_ok) as.numeric(s$prt_int[ref, cells]) else NULL
    good    <- if (ref_ok) !(is.na(ref_vec) | ref_vec <= 0)
               else rep(FALSE, length(cells))
    names(good) <- cells
    if (!is.null(ref_vec)) names(ref_vec) <- cells

    list(prots = prots, cells = cells, ref = ref, ref_ok = ref_ok,
         ref_vec = ref_vec, good = good,
         n_all_prots = nrow(s$prt_int), n_all_cells = ncol(s$prt_int))
  })

  output$s_refnorm_prot_ui <- renderUI({
    sc <- s_refnorm_scope()
    prots <- sc$prots; cells <- sc$cells
    sub   <- s$prt_int[prots, cells, drop=FALSE]

    # Detection within the cells that will actually be normalized …
    det_filt <- rowSums(sub > 0, na.rm=TRUE) / max(length(cells), 1) * 100
    # … and across all loaded cells, shown alongside it for comparison
    det_all  <- rowSums(s$prt_int[prots, , drop=FALSE] > 0, na.rm=TRUE) /
                max(sc$n_all_cells, 1) * 100
    ord <- order(det_filt, decreasing=TRUE)

    # Anchored whole-name match. The previous unanchored pattern
    # ("H4|Hist1|HIST1|h4c|H4c", ignore.case) also matched MYH4, ANKH4 and every
    # HIST1H1/H2/H3, then took whichever happened to come first in row order.
    h4 <- prots[grepl("^(H4|H4C[0-9]+|HIST1H4[A-Z]?|Hist1h4[a-z]?)$",
                      prots, ignore.case=TRUE)]

    # Preserve the current choice: this UI depends on the QC sliders through
    # s_pass_cells()/s_pass_prots(), so it re-renders whenever one of them moves.
    cur <- isolate(input$s_refnorm_prot)
    default_sel <-
      if (!is.null(cur) && cur %in% prots)  cur
      else if (length(h4))                  h4[which.max(det_filt[h4])]
      else if (length(ord))                 prots[ord[1]]
      else                                  prots[1]

    choices <- setNames(prots,
      sprintf("%s  \u2014  %.0f%% of filtered cells (%.0f%% of all)",
              prots, det_filt, det_all))[ord]

    tagList(
      selectizeInput("s_refnorm_prot", "Reference feature:",
                     choices=choices, selected=default_sel,
                     options=list(maxOptions=50, placeholder="Type to search...")),
      tags$p(tags$small(sprintf(
        paste0("Scope: %d QC-passing cells \u00d7 %d retained features ",
               "(of %d \u00d7 %d loaded). Ranked by completeness in the filtered cells."),
        length(cells), length(prots), sc$n_all_cells, sc$n_all_prots)),
        style="color:grey;font-size:11px;")
    )
  })

  output$s_refnorm_status <- renderUI({
    if (!isTRUE(input$s_refnorm_enable))
      return(tags$p("Reference normalization disabled.",
                    style="color:grey;font-size:12px;"))
    sc <- s_refnorm_scope()
    if (!isTRUE(sc$ref_ok)) {
      msg <- if (!length(sc$ref) || is.na(sc$ref) || !nzchar(sc$ref))
               "Select a reference feature above."
             else paste0("'", sc$ref, "' is not in the current filtered feature ",
                         "set \u2014 normalization will NOT be applied. Loosen the ",
                         "sparsity filter or choose another feature.")
      return(tags$p(msg, style="color:#E74C3C;font-size:12px;"))
    }
    n_tot  <- length(sc$cells)
    n_good <- sum(sc$good)
    n_bad  <- n_tot - n_good
    tagList(
      tags$p(paste0("\u2713 Normalizing by: ", sc$ref),
             style="color:#27AE60;font-weight:600;font-size:13px;"),
      tags$p(sprintf("%d of %d QC-passing cells have a usable reference value (%.1f%%)",
                     n_good, n_tot, if (n_tot > 0) n_good/n_tot*100 else 0),
             style="color:#2980B9;font-size:12px;"),
      if (n_bad > 0)
        tags$p(sprintf(paste0("\u26a0 %d cell%s no usable reference value and ",
                              "these will be dropped from the matrix during Seurat object creation."),
                       n_bad,
                       if (n_bad == 1) " has" else "s have",
                       if (n_bad == 1) "is"    else "are"),
               style="color:#E67E22;font-size:12px;font-weight:600;")
      else NULL,
      if (n_good == 0)
        tags$p(paste0("Reference undetected in every filtered cell \u2014 ",
                      "normalization skipped, matrix left unchanged."),
               style="color:#E74C3C;font-size:12px;font-weight:600;")
      else NULL
    )
  })

  output$s_refnorm_detect <- renderPlotly({
    sc <- s_refnorm_scope(); req(isTRUE(sc$ref_ok))
    det_rate <- if (length(sc$good)) mean(sc$good) * 100 else 0
    n_drop   <- sum(!sc$good)
    df <- data.frame(Cell      = sc$cells,
                     Intensity = as.numeric(sc$ref_vec),
                     Detected  = as.logical(sc$good))
    ggplotly(
      ggplot(df, aes(x=Cell, y=Intensity, color=Detected,
                     text=paste0(Cell, "\n", round(Intensity,2)))) +
        geom_point(size=2, alpha=0.8) +
        scale_color_manual(values=c("TRUE"="#27AE60","FALSE"="#E74C3C")) +
        theme_classic(base_size=13) + theme(axis.text.x=element_blank()) +
        labs(title=paste0(sc$ref, " \u2014 detected in ", round(det_rate,1),
                          "% of filtered cells",
                          if (n_drop > 0) paste0(" (", n_drop, " dropped)") else ""),
             x="Cell", y="Intensity", color="Detected"),
      tooltip="text")
  })

  output$s_refnorm_dist <- renderPlotly({
    sc <- s_refnorm_scope(); req(isTRUE(sc$ref_ok))
    ref_vals <- as.numeric(sc$ref_vec)[sc$good]
    req(length(ref_vals) > 0)
    ggplotly(
      ggplot(data.frame(x=ref_vals), aes(x=x)) +
        geom_histogram(bins=40, fill="#3498DB", color="white", alpha=0.85) +
        theme_classic(base_size=13) +
        labs(title=paste0(sc$ref, " (", length(ref_vals),
                          " filtered cells with a detectable intensity)"),
             x="Intensity", y="Count"))
  })

  output$s_refnorm_compare <- renderPlot({
    sc <- s_refnorm_scope()
    mat_before <- s$prt_int[sc$prots, sc$cells, drop=FALSE]
    mat_after  <- tryCatch(s_mat_filt(), error=function(e) mat_before)
    # Cells present before but not after are the ones dropped for lack of a
    # usable reference value. Name them in the subtitle rather than letting the
    # intersect() below silently hide the loss.
    lost  <- setdiff(colnames(mat_before), colnames(mat_after))
    cells <- intersect(colnames(mat_before), colnames(mat_after))
    req(length(cells) > 0)
    
    df <- data.frame(
      Cell   = cells,
      Before = log2(colSums(mat_before[, cells, drop=FALSE], na.rm=TRUE) + 1),
      After  = log2(colSums(mat_after[,  cells, drop=FALSE], na.rm=TRUE) + 1)
    ) %>% tidyr::pivot_longer(-Cell, names_to="Stage", values_to="log2_val")
    
    sub_txt <- if (length(lost) > 0)
      sprintf("%d cell%s dropped: %s%s",
              length(lost), if (length(lost) == 1) "" else "s",
              paste(utils::head(lost, 5), collapse=", "),
              if (length(lost) > 5) ", \u2026" else "")
    else "No cells dropped \u2014 reference detected in every filtered cell"
    ggplot(df, aes(x=reorder(Cell, log2_val), y=log2_val, color=Stage)) +
      geom_point(size=1.5, alpha=0.7) +
      scale_color_manual(values=c("Before"="#E74C3C","After"="#27AE60")) +
      theme_classic(base_size=13) +
      theme(axis.text.x=element_blank(), legend.position="top") +
      labs(title="log2(Total intensity) — before vs after reference normalization",
           subtitle=sub_txt,
           x="Cells", y="log2(Total intensity)", color="")
  })

  # Apply/Reset are no-ops on the matrix — normalization is reactive in
  # s_mat_filt(). These observers log and report the cell loss so that Option-B
  # behavior (drop, never silently) is announced at the moment of activation.
  observeEvent(input$s_apply_refnorm, {
    req(isTRUE(input$s_refnorm_enable))
    sc <- s_refnorm_scope()
    if (!isTRUE(sc$ref_ok)) {
      showNotification(paste0("Reference feature is not in the current filtered ",
                              "feature set \u2014 normalization not applied."),
                       type="error", duration=8)
      return()
    }
    n_bad <- sum(!sc$good)
    s_log(paste0("Ref norm enabled: ", sc$ref, ", scale=", input$s_refnorm_scale,
                 " | usable in ", sum(sc$good), "/", length(sc$cells), " cells",
                 if (n_bad > 0) paste0(" | ", n_bad, " cells dropped") else ""))
    showNotification(paste0("Reference normalization active (", sc$ref, "). ",
                            if (n_bad > 0)
                              paste0(n_bad, " cell(s) dropped for lack of a reference value. ")
                            else "",
                            "Rebuild Seurat object in \u2464 to apply."),
                     type=if (n_bad > 0) "warning" else "message", duration=8)
  })
  observeEvent(input$s_reset_refnorm, {
    updateCheckboxInput(session, "s_refnorm_enable", value=FALSE)
    s_log("Ref norm disabled — checkbox unchecked")
    showNotification("Reference normalization disabled.", type="message", duration=4)
  })
  output$s_sct_view_ui <- renderUI({
    choices <- c("Combined (unintegrated)" = "_full_")
    if (!is.null(s$sct_list) && length(s$sct_list) > 0)
      choices <- c(choices, setNames(names(s$sct_list),
                                     paste0(names(s$sct_list), " (split)")))
    selectInput("s_sct_view", "Viewing:", choices=choices, selected="_full_")
  })

  # Returns the active Seurat object for SCTransform plot tabs
  s_sct_active <- reactive({
    sel <- input$s_sct_view %||% "_full_"
    if (!is.null(s$sct_list) && length(s$sct_list) > 0 && sel != "_full_" &&
        sel %in% names(s$sct_list)) {
      s$sct_list[[sel]]
    } else {
      s$seu
    }
  })

  # ── Plain-language account of the last ⑥ run ────────────────────────────────
  # Everything a user needs in order to know what the numbers on screen are:
  # which matrix was transformed, what was removed, what was kept, and which of
  # the three resulting matrices each downstream step reads. Rendered from the
  # stash, so it describes what ACTUALLY ran rather than the current dropdowns.
  output$s_run_summary <- renderUI({
    d <- s$intensity_diag
    if (is.null(d) || is.null(d$mat))
      return(tags$p(paste0("No intensity-native run stored yet. SCTransform and ",
                           "LogNormalize write directly into the object; this summary ",
                           "describes VSN and scp-median runs."),
                    style="color:grey;font-size:11px;"))
    mth  <- toupper(d$method %||% "?")
    rv   <- d$rv_use %||% character(0)
    sdf  <- d$spline_df %||% 1
    std  <- isTRUE(d$standardize)
    nft  <- length(d$vf %||% character(0))
    dims <- paste0(nrow(d$mat), " features \u00d7 ", ncol(d$mat), " cells")

    row <- function(lbl, txt) tags$tr(
      tags$td(tags$b(lbl), style="padding:2px 8px;vertical-align:top;white-space:nowrap;"),
      tags$td(txt, style="padding:2px 8px;"))

    div(style=paste0("background:#f4f7fb;border-left:4px solid #2980B9;border-radius:3px;",
                     "padding:8px 10px;margin-top:8px;"),
      tags$p(tags$b("What this run did"),
             style="margin:0 0 4px 0;font-size:12px;color:#1F4E79;"),
      tags$table(style="font-size:11px;border-collapse:collapse;",
        row("Input matrix",
            paste0("s$prt_int_raw \u2014 the raw upload with missing values intact. ",
                   "Not the counts layer, so reference normalization from \u2461 does not apply.")),
        row("Transform",
            switch(d$method %||% "",
              "vsn"    = "VSN: values \u2264 0 set to NA, then vsn2() fits an affine per-cell calibration and an arcsinh transform by maximum likelihood.",
              "log2"   = paste0("log2 only: values \u2264 0 set to NA, then log2. NO per-cell ",
                                "normalization \u2014 depth is left entirely to the covariate model, ",
                                "which makes a depth or protein covariate the single place it is ",
                                "handled and its coefficient interpretable."),
              "scpmed" = "scp-median: values \u2264 0 set to NA, each cell divided by the median of its DETECTED features, rescaled to the global median of those medians, then log2.",
              "unknown transform")),
        row("Missing values", "Never imputed. NAs are carried through the transform, the regression, the stored matrix and the statistical tests."),
        row("Removed",
            if (length(rv))
              paste0(paste(rv, collapse=", "),
                     " \u2014 fitted per feature on observed values only",
                     if (sdf > 1) paste0("; continuous terms as a natural spline, df=", sdf) else " (linear)")
            else "nothing \u2014 no covariates were selected"),
        row("Retained (added back)",
            paste0("nothing \u2014 the regression removes the covariates above and adds ",
                   "nothing back. Note the consequence: if a removed covariate is ",
                   "correlated with your biology, part of that biology was removed with ",
                   "it. Compare the two panels on the PCA: data vs regressed tab to see ",
                   "how much separation the removal cost.")),
        row("data layer",
            paste0("the transform output, ", dims, ", NO covariates removed. This is what the ",
                   "proDA / limma engines test, what cell-cycle scoring and the trajectory ",
                   "overlay read, and the default for every feature-level plot. Covariates go ",
                   "into the test design instead, which keeps the degrees of freedom honest.")),
        row("scale.data layer",
            "the same matrix with the covariates above regressed out, then z-scored per protein over observed values, not-detected filled with 0 and clipped to \u00b110. Feeds the heatmaps and is selectable as a display source."),
        row("Matrix the PCA read",
            paste0(if (identical(d$pca_feats %||% "vf", "all"))
                     "ALL features with a computable variance (selection skipped)"
                   else paste0(nft, " variable features"),
                   ", regressed",
                   if (!is.null(d$keep_var))
                     paste0(" with the effect of ", paste(d$keep_var, collapse=", "),
                            " added back (so the embedding contains it by design)")
                   else " (nuisance-only, nothing added back)",
                   ", ",
                   if (std) "standardized to unit variance per feature" else "unstandardized",
                   ", NIPALS/PPCA/BPCA on the NA-containing matrix.")),
        row("scale.data",
            "z-scored on observed values with not-detected filled at 0 and clipped to \u00b110. Heatmaps only \u2014 never a testing input.")
      )
    )
  })

  output$s_sct_status <- renderUI({
    obj     <- s_sct_active()
    lbl     <- input$s_sct_view %||% "_full_"
    grp_lbl <- if (lbl == "_full_") "Combined" else lbl
    method  <- input$s_norm_method %||% "sct"
    has_sct <- !is.null(obj) && "SCT" %in% names(obj@assays)
    has_ln  <- !is.null(obj) && !is.null(input$s_assay) &&
               input$s_assay %in% names(obj@assays) &&
               length(Seurat::VariableFeatures(obj)) > 0
    has_pca <- !is.null(obj) && "pca" %in% names(obj@reductions)
    norm_ok <- if(method=="sct") has_sct else has_ln
    col     <- if(norm_ok && has_pca) "#27AE60" else "#E74C3C"
    norm_lbl <- if(method=="sct") {
      if(has_sct)"✓ SCT" else "✗ SCT"
    } else if(method %in% .NA_AWARE) {
      if(has_ln) paste0("✓ ", toupper(method), " (", length(Seurat::VariableFeatures(obj)),
                        " var proteins, no impute)")
      else paste0("✗ ", toupper(method))
    } else {
      if(has_ln) paste0("✓ LogNorm (", length(Seurat::VariableFeatures(obj)), " var features)")
      else "✗ LogNorm"
    }
    tags$p(paste0("[", grp_lbl, "]  ", norm_lbl, "  ",
                  if(has_pca) "✓ PCA" else "✗ PCA"),
           style=paste0("color:",col,";font-size:13px;font-weight:600;margin-top:8px;"))
  })

  observeEvent(input$s_run_sct, {
    req(s$seu)
    norm_method <- input$s_norm_method %||% "sct"

    # ══════════════════════════════════════════════════════════════════════════
    # PATH C: intensity-native, NA-aware, NO IMPUTATION (VSN / scp median)
    # ══════════════════════════════════════════════════════════════════════════
    if (norm_method %in% .NA_AWARE) {
      req(s$seu)
      if (!requireNamespace("pcaMethods", quietly=TRUE)) {
        showNotification(paste0("Package 'pcaMethods' is required for NA-aware PCA. ",
          "Install: BiocManager::install('pcaMethods')"), type="error", duration=12); return()
      }

      raw <- s$prt_int_raw
      if (is.null(raw)) {
        showNotification(paste0("Raw intensity matrix (s$prt_int_raw) not found — reload data ",
          "so the raw copy is captured. Falling back to count matrix (zeros not distinguishable ",
          "from missing)."), type="warning", duration=10)
        raw <- s$prt_int
      }
      seu_obj  <- s$seu
      assay_nm <- input$s_assay
      cells_use <- colnames(seu_obj)
      feats_seu <- rownames(seu_obj)

      # Reconcile renamed feature IDs (Genes/Peptides/Proteins) back to raw
      # rownames. Two peptide-specific gotchas are handled here:
      #  (1) Seurat's CreateSeuratObject sanitizes feature names, converting
      #      underscores to dashes (raw '_AAAK_' becomes Seurat '-AAAK-'), so we
      #      canonicalize '_' and '-' to a common token on BOTH sides before
      #      matching. (2) ';'-joined groups and make.unique '.1' suffixes.
      canon  <- function(x) gsub("[-_]", "\u01c0", sub("[._][0-9]+$", "", sub(";.*", "", as.character(x))))
      lead   <- function(x) sub(";.*", "", as.character(x))
      strip  <- function(x) canon(x)
      raw_feats    <- rownames(raw)
      common_feats <- intersect(feats_seu, raw_feats)

      if (length(common_feats) < 0.5 * length(feats_seu)) {
        rs <- strip(raw_feats); fs <- strip(feats_seu)
        idx <- match(fs, rs)
        if (sum(!is.na(idx)) > length(common_feats)) {
          keep <- !is.na(idx)
          raw_try <- raw[idx[keep], , drop=FALSE]
          rownames(raw_try) <- feats_seu[keep]   # keep the Seurat-style names
          raw <- raw_try; common_feats <- feats_seu[keep]
        }
        if (length(common_feats) < 0.5 * length(feats_seu) && !is.null(s$prt_map)) {
          pm <- s$prt_map
          best_keep <- common_feats; best_raw <- raw
          for (from_col in names(pm)) {
            for (to_col in names(pm)) {
              if (from_col == to_col) next
              lut    <- setNames(strip(pm[[to_col]]), strip(pm[[from_col]]))
              mapped <- lut[strip(feats_seu)]
              ok     <- !is.na(mapped) & mapped %in% strip(raw_feats)
              if (sum(ok) > length(best_keep)) {
                ridx <- match(mapped[ok], strip(raw_feats))
                raw_try <- raw[ridx, , drop=FALSE]
                rownames(raw_try) <- feats_seu[ok]
                best_raw <- raw_try; best_keep <- feats_seu[ok]
              }
            }
          }
          raw <- best_raw; common_feats <- best_keep
        }
      }
      cells_common <- intersect(cells_use, colnames(raw))
      raw_mat <- raw[intersect(common_feats, rownames(raw)), cells_common, drop=FALSE]
      if (nrow(raw_mat) < 2 || ncol(raw_mat) < 2) {
        ex <- function(v) paste(utils::head(as.character(v), 3), collapse=", ")
        msg <- paste0(
          "Could not align raw intensities to the Seurat object. ",
          "Feature overlap: ", length(intersect(common_feats, rownames(raw))),
          " (Seurat features: ", length(feats_seu), ", raw rows: ", nrow(raw), "). ",
          "Cell overlap: ", length(cells_common),
          " (Seurat cells: ", length(cells_use), ", raw cols: ", ncol(raw), "). ",
          "Example Seurat features [", ex(feats_seu), "] vs raw features [", ex(rownames(raw)), "]. ",
          "Example Seurat cells [", ex(cells_use), "] vs raw cells [", ex(colnames(raw)), "]. ",
          if (is.null(s$prt_map)) "No prt.map loaded to bridge IDs. "
          else paste0("prt.map columns: ", ex(names(s$prt_map)), ". "))
        showNotification(msg, type="error", duration=25)
        s_log(paste0("VSN/scpmed align FAILED — ", msg))
        return()
      }

      # ── transforms (NAs preserved) ───────────────────────────────────────────
      vsn_transform <- function(m) {
        if (!requireNamespace("vsn", quietly=TRUE))
          stop("Package 'vsn' not installed: BiocManager::install('vsn')")
        mm <- m; mm[mm <= 0] <- NA
        fit <- vsn::vsn2(mm)
        vsn::predict(fit, newdata=mm)
      }
      # log2 ONLY: no per-cell normalization of any kind. Values <= 0 become NA
      # (log2 of a non-positive intensity is undefined, and a zero here means
      # not-detected rather than measured-zero), then log2. Rows with fewer than
      # two observations are dropped because their variance is not computable,
      # which every downstream step assumes.
      #
      # Why this is a useful option rather than an omission: VSN and scp-median
      # both remove a per-cell loading component, so any covariate meant to
      # capture loading (a histone, total intensity) is partly redundant after
      # them and can end up fitting noise. Choosing log2-only makes the model the
      # single place depth is handled, so a protein or depth covariate does the
      # whole job and its coefficient is interpretable. It is also the honest
      # baseline for asking how much the normalization actually changed.
      log2_transform <- function(m) {
        mm <- m; mm[mm <= 0] <- NA
        out <- log2(mm)
        out[!is.finite(out)] <- NA
        out[rowSums(!is.na(out)) >= 2, , drop=FALSE]
      }

      scpmed_transform <- function(m, center_feat=FALSE) {
        mm <- m; mm[mm <= 0] <- NA
        cell_med <- apply(mm, 2, median, na.rm=TRUE)
        cell_med[!is.finite(cell_med) | cell_med == 0] <- NA
        global_med <- median(cell_med, na.rm=TRUE)
        mm  <- sweep(mm, 2, cell_med, "/") * global_med
        out <- log2(mm)
        if (isTRUE(center_feat)) {
          feat_med <- apply(out, 1, median, na.rm=TRUE)
          out <- sweep(out, 1, feat_med, "-")
        }
        # Guard against degenerate values/rows that break NIPALS PCA and layer
        # splitting downstream (VSN's vsn2 filters these internally; the hand-rolled
        # scp-median transform must do so explicitly). Non-finite → NA, then drop
        # rows that are all-NA or have <2 observed values (no computable variance).
        out[!is.finite(out)] <- NA
        nobs <- rowSums(!is.na(out))
        keep <- nobs >= 2
        if (any(!keep)) out <- out[keep, , drop=FALSE]
        out
      }

      # ── NA-aware covariate removal (per-protein OLS on observed values) ──────
      # Regress covariates out of the (VSN/scp-median) matrix, NA-aware, per
      # protein. Two upgrades bring this closer to SCTransform's Pearson-residual
      # behavior for continuous covariates such as nFeature:
      #   spline_df  : if >1, continuous covariates enter as a natural cubic spline
      #                basis ns(x, spline_df) so a NONLINEAR depth effect is removed,
      #                not just the linear slope (a straight lm leaves the curved
      #                part of the depth relationship in the residual, which then
      #                re-enters PCA). Factors are left as-is.
      #   standardize: if TRUE, residuals are divided by the per-protein residual SD
      #                (a Pearson-like step) so every protein contributes on a
      #                comparable footing. Without this, high-abundance proteins with
      #                large residual variance dominate the variance-driven PCA and
      #                drag depth structure back in. Used for the PCA INPUT only.
      # For the data layer / testing we call with standardize=FALSE and add the
      # residual back to the observed mean (interpretable VSN scale, variance
      # unchanged). For PCA we call with standardize=TRUE.
      # `keep` implements the scplainer reconstruction. Without it the model is
      # fitted on NUISANCE COVARIATES ONLY and the output is
      #     mean(y_observed) + residual
      # which is correct only when the nuisance covariates are uncorrelated with
      # the biology of interest. When they are correlated — and in single-cell
      # proteomics they usually are, because a bigger cell yields both more
      # protein and more detected features — a nuisance-only fit absorbs the
      # shared part. Writing y = a + b·depth + c·group + e and fitting depth
      # alone gives
      #     b_hat = b + c · cov(depth, group) / var(depth)
      # so the residual retains only part of c·group and picks up a spurious
      # depth-correlated term. The biological contrast is shrunk toward zero.
      #
      # scplainer (Vanderaa & Gatto, Genome Biology 2025) avoids this by fitting
      # the FULL model and reconstructing the display values as
      #     intercept + (retained effect) + residual
      # so shared variance is partitioned by the model rather than assigned
      # wholesale to the nuisance term, and the effect of interest survives
      # intact. Passing `keep` here reproduces that exactly: the named columns
      # enter the design alongside `covs`, and their fitted contribution is added
      # back together with the intercept and the residual.

      # ── NA-aware variable-feature selection (variance, na.rm) ────────────────
      # mode "topn": take the n highest-variance proteins.
      # mode "thresh": take all proteins with variance >= vthresh.

      # ── per-object pipeline: normalize -> regress -> VF -> NIPALS -> DimReduc
      # `pca_feats`: "vf" uses the selected variable features (the default, and what
      # Seurat's routes do); "all" uses every feature with a computable variance and
      # at least 3 observations, skipping selection. VariableFeatures(obj) is set
      # either way, so the Variable Features plot and every feature-list consumer
      # still behave the same — only the PCA input changes.
      run_naaware <- function(obj, norm_mat_full, rv_use, npcs_use, nfeat, pca_method,
                              vf_mode="topn", vf_thresh=NULL, spline_df=1, standardize=FALSE,
                              keep_var=NULL, pca_feats="vf") {
        cells_o  <- colnames(obj)
        m0 <- norm_mat_full[, intersect(cells_o, colnames(norm_mat_full)), drop=FALSE]
        # ── Two regressions, two purposes ──────────────────────────────────────
        # This regression feeds scale.data (and the variable-feature selection).
        # With `keep_var` set it is the scplainer reconstruction:
        #     intercept + retained effect + residual
        # so variance shared between a retained variable and a removed one is
        # partitioned by the joint fit instead of being assigned wholesale to the
        # nuisance term. With keep_var = NULL it is simply nuisance removal.
        m <- regress_out_na(m0, obj@meta.data, rv_use, spline_df=spline_df,
                            standardize=FALSE, keep=keep_var)

        # Same minimum-observation requirement the regression used, so only
        # features that were actually corrected can become variable features.
        min_obs_vf <- .model_df(obj@meta.data,
                                unique(c(rv_use, keep_var)), spline_df) + 2L
        vf <- select_vf(m, nfeat, mode=vf_mode, vthresh=vf_thresh, min_obs=min_obs_vf)
        if (length(vf) < 3) {
          # threshold too strict — fall back to top 50 so PCA can still run
          vf <- select_vf(m, 50, mode="topn", min_obs=min_obs_vf)
        }
        if (length(vf) < 3) {
          # still nothing: relax to the bare 3-observation floor and say so.
          vf <- select_vf(m, 50, mode="topn", min_obs=3)
          s_log(paste0("Variable features: no feature met the covariate model's ",
                       "minimum of ", min_obs_vf, " observations; relaxed to 3. ",
                       "The embedding is built on features the model could not correct."))
        }
        Seurat::VariableFeatures(obj) <- vf

        # Feature set for the PCA. Selection still runs and is still recorded, so
        # the Variable Features diagnostics are unchanged; this decides only what
        # the embedding sees.
        pca_vf <- if (identical(pca_feats, "all")) {
          vv   <- apply(m, 1, stats::var, na.rm=TRUE)
          nobs <- rowSums(!is.na(m))
          rownames(m)[is.finite(vv) & vv > 0 & nobs >= 3]
        } else vf
        if (length(pca_vf) < 3) pca_vf <- vf

        # Write normalized matrix (NAs preserved) into the data layer as DENSE,
        # at FULL assay height and cell order — features absent from the
        # normalized set are filled with NA so dimensions match the assay.
        # ── LAYER CONTRACT (matches SCT and LogNormalize) ──────────────────────
        #   data       = the NORMALIZATION OUTPUT, un-regressed, NAs preserved.
        #                This is the measurement: VSN / scp-median applied to the
        #                raw NA-containing matrix and nothing else. It is what the
        #                proDA / limma engines test, what cell-cycle scoring and
        #                the trajectory overlay read, and what gets exported.
        #   scale.data = the same matrix with covariates REGRESSED OUT, then
        #                z-scored per feature over observed values, not-detected
        #                filled with 0 and clipped to +/-10.
        #
        # Previously `data` held the regressed matrix, which inverted Seurat's
        # convention: anything reading `data` and expecting a measurement got
        # model-adjusted values instead, silently, with no switch and no caption
        # on several panels. Writing the transform output to `data` and confining
        # the correction to `scale.data` makes all three routes behave the same
        # way, so "what is in the data layer" has one answer regardless of method.
        full <- matrix(NA_real_, nrow=nrow(obj), ncol=ncol(obj),
                       dimnames=list(rownames(obj), colnames(obj)))
        feats0 <- intersect(rownames(obj), rownames(m0))
        cells0 <- intersect(colnames(obj), colnames(m0))
        full[feats0, cells0] <- as.matrix(m0[feats0, cells0, drop=FALSE])
        tryCatch(
          SeuratObject::LayerData(obj@assays[[assay_nm]], layer="data") <- full,
          error=function(e) NULL
        )

        # scale.data: covariate-removed and z-scored, built from the REGRESSED
        # matrix `m`.
        # Per protein: center & scale using mean/sd over OBSERVED values only, then
        # fill not-detected cells with 0 (the centered "no information" value) and
        # clip to +/-10 (Seurat's default). The z-score is computed on real values;
        # only the fill imputes. Feeds DimHeatmap / DoHeatmap and is offered as a
        # display source; never feeds testing.
        full_r <- matrix(NA_real_, nrow=nrow(obj), ncol=ncol(obj),
                         dimnames=list(rownames(obj), colnames(obj)))
        feats_in <- intersect(rownames(obj), rownames(m))
        cells_in <- intersect(colnames(obj), colnames(m))
        full_r[feats_in, cells_in] <- as.matrix(m[feats_in, cells_in, drop=FALSE])
        tryCatch({
          zsc <- full_r  # regressed, features x cells, NAs still present
          rm_mean <- rowMeans(zsc, na.rm=TRUE)
          rm_sd   <- apply(zsc, 1, function(r) stats::sd(r, na.rm=TRUE))
          rm_sd[!is.finite(rm_sd) | rm_sd == 0] <- 1     # guard flat/all-NA rows
          zsc <- (zsc - rm_mean) / rm_sd
          zsc[is.na(zsc)] <- 0                            # not-detected -> center
          zsc[zsc >  10]  <- 10                           # clip like ScaleData
          zsc[zsc < -10]  <- -10
          SeuratObject::LayerData(obj@assays[[assay_nm]], layer="scale.data") <- zsc
        }, error=function(e) NULL)

        # PCA input: when standardize=TRUE, recompute residuals on the variable
        # features with Pearson-like per-protein scaling (and the same spline
        # basis) so no single high-variance protein dominates and the nonlinear
        # covariate effect is removed. Otherwise reuse the interpretable matrix.
        if (isTRUE(standardize) && !is.null(rv_use) && length(rv_use) > 0) {
          # PCA INPUT: uses the SAME `keep` as scale.data, so the embedding and the
          # z-scored matrix describe the same model.
          #
          # Why they must match: DimHeatmap takes the top-loading features per PC
          # from reductions$pca and then draws their values from scale.data. If one
          # of those carried the retained effect and the other did not, the heatmap
          # would show one matrix's values under the other matrix's feature
          # ranking, and the PC loadings would not correspond to the picture.
          #
          # The consequence to be aware of: with an effect retained, the embedding
          # deliberately CONTAINS that effect, so clusters computed from it are
          # partly defined by it. Do not then test the retained variable on those
          # clusters — that is circular. For a discovery embedding, leave the
          # add-back boxes unticked; the covariates are then simply removed and the
          # embedding carries only unexplained variation.
          m_pca <- regress_out_na(m0[pca_vf, , drop=FALSE], obj@meta.data, rv_use,
                                  spline_df=spline_df, standardize=TRUE, keep=keep_var)
        } else if (isTRUE(standardize)) {
          # No covariates to regress, but standardizing was requested: z-score per
          # feature over observed values so the PCA input is on the same footing as
          # scale.data. Without this the checkbox silently did nothing whenever the
          # covariate list was empty, and the embedding used raw normalized values
          # while every other matrix was scaled.
          mm  <- m[pca_vf, , drop=FALSE]
          mu  <- rowMeans(mm, na.rm=TRUE)
          sdv <- apply(mm, 1, function(r) stats::sd(r, na.rm=TRUE))
          sdv[!is.finite(sdv) | sdv == 0] <- 1
          m_pca <- (mm - mu) / sdv
        } else {
          m_pca <- m[pca_vf, , drop=FALSE]
        }
        mvf <- m_pca

        # ── Pre-flight clean of the PCA input ──────────────────────────────────
        # pcaMethods rejects an all-NA row or column outright, and NIPALS cannot
        # place a feature or a cell that has essentially no observations. The
        # variable-feature path rarely hits this because selection already removed
        # such features; the ALL-FEATURES path hands over everything, including
        # features whose few observations do not survive the covariate model's
        # complete-cases restriction. So clean here rather than letting pca() error.
        keep_f <- rowSums(is.finite(mvf)) >= 2 &
                  apply(mvf, 1, function(r) { v <- stats::var(r, na.rm=TRUE)
                                              is.finite(v) && v > 0 })
        keep_c <- colSums(is.finite(mvf)) >= 2
        n_drop_f <- sum(!keep_f); n_drop_c <- sum(!keep_c)
        if (n_drop_f > 0 || n_drop_c > 0) {
          mvf    <- mvf[keep_f, keep_c, drop=FALSE]
          pca_vf <- rownames(mvf)          # keep the loadings naming in step
          s_log(paste0("PCA input cleaned: dropped ", n_drop_f,
                       " feature(s) with < 2 observations or zero variance and ",
                       n_drop_c, " cell(s) with < 2 observations."))
        }

        if (nrow(mvf) < 3 || ncol(mvf) < 3)
          stop("PCA input collapsed to ", nrow(mvf), " features x ", ncol(mvf),
               " cells after cleaning. With 'All features' this usually means the ",
               "covariate model's minimum-observation requirement removed most rows \u2014 ",
               "lower the spline df, drop a covariate, or use variable features.")

        n_pcs <- min(npcs_use, ncol(mvf)-1, nrow(mvf)-1)
        if (n_pcs < 2)
          stop("Only ", n_pcs, " principal component(s) can be computed from ",
               nrow(mvf), " features x ", ncol(mvf), " cells.")

        na_pct <- round(100 * mean(!is.finite(mvf)), 1)
        pres <- tryCatch(
          pcaMethods::pca(t(mvf), method=pca_method, nPcs=n_pcs,
                          center=TRUE, scale="none"),
          error = function(e) {
            s_log(paste0("pcaMethods::", pca_method, " FAILED on ", nrow(mvf),
                         " features x ", ncol(mvf), " cells (", na_pct,
                         "% missing), nPcs=", n_pcs, ": ", conditionMessage(e)))
            NULL
          })
        if (is.null(pres))
          stop("pcaMethods::", pca_method, " failed on ", nrow(mvf), " features x ",
               ncol(mvf), " cells with ", na_pct, "% missing values. ",
               if (identical(pca_feats, "all"))
                 paste0("This is the 'All features' path, which passes every feature to ",
                        "NIPALS including sparse ones. Try variable features, or PPCA, ",
                        "which tolerates higher missingness.")
               else "Try a different pcaMethods algorithm or fewer PCs.",
               " See the log for the underlying message.")
        s_log(paste0("NA-aware PCA: ", pca_method, " on ", nrow(mvf), " features x ",
                     ncol(mvf), " cells (", na_pct, "% missing), ", n_pcs, " PCs, ",
                     "feature set = ", pca_feats))

        emb <- pcaMethods::scores(pres)
        rownames(emb) <- colnames(mvf)
        colnames(emb) <- paste0("PC_", seq_len(ncol(emb)))
        # Cells dropped by the clean have no scores; pad them with NA so the
        # DimReduc still spans the object and every downstream lookup by cell name
        # continues to work.
        emb_full <- matrix(NA_real_, nrow=ncol(obj), ncol=ncol(emb),
                           dimnames=list(colnames(obj), colnames(emb)))
        shared_c <- intersect(colnames(obj), rownames(emb))
        emb_full[shared_c, ] <- emb[shared_c, , drop=FALSE]
        emb  <- emb_full
        sdev <- pcaMethods::sDev(pres)

        # Feature loadings — DimHeatmap needs these to pick top features per PC.
        load_mat <- tryCatch({
          L <- pcaMethods::loadings(pres)          # features x PCs
          # Name from the CLEANED pca_vf, not vf: with "All features" the PCA ran on
          # a different (larger) set, and the clean above may have shrunk it again,
          # so anything else would misname every loading and DimHeatmap would pick
          # the wrong features per PC.
          if (nrow(L) != length(pca_vf))
            stop("loadings rows (", nrow(L), ") != features (", length(pca_vf), ")")
          rownames(L) <- pca_vf; colnames(L) <- paste0("PC_", seq_len(ncol(L)))
          L
        }, error=function(e) { s_log(paste0("PCA loadings unavailable: ",
                                            conditionMessage(e))); NULL })

        obj[["pca"]] <- SeuratObject::CreateDimReducObject(
          embeddings = emb, key = "PC_", assay = assay_nm,
          loadings = if(!is.null(load_mat)) load_mat else new(Class="matrix"),
          stdev = as.numeric(sdev))
        obj
      }

      center_feat <- isTRUE(input$s_scpmed_center_feat)
      norm_mat <- tryCatch({
        if (norm_method == "vsn")         vsn_transform(raw_mat)
        else if (norm_method == "log2")   log2_transform(raw_mat)
        else                              scpmed_transform(raw_mat, center_feat)
      }, error=function(e){showNotification(paste0("Normalization failed: ",
                            conditionMessage(e)),type="error",duration=12);NULL})
      if (is.null(norm_mat)) return()

      nfeat <- if (norm_method=="vsn") .num(input$s_vsn_nfeatures, 2000)
               else .num(input$s_scpmed_nfeatures, 2000)
      vf_mode <- if (norm_method=="vsn") (input$s_vsn_vf_mode %||% "topn")
                 else (input$s_scpmed_vf_mode %||% "topn")
      vf_thresh <- if (norm_method=="vsn") input$s_vsn_rv_thresh
                   else input$s_scpmed_rv_thresh
      pca_method <- if (norm_method=="vsn") (input$s_vsn_pca_method %||% "nipals")
                    else (input$s_scpmed_pca_method %||% "nipals")
      rv_cat <- if (norm_method=="vsn") unname(input$s_vsn_regress)
                else unname(input$s_scpmed_regress)
      # Variables ticked for add-back. They are fitted alongside the nuisance
      # covariates and their fitted contribution is added back, so scale.data
      # holds intercept + retained effect + residual. The PCA input is computed
      # separately with keep = NULL, so nothing is added back there.
      keep_var_use <- {
        kv <- if (norm_method=="vsn") input$s_vsn_regress_keep
              else input$s_scpmed_regress_keep
        kv <- intersect(kv %||% character(0), names(s$seu@meta.data))
        if (!length(kv)) NULL else kv
      }
      rv_num <- if (norm_method=="vsn") unname(input$s_vsn_regress_num)
                else unname(input$s_scpmed_regress_num)
      # ── Protein-as-covariate ──────────────────────────────────────────────
      # The feature's per-cell values are taken from the NORMALIZED matrix, so the
      # covariate is on the same scale as the response. Written into metadata as
      # prot_<NAME> and appended to the covariate list, which lets the existing
      # spline / add-back / min_obs machinery treat it like any numeric covariate.
      feat_cov <- {
        fc <- if (norm_method=="vsn") input$s_vsn_regress_featcov
              else input$s_scpmed_regress_featcov
        if (is.null(fc) || identical(fc, "__none__") || !nzchar(fc)) NULL else fc
      }
      feat_cov_col <- NULL
      if (!is.null(feat_cov)) {
        # RAW values, from the ID-reconciled raw matrix. Falls back to the raw
        # store if the feature name did not survive reconciliation.
        fv <- NULL; fv_src <- NA_character_
        if (!is.null(raw_mat) && feat_cov %in% rownames(raw_mat)) {
          fv <- raw_mat[feat_cov, , drop=TRUE];        fv_src <- "raw_mat"
        } else if (!is.null(s$prt_int_raw) && feat_cov %in% rownames(s$prt_int_raw)) {
          fv <- s$prt_int_raw[feat_cov, , drop=TRUE];  fv_src <- "s$prt_int_raw"
        }
        if (is.null(fv)) {
          showNotification(paste0("'", feat_cov, "' is not in the raw matrix \u2014 ",
                                  "protein covariate skipped."), type="warning", duration=9)
        } else {
          feat_cov_col <- paste0("prot_", make.names(feat_cov))
          cells_fv <- intersect(names(fv), colnames(seu_obj))
          vv <- rep(NA_real_, ncol(seu_obj)); names(vv) <- colnames(seu_obj)
          raw_v <- suppressWarnings(as.numeric(fv[cells_fv]))
          # log2 the raw intensities: the response is on a log scale, so a linear
          # term in log2(protein) is the form a loading control actually takes
          # (constant shift per doubling). Values <= 0 become NA rather than -Inf.
          raw_v[!is.finite(raw_v) | raw_v <= 0] <- NA_real_
          vv[cells_fv] <- log2(raw_v)
          seu_obj@meta.data[[feat_cov_col]] <- vv[colnames(seu_obj)]
          n_det <- sum(is.finite(vv)); pct <- round(100*n_det/length(vv), 1)
          s_log(paste0("Protein covariate: ", feat_cov, " -> ", feat_cov_col,
                       " | source=", fv_src, " (RAW), transform=log2",
                       " | detected in ", n_det, "/", length(vv), " cells, ", pct, "%"))
          if (pct < 80)
            showNotification(paste0("'", feat_cov, "' is detected in only ", pct,
                                    "% of cells. Every feature's fit is restricted to ",
                                    "those cells, so the effective sample size drops ",
                                    "accordingly. Prefer a more completely detected protein."),
                             type="warning", duration=12)
        }
      }

      rv_use <- unique(c(rv_cat, rv_num, feat_cov_col))
      if (length(rv_use)==0) rv_use <- NULL
      intmode <- if (norm_method=="vsn") isTRUE(input$s_vsn_intmode)
                 else isTRUE(input$s_scpmed_intmode)
      split_var <- if (norm_method=="vsn") input$s_vsn_split_var
                   else input$s_scpmed_split_var
      # nonlinear/standardized residual settings (for continuous covariate regression)
      # A cleared box here used to crash the run: NA makes use_spline NA and if()
      # errors inside regress_out_na.
      spline_df <- if (norm_method=="vsn") .num(input$s_vsn_spline_df, 1)
                   else .num(input$s_scpmed_spline_df, 1)
      std_resid <- if (norm_method=="vsn") isTRUE(input$s_vsn_std_resid)
                   else isTRUE(input$s_scpmed_std_resid)
      pca_feats_use <- if (norm_method=="vsn") (input$s_vsn_pca_feats %||% "vf")
                       else (input$s_scpmed_pca_feats %||% "vf")
      # NA here reached RunPCA / pcaMethods as nPcs and errored.
      npcs <- min(.num(input$s_sct_npcs, 30), ncol(seu_obj)-1, nrow(seu_obj)-1)
      lbl  <- toupper(norm_method)

      # ── Full settings record ──────────────────────────────────────────────
      # Everything a run depends on, in one line, so a result can be reproduced
      # from the log without reconstructing the state of a dozen widgets.
      s_log(paste0(
        "\u2465 SETTINGS | method=", norm_method,
        " | source=", if (norm_method %in% .NA_AWARE) "s$prt_int_raw (NAs kept)"
                      else "counts layer (NA->0, ceiling)",
        " | covariates=", if (length(rv_use)) paste(rv_use, collapse="+") else "none",
        " | retained=",  if (length(keep_var_use)) paste(keep_var_use, collapse="+") else "none",
        " | spline_df=", spline_df,
        " | standardize=", std_resid,
        " | vf_mode=", vf_mode, if (identical(vf_mode,"thresh")) paste0("(>=", vf_thresh, ")")
                                else paste0("(top ", nfeat, ")"),
        " | pca_features=", pca_feats_use,
        " | pca_method=", pca_method, " | npcs=", npcs,
        " | protein_covariate=", if (!is.null(feat_cov)) feat_cov else "none",
        " | integration_mode=", intmode,
        if (intmode && !is.null(split_var)) paste0(" (split by ", split_var, ")") else "",
        if (identical(norm_method,"scpmed"))
          paste0(" | row_centered=", isTRUE(input$s_scpmed_center_feat)) else "",
        " | ref_norm_from_QC=", isTRUE(input$s_refnorm_enable),
        if (norm_method %in% .NA_AWARE) " (NOT applied on this route)" else ""))

      if (intmode && !is.null(split_var)) {
        showNotification(paste0("Integration mode computes a PCA per group. \u246a Integration ",
                                "for this method reuses the MAIN object's pooled PCA instead, ",
                                "so these per-group PCAs will not be used there. Uncheck it ",
                                "unless you specifically want per-group \u2465 diagnostics."),
                         type="warning", duration=14)
        s_log(paste0("NOTE: integration mode ON for ", norm_method,
                     " \u2014 per-group PCAs are stored in s$sct_list; \u246a Step 1 will rebuild ",
                     "a pooled PCA from the data layer and ignore them."))
        grps <- unique(as.character(seu_obj@meta.data[[split_var]])); grps <- grps[!is.na(grps)]
        if (length(grps) < 2) { showNotification(paste0("'",split_var,"' has <2 groups."),
                                type="error",duration=8); return() }
        withProgress(message=paste0(lbl," + NA-aware PCA per group..."), value=0, {
          obj_list <- Seurat::SplitObject(seu_obj, split.by=split_var)
          obj_list <- lapply(seq_along(obj_list), function(i){
            nm <- names(obj_list)[i]
            incProgress(1/length(obj_list), detail=paste0("Processing ", nm))
            tryCatch(
              run_naaware(obj_list[[nm]], norm_mat, rv_use, npcs, nfeat, pca_method,
                          keep_var = keep_var_use, pca_feats = pca_feats_use,
                          vf_mode=vf_mode, vf_thresh=vf_thresh,
                          spline_df=spline_df, standardize=std_resid),
              error = function(e) {
                # One group failing must not abort the whole split run: report it,
                # return the un-processed object, and let the others complete.
                showNotification(paste0("Group '", nm, "' failed in the NA-aware PCA: ",
                                        conditionMessage(e)), type="error", duration=20)
                s_log(paste0("NA-aware PCA FAILED for group '", nm, "' (pca_feats=",
                             pca_feats_use, "): ", conditionMessage(e)))
                obj_list[[nm]]
              })
          })
          names(obj_list) <- grps; s$sct_list <- obj_list
        })
        # Union of per-group variable features (a protein variable in any group),
        # so the Variable Features plot has something meaningful to highlight.
        vf_union <- unique(unlist(lapply(s$sct_list, Seurat::VariableFeatures)))
        # Selection basis: features are chosen PER GROUP on each group's regressed
        # matrix. The correct variance to plot is therefore the MAX per-group
        # regressed variance (the statistic that determines threshold-mode union
        # membership) — NOT the pooled variance, which inflates when group means
        # differ and would show high-variance points that were never selected.
        sel_stats <- tryCatch({
          per_grp <- lapply(grps, function(g){
            cells_g <- rownames(seu_obj@meta.data)[
              as.character(seu_obj@meta.data[[split_var]]) == g]
            cells_g <- intersect(cells_g, colnames(norm_mat))
            # Same keep as the pipeline, so the Variable Features plot describes the
            # matrix selection actually ran on.
            mg <- regress_out_na(norm_mat[, cells_g, drop=FALSE],
                                 seu_obj@meta.data[cells_g, , drop=FALSE], rv_use,
                                 spline_df=spline_df, standardize=FALSE,
                                 keep=keep_var_use)
            data.frame(gene=rownames(mg),
                       variance=apply(mg, 1, stats::var, na.rm=TRUE),
                       mean=rowMeans(mg, na.rm=TRUE),
                       nobs=rowSums(!is.na(mg)), stringsAsFactors=FALSE)
          })
          genes_all <- Reduce(union, lapply(per_grp, function(d) d$gene))
          # max variance across groups, mean at the arg-max group, total obs
          vmat <- sapply(per_grp, function(d) d$variance[match(genes_all, d$gene)])
          mmat <- sapply(per_grp, function(d) d$mean[match(genes_all, d$gene)])
          omat <- sapply(per_grp, function(d) d$nobs[match(genes_all, d$gene)])
          if (is.null(dim(vmat))) { vmat <- matrix(vmat, ncol=1); mmat <- matrix(mmat, ncol=1); omat <- matrix(omat, ncol=1) }
          vmax <- apply(vmat, 1, max, na.rm=TRUE)
          wmax <- apply(vmat, 1, function(r){ i <- which.max(replace(r, is.na(r), -Inf)); if(length(i)) i else 1L })
          mean_at <- mmat[cbind(seq_along(wmax), wmax)]
          nobs_tot <- apply(omat, 1, function(r) max(r, na.rm=TRUE))
          data.frame(gene=genes_all,
                     mean=mean_at,
                     variance=ifelse(is.finite(vmax), vmax, NA_real_),
                     nobs=nobs_tot, stringsAsFactors=FALSE)
        }, error=function(e) NULL)
        s$intensity_diag <- list(mat = norm_mat, method = norm_method,
                                 vf = vf_union,
                                 regressed = (length(rv_use) > 0 && !is.null(rv_use)),
                                 rv_use = rv_use, spline_df = spline_df,
                                 keep_var = keep_var_use,
                                 pca_feats = pca_feats_use,
                                 standardize = std_resid,
                                 sel_stats = sel_stats,
                                 vf_union = TRUE,
                                 per_group_var = TRUE)
        s_log(paste0(lbl," integration-mode complete (", length(grps),
                     " groups, NA-aware PCA). ", length(vf_union),
                     " variable proteins (union across groups)."))
        showNotification(paste0(lbl," per group done. Go to Integration next."),
                         type="message", duration=8); return()
      }

      withProgress(message=paste0(lbl," + NA-aware PCA..."), value=0, {
        incProgress(0.4, detail="normalize + regress")
        incProgress(0.7, detail="NIPALS PCA")
        seu_obj <- tryCatch(
          run_naaware(seu_obj, norm_mat, rv_use, npcs, nfeat, pca_method,
                      keep_var = keep_var_use, pca_feats = pca_feats_use,
                      vf_mode=vf_mode, vf_thresh=vf_thresh,
                      spline_df=spline_df, standardize=std_resid),
          error = function(e) {
            showNotification(paste0("NA-aware PCA failed: ", conditionMessage(e)),
                             type="error", duration=20)
            s_log(paste0("NA-aware PCA FAILED (pca_feats=", pca_feats_use, "): ",
                         conditionMessage(e)))
            NULL
          })
        if (is.null(seu_obj)) return()
        s$seu <- seu_obj
        # Compute the variance/mean actually used for selection (i.e. AFTER
        # regress_out_na) so the Variable Features plot shows the true basis for
        # red/grey membership rather than pre-regression variance.
        sel_stats <- tryCatch({
          m_sel <- regress_out_na(norm_mat, seu_obj@meta.data, rv_use,
                                  spline_df=spline_df, standardize=FALSE,
                                  keep=keep_var_use)
          data.frame(gene=rownames(m_sel),
                     mean=rowMeans(m_sel, na.rm=TRUE),
                     variance=apply(m_sel, 1, stats::var, na.rm=TRUE),
                     nobs=rowSums(!is.na(m_sel)), stringsAsFactors=FALSE)
        }, error=function(e) NULL)
        # Stash normalized matrix + selected features for the fit diagnostics
        # (meanSdPlot and the variance-vs-mean Variable Features plot).
        s$intensity_diag <- list(mat = norm_mat, method = norm_method,
                                 vf = Seurat::VariableFeatures(seu_obj),
                                 regressed = (length(rv_use) > 0 && !is.null(rv_use)),
                                 rv_use = rv_use, spline_df = spline_df,
                                 keep_var = keep_var_use,
                                 pca_feats = pca_feats_use,
                                 standardize = std_resid,
                                 sel_stats = sel_stats)
        n_var <- length(Seurat::VariableFeatures(seu_obj))
        vf_note <- if(identical(vf_mode,"thresh")) paste0("var>=", vf_thresh) else paste0("top ", nfeat)
        rv_note <- if(!is.null(rv_use)) paste0(" | regress: ",paste(rv_use,collapse=",")) else " | regress: none"
        s_log(paste0(lbl," complete: ", n_var, " variable proteins (", vf_note, "), NA-aware ",
                     toupper(pca_method), " PCA, npcs=", npcs, rv_note,
                     if(norm_method=="scpmed" && center_feat) " | row-centered" else "",
                     " | NO imputation"))
      })
      showNotification(paste0(lbl," + NA-aware PCA complete (no imputation)."),
                       type="message", duration=4)
      return()
    }
    # ══════════════════════ end PATH C ═══════════════════════════════════════

    # ══════════════════════════════════════════════════════════════════════════
    # PATH A: LogNormalize → FindVariableFeatures → ScaleData → RunPCA
    # ══════════════════════════════════════════════════════════════════════════
    if (norm_method == "lognorm") {
      seu   <- s$seu
      npcs  <- min(input$s_sct_npcs, ncol(seu)-1, nrow(seu)-1)
      rv_ln <- unname(input$s_ln_regress)
      if (length(rv_ln) == 0) rv_ln <- NULL

      # Helper: validate + clean regression variables for a given object
      clean_rv <- function(obj, rv) {
        if (is.null(rv) || length(rv) == 0) return(NULL)
        rv <- rv[sapply(rv, function(col) {
          if (!col %in% names(obj@meta.data)) return(FALSE)
          vals <- obj@meta.data[[col]]
          if (is.character(vals)) { vals <- as.factor(vals); obj@meta.data[[col]] <<- vals }
          if (any(is.na(vals))) {
            if (is.factor(vals)) { v2 <- as.character(vals); v2[is.na(v2)] <- "0"; obj@meta.data[[col]] <<- as.factor(v2) }
            else { vals[is.na(vals)] <- 0; obj@meta.data[[col]] <<- vals }
          }
          n_lev <- if(is.factor(obj@meta.data[[col]])) nlevels(droplevels(obj@meta.data[[col]]))
                   else length(unique(obj@meta.data[[col]][!is.na(obj@meta.data[[col]])]))
          n_lev >= 2
        })]
        if (length(rv) == 0) NULL else rv
      }

      # Helper: run full LogNorm pipeline on one object
      ln_pipeline <- function(obj, rv_use, npcs_use, detail_pfx="") {
        assay_nm_local <- input$s_assay

        # ── Helper: join layers and verify "data" exists ────────────────────
        force_join_data <- function(o) {
          tryCatch({
            join_fn <- if (existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                       else if (requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                       else get("JoinLayers")
            o[[assay_nm_local]] <- join_fn(o[[assay_nm_local]])
          }, error=function(e) NULL)
          # Fallback: if "data" still missing, manually collapse all data.* layers
          layer_nms <- tryCatch(names(o@assays[[assay_nm_local]]@layers), error=function(e) character(0))
          if (!"data" %in% layer_nms) {
            data_layers <- grep("^data", layer_nms, value=TRUE)
            if (length(data_layers) > 0) {
              tryCatch({
                # Stack all data.* layers into one matrix and write as "data"
                mats <- lapply(data_layers, function(ln)
                  SeuratObject::LayerData(o@assays[[assay_nm_local]], layer=ln))
                combined <- do.call(cbind, mats)
                # Reorder columns to match cell order
                combined <- combined[, colnames(o), drop=FALSE]
                SeuratObject::LayerData(o@assays[[assay_nm_local]], layer="data") <- combined
              }, error=function(e) NULL)
            } else {
              # Last resort: copy counts → data so FindMarkers has something
              tryCatch({
                cm <- SeuratObject::LayerData(o@assays[[assay_nm_local]], layer="counts")
                SeuratObject::LayerData(o@assays[[assay_nm_local]], layer="data") <- cm
              }, error=function(e) NULL)
            }
          }
          o
        }

        if (!isTRUE(input$s_ln_skip_norm)) {
          obj <- Seurat::NormalizeData(obj, normalization.method="LogNormalize",
                                        scale.factor=.num(input$s_ln_scale_factor, 10000),
                                        assay=assay_nm_local, verbose=FALSE)
          # Force join immediately — Seurat v5 may write data.sample1/data.sample2
          # instead of a unified "data" layer when counts were split at object creation
          obj <- force_join_data(obj)
        } else {
          # Skip NormalizeData — copy counts into data so downstream steps work
          tryCatch({
            cm <- SeuratObject::LayerData(obj@assays[[assay_nm_local]], layer="counts")
            SeuratObject::LayerData(obj@assays[[assay_nm_local]], layer="data") <- cm
          }, error=function(e) {
            tryCatch({
              obj@assays[[assay_nm_local]]@data <<- obj@assays[[assay_nm_local]]@counts
            }, error=function(e2) NULL)
          })
        }
        obj <- Seurat::FindVariableFeatures(obj,
                                             selection.method=input$s_ln_vf_method %||% "vst",
                                             nfeatures=.num(input$s_ln_nfeatures, 2000),
                                             assay=assay_nm_local, verbose=FALSE)
        obj <- Seurat::ScaleData(obj, features=rownames(obj),
                                  vars.to.regress=clean_rv(obj, rv_use),
                                  assay=assay_nm_local, verbose=FALSE)
        n_pcs <- min(npcs_use, ncol(obj)-1, nrow(obj)-1)
        obj <- Seurat::RunPCA(obj, features=Seurat::VariableFeatures(obj),
                               assay=assay_nm_local, npcs=n_pcs, verbose=FALSE)
        obj
      }

      # ── Integration mode: split + normalize per group ──────────────────────
      if (isTRUE(input$s_ln_intmode) && !is.null(input$s_ln_split_var)) {
        split_by <- input$s_ln_split_var
        grps     <- unique(as.character(seu@meta.data[[split_by]]))
        grps     <- grps[!is.na(grps)]
        if (length(grps) < 2) {
          showNotification(paste0("'",split_by,"' has only 1 group — need ≥ 2."),
                           type="error", duration=8); return()
        }
        withProgress(message="LogNorm + PCA per group...", value=0, {
          obj_list <- Seurat::SplitObject(seu, split.by=split_by)
          obj_list <- lapply(seq_along(obj_list), function(i) {
            nm  <- names(obj_list)[i]
            obj <- obj_list[[nm]]
            incProgress(1/length(obj_list), detail=paste0("Processing ", nm))
            ln_pipeline(obj, rv_ln, npcs)
          })
          names(obj_list) <- grps
          s$sct_list <- obj_list
          n_vars <- sapply(names(obj_list), function(nm)
            length(Seurat::VariableFeatures(obj_list[[nm]])))
          s_log(paste0("LogNorm integration mode complete: ",
                       paste(names(n_vars), n_vars, sep="=", collapse=", "), " var features"))
        })
        showNotification(
          paste0("LogNorm per group done (",
                 paste(sapply(names(s$sct_list), function(nm)
                   paste0(nm, ": ", length(Seurat::VariableFeatures(s$sct_list[[nm]])),
                          " var features")), collapse="; "),
                 "). Go to ⑪ Integration next."),
          type="message", duration=8)
        return()
      }

      # ── Single-object mode ─────────────────────────────────────────────────
      withProgress(message="LogNormalize + PCA...", value=0, {
        if (!isTRUE(input$s_ln_skip_norm)) incProgress(0.2, detail="NormalizeData")
        incProgress(0.4, detail="FindVariableFeatures")
        incProgress(0.6, detail="ScaleData")
        incProgress(0.8, detail="RunPCA")
        seu <- ln_pipeline(seu, rv_ln, npcs)
        # Ensure layers joined for Seurat v5 before FindNeighbors/FindClusters
        tryCatch({
          join_fn <- if(existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                     else if(requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                     else get("JoinLayers")
          seu[[input$s_assay]] <- join_fn(seu[[input$s_assay]])
        }, error=function(e) NULL)
        s$seu <- seu
        n_var <- length(Seurat::VariableFeatures(seu))
        skip_note <- if(isTRUE(input$s_ln_skip_norm)) " [NormalizeData skipped]" else ""
        rv_note   <- if(!is.null(rv_ln) && length(rv_ln)>0)
                       paste0(" | vars.to.regress: ", paste(rv_ln, collapse=", "))
                     else " | vars.to.regress: none"
        s_log(paste0("LogNormalize complete: ", n_var, " variable features (method=",
                     input$s_ln_vf_method %||% "vst", ", nfeatures=",
                     .num(input$s_ln_nfeatures, 2000), "), scale.factor=",
                     .num(input$s_ln_scale_factor, 10000), ", npcs=", npcs,
                     rv_note, skip_note))
      })
      skip_note <- if(isTRUE(input$s_ln_skip_norm)) " (NormalizeData skipped)" else ""
      showNotification(paste0("LogNormalize + PCA complete", skip_note, "."), type="message", duration=4)
      return()
    }

    # ══════════════════════════════════════════════════════════════════════════
    # PATH B: SCTransform (original path)
    # ══════════════════════════════════════════════════════════════════════════
    tryCatch({
    withProgress(message="SCTransform...", value=0, {
      seu <- s$seu; rv <- input$s_sct_regress

      # Seurat v5 renames metadata columns: underscores → dashes.
      # Map any selected names that no longer exist to their dash equivalent.
      if (!is.null(rv) && length(rv) > 0) {
        meta_names <- names(seu@meta.data)
        rv <- unname(rv)
        rv <- sapply(rv, function(col) {
          if (col %in% meta_names) return(col)
          # Try dash variant
          col_dash <- gsub("_", "-", col)
          if (col_dash %in% meta_names) return(col_dash)
          return(NA_character_)
        })
        rv <- rv[!is.na(rv)]
        if (length(rv) == 0) rv <- NULL
      }

      if (isTRUE(input$s_sct_intmode) && !is.null(input$s_sct_split_var)) {
        incProgress(0.1, detail="SCT per group (integration mode)")
        obj_list <- Seurat::SplitObject(seu, split.by=input$s_sct_split_var)

        obj_list <- lapply(obj_list, function(obj) {
          rv_grp <- unname(if (!is.null(rv)) intersect(rv, names(obj@meta.data)) else character(0))

          if (length(rv_grp) > 0) {
            rv_keep <- sapply(rv_grp, function(col) {
              vals <- obj@meta.data[[col]]

              # Coerce character → factor for SCTransform dummy coding
              if (is.character(vals)) {
                vals <- as.factor(vals)
                obj@meta.data[[col]] <<- vals
              }

              # Replace NAs with 0 — do not impute
              if (any(is.na(vals))) {
                if (is.factor(vals)) {
                  vals <- as.character(vals)
                  vals[is.na(vals)] <- "0"
                  vals <- as.factor(vals)
                } else {
                  vals[is.na(vals)] <- 0
                }
                obj@meta.data[[col]] <<- vals
              }

              # Drop constant columns — zero variance breaks SCT GLM
              n_lev <- if (is.factor(vals)) nlevels(droplevels(vals))
                       else length(unique(vals[!is.na(vals)]))
              if (n_lev < 2) {
                message(paste0("Dropping '", col,
                               "' from vars.to.regress — constant in this split group"))
                return(FALSE)
              }
              TRUE
            })
            rv_grp <- rv_grp[rv_keep]
          }
          if (length(rv_grp) == 0) rv_grp <- NULL

          # Re-enforce integer storage — SplitObject inherits double from CreateSeuratObject
          tryCatch({
            cm_grp <- SeuratObject::LayerData(obj@assays[[input$s_assay]], layer="counts")
            if (!is.null(cm_grp) && typeof(cm_grp@x) != "integer") {
              cm_grp@x <- as.integer(round(cm_grp@x))
              cm_grp@x[cm_grp@x < 0L] <- 0L
              SeuratObject::LayerData(obj@assays[[input$s_assay]], layer="counts") <- cm_grp
            }
          }, error=function(e) NULL)

          obj <- Seurat::SCTransform(obj, vars.to.regress=rv_grp, verbose=FALSE,
                                     assay=input$s_assay, vst.flavor="v2",
                                     return.only.var.genes=FALSE,
                                     variable.features.n=NULL,
                                     variable.features.rv.th=input$s_sct_rv_thresh)

          # RunPCA per group so elbow/PCA tabs work in the view selector
          n_pcs_grp <- min(input$s_sct_npcs, ncol(obj) - 1, nrow(obj) - 1, 50)
          obj <- Seurat::RunPCA(obj,
                                features = Seurat::VariableFeatures(obj),
                                assay    = "SCT",
                                npcs     = n_pcs_grp,
                                verbose  = FALSE)
          obj
        })

        s$sct_list <- obj_list
        s_log(paste0("SCTransform + PCA per group complete (",
                     length(obj_list), " groups): ",
                     paste(names(obj_list), collapse=", ")))
        showNotification(
          paste0("SCTransform per group done (",
                 paste(sapply(names(obj_list), function(nm)
                   paste0(nm, ": ", length(Seurat::VariableFeatures(obj_list[[nm]])), " var features")),
                   collapse="; "), "). Go to ⑪ Integration next."),
          type="message", duration=8)
        return()
      }

      incProgress(0.2,detail="SCTransform")

      # ── Final count matrix validation (Seurat v5 Assay5 compatible) ──────
      tryCatch({
        assay_obj <- seu@assays[[input$s_assay]]
        cm <- tryCatch(
          SeuratObject::LayerData(assay_obj, layer="counts"),
          error=function(e) tryCatch(
            SeuratObject::LayerData(assay_obj, layer="data"),
            error=function(e2) NULL))

        if (!is.null(cm)) {
          if (!methods::is(cm, "dgCMatrix")) cm <- methods::as(cm, "dgCMatrix")

          # Step 1: replace all non-finite values
          # @x must stay numeric (double) — dgCMatrix requires this
          cm@x[!is.finite(cm@x)] <- 0
          cm@x <- as.integer(round(cm@x))
          cm@x[cm@x < 0L] <- 0L

          # Step 3: cap extreme values — SCTransform NB model fails on
          # very large values (overflow in C++ arg 5)
          max_count <- 1e5
          n_overflow <- sum(cm@x > max_count, na.rm=TRUE)
          if (n_overflow > 0) {
            cm@x[cm@x > max_count] <- max_count
            msg <- paste0(n_overflow, " values capped at ", max_count,
                          " before SCTransform (extreme values cause C++ overflow).")
            showNotification(msg, type="warning", duration=10)
            s_log(paste0("WARNING pre-SCT: ", msg))
          }

          # Validate the object is well-formed before writing back
          tryCatch(methods::validObject(cm), error=function(e) {
            # If still invalid, rebuild from scratch via sparseMatrix
            cm <<- Matrix::sparseMatrix(
              i=cm@i+1L, p=cm@p, x=as.integer(cm@x),
              dims=cm@Dim, dimnames=cm@Dimnames)
          })

          SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="counts") <- cm

          cell_totals <- Matrix::colSums(cm)
          prot_totals <- Matrix::rowSums(cm)
          zero_cells  <- sum(cell_totals == 0)
          zero_prots  <- sum(prot_totals == 0)

          # Step 4: hard-remove zero-sum cells
          if (zero_cells > 0) {
            keep_cells <- colnames(cm)[cell_totals > 0]
            msg <- paste0(zero_cells, " cells with zero total counts removed before SCTransform.")
            showNotification(msg, type="warning", duration=12)
            s_log(paste0("WARNING pre-SCT: ", msg))
            seu <- seu[, keep_cells]
          }
          # Note: all-zero proteins are already removed upstream in s_pass_prots()

          # Final zero-cell check — abort if >50% still zero after cleanup
          cell_totals2 <- Matrix::colSums(
            tryCatch(SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="counts"),
                     error=function(e) cm))
          if (sum(cell_totals2 == 0) > ncol(seu) * 0.5) {
            showNotification(
              paste0("SCTransform aborted: >50% of cells have zero total counts after cleanup. ",
                     "This data is likely already log-normalized. Use LogNormalize instead."),
              type="error", duration=20)
            s_log("SCTransform ABORTED: >50% zero-count cells — use LogNormalize")
            return()
          }
        }
      }, error=function(e)
        s_log(paste0("Count sanitization note: ", conditionMessage(e))))

      rv <- unname(rv)
      if (!is.null(rv) && length(rv) > 0) {
        rv <- rv[sapply(rv, function(col) {
          if (!col %in% names(seu@meta.data)) return(FALSE)
          vals <- seu@meta.data[[col]]

          # Coerce character → factor
          if (is.character(vals)) {
            vals <- as.factor(vals)
            seu@meta.data[[col]] <<- vals
          }

          # Replace NAs with 0 — do not impute
          if (any(is.na(vals))) {
            if (is.factor(vals)) {
              vals <- as.character(vals)
              vals[is.na(vals)] <- "0"
              vals <- as.factor(vals)
            } else {
              vals[is.na(vals)] <- 0
            }
            seu@meta.data[[col]] <<- vals
          }

          # Drop constant columns
          n_lev <- if (is.factor(vals)) nlevels(droplevels(vals))
                   else length(unique(vals[!is.na(vals)]))
          if (n_lev < 2) {
            message(paste0("Dropping '", col, "' — constant in dataset"))
            return(FALSE)
          }
          TRUE
        })]
        if (length(rv) == 0) rv <- NULL
      }

      # ── Final integer enforcement before SCTransform ──────────────────────
      # CreateSeuratObject and JoinLayers both convert @x to double.
      # This is the last point before SCTransform — enforce integer here.
      tryCatch({
        cm_sct <- SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="counts")
        if (!is.null(cm_sct)) {
          cm_sct@x <- as.integer(round(cm_sct@x))
          cm_sct@x[cm_sct@x < 0L] <- 0L
          SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="counts") <- cm_sct
          s_log(paste0("Pre-SCT integer check: typeof(cm@x) = ", typeof(cm_sct@x)))
        }
      }, error=function(e)
        s_log(paste0("Pre-SCT integer enforcement note: ", conditionMessage(e))))

      # ── Pre-SCTransform sparsity diagnostic ──────────────────────────────
      # SCTransform NB-GLM (arg 5 error) fails on proteins detected in very
      # few cells — it cannot estimate dispersion with near-zero variance.
      tryCatch({
        cm_check <- SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="counts")
        if (!is.null(cm_check)) {
          n_cells      <- ncol(cm_check)
          detect_rate  <- Matrix::rowSums(cm_check > 0) / n_cells * 100
          n_sparse     <- sum(detect_rate < 10)   # proteins detected in <10% cells
          n_zero       <- sum(detect_rate == 0)
          if (n_sparse > 0) {
            msg <- paste0(
              n_sparse, " proteins detected in <10% of cells (", n_zero, " in 0%). ",
              "SCTransform may fail on these. ",
              "Recommendation: enable '③ Sparsity reduction' and set to 20%+ ",
              "to remove proteins that cannot be modeled by SCTransform's NB-GLM.")
            showNotification(msg, type="warning", duration=20)
            s_log(paste0("Pre-SCT sparsity warning: ", msg))
          }
        }
      }, error=function(e) NULL)

      seu <- Seurat::SCTransform(seu, vars.to.regress=rv, verbose=FALSE,
                                 assay=input$s_assay, vst.flavor="v2",
                                 return.only.var.genes=FALSE,
                                 variable.features.n=NULL,
                                 variable.features.rv.th=input$s_sct_rv_thresh)
      incProgress(0.7,detail="RunPCA")
      seu <- Seurat::RunPCA(seu, features=Seurat::VariableFeatures(seu),
                            assay="SCT", npcs=input$s_sct_npcs, verbose=FALSE)
      s$seu <- seu
      n_var     <- length(Seurat::VariableFeatures(seu))
      n_total   <- nrow(seu@assays$SCT)
      n_non_var <- n_total - n_var
      rv_used   <- unname(input$s_sct_regress)
      rv_note   <- if(!is.null(rv_used) && length(rv_used)>0)
                     paste0(" | vars.to.regress: ", paste(rv_used, collapse=", "))
                   else " | vars.to.regress: none"
      s_log(paste0("SCTransform complete: ", n_var, " variable / ", n_non_var,
                   " non-variable features (rv.th=", input$s_sct_rv_thresh,
                   "), npcs=", input$s_sct_npcs, rv_note))
    })
    showNotification("SCTransform complete.",type="message",duration=4)
    }, error=function(e) {
      msg <- conditionMessage(e)
      friendly <- if (grepl("arg 5|NaN|foreign function", msg)) {
        paste0("SCTransform failed: proteins with too few detections are causing ",
               "numerical instability in the NB-GLM. ",
               "Fix: enable '③ Sparsity reduction' and set Min % cells to 20% or higher, ",
               "then rebuild the Seurat object and retry. ",
               "(Technical: ", msg, ")")
      } else {
        paste0("SCTransform error: ", msg)
      }
      showNotification(friendly, type="error", duration=25)
      s_log(paste0("SCTransform FAILED: ", msg))
    })
  })

  output$s_varfeat <- renderPlotly({
    obj    <- s_sct_active()
    method <- input$s_norm_method %||% "sct"
    lbl    <- input$s_sct_view %||% "_full_"

    # ── VSN / scp-median: no HVFInfo metadata exists (features set directly),
    #    so draw an NA-aware variance-vs-mean plot from the stashed matrix. ──
    if (method %in% .NA_AWARE) {
      diag <- s$intensity_diag
      req(diag, !is.null(diag$mat))
      run_method <- diag$method %||% method
      dropdown_mismatch <- !identical(run_method, method)
      method <- run_method

      # View-aware: if a specific GROUP is selected (integration mode) and its
      # per-group object exists, compute variance-vs-mean from THAT group's data
      # and variable features — not the pooled stash. Without this, switching the
      # control/treated view leaves this plot unchanged (it was always pooled),
      # which makes VSN and scp-median look identical across views.
      view_sel <- input$s_sct_view %||% "_full_"
      per_group_view <- view_sel != "_full_" && !is.null(s$sct_list) &&
                        view_sel %in% names(s$sct_list)
      if (per_group_view) {
        gobj <- s$sct_list[[view_sel]]
        gm   <- tryCatch(as.matrix(SeuratObject::LayerData(gobj@assays[[input$s_assay]], layer="data")),
                         error=function(e) tryCatch(as.matrix(Seurat::GetAssayData(gobj, layer="data")),
                                                     error=function(e2) NULL))
        if (!is.null(gm)) {
          mu <- rowMeans(gm, na.rm=TRUE); v <- apply(gm, 1, stats::var, na.rm=TRUE)
          nobs <- rowSums(!is.na(gm))
          df <- data.frame(gene=rownames(gm), mean=mu, variance=v, nobs=nobs, stringsAsFactors=FALSE)
          df <- df[is.finite(df$mean) & is.finite(df$variance) & df$variance > 0, , drop=FALSE]
          vf <- Seurat::VariableFeatures(gobj)
          df$is_var <- df$gene %in% vf
          used_regressed <- FALSE   # per-group data layer already reflects processing
        } else per_group_view <- FALSE
      }
      # Prefer the stats actually used for selection (post-regression) so the
      # axes/tooltip agree with red/grey membership. Fall back to the un-regressed
      # matrix (e.g. integration mode, where sel_stats isn't stashed).
      if (!per_group_view) {
      used_regressed <- !is.null(diag$sel_stats)
      if (used_regressed) {
        df <- diag$sel_stats
        df <- df[is.finite(df$mean) & is.finite(df$variance) & df$variance > 0, , drop=FALSE]
      } else {
        m  <- diag$mat
        mu <- rowMeans(m, na.rm=TRUE)
        v  <- apply(m, 1, stats::var, na.rm=TRUE)
        nobs <- rowSums(!is.na(m))
        df <- data.frame(gene=rownames(m), mean=mu, variance=v, nobs=nobs,
                         stringsAsFactors=FALSE)
        df <- df[is.finite(df$mean) & is.finite(df$variance) & df$variance > 0, , drop=FALSE]
      }
      vf <- if (!is.null(diag$vf)) diag$vf else Seurat::VariableFeatures(obj)
      df$is_var <- df$gene %in% vf
      }  # end pooled-only branch
      n_var <- sum(df$is_var); n_non <- sum(!df$is_var)
      n_label <- if(method=="vsn") (.num(input$s_vsn_label_n, 20)) else (.num(input$s_scpmed_label_n, 20))
      top <- head(vf, n_label)
      vf_mode  <- if(method=="vsn") (input$s_vsn_vf_mode %||% "topn") else (input$s_scpmed_vf_mode %||% "topn")
      vf_thr   <- if(method=="vsn") input$s_vsn_rv_thresh else input$s_scpmed_rv_thresh
      mode_note <- if(identical(vf_mode,"thresh") && !is.null(vf_thr))
                     paste0("variance ≥ ", vf_thr)
                   else paste0("top ", length(vf), " by variance")
      title_str <- paste0("[", lbl, "]  ", toupper(method),
                          " variance vs mean  |  ", n_var, " variable / ", n_non,
                          " non-variable  (NA-aware, ", mode_note,
                          if (used_regressed) ", post-regression" else "",
                          if (isTRUE(diag$per_group_var)) ", max per-group variance"
                          else if (isTRUE(diag$vf_union)) ", union across groups" else "", ")",
                          if (dropdown_mismatch) paste0("  ⚠ showing last-run ", toupper(method),
                            " — re-run to update for the current dropdown selection") else "")
      p <- ggplot(df, aes(x=mean, y=variance, color=is_var,
                          text=paste0(gene, "\nmean: ", round(mean,3),
                                      "\nvar: ", round(variance,3),
                                      "\nobs cells: ", nobs))) +
        geom_point(alpha=0.6, size=1.4) +
        scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                           labels=c(paste0("Non-variable (",n_non,")"),
                                    paste0("Variable (",n_var,")"))) +
        geom_text(data=df[df$gene %in% top,], aes(label=gene), size=2.5,
                  hjust=0, vjust=0, nudge_x=0.02, color="#C0392B", inherit.aes=TRUE) +
        theme_classic(base_size=13) +
        labs(title=title_str, x=paste0(toupper(method)," mean (log-scale)"),
             y=if(isTRUE(diag$per_group_var)) "variance (max per-group, na.rm)" else "variance (na.rm)",
             color="")
      # draw the threshold line so the cutoff is visible when in threshold mode
      if (identical(vf_mode,"thresh") && !is.null(vf_thr))
        p <- p + geom_hline(yintercept=vf_thr, linetype="dashed", color="#2980B9")
      return(ggplotly(p, tooltip="text") %>%
               plotly::layout(title=list(text=title_str, font=list(size=12))))
    }

    # Require either SCT assay (SCTransform) or variable features (LogNormalize)
    if (method == "sct") {
      req(obj, "SCT" %in% names(obj@assays))
    } else {
      req(obj, length(Seurat::VariableFeatures(obj)) > 0)
    }

    n_var     <- length(Seurat::VariableFeatures(obj))
    n_total   <- if(method=="sct") tryCatch(nrow(obj@assays$SCT), error=function(e) NA)
                 else tryCatch(nrow(obj@assays[[input$s_assay]]), error=function(e) NA)
    n_non_var <- if (!is.na(n_total)) n_total - n_var else NA
    n_label   <- if(method=="sct") input$s_sct_label_n else (.num(input$s_ln_label_n, 20))

    suffix    <- if(method=="sct") paste0("  (rv.th = ", input$s_sct_rv_thresh, ")")
                 else paste0("  (", input$s_ln_vf_method %||% "vst", ", nfeatures=",
                             .num(input$s_ln_nfeatures, 2000), ")")
    title_str <- paste0("[", lbl, "]  Variable Features  |  ",
                        n_var, " variable  /  ",
                        if(!is.na(n_non_var)) paste0(n_non_var," non-variable") else "? non-variable",
                        suffix)

    tryCatch({
      p_base <- Seurat::VariableFeaturePlot(obj)
      top    <- head(Seurat::VariableFeatures(obj), n_label)
      p_lab  <- Seurat::LabelPoints(plot=p_base, points=top, repel=FALSE,
                                     xnudge=0.05, ynudge=0.05)
      ggplotly(p_lab, tooltip=c("x","y","label")) %>%
        plotly::layout(title=list(text=title_str, font=list(size=13)))

    }, error=function(e) {
      # Fallback: manual plot from meta.features (SCT) or HVG data (LogNorm)
      assay_use <- if(method=="sct") "SCT" else input$s_assay
      mf_raw <- tryCatch(obj@assays[[assay_use]]@meta.features, error=function(e2) NULL)
      if (is.null(mf_raw) || length(mf_raw) == 0) {
        p_empty <- ggplot() + theme_void() +
          labs(title=paste0("Variable feature plot error: ", conditionMessage(e)))
        return(ggplotly(p_empty))
      }

      mf <- as.data.frame(mf_raw, stringsAsFactors=FALSE)
      mf$gene <- rownames(mf)

      gm_col <- NULL
      for (cand in c("gmean","log_gmean","geometric.mean","geomean")) {
        if (cand %in% names(mf) && is.numeric(mf[[cand]])) { gm_col <- cand; break }
      }
      if (is.null(gm_col)) {
        hits <- names(mf)[sapply(names(mf), function(n) grepl("mean",n,ignore.case=TRUE) && is.numeric(mf[[n]]))]
        if (length(hits)) gm_col <- hits[1]
      }
      rv_col <- NULL
      for (cand in c("residual_variance","residual.variance","variance","rv")) {
        if (cand %in% names(mf) && is.numeric(mf[[cand]])) { rv_col <- cand; break }
      }
      if (is.null(rv_col)) {
        hits <- names(mf)[sapply(names(mf), function(n) grepl("var|resid",n,ignore.case=TRUE) && is.numeric(mf[[n]]))]
        if (length(hits)) rv_col <- hits[1]
      }

      if (is.null(gm_col) || is.null(rv_col)) {
        p_empty <- ggplot() + theme_void() +
          labs(title="Cannot find gmean/residual_variance columns in SCT@meta.features")
        return(ggplotly(p_empty))
      }

      top       <- head(Seurat::VariableFeatures(obj), n_label)
      mf$is_top <- mf$gene %in% top
      mf$x_val  <- as.numeric(mf[[gm_col]])
      mf$y_val  <- as.numeric(mf[[rv_col]])

      if (!grepl("log", gm_col, ignore.case=TRUE)) mf$x_val <- log10(mf$x_val + 1)

      p <- ggplot(mf, aes(x=x_val, y=y_val, color=is_top,
                          text=paste0(gene, "\n", rv_col, ": ", round(y_val, 4)))) +
        geom_point(alpha=0.7, size=1.5) +
        scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                           labels=c(paste0("Non-variable (",n_non_var,")"),
                                    paste0("Variable (",n_var,")"))) +
        geom_text(data=mf[mf$is_top,], aes(label=gene), size=2.5,
                  hjust=0, vjust=0, nudge_x=0.02, color="#C0392B") +
        theme_classic(base_size=13) +
        labs(title=title_str,
             x=paste0("log10(",gm_col,"+1)"), y=rv_col, color="")

      ggplotly(p, tooltip="text")
    })
  })

  # ── Static variable-feature plot (PDF export) ───────────────────────────────
  # The on-screen version above returns a plotly object and branches three ways
  # by normalization route. The PDF export used to call VariableFeaturePlot()
  # directly, which meant it (a) read the global object instead of the view
  # selected in ⑥, and (b) failed outright on VSN / scp-median / log2, where no
  # HVFInfo metadata exists because variable features are assigned directly.
  # This mirrors the same three branches and returns a plain ggplot, so the
  # exported figure matches what is on screen on every route.
  .build_varfeat_static <- function(fs = 12) {
    obj    <- tryCatch(s_sct_active(), error=function(e) NULL)
    method <- input$s_norm_method %||% "sct"
    lbl    <- input$s_sct_view %||% "_full_"

    # ── VSN / scp-median / log2: NA-aware variance-vs-mean from the stash ──
    if (method %in% .NA_AWARE) {
      diag <- s$intensity_diag
      if (is.null(diag) || is.null(diag$mat))
        stop("No intensity-native run stored yet \u2014 run \u2465 with VSN, scp-median ",
             "or log2 before exporting this plot.", call.=FALSE)
      run_method <- diag$method %||% method
      method     <- run_method

      # Same view-awareness as the screen: a per-group view plots THAT group's
      # matrix and variable features, not the pooled stash.
      view_sel <- lbl
      per_group_view <- view_sel != "_full_" && !is.null(s$sct_list) &&
                        view_sel %in% names(s$sct_list)
      df <- NULL; vf <- NULL; used_regressed <- FALSE
      if (per_group_view) {
        gobj <- s$sct_list[[view_sel]]
        gm <- tryCatch(as.matrix(SeuratObject::LayerData(gobj@assays[[input$s_assay]], layer="data")),
                       error=function(e) tryCatch(as.matrix(Seurat::GetAssayData(gobj, layer="data")),
                                                   error=function(e2) NULL))
        if (!is.null(gm)) {
          mu <- rowMeans(gm, na.rm=TRUE); v <- apply(gm, 1, stats::var, na.rm=TRUE)
          df <- data.frame(gene=rownames(gm), mean=mu, variance=v,
                           nobs=rowSums(!is.na(gm)), stringsAsFactors=FALSE)
          df <- df[is.finite(df$mean) & is.finite(df$variance) & df$variance > 0, , drop=FALSE]
          vf <- Seurat::VariableFeatures(gobj)
        } else per_group_view <- FALSE
      }
      if (!per_group_view) {
        used_regressed <- !is.null(diag$sel_stats)
        if (used_regressed) {
          df <- diag$sel_stats
          df <- df[is.finite(df$mean) & is.finite(df$variance) & df$variance > 0, , drop=FALSE]
        } else {
          m  <- diag$mat
          df <- data.frame(gene=rownames(m), mean=rowMeans(m, na.rm=TRUE),
                           variance=apply(m, 1, stats::var, na.rm=TRUE),
                           nobs=rowSums(!is.na(m)), stringsAsFactors=FALSE)
          df <- df[is.finite(df$mean) & is.finite(df$variance) & df$variance > 0, , drop=FALSE]
        }
        vf <- if (!is.null(diag$vf)) diag$vf else tryCatch(Seurat::VariableFeatures(obj),
                                                           error=function(e) character(0))
      }
      if (is.null(df) || !nrow(df)) stop("No finite variance-vs-mean values to plot.", call.=FALSE)
      df$is_var <- df$gene %in% vf
      n_var <- sum(df$is_var); n_non <- sum(!df$is_var)
      n_label <- if (method=="vsn") .num(input$s_vsn_label_n, 20) else .num(input$s_scpmed_label_n, 20)
      top     <- head(vf, n_label)
      vf_mode <- if (method=="vsn") (input$s_vsn_vf_mode %||% "topn") else (input$s_scpmed_vf_mode %||% "topn")
      vf_thr  <- if (method=="vsn") input$s_vsn_rv_thresh else input$s_scpmed_rv_thresh
      mode_note <- if (identical(vf_mode,"thresh") && !is.null(vf_thr))
                     paste0("variance \u2265 ", vf_thr)
                   else paste0("top ", length(vf), " by variance")
      title_str <- paste0("[", lbl, "]  ", toupper(method),
                          " variance vs mean  |  ", n_var, " variable / ", n_non,
                          " non-variable  (NA-aware, ", mode_note,
                          if (used_regressed) ", post-regression" else "",
                          if (isTRUE(diag$per_group_var)) ", max per-group variance"
                          else if (isTRUE(diag$vf_union)) ", union across groups" else "", ")")
      p <- ggplot(df, aes(x=mean, y=variance, color=is_var)) +
        geom_point(alpha=0.6, size=1.4) +
        scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                           labels=c(paste0("Non-variable (",n_non,")"),
                                    paste0("Variable (",n_var,")"))) +
        theme_classic(base_size=fs) +
        labs(title=title_str, x=paste0(toupper(method)," mean (log-scale)"),
             y=if (isTRUE(diag$per_group_var)) "variance (max per-group, na.rm)" else "variance (na.rm)",
             color="")
      p <- p + .varfeat_labels(df[df$gene %in% top, , drop=FALSE], fs)
      if (identical(vf_mode,"thresh") && !is.null(vf_thr))
        p <- p + geom_hline(yintercept=vf_thr, linetype="dashed", color="#2980B9")
      return(p)
    }

    # ── SCTransform / LogNormalize ──────────────────────────────────────────
    if (is.null(obj))
      stop("No Seurat object available yet \u2014 build it in \u2464 and normalize in \u2465.", call.=FALSE)
    if (method == "sct") {
      if (!"SCT" %in% names(obj@assays))
        stop("No SCT assay on the selected object \u2014 run \u2465 with SCTransform first.", call.=FALSE)
    } else if (!length(tryCatch(Seurat::VariableFeatures(obj), error=function(e) character(0)))) {
      stop("No variable features on the selected object \u2014 run \u2465 first.", call.=FALSE)
    }

    n_var   <- length(Seurat::VariableFeatures(obj))
    n_total <- if (method=="sct") tryCatch(nrow(obj@assays$SCT), error=function(e) NA)
               else tryCatch(nrow(obj@assays[[input$s_assay]]), error=function(e) NA)
    n_non_var <- if (!is.na(n_total)) n_total - n_var else NA
    n_label   <- if (method=="sct") .num(input$s_sct_label_n, 20) else .num(input$s_ln_label_n, 20)
    suffix    <- if (method=="sct") paste0("  (rv.th = ", input$s_sct_rv_thresh, ")")
                 else paste0("  (", input$s_ln_vf_method %||% "vst", ", nfeatures=",
                             .num(input$s_ln_nfeatures, 2000), ")")
    title_str <- paste0("[", lbl, "]  Variable Features  |  ", n_var, " variable  /  ",
                        if (!is.na(n_non_var)) paste0(n_non_var," non-variable") else "? non-variable",
                        suffix)

    p <- tryCatch({
      p_base <- Seurat::VariableFeaturePlot(obj)
      top    <- head(Seurat::VariableFeatures(obj), n_label)
      # repel=FALSE matches the screen and avoids ggrepel's "too many overlaps"
      # warning turning into an empty label layer at export dimensions.
      Seurat::LabelPoints(plot=p_base, points=top, repel=FALSE,
                          xnudge=0, ynudge=0) +
        theme_classic(base_size=fs) + labs(title=title_str)
    }, error=function(e) NULL)
    if (!is.null(p)) return(p)

    # Fallback: build from meta.features (same column discovery as the screen).
    assay_use <- if (method=="sct") "SCT" else input$s_assay
    mf_raw <- tryCatch(obj@assays[[assay_use]]@meta.features, error=function(e) NULL)
    if (is.null(mf_raw) || length(mf_raw) == 0)
      stop("VariableFeaturePlot failed and ", assay_use,
           "@meta.features is empty \u2014 nothing to plot.", call.=FALSE)
    mf <- as.data.frame(mf_raw, stringsAsFactors=FALSE); mf$gene <- rownames(mf)
    .pick <- function(cands, pattern) {
      for (cn in cands) if (cn %in% names(mf) && is.numeric(mf[[cn]])) return(cn)
      hits <- names(mf)[vapply(names(mf), function(n)
        grepl(pattern, n, ignore.case=TRUE) && is.numeric(mf[[n]]), logical(1))]
      if (length(hits)) hits[1] else NULL
    }
    gm_col <- .pick(c("gmean","log_gmean","geometric.mean","geomean"), "mean")
    rv_col <- .pick(c("residual_variance","residual.variance","variance","rv"), "var|resid")
    if (is.null(gm_col) || is.null(rv_col))
      stop("Cannot find gmean / residual_variance columns in ", assay_use,
           "@meta.features.", call.=FALSE)
    top       <- head(Seurat::VariableFeatures(obj), n_label)
    mf$is_top <- mf$gene %in% top
    mf$x_val  <- as.numeric(mf[[gm_col]])
    mf$y_val  <- as.numeric(mf[[rv_col]])
    if (!grepl("log", gm_col, ignore.case=TRUE)) mf$x_val <- log10(mf$x_val + 1)
    pl <- ggplot(mf, aes(x=x_val, y=y_val, color=is_top)) +
      geom_point(alpha=0.7, size=1.5) +
      scale_color_manual(values=c("FALSE"="grey70","TRUE"="#E74C3C"),
                         labels=c(paste0("Non-variable (",n_non_var,")"),
                                  paste0("Variable (",n_var,")"))) +
      theme_classic(base_size=fs) +
      labs(title=title_str, x=paste0("log10(",gm_col,"+1)"), y=rv_col, color="")
    lab_df <- mf[mf$is_top, , drop=FALSE]
    if (nrow(lab_df)) {
      lab_df$gene_lab <- lab_df$gene; lab_df$mean <- lab_df$x_val; lab_df$variance <- lab_df$y_val
      pl <- pl + .varfeat_labels(lab_df, fs)
    }
    pl
  }

  # Gene labels for the static variable-feature plot. ggrepel when available
  # (export dimensions give it room to work), plain geom_text otherwise.
  .varfeat_labels <- function(lab_df, fs) {
    if (is.null(lab_df) || !nrow(lab_df)) return(NULL)
    if (requireNamespace("ggrepel", quietly=TRUE))
      ggrepel::geom_text_repel(data=lab_df, aes(label=gene), size=fs/4,
                               color="#C0392B", max.overlaps=Inf,
                               inherit.aes=TRUE, show.legend=FALSE)
    else
      geom_text(data=lab_df, aes(label=gene), size=fs/4, hjust=0, vjust=0,
                nudge_x=0.02, color="#C0392B", inherit.aes=TRUE, show.legend=FALSE)
  }

  # ── Mean–SD fit diagnostic (vsn::meanSdPlot) for VSN / scp-median ────────────
  # ══════════════════════════════════════════════════════════════════════════════
  # ⑥ PCA COMPARISON — data layer vs regressed matrix
  # ══════════════════════════════════════════════════════════════════════════════
  # Two PCAs of the same cells and the same features, differing ONLY in whether
  # the selected covariates have been regressed out:
  #
  #   DATA LAYER  the normalization output as stored, nothing removed. If this
  #               separates by a technical variable, that variable belongs in the
  #               model. This is the "before" picture.
  #
  #   REGRESSED   after the covariates are removed and each feature is z-scored by
  #               its residual SD. This is the matrix the stored reductions$pca was
  #               built from, so it is the reduction ⑦ embeddings and ⑧
  #               clustering actually use. Structure that survives here is
  #               structure the covariates do not explain.
  #
  # Both panels are z-scored per feature over observed values, so per-feature
  # scaling is NOT a difference between them — otherwise a few high-variance
  # proteins would dominate the left panel and any apparent change in separation
  # could come from the missing scaling rather than from the regression.
  #
  # Reading it: more separation is not better. Regressing a covariate that
  # correlates with a grouping always reduces the separation between those groups,
  # which is arithmetic rather than evidence. A drop tells you the covariate and
  # the grouping share variance; it does not say whether that variance was biology
  # the covariate absorbed or an artifact it correctly removed.

  s_capca <- reactiveVal(NULL)


  output$s_capca_color_ui <- renderUI({
    req(s$seu)
    selectInput("s_capca_color", "Color by:",
                choices=.opt_clean(names(s$seu@meta.data), "variables"),
                selected=if ("seurat_clusters" %in% names(s$seu@meta.data))
                           "seurat_clusters" else names(s$seu@meta.data)[1])
  })

  output$s_capca_note <- renderUI({
    cr <- s_capca()
    if (is.null(cr))
      return(tags$p(paste0("Run ⑥ with VSN or scp-median first, then press ",
                           "▶ Run component analysis."),
                    style="color:grey;font-size:12px;"))
    tags$div(style=paste0("background:#f4f7fb;border-left:4px solid #2980B9;",
                          "border-radius:3px;padding:8px 10px;margin:6px 0;"),
      tags$p(tags$b("How to read the two panels"),
             style="margin:0 0 3px 0;font-size:12px;color:#1F4E79;"),
      tags$p(tags$small(
        tags$b("Data layer"), " \u2014 the normalization output, nothing removed. If this ",
        "separates by a technical variable, that is the effect you need in the model. ",
        tags$b("Regressed"), " \u2014 the matrix the stored PCA was built from and the ",
        "reduction ⑦ / ⑧ cluster on. With no effect retained, structure here is ",
        "structure the covariates do not explain. With an effect retained, that ",
        "effect is present by design, so separation along it is expected rather ",
        "than discovered."),
        style="margin:0;color:#1F4E79;font-size:11px;"),
      tags$p(tags$small(
        tags$b("More separation is not better. "),
        "Regressing a covariate that correlates with your grouping will ALWAYS reduce ",
        "the separation between groups \u2014 that is arithmetic, not evidence. Losing ",
        "separation means the covariate and the grouping share variance; it does not ",
        "say whether that shared variance is biology the covariate stole, or an ",
        "artifact the covariate correctly removed. Those two cases look identical ",
        "here. To tell them apart, check whether the covariate differs between your ",
        "groups (\u246f Correlations, grouped), whether an external technical variable ",
        "(run, plate) explains that difference, and whether the loadings driving the ",
        "separation are plausible biology or simply the most abundant features."),
        style="margin:5px 0 0 0;color:#8A6D3B;font-size:11px;"),
      tags$p(tags$small(sprintf(
        paste0("%d features \u00d7 %d cells | removed in the right panel: %s | retained: %s"),
        cr$nfeat, cr$ncell,
        # `rv` is every covariate in the model; a variable also ticked for add-back
        # is fitted but NOT removed, so listing it as removed was wrong.
        { .rm <- setdiff(cr$rv, cr$kv %||% character(0))
          if (length(.rm)) paste(.rm, collapse=", ")
          else if (!length(cr$rv)) "nothing \u2014 the two panels are identical"
          else "nothing (every covariate is retained)" },
        if (length(cr$kv %||% character(0))) paste(cr$kv, collapse=", ") else "nothing")),
        style="margin:4px 0 0 0;color:grey;font-size:11px;"),
      {
        pv_txt <- vapply(cr$res, function(z) {
          if (is.null(z) || is.null(z$pve) || length(z$pve) < 2) return(NA_character_)
          sprintf("%s: PC1 %.1f%%, PC2 %.1f%% (first 5 = %.1f%%)",
                  z$label, z$pve[1], z$pve[2], sum(z$pve[seq_len(min(5, length(z$pve)))]))
        }, character(1))
        pv_txt <- pv_txt[!is.na(pv_txt)]
        if (!length(pv_txt)) NULL else
          tags$p(tags$small(tags$b("Variance explained \u2014 "),
                 paste(pv_txt, collapse="  |  "), tags$br(),
                 "A regression that removed a dominant nuisance effect should LOWER PC1's ",
                 "share, because the largest single source of variance is gone. PC1 rising ",
                 "instead means what remains is more concentrated \u2014 which is what you want ",
                 "if the covariate was noise, and a warning sign if it was correlated with ",
                 "your biology."),
                 style="margin:3px 0 0 0;color:#1F4E79;font-size:11px;")
      }
    )
  })

  observeEvent(input$s_run_capca, {
    diag <- s$intensity_diag
    m0 <- .norm_mat(s$seu)
    if (is.null(m0) || is.null(diag)) {
      showNotification(paste0("No NA-aware normalized data layer found. Run ⑥ with ",
                              "VSN or scp-median first."), type="error", duration=9); return()
    }
    if (!requireNamespace("pcaMethods", quietly=TRUE)) {
      showNotification("pcaMethods is required. BiocManager::install('pcaMethods')",
                       type="error", duration=10); return()
    }
    md   <- s$seu@meta.data
    cells <- intersect(colnames(m0), rownames(md))
    m0    <- m0[, cells, drop=FALSE]; md <- md[cells, , drop=FALSE]
    rv    <- intersect(diag$rv_use %||% character(0), names(md))
    sdf   <- diag$spline_df %||% 1
    pcam  <- diag$pca_method %||% "nipals"

    withProgress(message="Component analysis...", value=0, {
      # Feature set. "Variable" uses the set the stored PCA was built on, so the
      # right-hand panel reproduces reductions$pca. "All" skips selection
      # entirely, which is the check on whether the selection step itself is
      # shaping the structure you see.
      if (identical(input$s_capca_feats %||% "vf", "all")) {
        keep <- rowSums(!is.na(m0)) >= 3 &
                is.finite(apply(m0, 1, stats::var, na.rm=TRUE)) &
                apply(m0, 1, stats::var, na.rm=TRUE) > 0
        feats <- rownames(m0)[keep]
      } else {
        feats <- intersect(Seurat::VariableFeatures(s$seu), rownames(m0))
        if (length(feats) < 3) feats <- select_vf(m0, 2000, mode="topn")
      }
      if (length(feats) < 3) {
        showNotification("Fewer than 3 usable features.", type="error", duration=8); return()
      }
      sub <- m0[feats, , drop=FALSE]

      .pca <- function(mat, lab) {
        np <- min(10, ncol(mat)-1, nrow(mat)-1)
        if (np < 2) return(NULL)
        pr <- tryCatch(pcaMethods::pca(t(mat), method=pcam, nPcs=np,
                                       center=TRUE, scale="none"),
                       error=function(e) NULL)
        if (is.null(pr)) return(NULL)
        sc  <- pcaMethods::scores(pr)
        r2c <- tryCatch(as.numeric(pcaMethods::R2cum(pr)), error=function(e) NULL)
        # Per-PC share from the cumulative curve; fall back to sDev^2 if R2cum is
        # unavailable for the chosen method.
        pve <- if (!is.null(r2c) && length(r2c)) c(r2c[1], diff(r2c)) * 100 else {
          sd_v <- tryCatch(as.numeric(pcaMethods::sDev(pr)), error=function(e) NULL)
          if (!is.null(sd_v) && sum(sd_v^2) > 0) sd_v^2 / sum(sd_v^2) * 100 else NULL
        }
        list(scores=sc, load=pcaMethods::loadings(pr),
             r2=r2c, pve=pve, label=lab)
      }

      # ── The three panels must differ ONLY in what is modeled ────────────────
      # regress_out_na(standardize=TRUE) z-scores each feature by its residual SD.
      # If the unmodeled panel were left unstandardized, it would differ from the
      # others in TWO ways at once — no regression AND no per-feature scaling — so
      # a few high-variance (usually abundant) proteins would dominate it and any
      # apparent gain in separation could come from the missing scaling rather
      # than from the missing regression. That would make the comparison
      # uninterpretable, which is the one thing this panel exists to provide.
      # So every panel is z-scored per feature over OBSERVED values only, and the
      # regression is the sole difference between them.
      .zs <- function(mm) {
        mu <- rowMeans(mm, na.rm=TRUE)
        sd <- apply(mm, 1, function(r) stats::sd(r, na.rm=TRUE))
        sd[!is.finite(sd) | sd == 0] <- 1
        (mm - mu) / sd
      }

      incProgress(0.15, detail="unmodeled")
      res <- list(unmodeled = .pca(.zs(sub), "Unmodeled (data layer)"))

      incProgress(0.3, detail="regressed")
      # Same `keep` the pipeline used, so this panel reproduces reductions$pca
      # rather than describing a model the object was not built from.
      kv <- diag$keep_var
      m_res <- if (length(rv))
                 regress_out_na(sub, md, rv, spline_df=sdf, standardize=TRUE, keep=kv)
               else .zs(sub)
      res$residual <- .pca(m_res,
        if (!length(rv)) "Regressed (no covariates selected)"
        else if (!is.null(kv)) paste0("Regressed (", paste(kv, collapse=", "), " retained)")
        else "Regressed (nuisance removed)")

      s_capca(list(res=res, rv=rv, kv=kv, nfeat=length(feats),
                   ncell=length(cells), md=md))
    })
    s_log(paste0("PCA comparison: ", length(feats), " features, data layer vs ",
                 if (length(rv)) paste0("regressed (", paste(rv, collapse=", "), ")")
                 else "no covariates selected"))
  })

  output$s_capca_plot <- renderPlot({
    cr <- s_capca()
    validate(need(!is.null(cr), "Press \u25b6 Run component analysis."))
    cc <- input$s_capca_color
    # Continuous covariates (depth, intensity, scores) must get a gradient, not one
    # hue per distinct value: nFeature_raw has as many levels as there are cells,
    # which produces an unreadable legend and hides the gradient that is the whole
    # point of coloring by it. Same >10-distinct-values rule the PCA-Technical
    # panel uses, so the two panels behave consistently.
    raw_vals <- if (!is.null(cc) && cc %in% names(cr$md)) cr$md[[cc]] else NULL
    is_cont  <- !is.null(raw_vals) && is.numeric(raw_vals) &&
                length(unique(raw_vals[!is.na(raw_vals)])) > 10

    dfs <- lapply(names(cr$res), function(k) {
      z <- cr$res[[k]]
      if (is.null(z)) return(NULL)
      sc <- z$scores
      vals <- if (is.null(raw_vals)) rep("all", nrow(sc)) else cr$md[rownames(sc), cc]
      # Percent variance is a property of each PANEL's own decomposition, so it is
      # carried in the strip label. A faceted plot has a single shared x-axis
      # label, but PC1 explains a different share in each panel.
      pv  <- z$pve
      lab <- if (!is.null(pv) && length(pv) >= 2)
               sprintf("%s\nPC1 %.1f%% | PC2 %.1f%%", z$label, pv[1], pv[2])
             else z$label
      data.frame(PC1=sc[,1], PC2=sc[,2], panel=lab,
                 Color=if (is_cont) suppressWarnings(as.numeric(vals))
                        else as.factor(as.character(vals)),
                 stringsAsFactors=FALSE)
    })
    d <- do.call(rbind, dfs)
    validate(need(!is.null(d) && nrow(d) > 0, "No components to draw."))
    d$panel <- factor(d$panel, levels=unique(d$panel))   # keep the run order
    p <- ggplot(d, aes(PC1, PC2, color=Color)) +
      geom_point(size=1.8, alpha=0.85) +
      facet_wrap(~ panel, scales="free") +
      theme_classic(base_size=13) +
      labs(color=cc,
           title="Component analysis \u2014 same cells, three models",
           subtitle=paste0("Left to right: before modeling, after nuisance removal ",
                           "(the discovery view), and the retained effect plus residuals"),
           caption=paste0("pcaMethods NIPALS on the NA-containing matrix; no imputation. ",
                          "Percentages are each panel's share of the variance in ITS OWN ",
                          "input, so they are not comparable across panels as absolute ",
                          "amounts \u2014 only as concentration of structure."))
    if (is_cont) {
      p <- p + scale_color_viridis_c(option="plasma")   # matches PCA-Technical
    } else if (length(unique(d$Color)) > 24) {
      # Too many discrete levels to read: almost always a numeric column stored as
      # character. Say so rather than drawing a 90-entry legend.
      p <- p + theme(legend.position="none") +
        labs(caption=paste0("pcaMethods NIPALS on the NA-containing matrix; no imputation. ",
                            "Legend suppressed: ", length(unique(d$Color)), " levels in '",
                            cc, "' \u2014 if this is a numeric variable, convert it in \u2462."))
    }
    p
  })

  output$s_capca_load <- renderDT({
    cr <- s_capca()
    validate(need(!is.null(cr), "Press \u25b6 Run component analysis."))
    z <- cr$res$residual
    validate(need(!is.null(z), "No loadings available."))
    ld <- z$load
    tb <- data.frame(feature=rownames(ld),
                     PC1=round(ld[,1], 4),
                     PC2=round(if (ncol(ld) > 1) ld[,2] else NA_real_, 4),
                     stringsAsFactors=FALSE)
    tb <- tb[order(-abs(tb$PC1)), , drop=FALSE]
    datatable(tb, rownames=FALSE,
              caption=paste0("Top loadings \u2014 ", z$label,
                             ". These are the features driving the separation."),
              options=list(pageLength=10, scrollX=TRUE))
  })

  # ── Covariate shape diagnostic ──────────────────────────────────────────────
  # For each continuous covariate currently selected for regression, fit per
  # feature (observed values only) a linear model and natural-spline models of
  # increasing df, and compare them by nested F-test and AIC. Reports how often
  # the curve wins, which is the evidence for choosing a spline df.
  #
  # The answer feeds two places: the ⑥ embedding regression AND the ⑨ / ⑫ test
  # designs, which now share the same basis. A covariate whose effect is curved
  # is otherwise only half-adjusted — the linear part removed, the curvature left
  # in the residual — and residual curvature both inflates residual variance and
  # biases the group coefficient whenever the covariate is unbalanced across the
  # groups being compared.
  s_covshape <- reactiveVal(NULL)

  observeEvent(input$s_run_covshape, {
    diag <- s$intensity_diag
    if (is.null(diag) || is.null(diag$mat)) {
      showNotification("Run VSN or scp-median normalization first.", type="error", duration=8)
      return()
    }
    method <- diag$method %||% (input$s_norm_method %||% "sct")
    covs <- if (method == "vsn") unname(input$s_vsn_regress_num)
            else if (method %in% .NA_AWARE) unname(input$s_scpmed_regress_num)
            else character(0)
    covs <- intersect(covs %||% character(0), names(s$seu@meta.data))
    if (!length(covs)) {
      showNotification(paste0("Select at least one continuous covariate in the \u2465 ",
                              "regression list first."), type="warning", duration=9)
      return()
    }
    if (!requireNamespace("splines", quietly=TRUE)) {
      showNotification("Package 'splines' unavailable.", type="error", duration=8); return()
    }

    m  <- as.matrix(diag$mat)
    md <- s$seu@meta.data
    cells <- intersect(colnames(m), rownames(md))
    m  <- m[, cells, drop=FALSE]; md <- md[cells, , drop=FALSE]

    # NA reached sample(n = NA) and max(2L, NA).
    n_feat  <- min(as.integer(.num(input$s_covshape_nfeat, 300)), nrow(m))
    max_df  <- max(2L, as.integer(.num(input$s_covshape_maxdf, 5)))
    set.seed(42)                            # reproducible sample, like the QQ panel
    idx <- sample(seq_len(nrow(m)), n_feat)

    withProgress(message="Testing covariate shape...", value=0, {
      res  <- list()
      pts  <- list()
      for (ci in seq_along(covs)) {
        cn <- covs[ci]
        incProgress(1/length(covs), detail=cn)
        x <- suppressWarnings(as.numeric(as.character(md[[cn]])))
        if (sum(is.finite(x)) < 10 || stats::sd(x, na.rm=TRUE) == 0) next
        nuniq  <- length(unique(x[is.finite(x)]))
        dfs    <- 2:min(max_df, max(2, nuniq - 1))
        n_ok   <- 0L
        win_df <- integer(0)
        better <- setNames(integer(length(dfs)), as.character(dfs))
        d_aic  <- setNames(numeric(0), character(0))
        aic_by_df <- vector("list", length(dfs)); names(aic_by_df) <- as.character(dfs)

        for (i in idx) {
          y  <- m[i, ]
          ok <- is.finite(y) & is.finite(x)
          if (sum(ok) < (max(dfs) + 4)) next          # need df for the widest model
          n_ok <- n_ok + 1L
          fit0 <- tryCatch(stats::lm(y[ok] ~ x[ok]), error=function(e) NULL)
          if (is.null(fit0)) next
          aic0 <- stats::AIC(fit0)
          best_df <- 1L; best_aic <- aic0
          for (jj in seq_along(dfs)) {
            dfu <- dfs[jj]
            B <- tryCatch(splines::ns(x[ok], df=dfu), error=function(e) NULL)
            if (is.null(B)) next
            fit1 <- tryCatch(stats::lm(y[ok] ~ B), error=function(e) NULL)
            if (is.null(fit1)) next
            av <- tryCatch(stats::anova(fit0, fit1), error=function(e) NULL)
            pv <- if (!is.null(av) && nrow(av) >= 2) av[["Pr(>F)"]][2] else NA_real_
            if (is.finite(pv) && pv < 0.05) better[jj] <- better[jj] + 1L
            a1 <- stats::AIC(fit1)
            aic_by_df[[jj]] <- c(aic_by_df[[jj]], aic0 - a1)
            if (is.finite(a1) && a1 < best_aic) { best_aic <- a1; best_df <- dfu }
          }
          win_df <- c(win_df, best_df)
        }
        if (n_ok < 5) next

        med_gain <- vapply(aic_by_df, function(z)
                      if (length(z)) stats::median(z, na.rm=TRUE) else NA_real_, numeric(1))
        pct_bet  <- round(100 * better / n_ok, 1)
        # Recommendation: the df with the highest median AIC gain, but only if a
        # meaningful share of features actually improve; otherwise linear.
        best_j <- if (all(!is.finite(med_gain))) NA_integer_ else which.max(med_gain)
        rec <- if (is.na(best_j) || !is.finite(med_gain[best_j]) ||
                   med_gain[best_j] <= 2 || pct_bet[best_j] < 20) 1L else dfs[best_j]

        res[[cn]] <- list(cov=cn, n_features=n_ok, dfs=dfs, pct_better=pct_bet,
                          median_aic_gain=round(med_gain, 2),
                          mode_best_df=as.integer(names(sort(table(win_df),
                                                             decreasing=TRUE))[1]),
                          recommend=rec)

        # Points for the visual: each feature centered on its own observed mean, so
        # all features share one y-scale and the common shape is visible.
        keep_i <- idx[seq_len(min(120, length(idx)))]
        sub <- m[keep_i, , drop=FALSE]
        cent <- sweep(sub, 1, apply(sub, 1, function(z) mean(z, na.rm=TRUE)), "-")
        pts[[cn]] <- data.frame(
          covariate = cn,
          x = rep(x, each=nrow(cent)),
          y = as.numeric(cent),
          stringsAsFactors = FALSE)
      }
      s_covshape(list(res=res, pts=do.call(rbind, pts), method=method,
                      n_sampled=n_feat))
    })
    s_log(paste0("Covariate shape tested on ", n_feat, " features for: ",
                 paste(covs, collapse=", ")))
  })

  output$s_covshape_summary <- renderUI({
    cs <- s_covshape()
    if (is.null(cs))
      return(tags$p(paste0("Select continuous covariates in the \u2465 regression list, ",
                           "then press \u25b6 Test covariate shape."),
                    style="color:grey;font-size:12px;"))
    if (!length(cs$res))
      return(tags$p("No covariate had enough finite values to test.",
                    style="color:#E74C3C;font-size:12px;"))
    rows <- lapply(cs$res, function(r) {
      tags$tr(
        tags$td(tags$b(r$cov), style="padding:3px 8px;"),
        tags$td(r$n_features, style="padding:3px 8px;"),
        tags$td(paste0(paste0("df", r$dfs, ": ", r$pct_better, "%"), collapse="  |  "),
                style="padding:3px 8px;"),
        tags$td(paste0(paste0("df", r$dfs, ": ", r$median_aic_gain), collapse="  |  "),
                style="padding:3px 8px;"),
        tags$td(tags$b(if (r$recommend > 1) paste0("spline df=", r$recommend) else "linear"),
                style=paste0("padding:3px 8px;color:",
                             if (r$recommend > 1) "#E67E22" else "#27AE60", ";"))
      )
    })
    tagList(
      tags$table(style="font-size:11px;border-collapse:collapse;margin-bottom:6px;",
        tags$thead(tags$tr(
          tags$th("Covariate", style="padding:3px 8px;text-align:left;"),
          tags$th("Features fitted", style="padding:3px 8px;text-align:left;"),
          tags$th("% where spline beats linear (F-test p<0.05)", style="padding:3px 8px;text-align:left;"),
          tags$th("Median AIC gain", style="padding:3px 8px;text-align:left;"),
          tags$th("Suggested", style="padding:3px 8px;text-align:left;"))),
        tags$tbody(rows)),
      tags$p(tags$small(
        "A suggestion of \u201clinear\u201d means the curve is not earning its degrees of ",
        "freedom (median AIC gain \u2264 2, or fewer than 20% of features improved). ",
        "Set the chosen df in the method options above; the \u2468 / \u246b test designs ",
        "inherit it unless overridden on the Markers tab."),
        style="color:grey;font-size:11px;")
    )
  })

  output$s_covshape_plot <- renderPlot({
    cs <- s_covshape()
    validate(need(!is.null(cs) && !is.null(cs$pts) && nrow(cs$pts) > 0,
                  "Press \u25b6 Test covariate shape to draw the covariate-abundance relationship."))
    df <- cs$pts[is.finite(cs$pts$x) & is.finite(cs$pts$y), , drop=FALSE]
    validate(need(nrow(df) > 20, "Too few finite values to plot."))
    ggplot(df, aes(x=x, y=y)) +
      geom_point(alpha=0.06, size=0.5, color="grey40") +
      geom_smooth(method="lm", formula=y ~ x, se=FALSE,
                  color="#2980B9", linewidth=0.9, linetype="dashed") +
      geom_smooth(method="loess", formula=y ~ x, se=FALSE,
                  color="#E67E22", linewidth=1.1) +
      facet_wrap(~ covariate, scales="free_x") +
      theme_classic(base_size=13) +
      labs(title="Feature abundance vs covariate, each feature centered on its own mean",
           subtitle="Blue dashed = linear fit; orange = LOESS. Divergence between them is the curvature a spline would capture.",
           x="Covariate value", y="Centered abundance")
  })

  # Mean–SD fit check, shared by the panel and the PDF export. stop() instead of
  # validate() for the guards, so the export handler can surface the same
  # messages on its error page rather than writing a blank PDF.
  .build_meansd <- function(fs = 13) {
    method <- input$s_norm_method %||% "sct"
    if (!method %in% .NA_AWARE)
      stop("Mean–SD plot is available for VSN and scp-median normalization only.", call.=FALSE)
    diag <- s$intensity_diag
    if (is.null(diag) || is.null(diag$mat))
      stop("Run VSN or scp-median normalization first.", call.=FALSE)
    if (!requireNamespace("vsn", quietly=TRUE))
      stop("Package 'vsn' is required. Install: BiocManager::install('vsn')", call.=FALSE)
    method <- diag$method %||% method   # describe what was actually run

    # View-aware: use the selected group's data layer in integration mode, so the
    # fit check reflects the group shown in the view selector (matches the elbow).
    view_sel <- input$s_sct_view %||% "_full_"
    if (view_sel != "_full_" && !is.null(s$sct_list) && view_sel %in% names(s$sct_list)) {
      gobj <- s$sct_list[[view_sel]]
      m <- .norm_mat(gobj)
      view_note <- paste0(" [", view_sel, "]")
    } else {
      m <- .norm_mat(s$seu); view_note <- ""
    }
    if (is.null(m) || nrow(m) <= 10)
      stop("No NA-aware normalized data layer to check. Re-run ⑥.", call.=FALSE)
    # meanSdPlot needs a finite matrix. Use observed values only — drop features
    # with too few observations rather than imputing (keeps the check honest).
    nobs   <- rowSums(!is.na(m))
    thr_n  <- max(3, 0.3*ncol(m))
    n_drop <- sum(nobs < thr_n)
    m <- m[nobs >= thr_n, , drop=FALSE]

    res <- tryCatch(
      vsn::meanSdPlot(m, ranks=TRUE, plot=FALSE),
      error=function(e) NULL)

    if (is.null(res)) {
      # Fallback: some vsn/meanSdPlot versions reject NAs. Restrict to complete
      # features for the plot only (clearly noted), still no imputation.
      mc <- m[stats::complete.cases(m), , drop=FALSE]
      if (nrow(mc) < 10)
        stop("Too few fully-observed proteins to draw the Mean–SD plot without imputing.",
             call.=FALSE)
      res <- vsn::meanSdPlot(mc, ranks=TRUE, plot=FALSE)
      note <- paste0("\n(computed on ", nrow(mc), " fully-observed proteins)")
    } else note <- paste0("\n(", nrow(m), " proteins, SD/mean over observed cells; ",
                          n_drop, " dropped below ", round(100*thr_n/ncol(m)),
                          "% detection)")

    ttl <- paste0(toupper(method), " mean–SD fit check", view_note, note,
                  "  —  flat red line = variance stabilised")
    if (!is.null(res$gg) && inherits(res$gg, "ggplot")) {
      res$gg + ggplot2::ggtitle(ttl) + theme_classic(base_size=fs)
    } else {
      # very old vsn returns base-graphics; redraw from returned components
      df <- data.frame(rank=res$rank, sd=res$sd)
      ggplot(df, aes(rank, sd)) +
        geom_point(alpha=0.3, size=.pdf_pt(0.6), color="grey50") +
        geom_line(data=data.frame(px=res$px, py=res$py), aes(px, py),
                  color="red", linewidth=1) +
        theme_classic(base_size=fs) +
        labs(title=ttl, x="rank(mean)", y="sd")
    }
  }

  output$s_meansd <- renderPlot({
    p <- tryCatch(.build_meansd(13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  output$s_elbow <- renderPlotly({
    obj <- s_sct_active(); req(obj, "pca" %in% names(obj@reductions))
    sd_v <- obj@reductions$pca@stdev
    df_e <- data.frame(PC=seq_along(sd_v),StdDev=sd_v)
    lbl  <- input$s_sct_view %||% "_full_"
    ggplotly(ggplot(df_e,aes(x=PC,y=StdDev))+geom_point(size=3,color="#2980B9")+geom_line(color="#2980B9")+
               theme_classic(base_size=13)+labs(title=paste0("Elbow — ",lbl),x="PC",y="Std Dev"))
  })

  s_pca_df <- reactive({
    obj <- s_sct_active(); req(obj, "pca" %in% names(obj@reductions))
    df_p <- as.data.frame(Seurat::Embeddings(obj,"pca")[,1:2])
    colnames(df_p) <- c("PC1","PC2"); df_p$Cell <- rownames(df_p)
    df_p
  })

  s_pve <- reactive({
    obj <- s_sct_active(); req(obj, "pca" %in% names(obj@reductions))
    sd_v <- obj@reductions$pca@stdev
    round(sd_v^2/sum(sd_v^2)*100,1)
  })

  # PCA — Biological: user-selectable color variable
  output$s_pca_bio_col_ui <- renderUI({
    obj <- s_sct_active(); req(obj)
    cc       <- s_cat_cols()
    all_cols <- names(obj@meta.data)
    selectInput("s_pca_bio_col","Color by (biological variable):",
                choices=all_cols,
                selected=if(length(cc)>0 && cc[1] %in% all_cols) cc[1] else all_cols[1])
  })

  output$s_pca_bio <- renderPlotly({
    req(s_pca_df(), input$s_pca_bio_col)
    obj  <- s_sct_active(); req(obj)
    df_p <- s_pca_df(); pve <- s_pve()
    lbl  <- input$s_sct_view %||% "_full_"
    cc   <- input$s_pca_bio_col
    # .lvl_factor rather than as.factor: s_sct_active() does NOT pass through
    # .apply_level_order, so the covariate arrives with alphabetical levels and
    # the drag-to-order control in ③ was being ignored here.
    df_p$Color <- if(cc %in% names(obj@meta.data)) .lvl_factor(obj@meta.data[df_p$Cell, cc], cc) else factor("All")
    df_p$Label <- if("ID" %in% names(obj@meta.data)) obj@meta.data[df_p$Cell,"ID"] else df_p$Cell
    p <- ggplot(df_p,aes(x=PC1,y=PC2,color=Color,text=Label))+
      geom_point(size=3,alpha=0.8)+theme_classic(base_size=13)+
      labs(title=paste0("[",lbl,"] PCA — ",cc),color=cc,
           x=paste0("PC1 (",pve[1],"%)"),y=paste0("PC2 (",pve[2],"%)"))+
      # One resolver for every covariate including seurat_clusters, so this plot
      # cannot drift from the cluster plots or from the PDF export.
      { .scale_col_for(cc, levels(df_p$Color), na.value="grey70") }
    ggplotly(p,tooltip=c("text","x","y"))
  })

  # PCA — Technical: single color OR faceted multi-feature overlay
  output$s_pca_tech_col_ui <- renderUI({
    obj <- s_sct_active(); req(obj)
    all_cols <- names(obj@meta.data)
    selectInput("s_pca_tech_col","Single color / facet variable:",choices=all_cols,
                selected=if("lcbatch" %in% all_cols)"lcbatch" else all_cols[1])
  })
  output$s_pca_tech_facet_ui <- renderUI({
    obj <- s_sct_active(); req(obj)
    all_cols <- names(obj@meta.data)
    selectizeInput("s_pca_tech_facet_vars","Feature(s) for facets (up to 8):",
                   choices=all_cols, multiple=TRUE, selected=head(all_cols,3),
                   options=list(maxItems=8))
  })

  output$s_pca_tech <- renderPlot({
    req(s_pca_df(), input$s_pca_tech_col)
    obj  <- s_sct_active(); req(obj)
    df_p <- s_pca_df(); pve <- s_pve()
    df_p$Label <- if("ID" %in% names(obj@meta.data)) obj@meta.data[df_p$Cell,"ID"] else df_p$Cell

    if (!is.null(input$s_pca_tech_mode) && input$s_pca_tech_mode == "facet") {
      req(input$s_pca_tech_facet_vars, length(input$s_pca_tech_facet_vars) > 0)
      facet_vars <- input$s_pca_tech_facet_vars
      plot_list <- lapply(facet_vars, function(v) {
        vals <- obj@meta.data[df_p$Cell, v]
        is_cont <- is.numeric(vals) && length(unique(vals)) > 10
        df_v <- data.frame(PC1=df_p$PC1, PC2=df_p$PC2,
                           Color=if(is_cont) as.numeric(vals) else .lvl_factor(vals, v))
        p <- ggplot(df_v,aes(x=PC1,y=PC2,color=Color))+geom_point(size=2,alpha=0.8)+
          theme_classic(base_size=11)+labs(title=v,
               x=paste0("PC1 (",pve[1],"%)"),y=paste0("PC2 (",pve[2],"%)"),color=v)
        # Each facet is a DIFFERENT covariate, so each takes its own palette.
        if(is_cont) p <- p+viridis::scale_color_viridis(option="plasma",name=v)
        else p <- p + { .scale_col_for(v, levels(df_v$Color), na.value="grey70") }
        p
      })
      n_vars <- length(plot_list)
      patchwork::wrap_plots(plot_list, ncol=min(4, n_vars))
    } else {
      cc <- input$s_pca_tech_col
      raw_vals <- if(cc %in% names(obj@meta.data)) obj@meta.data[df_p$Cell, cc] else "NA"
      is_continuous <- is.numeric(raw_vals) && length(unique(raw_vals)) > 10
      df_p$Color <- if(is_continuous) as.numeric(raw_vals) else .lvl_factor(raw_vals, cc)
      lbl <- input$s_sct_view %||% "_full_"
      p <- ggplot(df_p,aes(x=PC1,y=PC2,color=Color))+geom_point(size=3,alpha=0.8)+
        theme_classic(base_size=13)+
        labs(title=paste0("[",lbl,"] PCA — ",cc),color=cc,
             x=paste0("PC1 (",pve[1],"%)"),y=paste0("PC2 (",pve[2],"%)"))
      if(is_continuous) p <- p+viridis::scale_color_viridis(option="plasma",name=cc)
      else p <- p + { .scale_col_for(cc, levels(df_p$Color), na.value="grey70") }
      print(p)
    }
  })

  output$s_pc_heatmap <- renderPlot({
    obj <- s_sct_active(); req(obj, "pca" %in% names(obj@reductions))
    pcs <- seq(input$s_hm_pcs[1], input$s_hm_pcs[2])
    Seurat::DimHeatmap(obj, dims=pcs, cells=min(ncol(obj),100),
                       balanced=TRUE, fast=FALSE, raster=FALSE)
  })

  # ── ⑦ Embeddings ───────────────────────────────────────────────────────────

  # ── UI outputs ──────────────────────────────────────────────────────────────
  output$s_emb_col_ui <- renderUI({
    req(s$seu)
    opts <- unique(c("seurat_clusters", names(s$seu@meta.data)))
    selectInput("s_emb_col","Color by:",choices=opts,
                selected=if("seurat_clusters" %in% names(s$seu@meta.data)) "seurat_clusters" else opts[1])
  })
  output$s_emb_shape_ui <- renderUI({
    req(s$seu)
    cat_opts <- c("(none)"="none")
    # Only columns with ≤ 6 unique values work as Seurat shape.by
    for (col in names(s$seu@meta.data)) {
      v <- s$seu@meta.data[[col]]
      if ((is.character(v)||is.factor(v)) && length(unique(v[!is.na(v)])) <= 6)
        cat_opts <- c(cat_opts, setNames(col, col))
    }
    selectInput("s_emb_shape","Shape by:",choices=cat_opts,selected="none")
  })
  output$s_emb_feat_ui <- renderUI({
    req(s$seu)
    # Cached: see s_feats_with_values(). Features present in the assay but with no
    # measured values (all-NA rows, which exist because the data layer is written
    # at full assay height on the NA-aware routes) are hidden, because selecting
    # one produces an empty continuous scale.
    ft <- .feat_choices()
    selectInput("s_emb_feat","Feature (continuous):",
                choices=ft, selected=if (length(ft)) ft[1] else NULL)
  })


  # ── Compute embeddings ───────────────────────────────────────────────────────
  # ── ⑦ Embeddings diagnostics ────────────────────────────────────────────────

  output$s_sweep_col_ui <- renderUI({
    req(s$seu)
    cols <- names(s$seu@meta.data)
    selectInput("s_sweep_col","Color by:", choices=cols,
                selected=if("seurat_clusters"%in%cols)"seurat_clusters" else cols[1])
  })

  output$s_js_status <- renderUI({
    if (is.null(s$js_result))
      tags$p("Not run yet.", style="color:grey;font-size:12px;")
    else
      tags$p("✓ Jackstraw complete.", style="color:#27AE60;font-weight:600;font-size:12px;")
  })

  observeEvent(input$s_run_jackstraw, {
    req(s$seu, "pca" %in% names(s$seu@reductions))
    tryCatch({
      withProgress(message="Running Jackstraw (slow)...", value=0.3, {
        seu_js <- Seurat::JackStraw(s$seu, num.replicate=input$s_js_reps,
                                     dims=input$s_js_dims)
        seu_js <- Seurat::ScoreJackStraw(seu_js, dims=1:input$s_js_dims)
        s$js_result <- seu_js
      })
      s_log(paste0("Jackstraw: ", input$s_js_dims, " PCs, ", input$s_js_reps, " reps"))
      showNotification("Jackstraw done.", type="message", duration=4)
    }, error=function(e) showNotification(paste0("Jackstraw error: ", e$message),
                                          type="error", duration=10))
  })

  output$s_jackstraw_plot <- renderPlot({
    req(s$js_result)
    Seurat::JackStrawPlot(s$js_result, dims=1:input$s_js_dims) +
      theme_classic(base_size=13) +
      labs(title="Jackstraw — significant PCs highlighted in red (p<0.05)")
  })

  observeEvent(input$s_run_sweep, {
    req(s$seu, "pca" %in% names(s$seu@reductions))
    tryCatch({
      nn_vals <- as.numeric(input$s_sweep_nn)
      md_vals <- as.numeric(input$s_sweep_md)
      req(length(nn_vals) >= 1, length(md_vals) >= 1)
      dims    <- 1:min(input$s_emb_dims, ncol(Seurat::Embeddings(s$seu,"pca")))
      col_by  <- input$s_sweep_col %||% "seurat_clusters"
      params  <- expand.grid(nn=nn_vals, md=md_vals)
      withProgress(message=paste0("UMAP sweep: ", nrow(params), " combinations..."),
                   value=0, {
        plots <- lapply(seq_len(nrow(params)), function(i) {
          incProgress(1/nrow(params))
          seu_tmp <- Seurat::RunUMAP(s$seu, dims=dims,
                                     n.neighbors=params$nn[i],
                                     min.dist=params$md[i], verbose=FALSE)
          Seurat::DimPlot(seu_tmp, group.by=col_by, pt.size=1.5,
                          label=TRUE, label.size=3) +
            labs(title=paste0("nn=",params$nn[i],"  md=",params$md[i])) +
            theme(legend.position="none", plot.title=element_text(size=11))
        })
        s$sweep_plots <- plots
      })
      showNotification(paste0("Sweep done: ", nrow(params), " UMAPs."),
                       type="message", duration=4)
    }, error=function(e) showNotification(paste0("Sweep error: ", e$message),
                                          type="error", duration=10))
  })

  output$s_sweep_plot <- renderPlot({
    req(s$sweep_plots)
    patchwork::wrap_plots(s$sweep_plots,
                          ncol=max(1, length(as.numeric(input$s_sweep_md))))
  })

  observeEvent(input$s_run_sil_grid, {
    req(s$seu, "pca" %in% names(s$seu@reductions))
    tryCatch({
      res_vals <- as.numeric(input$s_sil_res)
      k_vals   <- as.numeric(input$s_sil_k)
      dims     <- 1:min(input$s_sil_dims, ncol(Seurat::Embeddings(s$seu,"pca")))
      grid     <- expand.grid(res=res_vals, k=k_vals)
      dist_mat <- cluster::daisy(Seurat::Embeddings(s$seu,"pca")[, dims])
      withProgress(message="Silhouette grid...", value=0, {
        grid$sil <- NA_real_
        for (i in seq_len(nrow(grid))) {
          incProgress(1/nrow(grid))
          tryCatch({
            st <- Seurat::FindNeighbors(s$seu, dims=dims,
                                        k.param=grid$k[i], verbose=FALSE)
            st <- Seurat::FindClusters(st, resolution=grid$res[i], verbose=FALSE)
            cl <- as.integer(st$seurat_clusters)
            if (length(unique(cl)) > 1)
              grid$sil[i] <- round(mean(cluster::silhouette(cl, dist_mat)[,3]),3)
          }, error=function(e) NULL)
        }
        s$sil_grid <- grid
      })
      showNotification("Silhouette grid done.", type="message", duration=4)
    }, error=function(e) showNotification(paste0("Sil grid error: ", e$message),
                                          type="error", duration=10))
  })

  output$s_sil_grid_plot <- renderPlot({
    p <- tryCatch(.build_sil_grid(s$sil_grid, "Mean silhouette", 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  # ── ⑧ Clustering diagnostics ─────────────────────────────────────────────────

  # ── Clustering-diagnostic builders ─────────────────────────────────
  # One builder per figure, used by the panel AND the PDF export, so the two
  # cannot drift. Guards stop() rather than validate(), because validate() is a
  # render-only construct: inside a download handler it aborts silently and
  # yields a blank page instead of the message.

  # Silhouette bar chart (per-cell widths, faceted by cluster).
  .build_sil_bar <- function(sil_obj, title_stem, fs = 13) {
    if (is.null(sil_obj))
      stop("No silhouette result yet — click 'Run silhouette' first.", call.=FALSE)
    df <- as.data.frame(sil_obj[,])
    names(df) <- c("cluster","neighbor","sil_width")
    df$cluster <- factor(df$cluster)
    df <- df[order(df$cluster, df$sil_width), ]
    df$cell <- seq_len(nrow(df))
    ggplot(df, aes(x=cell, y=sil_width, fill=cluster)) +
      geom_bar(stat="identity", width=1) +
      scale_fill_manual(values=.cluster_cols(levels(df$cluster))) +
      geom_hline(yintercept=0, color="black", linewidth=0.5) +
      geom_hline(yintercept=mean(df$sil_width), color="grey30",
                 linetype="dashed", linewidth=0.8) +
      facet_wrap(~cluster, scales="free_x", nrow=1) +
      theme_classic(base_size=fs) +
      theme(axis.text.x=element_blank(), axis.ticks.x=element_blank(),
            strip.background=element_blank()) +
      labs(title=paste0(title_stem, "  |  Mean = ", round(mean(df$sil_width), 3)),
           subtitle="Dashed = mean. Positive = well-assigned, negative = misassigned.",
           x="Cells (sorted within cluster)", y="Silhouette width", fill="Cluster")
  }

  # Silhouette sweep heatmap (resolution x k).
  .build_sil_grid <- function(grid_df, title_stem, fs = 13) {
    if (is.null(grid_df) || !nrow(grid_df))
      stop("No silhouette sweep yet — run the resolution × k grid first.", call.=FALSE)
    g <- grid_df; g$res <- factor(g$res); g$k <- factor(g$k)
    ggplot(g, aes(x=res, y=k, fill=sil)) +
      geom_tile(color="white", linewidth=0.5) +
      geom_text(aes(label=ifelse(is.na(sil),"—",sprintf("%.2f",sil))), size=fs/3.2) +
      scale_fill_gradient2(low="#E74C3C", mid="lightyellow", high="#27AE60",
                           midpoint=0, na.value="grey90", name="Mean\nsilhouette") +
      theme_classic(base_size=fs) +
      labs(title=paste0(title_stem, " — green = better separation"),
           x="Resolution", y="k")
  }

  # Clustree tree. clustree() returns a ggraph/ggplot, so this exports normally.
  .build_clustree <- function(seu_ct, fs = 13) {
    if (is.null(seu_ct))
      stop("No clustree result — pick the resolutions to test and click 'Run clustree'.",
           call.=FALSE)
    if (!requireNamespace("clustree", quietly=TRUE))
      stop("Package 'clustree' is required. Install: install.packages('clustree')", call.=FALSE)
    prefix <- grep("_snn_res\\.", names(seu_ct@meta.data), value=TRUE)
    pfx    <- if (length(prefix) > 0) sub("[0-9].*","",prefix[1]) else "seurat_clusters"
    # The edge_colorbar guide needs ggraph >= 2.2; drop it rather than fail.
    tryCatch(
      clustree::clustree(seu_ct, prefix=pfx) +
        guides(edge_color="none", edge_alpha="none") +
        theme(legend.position="right", text=element_text(size=fs)),
      error = function(e)
        clustree::clustree(seu_ct, prefix=pfx, edge_color="grey50", edge_arrow=FALSE) +
          theme(legend.position="right", text=element_text(size=fs))
    )
  }

  # Cluster x metadata stacked proportions.
  .build_clust_meta <- function(seu, col, title_stem, fs = 13) {
    if (is.null(seu)) stop("No object yet.", call.=FALSE)
    if (!"seurat_clusters" %in% names(seu@meta.data))
      stop("No clusters yet — run clustering first.", call.=FALSE)
    if (is.null(col) || !nzchar(col) || !col %in% names(seu@meta.data))
      stop("Pick a metadata variable on the Cluster × metadata tab first.", call.=FALSE)
    df_p <- data.frame(Cluster = seu$seurat_clusters,
                       Var     = .lvl_factor(seu@meta.data[[col]], col))
    ggplot(df_p, aes(x=Cluster, fill=Var)) + geom_bar(position="fill") +
      { .scale_fill_for(col, levels(df_p$Var)) } +
      scale_y_continuous(labels=scales::percent) +
      theme_classic(base_size=fs) +
      labs(title=paste0(title_stem, col), y="Proportion", fill=col)
  }

  # ── Clustree: drop every pre-existing resolution column ──────────────────
  # FindClusters names its output <assay>_snn_res.<R> and clustree::clustree()
  # consumes EVERY meta.data column matching the prefix it is given. The run
  # below starts from s$seu, which already carries a resolution column from the
  # ⑧ Clustering tab (and the integrated one from Step 8), so those stale
  # resolutions were silently appearing as extra tiers in the tree.
  #
  # That is what made the result depend on history: deselect a resolution and
  # re-run and it vanishes from the requested set but a leftover column with a
  # different value may still be present, so returning to an earlier selection
  # did not reproduce the earlier tree. Stripping them means the tree shows
  # exactly the resolutions ticked in the box, nothing else.
  .strip_res_cols <- function(seu) {
    drop <- grep("_snn_res\\.|^seurat_clusters$", names(seu@meta.data), value=TRUE)
    if (length(drop)) for (cc in drop) seu@meta.data[[cc]] <- NULL
    seu
  }

  observeEvent(input$s_run_clustree, {
    req(s$seu, "pca" %in% names(s$seu@reductions))
    # Clear FIRST, so an aborted or failed run cannot leave the previous tree on
    # screen next to the new settings.
    s$clustree_seu <- NULL
    tryCatch({
      res_vals <- sort(unique(as.numeric(input$s_clustree_res)))
      res_vals <- res_vals[is.finite(res_vals)]
      if (length(res_vals) < 2)
        stop("Tick at least two resolutions — a tree needs more than one tier.", call.=FALSE)
      dims     <- 1:min(input$s_clustree_dims, ncol(Seurat::Embeddings(s$seu,"pca")))
      kp       <- input$s_clust_k %||% 20    # match the ⑧ Clustering KNN k
      withProgress(message=paste0("Clustree: ", length(res_vals), " resolutions (k=", kp, ")..."),
                   value=0, {
        seu_ct <- .strip_res_cols(s$seu)
        seu_ct <- Seurat::FindNeighbors(seu_ct, dims=dims, k.param=kp, reduction="pca", verbose=FALSE)
        for (res in res_vals) {
          incProgress(1/length(res_vals))
          seu_ct <- Seurat::FindClusters(seu_ct, resolution=res, verbose=FALSE)
        }
        s$clustree_res <- res_vals
        s$clustree_seu <- seu_ct
      })
      s_log(paste0("Clustree: ", length(res_vals), " resolutions (",
                   paste(res_vals, collapse=", "), ") | dims 1:",
                   max(dims), " | k.param=", kp, " (matched to ⑧ Clustering)."))
      showNotification(paste0("Clustree done (k=", kp, ")."), type="message", duration=4)
    }, error=function(e) {
      s$clustree_seu <- NULL
      showNotification(paste0("Clustree error: ", e$message), type="error", duration=10)
    })
  })

  # Changing any clustree input invalidates the tree on screen. Without this the
  # panel keeps showing the previous result while the controls read something
  # else, which is the state that made two identical selections look like they
  # gave different answers. Blank until re-run is the honest display.
  observeEvent(list(input$s_clustree_res, input$s_clustree_dims, input$s_clust_k), {
    if (!is.null(s$clustree_seu)) {
      s$clustree_seu <- NULL
      s$clustree_res <- NULL
    }
  }, ignoreInit = TRUE)

  output$s_clustree_plot <- renderPlot({
    p <- tryCatch(.build_clustree(s$clustree_seu, 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  observeEvent(input$s_run_sil, {
    req(s$seu, "seurat_clusters" %in% names(s$seu@meta.data),
        "pca" %in% names(s$seu@reductions))
    tryCatch({
      withProgress(message="Computing silhouette...", value=0.5, {
        dims     <- 1:min(input$s_clust_dims, ncol(Seurat::Embeddings(s$seu,"pca")))
        dist_mat <- cluster::daisy(Seurat::Embeddings(s$seu,"pca")[, dims])
        sil_obj  <- cluster::silhouette(as.integer(s$seu$seurat_clusters), dist_mat)
        s$sil_result <- sil_obj
      })
      showNotification("Silhouette done.", type="message", duration=4)
    }, error=function(e) showNotification(paste0("Silhouette error: ", e$message),
                                          type="error", duration=10))
  })

  output$s_sil_summary_ui <- renderUI({
    req(s$sil_result)
    m   <- round(mean(s$sil_result[,3]), 3)
    col <- if(m>0.5)"#27AE60" else if(m>0.25)"#F39C12" else "#E74C3C"
    tags$p(paste0("Mean silhouette: ", m),
           style=paste0("color:",col,";font-weight:600;font-size:14px;"))
  })

  output$s_sil_plot <- renderPlot({
    p <- tryCatch(.build_sil_bar(s$sil_result, "Silhouette by cluster", 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  observeEvent(input$s_run_emb, {
    req(s$seu,"pca" %in% names(s$seu@reductions))
    withProgress(message="Computing embeddings...", value=0, {
      seu  <- s$seu
      dims <- 1:min(input$s_emb_dims, ncol(Seurat::Embeddings(seu,"pca")))
      incProgress(0.2, detail="UMAP")
      seu <- Seurat::RunUMAP(seu, dims=dims, reduction="pca", verbose=FALSE,
                             n.neighbors=input$s_emb_nn, min.dist=input$s_emb_mindist)
      incProgress(0.6, detail="t-SNE")
      perp <- min(input$s_emb_tsne_perp, floor((ncol(seu)-1)/3))
      seu  <- Seurat::RunTSNE(seu, dims=dims, reduction="pca", verbose=FALSE, perplexity=perp)
      s$seu <- seu; s_log(paste0("UMAP + t-SNE computed | dims=1:", max(dims),
                                  " | n.neighbors=", input$s_emb_nn,
                                  " | min.dist=", input$s_emb_mindist,
                                  " | tsne.perplexity=", perp))
    })
    showNotification("UMAP and t-SNE complete.", type="message", duration=4)
  })

  # ── Helper: binarize (numerically encode) a metadata column for plotting/regression ──
  # Returns the vector as numeric; characters/factors → integer codes
  s_encode_meta <- function(x) {
    if (is.character(x) || is.factor(x)) as.numeric(factor(x, levels=sort(unique(x[!is.na(x)]))))
    else as.numeric(x)
  }

  # ── Simple plotly dim plot (used for Groups / Feature tabs) ─────────────────
  s_dim_plotly <- function(reduction, color_by=NULL, title="", feature=NULL) {
    req(s$seu, reduction %in% names(s$seu@reductions))
    emb <- as.data.frame(Seurat::Embeddings(s$seu, reduction)[,1:2])
    colnames(emb) <- c("D1","D2")
    emb$Cell  <- rownames(emb)
    emb$Label <- if("ID" %in% names(s$seu@meta.data)) s$seu@meta.data[emb$Cell,"ID"] else emb$Cell
    if (!is.null(feature) && feature %in% rownames(s$seu)) {
      fd <- tryCatch(Seurat::FetchData(s$seu, vars=feature), error=function(e) NULL)
      validate(need(!is.null(fd) && nrow(fd) > 0,
                    paste0("Could not fetch '", feature, "' from the active assay.")))
      # Align BY CELL NAME. FetchData returns the object's cell order; `emb` is in
      # the reduction's order, and assigning positionally would mismatch values to
      # cells wherever the two differ.
      vals <- suppressWarnings(as.numeric(fd[[1]]))
      names(vals) <- rownames(fd)
      emb$Color <- vals[emb$Cell]
      n_fin <- sum(is.finite(emb$Color)); n_na <- sum(!is.finite(emb$Color))
      # An all-NA feature cannot be drawn on a continuous scale. On the NA-aware
      # routes the data layer is at full assay height, so features the transform
      # dropped (scp-median removes rows with < 2 observed values) are present but
      # entirely empty — selecting one used to error here.
      validate(need(n_fin > 0,
                    paste0("'", feature, "' has no measured values in this object \u2014 ",
                           "it was dropped by the normalization (too few observations) but ",
                           "remains in the assay as an empty row.")))
      p <- ggplot(emb, aes(x=D1, y=D2, color=Color, text=Label)) +
        geom_point(size=2.5, alpha=0.9) +
        scale_color_viridis_c(option="plasma", na.value="grey88") +
        theme_classic(base_size=13) +
        labs(title=title, color=feature,
             subtitle=if (n_na > 0)
               paste0(n_na, " of ", nrow(emb),
                      " cells not detected (grey) \u2014 grey is missing, not low")
             else NULL)
    } else {
      cb <- if(!is.null(color_by) && color_by %in% names(s$seu@meta.data))
        as.factor(s$seu@meta.data[emb$Cell, color_by])
      else factor(rep("All", nrow(emb)))
      emb$Color <- cb
      p <- ggplot(emb, aes(x=D1, y=D2, color=Color, text=Label)) +
        geom_point(size=2.5, alpha=0.9) +
        theme_classic(base_size=13) +
        labs(title=title, color=if(!is.null(color_by)) color_by else "")
      # apply the custom per-covariate palette (name-keyed) when one exists
      pal <- if(!is.null(color_by)) s$palette[[color_by]] else NULL
      if (identical(color_by, "seurat_clusters")) {
        # shared cluster colors so the cluster UMAP matches proportions/PDF
        p <- p + scale_color_manual(values=.cluster_cols(levels(emb$Color)), na.value="grey70")
      } else if (!is.null(pal)) {
        lv  <- levels(emb$Color)
        pal <- pal[names(pal) %in% lv]
        if (length(pal)) p <- p + scale_color_manual(values=pal, na.value="grey70")
      }
    }
    ggplotly(p, tooltip=c("text","x","y"))
  }

  output$s_umap_grp  <- renderPlotly({ s_dim_plotly("umap", input$s_emb_col, "UMAP — groups") })
  output$s_umap_feat <- renderPlotly({ s_dim_plotly("umap", NULL, paste0("UMAP — ",input$s_emb_feat), feature=input$s_emb_feat) })
  output$s_tsne_grp  <- renderPlotly({ s_dim_plotly("tsne", input$s_emb_col, "t-SNE — groups") })
  output$s_tsne_feat <- renderPlotly({ s_dim_plotly("tsne", NULL, paste0("t-SNE — ",input$s_emb_feat), feature=input$s_emb_feat) })

  # ── Technical overlay: single variable, user-selected, UMAP or t-SNE ──────
  # ── Technical overlay: multi-variable grid, one panel per variable ──────────
  # NOTE: separate categorical / continuous overlay selectors used to live here
  # (s_tech_cat_ui, s_tech_cont_ui). They were superseded by this single combined
  # selector, which offers metadata AND protein features and routes each choice
  # automatically (categorical -> DimPlot, continuous or protein -> FeaturePlot).
  # The old pair was removed rather than wired up: nothing read their inputs, and
  # re-exposing them would have duplicated this control.
  output$s_tech_overlay_var_ui <- renderUI({
    req(s$seu)
    meta_cols  <- names(s$seu@meta.data)
    # Same cached list, so the overlay grid cannot be pointed at a feature with no
    # measured values.
    all_opts   <- unique(c(.opt_clean(meta_cols, "variables"), .feat_choices()))
    selectizeInput("s_tech_overlay_vars",
                   "Variables to plot (one panel each):",
                   choices  = all_opts,
                   selected = character(0),
                   multiple = TRUE,
                   options  = list(maxItems=12, placeholder="Type to search..."))
  })

  s_tech_grid_plot <- reactiveVal(NULL)

  # Build the Seurat-tab technical-overlay grid fresh from current inputs. Shared
  # by the GUI observe and the PDF export so the exported PDF is the SAME
  # multi-panel grid (previously the PDF read a non-existent singular input and
  # produced one wrong/blank panel). NA-fills the data layer for faithful
  # protein-feature panels on VSN/scp-median data.
  .build_s_tech_grid <- function(reduction) {
    if (is.null(s$seu)) return(NULL)
    vars_sel  <- input$s_tech_overlay_vars
    pt_size   <- input$s_tech_pt_size %||% 2
    ncol_use  <- .num(input$s_tech_ncol, 2)
    if (is.null(vars_sel) || length(vars_sel) == 0 ||
        !reduction %in% names(s$seu@reductions)) return(NULL)
    seu_use   <- s_seu_with_ident()
    assay_use <- if("SCT" %in% names(seu_use@assays))"SCT" else input$s_assay
    seu_use   <- tryCatch(.display_safe_seu(seu_use, assay_use), error=function(e) seu_use)
    plot_list <- lapply(vars_sel, function(v) {
      tryCatch({
        is_meta    <- v %in% names(seu_use@meta.data)
        is_protein <- v %in% rownames(seu_use)
        if (is_meta) {
          vals    <- seu_use@meta.data[[v]]
          is_cont <- is.numeric(vals) && length(unique(vals[!is.na(vals)])) > 8
          if (is_cont) {
            seu_use[[".tmp_grid_overlay"]] <- as.numeric(vals)
            Seurat::FeaturePlot(seu_use, features=".tmp_grid_overlay",
                                reduction=reduction, pt.size=pt_size,
                                cols=c("grey90","#E74C3C")) +
              ggplot2::ggtitle(v) + ggplot2::theme(plot.title=ggplot2::element_text(size=11))
          } else {
            pal <- .pal_seu(seu_use, v)
            Seurat::DimPlot(seu_use, reduction=reduction, group.by=v, pt.size=pt_size,
                            cols=if(!is.null(pal)) pal else NULL) +
              ggplot2::ggtitle(v) + ggplot2::theme(plot.title=ggplot2::element_text(size=11))
          }
        } else if (is_protein) {
          assay_use <- if("SCT" %in% names(seu_use@assays))"SCT" else input$s_assay
          Seurat::DefaultAssay(seu_use) <- assay_use
          Seurat::FeaturePlot(seu_use, features=v, reduction=reduction, pt.size=pt_size,
                              cols=c("grey90","#8E44AD")) +
            ggplot2::ggtitle(v) + ggplot2::theme(plot.title=ggplot2::element_text(size=11))
        } else NULL
      }, error=function(e) {
        ggplot2::ggplot() + ggplot2::theme_void() +
          ggplot2::labs(title=paste0(v,"\nError: ",conditionMessage(e)))
      })
    })
    plot_list <- Filter(Negate(is.null), plot_list)
    if (length(plot_list) == 0) return(NULL)
    patchwork::wrap_plots(plot_list, ncol=ncol_use) &
      ggplot2::theme(legend.position="right")
  }

  observeEvent(input$s_tech_run, {
    s_tech_grid_plot(.build_s_tech_grid(input$s_tech_reduction %||% "umap"))
  })

  output$s_tech_overlay_plot <- renderPlot({
    p <- s_tech_grid_plot()
    if (is.null(p)) {
      plot(0, type="n", axes=FALSE, xlab="", ylab="")
      text(0, 0, "Select variables and click 'Draw grid'", cex=1.1, col="grey50")
    } else {
      print(p)
    }
  })

  # ── ⑧ Clustering ────────────────────────────────────────────────────────────
  output$s_clust_status <- renderUI({
    if(is.null(s$seu)||!"seurat_clusters" %in% names(s$seu@meta.data))
      return(tags$p("No clusters yet.",style="color:#E74C3C;font-size:13px;"))
    tags$p(paste0("✓ ",length(unique(s$seu$seurat_clusters))," clusters"),
           style="color:#27AE60;font-size:13px;font-weight:600;")
  })

  observeEvent(input$s_run_clust, {
    req(s$seu,"pca" %in% names(s$seu@reductions))
    withProgress(message="Clustering...", value=0, {
      seu  <- s$seu
      # Seurat v5: ensure layers are joined before FindNeighbors
      tryCatch({
        join_fn <- if (existsMethod("JoinLayers", "Seurat")) Seurat::JoinLayers
                   else if (requireNamespace("SeuratObject", quietly=TRUE)) SeuratObject::JoinLayers
                   else get("JoinLayers")
        seu[[input$s_assay]] <- join_fn(seu[[input$s_assay]])
      }, error=function(e) NULL)
      dims <- 1:min(input$s_clust_dims,ncol(Seurat::Embeddings(seu,"pca")))
      incProgress(0.3,detail="FindNeighbors")
      seu <- Seurat::FindNeighbors(seu,dims=dims,k.param=input$s_clust_k,reduction="pca",verbose=FALSE)
      incProgress(0.6,detail="FindClusters")
      seu <- Seurat::FindClusters(seu,resolution=input$s_clust_res,algorithm=as.numeric(input$s_clust_alg),verbose=FALSE)
      s$seu <- seu
      s_log(paste0("Clustering: ", length(unique(seu$seurat_clusters)), " clusters",
                   " | res=", input$s_clust_res,
                   " | dims=1:", max(dims),
                   " | k=", input$s_clust_k,
                   " | algorithm=", input$s_clust_alg))
    })
    showNotification(paste0(length(unique(s$seu$seurat_clusters))," clusters found."),type="message",duration=4)
  })

  output$s_clust_umap <- renderPlotly({ s_dim_plotly("umap","seurat_clusters","UMAP — clusters") })
  output$s_clust_prop <- renderPlotly({
    req(s$seu,"seurat_clusters" %in% names(s$seu@meta.data))
    df_p<-as.data.frame(table(Cluster=s$seu$seurat_clusters))
    df_p$Pct<-df_p$Freq/sum(df_p$Freq)*100
    ggplotly(ggplot(df_p,aes(x=Cluster,y=Pct,fill=Cluster,
                              text=paste0("Cluster ",Cluster,"\n",round(Pct,1),"%")))+
               geom_bar(stat="identity")+
               scale_fill_manual(values=.cluster_cols(levels(df_p$Cluster)))+
               theme_classic(base_size=13)+labs(y="% cells",title="Cluster proportions"),tooltip="text")
  })
  output$s_clust_meta_ui <- renderUI({ req(s$seu); selectInput("s_clust_meta_col","Variable:",choices=names(s$seu@meta.data)) })
  output$s_clust_meta <- renderPlotly({
    p <- tryCatch(.build_clust_meta(s$seu, input$s_clust_meta_col,
                                    "Cluster × ", 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    ggplotly(p)
  })

  # ── ⑨ Markers ───────────────────────────────────────────────────────────────
  output$s_mk_grpby_ui <- renderUI({ req(s$seu); opts<-c("seurat_clusters",names(s$seu@meta.data)); selectInput("s_mk_grpby","Identity class:",choices=opts,selected=if("seurat_clusters"%in%names(s$seu@meta.data))"seurat_clusters"else opts[1]) })
  output$s_mk_id1_ui   <- renderUI({ req(s$seu,input$s_mk_grpby); ids<-sort(unique(as.character(s$seu@meta.data[[input$s_mk_grpby]]))); selectInput("s_mk_id1","Group A:",choices=ids,selected=ids[1]) })

  output$s_mk_latent_ui <- renderUI({
    req(s$seu)
    md <- s$seu@meta.data
    # Same split as the limma / proDA covariate selector, so the two engines
    # present identical choices: a numeric column with few distinct values is a
    # coded factor (plate, batch) and belongs on the categorical side.
    all_cols <- setdiff(names(md), c("orig.ident","nCount_RNA","nFeature_RNA",
                                     input$s_mk_grpby))
    is_cat <- vapply(all_cols, function(c){
      v <- md[[c]]
      (is.character(v) || is.factor(v) || is.logical(v) ||
        (is.numeric(v) && length(unique(v[!is.na(v)])) <= 10)) &&
      length(unique(as.character(v)[!is.na(v)])) >= 2 &&
      # A column with one level per cell (IDs, filenames) can never be a
      # covariate: the design would have as many parameters as observations.
      length(unique(as.character(v)[!is.na(v)])) <= max(2, floor(nrow(md)/3))
    }, logical(1))
    is_cont <- vapply(all_cols, function(c){
      v <- md[[c]]
      is.numeric(v) && !is.factor(v) && length(unique(v[!is.na(v)])) > 10
    }, logical(1))
    cat_cols  <- sort(all_cols[is_cat])
    cont_cols <- sort(all_cols[is_cont])
    if (!length(cat_cols) && !length(cont_cols))
      return(tags$p(tags$small("No covariate columns available."),
                    style="color:grey;font-size:11px;"))
    cc_cols <- intersect(c("S.Score","G2M.Score","Score_Diff"), cont_cols)
    tagList(
      tags$p(tags$small(tags$b("Latent variables"),
             " \u2014 included in the test's own model (LR / MAST / negbinom / poisson)"),
             style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
      if (length(cat_cols)) tagList(
        tags$p(tags$small(tags$b("Categorical: "), "enter as factor (dummy-coded)"),
               style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
        checkboxGroupInput("s_mk_latent", label=NULL, choices=cat_cols, selected=NULL)
      ) else NULL,
      if (length(cont_cols)) tagList(
        tags$p(tags$small(tags$b("Continuous: "), "enter as a linear term"),
               style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
        checkboxGroupInput("s_mk_latent_num", label=NULL, choices=cont_cols,
                           selected=if (length(cc_cols)) cc_cols else NULL)
      ) else NULL
    )
  })
  output$s_mk_id2_ui   <- renderUI({ req(s$seu,input$s_mk_grpby); ids<-sort(unique(as.character(s$seu@meta.data[[input$s_mk_grpby]]))); selectInput("s_mk_id2","Group B:",choices=ids,selected=ids[min(2,length(ids))]) })
  output$s_mk_status   <- renderUI({
    if (is.null(s$markers)) return(tags$p("No markers yet.",style="color:#E74C3C;font-size:13px;"))
    # Show what was compared
    last_mode <- if (!is.null(s$last_mk_mode)) s$last_mk_mode else "?"
    last_grp  <- if (!is.null(s$last_mk_grp))  s$last_mk_grp  else "?"
    last_comp <- if (!is.null(s$last_mk_comp))  s$last_mk_comp else ""
    tagList(
      tags$p(paste0("✓ ", nrow(s$markers), " results"),
             style="color:#27AE60;font-size:13px;font-weight:600;"),
      tags$p(paste0("Mode: ", last_mode, " | Identity: ", last_grp),
             style="color:#5d6d7e;font-size:12px;margin:2px 0;"),
      if (last_comp != "")
        tags$p(paste0("Comparison: ", last_comp),
               style="color:#2980B9;font-size:12px;font-weight:600;margin:2px 0;")
    )
  })

  # ── The DE model, printed ───────────────────────────────────────────────────
  # Each test family fits a structurally different model, and the differences are
  # not cosmetic: LR puts GROUP on the left-hand side and expression on the right,
  # so it asks whether abundance predicts group membership; limma and proDA put
  # abundance on the left and test its group coefficient. Printing the formula
  # makes the direction, the covariate placement and the tested coefficient
  # explicit rather than something a reader has to infer from the method name.
  .mk_model_block <- function(prefix) {
    renderUI({
      req(s$seu)
      md      <- s$seu@meta.data
      test    <- input[[paste0(prefix, "_test")]]    %||% "wilcox"
      grpby   <- input[[paste0(prefix, "_grpby")]]   %||% "<group>"
      na_meth <- input[[paste0(prefix, "_namethod")]] %||% "proda"
      norm    <- (s$intensity_diag$method %||% input$s_norm_method) %||% "sct"
      na_route <- norm %in% .NA_AWARE

      hdr <- function(txt) tags$p(tags$b(txt),
        style="margin:0 0 3px 0;font-size:12px;color:#1F4E79;")
      frm <- function(txt) tags$p(txt, style=paste0("margin:0 0 3px 0;font-family:",
        "Consolas,monospace;font-size:12px;color:#1F4E79;"))
      note <- function(...) tags$p(tags$small(...),
        style="margin:0;color:#1F4E79;font-size:11px;")
      wrap <- function(...) div(style=paste0("background:#eef4fb;border-left:4px solid ",
        "#2980B9;border-radius:3px;padding:8px;margin:8px 0;"), ...)

      # ── Intensity-native engines (proDA / limma / complete-case Wilcoxon) ────
      if (na_route && na_meth != "na_zero") {
        cats <- input[[paste0(prefix, "_proda_cov")]]      %||% character(0)
        nums <- input[[paste0(prefix, "_proda_cov_cont")]] %||% character(0)
        # ⑫ has no spline / linear controls of its own, so fall back to the ⑨
        # ones — the same precedence .de_spline_df() uses for the actual fit.
        lin_ov <- input[[paste0(prefix, "_cov_linear")]] %||% input$s_mk_cov_linear
        sdf  <- if (isTRUE(lin_ov)) 1 else {
          ov <- suppressWarnings(as.numeric(
                  input[[paste0(prefix, "_spline_df")]] %||% input$s_mk_spline_df))
          # length() first: a missing widget gives numeric(0), and
          # `logical(0) && x` evaluates to NA, which then breaks if().
          if (length(ov) == 1 && is.finite(ov) && ov >= 1) as.integer(ov)
          else as.integer((if (norm == "vsn") input$s_vsn_spline_df
                           else input$s_scpmed_spline_df) %||% 1)
        }
        ix <- input[[paste0(prefix, "_interact")]]
        ix <- if (is.null(ix) || identical(ix, "__none__") || !nzchar(ix)) NULL else ix
        .tm <- function(v) if (v %in% nums && sdf > 1)
                             paste0("ns(", v, ", df=", sdf, ")") else v
        rhs <- vapply(c(cats, nums), .tm, character(1))
        lhs <- if (identical(na_meth, "limma")) "abundance" else "abundance"
        core <- if (!is.null(ix)) paste0("group * ", ix) else "group"
        formula_txt <- paste0(lhs, " ~ ", core,
                              if (length(rhs)) paste0(" + ", paste(rhs, collapse=" + ")) else "")
        engine <- switch(na_meth,
          "proda"    = "proDA \u2014 per-feature linear model with an explicit dropout curve; missing values modeled, never imputed",
          "limma"    = "limma lmFit + eBayes \u2014 per-feature linear model; residual variances shrunk toward a global prior across features",
          "ccwilcox" = "complete-case Wilcoxon \u2014 rank test on observed values only",
          na_meth)
        tested <- if (!is.null(ix)) {
          if (identical(na_meth, "limma"))
            "F-test over all group:interaction columns (omnibus \u2014 no single log2FC is defined)"
          else "likelihood-ratio test against the additive model (omnibus)"
        } else if (identical(na_meth, "ccwilcox")) "rank difference between groups"
        else "the single `group` coefficient (moderated t / Wald)"
        reported <- if (!is.null(ix))
          paste0("omnibus interaction group \u00d7 ", ix,
                 " \u2014 no single effect size; the table reports the largest ",
                 "interaction coefficient, which is NOT a log2 fold change")
        else if (identical(na_meth, "ccwilcox"))
          "difference in ranks between the two groups (no model coefficient)"
        else paste0("the `group` effect: the change in ", grpby,
                    " on the normalized scale, adjusted for ",
                    if (length(rhs)) paste(c(cats, nums), collapse=", ") else "nothing")
        # How many features can support this design?
        .feasible <- local({
          mm <- tryCatch(.norm_mat(s$seu), error=function(e) NULL)
          if (is.null(mm)) return(NULL)
          terms_all <- unique(c(cats, nums))
          p_need <- .model_df(s$seu@meta.data, terms_all, sdf) + 1L   # + group
          nobs   <- rowSums(!is.na(mm))
          list(p=p_need, need=p_need + 2L,
               ok=sum(nobs >= (p_need + 2L)), total=length(nobs),
               med=stats::median(nobs))
        })

        return(wrap(
          hdr(paste0("Model tested \u2014 ", toupper(na_meth))),
          frm(formula_txt),
          if (!is.null(.feasible)) {
            fr  <- .feasible
            pct <- if (fr$total > 0) round(100*fr$ok/fr$total, 1) else NA
            col <- if (is.finite(pct) && pct < 25) "#8A6D3B" else "#1F4E79"
            tags$p(tags$small(
              tags$b("Testable features: "),
              sprintf("%d of %d (%.1f%%) have the \u2265 %d observations this %d-parameter design needs; median observed cells per feature is %d.",
                      fr$ok, fr$total, pct, fr$need, fr$p, as.integer(fr$med)),
              if (is.finite(pct) && pct < 25)
                tagList(tags$br(), tags$b("Most features cannot be fitted. "),
                        "A categorical covariate with many levels costs one parameter per level ",
                        "beyond the first, which can push the requirement above almost every ",
                        "feature's observation count \u2014 the run then completes and tests almost ",
                        "nothing. Use a coarser grouping (plate or batch rather than file), or ",
                        "drop the term.")
              else NULL),
              style=paste0("margin:0 0 4px 0;color:", col, ";font-size:11px;"))
          } else NULL,
          note(tags$b("Reported effect: "), reported, tags$br(),
               tags$b("Grouping: "), grpby, tags$br(),
               tags$b("Engine: "), engine, tags$br(),
               tags$b("Coefficient tested: "), tested, tags$br(),
               tags$b("Matrix: "), "the data layer \u2014 normalization output, un-regressed. ",
               "Covariates are held constant INSIDE this model; nothing is subtracted ",
               "from the values.",
               if (identical(na_meth, "ccwilcox") && length(rhs))
                 tagList(tags$br(), tags$b("Warning: "),
                         "a rank test has no design matrix, so the covariates above are IGNORED.")
               else NULL)
        ))
      }

      # ── Seurat FindMarkers ──────────────────────────────────────────────────
      # Two checkbox groups feed one covariate list (checkboxGroupInput cannot
      # render optgroups), so the printout must union them or it silently omits
      # every continuous covariate.
      lat <- unique(c(input[[paste0(prefix, "_latent")]],
                      input[[paste0(prefix, "_latent_num")]])) %||% character(0)
      lat <- intersect(lat, names(md))
      cov_ok <- test %in% c("LR","MAST","negbinom","poisson")
      lat_txt <- if (length(lat)) paste(lat, collapse=" + ") else NULL
      layer_txt <- if (na_route)
        "the data layer with NA \u2192 0 substituted (user-selected na_zero path)"
      else if (identical(norm, "sct")) "SCT data layer \u2014 log1p corrected counts"
      else "data layer \u2014 log-normalized"

      spec <- switch(test,
        "LR" = list(
          f = paste0("group ~ abundance",
                     if (!is.null(lat_txt)) paste0(" + ", lat_txt) else ""),
          f2 = paste0("group ~ ",
                      if (!is.null(lat_txt)) lat_txt else "1"),
          d = "Logistic regression with GROUP as the response. Compared against the null model without abundance by a likelihood-ratio test.",
          w = "The reported avg_log2FC is computed from group means OUTSIDE this model, so the effect size is unadjusted even though the p-value is."),
        "MAST" = list(
          f = paste0("abundance ~ ",
                     if (!is.null(lat_txt)) paste0(lat_txt, " + ") else "", "group"),
          f2 = NULL,
          d = "Hurdle model (zlm): a logistic part for detection and a Gaussian part for magnitude, fitted jointly; LRT on the group term.",
          w = paste0("MAST adds NOTHING automatically. Its convention of including the ",
                     "cellular detection rate (cngeneson) is something the user attaches ",
                     "before zlm() is called, and Seurat passes only what you select here \u2014 ",
                     "so if no depth covariate is ticked, the model has none. nFeature_* is ",
                     "the direct equivalent: it is a COUNT of detected features per cell, ",
                     "which is what cngeneson is. log2_total_intensity is a different ",
                     "quantity (total signal, the multiplicative loading channel) and is ",
                     "not a substitute, though on the log2-only route both are worth ",
                     "including since no per-cell normalization was applied.")),
        "negbinom" = list(
          f = paste0("counts ~ group",
                     if (!is.null(lat_txt)) paste0(" + ", lat_txt) else ""),
          f2 = NULL,
          d = "Negative-binomial GLM.",
          w = "Assumes raw counts. Inappropriate for intensity data."),
        "poisson" = list(
          f = paste0("counts ~ group",
                     if (!is.null(lat_txt)) paste0(" + ", lat_txt) else ""),
          f2 = NULL,
          d = "Poisson GLM.",
          w = "Assumes raw counts. Inappropriate for intensity data."),
        list(f = NULL, f2 = NULL,
             d = switch(test,
                   "wilcox" = "Wilcoxon rank-sum test on the two groups.",
                   "roc"    = "ROC/AUC classification power \u2014 a ranking, not a hypothesis test.",
                   "t"      = "Welch t-test on the two groups.",
                   paste0(test, " test.")),
             w = "No design matrix, so covariates cannot be included. Any latent variables selected above are IGNORED.")
      )

      reported <- switch(test,
        "LR"   = paste0("p-value: whether abundance improves prediction of ", grpby,
                        " beyond the covariates. avg_log2FC: group means, computed ",
                        "OUTSIDE the model and therefore NOT covariate-adjusted."),
        "MAST" = paste0("the group term of the hurdle model \u2014 a combined test of ",
                        "detection rate and magnitude. avg_log2FC is computed ",
                        "separately from group means."),
        "roc"  = "classification power (AUC) only \u2014 a ranking, not an effect size or a p-value.",
        paste0("avg_log2FC between the two levels of ", grpby,
               ", computed from group means on the data layer; unadjusted for any covariate."))
      wrap(
        hdr(paste0("Model tested \u2014 ", test)),
        if (!is.null(spec$f)) frm(spec$f) else
          frm(paste0("no model \u2014 two-sample test on ", grpby)),
        if (!is.null(spec$f2)) frm(paste0("vs null:  ", spec$f2)) else NULL,
        note(tags$b("Reported effect: "), reported, tags$br(),
             tags$b("Grouping: "), grpby, tags$br(),
             tags$b("Engine: "), spec$d, tags$br(),
             tags$b("Covariates: "),
             if (!cov_ok) "not supported by this test"
             else if (length(lat)) paste(lat, collapse=", ")
             else "none selected", tags$br(),
             tags$b("Matrix: "), layer_txt, tags$br(),
             tags$b("Note: "), spec$w)
      )
    })
  }
  # ── Combined-factor builder ─────────────────────────────────────────────────
  .mk_combo_choices <- function() {
    req(s$seu)
    md <- s$seu@meta.data
    names(md)[vapply(md, function(x)
      is.character(x) || is.factor(x) ||
      (is.numeric(x) && length(unique(x[!is.na(x)])) <= 20), logical(1))]
  }
  output$s_mk_combo_a_ui <- renderUI({
    ch <- .mk_combo_choices()
    selectInput("s_mk_combo_a", "First:", choices=ch,
                selected=if ("seurat_clusters" %in% ch) "seurat_clusters" else ch[1])
  })
  output$s_mk_combo_b_ui <- renderUI({
    ch <- .mk_combo_choices()
    selectInput("s_mk_combo_b", "Second:", choices=ch,
                selected=if (length(ch) > 1) ch[2] else ch[1])
  })

  observeEvent(input$s_mk_combo_go, {
    req(s$seu)
    a <- input$s_mk_combo_a; b <- input$s_mk_combo_b
    md <- s$seu@meta.data
    if (is.null(a) || is.null(b) || !(a %in% names(md)) || !(b %in% names(md))) {
      showNotification("Pick two metadata columns.", type="error", duration=8); return() }
    if (identical(a, b)) {
      showNotification("Pick two DIFFERENT columns.", type="warning", duration=8); return() }
    nm <- input$s_mk_combo_name
    nm <- if (is.null(nm) || !nzchar(trimws(nm))) paste0(a, "_", b) else make.names(trimws(nm))

    va <- as.character(md[[a]]); vb <- as.character(md[[b]])
    combo <- ifelse(is.na(va) | is.na(vb), NA_character_, paste0(va, "_", vb))
    seu <- s$seu
    seu@meta.data[[nm]] <- factor(combo)
    s$seu <- seu
    # Keep the integrated object in step when it exists, so the same factor is
    # available on ⑫ without rebuilding it there.
    if (!is.null(s$seu_int)) {
      si <- s$seu_int
      # `combo` is positional against rownames(md), so map by cell name.
      si@meta.data[[nm]] <- factor(combo[match(rownames(si@meta.data), rownames(md))])
      s$seu_int <- si
    }
    n_lev <- length(levels(factor(combo)))
    small <- sum(table(combo) < 3)
    updateSelectInput(session, "s_mk_grpby", selected=nm)
    showNotification(paste0("Created '", nm, "' with ", n_lev, " levels and selected it as the ",
                            "Identity class.",
                            if (small > 0) paste0(" ", small,
                              " level(s) have fewer than 3 cells \u2014 contrasts involving those ",
                              "will be unstable.") else ""),
                     type="message", duration=12)
    s_log(paste0("Combined factor '", nm, "' = ", a, " \u00d7 ", b, " (", n_lev, " levels; ",
                 small, " with < 3 cells). Selected as the grouping variable."))
  })

  output$s_mk_model_ui <- .mk_model_block("s_mk")
  output$i_mk_model_ui <- .mk_model_block("i_mk")

  output$s_mk_proda_cov_ui <- renderUI({
    req(s$seu)
    md <- s$seu@meta.data
    all_cols <- setdiff(names(md), c("orig.ident"))
    # Categorical: character/factor, or numeric with few distinct values (coded batch).
    # Continuous: numeric with many distinct values (total intensity, nFeature, TIC…).
    is_cat <- vapply(all_cols, function(c){
      v <- md[[c]]
      is.character(v) || is.factor(v) || (is.numeric(v) && length(unique(v[!is.na(v)]))<=10)
    }, logical(1))
    is_cont <- vapply(all_cols, function(c){
      v <- md[[c]]
      is.numeric(v) && length(unique(v[!is.na(v)])) > 10
    }, logical(1))
    cat_cols  <- all_cols[is_cat]
    cont_cols <- all_cols[is_cont]
    if (!length(cat_cols) && !length(cont_cols))
      return(tags$p(tags$small("No covariate columns available."),
                    style="color:grey;font-size:11px;"))
    tagList(
      if (length(cat_cols)) tagList(
        tags$p(tags$small(tags$b("Categorical: "), "enter as factor (dummy-coded)"),
               style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
        checkboxGroupInput("s_mk_proda_cov", label=NULL, choices=cat_cols, selected=NULL)
      ) else NULL,
      if (length(cont_cols)) tagList(
        tags$p(tags$small(tags$b("Continuous: "), "enter as a linear term"),
               style="color:#2c3e50;font-size:11px;margin:6px 0 2px 0;"),
        checkboxGroupInput("s_mk_proda_cov_cont", label=NULL, choices=cont_cols, selected=NULL)
      ) else NULL
    )
  })

  # ── Shared DE design builder (spline-aware) ─────────────────────────────────
  # Builds the covariate part of a differential-abundance design. Continuous
  # covariates can enter as a natural cubic spline basis instead of one linear
  # term, matching what the ⑥ embedding regression does.
  #
  # WHY THIS MATTERS: a covariate is only "adjusted for" to the extent the model
  # can describe it. Depth effects in proteomics are rarely linear — under
  # abundance-dependent censoring the relationship between a feature's abundance
  # and a cell's depth bends and can flatten at both ends. A single linear term
  # leaves that curvature in the residual, where it inflates the residual
  # variance and can bias the group coefficient if depth is unbalanced across
  # groups. Both proDA and limma accept arbitrary design columns, so there is no
  # statistical obstacle: the spline basis is simply extra nuisance columns and
  # the contrast of interest is still the single "group" coefficient.
  #
  # The basis is materialised as plain numeric columns (name_s1, name_s2, ...)
  # rather than left as splines::ns() inside the formula, so column names stay
  # syntactic and neither package has to evaluate a function call in the design.
  # `interact` crosses the grouping variable with one metadata column, giving
  # ~ group * X + other covariates. The question it answers is different from any
  # main effect: not "does this protein differ between groups" but "does the group
  # difference itself differ across levels of X" — e.g. does the sex effect differ
  # between clusters. That is a genuine interaction and cannot be obtained by
  # comparing two separate contrasts: significance in one subset and not another
  # can come purely from unequal cell numbers or detection rates.
  #
  # Because X usually has more than two levels there is more than one interaction
  # coefficient, so the test is an OMNIBUS one: an F-test over all of them in
  # limma, and a likelihood-ratio test against the additive model in proDA. A
  # single "log fold change" is not defined for an omnibus test; the largest
  # interaction coefficient is reported in its place and labeled as such.
  .de_design <- function(base_df, cat_cov, cont_cov, dat, spline_df = 1,
                         interact = NULL) {
    out   <- base_df
    terms <- character(0)
    notes <- character(0)
    for (cn in cat_cov) {
      nm <- make.names(cn)
      out[[nm]] <- factor(as.character(dat[[cn]]))
      terms <- c(terms, nm)
    }
    use_spline <- is.numeric(spline_df) && spline_df > 1 &&
                  requireNamespace("splines", quietly = TRUE)
    for (cn in cont_cov) {
      nm <- make.names(cn)
      v  <- suppressWarnings(as.numeric(as.character(dat[[cn]])))
      # A covariate with NAs would make model.matrix drop rows and desynchronise
      # the design from the expression matrix, so fill with the median and say so.
      if (anyNA(v)) {
        nfill <- sum(is.na(v))
        v[is.na(v)] <- stats::median(v, na.rm = TRUE)
        notes <- c(notes, paste0(cn, ": ", nfill, " NA filled with median"))
      }
      nuniq  <- length(unique(v[is.finite(v)]))
      df_use <- if (use_spline) max(1L, min(as.integer(spline_df), nuniq - 1L)) else 1L
      B <- if (df_use >= 2)
             tryCatch(splines::ns(v, df = df_use), error = function(e) NULL)
           else NULL
      if (!is.null(B)) {
        for (j in seq_len(ncol(B))) {
          nmj <- paste0(nm, "_s", j)
          out[[nmj]] <- as.numeric(B[, j])
          terms <- c(terms, nmj)
        }
        notes <- c(notes, paste0(cn, ": spline df=", df_use))
      } else {
        out[[nm]] <- v
        terms <- c(terms, nm)
      }
    }
    # Interaction: added last so its columns are identifiable in the design.
    ix_term <- NULL
    if (!is.null(interact) && nzchar(interact) && interact %in% names(dat)) {
      nm <- make.names(interact)
      v  <- dat[[interact]]
      v  <- if (is.numeric(v) && length(unique(v[!is.na(v)])) > 10) as.numeric(v)
            else factor(as.character(v))
      lv_ok <- if (is.factor(v)) nlevels(droplevels(v[!is.na(v)])) >= 2
               else length(unique(v[is.finite(v)])) >= 2
      if (lv_ok) {
        if (is.factor(v) && anyNA(v)) {
          v <- addNA(v, ifany = TRUE)
          notes <- c(notes, paste0(interact, ": NA kept as its own level"))
        }
        out[[nm]] <- v
        ix_term <- nm
        notes <- c(notes, paste0("interaction: group \u00d7 ", interact))
      } else {
        notes <- c(notes, paste0(interact, ": only one usable level \u2014 interaction dropped"))
      }
    }

    names(out) <- make.names(names(out))
    rhs <- if (!is.null(ix_term))
             paste0("group * ", ix_term,
                    if (length(setdiff(terms, ix_term)))
                      paste0(" + ", paste(setdiff(terms, ix_term), collapse = " + ")) else "")
           else
             paste0("group",
                    if (length(terms)) paste0(" + ", paste(terms, collapse = " + ")) else "")
    frm <- stats::as.formula(paste0("~ ", rhs))
    # The additive (reduced) model, used as the null for the proDA LRT.
    frm_reduced <- if (!is.null(ix_term))
      stats::as.formula(paste0("~ group",
        if (length(unique(c(terms, ix_term))))
          paste0(" + ", paste(unique(c(terms, ix_term)), collapse = " + ")) else ""))
    else NULL
    list(data = out, terms = terms, formula = frm, notes = notes,
         interact = ix_term, formula_reduced = frm_reduced)
  }

  output$s_mk_interact_ui <- renderUI({
    req(s$seu)
    md <- s$seu@meta.data
    cat_cols <- names(md)[vapply(md, function(x)
      is.character(x) || is.factor(x) ||
      (is.numeric(x) && length(unique(x[!is.na(x)])) <= 10), logical(1))]
    cat_cols <- setdiff(cat_cols, c("orig.ident", input$s_mk_grpby))
    div(style=paste0("background:#fdf6e3;border-left:4px solid #E67E22;",
                     "border-radius:3px;padding:8px;margin-bottom:8px;"),
      tags$p(tags$b("Interaction (optional)"),
             style="margin:0 0 3px 0;font-size:12px;color:#8A6D3B;"),
      selectInput("s_mk_interact", NULL,
                  choices  = c("(none \u2014 test the group main effect)" = "__none__", cat_cols),
                  selected = "__none__"),
      tags$p(tags$small(
        "Selecting a variable fits ", tags$b("~ group * X"),
        " and tests whether the group difference ", tags$b("differs across levels of X"),
        " \u2014 e.g. group by sex, interact with cluster, to ask whether the sex effect ",
        "is cluster-specific. This is not the same as running the contrast separately ",
        "in each subset and comparing: significance in one subset and not another can ",
        "come purely from unequal cell numbers. Because X usually has several levels ",
        "the test is an omnibus one (F-test in limma, likelihood-ratio against the ",
        "additive model in proDA), so a single log fold change is undefined \u2014 the ",
        "effect-size column reports the largest interaction coefficient instead. ",
        "Applies to the \u2468 one-vs-rest engines only."),
        style="margin:0;color:#8A6D3B;font-size:11px;"))
  })

  # Resolved interaction variable for the ⑨ Markers engine ("(none)" = off).
  .de_interact <- reactive({
    iv <- input$s_mk_interact
    if (is.null(iv) || identical(iv, "__none__") || !nzchar(iv)) NULL else iv
  })

  # Same for ⑫. Kept separate rather than shared, because the natural partner
  # differs: ⑨ typically crosses with the unintegrated clusters and ⑫ with the
  # integrated ones, and a shared control would silently change both.
  .i_de_interact <- reactive({
    iv <- input$i_mk_interact
    if (is.null(iv) || identical(iv, "__none__") || !nzchar(iv)) NULL else iv
  })

  output$i_mk_interact_ui <- renderUI({
    req(s$seu_int)
    md <- s$seu_int@meta.data
    cat_cols <- names(md)[vapply(md, function(x)
      is.character(x) || is.factor(x) ||
      (is.numeric(x) && length(unique(x[!is.na(x)])) <= 10), logical(1))]
    cat_cols <- setdiff(cat_cols, c("orig.ident", input$i_mk_grpby))
    div(style=paste0("background:#fdf6e3;border-left:4px solid #E67E22;",
                     "border-radius:3px;padding:8px;margin-bottom:8px;"),
      tags$p(tags$b("Interaction (optional)"),
             style="margin:0 0 3px 0;font-size:12px;color:#8A6D3B;"),
      selectInput("i_mk_interact", NULL,
                  choices  = c("(none \u2014 test the group main effect)" = "__none__", cat_cols),
                  selected = "__none__"),
      tags$p(tags$small(
        "Fits ", tags$b("~ group * X"), " and tests whether the group difference ",
        tags$b("differs across levels of X"), " \u2014 e.g. group by Sex, interact with the ",
        "integrated seurat_clusters, to ask whether the sex effect is cluster-specific. ",
        "The test is an omnibus one (F-test in limma, likelihood-ratio against the additive ",
        "model in proDA), so no single log fold change exists \u2014 the effect-size column ",
        "reports the largest interaction coefficient. Applies to the proDA and limma ",
        "engines only."),
        style="margin:0;color:#8A6D3B;font-size:11px;"))
  })

  # Spline df for DE designs. Defaults to matching the ⑥ setting for whichever
  # intensity-native method was run, so the embedding and the tests describe the
  # covariate the same way unless the user deliberately overrides it.
  .de_spline_df <- reactive({
    if (isTRUE(input$s_mk_cov_linear)) return(1)
    ov <- suppressWarnings(as.numeric(input$s_mk_spline_df))
    # length() first: a blank or absent input gives numeric(0), and
    # `logical(0) && x` is NA, which breaks the if().
    if (length(ov) == 1 && is.finite(ov) && ov >= 1) return(as.integer(ov))
    m <- (s$intensity_diag$method %||% input$s_norm_method) %||% "sct"
    if (m == "vsn")        return(as.integer(.num(input$s_vsn_spline_df, 1)))
    if (m %in% .NA_AWARE)  return(as.integer(.num(input$s_scpmed_spline_df, 1)))
    1L
  })

  observeEvent(input$s_run_mk, {
    req(s$seu)

    # Record every user-alterable setting for this run BEFORE anything can fail,
    # so the activity log in the Export tab always shows what was asked for even
    # if the fit errors out partway.
    if ((input$s_norm_method %||% "sct") %in% .NA_AWARE) .log_proda_settings("s_mk")

    # Grouping variable, resolved ONCE for every branch of this observer.
    # It used to be assigned only inside the two NA-aware intercepts, both of
    # which return() before the standard Seurat path runs. The latent.vars
    # validation below then referenced `grpby` in a frame where it had never
    # been bound, so selecting any covariate threw 'object grpby not found'.
    grpby <- input$s_mk_grpby

    # ══════════════════════════════════════════════════════════════════════════
    # VSN / scp-median: NA-aware marker testing on the un-regressed normalized
    # matrix (proDA default, complete-case Wilcoxon alternative). Overrides the
    # standard FindMarkers path so NAs are handled correctly (not zero-imputed).
    # ══════════════════════════════════════════════════════════════════════════
    norm_method <- input$s_norm_method %||% "sct"

    # ── VSN/scpmed ALL-CLUSTERS: NA-aware one-vs-rest (proDA or Wilcoxon) ──────
    if (norm_method %in% .NA_AWARE && input$s_mk_mode == "all" &&
        (input$s_mk_namethod %||% "proda") != "na_zero") {
      # Reads the DATA LAYER: normalization output, un-regressed, NAs intact.
      # Covariates are adjusted for inside the proDA / limma design rather than
      # subtracted from these values, which keeps the degrees of freedom honest.
      diag <- s$intensity_diag
      m <- .norm_mat(s$seu)
      if (is.null(m)) {
        showNotification(paste0("No NA-aware normalized data layer found. Run \u2465 with ",
                                "VSN or scp-median first."), type="error", duration=10); return() }
      grpby <- input$s_mk_grpby
      if (is.null(grpby) || !grpby %in% names(s$seu@meta.data)) {
        showNotification("Select a valid grouping variable.", type="error", duration=8); return() }
      md <- s$seu@meta.data
      cells <- intersect(colnames(m), rownames(md))
      m <- m[, cells, drop=FALSE]; md <- md[cells, , drop=FALSE]
      grp_all <- as.character(md[[grpby]])
      clusters <- sort(unique(grp_all[!is.na(grp_all)]))
      if (length(clusters) < 2) {
        showNotification("Need ≥2 groups for all-clusters markers.", type="error", duration=8); return() }
      na_method <- input$s_mk_namethod %||% "proda"
      minpct    <- .num(input$s_mk_minpct, 0.1)
      covs_cat  <- setdiff(intersect(input$s_mk_proda_cov      %||% character(0), names(md)), grpby)
      covs_cont <- setdiff(intersect(input$s_mk_proda_cov_cont %||% character(0), names(md)), grpby)

      if (na_method=="proda" && !requireNamespace("proDA", quietly=TRUE)) {
        showNotification("proDA not installed: BiocManager::install('proDA').", type="error", duration=12); return() }
      if (na_method=="limma" && !requireNamespace("limma", quietly=TRUE)) {
        showNotification("limma not installed: BiocManager::install('limma').", type="error", duration=12); return() }

      withProgress(message=paste0("NA-aware one-vs-rest (", toupper(na_method), ")..."), value=0, {
        all_res <- list()
        for (k in seq_along(clusters)) {
          cl <- clusters[k]
          incProgress(1/length(clusters), detail=paste0("cluster ", cl))
          is_k <- factor(ifelse(grp_all==cl, "this", "rest"), levels=c("rest","this"))
          n_this <- sum(is_k=="this"); n_rest <- sum(is_k=="rest")
          if (n_this < 3 || n_rest < 3) next
          o1 <- rowSums(!is.na(m[, is_k=="this", drop=FALSE]))
          o2 <- rowSums(!is.na(m[, is_k=="rest", drop=FALSE]))
          p1 <- o1/max(n_this,1); p2 <- o2/max(n_rest,1)
          kf <- (p1>=minpct)|(p2>=minpct)

          # ── Degenerate-fit guard ──────────────────────────────────────────
          # Detection rate alone is not enough: a feature can clear min.pct and
          # still have fewer observations than the design has parameters, in which
          # case the coefficient is not estimable and comes back enormous. Count
          # the parameters the design will actually consume and require that many
          # observations plus 2.
          if (na_method %in% c("proda","limma")) {
            .terms_all <- unique(c(covs_cat, covs_cont))
            .p_need <- .model_df(md, .terms_all, .de_spline_df()) + 1L   # + group
            .n_obs  <- rowSums(!is.na(m))
            .kf_df  <- .n_obs >= (.p_need + 2L)
            n_underdet <- sum(kf & !.kf_df)
            if (n_underdet > 0 && k == 1)
              s_log(paste0("DE: ", n_underdet, " feature(s) excluded \u2014 fewer than ",
                           .p_need + 2L, " observations for a ", .p_need,
                           "-parameter design. Without this they return ",
                           "uninterpretably large fold changes."))
            kf <- kf & .kf_df
          }
          # Optional variable-feature restriction (see the ⑨ control).
          if (isTRUE(input$s_mk_vf_only)) {
            vfs <- Seurat::VariableFeatures(s$seu)
            if (length(vfs) >= 3) {
              n_before <- sum(kf)
              kf <- kf & (rownames(m) %in% vfs)
              if (k == 1)
                s_log(paste0("DE restricted to variable features: ", sum(kf), " of ",
                             n_before, " \u2014 p-adjusted values are on this reduced universe."))
            } else if (k == 1) {
              showNotification("No variable-feature set available; testing all features.",
                               type="warning", duration=8)
            }
          }
          if (!any(kf)) {
            if (k == 1)
              showNotification(paste0("No feature has enough observations for this design. ",
                                      "Reduce the covariate count or the spline df."),
                               type="error", duration=12)
            next
          }

          mk_k <- m[kf,,drop=FALSE]; p1k<-p1[kf]; p2k<-p2[kf]; o1k<-o1[kf]; o2k<-o2[kf]
          rk <- NULL
          if (na_method=="proda") {
            keep_cat  <- covs_cat[vapply(covs_cat, function(cn) length(unique(md[[cn]][!is.na(md[[cn]])]))>=2, logical(1))]
            keep_cont <- covs_cont[vapply(covs_cont, function(cn){v<-suppressWarnings(as.numeric(as.character(md[[cn]]))); sum(!is.na(v))>=3 && stats::sd(v,na.rm=TRUE)>0}, logical(1))]
            .dd <- .de_design(data.frame(group=is_k, check.names=TRUE),
                              keep_cat, keep_cont, md, .de_spline_df(),
                              interact = .de_interact())
            dsn <- .dd$data; frm <- .dd$formula
            if (k == 1 && length(.dd$notes))
              s_log(paste0("DE design (", toupper(na_method), "): ",
                           paste(.dd$notes, collapse="; ")))
            # proDA fits a per-feature model AND estimates a dropout curve, so it
            # is inherently slower than limma by roughly an order of magnitude.
            # n_subsample caps the number of features used for the hyperparameter
            # step (the dominant cost); the per-feature fits still use everything.
            nsub <- suppressWarnings(as.integer(.num(input$s_mk_proda_nsub, 0)))
            nsub <- if (is.finite(nsub) && nsub >= 100) min(nsub, nrow(mk_k)) else nrow(mk_k)
            setProgress(detail=paste0("proDA: cluster ", cl, " \u2014 ", nrow(mk_k),
                                      " features \u00d7 ", ncol(mk_k), " cells",
                                      if (nsub < nrow(mk_k)) paste0(" (n_subsample=", nsub, ")") else ""))
            t0  <- Sys.time()
            fit <- tryCatch(proDA::proDA(as.matrix(mk_k), design=frm, col_data=dsn,
                                         n_subsample=nsub,
                                         # proDA prints its EM iterations when
                                         # verbose: the only way to see that a
                                         # long run is progressing rather than
                                         # stuck, since the Shiny progress bar
                                         # cannot advance inside one call.
                                         verbose=isTRUE(input$s_mk_proda_verbose),
                                         max_iter=as.integer(.num(input$s_mk_proda_maxit, 20)),
                                         epsilon=.num(input$s_mk_proda_eps, 0.001)),
                            error=function(e) { s_log(paste0("proDA failed for cluster ", cl,
                                                             ": ", conditionMessage(e))); NULL })
            if (is.null(fit)) next
            s_log(sprintf("proDA cluster %s: %d features, %.1f s", cl, nrow(mk_k),
                          as.numeric(difftime(Sys.time(), t0, units="secs"))))
            if (!is.null(.dd$interact)) {
              # Omnibus interaction test: full vs additive model. `diff` from an
              # LRT is not a fold change, so it is reported as NA and the effect
              # size column is left empty rather than filled with something that
              # would be read as a log2FC.
              rr <- tryCatch(proDA::test_diff(fit, reduced_model=.dd$formula_reduced),
                             error=function(e) NULL)
              if (is.null(rr)) next
              if (!"diff" %in% names(rr)) rr$diff <- NA_real_
            } else {
              cn2 <- tryCatch(grep("^group", colnames(proDA::design(fit)), value=TRUE)[1], error=function(e) "groupthis")
              if (is.na(cn2)) cn2 <- "groupthis"
              rr <- tryCatch(proDA::test_diff(fit, contrast=cn2), error=function(e) NULL)
              if (is.null(rr)) next
            }
            .lpk <- .proda_log_p(rr)
            rk <- data.frame(gene=rr$name, avg_log2FC=rr$diff, p_val=rr$pval, p_val_adj=rr$adj_pval,
                             neg_log10_p=-.lpk/log(10),
                             neg_log10_p_adj=-.bh_log(.lpk)/log(10),
                             pct.1=round(p1k[match(rr$name, rownames(mk_k))],3),
                             pct.2=round(p2k[match(rr$name, rownames(mk_k))],3),
                             cluster=cl,
                             n_obs.1=o1k[match(rr$name, names(o1k))],
                             n_obs.2=o2k[match(rr$name, names(o2k))], stringsAsFactors=FALSE)
          } else if (na_method=="limma") {
            if (!requireNamespace("limma", quietly=TRUE)) {
              showNotification("limma not installed: BiocManager::install('limma').", type="error", duration=12); next }
            keep_cat  <- covs_cat[vapply(covs_cat, function(cn) length(unique(md[[cn]][!is.na(md[[cn]])]))>=2, logical(1))]
            keep_cont <- covs_cont[vapply(covs_cont, function(cn){v<-suppressWarnings(as.numeric(as.character(md[[cn]]))); sum(!is.na(v))>=3 && stats::sd(v,na.rm=TRUE)>0}, logical(1))]
            .dd <- .de_design(data.frame(group=is_k, check.names=TRUE),
                              keep_cat, keep_cont, md, .de_spline_df(),
                              interact = .de_interact())
            dd <- .dd$data; frm <- .dd$formula
            if (k == 1 && length(.dd$notes))
              s_log(paste0("DE design (LIMMA): ", paste(.dd$notes, collapse="; ")))
            design <- stats::model.matrix(frm, data=dd)
            if (!is.null(.dd$interact)) {
              # All columns carrying a ":" between group and the interaction
              # variable — the omnibus F-test over the interaction.
              ci <- grep(paste0("^group.*:", .dd$interact, "|^", .dd$interact, ".*:group"),
                         colnames(design))
              if (!length(ci)) ci <- grep(":", colnames(design), fixed=TRUE)
            } else {
              ci <- grep("^group", colnames(design))[1]; if (is.na(ci)) ci <- 2
            }
            if (!length(ci) || any(is.na(ci))) {
              showNotification(paste0("No testable coefficient in the design for cluster ", cl,
                                      " \u2014 check the interaction variable's levels."),
                               type="error", duration=10)
              next
            }
            fit <- tryCatch(limma::eBayes(limma::lmFit(as.matrix(mk_k), design)), error=function(e) NULL)
            if (is.null(fit)) next
            tt <- limma::topTable(fit, coef=ci, number=Inf, sort.by="none")
            if (!"logFC" %in% names(tt)) {
              # Multi-coefficient F-test: report the largest interaction
              # coefficient as the effect size, clearly not a simple log2FC.
              cfm <- as.matrix(fit$coefficients[rownames(tt), ci, drop=FALSE])
              tt$logFC <- apply(cfm, 1, function(z) z[which.max(abs(z))])
            }
            rk <- data.frame(gene=rownames(tt), avg_log2FC=tt$logFC, p_val=tt$P.Value, p_val_adj=tt$adj.P.Val,
                             pct.1=round(p1k[match(rownames(tt), rownames(mk_k))],3),
                             pct.2=round(p2k[match(rownames(tt), rownames(mk_k))],3),
                             cluster=cl,
                             n_obs.1=o1k[match(rownames(tt), names(o1k))],
                             n_obs.2=o2k[match(rownames(tt), names(o2k))], stringsAsFactors=FALSE)
          } else {
            x1 <- mk_k[, is_k=="this", drop=FALSE]; x2 <- mk_k[, is_k=="rest", drop=FALSE]
            rr <- do.call(rbind, lapply(seq_len(nrow(mk_k)), function(i){
              a<-x1[i,]; b<-x2[i,]; a<-a[!is.na(a)]; b<-b[!is.na(b)]
              if(length(a)<3||length(b)<3) return(c(diff=NA,p=NA))
              c(diff=median(a)-median(b), p=tryCatch(stats::wilcox.test(a,b)$p.value, error=function(e) NA))
            }))
            rk <- data.frame(gene=rownames(mk_k), avg_log2FC=rr[,"diff"], p_val=rr[,"p"],
                             p_val_adj=p.adjust(rr[,"p"], method="BH"),
                             pct.1=round(p1k,3), pct.2=round(p2k,3), cluster=cl,
                             n_obs.1=o1k, n_obs.2=o2k, stringsAsFactors=FALSE)
            rk <- rk[!is.na(rk$p_val), ]
          }
          if (!is.null(rk) && nrow(rk)) all_res[[as.character(cl)]] <- rk
        }
        mk <- if (length(all_res)) do.call(rbind, all_res) else NULL
        if (is.null(mk) || !nrow(mk)) { showNotification("No markers produced.", type="warning", duration=8); return() }
        if (!is.null(input$s_mk_logfc)) mk <- mk[abs(mk$avg_log2FC) >= input$s_mk_logfc | is.na(mk$avg_log2FC), ]
        if (isTRUE(input$s_mk_posonly)) mk <- mk[!is.na(mk$avg_log2FC) & mk$avg_log2FC > 0, ]
        mk <- mk[order(mk$cluster, mk$p_val_adj), ]
        s$markers <- mk; s$last_mk_mode <- "all"
        s_log(paste0(toupper(na_method), " one-vs-rest markers: ", length(all_res),
                     " clusters, ", nrow(mk), " total rows"))
      })
      showNotification(paste0(nrow(s$markers), " one-vs-rest marker results (",
                              toupper(input$s_mk_namethod %||% "proda"), ")."), type="message", duration=5)
      return()
    }

    if (norm_method %in% .NA_AWARE && input$s_mk_mode == "two" &&
        (input$s_mk_namethod %||% "proda") != "na_zero") {
      diag <- s$intensity_diag
      if (is.null(diag) || is.null(diag$mat)) {
        showNotification("Run VSN/scp-median normalization first (no stashed matrix).",
                         type="error", duration=10); return()
      }
      grpby <- input$s_mk_grpby
      if (is.null(grpby) || !grpby %in% names(s$seu@meta.data)) {
        showNotification("Select a valid grouping variable.", type="error", duration=8); return()
      }
      md   <- s$seu@meta.data
      m    <- diag$mat                      # un-regressed, NA-containing, log-scale
      # align matrix cells to metadata
      cells <- intersect(colnames(m), rownames(md))
      m <- m[, cells, drop=FALSE]; md <- md[cells, , drop=FALSE]
      grp <- as.character(md[[grpby]])
      id1 <- input$s_mk_id1; id2 <- input$s_mk_id2
      keep <- grp %in% c(id1, id2)
      if (sum(grp==id1, na.rm=TRUE) < 3 || sum(grp==id2, na.rm=TRUE) < 3) {
        showNotification("Each group needs ≥3 cells for NA-aware testing.",
                         type="error", duration=8); return()
      }
      m   <- m[, keep, drop=FALSE]
      sub <- md[keep, , drop=FALSE]
      grp <- factor(grp[keep], levels=c(id2, id1))   # id1 = "positive" direction

      na_method <- input$s_mk_namethod %||% "proda"
      minpct    <- .num(input$s_mk_minpct, 0.1)

      # per-protein observed-cell counts / detection rates (reported alongside)
      obs1 <- rowSums(!is.na(m[, grp==id1, drop=FALSE]))
      obs2 <- rowSums(!is.na(m[, grp==id2, drop=FALSE]))
      n1 <- sum(grp==id1); n2 <- sum(grp==id2)
      pct1 <- obs1/max(n1,1); pct2 <- obs2/max(n2,1)
      # min.pct filter: keep proteins detected in >= minpct of either group
      keep_feat <- (pct1 >= minpct) | (pct2 >= minpct)

      # ── Degenerate-fit guard (same as the one-vs-rest path) ────────────────
      # Detection rate alone is not enough: a protein can clear min.pct and still
      # have fewer observations than the design has parameters, in which case the
      # coefficient is not estimable and returns an absurd magnitude that eBayes
      # can still call significant.
      if (na_method %in% c("proda","limma")) {
        .cc  <- setdiff(intersect(c(input$s_mk_proda_cov      %||% character(0),
                                    input$s_mk_proda_cov_cont %||% character(0)),
                                  names(sub)), grpby)
        .pn  <- .model_df(sub, .cc, .de_spline_df()) + 1L      # + group
        .nob <- rowSums(!is.na(m))
        .kdf <- .nob >= (.pn + 2L)
        n_underdet <- sum(keep_feat & !.kdf)
        if (n_underdet > 0)
          s_log(paste0("DE (two groups): ", n_underdet, " feature(s) excluded \u2014 fewer than ",
                       .pn + 2L, " observations for a ", .pn, "-parameter design. ",
                       "Without this they return uninterpretably large fold changes."))
        keep_feat <- keep_feat & .kdf
      }
      if (isTRUE(input$s_mk_vf_only)) {
        vfs <- Seurat::VariableFeatures(s$seu)
        if (length(vfs) >= 3) {
          n_before <- sum(keep_feat)
          keep_feat <- keep_feat & (rownames(m) %in% vfs)
          s_log(paste0("DE restricted to variable features: ", sum(keep_feat), " of ",
                       n_before, " \u2014 p-adjusted values are on this reduced universe."))
        } else {
          showNotification("No variable-feature set available; testing all features.",
                           type="warning", duration=8)
        }
      }
      if (!any(keep_feat)) {
        showNotification(paste0("No feature has enough observations for this design. ",
                                "Reduce the covariate count or the spline df."),
                         type="error", duration=12); return()
      }

      m <- m[keep_feat, , drop=FALSE]
      pct1 <- pct1[keep_feat]; pct2 <- pct2[keep_feat]
      obs1 <- obs1[keep_feat]; obs2 <- obs2[keep_feat]

      withProgress(message=paste0("NA-aware markers (", toupper(na_method), ")..."), value=0.2, {
        mk <- NULL
        if (na_method == "proda") {
          if (!requireNamespace("proDA", quietly=TRUE)) {
            showNotification("proDA not installed: BiocManager::install('proDA'). Use Complete-case Wilcoxon instead.",
                             type="error", duration=12); return()
          }
          covs_cat  <- intersect(input$s_mk_proda_cov %||% character(0), names(sub))
          covs_cont <- intersect(input$s_mk_proda_cov_cont %||% character(0), names(sub))
          covs_cat  <- setdiff(covs_cat,  grpby)   # never adjust for the grouping variable
          covs_cont <- setdiff(covs_cont, grpby)
          # build design: ~ group (+ covariates). Drop covariates that are
          # constant (no variation to model) within this subset.
          keep_cat <- covs_cat[vapply(covs_cat, function(cn)
            length(unique(sub[[cn]][!is.na(sub[[cn]])])) >= 2, logical(1))]
          keep_cont <- covs_cont[vapply(covs_cont, function(cn){
            v <- suppressWarnings(as.numeric(as.character(sub[[cn]])))
            sum(!is.na(v)) >= 3 && stats::sd(v, na.rm=TRUE) > 0
          }, logical(1))]
          keep_cov <- c(keep_cat, keep_cont)
          # assemble design frame: factors for categorical, numeric for continuous
          dsn_df <- data.frame(group = grp, check.names = TRUE)
          for (cn in keep_cat)  dsn_df[[cn]] <- factor(as.character(sub[[cn]]))
          for (cn in keep_cont) dsn_df[[cn]] <- suppressWarnings(as.numeric(as.character(sub[[cn]])))
          names(dsn_df) <- make.names(names(dsn_df))
          form <- stats::as.formula(
            paste0("~ group", if(length(keep_cov)) paste0(" + ", paste(make.names(keep_cov), collapse=" + ")) else ""))
          nsub <- suppressWarnings(as.integer(.num(input$s_mk_proda_nsub, 0)))
          nsub <- if (is.finite(nsub) && nsub >= 100) min(nsub, nrow(m)) else nrow(m)
          incProgress(0.3, detail=paste0("fitting proDA \u2014 ", nrow(m), " features \u00d7 ",
                                         ncol(m), " cells",
                                         if (nsub < nrow(m)) paste0(" (n_subsample=", nsub, ")") else ""))
          t0  <- Sys.time()
          fit <- tryCatch(proDA::proDA(as.matrix(m), design=form, col_data=dsn_df,
                                       n_subsample=nsub,
                                         # proDA prints its EM iterations when
                                         # verbose: the only way to see that a
                                         # long run is progressing rather than
                                         # stuck, since the Shiny progress bar
                                         # cannot advance inside one call.
                                         verbose=isTRUE(input$s_mk_proda_verbose),
                                       max_iter=as.integer(.num(input$s_mk_proda_maxit, 20)),
                                       epsilon=.num(input$s_mk_proda_eps, 0.001)),
                          error=function(e){showNotification(paste0("proDA failed: ",
                            conditionMessage(e)),type="error",duration=12);NULL})
          if (!is.null(fit))
            s_log(sprintf("proDA pairwise: %d features, %.1f s", nrow(m),
                          as.numeric(difftime(Sys.time(), t0, units="secs"))))
          if (is.null(fit)) return()
          incProgress(0.7, detail="testing group contrast")
          # Discover the group coefficient name from the fitted design matrix.
          # proDA names it "group<id1>" (id1 is the non-reference level here).
          coef_names <- tryCatch(colnames(proDA::design(fit)), error=function(e) NULL)
          if (is.null(coef_names))
            coef_names <- tryCatch(colnames(fit@design_matrix), error=function(e) NULL)
          coef_name <- if (!is.null(coef_names))
                         grep("^group", coef_names, value=TRUE)[1] else NA
          if (is.na(coef_name) || is.null(coef_name))
            coef_name <- paste0("group", make.names(id1))
          res <- tryCatch(proDA::test_diff(fit, contrast=coef_name),
                          error=function(e){showNotification(paste0("proDA test failed (contrast '",
                            coef_name, "'): ", conditionMessage(e)),type="error",duration=14);NULL})
          if (is.null(res)) return()
          .lp <- .proda_log_p(res)
          mk <- data.frame(
            gene       = res$name,
            avg_log2FC = res$diff,                 # proDA diff is on the log2 (VSN) scale
            p_val      = res$pval,
            p_val_adj  = res$adj_pval,
            neg_log10_p     = -.lp / log(10),      # finite where p_val underflows
            neg_log10_p_adj = -.bh_log(.lp) / log(10),
            pct.1      = round(pct1[match(res$name, rownames(m))], 3),
            pct.2      = round(pct2[match(res$name, rownames(m))], 3),
            cluster    = paste0(id1, " vs ", id2),
            n_obs.1    = obs1[match(res$name, names(obs1))],
            n_obs.2    = obs2[match(res$name, names(obs2))],
            stringsAsFactors=FALSE)
          mk <- mk[order(mk$p_val_adj), ]
          s_log(paste0("proDA markers: ", id1, " vs ", id2,
                       if(length(keep_cov)) paste0(" | adjusted for: ", paste(keep_cov, collapse=",")) else " | no covariates",
                       " | ", nrow(mk), " proteins tested"))
        } else if (na_method == "limma") {
          if (!requireNamespace("limma", quietly=TRUE)) {
            showNotification("limma not installed: BiocManager::install('limma').",
                             type="error", duration=12); return()
          }
          covs_cat  <- setdiff(intersect(input$s_mk_proda_cov %||% character(0), names(sub)), grpby)
          covs_cont <- setdiff(intersect(input$s_mk_proda_cov_cont %||% character(0), names(sub)), grpby)
          keep_cat  <- covs_cat[vapply(covs_cat, function(cn) length(unique(sub[[cn]][!is.na(sub[[cn]])]))>=2, logical(1))]
          keep_cont <- covs_cont[vapply(covs_cont, function(cn){v<-suppressWarnings(as.numeric(as.character(sub[[cn]]))); sum(!is.na(v))>=3 && stats::sd(v,na.rm=TRUE)>0}, logical(1))]
          keep_cov  <- c(keep_cat, keep_cont)
          .dd <- .de_design(data.frame(group=grp, check.names=TRUE),
                            keep_cat, keep_cont, sub, .de_spline_df(),
                            interact = .de_interact())
          dd <- .dd$data; frm <- .dd$formula
          if (length(.dd$notes))
            s_log(paste0("DE design (pairwise LIMMA): ", paste(.dd$notes, collapse="; ")))
          design <- stats::model.matrix(frm, data=dd)
          incProgress(0.4, detail="limma lmFit + eBayes")
          # limma handles NA per-protein (missing-at-random). Coefficient for id1
          # is the 2nd "group" column of the design. With an interaction set, the
          # tested coefficient is instead EVERY group:interaction column, giving an
          # omnibus F-test: "does the group difference differ across levels of X".
          if (!is.null(.dd$interact)) {
            coef_idx <- grep(paste0("^group.*:", .dd$interact, "|^", .dd$interact, ".*:group"),
                             colnames(design))
            if (!length(coef_idx)) coef_idx <- grep(":", colnames(design), fixed=TRUE)
            if (!length(coef_idx)) {
              showNotification(paste0("The interaction with '", .dd$interact, "' produced no ",
                                      "testable columns \u2014 it probably has only one level ",
                                      "within this comparison. Check table(", grpby, ", ",
                                      .dd$interact, ")."), type="error", duration=14)
              return()
            }
            s_log(paste0("Pairwise LIMMA: omnibus F-test over ", length(coef_idx),
                         " group\u00d7", .dd$interact, " interaction column(s)."))
          } else {
            coef_idx <- grep("^group", colnames(design))[1]
            if (is.na(coef_idx)) coef_idx <- 2
          }
          fit <- tryCatch({
            f <- limma::lmFit(as.matrix(m), design)
            limma::eBayes(f)
          }, error=function(e){showNotification(paste0("limma failed: ", conditionMessage(e)),
                                                type="error", duration=12); NULL})
          if (is.null(fit)) return()
          tt <- limma::topTable(fit, coef=coef_idx, number=Inf, sort.by="none")
          if (!"logFC" %in% names(tt)) {
            # Multi-coefficient F-test: no single logFC exists. Report the largest
            # interaction coefficient so the volcano has an x-axis, and say in the
            # log that it is NOT a fold change.
            cfm <- as.matrix(fit$coefficients[rownames(tt), coef_idx, drop=FALSE])
            tt$logFC <- apply(cfm, 1, function(z) z[which.max(abs(z))])
            s_log(paste0("Omnibus interaction test: the effect-size column holds the largest ",
                         "interaction coefficient, which is NOT a log2 fold change."))
          }
          mk <- data.frame(
            gene       = rownames(tt),
            avg_log2FC = tt$logFC,
            p_val      = tt$P.Value,
            p_val_adj  = tt$adj.P.Val,
            pct.1      = round(pct1[match(rownames(tt), rownames(m))], 3),
            pct.2      = round(pct2[match(rownames(tt), rownames(m))], 3),
            cluster    = paste0(id1, " vs ", id2),
            n_obs.1    = obs1[match(rownames(tt), names(obs1))],
            n_obs.2    = obs2[match(rownames(tt), names(obs2))],
            stringsAsFactors=FALSE)
          mk <- mk[order(mk$p_val_adj), ]
          s_log(paste0("limma markers: ", id1, " vs ", id2,
                       if(length(keep_cov)) paste0(" | adjusted for: ", paste(keep_cov, collapse=",")) else " | no covariates",
                       " | ", nrow(mk), " proteins tested"))
        } else {
          # complete-case Wilcoxon, per protein, on observed cells only
          incProgress(0.4, detail="per-protein Wilcoxon")
          x1 <- m[, grp==id1, drop=FALSE]; x2 <- m[, grp==id2, drop=FALSE]
          res_list <- lapply(seq_len(nrow(m)), function(i){
            a <- x1[i, ]; b <- x2[i, ]; a <- a[!is.na(a)]; b <- b[!is.na(b)]
            if (length(a) < 3 || length(b) < 3) return(c(diff=NA, p=NA))
            p <- tryCatch(stats::wilcox.test(a, b)$p.value, error=function(e) NA)
            c(diff = median(a) - median(b), p = p)   # log2-scale median difference
          })
          rr <- do.call(rbind, res_list)
          mk <- data.frame(
            gene       = rownames(m),
            avg_log2FC = rr[,"diff"],
            p_val      = rr[,"p"],
            p_val_adj  = p.adjust(rr[,"p"], method="BH"),
            pct.1      = round(pct1, 3), pct.2 = round(pct2, 3),
            cluster    = paste0(id1, " vs ", id2),
            n_obs.1    = obs1[keep_feat], n_obs.2 = obs2[keep_feat],
            stringsAsFactors=FALSE)
          mk <- mk[!is.na(mk$p_val), ]
          mk <- mk[order(mk$p_val_adj), ]
          s_log(paste0("Complete-case Wilcoxon markers: ", id1, " vs ", id2,
                       " | ", nrow(mk), " proteins tested (observed cells only)"))
        }
        # apply logFC threshold + positive-only filters to match the UI controls
        if (!is.null(input$s_mk_logfc))
          mk <- mk[abs(mk$avg_log2FC) >= input$s_mk_logfc | is.na(mk$avg_log2FC), ]
        if (isTRUE(input$s_mk_posonly))
          mk <- mk[!is.na(mk$avg_log2FC) & mk$avg_log2FC > 0, ]
        s$markers <- mk
        s$last_mk_mode <- "two"
      })
      showNotification(paste0(nrow(s$markers), " NA-aware marker results (",
                              toupper(input$s_mk_namethod %||% "proda"), ")."),
                       type="message", duration=5)
      return()
    }
    # ══════════════════════ end NA-aware marker intercept ═════════════════════

    # Work with either SCT or original assay depending on normalization method
    assay_mk <- if("SCT" %in% names(s$seu@assays)) "SCT" else input$s_assay
    req(assay_mk %in% names(s$seu@assays))
    withProgress(message="Finding markers...", value=0, {
      seu <- s$seu; Seurat::Idents(seu) <- input$s_mk_grpby

      # ── NA→0 substitution (user-chosen escape hatch for VSN/scpmed) ──────────
      # Only when the intensity-native method is set to "na_zero": replace NAs in
      # the data layer with 0 so standard FindMarkers can run. NOTE: this treats
      # 'not detected' as 'abundance zero' and biases fold-changes — the proDA
      # path avoids this. Chosen explicitly by the user.
      if ((input$s_norm_method %||% "sct") %in% .NA_AWARE &&
          (input$s_mk_namethod %||% "proda") == "na_zero") {
        dl <- tryCatch(as.matrix(SeuratObject::LayerData(seu@assays[[assay_mk]], layer="data")),
                       error=function(e) NULL)
        if (!is.null(dl) && anyNA(dl)) {
          dl[is.na(dl)] <- 0
          tryCatch(SeuratObject::LayerData(seu@assays[[assay_mk]], layer="data") <- dl,
                   error=function(e) NULL)
          s_log("NA→0 substitution applied to data layer for standard FindMarkers (user-selected).")
        }
      }

      # ── Seurat v5: ensure layers are joined before FindMarkers ───────────────
      # In Seurat v5 multi-sample objects the data layer may be split into
      # data.sample1 / data.sample2 etc. FindMarkers looks for a single "data"
      # layer and silently falls back to "counts" if it can't find one — meaning
      # results are computed on raw integers regardless of normalization.
      # JoinLayers collapses split layers into the single "data" layer FindMarkers needs.
      tryCatch({
        join_fn <- if (existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                   else if (requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                   else get("JoinLayers")
        seu[[assay_mk]] <- join_fn(seu[[assay_mk]])
        layer_names <- names(seu@assays[[assay_mk]]@layers)
        if (!"data" %in% layer_names)
          s_log(paste0("JoinLayers warning: 'data' layer still not found after join. Layers: ",
                       paste(layer_names, collapse=", ")))
        else
          s_log(paste0("JoinLayers OK: using normalized 'data' layer for ", assay_mk))
      }, error=function(e) {
        s_log(paste0("JoinLayers skipped (Seurat v4 or already joined): ", conditionMessage(e)))
      })

      # recorrect_umi only applies to SCT; ignored for LogNormalize
      use_recorrect <- assay_mk == "SCT"

      # ── PrepSCTFindMarkers — must run before FindMarkers when using SCT ──────
      # When SCTransform was run per group (⑥ writes one model per view), the SCT
      # assay holds several models fitted at different sequencing depths.
      # PrepSCTFindMarkers reverses each model at the MINIMUM of the per-model
      # median UMI, putting the corrected counts on one common depth so
      # fold-changes are comparable across clusters. It rewrites the counts and
      # data slots of the SCT assay (on this local copy only, so the plots in
      # other tabs still show the original SCT values).
      #
      # Runs AFTER Idents() is set above and on the full object, which is the
      # pattern Seurat documents. recorrect_umi stays TRUE below: the vignette
      # only sets it FALSE when testing a SUBSET of an already-prepped object,
      # which this tab never does.
      if (assay_mk == "SCT") {
        n_models <- tryCatch(length(slot(seu@assays[[assay_mk]], "SCTModel.list")),
                             error=function(e) NA_integer_)
        prepped <- FALSE
        tryCatch({
          incProgress(0.15, detail="PrepSCTFindMarkers (SCT assay)")
          seu <- Seurat::PrepSCTFindMarkers(seu, verbose=FALSE)
          prepped <- TRUE
          s_log(paste0("PrepSCTFindMarkers complete",
                       if (is.finite(n_models)) paste0(" (", n_models, " SCT model(s))") else ""))
        }, error=function(e) {
          s_log(paste0("PrepSCTFindMarkers FAILED: ", conditionMessage(e)))
        })
        if (!prepped) {
          # Be honest about what happens next. With more than one model at
          # unequal depths, FindMarkers(recorrect_umi=TRUE) does NOT silently
          # fall back — it raises "Object contains multiple models with
          # unequal library sizes", the very error Prep exists to prevent.
          multi <- is.finite(n_models) && n_models > 1
          showNotification(
            paste0("PrepSCTFindMarkers failed",
                   if (multi) paste0(" and this object holds ", n_models, " SCT models. ",
                                     "FindMarkers will stop with an 'unequal library sizes' ",
                                     "error rather than fall back. Re-run ⑥ (one SCTransform ",
                                     "over all cells avoids multiple models), or switch the ",
                                     "marker assay away from SCT.")
                   else paste0(". With a single SCT model the test can still run, but ",
                               "fold-changes are uncorrected for sequencing depth.")),
            type=if (multi) "error" else "warning", duration=16)
        }
      }

      # latent.vars only applies to MAST; ignored by all other tests
      # latent.vars is accepted by LR, MAST, negbinom and poisson only. The
      # admissibility rules differ: MAST's hurdle model needs numeric covariates,
      # while LR builds a glm design and takes factors as well.
      # A covariate selected under a test that cannot use it would otherwise be
      # silently ignored, which looks identical to it having been applied.
      if (!(input$s_mk_test %in% c("LR","MAST","negbinom","poisson")) &&
          length(c(input$s_mk_latent, input$s_mk_latent_num) %||% character(0)) > 0)
        showNotification(paste0("'", input$s_mk_test, "' cannot use covariates \u2014 it has no ",
                                "design matrix. The selected latent variables are IGNORED. ",
                                "Switch to LR or MAST for covariate-adjusted p-values."),
                         type="warning", duration=12)

      if (identical(as.numeric(.num(input$s_mk_minpct, 0.1)), 0) &&
          (input$s_norm_method %||% "sct") %in% .NA_AWARE)
        showNotification(paste0("Min pct is 0, so every feature is tested regardless of how ",
                                "few cells detected it. Features without enough observations ",
                                "for the design are excluded automatically, but a small value ",
                                "(0.05-0.1) is a better first filter."),
                         type="warning", duration=10)

      # An interaction is only implemented for the NA-aware engines (proDA and
      # limma). Selecting one with Seurat's FindMarkers or complete-case Wilcoxon
      # used to do nothing at all.
      if (!is.null(.de_interact())) {
        .na_ok <- (input$s_norm_method %||% "sct") %in% .NA_AWARE &&
                  (input$s_mk_namethod %||% "proda") %in% c("proda","limma")
        if (!.na_ok)
          showNotification(paste0("Interaction with '", .de_interact(), "' is IGNORED by this ",
                                  "test. It is implemented for the NA-aware proDA and limma ",
                                  "engines only \u2014 switch Method to one of those."),
                           type="warning", duration=14)
      }

      cov_tests <- c("LR","MAST","negbinom","poisson")
      # Categorical and continuous selections are separate inputs (checkbox groups
      # cannot be grouped in one), so the model takes their union.
      latent_pick <- unique(c(input$s_mk_latent, input$s_mk_latent_num))
      latent_vars <- if (input$s_mk_test %in% cov_tests && length(latent_pick) > 0) {
        vars_req <- intersect(latent_pick, names(seu@meta.data))

        # Cells the contrast will actually use, so a factor is judged on the
        # subset being tested rather than on the whole object. A level present
        # only outside the comparison contributes an all-zero dummy column.
        cells_cmp <- if (identical(input$s_mk_mode %||% "all", "two") &&
                         !is.null(input$s_mk_id1) && !is.null(input$s_mk_id2) &&
                         !is.null(grpby) && grpby %in% names(seu@meta.data)) {
          gv <- as.character(seu@meta.data[[grpby]])
          colnames(seu)[gv %in% c(input$s_mk_id1, input$s_mk_id2)]
        } else colnames(seu)

        why <- list()   # list, so why[["absent"]] is NULL rather than an error
        vars_ok <- vars_req[vapply(vars_req, function(v) {
          x <- seu@meta.data[cells_cmp, v]
          if (all(is.na(x))) { why[[v]] <<- "all NA"; return(FALSE) }
          if (is.numeric(x) && !(is.factor(x))) {
            if (length(unique(na.omit(x))) < 2) { why[[v]] <<- "constant"; return(FALSE) }
            return(TRUE)
          }
          # Categorical: needs at least two levels OCCUPIED among the compared
          # cells, and must not be nested inside the grouping variable.
          xx <- as.character(x); xx <- xx[!is.na(xx)]
          if (length(unique(xx)) < 2) { why[[v]] <<- "only one level in the compared cells"; return(FALSE) }
          if (!is.null(grpby) && grpby %in% names(seu@meta.data)) {
            gv <- as.character(seu@meta.data[cells_cmp, grpby])
            tb <- table(xx, gv[!is.na(as.character(x))])
            # Nested if every level of the covariate occurs in exactly one group:
            # the covariate is then a relabelling of the contrast.
            if (all(rowSums(tb > 0) <= 1)) {
              why[[v]] <<- paste0("nested within ", grpby,
                                  " \u2014 cannot be separated from the contrast")
              return(FALSE)
            }
          }
          TRUE
        }, logical(1))]

        dropped <- setdiff(vars_req, vars_ok)
        if (length(dropped))
          showNotification(paste0("Dropped from latent.vars: ",
                                  paste(vapply(dropped, function(v)
                                    paste0(v, " (", why[[v]] %||% "unusable", ")"),
                                    character(1)), collapse="; ")),
                           type="warning", duration=12)
        if (length(vars_ok) > 0) {
          s_log(paste0(input$s_mk_test, " latent.vars: ", paste(vars_ok, collapse=", ")))
          vars_ok
        } else NULL
      } else NULL

      incProgress(0.3, detail=paste0("FindMarkers (", assay_mk, " assay",
                                     if(!is.null(latent_vars))
                                       paste0(", latent: ", paste(latent_vars, collapse=","))
                                     else "", ")"))
      # ── MAST pre-flight ──────────────────────────────────────────────────
      # Everything that can be checked cheaply is checked here, because a failure
      # inside zlm() may abort the session rather than raise an R error.
      if ((input$s_mk_namethod %||% "proda") == "proda" &&
          (input$s_norm_method %||% "sct") %in% .NA_AWARE) {
        .mm_pf <- tryCatch(.norm_mat(s$seu), error=function(e) NULL)
        if (!is.null(.mm_pf)) {
          .nf <- nrow(.mm_pf); .nc <- ncol(.mm_pf)
          .ns <- .num(input$s_mk_proda_nsub, 500)
          if (.nf * .nc > 1e6 && !(.ns >= 100 && .ns < .nf))
            showNotification(paste0(
              "proDA on ", .nf, " features \u00d7 ", .nc, " cells with n_subsample = all. ",
              "This can run for an hour or more: proDA was built for bulk MS (thousands of ",
              "proteins, tens of samples), and at single-cell width every EM iteration ",
              "re-optimises a censored likelihood over hundreds of points per feature. ",
              "Set n_subsample to 500, or run limma with the same design first \u2014 it is ",
              "far faster and still moderates variance."),
              type="warning", duration=20)
        }
      }

      if (identical(input$s_mk_test, "MAST")) {
        if (!requireNamespace("MAST", quietly = TRUE)) {
          showNotification(paste0("MAST is not installed. ",
                                  "BiocManager::install('MAST'), then restart R."),
                           type="error", duration=15)
          return()
        }
        n_feat_mast <- nrow(seu[[assay_mk]])
        n_cell_mast <- ncol(seu)
        # Keep MAST single-threaded for this observer. zlm() dispatches through
        # plyr with .parallel = TRUE; with no foreach backend registered that only
        # warns, but if one IS registered then forking inside a Shiny process is
        # unsafe and an abort in a child takes the session with it. Setting
        # mc.cores here cannot affect the other tests, unlike passing
        # parallel = FALSE through Seurat's `...`.
        .old_mc <- getOption("mc.cores")
        options(mc.cores = 1L)
        on.exit(options(mc.cores = .old_mc), add = TRUE)
        s_log(paste0("MAST pre-flight: ", n_feat_mast, " features \u00d7 ", n_cell_mast,
                     " cells, latent.vars=",
                     if (length(latent_vars)) paste(latent_vars, collapse="+") else "none",
                     ", mc.cores forced to 1."))
        if (n_feat_mast > 6000)
          showNotification(paste0("MAST on ", n_feat_mast, " features fits a hurdle model per ",
                                  "feature and builds a large summary table \u2014 this is the ",
                                  "usual cause of the session running out of memory and ",
                                  "closing. Raise Min pct to cut the feature count, or use ",
                                  "proDA / limma, which model the same missingness and are ",
                                  "far lighter."),
                           type="warning", duration=18)
      }

      mk <- tryCatch({
        if(input$s_mk_mode=="all") {
          Seurat::FindAllMarkers(seu, assay=assay_mk, test.use=input$s_mk_test,
                                 logfc.threshold=input$s_mk_logfc, min.pct=input$s_mk_minpct,
                                 only.pos=input$s_mk_posonly, verbose=FALSE,
                                 latent.vars=latent_vars,
                                 recorrect_umi=use_recorrect)
        } else {
          m <- Seurat::FindMarkers(seu, assay=assay_mk, ident.1=input$s_mk_id1, ident.2=input$s_mk_id2,
                                    test.use=input$s_mk_test, logfc.threshold=input$s_mk_logfc,
                                    min.pct=input$s_mk_minpct, only.pos=input$s_mk_posonly,
                                    verbose=FALSE, latent.vars=latent_vars,
                                    recorrect_umi=use_recorrect)
          m$gene <- rownames(m); m$cluster <- paste0(input$s_mk_id1," vs ",input$s_mk_id2); m
        }
      }, error=function(e) {
        msg <- conditionMessage(e)
        if (grepl("MAST", msg, ignore.case=TRUE))
          showNotification(
            "MAST is not installed. Install with: BiocManager::install('MAST'). Switching to Wilcoxon is recommended.",
            type="error", duration=12)
        else if (grepl("recorrect_umi", msg, ignore.case=TRUE))
          # Older Seurat version — retry without recorrect_umi
          tryCatch({
            if(input$s_mk_mode=="all")
              Seurat::FindAllMarkers(seu, assay=assay_mk, test.use=input$s_mk_test,
                                     logfc.threshold=input$s_mk_logfc, min.pct=input$s_mk_minpct,
                                     only.pos=input$s_mk_posonly, verbose=FALSE,
                                     latent.vars=latent_vars)
            else {
              m <- Seurat::FindMarkers(seu, assay=assay_mk, ident.1=input$s_mk_id1,
                                        ident.2=input$s_mk_id2, test.use=input$s_mk_test,
                                        logfc.threshold=input$s_mk_logfc, min.pct=input$s_mk_minpct,
                                        only.pos=input$s_mk_posonly, verbose=FALSE,
                                        latent.vars=latent_vars)
              m$gene <- rownames(m); m$cluster <- paste0(input$s_mk_id1," vs ",input$s_mk_id2); m
            }
          }, error=function(e2) { showNotification(conditionMessage(e2), type="error", duration=10); NULL })
        else {
          showNotification(paste0("FindMarkers error: ", msg), type="error", duration=10)
          NULL
        }
      })
      req(!is.null(mk), nrow(mk) > 0)
      s$markers      <- mk
      s$last_mk_mode <- input$s_mk_mode
      s$last_mk_grp  <- input$s_mk_grpby
      s$last_mk_comp <- if (input$s_mk_mode=="all")
        paste0("All clusters (", length(unique(Seurat::Idents(seu))), " groups)")
      else
        paste0(input$s_mk_id1, "  vs  ", input$s_mk_id2)
      s_log(paste0("Markers: ", nrow(mk), " results",
                   " | test=", input$s_mk_test,
                   " | assay=", assay_mk,
                   " | logfc.threshold=", input$s_mk_logfc,
                   " | min.pct=", input$s_mk_minpct,
                   " | only.pos=", isTRUE(input$s_mk_posonly),
                   if(!is.null(latent_vars)) paste0(" | latent.vars: ", paste(latent_vars, collapse=", ")) else "",
                   " — ", s$last_mk_comp))
    })
    showNotification(paste0(nrow(s$markers)," marker results."),type="message",duration=4)
  })

  # ── Underflow-safe p-value reporting ───────────────────────────────────────
  # A double cannot represent anything below ~5e-324, so proDA's $pval becomes
  # exactly 0 once the test statistic is large enough and every digit of
  # precision is already gone by the time the value reaches this app. No display
  # format can recover it. The statistic and its df, however, are finite and
  # exact, so the p-value is recomputed on the log scale with log.p=TRUE, which
  # never underflows, and reported as -log10(p).
  .proda_log_p <- function(res) {
    if (all(c("t_statistic","df") %in% names(res))) {
      log(2) + stats::pt(-abs(as.numeric(res$t_statistic)),
                         df = as.numeric(res$df), log.p = TRUE)
    } else if (all(c("f_statistic","df1","df2") %in% names(res))) {
      stats::pf(as.numeric(res$f_statistic), df1 = as.numeric(res$df1),
                df2 = as.numeric(res$df2), lower.tail = FALSE, log.p = TRUE)
    } else {
      pv <- as.numeric(res$pval); pv[!is.finite(pv) | pv <= 0] <- NA_real_; log(pv)
    }
  }

  # Benjamini-Hochberg entirely in log space: log(n/i) + log(p), then a running
  # minimum from the largest p downward, capped at log(1) = 0. Identical to
  # p.adjust(method="BH") but finite where the raw p-values would have hit 0.
  .bh_log <- function(log_p) {
    out <- rep(NA_real_, length(log_p))
    ok  <- is.finite(log_p)
    lp  <- log_p[ok]; n <- length(lp)
    if (n == 0) return(out)
    o  <- order(lp, decreasing = TRUE); ro <- order(o)
    out[ok] <- pmin(0, cummin(lp[o] + log(n) - log(n:1)))[ro]
    out
  }

  # Render an exact scientific-notation p-value from -log10(p), with no ceiling
  # on the exponent. log10(p) is split into its integer part (the exponent) and
  # its fractional part (the mantissa), so 1e-1043 prints as 1.000000e-1043
  # rather than collapsing to 0. Mantissas that round up to 10 are carried.
  .fmt_nlog10_p <- function(nlp) {
    out <- rep(NA_character_, length(nlp))
    ok  <- is.finite(nlp)
    if (!any(ok)) return(out)
    l10 <- -nlp[ok]
    ex  <- floor(l10)
    man <- 10^(l10 - ex)
    carry <- man >= 9.9999995
    man[carry] <- man[carry] / 10; ex[carry] <- ex[carry] + 1
    txt <- sprintf("%.6fe%+03d", man, as.integer(ex))
    txt[nlp[ok] <= 0] <- "1.000000e+00"        # p == 1 exactly
    out[ok] <- txt
    out
  }

  # Volcano y-axis. Prefers the precomputed neg_log10_p column, which stays
  # finite where p_val underflowed to 0. The old expression was
  # -log10(PVAL + 1e-300): that pseudocount silently pinned the axis at 300, so
  # every strongly significant protein collapsed onto one flat line at the top
  # of the plot. Falls back to it only for tests that supply no log column.
  .vol_nlp <- function(mk) {
    v <- if ("neg_log10_p" %in% names(mk)) as.numeric(mk$neg_log10_p)
         else rep(NA_real_, nrow(mk))
    bad <- !is.finite(v)
    if (any(bad))
      v[bad] <- -log10(pmax(as.numeric(mk$PVAL)[bad], 1e-300))
    v
  }

  # Helper: format a markers data.frame for DT display with scientific notation on p-values
  fmt_markers_dt <- function(mk) {
    p_cols   <- intersect(c("p_val","p_val_adj","pvalue","padj","p.value","p.adj"), names(mk))

    # p-values first, at full precision. Where the stored double underflowed to
    # 0 the true value is rebuilt from its -log10 partner and printed in the
    # SAME column, so p_val reads 6.678124e-1044 rather than 0. This must run
    # before the rounding below, which would otherwise blunt the mantissa.
    nlp_for <- c(p_val = "neg_log10_p", p_val_adj = "neg_log10_p_adj")
    for (col in p_cols) {
      v   <- as.numeric(mk[[col]])
      txt <- formatC(v, format="e", digits=6)
      nc  <- nlp_for[[col]] %||% NA_character_
      if (!is.na(nc) && nc %in% names(mk)) {
        fix <- !is.na(v) & v == 0
        if (any(fix)) txt[fix] <- .fmt_nlog10_p(as.numeric(mk[[nc]])[fix])
      }
      txt[is.na(txt)] <- "NA"
      mk[[col]] <- txt
    }

    # Round every remaining numeric column, -log10 columns included: 4 dp is
    # ample for reading and sorting, and the p_val strings above were built
    # from the unrounded values.
    num_cols <- setdiff(names(mk)[sapply(mk, is.numeric)], p_cols)
    for (col in num_cols) mk[[col]] <- round(mk[[col]], 4)

    datatable(mk, filter="top", options=list(pageLength=15, scrollX=TRUE))
  }

  output$s_mk_tbl <- renderDT({ req(s$markers); fmt_markers_dt(s$markers) })
  output$s_mk_dl_ui <- renderUI({ req(s$markers); downloadButton("s_mk_dl_now","⬇ Download Results",class="btn-success") })
  output$s_mk_dl_now <- downloadHandler(filename=function()paste0("markers_",Sys.Date(),".csv"),content=function(file) readr::write_csv(s$markers,file))

  # ── Markers: cluster overlap / specificity ─────────────────────────────────
  # Answers "which features mark ONE population?". Each row of s$markers is a
  # feature tested in one cluster's one-vs-rest contrast, so counting how many
  # clusters a feature clears the cutoffs in gives its specificity directly.
  # Requires All-clusters mode; a two-group run has only one contrast.
  output$s_ov_clusters_ui <- renderUI({
    req(s$markers)
    if (!"cluster" %in% names(s$markers)) return(NULL)
    cl <- sort(unique(as.character(s$markers$cluster)))
    checkboxGroupInput("s_ov_clusters", "Clusters to compare:",
                       choices=cl, selected=cl, inline=TRUE)
  })

  # ── proDA / NA-aware run settings snapshot ──────────────────────────────────
  # Every user-alterable setting that feeds an intensity-native marker run, as a
  # character vector for the activity log. Written once per run so the Export
  # tab's log — and the log .txt that ships next to the results — records what
  # actually produced the numbers, rather than whatever the widgets happen to
  # read at export time. `prefix` is "s_mk" for ⑨ or "i_mk" for ⑫; the proDA
  # speed controls live only on ⑨ and govern both tabs, so they are always read
  # from s_mk_*.
  .proda_settings_lines <- function(prefix = "s_mk") {
    g  <- function(nm) input[[paste0(prefix, "_", nm)]]
    tag <- if (identical(prefix, "i_mk")) "\u246b integrated" else "\u2468"
    meth <- g("namethod") %||% "proda"
    ln <- c(paste0("\u2500\u2500 ", tag, " run settings (", toupper(meth), ") \u2500\u2500"))

    mode <- g("mode") %||% "all"
    ln <- c(ln, paste0("  mode          : ", if (identical(mode,"all")) "all clusters (one-vs-rest)" else "two groups"),
                paste0("  grouping var  : ", g("grpby") %||% "(unset)"))
    if (identical(mode, "two"))
      ln <- c(ln, paste0("  comparison    : ", g("id1") %||% "?", " vs ", g("id2") %||% "?"))

    ln <- c(ln, paste0("  normalization : ", input$s_norm_method %||% "sct",
                       "  |  assay: ", input$s_assay %||% "(unset)"))

    # proDA's own knobs (shared across both tabs).
    if (identical(meth, "proda")) {
      nsub <- suppressWarnings(as.integer(.num(input$s_mk_proda_nsub, 0)))
      ln <- c(ln,
        paste0("  n_subsample   : ", if (is.finite(nsub) && nsub >= 100) nsub
                                     else "all features (no subsampling)"),
        paste0("  max_iter      : ", as.integer(.num(input$s_mk_proda_maxit, 20))),
        paste0("  epsilon       : ", .num(input$s_mk_proda_eps, 0.001)),
        paste0("  verbose       : ", isTRUE(input$s_mk_proda_verbose)))
    }

    # Design: covariates, spline basis, interaction.
    if (meth %in% c("proda","limma")) {
      cats <- input[[paste0(prefix, "_proda_cov")]]      %||% character(0)
      nums <- input[[paste0(prefix, "_proda_cov_cont")]] %||% character(0)
      ln <- c(ln,
        paste0("  covariates    : ",
               if (!length(cats) && !length(nums)) "none (~ group)"
               else paste0("~ group + ", paste(c(cats, nums), collapse=" + "))),
        paste0("  categorical   : ", if (length(cats)) paste(cats, collapse=", ") else "\u2014"),
        paste0("  continuous    : ", if (length(nums)) paste(nums, collapse=", ") else "\u2014"))
      sdf <- tryCatch(if (identical(prefix,"i_mk")) .de_spline_df() else .de_spline_df(),
                      error=function(e) NA)
      if (length(nums))
        ln <- c(ln, paste0("  spline df     : ", sdf,
                           if (identical(sdf, 1)) "  (linear)" else "  (natural spline on continuous covariates)"))
      iv <- tryCatch(if (identical(prefix,"i_mk")) .i_de_interact() else .de_interact(),
                     error=function(e) NULL)
      ln <- c(ln, paste0("  interaction   : ", if (is.null(iv)) "none" else paste0("group \u00d7 ", iv)))
      ln <- c(ln, paste0("  variable feats only: ", isTRUE(input$s_mk_vf_only)))
    }

    # Post-test filters applied by Seurat/the app to the reported table.
    ln <- c(ln,
      paste0("  min log2FC    : ", .num(g("logfc"),  0.25)),
      paste0("  min pct       : ", .num(g("minpct"), 0.1)),
      paste0("  positive only : ", isTRUE(g("posonly"))))
    ln
  }

  # Write the snapshot to the activity log, one line per setting.
  .log_proda_settings <- function(prefix = "s_mk") {
    for (l in .proda_settings_lines(prefix)) s_log(l)
    invisible(TRUE)
  }

  # Marker-overlap / specificity computation, shared by the ⑨ Markers tab and
  # the ⑫ Integrated Markers tab. Takes the cutoffs as plain arguments rather
  # than reading input$ directly, so the two tabs can keep independent controls
  # (s_ov_* and i_ov_*) over identical logic. Returns the list .build_overlap_plot
  # expects: list(sets, tab, dir, sel, n_tested).
  .overlap_compute <- function(mk, p_t, fc_t, pct_t, dir, sel = NULL) {
    if (is.null(mk) || !nrow(mk) || !"cluster" %in% names(mk)) return(NULL)
    is_roc <- .mk_is_roc(mk)
    gene <- if ("gene" %in% names(mk)) as.character(mk$gene) else rownames(mk)
    fc   <- if ("avg_log2FC" %in% names(mk)) mk$avg_log2FC
            else if ("avg_diff" %in% names(mk)) mk$avg_diff
            else rep(NA_real_, nrow(mk))
    # ROC has no p-value, so `power` becomes the significance axis and the
    # comparison flips to >= rather than <=.
    sig  <- if (is_roc && "power" %in% names(mk)) mk$power
            else if ("p_val_adj" %in% names(mk)) mk$p_val_adj
            else mk$p_val

    keep <- if (is_roc) !is.na(sig) & sig >= p_t else !is.na(sig) & sig <= p_t
    keep <- keep & !is.na(fc) & abs(fc) >= fc_t
    if (dir == "up")   keep <- keep & fc > 0
    if (dir == "down") keep <- keep & fc < 0
    if (pct_t > 0 && "pct.1" %in% names(mk))
      keep <- keep & !is.na(mk$pct.1) & mk$pct.1 >= pct_t

    df <- unique(data.frame(gene    = gene[keep],
                            cluster = as.character(mk$cluster)[keep],
                            stringsAsFactors = FALSE))
    if (is.null(sel) || !length(sel)) sel <- sort(unique(as.character(mk$cluster)))
    df  <- df[df$cluster %in% sel, , drop=FALSE]
    n_tested <- length(unique(gene))
    if (!nrow(df))
      return(list(sets=list(), tab=NULL, dir=dir, sel=sel, n_tested=n_tested))

    lev  <- sel[sel %in% df$cluster]
    sets <- split(df$gene, factor(df$cluster, levels=lev))

    n_by  <- table(df$gene)
    cl_by <- tapply(df$cluster, df$gene, function(x) paste(sort(unique(x)), collapse=", "))
    tab <- data.frame(gene        = names(n_by),
                      n_clusters  = as.integer(n_by),
                      clusters    = as.character(cl_by[names(n_by)]),
                      stringsAsFactors = FALSE)
    tab$specific_to <- ifelse(tab$n_clusters == 1, tab$clusters, NA_character_)
    tab <- tab[order(tab$n_clusters, tab$gene), , drop=FALSE]
    list(sets=sets, tab=tab, dir=dir, sel=sel, n_tested=n_tested)
  }

  s_overlap_data <- reactive({
    .overlap_compute(s$markers,
                     p_t   = .num(input$s_ov_p, 0.05),
                     fc_t  = .num(input$s_ov_fc, 0.5),
                     pct_t = .num(input$s_ov_minpct, 0),
                     dir   = input$s_ov_dir %||% "up",
                     sel   = input$s_ov_clusters)
  })

  # Same computation on the INTEGRATED marker table (⑫), with its own cutoffs.
  i_overlap_data <- reactive({
    .overlap_compute(s$int_markers,
                     p_t   = .num(input$i_ov_p, 0.05),
                     fc_t  = .num(input$i_ov_fc, 0.5),
                     pct_t = .num(input$i_ov_minpct, 0),
                     dir   = input$i_ov_dir %||% "up",
                     sel   = input$i_ov_clusters)
  })

  # Shared by the interactive plot and the PDF export, so both stay identical.
  # Handles the ggplot types only; UpSet is drawn separately in renderPlot.
  .build_overlap_plot <- function(d, type, fs=13) {
    if (is.null(d) || !length(d$sets)) return(NULL)
    sets <- d$sets; k <- length(sets)
    dir_lbl <- switch(d$dir, up="up-regulated", down="down-regulated", "either direction")
    ttl <- paste0("Cluster-specific markers (", dir_lbl, ") \u2014 ", k, " clusters compared")

    if (identical(type, "venn")) {
      if (!requireNamespace("ggVennDiagram", quietly=TRUE))
        stop("ggVennDiagram required: install.packages('ggVennDiagram')", call.=FALSE)
      if (k < 2 || k > 5)
        stop(paste0("A Venn diagram needs 2\u20135 sets and ", k, " clusters are selected.\n",
                    "Deselect clusters, or switch Plot to 'Exclusivity barplots' / 'UpSet'."),
             call.=FALSE)
      ggVennDiagram::ggVennDiagram(sets, label_alpha=0, label="count") +
        scale_fill_gradient(low="grey92", high="#2980B9") +
        labs(title=ttl, fill="Features") +
        theme(legend.position="bottom", plot.title=element_text(size=fs))

    } else {
      tab <- d$tab
      # Panel A: how many clusters each feature passes in. The bar at 1 is the
      # cluster-specific set, which is the whole point of the tab.
      cnt <- table(tab$n_clusters)
      ord <- order(as.integer(names(cnt)))
      deg <- data.frame(n_clusters = factor(names(cnt)[ord], levels=names(cnt)[ord]),
                        features   = as.integer(cnt)[ord])
      pa <- ggplot(deg, aes(x=n_clusters, y=features)) +
        geom_col(fill="#2980B9", width=0.75) +
        geom_text(aes(label=features), vjust=-0.35, size=fs/4) +
        scale_y_continuous(expand=expansion(mult=c(0, 0.12))) +
        theme_classic(base_size=fs) +
        labs(x="Number of clusters the feature passes in", y="Features",
             title="Marker sharing", subtitle="Bar at 1 = cluster-specific")

      # Panel B: per-cluster split into exclusive vs shared.
      excl_g <- tab$gene[tab$n_clusters == 1]
      per <- do.call(rbind, lapply(names(sets), function(cl) {
        g <- sets[[cl]]
        data.frame(cluster   = cl,
                   Exclusive = sum(g %in% excl_g),
                   Shared    = sum(!(g %in% excl_g)), stringsAsFactors=FALSE)
      }))
      per$cluster <- factor(per$cluster, levels=names(sets))
      per_l <- tidyr::pivot_longer(per, c("Exclusive","Shared"),
                                   names_to="Class", values_to="n")
      per_l$Class <- factor(per_l$Class, levels=c("Shared","Exclusive"))
      pb <- ggplot(per_l, aes(x=cluster, y=n, fill=Class)) +
        geom_col(width=0.75) +
        scale_fill_manual(values=c(Shared="grey80", Exclusive="#E67E22")) +
        theme_classic(base_size=fs) +
        theme(legend.position="bottom") +
        labs(x="Cluster", y="Features", fill=NULL, title="Per-cluster breakdown")

      patchwork::wrap_plots(pa, pb, ncol=2) +
        patchwork::plot_annotation(title=ttl)
    }
  }

  .ov_msg <- function(txt, col="grey50") {
    plot(0, type="n", axes=FALSE, xlab="", ylab="")
    text(0, 0, txt, cex=1.05, col=col)
    invisible(NULL)
  }

  output$s_mk_overlap <- renderPlot({
    d <- s_overlap_data()
    if (is.null(d))
      return(.ov_msg(paste0("No cluster column in the results.\n",
                            "Run Find Markers with Mode = all clusters first.")))
    if (!length(d$sets))
      return(.ov_msg("No features pass the current cutoffs \u2014 loosen them above."))

    type <- input$s_ov_type %||% "auto"
    if (identical(type, "auto")) type <- if (length(d$sets) <= 4) "venn" else "excl"

    if (identical(type, "upset")) {
      if (!requireNamespace("UpSetR", quietly=TRUE))
        return(.ov_msg("UpSetR not installed: install.packages('UpSetR')", "#C0392B"))
      if (length(d$sets) < 2)
        return(.ov_msg("UpSet needs at least 2 clusters.", "#C0392B"))
      return(UpSetR::upset(UpSetR::fromList(d$sets),
                           nsets=length(d$sets), nintersects=30, order.by="freq",
                           mainbar.y.label="Features in intersection",
                           sets.x.label="Features per cluster",
                           text.scale=1.1))
    }
    p <- tryCatch(.build_overlap_plot(d, type, 13), error=function(e) e)
    if (inherits(p, "error")) return(.ov_msg(conditionMessage(p), "#C0392B"))
    if (is.null(p)) return(.ov_msg("Nothing to plot."))
    print(p)
  })

