  output$s_vol_cluster_ui <- renderUI({
    req(s$markers)
    if (input$s_mk_mode == "all") {
      clusters <- sort(unique(as.character(s$markers$cluster)))
      tagList(
        tags$b("Highlight cluster:", style="font-size:12px;"),
        selectInput("s_vol_cluster","", choices=c("All clusters"="all", clusters), selected="all")
      )
