      tags$p(tags$small(paste0("Comparison: ", s$last_mk_comp %||% "")),
             style="color:#2980B9;font-weight:600;font-size:12px;margin-top:8px;")
    }
  })

  output$s_vol_label_ui <- renderUI({
    req(s$markers)
    vh <- function(x,d) if(!is.null(x) && grepl("^#[0-9A-Fa-f]{6}$",x)) x else d
    uc <- vh(input$s_vol_up_col,"#E74C3C"); dc <- vh(input$s_vol_down_col,"#2E86C1")
    if (input$s_mk_mode == "two") {
      comp  <- s$last_mk_comp %||% "A vs B"
      parts <- strsplit(comp, "  vs  ")[[1]]
      grp_a <- if(length(parts)==2) trimws(parts[1]) else "Group A"
      grp_b <- if(length(parts)==2) trimws(parts[2]) else "Group B"
      tagList(
        tags$p(tags$span("●", style=paste0("color:",uc,";")), tags$b(paste0(" Up in ", grp_a)), style="font-size:12px;margin:4px 0;"),
        tags$p(tags$span("●", style=paste0("color:",dc,";")), tags$b(paste0(" Up in ", grp_b)), style="font-size:12px;margin:4px 0;")
      )
    } else {
      sel <- input$s_vol_cluster %||% "all"
      if (sel != "all")
        tagList(
          tags$p(tags$span("●", style=paste0("color:",uc,";")), tags$b(paste0(" Up in Cluster ", sel)), style="font-size:12px;margin:4px 0;"),
          tags$p(tags$span("●", style=paste0("color:",dc,";")), tags$b(paste0(" Down in Cluster ", sel)), style="font-size:12px;margin:4px 0;")
        )
    }
  })

  # Volcano feature pickers. updateSelectizeInput(server=TRUE) rather than a
  # choices= on the input: marker tables routinely run to thousands of features
  # and shipping them all into the page makes the control crawl.
  observeEvent(s$markers, {
    ch <- .vol_pick_choices(s$markers)
    updateSelectizeInput(session, "s_vol_pick", choices=ch,
                         selected=intersect(input$s_vol_pick, ch), server=TRUE)
  }, ignoreNULL=FALSE)

  output$s_mk_volcano <- renderPlotly({
    req(s$markers); mk <- s$markers
    is_roc <- .mk_is_roc(mk)
    fc_col <- if("avg_log2FC" %in% names(mk)) "avg_log2FC"
              else if("avg_diff" %in% names(mk)) "avg_diff"
              else names(mk)[grep("log2fc|logfc",names(mk),ignore.case=TRUE)[1]]
    if (is_roc) {
      # ROC has no p-value: use power as the y significance axis, avg_diff as x.
      p_col <- "power"; padj_col <- "power"
    } else {
      p_col  <- if("p_val" %in% names(mk)) "p_val" else if("p_val_adj" %in% names(mk)) "p_val_adj" else "p_val"
      padj_col <- if("p_val_adj" %in% names(mk)) "p_val_adj" else p_col
    }
    mk$FC    <- mk[[fc_col]]; mk$PADJ <- mk[[padj_col]]; mk$PVAL <- mk[[p_col]]
    mk$Gene  <- if("gene" %in% names(mk)) mk$gene else rownames(mk)
    mk$Cluster <- if("cluster" %in% names(mk)) as.character(mk$cluster) else "?"

    fc_t <- .num(input$s_vol_fc, 0.5)
    p_t  <- if (is_roc) (.num(input$s_vol_p, 0.4)) else (.num(input$s_vol_p, 0.05))
    sel  <- input$s_vol_cluster %||% "all"

    # Display cap on |log2FC|. Removes points whose coefficient is too large to be
    # a real fold change, which otherwise compress every genuine effect into the
    # centre of the axis. PLOT ONLY \u2014 s$markers and the exports are untouched.
    fc_cap <- suppressWarnings(as.numeric(.num(input$s_vol_cap, 0)))
    n_capped <- 0L
    if (length(fc_cap) == 1 && is.finite(fc_cap) && fc_cap > 0) {
      n_capped <- sum(abs(mk$FC) > fc_cap, na.rm=TRUE)
      mk <- mk[is.na(mk$FC) | abs(mk$FC) <= fc_cap, , drop=FALSE]
    }

    if (input$s_mk_mode == "all" && sel != "all") {
      mk_plot <- mk[mk$Cluster == sel, , drop=FALSE]
      grp_a <- paste0("Cluster ", sel); grp_b <- "all others"
    } else {
      mk_plot <- mk
      if (input$s_mk_mode == "two") {
        comp  <- s$last_mk_comp %||% "A vs B"
        parts <- strsplit(comp, "  vs  ")[[1]]
        grp_a <- if(length(parts)==2) trimws(parts[1]) else "Group A"
        grp_b <- if(length(parts)==2) trimws(parts[2]) else "Group B"
      } else {
        grp_a <- "cluster (positive FC)"; grp_b <- "all others"
      }
    }
    if (nrow(mk_plot) == 0)
      return(plotly::plotly_empty() %>%
               plotly::layout(title="No results for selected cluster — choose a different cluster or run All Markers."))

    # significance direction: ROC uses power >= threshold, else p.adj <= threshold
    sig_ok <- if (is_roc) mk_plot$PADJ >= p_t else mk_plot$PADJ <= p_t
    mk_plot$Dir <- dplyr::case_when(
      abs(mk_plot$FC)>=fc_t & sig_ok & mk_plot$FC>0 ~ "Up",
      abs(mk_plot$FC)>=fc_t & sig_ok & mk_plot$FC<0 ~ "Down",
      TRUE ~ "NS")

    n_up <- sum(mk_plot$Dir=="Up", na.rm=TRUE)
    n_dn <- sum(mk_plot$Dir=="Down", na.rm=TRUE)

    # user-selectable up/down colors (validated hex, fall back to defaults)
    valid_hex <- function(x, d) if(!is.null(x) && grepl("^#[0-9A-Fa-f]{6}$", x)) x else d
    up_col   <- valid_hex(input$s_vol_up_col,   "#E74C3C")
    down_col <- valid_hex(input$s_vol_down_col, "#2E86C1")
    vol_cols <- c("Up"=up_col, "Down"=down_col, "NS"="grey70")

    # top-N features to label: strongest by significance among Up/Down, split
    # so both directions get labeled. y-axis is power (ROC) or -log10 p.
    mk_plot$yval <- if (is_roc) mk_plot$PADJ else .vol_nlp(mk_plot)
    mk_plot$do_label <- .vol_label_rows(mk_plot, input$s_vol_label_mode %||% "pval",
                                        .num(input$s_vol_nlabel, 0), input$s_vol_pick)

    title_str <- if (input$s_mk_mode=="all" && sel!="all")
      paste0("Cluster ", sel, " vs all others  |  ↑", n_up, " up  ↓", n_dn, " down")
    else if (input$s_mk_mode=="two")
      paste0(grp_a, " vs ", grp_b, "  |  ↑", n_up, " up in ", grp_a, "  ↓", n_dn, " up in ", grp_b)
    else paste0("All clusters  |  ", nrow(mk_plot), " proteins")

    mk_plot$tooltip <- if (is_roc) paste0(
      mk_plot$Gene,
      if("cluster" %in% names(mk_plot)) paste0("<br>Cluster: ", mk_plot$Cluster) else "",
      "<br>avg_diff: ", round(mk_plot$FC,3),
      "<br>power: ",    round(mk_plot$PADJ,3),
      if("myAUC" %in% names(mk_plot)) paste0("<br>myAUC: ", round(mk_plot$myAUC,3)) else "")
    else paste0(
      mk_plot$Gene,
      if("cluster" %in% names(mk_plot)) paste0("<br>Cluster: ", mk_plot$Cluster) else "",
      "<br>log2FC: ", round(mk_plot$FC,3),
      "<br>p_val: ",  formatC(mk_plot$PVAL, format="e", digits=2),
      "<br>p.adj: ",  formatC(mk_plot$PADJ, format="e", digits=2))

    ycol <- if (is_roc) "PADJ" else "yval"
    p <- ggplot(mk_plot, aes(x=FC, y=.data[[ycol]], text=tooltip)) +
      .vol_pt(size=2) +
      scale_fill_manual(values=vol_cols,
                        labels=c(paste0("Up in ",grp_a), paste0("Up in ",grp_b), "NS")) +
      geom_vline(xintercept=c(-fc_t,fc_t), linetype="dashed", color="grey40") +
      geom_hline(yintercept=if (is_roc) p_t else -log10(p_t),
                 linetype="dashed", color="grey40") +
      theme_classic(base_size=13) +
      labs(title=title_str,
           x=paste0(if (is_roc) "avg_diff" else "avg_log2FC",
                    "  (positive = higher in ", grp_a, ")"),
           y=if (is_roc) "ROC power (|2·AUC − 1|)" else "-log10(p_val)",
           fill="")
    p <- p + { .vol_xlim("s_vol") }
    sub_txt <- .vol_subtitle(n_capped, input$s_vol_pick, mk_plot)
    if (!is.null(sub_txt)) p <- p + labs(subtitle=sub_txt)
    # Labels are added AFTER conversion as plotly annotations, not as a ggplot
    # layer: ggplotly drops geom_text_repel entirely, and a plain geom_text has
    # no leader line and can be drawn under later traces.
    .vol_annotate(.vol_outline(ggplotly(p, tooltip="text")),
                  mk_plot[mk_plot$do_label, , drop=FALSE], "FC", ycol, "Gene")
  })

  output$s_mk_vln_ui <- renderUI({
    req(s$seu)
    # Offer all features; pre-select top significant markers if available
    all_feats <- .opt_clean(rownames(s$seu), "features")
    pre <- if (!is.null(s$markers) && "gene" %in% names(s$markers))
      head(.mk_order(s$markers)[, "gene"], 6)
    else head(all_feats, 6)
    pre <- intersect(pre, all_feats)
    tagList(
      selectizeInput("s_mk_vln_genes","Proteins to violin plot (type to search):",
                     choices=all_feats, multiple=TRUE, selected=pre,
                     options=list(maxItems=12, placeholder="Search proteins...")),
      numericInput("s_mk_vln_ncol","Columns:",value=3,min=1,max=6),
      conditionalPanel(
        "input.s_norm_method == 'vsn' || input.s_norm_method == 'scpmed' || input.s_norm_method == 'log2'",
        radioButtons("s_mk_disp_src", "Plot which layer?", inline=FALSE,
          choices=c("data \u2014 normalized, as tested" = "data",
                    "data \u2014 observed cells only (not-detected omitted)" = "data_obs",
                    "scale.data \u2014 z-scored, covariates regressed out" = "scale.data"),
          selected="data"),
        tags$p(tags$small(
          tags$b("data"), " is the normalization output with nothing removed \u2014 the same ",
          "matrix proDA / limma test, so group medians correspond to the reported ",
          "effect sizes. Covariates are adjusted for inside the model, not taken out ",
          "of the values. ",
          tags$b("scale.data"), " has the \u2465 covariates regressed out and is z-scored ",
          "per protein, so it matches the heatmaps and is closest to what the PCA saw \u2014 ",
          "but not-detected sits at 0, the center of the scale, so missingness and ",
          "average abundance look alike."),
          style="color:grey;font-size:11px;"))
    )
  })
  # ── WHAT IS BEING PLOTTED ────────────────────────────────────────────────────
  # On the intensity-native routes three different versions of the data exist,
  # and a feature-level plot has to choose one. They answer different questions:
  #
  #   "data"     the data layer — the normalized matrix with NO covariate
  #              regression. This is what proDA / limma actually test; covariates
  #              are adjusted for inside the model, not removed from the data.
  #              A violin drawn from this matrix shows the values behind the
  #              p-value, so group medians line up with the reported effect.
  #
  #   "scale.data" the covariate-regressed, z-scored layer
  #              intercept + retained effect + residual. Nuisance covariates have
  #              been removed, so this matches the PCA/UMAP layout, which was also
  #              built after regression. Use it when asking "where does this
  #              protein sit once depth is accounted for".
  #
  #   (scale.data is never plotted as a feature value; it is z-scored with
  #    not-detected filled at 0 and exists for heatmaps only.)
  #
  # Neither is more correct in the abstract: the right choice is whichever matches
  # the claim the plot is illustrating. Defaults therefore differ by tab — the
  # \u2468 marker plots default to "data", the \u2466 embedding overlays default to
  # "scale.data" — and every affected plot states its source in the caption.
  # ══════════════════════════════════════════════════════════════════════════════
  # NA-AWARE MODELLING HELPERS (server scope)
  # ══════════════════════════════════════════════════════════════════════════════
  # These were previously local to the ⑥ run observer, which meant nothing else
  # could reuse them. They are self-contained (no free variables, no reactive
  # reads) so hoisting is safe, and the ⑥ Component analysis panel now calls the
  # same code the pipeline runs rather than a copy that could drift.

  regress_out_na <- function(m, meta, covs, spline_df=1, standardize=FALSE,
                             keep=NULL) {
    keep <- intersect(keep %||% character(0), names(meta))
    # A variable listed in BOTH places is legitimate and is the common case:
    # "remove sex from the embedding, but keep it in the values I plot".
    # It is fitted once; its coefficients are then dropped (nuisance) or added
    # back (retained) depending on which call this is. The PCA call passes
    # keep = NULL, so there the same variable is removed. Subtracting `keep`
    # from `covs` (the previous behavior) silently discarded the retain and
    # made that combination impossible.
    covs <- setdiff(covs, keep)
    if ((is.null(covs) || length(covs) == 0) && !length(keep)) return(m)
    all_terms <- c(covs, keep)
    md <- meta[colnames(m), all_terms, drop=FALSE]
    for (cn in all_terms) if (is.character(md[[cn]])) md[[cn]] <- factor(md[[cn]])
    usable <- all_terms[sapply(all_terms, function(cn) {
      v <- md[[cn]]
      if (is.factor(v)) nlevels(droplevels(v[!is.na(v)])) >= 2
      else length(unique(v[!is.na(v)])) >= 2
    })]
    keep_cov  <- intersect(covs, usable)     # nuisance: removed
    keep_keep <- intersect(keep, usable)     # effect of interest: added back
    if (length(keep_cov) == 0 && length(keep_keep) == 0) return(m)
    md <- md[, unique(c(keep_cov, keep_keep)), drop=FALSE]

    # Build the RHS. Continuous covariates optionally get a natural spline
    # basis (falls back to linear if splines unavailable or too few unique
    # values to support df knots). Factors always enter as factors.
    use_spline <- is.numeric(spline_df) && spline_df > 1 &&
                  requireNamespace("splines", quietly=TRUE)
    .term <- function(cn) {
      v <- md[[cn]]
      if (!is.factor(v) && use_spline) {
        nuniq <- length(unique(v[is.finite(v)]))
        df_use <- max(1, min(as.integer(spline_df), nuniq - 1))
        if (df_use >= 2) paste0("splines::ns(", cn, ", df=", df_use, ")") else cn
      } else cn
    }
    terms_nuis <- if (length(keep_cov)) vapply(keep_cov, .term, character(1))
                  else character(0)
    terms_keep <- if (length(keep_keep)) vapply(keep_keep, .term, character(1)) else character(0)
    form <- stats::as.formula(paste0("y ~ ",
              paste(c(terms_nuis, terms_keep), collapse=" + ")))

    out <- m
    for (i in seq_len(nrow(m))) {
      y  <- m[i, ]
      ok <- is.finite(y) & stats::complete.cases(md)
      # need enough observations to fit the (possibly spline-expanded) model
      # Every term in the fitted model counts, retained ones included, plus a
      # little slack so residual df is not zero.
      min_n <- .model_df(md, c(keep_cov, keep_keep), spline_df) + 2L
      if (sum(ok) < min_n) {
        # Too few observations to fit the covariate model, so this feature is
        # left unregressed. Under standardize=TRUE every OTHER feature has been
        # scaled to unit variance, so leaving this one on its raw scale would
        # give it several times the weight in the PCA. Center and scale it the
        # same way without regressing anything, so the PCA input is on one
        # common scale regardless of which features the model could support.
        if (isTRUE(standardize)) {
          obs <- is.finite(out[i, ])
          if (sum(obs) > 1) {
            yv  <- out[i, obs]
            sdv <- stats::sd(yv, na.rm=TRUE)
            if (is.finite(sdv) && sdv > 0)
              out[i, obs] <- (yv - mean(yv, na.rm=TRUE)) / sdv
          }
        }
        next
      }
      df <- data.frame(y=y[ok], md[ok, , drop=FALSE])
      fit <- tryCatch(stats::lm(form, data=df), error=function(e) NULL)
      if (is.null(fit)) {
        # spline fit failed (e.g. degenerate basis) — retry linear
        if (use_spline) {
          form_lin <- stats::as.formula(paste0("y ~ ", paste(keep_cov, collapse=" + ")))
          fit <- tryCatch(stats::lm(form_lin, data=df), error=function(e) NULL)
        }
        if (is.null(fit)) next
      }
      res <- residuals(fit)

      # ── scplainer reconstruction ──────────────────────────────────────────
      # signal = fitted contribution of the RETAINED terms only (nuisance
      # coefficients dropped). With keep = NULL this is 0 and the behavior is
      # identical to before.
      sig <- rep(0, length(res))
      if (length(terms_keep)) {
        mmx <- tryCatch(stats::model.matrix(fit), error=function(e) NULL)
        cf  <- stats::coef(fit)
        if (!is.null(mmx) && length(cf) == ncol(mmx)) {
          asgn <- attr(mmx, "assign")
          tlab <- attr(stats::terms(fit), "term.labels")
          keep_idx <- which(tlab %in% terms_keep)
          cols <- which(asgn %in% keep_idx)
          if (length(cols)) {
            cfk <- cf[cols]; cfk[!is.finite(cfk)] <- 0
            sig <- as.numeric(mmx[, cols, drop=FALSE] %*% cfk)
          }
        }
      }

      if (isTRUE(standardize)) {
        # PCA input: unit-variance per feature so no feature dominates. When
        # an effect is retained the scaling uses the SD of signal+residual,
        # so retained biology keeps its magnitude relative to the noise.
        val <- sig + res
        vsd <- stats::sd(val)
        if (is.finite(vsd) && vsd > 0) val <- val / vsd
        out[i, ok] <- val
      } else {
        # Interpretable VSN / log2 scale:
        #   intercept (observed mean) + retained effect + residual
        out[i, ok] <- mean(y[ok]) + sig + res
      }
    }
    out
  }

  # `min_obs` excludes features the covariate model could not fit. Those features
  # were left UNREGRESSED by regress_out_na, so they keep their full unshrunken
  # variance while every fitted feature has been shrunk by whatever the covariates
  # explained — which systematically advantages them in a variance ranking, and
  # they are also the features whose variance is estimated from the fewest cells.
  # Because the PCA standardizes the selected set afterwards, every selected
  # feature is then weighted equally, so this ranking is the only place variance
  # magnitude matters and the bias would carry straight into the embedding.
  select_vf <- function(m, n, mode="topn", vthresh=NULL, min_obs=3) {
    v  <- apply(m, 1, stats::var, na.rm=TRUE)
    nobs <- rowSums(!is.na(m))
    ok <- is.finite(v) & v > 0 & nobs >= max(3, min_obs)
    v_ok <- v[ok]; names_ok <- rownames(m)[ok]
    if (identical(mode, "thresh") && !is.null(vthresh)) {
      sel <- names_ok[v_ok >= vthresh]
      # order selected by variance (highest first) for consistent labelling
      sel[order(v_ok[v_ok >= vthresh], decreasing=TRUE)]
    } else {
      ord <- order(v_ok, decreasing=TRUE)
      names_ok[ord][seq_len(min(n, length(v_ok)))]
    }
  }

  # ── Model degrees of freedom ────────────────────────────────────────────────
  # Number of parameters a per-feature fit will actually consume, counted term by
  # term, so the minimum-observation guard matches the model being fitted:
  #   factor    -> nlevels - 1 (dummy columns; a 4-level batch costs 3)
  #   numeric   -> spline_df when a spline is in use, otherwise 1
  #   intercept -> 1
  # Splines apply only to numeric terms, which is the part the previous
  # count-times-df formula got wrong when categorical and continuous covariates
  # were mixed.
  .model_df <- function(md, terms, spline_df = 1) {
    terms <- intersect(terms %||% character(0), names(md))
    if (!length(terms)) return(1L)
    use_spline <- is.numeric(spline_df) && spline_df > 1
    p <- vapply(terms, function(cn) {
      v <- md[[cn]]
      if (is.factor(v) || is.character(v) || is.logical(v)) {
        max(1L, length(unique(as.character(v[!is.na(v)]))) - 1L)
      } else if (use_spline) {
        # A spline cannot use more basis columns than the covariate has distinct
        # values, so cap it the same way the fit will.
        nuniq <- length(unique(v[is.finite(v)]))
        max(1L, min(as.integer(spline_df), nuniq - 1L))
      } else 1L
    }, integer(1))
    as.integer(sum(p) + 1L)
  }

  # ── The normalized matrix, read from the object ─────────────────────────────
  # Single accessor for "the VSN / scp-median output". Everything statistical now
  # reads the DATA LAYER through this function rather than a side stash, so the
  # tests, the Mean-SD panel, the exports, the Matrix Inspector, the Correlations
  # tab and the plots all consume the same object. There is one answer to "what
  # was analysed", and it is inspectable.
  #
  # Two things it must handle:
  #   * The layer is written at FULL assay height, so features the transform
  #     dropped (scp-median removes rows with < 2 observed values; ID
  #     reconciliation can leave rows unmatched) sit there as all-NA rows. Those
  #     have to go before proDA / limma / meanSdPlot see them, or they appear as
  #     features with zero observations.
  #   * `obj` defaults to the UNINTEGRATED object, because choosing CCA or RPCA
  #     runs an NA -> 0 prep on s$seu_int's data layer and never undoes it.
  #     Integration corrects the embedding, not the measurements.
  .norm_mat <- function(obj = NULL, assay = NULL) {
    obj   <- obj   %||% s$seu
    assay <- assay %||% input$s_assay
    if (is.null(obj)) return(NULL)
    if (!(assay %in% names(obj@assays))) assay <- SeuratObject::DefaultAssay(obj)
    m <- tryCatch(as.matrix(SeuratObject::LayerData(obj@assays[[assay]], layer="data")),
                  error = function(e) NULL)
    if (is.null(m) || !nrow(m) || !ncol(m)) return(NULL)
    keep <- rowSums(!is.na(m)) > 0
    if (!any(keep)) return(NULL)
    m[keep, , drop = FALSE]
  }

  # The two display sources are the two layers, named as such so a reader can
  # verify what a panel shows by inspecting the object.
  .disp_label <- function(src) {
    rvs <- s$intensity_diag$rv_use
    if (identical(src, "scale.data"))
      paste0("values: scale.data \u2014 z-scored per protein",
             if (length(rvs)) paste0(", ", paste(rvs, collapse=" + "), " regressed out")
             else ", no covariates removed")
    else if (identical(src, "data_obs"))
      "values: data layer, OBSERVED CELLS ONLY \u2014 not-detected omitted from the plot"
    else
      "values: data layer \u2014 normalization output only, NOT covariate-regressed"
  }

  # Single source of truth for "what am I looking at" captions. `fill` describes
  # what happened to not-detected values, which differs by plot type and is the
  # detail most easily misread: a filled zero looks like a measurement.
  # ── Significance annotation for the marker violins ──────────────────────────
  # Reads the adjusted p-value from the stored marker table. Returns NULL when
  # there is nothing to annotate, so callers can simply skip the layer.
  .fmt_p <- function(p) {
    if (!is.finite(p)) return("p = NA")
    stars <- if (p < 1e-4) "****" else if (p < 1e-3) "***" else
             if (p < 1e-2) "**"   else if (p < 0.05) "*"    else "ns"
    txt <- if (p < 2.2e-16) "p < 2.2e-16"
           else if (p < 1e-3) paste0("p = ", formatC(p, format="e", digits=2))
           else paste0("p = ", formatC(p, format="f", digits=4))
    paste0(txt, "  ", stars)
  }

  # mode = "two"  -> one row per gene; label applies to the A-vs-B bracket
  # mode = "all"  -> one row per gene per cluster; label applies to that cluster
  .sig_table <- function(mk, feats, mode, groups) {
    if (is.null(mk) || !nrow(mk) || !all(c("gene","p_val_adj") %in% names(mk))) return(NULL)
    mk <- mk[mk$gene %in% feats, , drop=FALSE]
    if (!nrow(mk)) return(NULL)
    if (identical(mode, "two")) {
      # Guard against a stale table: if it was produced by a different contrast,
      # annotating it against the current groups would be wrong.
      if ("cluster" %in% names(mk)) {
        want <- paste0(groups[1], " vs ", groups[2])
        alt  <- paste0(groups[2], " vs ", groups[1])
        if (!any(as.character(mk$cluster) %in% c(want, alt))) return(NULL)
      }
      mk <- mk[!duplicated(mk$gene), , drop=FALSE]
      data.frame(gene=mk$gene, group=NA_character_,
                 label=vapply(mk$p_val_adj, .fmt_p, character(1)),
                 stringsAsFactors=FALSE)
    } else {
      if (!("cluster" %in% names(mk))) return(NULL)
      data.frame(gene=mk$gene, group=as.character(mk$cluster),
                 label=vapply(mk$p_val_adj, .fmt_p, character(1)),
                 stringsAsFactors=FALSE)
    }
  }

  # ── Observed-only violin ────────────────────────────────────────────────────
  # Built here rather than through Seurat::VlnPlot, which errors on NA while
  # computing its y-limits. Cells where a feature was not detected are dropped
  # per feature, so every panel shows the distribution that feature's test was
  # actually fitted on, and the strip reports how many cells that was per group.
  # ── Per-tab identity reordering for the violins ────────────────────────────
  # The level ORDER control in ③ Covariates is global, so changing it to suit a
  # violin also reorders every other plot. These let a violin be reordered on its
  # own tab without touching anything else.
  #
  # Both the Idents AND the grouping column are re-levelled, because the two
  # violin paths read different things: Seurat::VlnPlot takes its x axis from
  # Idents, while .vln_observed() builds its own frame from the grouping column.
  # Re-levelling only one would reorder one of the two display sources.
  #
  # Colours are unaffected: .pal_for() keys the palette by level NAME, so a
  # cluster keeps its colour wherever it lands on the axis.
  .vln_apply_order <- function(seu, cov, want) {
    if (is.null(seu) || is.null(want) || !length(want)) return(seu)
    want <- as.character(want)
    id <- tryCatch(Seurat::Idents(seu), error = function(e) NULL)
    if (!is.null(id)) {
      present <- levels(droplevels(as.factor(id)))
      lv <- c(intersect(want, present), setdiff(present, want))
      if (length(lv)) Seurat::Idents(seu) <- factor(as.character(id), levels = lv)
    }
    if (!is.null(cov) && length(cov) && nzchar(cov) && cov %in% names(seu@meta.data)) {
      present <- unique(as.character(seu@meta.data[[cov]]))
      lv <- c(intersect(want, present), setdiff(present, want))
      if (length(lv))
        seu@meta.data[[cov]] <- factor(as.character(seu@meta.data[[cov]]), levels = lv)
    }
    seu
  }

  # Drag-to-reorder selector listing the levels the violin will actually draw.
  .vln_order_ui <- function(id, seu, cov) {
    if (is.null(seu)) return(NULL)
    lv <- NULL
    if (!is.null(cov) && length(cov) && nzchar(cov) && cov %in% names(seu@meta.data))
      lv <- levels(.lvl_factor(seu@meta.data[[cov]], cov))
    if (is.null(lv)) {
      id_v <- tryCatch(Seurat::Idents(seu), error = function(e) NULL)
      if (!is.null(id_v)) lv <- levels(droplevels(as.factor(id_v)))
    }
    if (is.null(lv) || length(lv) < 2) return(NULL)
    tagList(
      selectizeInput(id, "Identity order on the x axis (drag to reorder):",
                     choices = lv, selected = lv, multiple = TRUE,
                     options = list(plugins = list("drag_drop"),
                                    placeholder = "Default order")),
      tags$p(tags$small(
        "Applies to this violin only \u2014 the order control in \u2462 Covariates is global. ",
        "Removing a level from the box drops it to the end rather than hiding it; ",
        "colours follow the level name, so they do not shuffle."),
        style="color:#7f8c8d;font-size:11px;margin-top:-4px;")
    )
  }

  .vln_observed <- function(seu, feats, grpby, assay, pal, pt_size, overlay, ncol_use,
                            sig = NULL, mode = "all") {
    m <- tryCatch(as.matrix(SeuratObject::LayerData(seu@assays[[assay]], layer="data")),
                  error=function(e) NULL)
    validate(need(!is.null(m), "No data layer available."))
    md    <- seu@meta.data
    cells <- intersect(colnames(m), rownames(md))
    feats <- intersect(feats, rownames(m))
    validate(need(length(feats) > 0 && length(cells) > 0,
                  "None of the selected features are present."))
    grp_all <- as.character(md[cells, grpby])

    df <- do.call(rbind, lapply(feats, function(g) {
      v  <- suppressWarnings(as.numeric(m[g, cells]))
      ok <- is.finite(v)
      if (!any(ok)) return(NULL)
      # Per-feature detected counts go in the strip label: dropping the missing
      # cells removes the only cue that they existed, so the n must be visible.
      tb  <- table(grp_all[ok])
      lab <- paste0(g, "\n", paste0(names(tb), " n=", as.integer(tb), collapse="  |  "))
      data.frame(feature=lab, gene=g, group=grp_all[ok], value=v[ok],
                 stringsAsFactors=FALSE)
    }))
    validate(need(!is.null(df) && nrow(df) > 0,
                  "No selected feature was detected in any cell."))
    df$feature <- factor(df$feature, levels=unique(df$feature))
    df$group   <- factor(df$group, levels=sort(unique(df$group)))

    p <- ggplot(df, aes(x=group, y=value, fill=group)) +
      geom_violin(scale="width", trim=TRUE, alpha=0.85, color="grey30")
    if (is.numeric(pt_size) && pt_size > 0)
      p <- p + geom_jitter(width=0.18, height=0, size=pt_size, alpha=0.6, color="black")
    if (identical(overlay, "box"))
      p <- p + geom_boxplot(width=0.15, outlier.shape=NA, fill="white", alpha=0.6, color="black")
    else if (identical(overlay, "median"))
      p <- p + stat_summary(fun=median, geom="crossbar", width=0.5, color="black", linewidth=0.6)
    if (!is.null(pal)) p <- p + scale_fill_manual(values=pal, na.value="grey70")
    # ── Significance annotation ───────────────────────────────────────────────
    # Positions are per panel, computed from that panel's own observed range so
    # the bracket clears the data without a fixed offset that breaks on free
    # scales. Headroom is added to the panel so the label is not clipped.
    if (!is.null(sig) && nrow(sig)) {
      rng <- do.call(rbind, lapply(split(df, df$feature), function(z)
        data.frame(feature=z$feature[1], gene=z$gene[1],
                   lo=min(z$value, na.rm=TRUE), hi=max(z$value, na.rm=TRUE),
                   stringsAsFactors=FALSE)))
      rng$pad <- pmax((rng$hi - rng$lo) * 0.10, 1e-6)
      lv <- levels(df$group)

      if (identical(mode, "two") && length(lv) == 2) {
        ann <- merge(rng, sig[is.na(sig$group), c("gene","label")], by="gene")
        if (nrow(ann)) {
          ann$y  <- ann$hi + ann$pad
          ann$ty <- ann$hi + ann$pad * 1.45
          p <- p +
            geom_segment(data=ann, aes(x=1, xend=2, y=y, yend=y),
                         inherit.aes=FALSE, linewidth=0.4, color="grey20") +
            geom_segment(data=ann, aes(x=1, xend=1, y=y, yend=y - pad*0.25),
                         inherit.aes=FALSE, linewidth=0.4, color="grey20") +
            geom_segment(data=ann, aes(x=2, xend=2, y=y, yend=y - pad*0.25),
                         inherit.aes=FALSE, linewidth=0.4, color="grey20") +
            geom_text(data=ann, aes(x=1.5, y=ty, label=label),
                      inherit.aes=FALSE, size=3.1, vjust=0, color="grey20") +
            geom_blank(data=ann, aes(y=hi + pad*2.4), inherit.aes=FALSE)
        }
      } else {
        # One-vs-rest: label each cluster's own violin. No bracket, because the
        # comparison is against the rest rather than against another violin.
        ann <- merge(rng, sig[!is.na(sig$group), c("gene","group","label")], by="gene")
        ann <- ann[ann$group %in% lv, , drop=FALSE]
        if (nrow(ann)) {
          ann$group <- factor(ann$group, levels=lv)
          ann$ty <- ann$hi + ann$pad * 0.55
          p <- p +
            geom_text(data=ann, aes(x=group, y=ty, label=label),
                      inherit.aes=FALSE, size=2.7, vjust=0, color="grey20") +
            geom_blank(data=ann, aes(y=hi + pad*2.0), inherit.aes=FALSE)
        }
      }
    }

    p +
      facet_wrap(~ feature, scales="free_y", ncol=max(1L, as.integer(ncol_use))) +
      theme_classic(base_size=13) +
      theme(axis.text.x=element_text(angle=45, hjust=1), legend.position="none") +
      labs(x=grpby, y="Expression Level")
  }

  # Attach a caption to either a patchwork or a lone ggplot. plot_annotation() is
  # the right tool for a multi-panel patchwork but is not reliable on a single
  # ggplot across patchwork versions, and VlnPlot/FeaturePlot return a plain
  # ggplot when only one feature is selected. Try the annotation, then a plain
  # caption, then give up rather than losing the plot.
  .add_caption <- function(p, cap) {
    out <- tryCatch(p + patchwork::plot_annotation(caption = cap),
                    error = function(e) NULL)
    if (!is.null(out)) return(out)
    out <- tryCatch(p + ggplot2::labs(caption = cap), error = function(e) NULL)
    if (!is.null(out)) return(out)
    p
  }

  .disp_caption <- function(src = "data", fill = "none") {
    method <- (s$intensity_diag$method %||% input$s_norm_method) %||% "sct"
    if (!(method %in% .NA_AWARE)) {
      if (identical(src, "scale.data"))
        return(paste0("values: ",
                      if (method == "sct") "SCT Pearson residuals" else "centred/scaled",
                      " (scale.data layer) — 0 is the average cell, so colour reads as ",
                      "relative enrichment, not abundance"))
      base <- if (method == "sct") "values: SCT corrected counts (data layer)"
              else "values: log-normalized (data layer)"
      return(paste0(base, "; not-detected was already 0 at object build"))
    }
    # scale.data already has not-detected filled with 0 when it is written, so no
    # display fill is applied on top of it and the caption must say 0, not the
    # per-plot fill that only applies to the data layer.
    if (identical(src, "data_obs")) {
      # Report the detected fraction, because dropping the missing cells removes
      # the only visual cue that they existed.
      mm <- tryCatch(.norm_mat(s$seu), error=function(e) NULL)
      det <- if (!is.null(mm) && length(mm)) round(100*mean(!is.na(mm)), 1) else NA
      return(paste0(.disp_label(src),
                    "; the violin therefore describes the DETECTED distribution, which is what ",
                    "the test was fitted on",
                    if (is.finite(det)) paste0(" (", det, "% of all cell\u00d7feature entries are detected overall)") else "",
                    ". Compare against the \u201cdata\u201d view to see how much was missing"))
    }
    if (identical(src, "scale.data"))
      return(paste0(.disp_label(src),
                    "; not-detected already filled with 0 when the layer was written ",
                    "(0 = the center of the scale, so a neutral band is MISSINGNESS, ",
                    "not average abundance)"))
    fill_txt <- switch(fill,
      "min_minus_1" = "not-detected drawn one unit below each protein's minimum (visible as a separate spike)",
      "min"         = "not-detected drawn at each protein's minimum observed value (blends into the low end)",
      "excluded"    = "not-detected EXCLUDED from the statistic, not filled",
      "zero"        = "not-detected filled with 0 (the center of the scale)",
      "none"        = "not-detected handling: see panel",
      fill)
    paste0(.disp_label(src), "; ", fill_txt)
  }

  # Swap the data layer for the chosen source, then fill NAs for rendering.
  # `na_offset` = -1 makes not-detected a visible separated spike (violin/dot);
  # 0 blends it into the low end of a color scale (FeaturePlot).
  # Seurat's feature-level plotting functions read the `data` layer, so to display
  # scale.data the chosen matrix is copied INTO data on a throwaway copy of the
  # object. `seu_use` is always a fresh derivation (s_seu_with_ident() etc.), and
  # R copies on modify, so s$seu is untouched.
  #
  # `na_offset` applies to the DATA LAYER only: -1 makes not-detected a visible
  # separated spike (violin/dot), 0 blends it into the low end of a color scale
  # (FeaturePlot). scale.data was already written with not-detected at 0, so it is
  # passed through unmodified — filling it again would shift real z-scores.
  # Overwrite the data layer with scale.data for DISPLAY only, so FeaturePlot /
  # VlnPlot (which read the data layer) show scaled expression.
  #
  # scale.data is routinely a SUBSET of the assay: SCTransform defaults to
  # return.only.var.genes = TRUE, so a non-variable protein has no residual at
  # all. Padding those rows with 0 keeps the matrix conformable, but 0 is the
  # CENTRE of a residual scale, so such a protein would render as a uniformly
  # average-looking field rather than as missing. .scale_data_missing() below
  # lets callers warn about exactly which requested features that applies to.
  .swap_in_scale_data <- function(seu_use, assay_use) {
    sd_mat <- tryCatch(as.matrix(SeuratObject::LayerData(
                seu_use@assays[[assay_use]], layer="scale.data")), error=function(e) NULL)
    if (is.null(sd_mat) || !nrow(sd_mat)) {
      showNotification(paste0("No scale.data layer on this object \u2014 showing the ",
                              "data layer instead. Re-run \u2465 to write it."),
                       type="warning", duration=8)
      return(seu_use)
    }
    base <- tryCatch(as.matrix(SeuratObject::LayerData(
              seu_use@assays[[assay_use]], layer="data")), error=function(e) NULL)
    if (!is.null(base)) {
      out <- matrix(0, nrow=nrow(base), ncol=ncol(base), dimnames=dimnames(base))
      fi <- intersect(rownames(base), rownames(sd_mat))
      ci <- intersect(colnames(base), colnames(sd_mat))
      if (length(fi)) out[fi, ci] <- sd_mat[fi, ci, drop=FALSE]
      sd_mat <- out
    }
    ok <- tryCatch({
      SeuratObject::LayerData(seu_use@assays[[assay_use]], layer="data") <- sd_mat; TRUE
    }, error=function(e) FALSE)
    if (isTRUE(ok)) attr(seu_use, "scp_swapped") <- TRUE
    seu_use
  }

  # Which of `feats` are absent from the assay's scale.data layer.
  .scale_data_missing <- function(seu_use, assay_use, feats) {
    rn <- tryCatch(rownames(SeuratObject::LayerData(
            seu_use@assays[[assay_use]], layer="scale.data")), error=function(e) NULL)
    if (is.null(rn)) return(character(0))
    setdiff(feats, rn)
  }

  .display_seu <- function(seu_use, assay_use, src = "data", na_offset = -1) {
    method <- input$s_norm_method %||% "sct"

    # The scale.data swap is meaningful on EVERY route, so it runs before the
    # NA-aware gate below. On SCT that layer holds the Pearson residuals and on
    # LogNormalize the centred/scaled values; previously this function returned
    # early for both, so the feature plot silently always drew the data layer
    # with no way to ask for scaled expression.
    if (identical(src, "scale.data") && !(method %in% .NA_AWARE))
      return(.swap_in_scale_data(seu_use, assay_use))

    # Everything past here is about NOT-DETECTED handling, which only the
    # intensity-native routes have: on SCT / LogNormalize missing was already 0
    # at object build, so there is nothing to fill.
    if (!(method %in% .NA_AWARE)) return(seu_use)

    # Observed-only: return the object untouched so the NAs survive into the plot
    # and ggplot drops those cells. The distribution is then exactly what the test
    # was fitted on, at the cost of hiding how much was missing \u2014 which is why the
    # caption reports the detected fraction instead.
    if (identical(src, "data_obs")) return(seu_use)

    if (identical(src, "scale.data")) {
      swapped <- .swap_in_scale_data(seu_use, assay_use)
      if (!is.null(attr(swapped, "scp_swapped"))) return(swapped)
      # No scale.data layer: fall through to the data-layer handling below.
    }

    # data layer: fill not-detected for rendering only.
    dl <- tryCatch(as.matrix(SeuratObject::LayerData(
            seu_use@assays[[assay_use]], layer="data")), error=function(e) NULL)
    if (is.null(dl)) return(seu_use)
    if (anyNA(dl)) {
      rmin <- suppressWarnings(apply(dl, 1, function(r){
        mn <- min(r, na.rm=TRUE); if (is.finite(mn)) mn else 0 }))
      na_idx <- which(is.na(dl), arr.ind=TRUE)
      if (nrow(na_idx) > 0) dl[na_idx] <- rmin[na_idx[,1]] + na_offset
    }
    tryCatch(SeuratObject::LayerData(seu_use@assays[[assay_use]], layer="data") <- dl,
             error=function(e) NULL)
    seu_use
  }

  # Back-compatible wrapper for call sites that predate the source switch.
  .display_safe_seu <- function(seu_use, assay_use) {
    .display_seu(seu_use, assay_use, src = "data", na_offset = -1)
  }

  # Violin builder shared by the on-screen panel and the PDF export.
  #
  # The PDF case used to re-implement this from scratch and honoured almost none
  # of the panel's controls: it ignored the layer selector (s_mk_disp_src), the
  # observed-only mode, the significance brackets and the source caption, and it
  # NA-filled with .display_safe_seu() instead of .display_seu(). Exporting now
  # runs the SAME code as the screen, so the two cannot drift.
  #
  # fs = NULL keeps ggplot's default sizing (screen); a number re-themes every
  # panel at that base size for export.
  .build_mk_vln <- function(fs = NULL) {
    req(s_seu_with_ident(), input$s_mk_grpby, input$s_mk_vln_genes)
    # Reordered copy, reused by BOTH display paths below so they cannot disagree.
    seu_ord  <- .vln_apply_order(s_seu_with_ident(), input$s_mk_grpby,
                                 input$s_mk_vln_order)
    seu_use  <- seu_ord
    g        <- intersect(input$s_mk_vln_genes, rownames(seu_use)); req(length(g)>0)
    assay_use <- if("SCT" %in% names(seu_use@assays))"SCT" else input$s_assay
    disp_src <- input$s_mk_disp_src %||% "data"
    seu_use  <- .display_seu(seu_use, assay_use, src=disp_src, na_offset=-1)
    ncol_use  <- .num(input$s_mk_vln_ncol, 3)
    pt_size   <- .num(input$s_vln_pt_size, 0.5)
    pal       <- .pal_seu(seu_use, input$s_mk_grpby)
    overlay   <- input$s_vln_overlay  %||% "box"

    # Annotation table, from the stored marker results. NULL when markers have not
    # been run, when the table is for a different contrast, or when the toggle is
    # off — in all of those cases the plot is drawn unannotated rather than with a
    # number that does not belong to it.
    mk_mode <- input$s_mk_mode %||% "all"
    sig_tb  <- if (isTRUE(input$s_vln_sig))
                 .sig_table(s$markers, g, mk_mode,
                            c(input$s_mk_id1, input$s_mk_id2)) else NULL

    if (identical(disp_src, "data_obs")) {
      # Own builder: Seurat::VlnPlot errors on NA, and the overlay is applied
      # inside it rather than through patchwork.
      p <- .vln_observed(seu_ord, g, input$s_mk_grpby, assay_use,
                         pal, pt_size, overlay, ncol_use,
                         sig = sig_tb, mode = mk_mode)
      p <- p + labs(caption = .disp_caption(disp_src, "excluded"))
      return(.vln_fs(p, fs))
    } else {
      p <- Seurat::VlnPlot(seu_use, features=g, assay=assay_use,
                           pt.size=pt_size, ncol=ncol_use,
                           cols=if(!is.null(pal)) pal else NULL)
      # Overlay via patchwork: each panel is a ggplot, iterate and add the layer.
      if (overlay == "box") {
        p <- p & ggplot2::geom_boxplot(width=0.15, outlier.shape=NA,
                                        fill="white", alpha=0.6, color="black")
      } else if (overlay == "median") {
        p <- p & ggplot2::stat_summary(fun=median, geom="crossbar",
                                        width=0.5, color="black", linewidth=0.6)
      }
      # Annotate each panel. VlnPlot returns panels in the order of `features`,
      # so index by position; a single feature yields a bare ggplot rather than a
      # patchwork, which is why both cases are handled.
      if (!is.null(sig_tb) && nrow(sig_tb)) {
        # Ranges from the displayed matrix, keyed by the ORIGINAL feature name.
        .m_disp <- tryCatch(as.matrix(SeuratObject::LayerData(
                     seu_use@assays[[assay_use]], layer="data")), error=function(e) NULL)
        .yr_of <- function(gene) {
          if (is.null(.m_disp) || !(gene %in% rownames(.m_disp))) return(c(NA_real_, NA_real_))
          suppressWarnings(range(.m_disp[gene, ], na.rm=TRUE))
        }
        p <- tryCatch({
          ann_one <- function(pp, gene) {
            if (identical(mk_mode, "two")) {
              lab <- sig_tb$label[is.na(sig_tb$group) & sig_tb$gene == gene]
              if (!length(lab)) return(pp)
              yr  <- .yr_of(gene)
              if (!all(is.finite(yr))) return(pp)
              pad <- max(diff(yr)*0.10, 1e-6)
              pp + ggplot2::annotate("segment", x=1, xend=2,
                                     y=yr[2]+pad, yend=yr[2]+pad,
                                     linewidth=0.4, color="grey20") +
                   ggplot2::annotate("text", x=1.5, y=yr[2]+pad*1.45,
                                     label=lab[1], size=3.1, vjust=0, color="grey20") +
                   ggplot2::expand_limits(y=yr[2]+pad*2.6)
            } else {
              sub <- sig_tb[!is.na(sig_tb$group) & sig_tb$gene == gene, , drop=FALSE]
              if (!nrow(sub)) return(pp)
              yr  <- .yr_of(gene)
              if (!all(is.finite(yr))) return(pp)
              pad <- max(diff(yr)*0.10, 1e-6)
              pp + ggplot2::annotate("text", x=sub$group, y=yr[2]+pad*0.55,
                                     label=sub$label, size=2.7, vjust=0, color="grey20") +
                   ggplot2::expand_limits(y=yr[2]+pad*2.2)
            }
          }
          if (length(g) == 1) ann_one(p, g[1])
          else { for (i in seq_along(g)) p[[i]] <- ann_one(p[[i]], g[i]); p }
        }, error=function(e) { s_log(paste0("p-value annotation skipped: ",
                                            conditionMessage(e))); p })
      }
      p <- .add_caption(p, .disp_caption(disp_src, "min_minus_1"))
      return(.vln_fs(p, fs))
    }
  }

  # Re-theme a VlnPlot result at an explicit base size. Uses patchwork's `&` so
  # it works on both a single ggplot and a multi-panel patchwork, and is applied
  # LAST so it cannot drop the annotation layers added above.
  .vln_fs <- function(p, fs) {
    if (is.null(fs)) return(p)
    tryCatch(p & ggplot2::theme_classic(base_size = fs), error = function(e) p)
  }

  output$s_mk_vln_order_ui <- renderUI({
    .vln_order_ui("s_mk_vln_order", tryCatch(s_seu_with_ident(), error=function(e) NULL),
                  input$s_mk_grpby)
  })

  output$s_mk_vln <- renderPlot({ print(.build_mk_vln(NULL)) })

  output$s_mk_feat_ui <- renderUI({
    req(s$seu)
    all_feats <- .opt_clean(rownames(s$seu), "features")
    pre <- if (!is.null(s$markers) && "gene" %in% names(s$markers))
      head(.mk_order(s$markers)[, "gene"], 8)
    else head(all_feats, 8)
    pre <- intersect(pre, all_feats)
    tagList(
      selectizeInput("s_mk_feat_genes","Proteins to feature plot (type to search):",
                     choices=all_feats, multiple=TRUE, selected=pre,
                     options=list(maxItems=16, placeholder="Search proteins...")),
      numericInput("s_mk_feat_ncol","Columns:",value=4,min=1,max=8),
      # Shown on every route. The default differs by route, so it is set from the
      # server (see the observer on s_norm_method) rather than hardcoded here:
      # on the NA-aware routes scale.data is the sensible default because it
      # matches the embedding, whereas on SCT the data layer (corrected counts)
      # is what most people expect a feature plot to show.
      radioButtons("s_feat_disp_src", "Color by which layer?", inline=FALSE,
        choices=c("scale.data \u2014 scaled expression" = "scale.data",
                  "data \u2014 normalized, as tested" = "data"),
        selected="data"),
      conditionalPanel(
        "input.s_norm_method == 'vsn' || input.s_norm_method == 'scpmed' || input.s_norm_method == 'log2'",
        tags$p(tags$small(
          "Default matches the layout: the embedding was computed after covariate ",
          "regression, so coloring with ", tags$b("scale.data"), " keeps position and ",
          "color on the same footing and a depth gradient in the colors cannot be ",
          "mistaken for biology. Switch to ", tags$b("data"), " for the untouched ",
          "normalized values the marker statistics are based on \u2014 useful when a ",
          "protein looks differentially abundant in the table but flat here."),
          style="color:grey;font-size:11px;")),
      conditionalPanel(
        "input.s_norm_method == 'sct' || input.s_norm_method == 'lognorm'",
        tags$p(tags$small(
          tags$b("scale.data"), " on this route is the Pearson residuals (SCT) or the ",
          "centred/scaled values (LogNormalize): 0 is the average cell, so the colour ",
          "scale reads as relative enrichment rather than abundance. Note that ",
          "SCTransform stores residuals for ", tags$b("variable features only"),
          " by default, so a non-variable protein has none and will draw as a flat ",
          "field \u2014 the panel says so when that happens. ", tags$b("data"),
          " is the corrected counts and is the safer default for judging abundance."),
          style="color:grey;font-size:11px;"))
    )
  })
  # Route-appropriate default for the feature-plot layer. scale.data matches the
  # embedding on the NA-aware routes (covariates regressed out there), but on SCT
  # the data layer is the conventional thing to colour a feature plot by, so the
  # default flips rather than being fixed in the UI.
  observeEvent(input$s_norm_method, {
    want <- if ((input$s_norm_method %||% "sct") %in% .NA_AWARE) "scale.data" else "data"
    updateRadioButtons(session, "s_feat_disp_src", selected = want)
  }, ignoreInit = FALSE)

  # ══ Manual heatmap + abundance trajectory (⑨ and ⑫) ════════════════════════
  # Both plots are driven entirely by a hand-picked protein list, and both exist
  # in two copies that differ only by control-id prefix, so everything below is
  # parameterised by `p` ("s_mk" or "i_mk") rather than duplicated.

  # Object / assay / grouping for a given tab. Mirrors how .build_mk_vln picks
  # its assay, so the new plots read the same matrix as the violins.
  .mk_ctx <- function(p) {
    if (identical(p, "i_mk")) {
      seu <- tryCatch(i_seu_with_ident(), error=function(e) NULL)
      list(seu = seu, grp = input$i_mk_grpby,
           assay = if (!is.null(seu) && "SCT" %in% names(seu@assays)) "SCT" else input$s_assay,
           mk = s$int_markers, label = "Integrated")
    } else {
      seu <- tryCatch(s_seu_with_ident(), error=function(e) NULL)
      list(seu = seu, grp = input$s_mk_grpby,
           assay = if (!is.null(seu) && "SCT" %in% names(seu@assays)) "SCT" else input$s_assay,
           mk = s$markers, label = "Markers")
    }
  }

  # Expression matrix for the picked proteins, on the chosen layer.
  # Returns list(mat, src, grp_vec) or stop()s with a readable reason.
  .mk_pick_mat <- function(p, genes, src) {
    ctx <- .mk_ctx(p)
    if (is.null(ctx$seu)) stop("No object yet \u2014 build and normalize it first.", call.=FALSE)
    grp <- ctx$grp
    if (is.null(grp) || !nzchar(grp) || !grp %in% names(ctx$seu@meta.data))
      stop("Pick a grouping variable on this tab first.", call.=FALSE)
    genes <- intersect(genes, rownames(ctx$seu))
    if (!length(genes)) stop("Select at least one protein.", call.=FALSE)

    # data_obs keeps the NAs so they can be dropped per column; the other two
    # go through .display_seu exactly as the violins do.
    want <- if (identical(src, "data_obs")) "data" else src
    seu_d <- .display_seu(ctx$seu, ctx$assay, src = want, na_offset = 0)
    m <- tryCatch(as.matrix(SeuratObject::LayerData(seu_d@assays[[ctx$assay]], layer="data")),
                  error = function(e) NULL)
    if (is.null(m)) stop("Could not read the data layer for assay '", ctx$assay, "'.", call.=FALSE)
    m <- m[intersect(genes, rownames(m)), , drop=FALSE]
    if (!nrow(m)) stop("None of the selected proteins are present in this assay.", call.=FALSE)
    gv <- .lvl_factor(ctx$seu@meta.data[[grp]], grp)
    names(gv) <- colnames(seu_d)
    gv <- gv[colnames(m)]
    list(mat = m, src = src, grp = gv, grp_name = grp, label = ctx$label)
  }

  # Row-wise z-score that tolerates all-NA and zero-variance rows rather than
  # emitting NaN, which would silently blank a row of the heatmap.
  .row_z <- function(m) {
    t(apply(m, 1, function(v) {
      mu <- mean(v, na.rm=TRUE); sdv <- stats::sd(v, na.rm=TRUE)
      if (!is.finite(mu)) return(rep(NA_real_, length(v)))
      if (!is.finite(sdv) || sdv == 0) return(v - mu)
      (v - mu) / sdv
    }))
  }

  # Diverging / sequential fill with an explicit break count. A z-scored matrix
  # gets a symmetric diverging scale centred on 0; raw values get viridis,
  # because centring raw abundance on an arbitrary midpoint implies a reference
  # level that does not exist.
  .mk_hm_fill <- function(vals, scaled, n_breaks, cap) {
    rng <- range(vals, na.rm=TRUE)
    if (!all(is.finite(rng))) rng <- c(0, 1)
    if (scaled) {
      lim <- if (is.finite(cap) && cap > 0) cap else max(abs(rng), na.rm=TRUE)
      if (!is.finite(lim) || lim == 0) lim <- 1
      brks <- pretty(c(-lim, lim), n = max(3, n_breaks))
      ggplot2::scale_fill_gradientn(
        colours = c("#2166AC","#67A9CF","#D1E5F0","#F7F7F7","#FDDBC7","#EF8A62","#B2182B"),
        limits = c(-lim, lim), breaks = brks, oob = scales::squish,
        na.value = "grey90", name = "z")
    } else {
      brks <- pretty(rng, n = max(3, n_breaks))
      ggplot2::scale_fill_gradientn(
        colours = viridis::viridis(9), limits = rng, breaks = brks,
        oob = scales::squish, na.value = "grey90", name = "value")
    }
  }

  # ── Dynamic selectors + renderers for both tabs ────────────────────────────
  # Registered in a loop over the two prefixes so the ⑨ and ⑫ copies cannot
  # drift. local() captures p by value; without it every handler would close
  # over the final loop value.
  for (.p in c("s_mk", "i_mk")) local({
    p <- .p

    # Protein pickers, server-side: the feature list runs to thousands of rows
    # and a client-side selectize would ship all of them into the page.
    .genes_ui <- function(id, label, maxn) {
      ctx <- .mk_ctx(p)
      if (is.null(ctx$seu)) return(tags$p(tags$small("Build the object first."),
                                          style="color:#C0392B;"))
      all_feats <- .opt_clean(rownames(ctx$seu), "features")
      pre <- if (!is.null(ctx$mk) && "gene" %in% names(ctx$mk))
               head(.mk_order(ctx$mk)[, "gene"], min(10, maxn)) else head(all_feats, 6)
      selectizeInput(id, label, choices=all_feats, multiple=TRUE,
                     selected=intersect(pre, all_feats),
                     options=list(maxItems=maxn, placeholder="Search proteins\u2026"))
    }

    output[[paste0(p, "_hm_genes_ui")]] <- renderUI(
      .genes_ui(paste0(p, "_hm_genes"), "Proteins for the heatmap (type to search, max 150):", 150))

    output[[paste0(p, "_tj_genes_ui")]] <- renderUI(
      .genes_ui(paste0(p, "_tj_genes"), "Proteins to profile (type to search, max 12):", 12))

    # Metadata strips: only categorical-or-few-valued columns are offered,
    # because a continuous column with thousands of distinct values makes an
    # unreadable strip (it is still allowed, drawn on a viridis scale).
    output[[paste0(p, "_hm_anno_ui")]] <- renderUI({
      ctx <- .mk_ctx(p); if (is.null(ctx$seu)) return(NULL)
      md <- ctx$seu@meta.data
      keep <- names(md)[vapply(md, function(x)
        (is.factor(x) || is.character(x) || is.numeric(x)) &&
          length(unique(stats::na.omit(x))) >= 2, logical(1))]
      keep <- setdiff(keep, c("orig.ident"))
      conditionalPanel(
        paste0("input.", p, "_hm_cols == 'cell'"),
        selectizeInput(paste0(p, "_hm_anno"), "Metadata strips above the columns:",
                       choices=keep, multiple=TRUE,
                       selected=intersect(ctx$grp, keep),
                       options=list(maxItems=6, placeholder="None")),
        tags$p(tags$small(
          "Only available with one column per cell. On cluster columns the only ",
          "variable that is well defined per column is the grouping variable itself, ",
          "which is already the x axis."),
          style="color:#7f8c8d;font-size:11px;margin-top:-4px;"))
    })

    # Optional split / colour variable for the profile.
    output[[paste0(p, "_tj_ptcol_ui")]] <- renderUI({
      ctx <- .mk_ctx(p); if (is.null(ctx$seu)) return(NULL)
      md <- ctx$seu@meta.data
      # Discrete-ish columns only: splitting by a continuous variable would give
      # one line per distinct value, which is not a profile.
      keep <- names(md)[vapply(md, function(x) {
        u <- unique(stats::na.omit(x))
        (is.factor(x) || is.character(x) || length(u) <= 12) && length(u) >= 2
      }, logical(1))]
      keep <- setdiff(keep, c("orig.ident", ctx$grp))
      tagList(
        selectInput(paste0(p, "_tj_ptcol"), "Split / colour by (optional):",
                    choices=c("Protein (one line per protein)" = "__protein__",
                              stats::setNames(keep, keep)),
                    selected="__protein__"),
        tags$p(tags$small(
          "Choosing a variable here splits the profile by it: one mean line and band ",
          "per protein \u00d7 level, with the cells coloured to match, so the lines account ",
          "for the same split the points show. Colours come from that variable's palette ",
          "in \u2462 Covariates when one is set. The grouping variable itself is excluded ",
          "\u2014 it is already the x axis \u2014 as are continuous columns with more than ",
          "12 distinct values."),
          style="color:#7f8c8d;font-size:11px;margin-top:-4px;"))
    })

    # Cluster order for the profile x axis.
    output[[paste0(p, "_tj_order_ui")]] <- renderUI({
      ctx <- .mk_ctx(p); if (is.null(ctx$seu)) return(NULL)
      g <- ctx$grp
      if (is.null(g) || !nzchar(g) || !g %in% names(ctx$seu@meta.data)) return(NULL)
      lv <- levels(.lvl_factor(ctx$seu@meta.data[[g]], g))
      selectizeInput(paste0(p, "_tj_order"),
                     "Cluster order along the x axis (drag to reorder):",
                     choices=lv, selected=lv, multiple=TRUE,
                     options=list(plugins=list("drag_drop"), placeholder="Default order"))
    })

    output[[paste0(p, "_hm_plot")]] <- renderPlot({
      pl <- tryCatch(.build_mk_heatmap(p, 11), error=function(e) e)
      validate(need(!inherits(pl, "error"),
                    if (inherits(pl, "error")) conditionMessage(pl) else ""))
      pl
    })

    output[[paste0(p, "_tj_plot")]] <- renderPlot({
      pl <- tryCatch(.build_mk_traj(p, 13), error=function(e) e)
      validate(need(!inherits(pl, "error"),
                    if (inherits(pl, "error")) conditionMessage(pl) else ""))
      pl
    })
  })

  # ── Heatmap builder ────────────────────────────────────────────────────────
  .build_mk_heatmap <- function(p, fs = 11) {
    genes <- input[[paste0(p, "_hm_genes")]]
    src   <- input[[paste0(p, "_hm_src")]] %||% "data"
    d     <- .mk_pick_mat(p, genes, src)
    m     <- d$mat; gv <- d$grp
    by_cluster <- identical(input[[paste0(p, "_hm_cols")]] %||% "cluster", "cluster")
    scaled     <- identical(input[[paste0(p, "_hm_scale")]] %||% "row", "row")
    n_breaks   <- max(3, .num(input[[paste0(p, "_hm_breaks")]], 7))
    cap        <- .num(input[[paste0(p, "_hm_limit")]], 0)
    anno_vars  <- input[[paste0(p, "_hm_anno")]] %||% character(0)

    ctx <- .mk_ctx(p)
    if (by_cluster) {
      # Cluster means. na.rm so a protein missing in some cells still gets a
      # mean from the cells that saw it; a cluster with no observations at all
      # stays NA rather than becoming 0.
      lv  <- levels(droplevels(gv))
      m2  <- vapply(lv, function(L) {
        cols <- which(as.character(gv) == L)
        if (!length(cols)) return(rep(NA_real_, nrow(m)))
        rowMeans(m[, cols, drop=FALSE], na.rm=TRUE)
      }, numeric(nrow(m)))
      dimnames(m2) <- list(rownames(m), lv)
      m2[!is.finite(m2)] <- NA_real_
      col_grp <- factor(lv, levels=lv)
      names(col_grp) <- lv
      # Annotation strips are meaningless on cluster columns for anything other
      # than the grouping variable itself, so they are dropped there.
      anno_vars <- character(0)
    } else {
      if (identical(src, "data_obs")) m[!is.finite(m)] <- NA_real_
      ord <- order(gv, colnames(m))
      m2  <- m[, ord, drop=FALSE]
      col_grp <- gv[ord]
    }
    if (scaled) m2 <- .row_z(m2)
    if (!nrow(m2) || !ncol(m2)) stop("Nothing left to draw after filtering.", call.=FALSE)

    # Row order
    if (isTRUE(input[[paste0(p, "_hm_clust_rows")]]) && nrow(m2) > 2) {
      hc <- tryCatch(stats::hclust(stats::dist(ifelse(is.na(m2), 0, m2))), error=function(e) NULL)
      if (!is.null(hc)) m2 <- m2[hc$order, , drop=FALSE]
    }
    # Column order (only meaningful when columns are not already grouped)
    if (isTRUE(input[[paste0(p, "_hm_clust_cols")]]) && ncol(m2) > 2) {
      hcc <- tryCatch(stats::hclust(stats::dist(t(ifelse(is.na(m2), 0, m2)))), error=function(e) NULL)
      if (!is.null(hcc)) { m2 <- m2[, hcc$order, drop=FALSE]; col_grp <- col_grp[hcc$order] }
    }

    long <- data.frame(
      Protein = factor(rep(rownames(m2), times=ncol(m2)), levels=rev(rownames(m2))),
      Col     = factor(rep(colnames(m2), each=nrow(m2)), levels=colnames(m2)),
      Value   = as.vector(m2), stringsAsFactors = FALSE)

    hm <- ggplot2::ggplot(long, ggplot2::aes(x=Col, y=Protein, fill=Value)) +
      ggplot2::geom_raster() +
      .mk_hm_fill(long$Value, scaled, n_breaks, cap) +
      ggplot2::theme_classic(base_size=fs) +
      ggplot2::labs(x = if (by_cluster) d$grp_name else NULL, y = NULL,
                    title = paste0(d$label, " \u2014 ", nrow(m2), " protein(s) \u00d7 ",
                                   ncol(m2), if (by_cluster) " cluster(s)" else " cell(s)"),
                    subtitle = paste0(.disp_label(src),
                                      if (scaled) "  |  rows z-scored across the columns drawn"
                                      else "  |  rows unscaled")) +
      ggplot2::theme(
        axis.text.x = if (by_cluster)
                        ggplot2::element_text(angle=45, hjust=1, size=fs*0.9)
                      else ggplot2::element_blank(),
        axis.ticks.x = if (by_cluster) ggplot2::element_line() else ggplot2::element_blank(),
        axis.text.y = if (isTRUE(input[[paste0(p, "_hm_rownames")]]))
                        ggplot2::element_text(size=fs*0.8) else ggplot2::element_blank(),
        axis.line = ggplot2::element_blank())

    # Metadata strips above the columns, one thin row per variable, assembled
    # with patchwork so the x axes stay aligned with the heatmap.
    anno_vars <- intersect(anno_vars, names(ctx$seu@meta.data))
    if (!by_cluster && length(anno_vars)) {
      strips <- lapply(anno_vars, function(v) {
        vals <- ctx$seu@meta.data[colnames(m2), v]
        is_cont <- is.numeric(vals) && length(unique(stats::na.omit(vals))) > 12
        dfa <- data.frame(Col=factor(colnames(m2), levels=colnames(m2)), Row=v,
                          Val=if (is_cont) as.numeric(vals) else NA_real_,
                          Cat=if (is_cont) NA_character_ else as.character(vals),
                          stringsAsFactors=FALSE)
        g <- ggplot2::ggplot(dfa, ggplot2::aes(x=Col, y=Row)) +
          ggplot2::theme_classic(base_size=fs) +
          ggplot2::labs(x=NULL, y=NULL) +
          ggplot2::theme(axis.text.x=ggplot2::element_blank(),
                         axis.ticks=ggplot2::element_blank(),
                         axis.line=ggplot2::element_blank(),
                         axis.text.y=ggplot2::element_text(size=fs*0.8),
                         legend.position="right")
        if (is_cont)
          g + ggplot2::geom_raster(ggplot2::aes(fill=Val)) +
              viridis::scale_fill_viridis(option="mako", na.value="grey90", name=v)
        else {
          dfa$Cat <- .lvl_factor(dfa$Cat, v)
          g + ggplot2::geom_raster(ggplot2::aes(fill=Cat)) +
              { .scale_fill_for(v, levels(dfa$Cat)) } +
              ggplot2::labs(fill=v)
        }
      })
      n_s <- length(strips)
      return(patchwork::wrap_plots(c(strips, list(hm)), ncol=1,
                                   heights=c(rep(0.055, n_s), 1 - 0.055*n_s)))
    }
    hm
  }

  # ── Abundance trajectory builder ───────────────────────────────────────────
  .build_mk_traj <- function(p, fs = 13) {
    genes <- input[[paste0(p, "_tj_genes")]]
    src   <- input[[paste0(p, "_tj_src")]] %||% "data"
    d     <- .mk_pick_mat(p, genes, src)
    ctx   <- .mk_ctx(p)
    m     <- d$mat; gv <- d$grp
    if (identical(src, "data_obs")) m[!is.finite(m)] <- NA_real_
    mode   <- input[[paste0(p, "_tj_mode")]]   %||% "mean"
    band   <- input[[paste0(p, "_tj_band")]]   %||% "se"
    centre <- input[[paste0(p, "_tj_center")]] %||% "z"

    # Optional second grouping (condition, batch, sex, ...). When set, it becomes
    # the COLOUR variable and the profile is split by it: one mean line and band
    # per protein x level, rather than just recolouring the cells. Recolouring
    # the points alone would show a difference the line did not account for.
    splitv <- input[[paste0(p, "_tj_ptcol")]] %||% "__protein__"
    use_split <- !identical(splitv, "__protein__") &&
                 !is.null(ctx$seu) && splitv %in% names(ctx$seu@meta.data)

    # Cluster order: the custom order if one was set, else natural level order.
    want <- input[[paste0(p, "_tj_order")]]
    lv   <- levels(droplevels(gv))
    if (!is.null(want) && length(want)) lv <- c(intersect(want, lv), setdiff(lv, want))
    if (length(lv) < 2) stop("Need at least two clusters to draw a profile.", call.=FALSE)

    sv <- if (use_split) as.character(ctx$seu@meta.data[colnames(m), splitv])
          else rep(NA_character_, ncol(m))

    # Per-cell long frame, then cluster summaries from it.
    cells <- do.call(rbind, lapply(rownames(m), function(g) {
      data.frame(Protein=g, Cluster=as.character(gv), Split=sv,
                 Value=as.numeric(m[g, ]), stringsAsFactors=FALSE)
    }))
    cells <- cells[cells$Cluster %in% lv & is.finite(cells$Value), , drop=FALSE]
    if (use_split) cells <- cells[!is.na(cells$Split), , drop=FALSE]
    if (!nrow(cells)) stop("No finite values for the selected proteins.", call.=FALSE)

    key <- if (use_split) list(cells$Protein, cells$Cluster, cells$Split)
           else list(cells$Protein, cells$Cluster)
    summ <- do.call(rbind, lapply(split(cells, key, drop=TRUE),
      function(z) data.frame(Protein=z$Protein[1], Cluster=z$Cluster[1],
                             Split=z$Split[1],
                             Mean=mean(z$Value), SD=stats::sd(z$Value), N=nrow(z),
                             stringsAsFactors=FALSE)))
    summ$SE <- ifelse(is.finite(summ$SD) & summ$N > 1, summ$SD/sqrt(summ$N), NA_real_)

    # Centring / z-scoring is per PROTEIN, across all of that protein's summary
    # rows. Deliberately not per protein x split: centring each condition on its
    # own mean would subtract exactly the between-condition difference the split
    # exists to show, leaving every condition sitting on top of the others.
    if (centre != "none") {
      sp <- split(seq_len(nrow(summ)), summ$Protein)
      for (idx in sp) {
        prot <- summ$Protein[idx][1]
        mu  <- mean(summ$Mean[idx], na.rm=TRUE)
        sdv <- stats::sd(summ$Mean[idx], na.rm=TRUE)
        div <- if (identical(centre, "z") && is.finite(sdv) && sdv > 0) sdv else 1
        summ$Mean[idx] <- (summ$Mean[idx] - mu) / div
        summ$SD[idx]   <- summ$SD[idx] / div
        summ$SE[idx]   <- summ$SE[idx] / div
        ci <- which(cells$Protein == prot)
        if (length(ci)) cells$Value[ci] <- (cells$Value[ci] - mu) / div
      }
    }

    summ$Cluster  <- factor(summ$Cluster,  levels=lv)
    cells$Cluster <- factor(cells$Cluster, levels=lv)
    summ$Protein  <- factor(summ$Protein,  levels=rownames(m))
    cells$Protein <- factor(cells$Protein, levels=rownames(m))
    if (use_split) {
      slv <- levels(.lvl_factor(ctx$seu@meta.data[[splitv]], splitv))
      slv <- intersect(slv, unique(c(summ$Split, cells$Split)))
      summ$Split  <- factor(summ$Split,  levels=slv)
      cells$Split <- factor(cells$Split, levels=slv)
    }
    summ <- summ[order(summ$Protein, summ$Cluster), , drop=FALSE]

    summ$lo <- if (identical(band, "sd")) summ$Mean - summ$SD else summ$Mean - summ$SE
    summ$hi <- if (identical(band, "sd")) summ$Mean + summ$SD else summ$Mean + summ$SE

    # One discrete colour scale, keyed to whichever variable is doing the
    # colouring. Keeping it to one scale is why the split recolours the LINES
    # too: two independent discrete colour scales would need ggnewscale, which
    # is not a dependency here.
    if (use_split) {
      summ$ColourBy  <- summ$Split
      cells$ColourBy <- cells$Split
      summ$GroupBy   <- interaction(summ$Protein, summ$Split, drop=TRUE)
      pal <- .pal_for(splitv, levels(summ$Split))
      if (is.null(pal)) {
        pal <- .cluster_pal_cols(nlevels(summ$Split),
                                 input$s_cluster_pal_family %||% "okabe")
        names(pal) <- levels(summ$Split)
      }
      col_title <- splitv
    } else {
      summ$ColourBy  <- summ$Protein
      cells$ColourBy <- cells$Protein
      summ$GroupBy   <- summ$Protein
      pal <- .cluster_pal_cols(nlevels(summ$Protein),
                               input$s_cluster_pal_family %||% "okabe")
      names(pal) <- levels(summ$Protein)
      col_title <- NULL
    }

    faceted <- isTRUE(input[[paste0(p, "_tj_facet")]])
    g <- ggplot2::ggplot(summ, ggplot2::aes(x=Cluster, y=Mean,
                                            group=GroupBy, colour=ColourBy)) +
      { if (centre != "none")
          ggplot2::geom_hline(yintercept=0, linetype="dotted", colour="grey40") } +
      { if (identical(mode, "cells"))
          ggplot2::geom_jitter(data=cells,
            ggplot2::aes(x=Cluster, y=Value, colour=ColourBy),
            width=0.18, height=0, alpha=0.25,
            size=.num(input[[paste0(p, "_tj_pt")]], 1.6), inherit.aes=FALSE) } +
      { if (!identical(band, "none"))
          ggplot2::geom_ribbon(ggplot2::aes(ymin=lo, ymax=hi, fill=ColourBy),
                               alpha=0.18, colour=NA) } +
      ggplot2::geom_line(linewidth=0.7) +
      ggplot2::geom_point(size=.num(input[[paste0(p, "_tj_pt")]], 1.6) + 0.6) +
      ggplot2::scale_colour_manual(values=pal, na.value="grey70") +
      ggplot2::scale_fill_manual(values=pal, guide="none", na.value="grey80") +
      ggplot2::theme_classic(base_size=fs) +
      ggplot2::labs(
        x = d$grp_name, colour = col_title,
        y = switch(centre, "z" = "z-scored cluster mean",
                           "center" = "centred cluster mean",
                           "cluster mean"),
        title = paste0(d$label, " \u2014 abundance across ", length(lv), " clusters",
                       if (use_split) paste0(", split by ", splitv) else ""),
        subtitle = paste0(.disp_label(src),
                          if (!identical(band, "none"))
                            paste0("  |  band = ", toupper(band)) else "",
                          if (centre != "none")
                            "  |  scaled per protein across cluster means" else "",
                          if (use_split && !faceted && nlevels(summ$Protein) > 1)
                            "  |  several proteins x levels on one panel \u2014 tick 'One panel per protein'"
                          else ""))
    if (faceted)
      g <- g + ggplot2::facet_wrap(~Protein, scales="free_y") +
               ggplot2::theme(legend.position = if (use_split) "right" else "none")
    g
  }

  # Feature-overlay builder shared by the panel and the PDF export.
  #
  # The export used to call FeaturePlot on the raw object, so it ignored the
  # layer selector (s_feat_disp_src) entirely and always drew the untouched
  # assay: a panel set to scale.data exported as data, with no caption saying
  # which. It also skipped .display_seu, so NA cells came out in Seurat's
  # default grey instead of at the bottom of the gradient.
  .build_mk_feat <- function(fs = NULL) {
    req(s_seu_with_ident(), input$s_mk_feat_genes, "umap" %in% names(s_seu_with_ident()@reductions))
    seu_use <- s_seu_with_ident()
    g <- intersect(input$s_mk_feat_genes, rownames(seu_use)); req(length(g)>0)
    assay_use <- if("SCT" %in% names(seu_use@assays))"SCT" else input$s_assay
    ncol_use  <- if(!is.null(input$s_mk_feat_ncol)) input$s_mk_feat_ncol else 4
    Seurat::DefaultAssay(seu_use) <- assay_use
    # Missing (NA / not-detected) cells otherwise render in Seurat's default grey,
    # which dominates NA-heavy proteomics overlays. Fill each protein's NA cells
    # with that protein's MINIMUM observed value so they take the LOWEST color on
    # the scale (blend into the "low expression" end) rather than standing out in
    # grey. Display-only copy — the data layer used for testing is untouched.
    # Default "scale.data": the embedding was computed after covariate
    # regression, so coloring it with covariate-adjusted values keeps layout and
    # color on the same footing. Switch to "data" for the untouched normalized values
    # that the marker statistics are based on.
    fp_src  <- input$s_feat_disp_src %||% "scale.data"
    # Not-detected renders at the bottom of the gradient either way — filled at
    # the protein's minimum, or left NA and drawn at na.value, both grey90 — so
    # observed-only is the same picture here and is collapsed rather than passed
    # to FeaturePlot, which fails on NA as VlnPlot does.
    if (identical(fp_src, "data_obs")) fp_src <- "data"
    # A protein with no row in scale.data is padded with 0, which on a residual
    # scale looks like "perfectly average" rather than "not available". Name them
    # instead of letting the plot imply a result.
    miss_sd <- if (identical(fp_src, "scale.data"))
                 .scale_data_missing(seu_use, assay_use, g) else character(0)
    seu_use <- .display_seu(seu_use, assay_use, src=fp_src, na_offset=0)
    pt <- if (is.null(fs)) 1.5 else .pdf_pt(1.5)
    fp <- Seurat::FeaturePlot(seu_use, features=g, reduction="umap", pt.size=pt,
                              cols=c("grey90","#8E44AD"), ncol=ncol_use) &
      ggplot2::scale_color_gradient(low="grey90", high="#8E44AD", na.value="grey90")
    cap <- .disp_caption(fp_src, "min")
    if (length(miss_sd))
      cap <- paste0(cap, "\nNo scale.data for ", length(miss_sd), " selected protein(s): ",
                    paste(utils::head(miss_sd, 6), collapse=", "),
                    if (length(miss_sd) > 6) paste0(", +", length(miss_sd)-6, " more") else "",
                    " \u2014 drawn as a flat 0 field, not a measurement.")
    fp <- .add_caption(fp, cap)
    if (is.null(fs)) fp else tryCatch(fp & ggplot2::theme_classic(base_size=fs),
                                      error=function(e) fp)
  }

  output$s_mk_feat <- renderPlot({ print(.build_mk_feat(NULL)) })

  output$s_dot <- renderPlot({
    req(s_seu_with_ident(), s$markers, input$s_mk_grpby, input$s_dot_n)
    seu_use <- s_seu_with_ident()
    top <- .mk_top_per_cluster(s$markers, input$s_dot_n)
    top <- intersect(top, rownames(seu_use)); req(length(top)>0)
    assay_use <- if("SCT" %in% names(seu_use@assays))"SCT" else input$s_assay
    method <- input$s_norm_method %||% "sct"

    # ── NA-aware dot plot for VSN/scpmed ─────────────────────────────────────
    # Dot SIZE   = true detection rate (non-NA fraction per group). Computed from
    #              the NA pattern, which regression never alters — a value is
    #              either observed or it is not.
    # Dot COLOUR = mean of the ADJUSTED values (data layer: the scplainer
    #              reconstruction, intercept + retained effect + residual), taken
    #              over OBSERVED cells only. Not-detected values are excluded from
    #              the mean rather than filled, so a low color means "measured
    #              low", never "not measured" — that information is in the size.
    # Switchable to the un-regressed tested matrix via the plot-source control.
    if (method %in% .NA_AWARE) {
      dot_src <- input$s_mk_disp_src %||% "data"
      # Detection rate must come from the DATA layer's NA pattern: scale.data has
      # not-detected filled with 0, so every entry there is non-missing and the
      # size channel would read 100% everywhere. Color follows the chosen layer.
      m_det <- tryCatch(as.matrix(SeuratObject::LayerData(
                 seu_use@assays[[assay_use]], layer="data")), error=function(e) NULL)
      # The dot plot already excludes not-detected from every statistic, so
      # "data" and "data_obs" are the same picture here.
      if (identical(dot_src, "data_obs")) dot_src <- "data"
      m <- if (identical(dot_src, "scale.data"))
             tryCatch(as.matrix(SeuratObject::LayerData(
               seu_use@assays[[assay_use]], layer="scale.data")), error=function(e) NULL)
           else m_det
      if (is.null(m))     m <- m_det
      if (is.null(m_det)) m_det <- m
      validate(need(!is.null(m), "No matrix available for the dot plot."))
      md <- seu_use@meta.data
      grpby <- input$s_mk_grpby
      cells <- intersect(colnames(m), rownames(md))
      feats <- intersect(top, rownames(m))
      validate(need(length(feats) > 0 && length(cells) > 0,
                    "None of the selected features are present in the chosen matrix."))
      m <- m[feats, cells, drop=FALSE]
      grp <- as.character(md[cells, grpby])
      cl_levels <- sort(unique(grp[!is.na(grp)]))
      df <- do.call(rbind, lapply(rownames(m), function(g){
        do.call(rbind, lapply(cl_levels, function(cl){
          v   <- m[g, grp == cl]
          # Detection from the data layer; when a feature is missing there, fall
          # back to the plotted matrix so the row is still drawn.
          vd  <- if (g %in% rownames(m_det)) m_det[g, grp == cl] else v
          nn  <- sum(!is.na(vd))
          keep_v <- if (identical(dot_src, "scale.data")) !is.na(vd) else !is.na(v)
          data.frame(feature = g, cluster = cl,
                     n_obs    = nn,
                     detect   = if (length(vd)) nn/length(vd)*100 else 0,
                     # Mean over cells DETECTED in the data layer, so a scale.data
                     # color is never dragged toward 0 by filled not-detected
                     # entries — the fill would otherwise bias every sparse
                     # feature toward the center of the scale.
                     mean_obs = if (any(keep_v)) mean(v[keep_v], na.rm=TRUE) else NA_real_,
                     stringsAsFactors = FALSE)
        }))
      }))
      # A feature/group cell with zero observations has no mean to show. Previously
      # it was drawn as an NA-colored dot, which reads as a low value; drop those
      # points instead and say how many were dropped.
      n_empty <- sum(df$n_obs == 0)
      df_plot <- df[df$n_obs > 0, , drop=FALSE]
      validate(need(nrow(df_plot) > 0,
                    "No feature was detected in any group of the chosen matrix."))
      df_plot$feature <- factor(df_plot$feature, levels=rownames(m))
      p <- ggplot(df_plot, aes(x=feature, y=cluster)) +
        geom_point(aes(size=detect, color=mean_obs)) +
        scale_size_continuous(range=c(0.4,7), limits=c(0,100), name="Detection %\n(non-NA)") +
        scale_color_gradient(low="grey85", high="#8E44AD", name="Mean of\nobserved") +
        theme_classic(base_size=13) +
        theme(axis.text.x=element_text(angle=45, hjust=1, size=9)) +
        labs(x="Features", y=input$s_mk_grpby,
             title="Size = true detection rate  |  Color = mean of observed values",
             caption = paste0(.disp_caption(dot_src, "excluded"),
                              if (n_empty > 0)
                                paste0("; ", n_empty,
                                       " feature\u00d7group combinations omitted (0 cells detected)")
                              else ""))
      return(p)
    }

    # Standard path (SCT/LogNorm): Seurat DotPlot. Dot size here is the fraction
    # of cells with a NON-ZERO value, and zeros were written at object build, so
    # size conflates "not detected" with "measured zero" — unlike the NA-aware
    # branch above, where the two are separable.
    Seurat::DotPlot(seu_use, features=top, assay=assay_use) +
      RotatedAxis() + theme(axis.text.x=element_text(angle=45, hjust=1, size=9)) +
      labs(caption = .disp_caption("data", "zero"))
  })

  # ── P-value histogram (test-calibration QC, works for all test paths) ────────
  output$s_ph_cluster_ui <- renderUI({
    req(s$markers)
    cls <- sort(unique(as.character(s$markers$cluster)))
    selectInput("s_ph_cluster","Cluster / contrast:",
                choices=c("All"="__all__", setNames(cls, cls)), selected="__all__")
  })
  # P-value histogram builder, shared by both panels and both PDF cases.
  #
  # The PDF versions hardcoded 21 breaks and a /20 expectation line, so the bin
  # slider and the cluster selector on screen had no effect on the exported
  # figure. Both now read the same inputs. `pfx` is "s_ph" (9) or "i_ph" (12).
  .build_phist <- function(mk, pfx, title_stem, fs = 13) {
    if (is.null(mk) || !nrow(mk))
      stop("No marker results yet — run Find Markers first.", call. = FALSE)
    pcol <- if ("p_val" %in% names(mk)) "p_val" else
            names(mk)[grep("^p[._]?val$|pvalue|p\\.value", names(mk), ignore.case=TRUE)][1]
    if (is.null(pcol) || !pcol %in% names(mk))
      stop("No p-value column in results.", call. = FALSE)
    sel <- input[[paste0(pfx, "_cluster")]] %||% "__all__"
    if (!is.null(sel) && sel != "__all__" && "cluster" %in% names(mk))
      mk <- mk[as.character(mk$cluster) == sel, , drop=FALSE]
    pv <- mk[[pcol]]; pv <- pv[is.finite(pv)]
    if (!length(pv)) stop("No finite p-values to plot.", call. = FALSE)
    bins <- max(2, min(200, .num(input[[paste0(pfx, "_bins")]], 20)))
    ggplot(data.frame(p=pv), aes(x=p)) +
      geom_histogram(breaks=seq(0,1,length.out=bins+1),
                     fill="#5DADE2", color="white", boundary=0) +
      # Expectation line must track the bin count, or it sits at the wrong
      # height as soon as the slider moves off 20.
      geom_hline(yintercept=length(pv)/bins, linetype="dashed", color="#E74C3C") +
      theme_classic(base_size=fs) +
      labs(x="raw p-value", y="proteins",
           title=paste0(title_stem,
                        if(sel!="__all__") paste0(" — ", sel) else "",
                        "  (dashed red = uniform expectation)"))
  }

  output$s_mk_phist <- renderPlot({
    req(s$markers)
    p <- tryCatch(.build_phist(s$markers, "s_ph", "P-value distribution", 13),
                  error = function(e) e)
    validate(need(!inherits(p, "error"), if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  # ── ⑪ Integrated Clustering ─────────────────────────────────────────────────
  # Uses s$seu_int; DefaultAssay = "integrated" for graph/clustering, then
  # switches back to SCT for all marker work.

  # Shared cluster color resolver: returns a NAMED color vector keyed to the
  # given cluster levels, so every cluster-colored plot (UMAP, proportions, PDF)
  # uses the SAME colors. Prefers a user-set seurat_clusters palette; otherwise
  # uses ggplot2's DEFAULT discrete palette (scales::hue_pal) — the same evenly-
  # spaced hues ggplot assigns automatically — so every cluster plot matches the
  # default look (salmon/olive/teal/purple for 4 clusters) unless a custom
  # palette is applied.
  # Generate n colours from the family chosen in ③ Covariates. Recycles with a
  # warning-free wrap rather than erroring, so a cluster count above the family
  # size still plots.
  .cluster_pal_cols <- function(n, family = "okabe") {
    pick <- function(v) rep(v, ceiling(n/length(v)))[seq_len(n)]
    poly <- function() tryCatch(Seurat::DiscretePalette(n, palette="polychrome"),
                                error=function(e) pick(OKABE_ITO))
    # One entry point for every viridisLite map. Sampling a SEQUENTIAL map at n
    # points for categorical clusters is a deliberate compromise: it is
    # perceptually uniform and CVD-safe, but it implies an ordering the clusters
    # do not have, and neighbouring clusters get neighbouring colours. begin/end
    # trim the extremes, which are near-black and near-white in viridis and
    # otherwise read as "missing" rather than as a cluster.
    vir <- function(opt, begin = 0.05, end = 0.95) {
      tryCatch(viridis::viridis(n, option = opt, begin = begin, end = end),
               error = function(e)
                 tryCatch(viridisLite::viridis(n, option = opt, begin = begin, end = end),
                          error = function(e2) pick(OKABE_ITO)))
    }
    switch(family,
      "okabe"      = if (n <= length(OKABE_ITO)) OKABE_ITO[seq_len(n)] else poly(),
      "tol"        = if (n <= length(TOL_MUTED)) TOL_MUTED[seq_len(n)] else poly(),
      "polychrome" = poly(),
      "viridis"    = vir("viridis"),
      "cividis"    = vir("cividis"),
      "mako"       = vir("mako"),
      "plasma"     = vir("plasma"),
      "turbo"      = vir("turbo", begin = 0, end = 1),
      "hue"        = if (requireNamespace("scales", quietly=TRUE))
                       scales::hue_pal()(n) else pick(CLUSTER_PALETTE),
      pick(OKABE_ITO))
  }

  .cluster_cols <- function(levels) {
    levels <- as.character(levels)
    # An explicit per-level palette set in ③ always wins, and is keyed by level
    # NAME so it survives re-clustering at a different resolution.
    pal <- s$palette[["seurat_clusters"]]
    if (!is.null(pal) && all(levels %in% names(pal))) return(pal[levels])
    fam  <- input$s_cluster_pal_family %||% "okabe"
    cols <- .cluster_pal_cols(length(levels), fam)
    setNames(cols, levels)
  }

  # Readable label colour for a swatch, from WCAG relative luminance.
  #
  # The previous rule tested only the first hex digit of the RED channel as a
  # stand-in for lightness, which is wrong for any colour whose lightness comes
  # from green or blue: Okabe-Ito's sky blue #56B4E9 has R = 0x56 and so was
  # given white text on a light background. Green carries ~72% of perceived
  # luminance, so it has to be weighted properly.
  .text_on_bg <- function(hex) {
    rgb <- tryCatch(grDevices::col2rgb(hex)[, 1] / 255, error = function(e) NULL)
    if (is.null(rgb)) return("#000")
    lin <- function(v) ifelse(v <= 0.03928, v / 12.92, ((v + 0.055) / 1.055)^2.4)
    L <- 0.2126 * lin(rgb[1]) + 0.7152 * lin(rgb[2]) + 0.0722 * lin(rgb[3])
    if (L > 0.4) "#000" else "#fff"
  }

  # Swatch preview of the active cluster palette, at the real cluster count so
  # the user sees what the figures will actually use (the ggplot hue family in
  # particular looks different at n = 4 and n = 12).
  output$s_cluster_pal_preview <- renderUI({
    fam <- input$s_cluster_pal_family %||% "okabe"
    lv  <- tryCatch({
      sc <- s$seu@meta.data[["seurat_clusters"]]
      if (is.null(sc)) NULL else levels(droplevels(as.factor(sc)))
    }, error=function(e) NULL)
    n   <- if (is.null(lv)) 8L else length(lv)
    cols <- .cluster_pal_cols(n, fam)
    labs <- if (is.null(lv)) as.character(seq_len(n) - 1L) else lv
    tagList(
      div(style="display:flex;flex-wrap:wrap;gap:4px;margin:4px 0 2px 0;",
        lapply(seq_len(n), function(i)
          div(style=paste0("background:", cols[i], ";color:", .text_on_bg(cols[i]),
                           ";font-size:11px;font-weight:600;padding:3px 8px;",
                           "border-radius:3px;border:1px solid rgba(0,0,0,0.25);",
                           "font-family:monospace;"),
              labs[i]))
      ),
      tags$p(tags$small(
        if (is.null(lv))
          "No clusters yet \u2014 showing 8 swatches as an example."
        else paste0(n, " cluster(s) in the current object.")),
        style="color:#7f8c8d;font-size:11px;margin:0;"),
      actionButton("s_cluster_pal_to_editor",
                   "Copy into the per-level editor below",
                   class="btn-default",
                   style="width:100%;margin-top:6px;font-size:12px;")
    )
  })

  # Materialise the generated family into s$palette so the individual colours
  # become editable, and so they are pinned by level NAME \u2014 after this a
  # re-cluster at a different resolution keeps the colours it already matched
  # instead of regenerating from the new cluster count.
  observeEvent(input$s_cluster_pal_to_editor, {
    sc <- tryCatch(s$seu@meta.data[["seurat_clusters"]], error=function(e) NULL)
    if (is.null(sc)) {
      showNotification("No clusters yet \u2014 run clustering first.", type="warning", duration=6)
      return(invisible(NULL))
    }
    lv <- levels(droplevels(as.factor(sc)))
    s$palette[["seurat_clusters"]] <-
      setNames(.cluster_pal_cols(length(lv), input$s_cluster_pal_family %||% "okabe"), lv)
    s_log(paste0("Cluster palette pinned from '", input$s_cluster_pal_family %||% "okabe",
                 "' for ", length(lv), " clusters."))
    showNotification(paste0("Palette copied for ", length(lv),
                            " clusters \u2014 edit individual colours below."),
                     type="message", duration=5)
  })

  # ── Generic metadata-palette resolver ───────────────────────────────────────
  # ONE entry point for "what colors does this grouping variable use". Every
  # discrete-colored plot should go through here rather than reading s$palette
  # directly, because that is how a color set in ③ Covariates reaches ALL
  # figures instead of only the handful that happened to look it up.
  #
  #   cov     metadata column name (NULL / "none" -> NULL, i.e. ggplot default)
  #   levels  the levels actually present in this plot; the returned vector is
  #           subset and ORDERED to match, which is what Seurat's cols= needs
  #           (it matches by position, so an unfiltered palette shifts colors).
  #
  # Returns a named character vector, or NULL when no custom palette applies.
  .pal_for <- function(cov, levels = NULL) {
    if (is.null(cov) || !length(cov) || identical(cov, "none")) return(NULL)
    pal <- if (identical(cov, "seurat_clusters")) {
             if (is.null(levels)) s$palette[["seurat_clusters"]]
             else .cluster_cols(levels)
           } else s$palette[[cov]]
    if (is.null(pal) || !length(pal)) return(NULL)
    if (!is.null(levels)) {
      levels <- as.character(levels)
      pal    <- pal[names(pal) %in% levels]
      if (!length(pal)) return(NULL)
      # Position-ordered to the plot's own level order (the level ORDER control
      # can reorder levels; colors stay keyed by name).
      keep <- levels[levels %in% names(pal)]
      pal  <- pal[keep]
    }
    pal
  }

  # The levels a covariate actually takes on an object, in plot order. Split out
  # so callers that need a ggplot SCALE rather than a cols= vector (FeatureScatter,
  # which has no cols= argument) can pass the same level set to .scale_col_for().
  .pal_lv <- function(seu, cov) {
    if (is.null(seu) || is.null(cov) || !length(cov)) return(NULL)
    if (!cov %in% names(seu@meta.data)) return(NULL)
    v <- seu@meta.data[[cov]]
    if (is.factor(v)) levels(droplevels(v)) else sort(unique(as.character(v[!is.na(v)])))
  }

  # Palette for a Seurat plot's group.by, read off the object so the level set
  # and order are exactly what the plot will draw. Pass the result to cols=.
  .pal_seu <- function(seu, cov) {
    if (is.null(seu) || is.null(cov) || !length(cov) || identical(cov, "none")) return(NULL)
    .pal_for(cov, .pal_lv(seu, cov))
  }

  # Factor a vector using the stored level ORDER for its covariate, so a
  # hand-built data.frame (which never passes through .apply_level_order) still
  # honours the drag-to-order control. Levels present but unordered are appended.
  .lvl_factor <- function(x, cov) {
    present <- sort(unique(as.character(x[!is.na(x)])))
    want    <- if (!is.null(cov) && length(cov)) s$level_order[[cov]] else NULL
    lv      <- if (is.null(want)) present
               else c(want[want %in% present], setdiff(present, want))
    factor(as.character(x), levels=lv)
  }

  # ggplot scale wrappers for hand-built (non-Seurat) plots. Return NULL when no
  # palette applies, which is safe to `+` inside a { } list element.
  .scale_col_for <- function(cov, levels=NULL, na.value="grey70") {
    pal <- .pal_for(cov, levels)
    if (is.null(pal)) NULL else ggplot2::scale_color_manual(values=pal, na.value=na.value)
  }
  .scale_fill_for <- function(cov, levels=NULL, na.value="grey90") {
    pal <- .pal_for(cov, levels)
    if (is.null(pal)) NULL else ggplot2::scale_fill_manual(values=pal, na.value=na.value)
  }

  i_dim_plotly <- function(color_by, title) {
    req(s$seu_int, "umap" %in% names(s$seu_int@reductions))
    emb <- as.data.frame(Seurat::Embeddings(s$seu_int,"umap")[,1:2])
    colnames(emb) <- c("D1","D2"); emb$Cell <- rownames(emb)
    emb$Label <- if("ID" %in% names(s$seu_int@meta.data)) s$seu_int@meta.data[emb$Cell,"ID"] else emb$Cell
    cb <- if(!is.null(color_by) && color_by %in% names(s$seu_int@meta.data))
      as.factor(s$seu_int@meta.data[emb$Cell,color_by])
    else factor(rep("All",nrow(emb)))
    emb$Color <- cb
    pal  <- if(!is.null(color_by)) s$palette[[color_by]] else NULL
    # seurat_clusters: use the shared resolver so the UMAP matches the
    # proportions/other cluster plots even when no custom palette is set.
    if (identical(color_by, "seurat_clusters")) pal <- .cluster_cols(levels(cb))
    p    <- ggplot(emb,aes(x=D1,y=D2,color=Color,text=Label))+
      geom_point(size=2.5,alpha=0.8)+theme_classic(base_size=13)+
      labs(title=title,color=if(!is.null(color_by))color_by else "")
    if (!is.null(pal)) p <- p + ggplot2::scale_color_manual(values=pal, na.value="grey70")
    ggplotly(p,tooltip=c("text","x","y"))
  }

  output$i_clust_umap <- renderPlotly({
    i_dim_plotly("seurat_clusters","Integrated UMAP — clusters")
  })
  output$i_clust_umap_grp <- renderPlotly({
    req(s$seu_int, input$s_int_color2)
    i_dim_plotly(input$s_int_color2, paste0("Integrated UMAP — ",input$s_int_color2))
  })
  output$i_clust_prop <- renderPlotly({
    req(s$seu_int,"seurat_clusters" %in% names(s$seu_int@meta.data))
    df_p <- as.data.frame(table(Cluster=s$seu_int$seurat_clusters))
    df_p$Pct <- df_p$Freq/sum(df_p$Freq)*100
    ggplotly(ggplot(df_p,aes(x=Cluster,y=Pct,fill=Cluster,
                              text=paste0("Cluster ",Cluster,"\n",round(Pct,1),"% (",Freq," cells)")))+
               geom_bar(stat="identity")+
               scale_fill_manual(values=.cluster_cols(levels(df_p$Cluster)))+
               theme_classic(base_size=13)+labs(y="% cells",title="Integrated cluster proportions"),
             tooltip="text")
  })
  output$i_clust_meta_ui <- renderUI({ req(s$seu_int); selectInput("i_clust_meta_col","Variable:",choices=names(s$seu_int@meta.data)) })
  output$i_clust_meta <- renderPlotly({
    p <- tryCatch(.build_clust_meta(s$seu_int, input$i_clust_meta_col,
                                    "Integrated cluster × ", 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    ggplotly(p)
  })

  # ── Integration clustering diagnostics: Clustree / Silhouette ────────────────
  # Resolve the reduction the integrated clustering actually used: 'integrated.cca'
  # for the IntegrateLayers path (LogNorm/VSN/scpmed), else 'pca' (SCT).
  i_int_reduc <- reactive({
    req(s$seu_int)
    if ("integrated.cca" %in% names(s$seu_int@reductions)) "integrated.cca"
    else if ("pca" %in% names(s$seu_int@reductions)) "pca"
    else names(s$seu_int@reductions)[1]
  })

  observeEvent(input$i_run_clustree, {
    req(s$seu_int)
    reduc <- i_int_reduc()
    req(reduc %in% names(s$seu_int@reductions))
    s$i_clustree_seu <- NULL
    tryCatch({
      res_vals <- sort(unique(as.numeric(input$i_clustree_res)))
      res_vals <- res_vals[is.finite(res_vals)]
      if (length(res_vals) < 2)
        stop("Tick at least two resolutions — a tree needs more than one tier.", call.=FALSE)
      dims     <- 1:min(input$i_clustree_dims, ncol(Seurat::Embeddings(s$seu_int, reduc)))
      kp       <- input$i_clust_k %||% 20    # match the integrated clustering k.param
      withProgress(message=paste0("Clustree: ", length(res_vals), " resolutions (k=", kp, ")..."), value=0, {
        seu_ct <- .strip_res_cols(s$seu_int)
        seu_ct <- Seurat::FindNeighbors(seu_ct, reduction=reduc, dims=dims, k.param=kp, verbose=FALSE)
        for (res in res_vals) {
          incProgress(1/length(res_vals))
          seu_ct <- Seurat::FindClusters(seu_ct, resolution=res, verbose=FALSE)
        }
        s$i_clustree_res <- res_vals
        s$i_clustree_seu <- seu_ct
      })
      s_log(paste0("Integration clustree: resolutions (", paste(res_vals, collapse=", "),
                   ") | dims 1:", max(dims), " | k.param=", kp,
                   " | reduction=", reduc, "."))
      showNotification(paste0("Integration clustree done (k=", kp, ")."), type="message", duration=4)
    }, error=function(e) {
      s$i_clustree_seu <- NULL
      showNotification(paste0("Clustree error: ", e$message), type="error", duration=10)
    })
  })

  observeEvent(list(input$i_clustree_res, input$i_clustree_dims, input$i_clust_k), {
    if (!is.null(s$i_clustree_seu)) {
      s$i_clustree_seu <- NULL
      s$i_clustree_res <- NULL
    }
  }, ignoreInit = TRUE)

  output$i_clustree_plot <- renderPlot({
    p <- tryCatch(.build_clustree(s$i_clustree_seu, 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  observeEvent(input$i_run_sil_grid, {
    req(s$seu_int)
    reduc <- i_int_reduc()
    req(reduc %in% names(s$seu_int@reductions))
    tryCatch({
      res_vals <- as.numeric(input$i_sil_res)
      k_vals   <- as.numeric(input$i_sil_k)
      dims     <- 1:min(input$i_sil_dims, ncol(Seurat::Embeddings(s$seu_int, reduc)))
      grid     <- expand.grid(res=res_vals, k=k_vals)
      dist_mat <- cluster::daisy(Seurat::Embeddings(s$seu_int, reduc)[, dims])
      withProgress(message="Silhouette grid...", value=0, {
        grid$sil <- NA_real_
        for (i in seq_len(nrow(grid))) {
          incProgress(1/nrow(grid))
          tryCatch({
            st <- Seurat::FindNeighbors(s$seu_int, reduction=reduc, dims=dims,
                                        k.param=grid$k[i], verbose=FALSE)
            st <- Seurat::FindClusters(st, resolution=grid$res[i], verbose=FALSE)
            cl <- as.integer(st$seurat_clusters)
            if (length(unique(cl)) > 1)
              grid$sil[i] <- round(mean(cluster::silhouette(cl, dist_mat)[,3]),3)
          }, error=function(e) NULL)
        }
        s$i_sil_grid <- grid
      })
      showNotification("Silhouette grid done.", type="message", duration=4)
    }, error=function(e) showNotification(paste0("Sil grid error: ", e$message),
                                          type="error", duration=10))
  })

  output$i_sil_grid_plot <- renderPlot({
    p <- tryCatch(.build_sil_grid(s$i_sil_grid, "Integrated: mean silhouette", 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  observeEvent(input$i_run_sil, {
    req(s$seu_int, "seurat_clusters" %in% names(s$seu_int@meta.data))
    reduc <- i_int_reduc()
    req(reduc %in% names(s$seu_int@reductions))
    tryCatch({
      withProgress(message="Computing silhouette...", value=0.5, {
        dims     <- 1:min(input$i_clust_dims %||% 30, ncol(Seurat::Embeddings(s$seu_int, reduc)))
        dist_mat <- cluster::daisy(Seurat::Embeddings(s$seu_int, reduc)[, dims])
        s$i_sil_result <- cluster::silhouette(as.integer(s$seu_int$seurat_clusters), dist_mat)
      })
      showNotification("Silhouette done.", type="message", duration=4)
    }, error=function(e) showNotification(paste0("Silhouette error: ", e$message),
                                          type="error", duration=10))
  })

  output$i_sil_summary_ui <- renderUI({
    req(s$i_sil_result)
    m   <- round(mean(s$i_sil_result[,3]), 3)
    col <- if(m>0.5)"#27AE60" else if(m>0.25)"#F39C12" else "#E74C3C"
    tags$p(paste0("Mean silhouette: ", m),
           style=paste0("color:",col,";font-weight:600;font-size:14px;"))
  })

  output$i_sil_plot <- renderPlot({
    p <- tryCatch(.build_sil_bar(s$i_sil_result, "Integrated silhouette by cluster", 13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })


  # ── Integration UMAP technical overlay ──────────────────────────────────────
  # (The variable selector output$i_tech_overlay_var_ui is defined later as a
  #  server-side multi-select for performance with large protein lists.)

  i_tech_grid_plot <- reactiveVal(NULL)

  # Build the integrated technical-overlay grid fresh from current inputs. Used
  # by both the GUI observe and the PDF export, so the PDF doesn't depend on a
  # stored patchwork object rendering correctly in a different device context
  # (which was producing a blank PDF while the GUI looked fine).
  .build_i_tech_grid <- function() {
    if (is.null(s$seu_int) || !("umap" %in% names(s$seu_int@reductions))) return(NULL)
    vars_sel <- input$i_tech_overlay_var
    vars_sel <- vars_sel[!is.null(vars_sel) & nzchar(vars_sel)]
    if (length(vars_sel) == 0) return(NULL)
    seu_use  <- i_seu_with_ident()
    assay_use0 <- if("SCT" %in% names(seu_use@assays)) "SCT" else input$s_assay
    seu_use  <- tryCatch(.display_safe_seu(seu_use, assay_use0), error=function(e) seu_use)
    pt_size  <- input$i_tech_pt_size %||% 2
    ncol_use <- .num(input$i_tech_ncol, 2)
    assay_use <- if("SCT" %in% names(seu_use@assays)) "SCT" else input$s_assay
    plot_list <- lapply(vars_sel, function(v) {
      tryCatch({
        is_meta    <- v %in% names(seu_use@meta.data)
        is_protein <- v %in% rownames(seu_use)
        if (is_meta) {
          vals    <- seu_use@meta.data[[v]]
          is_cont <- is.numeric(vals) && length(unique(vals[!is.na(vals)])) > 8
          if (is_cont) {
            seu_use[[".tmp_int_ov"]] <- as.numeric(vals)
            Seurat::FeaturePlot(seu_use, features=".tmp_int_ov", reduction="umap",
                                pt.size=pt_size, cols=c("grey90","#E74C3C")) +
              ggplot2::ggtitle(v) + ggplot2::theme(plot.title=ggplot2::element_text(size=11))
          } else {
            # seurat_clusters uses the shared resolver so this panel matches the
            # main cluster UMAP and the proportions plot; other covariates use
            # their custom palette if one is set.
            pal <- .pal_seu(seu_use, v)
            Seurat::DimPlot(seu_use, reduction="umap", group.by=v, pt.size=pt_size,
                            cols=if(!is.null(pal)) pal else NULL) +
              ggplot2::ggtitle(v) + ggplot2::theme(plot.title=ggplot2::element_text(size=11))
          }
        } else if (is_protein) {
          Seurat::DefaultAssay(seu_use) <- assay_use
          Seurat::FeaturePlot(seu_use, features=v, reduction="umap",
                              pt.size=pt_size, cols=c("grey90","#8E44AD")) +
            ggplot2::ggtitle(v) + ggplot2::theme(plot.title=ggplot2::element_text(size=11))
        } else NULL
      }, error=function(e) {
        ggplot2::ggplot() + ggplot2::theme_void() +
          ggplot2::labs(title=paste0(v,"\nError: ",conditionMessage(e)))
      })
    })
    plot_list <- Filter(Negate(is.null), plot_list)
    if (length(plot_list) == 0) return(NULL)
    patchwork::wrap_plots(plot_list, ncol=ncol_use) &
      ggplot2::theme(legend.position="right")
  }

  observeEvent(input$i_tech_run, {
    i_tech_grid_plot(.build_i_tech_grid())
  })

  output$i_tech_overlay_plot <- renderPlot({
    p <- i_tech_grid_plot()
    if (is.null(p)) {
      plot(0, type="n", axes=FALSE, xlab="", ylab="")
      text(0, 0, "Select variables and click 'Draw grid'", cex=1.1, col="grey50")
    } else print(p)
  })

  # ── ⑫ Integrated Markers ────────────────────────────────────────────────────
  # DefaultAssay must be SCT (not integrated) for FindMarkers — set in run button

  output$i_mk_grpby_ui <- renderUI({
    req(s$seu_int); opts <- c("seurat_clusters",names(s$seu_int@meta.data))
    selectInput("i_mk_grpby","Identity class:",choices=opts,
                selected=if("seurat_clusters" %in% names(s$seu_int@meta.data))"seurat_clusters" else opts[1])
  })
  output$i_mk_id1_ui <- renderUI({
    req(s$seu_int,input$i_mk_grpby)
    ids <- sort(unique(as.character(s$seu_int@meta.data[[input$i_mk_grpby]])))
    selectInput("i_mk_id1","Group A:",choices=ids,selected=ids[1])
  })
  output$i_mk_id2_ui <- renderUI({
    req(s$seu_int,input$i_mk_grpby)
    ids <- sort(unique(as.character(s$seu_int@meta.data[[input$i_mk_grpby]])))
    selectInput("i_mk_id2","Group B:",choices=ids,selected=ids[min(2,length(ids))])
  })
  output$i_mk_status <- renderUI({
    if (is.null(s$int_markers))
      return(tags$p("No integrated markers yet.",style="color:#E74C3C;font-size:13px;"))
    last_comp <- if(!is.null(s$last_i_mk_comp)) s$last_i_mk_comp else ""
    tagList(
      tags$p(paste0("✓ ",nrow(s$int_markers)," results"),
             style="color:#27AE60;font-size:13px;font-weight:600;"),
      if(last_comp!="") tags$p(paste0("Comparison: ",last_comp),
                                style="color:#2980B9;font-size:12px;font-weight:600;")
    )
  })

  output$i_mk_proda_cov_ui <- renderUI({
    req(s$seu_int)
    md <- s$seu_int@meta.data
    all_cols <- setdiff(names(md), c("orig.ident"))
    is_cat <- vapply(all_cols, function(c){
      v <- md[[c]]
      is.character(v) || is.factor(v) || (is.numeric(v) && length(unique(v[!is.na(v)]))<=10)
    }, logical(1))
    is_cont <- vapply(all_cols, function(c){
      v <- md[[c]]; is.numeric(v) && length(unique(v[!is.na(v)])) > 10
    }, logical(1))
    cat_cols  <- all_cols[is_cat]; cont_cols <- all_cols[is_cont]
    if (!length(cat_cols) && !length(cont_cols))
      return(tags$p(tags$small("No covariate columns available."), style="color:grey;font-size:11px;"))
    tagList(
      if (length(cat_cols)) tagList(
        tags$p(tags$small(tags$b("Categorical: "), "enter as factor (dummy-coded)"),
               style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
        checkboxGroupInput("i_mk_proda_cov", label=NULL, choices=cat_cols, selected=NULL)
      ) else NULL,
      if (length(cont_cols)) tagList(
        tags$p(tags$small(tags$b("Continuous: "), "enter as a linear term"),
               style="color:#2c3e50;font-size:11px;margin:6px 0 2px 0;"),
        checkboxGroupInput("i_mk_proda_cov_cont", label=NULL, choices=cont_cols, selected=NULL)
      ) else NULL
    )
  })

  output$i_mk_latent_ui <- renderUI({
    req(s$seu_int)
    md <- s$seu_int@meta.data
    all_cols <- setdiff(names(md), c("orig.ident","nCount_RNA","nFeature_RNA",
                                     input$i_mk_grpby))
    is_cat <- vapply(all_cols, function(c){
      v <- md[[c]]
      (is.character(v) || is.factor(v) || is.logical(v) ||
        (is.numeric(v) && length(unique(v[!is.na(v)])) <= 10)) &&
      length(unique(as.character(v)[!is.na(v)])) >= 2 &&
      length(unique(as.character(v)[!is.na(v)])) <= max(2, floor(nrow(md)/3))
    }, logical(1))
    is_cont <- vapply(all_cols, function(c){
      v <- md[[c]]
      is.numeric(v) && !is.factor(v) && length(unique(v[!is.na(v)])) > 10
    }, logical(1))
    cat_cols  <- sort(all_cols[is_cat])
    cont_cols <- sort(all_cols[is_cont])
    if (!length(cat_cols) && !length(cont_cols))
      return(tags$p(tags$small("No covariate columns available."),
                    style="color:grey;font-size:11px;"))
    cc_cols <- intersect(c("S.Score","G2M.Score","Score_Diff"), cont_cols)
    tagList(
      tags$p(tags$small(tags$b("Latent variables"),
             " \u2014 included in the test's own model (LR / MAST / negbinom / poisson)"),
             style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
      if (length(cat_cols)) tagList(
        tags$p(tags$small(tags$b("Categorical: "), "enter as factor (dummy-coded)"),
               style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
        checkboxGroupInput("i_mk_latent", label=NULL, choices=cat_cols, selected=NULL)
      ) else NULL,
      if (length(cont_cols)) tagList(
        tags$p(tags$small(tags$b("Continuous: "), "enter as a linear term"),
               style="color:#2c3e50;font-size:11px;margin:4px 0 2px 0;"),
        checkboxGroupInput("i_mk_latent_num", label=NULL, choices=cont_cols,
                           selected=if (length(cc_cols)) cc_cols else NULL)
      ) else NULL
    )
  })

  output$i_ph_cluster_ui <- renderUI({
    req(s$int_markers)
    cls <- sort(unique(as.character(s$int_markers$cluster)))
    selectInput("i_ph_cluster","Cluster / contrast:",
                choices=c("All"="__all__", setNames(cls, cls)), selected="__all__")
  })
  output$i_mk_phist <- renderPlot({
    req(s$int_markers)
    p <- tryCatch(.build_phist(s$int_markers, "i_ph",
                               "Integrated p-value distribution", 13),
                  error = function(e) e)
    validate(need(!inherits(p, "error"), if (inherits(p, "error")) conditionMessage(p) else ""))
    p
  })

  observeEvent(input$i_run_mk, {
    req(s$seu_int)
    norm_method <- input$s_norm_method %||% "sct"
    na_method   <- input$i_mk_namethod %||% "proda"
    if (norm_method %in% .NA_AWARE) .log_proda_settings("i_mk")

    # ── VSN/scpmed NA-aware integrated markers (proDA / limma / Wilcoxon) ──────
    # Mirrors the ⑨ Markers engine and reads the SAME matrix it does: the DATA
    # LAYER of s$seu — the un-regressed VSN / scp-median output.
    #
    # WHY NOT THE INTEGRATED OBJECT'S data LAYER (the previous behavior):
    #   1. CORRECTNESS. Choosing CCA or RPCA for an intensity-native route runs
    #      an NA→0 prep on s$seu_int before anchor finding, and that fill is
    #      never undone. Reading the data layer therefore tested a zero-filled
    #      matrix — with not-detected recorded as a measured zero — which is
    #      exactly what the NA-aware route exists to prevent. The old guard
    #      (`!anyNA(m) && all(m==0)`) could not catch it: `&&` binds tighter
    #      than `||`, so it only fired when the matrix was entirely zero.
    #   2. CONSISTENCY. The data layer holds the covariate-REGRESSED values,
    #      while ⑨ tests the un-regressed matrix and adjusts inside proDA/limma.
    #      The same contrast in the two tabs therefore gave different p-values.
    #      One-stage adjustment is the statistically preferable option (it keeps
    #      the degrees of freedom honest, where testing residuals understates
    #      uncertainty), so ⑨ was right and ⑫ was the deviation.
    # Cells are intersected with the integrated object's metadata, so integration
    # -derived clusters remain available as the grouping variable.
    if (norm_method %in% .NA_AWARE && na_method != "na_zero") {
      # Values from s$seu (the UNINTEGRATED object's data layer), grouping from
      # s$seu_int. s$seu_int's own data layer is unsafe: choosing CCA or RPCA runs
      # an NA -> 0 prep on it before anchor finding and never undoes it, so reading
      # it would test manufactured zeros. Integration corrects the embedding, not
      # the measurements.
      m <- .norm_mat(s$seu)
      if (is.null(m)) {
        showNotification(paste0("No NA-aware normalized data layer found. Re-run ⑥ with ",
                                "VSN or scp-median before testing integrated markers."),
                         type="error", duration=12); return() }
      md <- s$seu_int@meta.data
      grpby <- input$i_mk_grpby
      if (is.null(grpby) || !grpby %in% names(md)) {
        showNotification("Select a valid grouping variable.", type="error", duration=8); return() }
      cells <- intersect(colnames(m), rownames(md))
      m <- m[, cells, drop=FALSE]; md <- md[cells, , drop=FALSE]
      minpct    <- .num(input$i_mk_minpct, 0.1)
      # An interaction on a path that cannot use it would otherwise be silently
      # dropped, which looks identical to it having been applied.
      if (!is.null(.i_de_interact()) &&
          !((input$s_norm_method %||% "sct") %in% .NA_AWARE &&
            (input$i_mk_namethod %||% "proda") %in% c("proda","limma")))
        showNotification(paste0("Interaction with '", .i_de_interact(), "' is IGNORED by this ",
                                "test \u2014 it is implemented for the NA-aware proDA and limma ",
                                "engines only."), type="warning", duration=14)

      covs_cat  <- setdiff(intersect(input$i_mk_proda_cov      %||% character(0), names(md)), grpby)
      covs_cont <- setdiff(intersect(input$i_mk_proda_cov_cont %||% character(0), names(md)), grpby)
      if (na_method=="proda" && !requireNamespace("proDA", quietly=TRUE)) {
        showNotification("proDA not installed.", type="error", duration=10); return() }
      if (na_method=="limma" && !requireNamespace("limma", quietly=TRUE)) {
        showNotification("limma not installed.", type="error", duration=10); return() }

      # One contrast: 'this vs rest' factor -> results data.frame (Seurat columns)
      run_contrast <- function(is_k, cl_label) {
        n1 <- sum(is_k=="this"); n2 <- sum(is_k=="rest")
        if (n1 < 3 || n2 < 3) return(NULL)
        o1 <- rowSums(!is.na(m[, is_k=="this", drop=FALSE]))
        o2 <- rowSums(!is.na(m[, is_k=="rest", drop=FALSE]))
        p1 <- o1/max(n1,1); p2 <- o2/max(n2,1)
        kf <- (p1>=minpct)|(p2>=minpct)
        mk_k <- m[kf,,drop=FALSE]; p1k<-p1[kf]; p2k<-p2[kf]; o1k<-o1[kf]; o2k<-o2[kf]
        if (nrow(mk_k) < 1) return(NULL)
        if (na_method=="proda") {
          keep_cat  <- covs_cat[vapply(covs_cat, function(cn) length(unique(md[[cn]][!is.na(md[[cn]])]))>=2, logical(1))]
          keep_cont <- covs_cont[vapply(covs_cont, function(cn){v<-suppressWarnings(as.numeric(as.character(md[[cn]]))); sum(!is.na(v))>=3 && stats::sd(v,na.rm=TRUE)>0}, logical(1))]
          .dd <- .de_design(data.frame(group=is_k, check.names=TRUE),
                            keep_cat, keep_cont, md, .de_spline_df(),
                            interact = .i_de_interact())
          dsn <- .dd$data; frm <- .dd$formula
          # The ⑨ Markers control governs both tabs; ⑫ has no separate widget.
          nsub <- suppressWarnings(as.integer(.num(input$s_mk_proda_nsub, 0)))
          nsub <- if (is.finite(nsub) && nsub >= 100) min(nsub, nrow(mk_k)) else nrow(mk_k)
          t0   <- Sys.time()
          fit <- tryCatch(proDA::proDA(as.matrix(mk_k), design=frm, col_data=dsn,
                                       n_subsample=nsub,
                                         # proDA prints its EM iterations when
                                         # verbose: the only way to see that a
                                         # long run is progressing rather than
                                         # stuck, since the Shiny progress bar
                                         # cannot advance inside one call.
                                         verbose=isTRUE(input$s_mk_proda_verbose),
                                       max_iter=as.integer(.num(input$s_mk_proda_maxit, 20)),
                                       epsilon=.num(input$s_mk_proda_eps, 0.001)),
                          error=function(e) NULL)
          if (is.null(fit)) return(NULL)
          s_log(sprintf("proDA (integrated) cluster %s: %d features, %.1f s", cl, nrow(mk_k),
                        as.numeric(difftime(Sys.time(), t0, units="secs"))))
          if (!is.null(.dd$interact)) {
            # Omnibus interaction: full vs additive model. An LRT has no single
            # effect size, so `diff` is left NA rather than filled with a number
            # that would be read as a log2 fold change.
            rr <- tryCatch(proDA::test_diff(fit, reduced_model=.dd$formula_reduced),
                           error=function(e) NULL)
            if (is.null(rr)) return(NULL)
            if (!"diff" %in% names(rr)) rr$diff <- NA_real_
          } else {
            cn2 <- tryCatch(grep("^group", colnames(proDA::design(fit)), value=TRUE)[1], error=function(e) "groupthis")
            if (is.na(cn2)) cn2 <- "groupthis"
            rr <- tryCatch(proDA::test_diff(fit, contrast=cn2), error=function(e) NULL)
            if (is.null(rr)) return(NULL)
          }
          .lpk <- .proda_log_p(rr)
          data.frame(gene=rr$name, avg_log2FC=rr$diff, p_val=rr$pval, p_val_adj=rr$adj_pval,
                     neg_log10_p=-.lpk/log(10),
                     neg_log10_p_adj=-.bh_log(.lpk)/log(10),
                     pct.1=round(p1k[match(rr$name, rownames(mk_k))],3),
                     pct.2=round(p2k[match(rr$name, rownames(mk_k))],3), cluster=cl_label,
                     n_obs.1=o1k[match(rr$name, names(o1k))], n_obs.2=o2k[match(rr$name, names(o2k))],
                     stringsAsFactors=FALSE)
        } else if (na_method=="limma") {
          keep_cat  <- covs_cat[vapply(covs_cat, function(cn) length(unique(md[[cn]][!is.na(md[[cn]])]))>=2, logical(1))]
          keep_cont <- covs_cont[vapply(covs_cont, function(cn){v<-suppressWarnings(as.numeric(as.character(md[[cn]]))); sum(!is.na(v))>=3 && stats::sd(v,na.rm=TRUE)>0}, logical(1))]
          .dd <- .de_design(data.frame(group=is_k, check.names=TRUE),
                            keep_cat, keep_cont, md, .de_spline_df(),
                            interact = .i_de_interact())
          dd <- .dd$data; frm <- .dd$formula
          design <- stats::model.matrix(frm, data=dd)
          if (!is.null(.dd$interact)) {
            ci <- grep(paste0("^group.*:", .dd$interact, "|^", .dd$interact, ".*:group"),
                       colnames(design))
            if (!length(ci)) ci <- grep(":", colnames(design), fixed=TRUE)
            if (!length(ci)) return(NULL)
          } else {
            ci <- grep("^group", colnames(design))[1]; if (is.na(ci)) ci <- 2
          }
          fit <- tryCatch(limma::eBayes(limma::lmFit(as.matrix(mk_k), design)), error=function(e) NULL)
          if (is.null(fit)) return(NULL)
          tt <- limma::topTable(fit, coef=ci, number=Inf, sort.by="none")
          if (!"logFC" %in% names(tt)) {
            # Multi-coefficient F-test: report the largest interaction coefficient
            # so the volcano has an axis. NOT a fold change.
            cfm <- as.matrix(fit$coefficients[rownames(tt), ci, drop=FALSE])
            tt$logFC <- apply(cfm, 1, function(z) z[which.max(abs(z))])
          }
          data.frame(gene=rownames(tt), avg_log2FC=tt$logFC, p_val=tt$P.Value, p_val_adj=tt$adj.P.Val,
                     pct.1=round(p1k[match(rownames(tt), rownames(mk_k))],3),
                     pct.2=round(p2k[match(rownames(tt), rownames(mk_k))],3), cluster=cl_label,
                     n_obs.1=o1k[match(rownames(tt), names(o1k))], n_obs.2=o2k[match(rownames(tt), names(o2k))],
                     stringsAsFactors=FALSE)
        } else {  # ccwilcox
          x1 <- mk_k[, is_k=="this", drop=FALSE]; x2 <- mk_k[, is_k=="rest", drop=FALSE]
          rr <- do.call(rbind, lapply(seq_len(nrow(mk_k)), function(i){
            a<-x1[i,]; b<-x2[i,]; a<-a[!is.na(a)]; b<-b[!is.na(b)]
            if(length(a)<3||length(b)<3) return(c(diff=NA,p=NA))
            c(diff=median(a)-median(b), p=tryCatch(stats::wilcox.test(a,b)$p.value, error=function(e) NA))
          }))
          out <- data.frame(gene=rownames(mk_k), avg_log2FC=rr[,"diff"], p_val=rr[,"p"],
                            p_val_adj=p.adjust(rr[,"p"], method="BH"),
                            pct.1=round(p1k,3), pct.2=round(p2k,3), cluster=cl_label,
                            n_obs.1=o1k, n_obs.2=o2k, stringsAsFactors=FALSE)
          out[!is.na(out$p_val), ]
        }
      }

      withProgress(message=paste0("Integrated NA-aware markers (", toupper(na_method), ")..."), value=0.2, {
        if (input$i_mk_mode == "all") {
          grp_all <- as.character(md[[grpby]])
          clusters <- sort(unique(grp_all[!is.na(grp_all)]))
          if (length(clusters) < 2) { showNotification("Need ≥2 groups.", type="error", duration=8); return() }
          all_res <- list()
          for (k in seq_along(clusters)) {
            incProgress(1/length(clusters), detail=paste0("cluster ", clusters[k]))
            is_k <- factor(ifelse(grp_all==clusters[k], "this", "rest"), levels=c("rest","this"))
            rk <- run_contrast(is_k, clusters[k])
            if (!is.null(rk) && nrow(rk)) all_res[[as.character(clusters[k])]] <- rk
          }
          mk <- if (length(all_res)) do.call(rbind, all_res) else NULL
        } else {
          id1 <- input$i_mk_id1; id2 <- input$i_mk_id2
          grp <- as.character(md[[grpby]])
          keep <- grp %in% c(id1, id2)
          m  <<- m[, keep, drop=FALSE]   # restrict to the two groups for this contrast
          is_k <- factor(ifelse(grp[keep]==id1, "this", "rest"), levels=c("rest","this"))
          md <<- md[keep, , drop=FALSE]
          mk <- run_contrast(is_k, paste0(id1, " vs ", id2))
        }
        if (is.null(mk) || !nrow(mk)) { showNotification("No markers produced.", type="warning", duration=8); return() }
        if (!is.null(input$i_mk_logfc)) mk <- mk[abs(mk$avg_log2FC) >= input$i_mk_logfc | is.na(mk$avg_log2FC), ]
        if (isTRUE(input$i_mk_posonly)) mk <- mk[!is.na(mk$avg_log2FC) & mk$avg_log2FC > 0, ]
        mk <- mk[order(mk$cluster, mk$p_val_adj), ]
        s$int_markers <- mk
        s$last_i_mk_comp <- if (input$i_mk_mode=="all")
          paste0("one-vs-rest (", toupper(na_method), ")")
        else paste0(input$i_mk_id1, " vs ", input$i_mk_id2, " (", toupper(na_method), ")")
      })
      showNotification(paste0(nrow(s$int_markers), " integrated marker results (",
                              toupper(na_method), ")."), type="message", duration=5)
      return()
    }

    withProgress(message="Finding integrated markers...", value=0, {
      seu <- s$seu_int

      # Choose the assay to test on: SCT if present (SCT integration path),
      # otherwise the base assay (LogNormalize / VSN / scp-median integration).
      assay_int <- if ("SCT" %in% names(seu@assays)) "SCT" else
                   if (input$s_assay %in% names(seu@assays)) input$s_assay else
                   Seurat::DefaultAssay(seu)
      if (!(assay_int %in% names(seu@assays))) {
        showNotification(paste0("Assay '", assay_int, "' not found on the integrated object."),
                         type="error", duration=10); return()
      }
      Seurat::DefaultAssay(seu) <- assay_int
      Seurat::Idents(seu) <- input$i_mk_grpby

      # In Seurat v5, the base assay may still be split into per-group layers
      # after integration — join them so FindMarkers sees a single data layer.
      if (assay_int != "SCT") {
        tryCatch({
          join_fn <- if (existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                     else if (requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                     else get("JoinLayers")
          seu[[assay_int]] <- join_fn(seu[[assay_int]])
        }, error=function(e) NULL)
      }

      # NA→0 substitution (user-chosen escape hatch) for VSN/scpmed integrated data
      if (norm_method %in% .NA_AWARE && na_method == "na_zero") {
        dl <- tryCatch(as.matrix(SeuratObject::LayerData(seu@assays[[assay_int]], layer="data")),
                       error=function(e) NULL)
        if (!is.null(dl) && anyNA(dl)) {
          dl[is.na(dl)] <- 0
          tryCatch(SeuratObject::LayerData(seu@assays[[assay_int]], layer="data") <- dl,
                   error=function(e) NULL)
          s_log("Integrated markers: NA→0 substitution applied to data layer (user-selected).")
        }
      }

      # PrepSCTFindMarkers only applies to the SCT path. Integration is the case
      # that most often yields several SCT models, so this matters more here.
      if (assay_int == "SCT") {
        incProgress(0.2, detail="PrepSCTFindMarkers (SCT assay)")
        n_models <- tryCatch(length(slot(seu@assays[[assay_int]], "SCTModel.list")),
                             error=function(e) NA_integer_)
        prepped <- FALSE
        tryCatch({
          seu <- Seurat::PrepSCTFindMarkers(seu, verbose=FALSE)
          prepped <- TRUE
          s_log(paste0("Integrated PrepSCTFindMarkers complete",
                       if (is.finite(n_models)) paste0(" (", n_models, " SCT model(s))") else ""))
        }, error=function(e) s_log(paste0("Integrated PrepSCTFindMarkers FAILED: ",
                                          conditionMessage(e))))
        if (!prepped) {
          multi <- is.finite(n_models) && n_models > 1
          showNotification(
            paste0("PrepSCTFindMarkers failed",
                   if (multi) paste0(" and the integrated object holds ", n_models,
                                     " SCT models. FindMarkers will stop with an ",
                                     "'unequal library sizes' error rather than use ",
                                     "uncorrected counts. Re-run integration, or test on the ",
                                     "RNA assay instead.")
                   else ". Fold-changes will be uncorrected for sequencing depth."),
            type=if (multi) "error" else "warning", duration=16)
        }
      }

      incProgress(0.5, detail=paste0("FindMarkers (", assay_int, " assay)"))
      use_recorrect <- assay_int == "SCT"
      lat <- if (input$i_mk_test %in% c("LR","MAST","negbinom","poisson"))
               intersect(unique(c(input$i_mk_latent, input$i_mk_latent_num)) %||% character(0),
                                                              names(seu@meta.data)) else NULL
      if (!is.null(lat) && length(lat)==0) lat <- NULL
      mk <- if (input$i_mk_mode=="all") {
        Seurat::FindAllMarkers(seu, assay=assay_int, test.use=input$i_mk_test,
                               logfc.threshold=input$i_mk_logfc, min.pct=input$i_mk_minpct,
                               only.pos=input$i_mk_posonly, verbose=FALSE,
                               latent.vars=lat, recorrect_umi=use_recorrect)
      } else {
        m <- Seurat::FindMarkers(seu, assay=assay_int, ident.1=input$i_mk_id1, ident.2=input$i_mk_id2,
                                  test.use=input$i_mk_test, logfc.threshold=input$i_mk_logfc,
                                  min.pct=input$i_mk_minpct, only.pos=input$i_mk_posonly,
                                  verbose=FALSE, latent.vars=lat, recorrect_umi=use_recorrect)
        m$gene <- rownames(m); m$cluster <- paste0(input$i_mk_id1," vs ",input$i_mk_id2); m
      }
      s$int_markers     <- mk
      s$last_i_mk_comp  <- if(input$i_mk_mode=="all")
        paste0("All clusters (",length(unique(Seurat::Idents(seu)))," groups)")
      else paste0(input$i_mk_id1,"  vs  ",input$i_mk_id2)
      s_log(paste0("Integrated markers: ",nrow(mk)," results (",assay_int,") — ",s$last_i_mk_comp))
    })
    showNotification(paste0(nrow(s$int_markers)," integrated marker results."),type="message",duration=4)
  })

  output$i_mk_tbl <- renderDT({ req(s$int_markers); fmt_markers_dt(s$int_markers) })
  output$i_mk_dl_ui <- renderUI({ req(s$int_markers); downloadButton("i_mk_dl_now","⬇ Download Results",class="btn-success") })
  output$i_mk_dl_now <- downloadHandler(
    filename=function() paste0("integrated_markers_",Sys.Date(),".csv"),
    content=function(file) readr::write_csv(s$int_markers, file)
  )

  # ── Integrated markers volcano UI helpers ─────────────────────────────────
  output$i_vol_cluster_ui <- renderUI({
    req(s$int_markers)
    if (input$i_mk_mode == "all") {
      # In FindAllMarkers mode each cluster was compared vs all others
      # Let user pick which cluster to highlight in the volcano
      clusters <- sort(unique(as.character(s$int_markers$cluster)))
      tagList(
        tags$b("Highlight cluster:", style="font-size:12px;"),
        selectInput("i_vol_cluster","",
                    choices=c("All clusters (overlay)"="all", clusters),
                    selected="all")
      )
    } else {
      # Two-group mode — comparison is fixed
      tags$p(tags$small(paste0("Comparison: ", s$last_i_mk_comp %||% "")),
             style="color:#2980B9;font-weight:600;font-size:12px;margin-top:8px;")
    }
  })

  output$i_vol_label_ui <- renderUI({
    req(s$int_markers)
    vh <- function(x,d) if(!is.null(x) && grepl("^#[0-9A-Fa-f]{6}$",x)) x else d
    uc <- vh(input$i_vol_up_col,"#E74C3C"); dc <- vh(input$i_vol_down_col,"#2E86C1")
    if (input$i_mk_mode == "two") {
      comp <- s$last_i_mk_comp %||% "Group A vs Group B"
      parts <- strsplit(comp, "  vs  ")[[1]]
      grp_a <- if(length(parts)==2) trimws(parts[1]) else "Group A"
      grp_b <- if(length(parts)==2) trimws(parts[2]) else "Group B"
      tagList(
        tags$p(tags$span("●", style=paste0("color:",uc,";")), tags$b(paste0(" Up in ", grp_a)),
               style="font-size:12px;margin:4px 0;"),
        tags$p(tags$span("●", style=paste0("color:",dc,";")), tags$b(paste0(" Up in ", grp_b)),
               style="font-size:12px;margin:4px 0;")
      )
    } else {
      sel <- input$i_vol_cluster %||% "all"
      if (sel == "all") {
        tags$p(tags$small("Showing all cluster comparisons. Select a cluster to focus."),
               style="color:grey;font-size:11px;margin-top:8px;")
      } else {
        tagList(
          tags$p(tags$span("●", style=paste0("color:",uc,";")),
                 tags$b(paste0(" Up in Cluster ", sel, " vs all others")),
                 style="font-size:12px;margin:4px 0;"),
          tags$p(tags$span("●", style=paste0("color:",dc,";")),
                 tags$b(paste0(" Down in Cluster ", sel, " vs all others")),
                 style="font-size:12px;margin:4px 0;")
        )
      }
    }
  })

  observeEvent(s$int_markers, {
    ch <- .vol_pick_choices(s$int_markers)
    updateSelectizeInput(session, "i_vol_pick", choices=ch,
                         selected=intersect(input$i_vol_pick, ch), server=TRUE)
  }, ignoreNULL=FALSE)

  output$i_mk_volcano <- renderPlotly({
    req(s$int_markers); mk <- s$int_markers
    is_roc <- .mk_is_roc(mk)
    fc_col <- if("avg_log2FC" %in% names(mk)) "avg_log2FC"
              else if("avg_diff" %in% names(mk)) "avg_diff"
              else names(mk)[grep("log2fc|logfc", names(mk), ignore.case=TRUE)[1]]
    if (is_roc) { padj_col <- "power"; pval_col <- "power" }
    else {
      padj_col <- if("p_val_adj" %in% names(mk)) "p_val_adj" else "p_val"
      pval_col <- if("p_val"     %in% names(mk)) "p_val"     else padj_col
    }
    mk$FC    <- mk[[fc_col]]
    mk$PADJ  <- mk[[padj_col]]
    mk$PVAL  <- mk[[pval_col]]
    mk$Gene  <- if("gene" %in% names(mk)) mk$gene else rownames(mk)
    mk$Cluster <- if("cluster" %in% names(mk)) as.character(mk$cluster) else "?"

    fc_t <- .num(input$i_vol_fc, 0.5)
    p_t  <- if (is_roc) (.num(input$i_vol_p, 0.4)) else (.num(input$i_vol_p, 0.05))

    fc_cap <- suppressWarnings(as.numeric(.num(input$i_vol_cap, 0)))
    n_capped <- 0L
    if (length(fc_cap) == 1 && is.finite(fc_cap) && fc_cap > 0) {
      n_capped <- sum(abs(mk$FC) > fc_cap, na.rm=TRUE)
      mk <- mk[is.na(mk$FC) | abs(mk$FC) <= fc_cap, , drop=FALSE]
    }
    sel  <- input$i_vol_cluster %||% "all"

    if (input$i_mk_mode == "all" && sel != "all") {
      # Filter to selected cluster only
      mk_plot <- mk[mk$Cluster == sel, ]
      grp_a <- paste0("Cluster ", sel)
      grp_b <- "all others"
    } else {
      mk_plot <- mk
      if (input$i_mk_mode == "two") {
        comp   <- s$last_i_mk_comp %||% "A vs B"
        parts  <- strsplit(comp, "  vs  ")[[1]]
        grp_a  <- if(length(parts)==2) trimws(parts[1]) else "Group A"
        grp_b  <- if(length(parts)==2) trimws(parts[2]) else "Group B"
      } else {
        grp_a <- "cluster (positive FC)"
        grp_b <- "all others (negative FC)"
      }
    }

    sig_ok <- if (is_roc) mk_plot$PADJ >= p_t else mk_plot$PADJ <= p_t
    mk_plot$Dir <- dplyr::case_when(
      abs(mk_plot$FC) >= fc_t & sig_ok & mk_plot$FC > 0 ~ "Up",
      abs(mk_plot$FC) >= fc_t & sig_ok & mk_plot$FC < 0 ~ "Down",
      TRUE ~ "NS"
    )

    n_up   <- sum(mk_plot$Dir == "Up",   na.rm=TRUE)
    n_down <- sum(mk_plot$Dir == "Down", na.rm=TRUE)

    # user-selectable up/down colors + top-N labelling (match ⑨ Markers volcano)
    valid_hex <- function(x, d) if(!is.null(x) && grepl("^#[0-9A-Fa-f]{6}$", x)) x else d
    up_col   <- valid_hex(input$i_vol_up_col,   "#E74C3C")
    down_col <- valid_hex(input$i_vol_down_col, "#2E86C1")
    vol_cols <- c("Up"=up_col, "Down"=down_col, "NS"="grey70")
    mk_plot$yval <- if (is_roc) mk_plot$PADJ else .vol_nlp(mk_plot)
    mk_plot$do_label <- .vol_label_rows(mk_plot, input$i_vol_label_mode %||% "pval",
                                        .num(input$i_vol_nlabel, 0), input$i_vol_pick)

    title_str <- if (input$i_mk_mode == "all" && sel != "all") {
      paste0("Cluster ", sel, " vs all others  |  ↑", n_up, " up  ↓", n_down, " down")
    } else if (input$i_mk_mode == "two") {
      paste0(grp_a, " vs ", grp_b, "  |  ↑", n_up, " up in ", grp_a, "  ↓", n_down, " up in ", grp_b)
    } else {
      paste0("All clusters  |  ", nrow(mk_plot), " proteins")
    }

    mk_plot$tooltip <- if (is_roc) paste0(
      mk_plot$Gene,
      if("cluster" %in% names(mk_plot)) paste0("<br>Cluster: ", mk_plot$Cluster) else "",
      "<br>avg_diff: ", round(mk_plot$FC, 3),
      "<br>power: ", round(mk_plot$PADJ, 3),
      if("myAUC" %in% names(mk_plot)) paste0("<br>myAUC: ", round(mk_plot$myAUC,3)) else ""
    ) else paste0(
      mk_plot$Gene,
      if("cluster" %in% names(mk_plot)) paste0("<br>Cluster: ", mk_plot$Cluster) else "",
      "<br>log2FC: ", round(mk_plot$FC, 3),
      "<br>p_val: ", formatC(mk_plot$PVAL, format="e", digits=2),
      "<br>p.adj: ", formatC(mk_plot$PADJ, format="e", digits=2)
    )

    ycol <- if (is_roc) "PADJ" else "yval"
    if (is_roc) {
      p <- ggplot(mk_plot, aes(x=FC, y=PADJ, text=tooltip)) +
        .vol_pt(size=2) +
        scale_fill_manual(values=vol_cols,
                           labels=c(paste0("Up in ", grp_a), paste0("Up in ", grp_b), "Not significant")) +
        geom_vline(xintercept=c(-fc_t, fc_t), linetype="dashed", color="grey40") +
        geom_hline(yintercept=p_t, linetype="dashed", color="grey40") +
        theme_classic(base_size=13) +
        labs(title=title_str, x=paste0("avg_diff  (positive = higher in ", grp_a, ")"),
             y="ROC power (|2·AUC − 1|)", fill="")
    } else {
      p <- ggplot(mk_plot, aes(x=FC, y=yval, text=tooltip)) +
        .vol_pt(size=2) +
        scale_fill_manual(values=vol_cols,
                           labels=c(paste0("Up in ", grp_a), paste0("Up in ", grp_b), "Not significant")) +
        geom_vline(xintercept=c(-fc_t, fc_t), linetype="dashed", color="grey40") +
        geom_hline(yintercept=-log10(p_t),    linetype="dashed", color="grey40") +
        theme_classic(base_size=13) +
        labs(title=title_str, x=paste0("avg_log2FC  (positive = higher in ", grp_a, ")"),
             y="-log10(p_val)", color="")
    }
    p <- p + { .vol_xlim("i_vol") }
    sub_txt <- .vol_subtitle(n_capped, input$i_vol_pick, mk_plot)
    if (!is.null(sub_txt)) p <- p + labs(subtitle=sub_txt)
    .vol_annotate(.vol_outline(ggplotly(p, tooltip="text")),
                  mk_plot[mk_plot$do_label, , drop=FALSE], "FC", ycol, "Gene")
  })

  output$i_mk_vln_ui <- renderUI({
    req(s$seu_int)
    all_feats <- .opt_clean(rownames(s$seu_int), "features")
    pre <- if(!is.null(s$int_markers) && "gene" %in% names(s$int_markers))
      head(.mk_order(s$int_markers)[,"gene"],6)
    else head(all_feats,6)
    tagList(
      selectizeInput("i_mk_vln_genes","Proteins:",choices=all_feats,multiple=TRUE,
                     selected=intersect(pre,all_feats),
                     options=list(maxItems=12,placeholder="Search proteins...")),
      numericInput("i_mk_vln_ncol","Columns:",value=3,min=1,max=6)
    )
  })
  # Returns s$seu_int with Idents set from the global identity selector
  i_seu_with_ident <- reactive({
    req(s$seu_int); seu <- s$seu_int
    if (!is.null(input$s_global_ident) && input$s_global_ident %in% names(seu@meta.data))
      Seurat::Idents(seu) <- input$s_global_ident
    seu
  })

  # Integrated violin builder, shared by the panel and the PDF export for the
  # same reasons as .build_mk_vln above.
  .build_i_mk_vln <- function(fs = NULL) {
    req(i_seu_with_ident(), input$i_mk_grpby, input$i_mk_vln_genes)
    seu_use  <- i_seu_with_ident()
    if (input$i_mk_grpby %in% names(seu_use@meta.data))
      Seurat::Idents(seu_use) <- input$i_mk_grpby
    # Order applied AFTER Idents is repointed at the grouping variable, or the
    # re-levelling would be overwritten by the assignment above.
    seu_use  <- .vln_apply_order(seu_use, input$i_mk_grpby, input$i_mk_vln_order)
    seu_ord  <- seu_use
    g        <- intersect(input$i_mk_vln_genes, rownames(seu_use)); req(length(g)>0)
    assay_use <- if("SCT" %in% names(seu_use@assays)) "SCT" else input$s_assay
    Seurat::DefaultAssay(seu_use) <- assay_use
    ncol_use <- .num(input$i_mk_vln_ncol, 3)
    pt_size  <- .num(input$i_vln_pt_size, 0.5)
    overlay  <- input$i_vln_overlay  %||% "box"
    pal      <- .pal_seu(seu_use, input$i_mk_grpby)
    # Same source switch and NA fill as the ⑨ violin, so the two tabs can be
    # compared. Previously this plot read the data layer with NAs left in place,
    # which VlnPlot renders as gaps with no indication that anything is missing.
    i_disp_src <- input$i_vln_src %||% "data"
    seu_use    <- .display_seu(seu_use, assay_use, src=i_disp_src, na_offset=-1)

    # Annotation from the INTEGRATED marker table, with the ⑫ mode and groups.
    i_mode  <- input$i_mk_mode %||% "all"
    i_sig   <- if (isTRUE(input$i_vln_sig))
                 .sig_table(s$int_markers, g, i_mode,
                            c(input$i_mk_id1, input$i_mk_id2)) else NULL

    if (identical(i_disp_src, "data_obs")) {
      # Same reason as ⑨: Seurat::VlnPlot errors on NA, so build it directly.
      p <- .vln_observed(seu_ord, g, input$i_mk_grpby, assay_use,
                         pal, pt_size, overlay, ncol_use,
                         sig = i_sig, mode = i_mode)
      p <- p + labs(caption = .disp_caption(i_disp_src, "excluded"))
      return(.vln_fs(p, fs))
    } else {
      p <- Seurat::VlnPlot(seu_use, features=g, assay=assay_use,
                           pt.size=pt_size, ncol=ncol_use,
                           cols=if(!is.null(pal)) pal else NULL)
      if (overlay == "box") {
        p <- p & ggplot2::geom_boxplot(width=0.15, outlier.shape=NA,
                                        fill="white", alpha=0.6, color="black")
      } else if (overlay == "median") {
        p <- p & ggplot2::stat_summary(fun=median, geom="crossbar",
                                        width=0.5, color="black", linewidth=0.6)
      }
      if (!is.null(i_sig) && nrow(i_sig)) {
        .m_disp <- tryCatch(as.matrix(SeuratObject::LayerData(
                     seu_use@assays[[assay_use]], layer="data")), error=function(e) NULL)
        .yr_of <- function(gene) {
          if (is.null(.m_disp) || !(gene %in% rownames(.m_disp))) return(c(NA_real_, NA_real_))
          suppressWarnings(range(.m_disp[gene, ], na.rm=TRUE))
        }
        p <- tryCatch({
          ann_one <- function(pp, gene) {
            yr <- .yr_of(gene)
            if (!all(is.finite(yr))) return(pp)
            pad <- max(diff(yr)*0.10, 1e-6)
            if (identical(i_mode, "two")) {
              lab <- i_sig$label[is.na(i_sig$group) & i_sig$gene == gene]
              if (!length(lab)) return(pp)
              pp + ggplot2::annotate("segment", x=1, xend=2,
                                     y=yr[2]+pad, yend=yr[2]+pad,
                                     linewidth=0.4, color="grey20") +
                   ggplot2::annotate("text", x=1.5, y=yr[2]+pad*1.45,
                                     label=lab[1], size=3.1, vjust=0, color="grey20") +
                   ggplot2::expand_limits(y=yr[2]+pad*2.6)
            } else {
              sub <- i_sig[!is.na(i_sig$group) & i_sig$gene == gene, , drop=FALSE]
              if (!nrow(sub)) return(pp)
              pp + ggplot2::annotate("text", x=sub$group, y=yr[2]+pad*0.55,
                                     label=sub$label, size=2.7, vjust=0, color="grey20") +
                   ggplot2::expand_limits(y=yr[2]+pad*2.2)
            }
          }
          if (length(g) == 1) ann_one(p, g[1])
          else { for (i in seq_along(g)) p[[i]] <- ann_one(p[[i]], g[i]); p }
        }, error=function(e) { s_log(paste0("⑫ p-value annotation skipped: ",
                                            conditionMessage(e))); p })
      }
      return(.vln_fs(.add_caption(p, .disp_caption(i_disp_src, "min_minus_1")), fs))
    }
  }

  output$i_mk_vln_order_ui <- renderUI({
    .vln_order_ui("i_mk_vln_order", tryCatch(i_seu_with_ident(), error=function(e) NULL),
                  input$i_mk_grpby)
  })

  output$i_mk_vln <- renderPlot({ print(.build_i_mk_vln(NULL)) })

  output$i_mk_feat_ui <- renderUI({
    req(s$seu_int)
    all_feats <- .opt_clean(rownames(s$seu_int), "features")
    pre <- if(!is.null(s$int_markers) && "gene" %in% names(s$int_markers))
      head(.mk_order(s$int_markers)[,"gene"],8)
    else head(all_feats,8)
    tagList(
      selectizeInput("i_mk_feat_genes","Proteins:",choices=all_feats,multiple=TRUE,
                     selected=intersect(pre,all_feats),
                     options=list(maxItems=16,placeholder="Search proteins...")),
      numericInput("i_mk_feat_ncol","Columns:",value=4,min=1,max=8)
    )
  })
  output$i_mk_feat <- renderPlot({
    req(i_seu_with_ident(), input$i_mk_feat_genes, "umap" %in% names(i_seu_with_ident()@reductions))
    seu_use <- i_seu_with_ident()
    g <- intersect(input$i_mk_feat_genes, rownames(seu_use)); req(length(g)>0)
    i_assay <- if("SCT" %in% names(seu_use@assays)) "SCT" else input$s_assay
    Seurat::DefaultAssay(seu_use) <- i_assay
    # Was reading the data layer with NAs left in place, which FeaturePlot draws
    # in default grey — indistinguishable from a genuinely low value. Fill at each
    # protein's minimum (display only) and state the source, matching \u2468.
    i_fp_src <- input$i_feat_src %||% "scale.data"
    # As on ⑨: not-detected lands at the bottom of the gradient either way.
    if (identical(i_fp_src, "data_obs")) i_fp_src <- "data"
    seu_use  <- .display_seu(seu_use, i_assay, src=i_fp_src, na_offset=0)
    .add_caption(
      Seurat::FeaturePlot(seu_use, features=g, reduction="umap", pt.size=1.5,
                          cols=c("grey90","#8E44AD"), ncol=.num(input$i_mk_feat_ncol, 4)),
      .disp_caption(i_fp_src, "min"))
  })

  output$i_dot <- renderPlot({
    req(i_seu_with_ident(), s$int_markers, input$i_mk_grpby, input$i_dot_n)
    seu_use <- i_seu_with_ident()
    # Group by the Integrated Markers tab's OWN identity selector (i_mk_grpby),
    # not the global ident — otherwise the dot plot stays on whatever the global
    # selector is (e.g. sex) even when this tab is set to seurat_clusters.
    if (input$i_mk_grpby %in% names(seu_use@meta.data))
      Seurat::Idents(seu_use) <- input$i_mk_grpby
    top <- .mk_top_per_cluster(s$int_markers, input$i_dot_n)
    top <- intersect(top, rownames(seu_use)); req(length(top)>0)
    assay_use <- if("SCT" %in% names(seu_use@assays)) "SCT" else input$s_assay
    Seurat::DefaultAssay(seu_use) <- assay_use
    # NOTE: this is Seurat's own DotPlot, so dot size is the fraction of cells
    # with a non-zero value and NAs are dropped from the mean — it is NOT the
    # NA-aware detection-rate dot plot used on the ⑨ Markers tab. The two look
    # alike and measure different things.
    i_dot_src <- input$i_dot_src %||% "data"
    method_i  <- (s$intensity_diag$method %||% input$s_norm_method) %||% "sct"

    if (method_i %in% .NA_AWARE) {
      # NA-aware dot plot, matching \u2468. Detection ALWAYS comes from the data
      # layer's NA pattern: scale.data has not-detected filled with 0, so every
      # entry there is non-missing and a size channel read from it would be 100%
      # everywhere \u2014 which is exactly what the previous version showed.
      m_det <- tryCatch(as.matrix(SeuratObject::LayerData(
                 seu_use@assays[[assay_use]], layer="data")), error=function(e) NULL)
      # As on \u2468: the dot plot never fills, so observed-only is the same picture.
      if (identical(i_dot_src, "data_obs")) i_dot_src <- "data"
      m_col <- if (identical(i_dot_src, "scale.data"))
                 tryCatch(as.matrix(SeuratObject::LayerData(
                   seu_use@assays[[assay_use]], layer="scale.data")), error=function(e) NULL)
               else m_det
      if (is.null(m_col)) m_col <- m_det
      validate(need(!is.null(m_det), "No data layer available for the dot plot."))

      md_i  <- seu_use@meta.data
      grpby <- input$i_mk_grpby
      cells <- intersect(colnames(m_det), rownames(md_i))
      feats <- intersect(top, rownames(m_det))
      validate(need(length(feats) > 0 && length(cells) > 0,
                    "None of the selected features are present in the matrix."))
      m_det <- m_det[feats, cells, drop=FALSE]
      m_col <- m_col[intersect(feats, rownames(m_col)), cells, drop=FALSE]
      grp   <- as.character(md_i[cells, grpby])
      lv    <- sort(unique(grp[!is.na(grp)]))

      df <- do.call(rbind, lapply(feats, function(g) {
        do.call(rbind, lapply(lv, function(cl) {
          sel <- grp == cl
          vd  <- m_det[g, sel]
          nn  <- sum(!is.na(vd))
          vc  <- if (g %in% rownames(m_col)) m_col[g, sel] else vd
          # Mean over cells detected in the DATA layer, so a scale.data color is
          # never dragged toward 0 by filled not-detected entries.
          ok  <- !is.na(vd)
          data.frame(feature=g, cluster=cl, n_obs=nn,
                     detect=if (length(vd)) nn/length(vd)*100 else 0,
                     mean_obs=if (any(ok)) mean(vc[ok], na.rm=TRUE) else NA_real_,
                     stringsAsFactors=FALSE)
        }))
      }))
      n_empty <- sum(df$n_obs == 0)
      dfp <- df[df$n_obs > 0, , drop=FALSE]
      validate(need(nrow(dfp) > 0, "No feature was detected in any group."))
      dfp$feature <- factor(dfp$feature, levels=feats)
      return(
        ggplot(dfp, aes(x=feature, y=cluster)) +
          geom_point(aes(size=detect, color=mean_obs)) +
          scale_size_continuous(range=c(0.4,7), limits=c(0,100), name="Detection %\n(non-NA)") +
          scale_color_gradient(low="grey85", high="#8E44AD", name="Mean of\nobserved") +
          theme_classic(base_size=13) +
          theme(axis.text.x=element_text(angle=45, hjust=1, size=9)) +
          labs(x="Features", y=grpby,
               title="Size = true detection rate  |  Color = mean of observed values",
               caption=paste0(.disp_caption(i_dot_src, "excluded"),
                              if (n_empty > 0)
                                paste0("; ", n_empty,
                                       " feature\u00d7group combinations omitted (0 cells detected)")
                              else ""))
      )
    }

    # Count-based routes: zeros were written at build, so Seurat's own DotPlot is
    # the right tool and its non-zero fraction is meaningful.
    Seurat::DotPlot(seu_use, features=top, assay=assay_use) +
      RotatedAxis() + theme(axis.text.x=element_text(angle=45,hjust=1,size=9)) +
      labs(caption = .disp_caption("data", "zero"))
  })

  # ── ⑩ Cell Cycle ────────────────────────────────────────────────────────────

  output$s_cc_assay_ui <- renderUI({
    req(s$seu)
    assays_avail <- names(s$seu@assays)
    selectInput("s_cc_assay","Assay:", choices=assays_avail,
                selected=if(input$s_assay %in% assays_avail) input$s_assay else assays_avail[1])
  })

  output$s_cc_gene_count_ui <- renderUI({
    gc <- s$cc_gene_counts
    if (is.null(gc)) return(NULL)
    # color-code coverage: green if a healthy fraction of the reference phase
    # genes were detected, amber if sparse (phase calls become unreliable).
    warn_s   <- gc$s_found   < 10
    warn_g2m <- gc$g2m_found < 10
    col_s   <- if (warn_s)   "#E67E22" else "#27AE60"
    col_g2m <- if (warn_g2m) "#E67E22" else "#27AE60"
    div(style="background:#f4f6f7;border:1px solid #d5dbdb;border-radius:4px;padding:8px;margin-top:8px;",
      tags$p(tags$b("Phase genes detected"),
             tags$span(paste0(" (assay: ", gc$assay, ")"), style="color:grey;font-weight:normal;"),
             style="margin:0 0 4px 0;font-size:12px;"),
      tags$p(tags$span("S phase: ", style="font-size:12px;"),
             tags$span(paste0(gc$s_found, " / ", gc$s_total),
                       style=paste0("color:",col_s,";font-weight:600;font-size:12px;")),
             style="margin:0;"),
      tags$p(tags$span("G2M phase: ", style="font-size:12px;"),
             tags$span(paste0(gc$g2m_found, " / ", gc$g2m_total),
                       style=paste0("color:",col_g2m,";font-weight:600;font-size:12px;")),
             style="margin:0;"),
      if (warn_s || warn_g2m)
        tags$p(tags$small("⚠ Few phase genes detected — phase assignments may be unreliable."),
               style="color:#E67E22;font-size:11px;margin:4px 0 0 0;"),
      tags$details(
        tags$summary(tags$small("Show detected genes"), style="cursor:pointer;color:#2980B9;font-size:11px;margin-top:4px;"),
        tags$p(tags$small(tags$b("S: "), paste(gc$s_genes, collapse=", ")), style="font-size:11px;margin:2px 0;"),
        tags$p(tags$small(tags$b("G2M: "), paste(gc$g2m_genes, collapse=", ")), style="font-size:11px;margin:2px 0;")
      )
    )
  })

  output$s_cc_split_col_ui <- renderUI({
    req(s$seu)
    cat_cols <- names(s$seu@meta.data)[sapply(s$seu@meta.data,
                 function(x) (is.factor(x)||is.character(x)) && length(unique(x))>=2)]
    cat_cols <- cat_cols[!cat_cols %in% c("Phase","orig.ident")]
    if (!length(cat_cols))
      return(tags$p("No categorical metadata columns found.",style="color:#E74C3C;font-size:12px;"))
    selectInput("s_cc_split_col","Split by:",choices=cat_cols)
  })

  output$s_cc_status_ui <- renderUI({
    scored    <- s$cc_scored
    diff_done <- s$cc_diff_done
    tags$div(style="margin-top:10px;font-size:12px;line-height:1.8;",
      tags$span(if(scored)"✓ Scored" else "○ Not scored",
        style=paste0("color:",if(scored)"#27AE60" else "#aaa",";display:block;")),
      tags$span(if(diff_done)"✓ Score_Diff calculated" else "○ Score difference not yet calculated",
        style=paste0("color:",if(diff_done)"#27AE60" else "#aaa",";display:block;"))
    )
  })

  # ── Score cells ──────────────────────────────────────────────────────────────
  observeEvent(input$s_cc_score_btn, {
    req(s$seu)
    withProgress(message="Running CellCycleScoring...", value=0.1, {
      tryCatch({
        seu       <- s$seu
        timing    <- input$s_cc_timing %||% "after"

        # Choose which layer/assay to score against
        if (timing == "before") {
          # Use raw counts layer in the base assay
          assay_use <- input$s_assay
          layer_use <- "counts"
        } else {
          # Use normalized data layer — prefer SCT if available
          assay_use <- if ("SCT" %in% names(seu@assays)) "SCT" else
                       (input$s_cc_assay %||% input$s_assay)
          layer_use <- "data"
        }

        # Verify chosen layer has non-zero content. Handle both sparse
        # (dgCMatrix, has @x) and dense (base matrix, VSN/scpmed) storage, and
        # treat NA as "no content" rather than erroring.
        layer_data <- tryCatch(
          SeuratObject::LayerData(seu@assays[[assay_use]], layer=layer_use),
          error=function(e) NULL)
        vals <- if (is.null(layer_data)) numeric(0)
                else if (methods::is(layer_data, "sparseMatrix")) layer_data@x
                else as.numeric(layer_data)
        vals <- vals[!is.na(vals)]
        if (is.null(layer_data) || length(vals) == 0 || all(vals == 0))
          stop("Layer '", layer_use, "' in assay '", assay_use,
               "' is empty or all zeros. ",
               if(timing=="after") "Run Normalization + PCA first (⑥)."
               else "Load data first.")

        s_genes   <- cc.genes$s.genes
        g2m_genes <- cc.genes$g2m.genes
        obj_feats <- rownames(seu[[assay_use]])

        # Case-insensitive gene matching: cc.genes are human symbols (upper),
        # data may be mouse-style (title case) — match on toupper() but keep the
        # object's REAL rownames. This only affects which features are selected.
        feat_upper <- toupper(obj_feats)
        s_present   <- obj_feats[feat_upper %in% toupper(s_genes)]
        g2m_present <- obj_feats[feat_upper %in% toupper(g2m_genes)]

        # Record how many (and which) phase genes were found in the data, so the
        # tab can report coverage (few genes found → unreliable phase calls).
        s$cc_gene_counts <- list(
          s_found     = length(s_present),   s_total   = length(s_genes),
          g2m_found   = length(g2m_present), g2m_total = length(g2m_genes),
          s_genes     = sort(s_present),
          g2m_genes   = sort(g2m_present),
          assay       = assay_use)

        if (length(s_present)==0 && length(g2m_present)==0)
          stop("No S or G2M phase genes found in assay '", assay_use,
               "' (checked case-insensitively). Your feature IDs may not be gene symbols.")

        # Coverage warning. AddModuleScore averages the found features against a
        # background bin, so with only a handful of phase proteins the score is
        # dominated by one or two measurements and Phase calls are close to noise.
        if (length(s_present) < 10 || length(g2m_present) < 10)
          showNotification(paste0("Thin cell-cycle coverage: ", length(s_present), "/",
                                  length(s_genes), " S and ", length(g2m_present), "/",
                                  length(g2m_genes), " G2M features found. Scores from this ",
                                  "few proteins are close to noise and Phase calls should not ",
                                  "be trusted or regressed on."),
                           type="warning", duration=14)
        s_log(paste0("Cell cycle scoring: assay=", assay_use, ", layer=", layer_use,
                     ", S=", length(s_present), "/", length(s_genes),
                     ", G2M=", length(g2m_present), "/", length(g2m_genes),
                     ", timing=", timing,
                     if ((input$s_norm_method %||% "sct") %in% .NA_AWARE &&
                         layer_use == "data")
                       " | NA filled at row min - 1 for scoring only" else ""))

        incProgress(0.3, detail=paste0("S: ",length(s_present),
                                       "  G2M: ",length(g2m_present),
                                       "  [assay=",assay_use,", layer=",layer_use,
                                       ", case-insensitive]"))

        # For VSN/scpmed the data layer contains NAs, which AddModuleScore (inside
        # CellCycleScoring) mishandles. Fill NAs with a per-protein left-censored
        # low value for the SCORING step only — the object's stored data layer is
        # left untouched for everything else.
        na_fill_needed <- (input$s_norm_method %||% "sct") %in% .NA_AWARE &&
                          layer_use == "data"

        # Helper: ensure the object passed to CellCycleScoring has a unified data layer
        prep_for_scoring <- function(obj) {
          tryCatch({
            join_fn <- if (existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                       else if (requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                       else get("JoinLayers")
            obj[[assay_use]] <- join_fn(obj[[assay_use]])
          }, error=function(e) NULL)
          obj
        }

        # Helper: score one object
        score_one <- function(obj) {
          obj <- prep_for_scoring(obj)
          # Build a guaranteed-2D dense data matrix on the chosen layer.
          dl <- tryCatch(as.matrix(SeuratObject::LayerData(obj@assays[[assay_use]], layer=layer_use)),
                         error=function(e) NULL)
          if (is.null(dl) || is.null(dim(dl)) || nrow(dl) < 2)
            stop("Data layer '", layer_use, "' is not a 2D matrix with >=2 features.")
          if (isTRUE(na_fill_needed) && anyNA(dl)) {
            rmin <- suppressWarnings(apply(dl, 1, function(r){ mn <- min(r, na.rm=TRUE); if(is.finite(mn)) mn else 0 }))
            na_idx <- which(is.na(dl), arr.ind=TRUE)
            if (nrow(na_idx) > 0) dl[na_idx] <- rmin[na_idx[,1]] - 1
            tryCatch(SeuratObject::LayerData(obj@assays[[assay_use]], layer=layer_use) <- dl,
                     error=function(e) NULL)
          }
          Seurat::DefaultAssay(obj) <- assay_use

          # Try Seurat's CellCycleScoring (uses AddModuleScore's control-gene
          # binning). Its layer/slot arg name varies across versions — try each.
          scored <- tryCatch(
            Seurat::CellCycleScoring(obj, s.features=s_present, g2m.features=g2m_present,
                                     assay=assay_use, layer=layer_use),
            error=function(e1) tryCatch(
              Seurat::CellCycleScoring(obj, s.features=s_present, g2m.features=g2m_present,
                                       assay=assay_use, slot=layer_use),
              error=function(e2) tryCatch(
                Seurat::CellCycleScoring(obj, s.features=s_present, g2m.features=g2m_present,
                                         assay=assay_use),
                error=function(e3) NULL)))

          # Fallback: AddModuleScore's control-gene binning collapses when few
          # cell-cycle genes are matched (common in proteomics) — giving
          # "'x' must be an array of at least two dimensions". If so, compute a
          # simple direct module score: mean expression of the phase genes per
          # cell (row-centered), and assign Phase by the larger score.
          if (is.null(scored)) {
            sg  <- intersect(s_present,   rownames(dl))
            g2g <- intersect(g2m_present, rownames(dl))
            zrow <- function(M){ mu <- rowMeans(M); sdv <- apply(M,1,stats::sd); sdv[!is.finite(sdv)|sdv==0] <- 1; (M-mu)/sdv }
            s_score   <- if (length(sg)  >= 1) colMeans(zrow(dl[sg,  , drop=FALSE]), na.rm=TRUE) else rep(0, ncol(dl))
            g2m_score <- if (length(g2g) >= 1) colMeans(zrow(dl[g2g, , drop=FALSE]), na.rm=TRUE) else rep(0, ncol(dl))
            phase <- ifelse(s_score < 0 & g2m_score < 0, "G1",
                            ifelse(g2m_score > s_score, "G2M", "S"))
            obj$S.Score   <- as.numeric(s_score)[match(colnames(obj), colnames(dl))]
            obj$G2M.Score <- as.numeric(g2m_score)[match(colnames(obj), colnames(dl))]
            obj$Phase     <- factor(phase[match(colnames(obj), colnames(dl))], levels=c("G1","S","G2M"))
            scored <- obj
            s_log("CellCycleScoring: used direct module-score fallback (few phase genes for AddModuleScore binning).")
          }
          scored
        }

        if (input$s_cc_split == "split") {
          req(input$s_cc_split_col)
          split_col  <- input$s_cc_split_col
          conditions <- unique(na.omit(seu@meta.data[[split_col]]))
          score_cols <- c("S.Score","G2M.Score","Phase")
          # Initialise columns so they always exist in full metadata even if
          # a condition subset fails
          for (col in score_cols) {
            if (!col %in% names(seu@meta.data))
              seu@meta.data[[col]] <- NA
          }
          for (cond in conditions) {
            incProgress(0.4/length(conditions), detail=paste("Scoring condition:", cond))
            idx  <- which(seu@meta.data[[split_col]] == cond)
            sub  <- tryCatch(score_one(seu[, idx]), error=function(e) {
              showNotification(paste0("Scoring failed for condition '",cond,"': ",
                                      conditionMessage(e)), type="warning", duration=6)
              NULL
            })
            if (!is.null(sub)) {
              for (col in score_cols)
                seu@meta.data[idx, col] <- sub@meta.data[colnames(seu)[idx], col]
            }
          }
        } else {
          incProgress(0.4, detail="Scoring all cells...")
          scored <- score_one(seu)
          # Copy back only the score columns — never the (possibly NA-filled)
          # data layer, so the clean NA-aware matrix is preserved for testing.
          for (col in c("S.Score","G2M.Score","Phase"))
            seu@meta.data[[col]] <- scored@meta.data[colnames(seu), col]
        }

        # Always write scores back to the main s$seu object
        # (never leave them only on a temporary subset)
        s$seu       <- seu
        s$cc_scored <- TRUE
        timing_note <- if(timing=="before") "raw counts" else paste0(assay_use,"/",layer_use)
        s_log(paste0("CellCycleScoring done [", timing_note, ", mode=", input$s_cc_split,
                     if(input$s_cc_split=="split" && !is.null(input$s_cc_split_col))
                       paste0(", split.col=", input$s_cc_split_col) else "",
                     "]. S genes used: ", length(s_present),
                     " | G2M genes used: ", length(g2m_present),
                     " | assay=", assay_use, " | layer=", layer_use))
        showNotification(
          paste0("Scoring complete [",timing_note,"]. S: ",length(s_present),
                 "  G2M: ",length(g2m_present)),
          type="message", duration=5)

      }, error=function(e) {
        showNotification(paste0("CellCycleScoring error: ",conditionMessage(e)),
                         type="error", duration=10)
      })
    })
  })

  # ── Calculate Score_Diff (G2M − S) ──────────────────────────────────────────
  observeEvent(input$s_cc_diff_btn, {
    req(s$seu)
    if (!all(c("S.Score","G2M.Score") %in% names(s$seu@meta.data)))
      return(showNotification("Run CellCycleScoring first (① Score Cells).",
                              type="warning", duration=5))
    # G2M − S: positive = G2M dominant, negative = S dominant (Seurat CC.Difference)
    s$seu$Score_Diff  <- s$seu$G2M.Score - s$seu$S.Score
    s$cc_diff_done    <- TRUE
    s_log("Score_Diff (G2M−S) added to metadata.")
    showNotification("Score_Diff added to metadata.", type="message", duration=4)
  })

  # ── DimPlot by Phase ─────────────────────────────────────────────────────────
  output$s_cc_dimplot <- renderPlot({
    req(s$seu, s$cc_scored)
    seu <- s$seu
    if (!"Phase" %in% names(seu@meta.data)) {
      return(plot(0, type="n", axes=FALSE, xlab="", ylab="",
        main="Phase not found in metadata.\nRun ① Score Cells first."))
    }
    red <- input$s_cc_dimred %||% "umap"
    if (!red %in% names(seu@reductions)) {
      avail <- names(seu@reductions)
      if (!length(avail)) return(plot(0,type="n",axes=FALSE,xlab="",ylab="",
        main="No reductions found.\nRun ⑥ Normalization + PCA and ⑦ Embeddings first."))
      red <- avail[1]
    }
    Seurat::DimPlot(seu, reduction=red, group.by="Phase",
                    cols=c("G1"="#95A5A6","S"="#3498DB","G2M"="#E74C3C")) +
      ggplot2::ggtitle(paste0("Cell Cycle Phase — ", toupper(red))) +
      ggplot2::theme_classic(base_size=13)
  })

  # ── Ridge plot ───────────────────────────────────────────────────────────────
  output$s_cc_ridge_feat_ui <- renderUI({
    req(s$seu, s$cc_scored)
    cc_feats <- intersect(c(cc.genes$s.genes, cc.genes$g2m.genes),
                          .opt_clean(rownames(s$seu), "features"))
    meta_cc  <- intersect(c("S.Score","G2M.Score","Score_Diff"),
                          names(s$seu@meta.data))
    cat_cols <- names(s$seu@meta.data)[sapply(s$seu@meta.data,
                 function(x) (is.factor(x)||is.character(x)) && length(unique(x))>=2)]
    cat_cols <- cat_cols[!cat_cols %in% "orig.ident"]
    def_split <- if("Condition" %in% cat_cols) "Condition" else
                 if("Phase" %in% cat_cols) "Phase" else cat_cols[1]
    tagList(
      fluidRow(
        column(8, selectizeInput("s_cc_ridge_feats","Features:",
                     choices=c(meta_cc, cc_feats),
                     selected=head(c(meta_cc, cc_feats), 4),
                     multiple=TRUE, options=list(maxItems=8))),
        column(4, selectInput("s_cc_ridge_splitby","Split / color by:",
                     choices=c("Phase"="Phase", cat_cols),
                     selected=def_split))
      )
    )
  })

  # NOTE ON WHAT CELL-CYCLE PLOTS SHOW: S.Score / G2M.Score / Phase were computed
  # by CellCycleScoring, which calls AddModuleScore internally. AddModuleScore
  # cannot handle NAs, so on the VSN / scp-median routes the scoring copy had
  # not-detected values FILLED at each protein's minimum − 1. The scores are
  # therefore partly built from fill values for cells that detected few
  # cycle proteins, which makes S.Score correlate with detection depth in sparse
  # data. Check cor(S.Score, nFeature_raw) before using a score as a covariate,
  # or the same effect is removed twice under two names.
  output$s_cc_ridge <- renderPlot({
    req(s$seu, s$cc_scored, input$s_cc_ridge_feats)
    seu       <- s$seu
    feats     <- input$s_cc_ridge_feats
    split_by  <- input$s_cc_ridge_splitby %||% "Phase"
    assay_use <- if("SCT" %in% names(seu@assays)) "SCT" else
                 (input$s_cc_assay %||% input$s_assay)

    # Validate split_by exists in metadata
    if (!split_by %in% names(seu@meta.data))
      return(plot(0,type="n",axes=FALSE,xlab="",ylab="",
                  main=paste0("'",split_by,"' not found in metadata.")))

    meta_score_feats <- intersect(feats,
                          c("S.Score","G2M.Score","Score_Diff"))
    assay_feats      <- setdiff(feats, meta_score_feats)

    # Validate meta score features actually exist
    meta_score_feats <- intersect(meta_score_feats, names(seu@meta.data))

    plot_list <- list()

    # ── Assay features via Seurat RidgePlot ─────────────────────────────────
    if (length(assay_feats) > 0) {
      assay_feats_ok <- intersect(assay_feats, rownames(seu[[assay_use]]))
      if (length(assay_feats_ok) > 0) {
        tryCatch({
          rp <- Seurat::RidgePlot(seu, features=assay_feats_ok, ncol=2,
                                  group.by=split_by, assay=assay_use,
                                  combine=FALSE)
          # combine=FALSE returns a plain list of ggplot objects — no patchwork issues
          for (p in rp) plot_list[[length(plot_list)+1]] <- p
        }, error=function(e) NULL)
      }
    }

    # ── Metadata score features via ggridges ────────────────────────────────
    if (length(meta_score_feats) > 0) {
      grp_vals <- seu@meta.data[[split_by]]
      pal_grp  <- .pal_seu(seu, split_by)
      for (feat in meta_score_feats) {
        df_f <- data.frame(
          Value = as.numeric(seu@meta.data[[feat]]),
          Group = factor(grp_vals),
          stringsAsFactors = FALSE
        )
        df_f <- df_f[!is.na(df_f$Value) & !is.na(df_f$Group), ]
        if (nrow(df_f) == 0) next
        p <- ggplot2::ggplot(df_f,
               ggplot2::aes(x=Value, y=Group, fill=Group)) +
          ggridges::geom_density_ridges(alpha=0.7, scale=0.9,
                                        rel_min_height=0.01) +
          { if(!is.null(pal_grp)) ggplot2::scale_fill_manual(values=pal_grp) } +
          ggplot2::labs(title=feat, x=feat, y=split_by) +
          ggplot2::theme_classic(base_size=12) +
          ggplot2::theme(legend.position="none")
        plot_list[[length(plot_list)+1]] <- p
      }
    }

    if (length(plot_list) == 0)
      return(plot(0,type="n",axes=FALSE,xlab="",ylab="",
                  main="No valid features to plot.\nCheck feature selection and that Score_Diff has been calculated."))

    n_cols <- min(2, length(plot_list))
    patchwork::wrap_plots(plot_list, ncol=n_cols)
  })

  # ── Score_Diff boxplot by condition ──────────────────────────────────────────
  output$s_cc_diff_grp_ui <- renderUI({
    req(s$seu)
    cat_cols <- names(s$seu@meta.data)[sapply(s$seu@meta.data,
                 function(x) (is.factor(x)||is.character(x)) && length(unique(x))>=2)]
    cat_cols <- cat_cols[!cat_cols %in% c("Phase","orig.ident")]
    def_grp  <- if("Condition" %in% cat_cols) "Condition" else cat_cols[1]
    tagList(
      fluidRow(
        column(4, selectInput("s_cc_diff_grp","Group by:", choices=cat_cols, selected=def_grp)),
        column(4, selectInput("s_cc_diff_metric","Score metric:",
                              choices=c("G2M − S (Score_Diff)"="Score_Diff"),
                              selected="Score_Diff")),
        column(4, checkboxInput("s_cc_diff_notch","Notched boxes", value=TRUE))
      ),
      fluidRow(
        column(4, checkboxInput("s_cc_diff_jitter","Show points", value=TRUE)),
        column(4, radioButtons("s_cc_diff_plabel","P-value label:",
                               choices=c("Exact (p.format)"="p.format",
                                         "Significance stars"="p.signif"),
                               selected="p.format", inline=TRUE)),
        column(4, sliderInput("s_cc_diff_pt_size","Point size:",
                              min=0.1, max=3, value=0.5, step=0.1))
      )
    )
  })

  # Cell-cycle score-difference boxplot, shared by the panel and the PDF export.
  #
  # The export used to be a separate, reduced copy and was missing three things:
  #   1. the geom_jitter layer entirely, so "Show points" had no effect on the PDF
  #   2. the point-size control, for the same reason
  #   3. a usable comparison list, so the p-value brackets silently vanished
  # On (3) there were two independent causes, both of which drop the
  # stat_compare_means layer without any error:
  #   - comparisons were built from ALL levels rather than only those with at
  #     least two non-NA values, so wilcox.test errored on a 1-value group
  #   - combn() was called on `lvls` while it was still a FACTOR, which yields
  #     integer level CODES (1, 2, ...) instead of level names, and
  #     stat_compare_means cannot match those against the x axis
  # as.character() on the level set is what fixes the second.
  .build_cc_diff <- function(fs = 13) {
    if (is.null(s$seu)) stop("No object yet.", call.=FALSE)
    seu <- s$seu

    # Auto-compute Score_Diff if not yet calculated so the plot works
    # immediately after scoring without a separate button press
    if (!("Score_Diff" %in% names(seu@meta.data))) {
      if (!all(c("S.Score","G2M.Score") %in% names(seu@meta.data)))
        stop("Run ① Score Cells first.", call.=FALSE)
      seu$Score_Diff <- seu$G2M.Score - seu$S.Score
      s$seu$Score_Diff <- seu$Score_Diff
      s$cc_diff_done   <- TRUE
    }

    df     <- seu@meta.data
    grp    <- input$s_cc_diff_grp
    metric <- input$s_cc_diff_metric %||% "Score_Diff"
    if (is.null(grp) || !nzchar(grp))
      stop("Pick a grouping variable first.", call.=FALSE)
    if (!grp %in% names(df))
      stop("Column '", grp, "' not found in metadata.", call.=FALSE)
    if (!metric %in% names(df))
      stop(metric, " not found — click 'Calculate Score Differences'.", call.=FALSE)

    # as.character() throughout: a factor level set passed to combn() returns
    # integer codes, which stat_compare_means cannot map to the x axis.
    lvls <- as.character(sort(unique(stats::na.omit(df[[grp]]))))
    df[[grp]] <- factor(as.character(df[[grp]]), levels=lvls)
    valid_lvls <- lvls[vapply(lvls, function(L)
      sum(!is.na(df[[metric]][df[[grp]] == L])) >= 2, logical(1))]
    my_comparisons <- if (length(valid_lvls) >= 2)
      utils::combn(as.character(valid_lvls), 2, simplify=FALSE) else NULL

    pal      <- .pal_for(grp, lvls)
    show_pts <- isTRUE(input$s_cc_diff_jitter)
    pt_size  <- .num(input$s_cc_diff_pt_size, 0.5)
    plabel   <- input$s_cc_diff_plabel  %||% "p.format"
    y_label  <- "Score_Diff (G2M.Score − S.Score)"
    p_title  <- "G2M − S Score Difference by Condition"
    p_sub    <- if (is.null(my_comparisons))
      paste0("Wilcoxon test  |  dashed = 0  |  (need ", "≥", "2 groups with ",
             "≥", "2 values each for p-values)")
    else "Wilcoxon test  |  dashed = 0"

    ggplot2::ggplot(df, ggplot2::aes(x=.data[[grp]], y=.data[[metric]],
                                     fill=.data[[grp]])) +
      { if (show_pts)
          ggplot2::geom_jitter(ggplot2::aes(color=.data[[grp]]),
                               alpha=0.25, size=pt_size, width=0.2) } +
      ggplot2::geom_boxplot(alpha=0.7, width=0.45, color="black",
                            outlier.shape=NA,
                            notch=isTRUE(input$s_cc_diff_notch)) +
      ggplot2::geom_hline(yintercept=0, linetype="dashed", color="red", alpha=0.5) +
      { if(!is.null(pal)) ggplot2::scale_fill_manual(values=pal) } +
      { if(!is.null(pal)) ggplot2::scale_color_manual(values=pal) } +
      { if(!is.null(my_comparisons))
          ggpubr::stat_compare_means(comparisons=my_comparisons,
                                     method="wilcox.test", label=plabel) } +
      ggplot2::labs(title=p_title, subtitle=p_sub, x=grp, y=y_label) +
      ggplot2::theme_classic(base_size=fs) +
      ggplot2::theme(legend.position="none",
                     axis.text=ggplot2::element_text(size=fs*0.85, color="black"))
  }

  output$s_cc_diff_plot <- renderPlot({
    req(s$seu, s$cc_scored, input$s_cc_diff_grp)
    p <- tryCatch(.build_cc_diff(13), error=function(e) e)
    validate(need(!inherits(p, "error"),
                  if (inherits(p, "error")) conditionMessage(p) else ""))
    print(p)
  })

  # ── Phase proportions ────────────────────────────────────────────────────────
  output$s_cc_prop_grp_ui <- renderUI({
    req(s$seu)
    cat_cols <- names(s$seu@meta.data)[sapply(s$seu@meta.data,
                 function(x) (is.factor(x)||is.character(x)) && length(unique(x))>=2)]
    cat_cols <- cat_cols[!cat_cols %in% c("Phase","orig.ident")]
    selectInput("s_cc_prop_grp","Group by:", choices=cat_cols)
  })

  output$s_cc_prop_plot <- renderPlot({
    req(s$seu, s$cc_scored, input$s_cc_prop_grp)
    df  <- s$seu@meta.data
    grp <- input$s_cc_prop_grp
    req(grp %in% names(df), "Phase" %in% names(df))
    df_prop <- df %>%
      dplyr::group_by(.data[[grp]], Phase) %>%
      dplyr::summarise(n=dplyr::n(), .groups="drop") %>%
      dplyr::group_by(.data[[grp]]) %>%
      dplyr::mutate(pct=100*n/sum(n))
    ggplot2::ggplot(df_prop, ggplot2::aes(x=.data[[grp]], y=pct, fill=Phase)) +
      ggplot2::geom_bar(stat="identity", color="black", linewidth=0.3) +
      ggplot2::scale_fill_manual(values=c("G1"="#95A5A6","S"="#3498DB","G2M"="#E74C3C")) +
      ggplot2::labs(title="Cell Cycle Phase Proportions", x=grp, y="% of cells") +
      ggplot2::theme_classic(base_size=13)
  })

  # ── QC by Phase ──────────────────────────────────────────────────────────────
  output$s_cc_qc_feat_ui <- renderUI({
    req(s$seu, s$cc_scored)
    qc_cols <- intersect(
      c("nFeature_Protein","nCount_Protein","percent.mt","nFeature_RNA","nCount_RNA"),
      names(s$seu@meta.data))
    if (!length(qc_cols))
      qc_cols <- names(s$seu@meta.data)[sapply(s$seu@meta.data, is.numeric)][1:3]
    selectizeInput("s_cc_qc_feats","QC features:", choices=qc_cols,
                   selected=head(qc_cols,3), multiple=TRUE, options=list(maxItems=5))
  })

  output$s_cc_qc_plot <- renderPlot({
    req(s$seu, s$cc_scored, input$s_cc_qc_feats)
    assay_use <- if("SCT" %in% names(s$seu@assays)) "SCT" else
                 (input$s_cc_assay %||% input$s_assay)
    Seurat::VlnPlot(s$seu, features=input$s_cc_qc_feats,
                    group.by="Phase", assay=assay_use, pt.size=0.3,
                    ncol=length(input$s_cc_qc_feats),
                    cols=c("G1"="#95A5A6","S"="#3498DB","G2M"="#E74C3C")) &
      ggplot2::theme_classic(base_size=12)
  })

  # ── Scores table ─────────────────────────────────────────────────────────────
  output$s_cc_table <- DT::renderDT({
    req(s$seu, s$cc_scored)
    cols_want <- intersect(c("S.Score","G2M.Score","Phase","Score_Diff"),
                           names(s$seu@meta.data))
    df <- s$seu@meta.data[, cols_want, drop=FALSE]
    DT::datatable(df, options=list(pageLength=15, scrollX=TRUE), rownames=TRUE) %>%
      DT::formatRound(intersect(c("S.Score","G2M.Score","Score_Diff"), cols_want), 4)
  })

  # ── ⑪ Integration ───────────────────────────────────────────────────────────
  output$s_int_split_ui <- renderUI({
    cc <- s_cat_cols()
    if (!length(cc)) return(tags$p("Assign at least one Categorical covariate in ③ Covariates first.",
                                    style="color:#E74C3C;"))
    selectInput("s_int_split","Split object by:",choices=cc,selected=cc[1])
  })
  output$s_int_sct_list_status <- renderUI({
    # ── IntegrateLayers path (LogNormalize / VSN / scp-median / log2) ──────────
    # Readiness here is about the single main object, not a list of per-group
    # objects: it needs a pca (written by ⑥), and Step 1 splits its layers.
    if (s_int_uses_layers()) {
      assay_nm <- input$s_assay
      has_pca  <- !is.null(s$seu) && "pca" %in% names(s$seu@reductions)
      n_cells  <- if (!is.null(s$seu)) ncol(s$seu) else 0
      lays <- if (!is.null(s$seu_int) && assay_nm %in% names(s$seu_int@assays))
                tryCatch(SeuratObject::Layers(s$seu_int[[assay_nm]]),
                         error=function(e) character(0)) else character(0)
      n_split <- length(grep("^data\\.", lays))
      ok_col <- "#27AE60"; bad_col <- "#E74C3C"
      line <- function(ok, txt) tags$p(paste0(if (ok) "\u2713 " else "\u2717 ", txt),
        style=paste0("color:", if (ok) ok_col else bad_col, ";font-size:12px;margin:2px 0;"))
      tagList(
        tags$p(tags$b("Readiness:"), style="margin:4px 0 2px 0;font-size:12px;"),
        line(has_pca, if (has_pca)
               paste0("Main object has an NA-aware 'pca' (", n_cells, " cells)")
             else "Main object has no 'pca' \u2014 run \u2465 with integration mode OFF"),
        line(isTRUE(s$int_step1_done),
             if (isTRUE(s$int_step1_done))
               paste0("Step 1 done \u2014 layers split into ", max(n_split, 1), " group(s)")
             else "Step 1 not run yet"),
        tags$p(tags$small(
          "Per-group SCT objects are not used on this route, so none are listed. ",
          "If \u2465 was run with integration mode on, those per-group objects exist but ",
          "\u246a ignores them."),
          style="color:#7f8c8d;font-size:11px;margin:4px 0 0 0;")
      )
    } else if (is.null(s$sct_list) || length(s$sct_list) == 0) {
      return(tags$p("❌ No group objects found — complete Step 1 in ⑥ SCTransform first.",
                    style="color:#E74C3C;font-weight:600;font-size:12px;"))
    } else {
    grp_info <- sapply(names(s$sct_list), function(nm) {
      obj     <- s$sct_list[[nm]]
      has_sct <- "SCT" %in% names(obj@assays)
      has_pca <- "pca" %in% names(obj@reductions)
      n_var   <- if(has_sct) length(Seurat::VariableFeatures(obj)) else 0
      paste0(nm, ": ", if(has_sct&&has_pca) paste0("✓ SCT+PCA (",n_var," var features)")
                       else if(has_sct) "✓ SCT, ✗ PCA missing"
                       else "✗ not ready")
    })
    tagList(
      tags$p(tags$b("Step 1 status:"), style="margin:4px 0 2px 0;font-size:12px;"),
      lapply(grp_info, function(g)
        tags$p(g, style=paste0("color:",if(grepl("SCT\\+PCA",g))"#27AE60"else"#E74C3C",
                               ";font-size:12px;margin:2px 0;")))
    )
    }
  })


  # ── Integration tab plot outputs ────────────────────────────────────────────
  output$s_int_color_ui <- renderUI({
    req(s$seu_int)
    all_cols <- names(s$seu_int@meta.data); cc <- s_cat_cols()
    selectInput("s_int_color","Color by:",choices=all_cols,
                selected=if(length(cc)>0&&cc[1]%in%all_cols)cc[1] else all_cols[1])
  })

  # Group selector for the "UMAP — group" tab. Defaults to the split variable
  # used for integration (falls back to the first categorical metadata column).
  output$s_int_color2_ui <- renderUI({
    req(s$seu_int)
    all_cols <- names(s$seu_int@meta.data); cc <- s_cat_cols()
    split_v  <- input$s_int_ln_split
    def <- if (!is.null(split_v) && split_v %in% all_cols) split_v
           else if (length(cc)>0 && cc[1] %in% all_cols) cc[1]
           else all_cols[1]
    selectInput("s_int_color2","Group by:",choices=all_cols, selected=def)
  })

  output$s_int_elbow <- renderPlotly({
    req(s$seu_int)
    # Show elbow for whichever reduction is available — pca (after step 6) or integrated.cca
    reduc_use <- if (s_int_uses_layers() &&
                     "integrated.cca" %in% names(s$seu_int@reductions)) "integrated.cca"
                 else if("pca" %in% names(s$seu_int@reductions)) "pca"
                 else if("integrated.cca" %in% names(s$seu_int@reductions)) "integrated.cca"
                 else return(plotly::plotly_empty())
    sd_v <- s$seu_int@reductions[[reduc_use]]@stdev
    if (is.null(sd_v) || length(sd_v) == 0) {
      # integrated.cca doesn't store stdev — compute from embeddings
      emb  <- Seurat::Embeddings(s$seu_int, reduc_use)
      sd_v <- apply(emb, 2, sd)
    }
    df_e <- data.frame(PC=seq_along(sd_v), StdDev=sd_v)
    vline <- input$i_clust_dims %||% 30
    ggplotly(
      ggplot(df_e, aes(x=PC, y=StdDev)) +
        geom_point(size=3, color="#E67E22") + geom_line(color="#E67E22") +
        geom_vline(xintercept=min(vline, max(df_e$PC)),
                   color="red", linetype="dashed", linewidth=1) +
        theme_classic(base_size=13) +
        labs(title=paste0("Integrated Elbow — ", reduc_use,
                          " (red = clustering dims)"), x="Component", y="Std Dev")
    )
  })

  output$s_int_pca_grp <- renderPlotly({
    req(s$seu_int)
    reduc_use <- if (s_int_uses_layers() &&
                     "integrated.cca" %in% names(s$seu_int@reductions)) "integrated.cca"
                 else if("pca" %in% names(s$seu_int@reductions)) "pca"
                 else if("integrated.cca" %in% names(s$seu_int@reductions)) "integrated.cca"
                 else return(plotly::plotly_empty())
    req(input$s_int_color, input$s_int_color %in% names(s$seu_int@meta.data))
    emb <- as.data.frame(Seurat::Embeddings(s$seu_int, reduc_use)[,1:2])
    colnames(emb) <- c("X1","X2"); emb$Cell <- rownames(emb)
    cc  <- input$s_int_color
    emb$Color <- as.factor(s$seu_int@meta.data[emb$Cell, cc])
    emb$Label <- if("ID" %in% names(s$seu_int@meta.data))
      s$seu_int@meta.data[emb$Cell,"ID"] else emb$Cell
    ggplotly(
      ggplot(emb, aes(x=X1, y=X2, color=Color, text=Label)) +
        geom_point(size=2.5, alpha=0.8) + theme_classic(base_size=13) +
        labs(title=paste0(toupper(reduc_use), " — ", cc),
             x="Component 1", y="Component 2", color=cc),
      tooltip=c("text","x","y")
    )
  })

  output$s_int_log_preview <- renderText({
    entries <- grep("Step [0-9]|Integration", s$log, value=TRUE)
    if (!length(entries)) "No integration steps run yet."
    else paste(tail(entries, 15), collapse="\n")
  })

  # Server-side selectize for i_tech_overlay_var (large protein lists). Multi-select:
  # each chosen variable/feature becomes its own panel in the grid.
  output$i_tech_overlay_var_ui <- renderUI({
    req(s$seu_int)
    all_opts <- c(names(s$seu_int@meta.data), rownames(s$seu_int))
    selectizeInput("i_tech_overlay_var", "Variables / features to overlay:",
                   choices  = all_opts,
                   selected = character(0),
                   multiple = TRUE,
                   options  = list(
                     placeholder     = "Type to search (multiple allowed)...",
                     maxItems        = 12,
                     maxOptions      = 50
                   ))
  })

  # ── Integration method helpers ──────────────────────────────────────────────
  s_int_method <- reactive({ input$s_norm_method %||% "sct" })
  # Methods that use the Seurat v5 IntegrateLayers path (correct a pca reduction)
  # rather than the SCT anchor path: LogNormalize, VSN, and scp-median.
  s_int_uses_layers <- reactive({ s_int_method() %in% c("lognorm", .NA_AWARE) })

  output$s_int_method_banner <- renderUI({
    m <- s_int_method()
    if (m == "sct") {
      tags$p(style="margin:4px 0;font-size:12px;",
        tags$b("SCTransform mode (anchor-based):"), tags$br(),
        "Step 1: ⑥ tab → Integration mode → SCTransform + PCA per group.", tags$br(),
        "Steps 2–9: SelectIntegrationFeatures → PrepSCTIntegration → FindIntegrationAnchors → IntegrateData → RunPCA → FindNeighbors → FindClusters → RunUMAP")
    } else if (m %in% .NA_AWARE) {
      tags$p(style="margin:4px 0;font-size:12px;",
        tags$b(paste0(toupper(m), " mode (Seurat v5 IntegrateLayers on the NA-aware PCA):")), tags$br(),
        tags$b("Prerequisite:"), " run ", toupper(m), " in ⑥ with split/integration mode ",
        tags$b("OFF"), " — this writes a single NA-aware NIPALS 'pca' onto the object.", tags$br(),
        "Step 1: split that object's layers by group (reuses the 'pca').", tags$br(),
        "Step 4: IntegrateLayers() corrects the 'pca' reduction → 'integrated.cca'.", tags$br(),
        "Step 5: JoinLayers().", tags$br(),
        "Steps 7–9: FindNeighbors/FindClusters/RunUMAP using reduction='integrated.cca'.", tags$br(),
        tags$em("Integration operates on the embedding, not the expression matrix, so NAs are not an issue. Harmony is recommended (reduction-only); CCA/RPCA also available — they apply NA→0 on the integration object only and re-apply your ⑥ vars.to.regress in ScaleData so the anchor PCA stays regressed."))
    } else {
      tags$p(style="margin:4px 0;font-size:12px;",
        tags$b("LogNormalize mode (Seurat v5 IntegrateLayers):"), tags$br(),
        "Step 1: NormalizeData → FindVariableFeatures → ScaleData → RunPCA on full object.", tags$br(),
        "Step 4: IntegrateLayers() → produces 'integrated.cca' reduction.", tags$br(),
        "Step 5: JoinLayers().", tags$br(),
        "Steps 7–9: FindNeighbors/FindClusters/RunUMAP using reduction='integrated.cca'.", tags$br(),
        tags$em("Steps 2, 3 are SCT-only and are skipped."))
    }
  })

  # Dynamic step cards
  output$s_int_step2_card <- renderUI({
    if (s_int_uses_layers()) return(NULL)   # IntegrateLayers path skips this
    div(class="s-card",style="margin-top:8px;",
      fluidRow(column(8,tags$h5("Step 2 — SelectIntegrationFeatures")),
               column(4,uiOutput("s_int_step2_status"))),
      uiOutput("s_int_split_ui"),
      numericInput("s_int_nfeatures","nfeatures:",value=3000,min=100,max=10000,step=100),
      actionButton("s_run_step2","▶  SelectIntegrationFeatures",
                   class="btn-info",style="width:100%;")
    )
  })

  output$s_int_step4_card <- renderUI({
    m <- s_int_method()
    if (s_int_uses_layers()) {
      is_intensity <- m %in% .NA_AWARE
      # For VSN/scpmed default to Harmony (reduction-only, no NA issues); for
      # LogNorm keep CCA default. All correct the 'pca' reduction.
      method_choices <- c("Harmony (recommended)"="HarmonyIntegration",
                          "CCA"="CCAIntegration",
                          "RPCA"="RPCAIntegration")
      method_sel <- if (is_intensity) "HarmonyIntegration" else "CCAIntegration"
      div(class="s-card",style="margin-top:8px;background:#f0fff0;border-color:#27AE60;",
        fluidRow(column(8,tags$h5("Step 4 — IntegrateLayers")),
                 column(4,uiOutput("s_int_step4_status"))),
        tags$p(tags$small(
          "Seurat v5 IntegrateLayers corrects the 'pca' reduction and writes ",
          "'integrated.cca'. Requires Step 1 (split + pca) complete first.",
          if (is_intensity) tags$span(tags$br(),
            "Harmony corrects the embedding directly and never touches the ",
            "NA-containing data layer — the safest choice for VSN/scp-median. ",
            tags$b("CCA/RPCA"), " are anchor-based and require a complete matrix, so ",
            "selecting them applies an ", tags$b("NA→0 substitution"), " plus ScaleData ",
            "(re-applying your ⑥ vars.to.regress) + RunPCA on the integration object only, so ",
            "the anchor PCA stays regressed. This imputation affects the integrated ",
            "embedding used for clustering/UMAP; your marker testing stays NA-aware. RPCA is ",
            "often better for small datasets.") else NULL),
          style="color:grey;font-size:11px;"),
        radioButtons("s_int_ln_method","Integration method:",
                     choices=method_choices, selected=method_sel, inline=TRUE),
        sliderInput("s_int_anch_dims","dims (1:N):",min=5,max=50,value=30),
        sliderInput("s_int_ln_k_weight","k.weight:",min=5,max=200,value=100,step=5),
        tags$p(tags$small(
          "k.weight controls anchor weighting (CCA/RPCA) — reduce if you get ",
          "'fewer than k.weight cells' errors for small groups. Ignored by Harmony."),
          style="color:grey;font-size:11px;"),
        actionButton("s_run_step4","▶  IntegrateLayers",
                     class="btn-success",style="width:100%;")
      )
    } else {
      div(class="s-card",style="margin-top:8px;",
        fluidRow(column(8,tags$h5("Step 4 — FindIntegrationAnchors")),
                 column(4,uiOutput("s_int_step4_status"))),
        radioButtons("s_int_reduction","Anchor reduction:",
                     choices=c("rpca"="rpca","cca"="cca"),selected="rpca",inline=TRUE),
        sliderInput("s_int_anch_dims","dims (1:N):",min=5,max=50,value=30),
        actionButton("s_run_step4","▶  FindIntegrationAnchors",
                     class="btn-info",style="width:100%;")
      )
    }
  })

  output$s_int_step5_card <- renderUI({
    if (s_int_uses_layers()) {
      # IntegrateLayers path: JoinLayers
      div(class="s-card",style="margin-top:8px;background:#f0fff0;border-color:#27AE60;",
        fluidRow(column(8,tags$h5("Step 5 — JoinLayers")),
                 column(4,uiOutput("s_int_step5_status"))),
        tags$p(tags$small(
          "Rejoins the split RNA layers after integration, as required by Seurat v5."),
          style="color:grey;font-size:11px;"),
        actionButton("s_run_step5","▶  JoinLayers",
                     class="btn-success",style="width:100%;")
      )
    } else {
      div(class="s-card",style="margin-top:8px;",
        fluidRow(column(8,tags$h5("Step 5 — IntegrateData")),
                 column(4,uiOutput("s_int_step5_status"))),
        sliderInput("s_int_k_weight","k.weight:",min=5,max=200,value=20,step=5),
        tags$p(tags$small("k.weight=20 matches the SCT pipeline script."),style="color:grey;font-size:11px;"),
        actionButton("s_run_step5","▶  IntegrateData",
                     class="btn-info",style="width:100%;")
      )
    }
  })

  output$s_int_step7_note <- renderUI({
    reduc <- if(s_int_uses_layers()) "integrated.cca" else "pca"
    tags$p(tags$small(paste0("reduction = '", reduc, "'")),
           style="color:grey;font-size:11px;")
  })

  output$s_int_step9_note <- renderUI({
    reduc <- if(s_int_uses_layers()) "integrated.cca" else "pca"
    tags$p(tags$small(paste0(
      "RunUMAP uses reduction='", reduc, "'. ",
      if(s_int_uses_layers()) "DefaultAssay set to original assay after completion."
      else "DefaultAssay set to SCT after completion.")),
      style="color:grey;font-size:11px;")
  })

  # Step 1 card — only shown for LogNormalize
  output$s_int_step1_card <- renderUI({
    if (!s_int_uses_layers()) return(NULL)
    is_intensity <- s_int_method() %in% .NA_AWARE
    div(class="s-card",style="margin-top:8px;background:#f0fff0;border-color:#27AE60;",
      fluidRow(
        column(8, tags$h5(if(is_intensity)
                            "Step 1 — Split layers by group (reuse VSN/scp-median PCA)"
                          else "Step 1 — Split + Normalize per group (LogNorm)")),
        column(4, uiOutput("s_int_step1_status"))
      ),
      if (is_intensity)
        tags$p(tags$small(
          "Splits the already-normalized object's layers by the variable below and ",
          "reuses the NA-aware NIPALS 'pca'. No re-normalization — the VSN/scp-median ",
          "data layer and pca are kept intact. Requires a completed VSN/scp-median run in ⑥."),
          style="color:grey;font-size:11px;")
      else
        tags$p(tags$small(
          "Splits by the variable below, then runs NormalizeData → FindVariableFeatures → ",
          "ScaleData → RunPCA on each group separately."),
          style="color:grey;font-size:11px;"),
      uiOutput("s_int_ln_split_ui"),
      if (!is_intensity) uiOutput("s_int_ln_regress_ui") else NULL,
      actionButton("s_run_step1",
                   if(is_intensity)"▶  Step 1: Split layers" else "▶  Step 1: Normalize per group",
                   class="btn-success",style="width:100%;")
    )
  })

  # Step 3 card — only shown for SCT
  output$s_int_step3_card <- renderUI({
    if (s_int_method() != "sct") {
      # Show greyed-out skip message for non-SCT paths
      return(div(class="s-card",style="margin-top:8px;opacity:0.4;",
        tags$h5("Step 3 — PrepSCTIntegration"),
        tags$p(tags$small("Skipped — SCT-only step."), style="color:grey;font-size:11px;")))
    }
    div(class="s-card",style="margin-top:8px;",
      fluidRow(
        column(8, tags$h5("Step 3 — PrepSCTIntegration")),
        column(4, uiOutput("s_int_step3_status"))
      ),
      actionButton("s_run_step3","▶  PrepSCTIntegration",
                   class="btn-info",style="width:100%;")
    )
  })

  output$s_int_step1_status <- renderUI({ int_step_status(isTRUE(s$int_step1_done)) })

  # Split variable UI for LogNorm Step 1
  output$s_int_ln_split_ui <- renderUI({
    req(s$seu)
    meta_cols <- names(s$seu@meta.data)
    cat_cols  <- meta_cols[sapply(meta_cols, function(c) {
      v <- s$seu@meta.data[[c]]
      (is.character(v)||is.factor(v)) && length(unique(v[!is.na(v)])) >= 2 &&
        length(unique(v[!is.na(v)])) <= 20
    })]
    selectInput("s_int_ln_split","Split variable (group by):",
                choices=cat_cols,
                selected=if("sex" %in% cat_cols)"sex" else cat_cols[1])
  })

  output$s_int_ln_regress_ui <- renderUI({
    req(s$seu)
    all_cols <- setdiff(names(s$seu@meta.data), "orig.ident")
    tagList(
      tags$p(tags$b("vars.to.regress (optional):"), style="font-size:12px;margin:4px 0 2px 0;"),
      checkboxGroupInput("s_int_ln_regress", label=NULL,
                         choices=all_cols, selected=NULL, inline=TRUE)
    )
  })

  # ── Step 1 (LogNorm): NormalizeData+ScaleData+RunPCA on full object with split layers ─
  observeEvent(input$s_run_step1, {
    # ── VSN/scpmed: split the already-normalized object, reuse its NIPALS pca ──
    if (s_int_method() %in% .NA_AWARE) {
      req(s$seu, input$s_int_ln_split)

      # If the main object has no 'pca' (e.g. VSN was run in split/integration
      # mode, which stores per-group objects instead), rebuild a single NA-aware
      # NIPALS pca from the stashed normalized matrix so this workflow can proceed.
      if (!("pca" %in% names(s$seu@reductions)) &&
          (!is.null(.norm_mat(s$seu)) || !is.null(s$intensity_diag$mat))) {
        rebuilt <- tryCatch({
          if (!requireNamespace("pcaMethods", quietly=TRUE)) stop("pcaMethods not installed")
          # Data layer first; the stash is only a fallback for objects written by
          # an earlier version where the layer held the regressed matrix.
          m <- .norm_mat(s$seu) %||% s$intensity_diag$mat
          vf <- s$intensity_diag$vf
          if (is.null(vf) || length(vf) < 3) {
            v <- apply(m, 1, stats::var, na.rm=TRUE); nobs <- rowSums(!is.na(m))
            ok <- is.finite(v) & v > 0 & nobs >= 3
            vf <- rownames(m)[ok][order(v[ok], decreasing=TRUE)][seq_len(min(2000, sum(ok)))]
          }
          vf <- intersect(vf, rownames(m))
          cells_common <- intersect(colnames(m), colnames(s$seu))
          mvf <- m[vf, cells_common, drop=FALSE]
          # Re-apply the SAME regression used in ⑥ (stashed), so a rebuilt PCA is
          # not silently un-regressed. Without this, the covariates the user
          # regressed (e.g. nFeature) would re-enter the integration embedding.
          rv_r  <- s$intensity_diag$rv_use
          sdf_r <- s$intensity_diag$spline_df %||% 1
          std_r <- isTRUE(s$intensity_diag$standardize)
          if (!is.null(rv_r) && length(rv_r) > 0) {
            # Reuse the stored keep so the rebuilt PCA matches the one the ⑥ run
            # produced; otherwise Step 1 would silently change the model.
            mvf <- regress_out_na(mvf, s$seu@meta.data[cells_common, , drop=FALSE], rv_r,
                                  spline_df=sdf_r, standardize=std_r,
                                  keep=s$intensity_diag$keep_var)
          }
          pca_method <- if (s_int_method()=="vsn") (input$s_vsn_pca_method %||% "nipals")
                        else (input$s_scpmed_pca_method %||% "nipals")
          npcs_r <- min(.num(input$s_sct_npcs, 30), ncol(mvf)-1, length(vf)-1)
          pres <- pcaMethods::pca(t(mvf), method=pca_method, nPcs=npcs_r, center=TRUE, scale="none")
          emb  <- pcaMethods::scores(pres); rownames(emb) <- cells_common
          colnames(emb) <- paste0("PC_", seq_len(ncol(emb)))
          emb <- emb[intersect(colnames(s$seu), rownames(emb)), , drop=FALSE]
          seu_r <- s$seu
          Seurat::VariableFeatures(seu_r) <- vf
          seu_r[["pca"]] <- SeuratObject::CreateDimReducObject(
            embeddings=emb, key="PC_", assay=input$s_assay,
            stdev=as.numeric(pcaMethods::sDev(pres)))
          s$seu <- seu_r
          TRUE
        }, error=function(e) FALSE)
        if (isTRUE(rebuilt))
          s_log(paste0("Rebuilt NA-aware NIPALS 'pca' on the main object from the stashed matrix",
                       if(!is.null(s$intensity_diag$rv_use) && length(s$intensity_diag$rv_use))
                         paste0(" (regression re-applied: ", paste(s$intensity_diag$rv_use, collapse=","),
                                if(isTRUE(s$intensity_diag$standardize)) ", standardized" else "",
                                if((s$intensity_diag$spline_df %||% 1) > 1) paste0(", spline df=", s$intensity_diag$spline_df) else "",
                                ").")
                       else "."))
      }

      if (!("pca" %in% names(s$seu@reductions))) {
        # Common cause: VSN was run in ⑥ with "integration mode" (per-group split)
        # toggled ON, which stores per-group objects in s$sct_list and never writes
        # a pca onto s$seu. The IntegrateLayers workflow needs a SINGLE VSN run.
        msg <- if (!is.null(s$sct_list) && length(s$sct_list) > 0)
          paste0("No 'pca' on the main object — it looks like VSN/scp-median was run in ",
                 "⑥ with integration/split mode ON (per-group). For this IntegrateLayers ",
                 "workflow, re-run VSN/scp-median in ⑥ with split/integration mode OFF so a ",
                 "single NA-aware PCA is written, then return here. (Step 1 will split it by group.)")
        else
          paste0("No 'pca' reduction found — run VSN/scp-median normalization + PCA in ⑥ ",
                 "first (with split/integration mode OFF), then return to Step 1.")
        showNotification(msg, type="error", duration=15); return()
      }
      tryCatch({
        seu      <- s$seu
        split_by <- input$s_int_ln_split
        grps <- unique(as.character(seu@meta.data[[split_by]])); grps <- grps[!is.na(grps)]
        if (length(grps) < 2) {
          showNotification(paste0("'",split_by,"' has only 1 group."),type="error",duration=8); return() }
        withProgress(message="Step 1: split layers (VSN/scp-median)...", value=0.3, {
          # Seurat v5: split the assay's layers by group. The NA-aware data layer
          # and the NIPALS 'pca' reduction are preserved — no re-normalization.
          incProgress(0.4, detail="Splitting layers by group")
          seu[[input$s_assay]] <- split(seu[[input$s_assay]], f=seu@meta.data[[split_by]])
          s$seu_int <- seu
        })
        s$int_step1_done <- TRUE
        s$int_step2_done <- s$int_step3_done <- s$int_step4_done <- FALSE
        s$int_step5_done <- s$int_step6_done <- s$int_step7_done <- FALSE
        s$int_step8_done <- s$int_step9_done <- FALSE
        s_log(paste0("Step 1 ✓ split layers by '", split_by, "' (VSN/scp-median), pca reused."))
        showNotification("Step 1 done: layers split, pca reused. Proceed to Step 4 (IntegrateLayers).",
                         type="message", duration=6)
      }, error=function(e) {
        showNotification(paste0("Step 1 error: ", conditionMessage(e)), type="error", duration=12)
        s_log(paste0("Step 1 FAILED: ", conditionMessage(e)))
      })
      return()
    }
    req(s$seu, s_int_method() == "lognorm", input$s_int_ln_split)
    tryCatch({
      seu      <- s$seu
      split_by <- input$s_int_ln_split
      rv_ln    <- unname(input$s_int_ln_regress)
      if (length(rv_ln) == 0) rv_ln <- NULL
      npcs_use <- min(input$s_int_pca_dims %||% 30, ncol(seu)-1, nrow(seu)-1)

      grps <- unique(as.character(seu@meta.data[[split_by]]))
      grps <- grps[!is.na(grps)]
      if (length(grps) < 2) {
        showNotification(paste0("'",split_by,"' has only 1 group."),type="error",duration=8); return()
      }

      withProgress(message="Step 1: LogNorm + PCA (Seurat v5)...", value=0, {
        # Seurat v5: split layers on the assay — keeps one object
        incProgress(0.1, detail="Splitting layers")
        seu[[input$s_assay]] <- split(seu[[input$s_assay]], f=seu@meta.data[[split_by]])

        if (!isTRUE(input$s_ln_skip_norm)) {
          incProgress(0.2, detail="NormalizeData")
          seu <- Seurat::NormalizeData(seu, verbose=FALSE)
        } else {
          incProgress(0.2, detail="NormalizeData skipped — copying counts to data layer")
          tryCatch({
            cm <- SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="counts")
            SeuratObject::LayerData(seu@assays[[input$s_assay]], layer="data") <- cm
          }, error=function(e) {
            tryCatch({
              seu@assays[[input$s_assay]]@data <<- seu@assays[[input$s_assay]]@counts
            }, error=function(e2) NULL)
          })
        }

        incProgress(0.4, detail="FindVariableFeatures")
        seu <- Seurat::FindVariableFeatures(seu,
                 selection.method=input$s_ln_vf_method %||% "vst",
                 nfeatures=.num(input$s_ln_nfeatures, 2000), verbose=FALSE)

        incProgress(0.6, detail="ScaleData")
        rv_clean <- if(!is.null(rv_ln)&&length(rv_ln)>0) {
          rv_ln[sapply(rv_ln, function(col) {
            if (!col %in% names(seu@meta.data)) return(FALSE)
            vals <- seu@meta.data[[col]]
            if (is.character(vals)) { vals <- as.factor(vals); seu@meta.data[[col]] <<- vals }
            if (any(is.na(vals))) {
              if (is.factor(vals)) { v2 <- as.character(vals); v2[is.na(v2)] <- "0"; seu@meta.data[[col]] <<- as.factor(v2) }
              else { vals[is.na(vals)] <- 0; seu@meta.data[[col]] <<- vals }
            }
            n_lev <- if(is.factor(seu@meta.data[[col]])) nlevels(droplevels(seu@meta.data[[col]]))
                     else length(unique(seu@meta.data[[col]][!is.na(seu@meta.data[[col]])]))
            n_lev >= 2
          })]
        } else NULL
        if (!is.null(rv_clean)&&length(rv_clean)==0) rv_clean <- NULL
        seu <- Seurat::ScaleData(seu, vars.to.regress=rv_clean, verbose=FALSE)

        incProgress(0.8, detail="RunPCA")
        seu <- Seurat::RunPCA(seu, npcs=npcs_use, verbose=FALSE)
        s$seu_int <- seu
      })
      s$int_step1_done <- TRUE
      s$int_step2_done <- s$int_step3_done <- s$int_step4_done <- FALSE
      s$int_step5_done <- s$int_step6_done <- s$int_step7_done <- FALSE
      s$int_step8_done <- s$int_step9_done <- FALSE
      n_var <- length(Seurat::VariableFeatures(seu))
      s_log(paste0("Step 1 ✓ LogNorm+PCA (v5 split layers): ", n_var,
                   " var features, ", npcs_use, " PCs, split by '", split_by, "'"))
      showNotification(paste0("Step 1 done: ", n_var, " var features. Proceed to Step 4 (IntegrateLayers)."),
                       type="message", duration=6)
    }, error=function(e) {
      showNotification(paste0("Step 1 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 1 FAILED: ", conditionMessage(e)))
    })
  })


  # ── Integration step status outputs ──────────────────────────────────────
  int_step_status <- function(done) {
    if (done) tags$span("✓", style="color:#27AE60;font-weight:700;font-size:14px;")
    else       tags$span("–", style="color:#aaa;font-size:14px;")
  }
  output$s_int_step2_status <- renderUI({ int_step_status(s$int_step2_done) })
  output$s_int_step3_status <- renderUI({ int_step_status(s$int_step3_done) })
  output$s_int_step4_status <- renderUI({ int_step_status(s$int_step4_done) })
  output$s_int_step5_status <- renderUI({ int_step_status(s$int_step5_done) })
  output$s_int_step6_status <- renderUI({ int_step_status(s$int_step6_done) })

  output$s_int_step6_note <- renderUI({
    if (!(s_int_method() %in% .NA_AWARE)) return(NULL)
    is_anchor <- !identical(input$s_int_ln_method %||% "HarmonyIntegration",
                            "HarmonyIntegration")
    div(style="background:#eafaf1;border:1px solid #27AE60;border-radius:4px;padding:6px;margin:4px 0;",
      tags$small(
        tags$b("Click RunPCA to mark this step complete \u2014 it is a no-op on this route. "),
        "Steps 7\u20139 read ", tags$code("integrated.cca"),
        " from Step 4, so nothing here is used.",
        tags$br(),
        if (is_anchor)
          tagList(
            tags$b("Note for CCA / RPCA: "),
            "a RunPCA already happened, inside Step 4's anchor prep \u2014 on the NA\u21920 copy, ",
            "to build the space the anchors are found in. That is a different PCA from this ",
            "one. Step 6 would recompute ", tags$code("pca"),
            " on the data layer, which has since been restored to its NA-containing form, ",
            "so it would be both invalid and unread.")
        else
          tagList(
            tags$b("Note for Harmony: "),
            "no RunPCA runs anywhere in this route. Harmony corrects your NIPALS ",
            tags$code("pca"), " directly into ", tags$code("integrated.cca"),
            ", and RunPCA on the NA-containing data layer would be invalid."),
        style="color:#1a5c38;"))
  })
  output$s_int_step7_status <- renderUI({ int_step_status(s$int_step7_done) })
  output$s_int_step8_status <- renderUI({ int_step_status(s$int_step8_done) })
  output$s_int_step9_status <- renderUI({ int_step_status(s$int_step9_done) })

  # ── Step 2: SelectIntegrationFeatures ──────────────────────────────────────
  observeEvent(input$s_run_step2, {
    req(s$sct_list, length(s$sct_list) >= 2)
    tryCatch({
      nfeats_req <- max(100, .num(input$s_int_nfeatures, 2000))
      withProgress(message="Step 2: SelectIntegrationFeatures...", value=0.5, {
        feats <- Seurat::SelectIntegrationFeatures(s$sct_list, nfeatures=nfeats_req)
      })
      n_actual <- length(feats)
      if (n_actual < nfeats_req) {
        min_vf <- min(sapply(s$sct_list, function(o) length(Seurat::VariableFeatures(o))))
        showNotification(paste0("WARNING: Requested ", nfeats_req, " features but only ",
          n_actual, " selected. Smallest group has ", min_vf, " variable features."),
          type="warning", duration=15)
      }
      s$int_feats      <- feats
      s$int_step2_done <- TRUE
      s$int_step3_done <- s$int_step4_done <- s$int_step5_done <- FALSE
      s$int_step6_done <- s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
      s_log(paste0("Step 2 ✓ SelectIntegrationFeatures: ", n_actual, " features"))
      showNotification(paste0("Step 2 done: ", n_actual, " features."), type="message", duration=5)
    }, error=function(e) {
      showNotification(paste0("Step 2 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 2 FAILED: ", conditionMessage(e)))
    })
  })

  # ── Step 3: PrepSCTIntegration (SCT only) ──────────────────────────────────
  observeEvent(input$s_run_step3, {
    req(s$sct_list, s$int_feats, s$int_step2_done)
    if (s_int_method() == "lognorm") {
      showNotification("Step 3 skipped for LogNormalize — proceed to Step 4.",
                       type="message", duration=5)
      s$int_step3_done <- TRUE; return()
    }
    tryCatch({
      withProgress(message="Step 3: PrepSCTIntegration...", value=0.5, {
        obj_list <- Seurat::PrepSCTIntegration(s$sct_list, anchor.features=s$int_feats)
      })
      s$int_obj_list   <- obj_list
      s$int_step3_done <- TRUE
      s$int_step4_done <- s$int_step5_done <- FALSE
      s$int_step6_done <- s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
      s_log("Step 3 ✓ PrepSCTIntegration")
      showNotification("Step 3 done.", type="message", duration=4)
    }, error=function(e) {
      showNotification(paste0("Step 3 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 3 FAILED: ", conditionMessage(e)))
    })
  })

  # ── Step 4: IntegrateLayers (LogNorm) or FindIntegrationAnchors (SCT) ────────
  observeEvent(input$s_run_step4, {
    method <- s_int_method()

    if (s_int_uses_layers()) {
      req(s$seu_int, s$int_step1_done, "pca" %in% names(s$seu_int@reductions))
      tryCatch({
        int_fn_name <- input$s_int_ln_method %||%
                       (if (method %in% .NA_AWARE) "HarmonyIntegration" else "CCAIntegration")
        int_fn <- tryCatch(get(int_fn_name), error=function(e) {
          showNotification(paste0("Integration function '", int_fn_name,
            "' not found. For Harmony, install the 'harmony' package."),
            type="error", duration=12); NULL })
        if (is.null(int_fn)) return()
        dims <- 1:min(input$s_int_anch_dims %||% 30,
                      ncol(Seurat::Embeddings(s$seu_int,"pca")))
        k_w  <- input$s_int_ln_k_weight %||% 100
        # Clamp to the smallest group, as the SCT path does. Harmony ignores
        # k.weight entirely, so only the anchor methods are affected.
        .grp_n <- table(as.character(s$seu_int@meta.data[[input$s_int_ln_split]]))
        .min_n <- if (length(.grp_n)) min(as.integer(.grp_n)) else NA_integer_
        if (is.finite(.min_n) && k_w >= .min_n) {
          k_old <- k_w
          k_w   <- max(5L, .min_n - 1L)
          showNotification(paste0("k.weight reduced from ", k_old, " to ", k_w,
                                  ": the smallest group has ", .min_n, " cells and k.weight ",
                                  "must be below that. With groups this small the anchor ",
                                  "methods have little to work with \u2014 Harmony, which ignores ",
                                  "k.weight, is usually the better choice here."),
                           type="warning", duration=14)
          s_log(paste0("k.weight clamped ", k_old, " -> ", k_w,
                       " (smallest group = ", .min_n, " cells)"))
        }
        is_harmony <- identical(int_fn_name, "HarmonyIntegration")
        is_intensity <- method %in% .NA_AWARE

        # ── NA→0 prep for anchor-based integration (RPCA/CCA) on VSN/scpmed ─────
        # RPCA/CCA need a scale.data layer and pca feature loadings, which the
        # NA-containing VSN data layer can't provide. Fill NA→0 on the INTEGRATION
        # object only (s$seu_int is a copy — the main object's NA-aware matrix and
        # NIPALS pca are untouched), then ScaleData + RunPCA so anchors can be found.
        # Scope: affects the integrated embedding only; marker testing stays NA-aware.
        if (is_intensity && !is_harmony) {
          withProgress(message="Preparing anchor-based integration (NA→0 + scale + PCA)...", value=0.2, {
            seu_prep <- s$seu_int
            assay_i  <- input$s_assay
            split_v  <- input$s_int_ln_split
            # Join → fill NA→0 → re-split, to guarantee a clean single data layer.
            join_fn <- if (existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                       else if (requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                       else get("JoinLayers")
            seu_prep[[assay_i]] <- tryCatch(join_fn(seu_prep[[assay_i]]),
                                            error=function(e) seu_prep[[assay_i]])
            dl <- tryCatch(as.matrix(SeuratObject::LayerData(seu_prep@assays[[assay_i]], layer="data")),
                           error=function(e) NULL)
            if (!is.null(dl)) {
              # Snapshot the NA-aware values so they can be restored after Step 4.
              # Stored on s$ rather than a local so a Step 4 that errors part-way
              # still leaves the snapshot available for the next attempt.
              s$int_data_snapshot <- dl
              s_log(paste0("Anchor-prep: snapshotted the NA-aware data layer (",
                           nrow(dl), " x ", ncol(dl), ") for restoration after Step 4."))
              n_na <- sum(is.na(dl)); dl[is.na(dl)] <- 0
              tryCatch(SeuratObject::LayerData(seu_prep@assays[[assay_i]], layer="data") <- dl,
                       error=function(e) NULL)
              incProgress(0.3, detail="Splitting + ScaleData")
              seu_prep[[assay_i]] <- split(seu_prep[[assay_i]], f=seu_prep@meta.data[[split_v]])
              # Keep existing variable features (from the VSN run); ensure some exist.
              if (length(Seurat::VariableFeatures(seu_prep)) < 3)
                seu_prep <- Seurat::FindVariableFeatures(seu_prep, verbose=FALSE)
              # Regress the SAME covariates used in ⑥ out of the scaled matrix, so the
              # anchor PCA that RPCA/CCA build is not un-regressed. Without this, the
              # integration embedding discards the regression from the NIPALS pca and
              # nuisance covariates (e.g. nFeature) re-enter the integrated UMAP.
              rv_int <- s$intensity_diag$rv_use
              rv_int <- rv_int[rv_int %in% names(seu_prep@meta.data)]
              # ScaleData needs each covariate to be non-constant within the object.
              rv_int <- rv_int[vapply(rv_int, function(cn){
                v <- seu_prep@meta.data[[cn]]
                if (is.character(v) || is.factor(v)) length(unique(v[!is.na(v)])) >= 2
                else length(unique(v[!is.na(v)])) >= 2
              }, logical(1))]
              if (length(rv_int) > 0) {
                seu_prep <- Seurat::ScaleData(seu_prep, vars.to.regress=rv_int, verbose=FALSE)
                s_log(paste0("Anchor-prep ScaleData regressed: ", paste(rv_int, collapse=", "), "."))
              } else {
                seu_prep <- Seurat::ScaleData(seu_prep, verbose=FALSE)
              }
              incProgress(0.3, detail="RunPCA (NA→0 matrix)")
              npcs_p   <- min(input$s_int_pca_dims %||% 30, ncol(seu_prep)-1, nrow(seu_prep)-1)
              seu_prep <- Seurat::RunPCA(seu_prep, npcs=npcs_p, verbose=FALSE)
              s$seu_int <- seu_prep
              s_log(paste0("Anchor-prep for ", int_fn_name, ": NA→0 (", n_na,
                           " values) + ScaleData + RunPCA on integration object (testing matrix untouched)."))
            }
          })
        }

        withProgress(message=paste0("Step 4: IntegrateLayers (", int_fn_name, ")..."), value=0.5, {
          seu_int <- if (is_harmony) {
            # Harmony corrects the pca embedding directly; k.weight not used.
            Seurat::IntegrateLayers(
              object=s$seu_int, method=int_fn,
              orig.reduction="pca", new.reduction="integrated.cca",
              verbose=FALSE)
          } else {
            # CCA/RPCA are anchor-based; pass dims and k.weight.
            Seurat::IntegrateLayers(
              object=s$seu_int, method=int_fn,
              orig.reduction="pca", new.reduction="integrated.cca",
              dims=dims, k.weight=k_w, verbose=FALSE)
          }
        })
        # ── Restore the NA-aware data layer ────────────────────────────────
        # The anchor prep's NA -> 0 substitution was needed to BUILD the anchor
        # space; it has served its purpose once integrated.cca exists. Putting the
        # original values back means the integrated object's data layer matches the
        # unintegrated one, so ⑫ plots show the same values ⑫ tests. scale.data is
        # deliberately left as the prep computed it: it is the regressed view the
        # plots offer and the space the anchors were found in.
        if (!is.null(s$int_data_snapshot)) {
          seu_int <- tryCatch({
            aq <- input$s_assay
            join_fn2 <- if (existsMethod("JoinLayers","Seurat")) Seurat::JoinLayers
                        else if (requireNamespace("SeuratObject",quietly=TRUE)) SeuratObject::JoinLayers
                        else get("JoinLayers")
            si <- seu_int
            si[[aq]] <- tryCatch(join_fn2(si[[aq]]), error=function(e) si[[aq]])
            snap <- s$int_data_snapshot
            cur  <- as.matrix(SeuratObject::LayerData(si@assays[[aq]], layer="data"))
            fi <- intersect(rownames(cur), rownames(snap))
            ci <- intersect(colnames(cur), colnames(snap))
            if (length(fi) >= max(3, 0.5*nrow(cur)) && length(ci) > 0) {
              cur[fi, ci] <- snap[fi, ci]
              SeuratObject::LayerData(si@assays[[aq]], layer="data") <- cur
              n_restored <- sum(is.na(cur))
              s_log(paste0("Step 4: restored the NA-aware data layer on the integrated object (",
                           n_restored, " values back to NA across ", length(fi), " features). ",
                           "scale.data left as the anchor prep computed it."))
              # Layers were joined to do this; re-split so Step 5 behaves the same
              # way it does on the Harmony branch.
              sv <- input$s_int_ln_split
              if (!is.null(sv) && sv %in% names(si@meta.data))
                si[[aq]] <- split(si[[aq]], f=si@meta.data[[sv]])
              si
            } else {
              s_log(paste0("Step 4: could NOT restore the NA-aware data layer \u2014 only ",
                           length(fi), " of ", nrow(cur), " features matched the snapshot. ",
                           "\u246b plots on this object will show zero-filled values."))
              seu_int
            }
          }, error=function(e) {
            s_log(paste0("Step 4: data-layer restoration failed (", conditionMessage(e),
                         "); leaving the zero-filled layer in place."))
            seu_int
          })
          s$int_data_snapshot <- NULL
        }

        s$seu_int        <- seu_int
        s$int_step4_done <- TRUE
        s$int_step5_done <- FALSE
        s$int_step6_done <- s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
        s_log(paste0("Step 4 \u2713 IntegrateLayers (", int_fn_name, "): integrated.cca ready",
                     if(is_harmony) " (Harmony, reduction-only)" else paste0(", k.weight=", k_w)))
        showNotification("Step 4 done: integrated.cca ready. Run Step 5 (JoinLayers).",
                         type="message", duration=5)
      }, error=function(e) {
        showNotification(paste0("Step 4 error: ", conditionMessage(e)), type="error", duration=12)
        s_log(paste0("Step 4 FAILED: ", conditionMessage(e)))
      })
    } else {
      obj_list <- s$int_obj_list; req(obj_list, s$int_feats, s$int_step3_done)
      tryCatch({
        min_cells <- min(sapply(obj_list, ncol))
        d_anch    <- 1:min(input$s_int_anch_dims %||% 30, min_cells - 1)
        reduction <- input$s_int_reduction %||% "rpca"
        withProgress(message=paste0("Step 4: FindIntegrationAnchors (SCT, ", reduction, ")..."),
                     value=0.5, {
          anchors <- Seurat::FindIntegrationAnchors(
            obj_list, normalization.method="SCT",
            anchor.features=s$int_feats, dims=d_anch,
            reduction=reduction, verbose=FALSE)
        })
        s$int_anchors    <- anchors
        s$int_step4_done <- TRUE
        s$int_step5_done <- FALSE
        s$int_step6_done <- s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
        s_log(paste0("Step 4 ✓ FindIntegrationAnchors: reduction=", reduction))
        showNotification("Step 4 done: anchors found.", type="message", duration=4)
      }, error=function(e) {
        showNotification(paste0("Step 4 error: ", conditionMessage(e)), type="error", duration=12)
        s_log(paste0("Step 4 FAILED: ", conditionMessage(e)))
      })
    }
  })


  # ── Step 5: JoinLayers (IntegrateLayers path) or IntegrateData (SCT) ─────────
  observeEvent(input$s_run_step5, {
    method <- s_int_method()

    if (s_int_uses_layers()) {
      req(s$seu_int, s$int_step4_done)
      tryCatch({
        withProgress(message="Step 5: JoinLayers...", value=0.5, {
          seu_int <- s$seu_int
          join_fn <- if (existsMethod("JoinLayers", "Seurat")) Seurat::JoinLayers
                     else if (requireNamespace("SeuratObject", quietly=TRUE)) SeuratObject::JoinLayers
                     else get("JoinLayers")
          seu_int[[input$s_assay]] <- join_fn(seu_int[[input$s_assay]])
        })
        s$seu_int        <- seu_int
        s$int_step5_done <- TRUE
        s$int_step6_done <- s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
        s_log("Step 5 ✓ JoinLayers complete")
        showNotification("Step 5 done: layers rejoined. Run Step 6 (RunPCA).",
                         type="message", duration=4)
      }, error=function(e) {
        showNotification(paste0("Step 5 error: ", conditionMessage(e)), type="error", duration=12)
        s_log(paste0("Step 5 FAILED: ", conditionMessage(e)))
      })
    } else {
      req(s$int_anchors, s$int_step4_done)
      tryCatch({
        min_cells     <- min(sapply(s$sct_list, ncol))
        d_anch        <- 1:min(input$s_int_anch_dims %||% 30, min_cells - 1)
        k_weight_safe <- min(input$s_int_k_weight %||% 20, min_cells - 1)
        withProgress(message=paste0("Step 5: IntegrateData (k.weight=", k_weight_safe, ")..."),
                     value=0.5, {
          seu_int <- Seurat::IntegrateData(
            s$int_anchors, normalization.method="SCT",
            dims=d_anch, k.weight=k_weight_safe, verbose=FALSE)
        })
        s$seu_int        <- seu_int
        s$int_step5_done <- TRUE
        s$int_step6_done <- s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
        s_log(paste0("Step 5 ✓ IntegrateData: ", ncol(seu_int), " cells, k.weight=", k_weight_safe))
        showNotification(paste0("Step 5 done: ", ncol(seu_int), " cells integrated."),
                         type="message", duration=4)
      }, error=function(e) {
        showNotification(paste0("Step 5 error: ", conditionMessage(e)), type="error", duration=12)
        s_log(paste0("Step 5 FAILED: ", conditionMessage(e)))
      })
    }
  })



  # ── Step 6: RunPCA ────────────────────────────────────────────────────────
  observeEvent(input$s_run_step6, {
    req(s$seu_int, s$int_step5_done)
    # VSN/scpmed: the integrated.cca reduction from IntegrateLayers is directly
    # usable, and RunPCA on the NA-containing data layer is invalid — so Step 6
    # is a no-op that simply marks itself done.
    if (s_int_method() %in% .NA_AWARE) {
      s$int_step6_done <- TRUE
      s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
      s_log("Step 6 ✓ skipped for VSN/scp-median — integrated.cca used directly (no RunPCA on NA data).")
      showNotification("Step 6 skipped for VSN/scp-median — integrated.cca is used directly. Proceed to Step 7.",
                       type="message", duration=6)
      return()
    }
    tryCatch({
      npcs <- min(input$s_int_pca_dims %||% 50, ncol(s$seu_int)-1, nrow(s$seu_int)-1)
      withProgress(message=paste0("Step 6: RunPCA (npcs=", npcs, ")..."), value=0.5, {
        # NOTE: on the IntegrateLayers path this is deliberately skipped above.
        # Reached only by the anchor (SCT) path, where DefaultAssay is "integrated"
        # and RunPCA on its scale.data is the documented next step.
        seu_int <- Seurat::RunPCA(s$seu_int, assay="integrated", npcs=npcs, verbose=FALSE)
      })
      s$seu_int        <- seu_int
      s$int_step6_done <- TRUE
      s$int_step7_done <- s$int_step8_done <- s$int_step9_done <- FALSE
      s_log(paste0("Step 6 ✓ RunPCA: ", npcs, " PCs — check Elbow Plot before Step 7"))
      showNotification(paste0("Step 6 done: ", npcs, " PCs. Check Elbow Plot before Step 7."),
                       type="message", duration=6)
    }, error=function(e) {
      showNotification(paste0("Step 6 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 6 FAILED: ", conditionMessage(e)))
    })
  })

  # ── Step 7: FindNeighbors ─────────────────────────────────────────────────
  observeEvent(input$s_run_step7, {
    method <- s_int_method()
    reduc  <- if(s_int_uses_layers()) "integrated.cca" else "pca"
    req(s$seu_int, s$int_step6_done, reduc %in% names(s$seu_int@reductions))
    tryCatch({
      dims <- 1:min(input$i_clust_dims %||% 30, ncol(Seurat::Embeddings(s$seu_int, reduc)))
      withProgress(message=paste0("Step 7: FindNeighbors (reduction=", reduc,
                                   ", dims=1:", max(dims), ")..."), value=0.5, {
        seu_int <- Seurat::FindNeighbors(s$seu_int, reduction=reduc, dims=dims,
                                          k.param=input$i_clust_k %||% 20, verbose=FALSE)
      })
      s$seu_int        <- seu_int
      s$int_step7_done <- TRUE
      s$int_step8_done <- s$int_step9_done <- FALSE
      s_log(paste0("Step 7 ✓ FindNeighbors: reduction=", reduc, ", dims=1:", max(dims)))
      showNotification("Step 7 done: KNN graph built.", type="message", duration=4)
    }, error=function(e) {
      showNotification(paste0("Step 7 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 7 FAILED: ", conditionMessage(e)))
    })
  })

  # ── Step 8: FindClusters ──────────────────────────────────────────────────
  observeEvent(input$s_run_step8, {
    req(s$seu_int, s$int_step7_done)
    tryCatch({
      res <- input$i_clust_res %||% 0.8
      withProgress(message=paste0("Step 8: FindClusters (resolution=", res, ")..."),
                   value=0.5, {
        seu_int <- Seurat::FindClusters(s$seu_int, resolution=res,
                                         algorithm=as.numeric(input$i_clust_alg %||% "1"),
                                         verbose=FALSE)
      })
      n_cl             <- length(unique(seu_int$seurat_clusters))
      s$seu_int        <- seu_int
      s$int_step8_done <- TRUE
      s$int_step9_done <- FALSE
      s_log(paste0("Step 8 ✓ FindClusters: ", n_cl, " clusters at resolution=", res))
      showNotification(paste0("Step 8 done: ", n_cl, " clusters."), type="message", duration=5)
    }, error=function(e) {
      showNotification(paste0("Step 8 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 8 FAILED: ", conditionMessage(e)))
    })
  })

  # ── Step 9: RunUMAP + RunTSNE ─────────────────────────────────────────────
  observeEvent(input$s_run_step9, {
    method <- s_int_method()
    reduc  <- if(s_int_uses_layers()) "integrated.cca" else "pca"
    req(s$seu_int, s$int_step8_done, reduc %in% names(s$seu_int@reductions))
    tryCatch({
      dims <- 1:min(input$i_clust_dims %||% 30, ncol(Seurat::Embeddings(s$seu_int, reduc)))
      withProgress(message="Step 9: RunUMAP + RunTSNE...", value=0, {
        incProgress(0.4, detail="RunUMAP")
        seu_int <- Seurat::RunUMAP(s$seu_int, reduction=reduc, dims=dims, verbose=FALSE)
        incProgress(0.8, detail="RunTSNE")
        perp    <- min(30, floor((ncol(seu_int)-1)/3))
        seu_int <- Seurat::RunTSNE(seu_int, reduction=reduc, dims=dims,
                                    perplexity=perp, verbose=FALSE)
        # Set DefaultAssay for downstream marker discovery
        target_assay <- if("SCT" %in% names(seu_int@assays)) "SCT" else input$s_assay
        if (target_assay %in% names(seu_int@assays))
          Seurat::DefaultAssay(seu_int) <- target_assay
      })
      s$seu_int        <- seu_int
      s$int_step9_done <- TRUE
      s_log(paste0("Step 9 ✓ RunUMAP + RunTSNE (reduction=", reduc,
                   ", dims=1:", max(dims), ") — integration complete"))
      showNotification("Step 9 done: UMAP + t-SNE ready. Proceed to ⑫ Integrated Markers.",
                       type="message", duration=6)
    }, error=function(e) {
      showNotification(paste0("Step 9 error: ", conditionMessage(e)), type="error", duration=12)
      s_log(paste0("Step 9 FAILED: ", conditionMessage(e)))
    })
  })

  # Stubs for old button IDs (no longer used but kept to prevent errors)
  observeEvent(input$s_run_int,    { showNotification("Use the individual Step buttons above.", type="warning", duration=5) })
  observeEvent(input$i_run_clust,  { showNotification("Use Steps 7–9 buttons in ⑩ Integration tab.", type="warning", duration=5) })


  # ── PDF plot download ──────────────────────────────────────────────────────
  # Central function: given a plot key, render the ggplot/Seurat plot at the
  # user-specified dimensions and write it to a PDF file.
  # Static ggplot volcano for PDF export (the GUI volcano is plotly). Mirrors the
  # GUI thresholds/colors/top-N labelling but uses ggrepel for clean, non-
  # overlapping labels — publication quality. `mk` is the marker frame, `pfx` the
  # input prefix ("s_vol" for ⑨ Markers, "i_vol" for ⑫ Integrated), `mode` the
  # marker mode ("all"/"two"), `comp` the stored comparison string, and `fs` font.
  # ── Marker-volcano label ranking + x-axis limits ─────────────────────────
  # Shared by the ⑨ panel, the ⑫ panel and the PDF builder so all three label
  # the SAME features. `d` must already carry FC and yval columns.
  #
  #   pval  strongest significance (the previous hardcoded behaviour)
  #   fc    largest |effect|, which at the extremes favours low-coverage features
  #   both  "outermost": rank by distance from the origin after scaling each axis
  #         to unit range, so neither axis wins on units alone. On a volcano the
  #         y spread is usually much larger than the x spread, so without the
  #         rescale this would collapse back into `pval`.
  .vol_label_rows <- function(d, mode, n, picked = NULL) {
    out <- rep(FALSE, nrow(d))
    if (!nrow(d)) return(out)
    # Hand-picked features are labelled unconditionally: not filtered by
    # direction, significance or the top-N cap, because the point of picking a
    # feature by name is usually to show where a known marker sits even when it
    # is NS. Picks union with the automatic top-N rather than replacing it, so
    # the two controls can be used together or independently.
    if (length(picked)) {
      key <- if ("Gene" %in% names(d)) as.character(d$Gene) else rownames(d)
      out[key %in% as.character(picked)] <- TRUE
    }
    n <- as.integer(n %||% 0)
    if (is.na(n) || n <= 0) return(out)
    rx <- suppressWarnings(diff(range(d$FC,   na.rm=TRUE)));  if (!is.finite(rx) || rx == 0) rx <- 1
    ry <- suppressWarnings(diff(range(d$yval, na.rm=TRUE)));  if (!is.finite(ry) || ry == 0) ry <- 1
    score <- switch(mode %||% "pval",
      "fc"   = abs(d$FC),
      "both" = sqrt((abs(d$FC)/rx)^2 + (d$yval/ry)^2),
      d$yval)
    # Split by direction so both sides get labels rather than whichever side
    # happens to hold the strongest hits.
    for (dir in c("Up","Down")) {
      idx <- which(d$Dir == dir & is.finite(score))
      if (length(idx)) out[idx[order(-score[idx])][seq_len(min(n, length(idx)))]] <- TRUE
    }
    out
  }

  # Volcano subtitle: the |log2FC| cap notice, plus a warning naming any
  # hand-picked feature that is NOT in the plotted set.
  #
  # Picks override the significance filter (NS features still get labelled,
  # see .vol_label_rows), but they cannot override the two controls that
  # physically REMOVE rows before labelling happens: the |log2FC| cap and, in
  # all-clusters mode, the cluster selector. Previously such a pick just
  # produced no label with nothing on the figure to say why.
  .vol_subtitle <- function(n_capped, picked, d) {
    parts <- character(0)
    if (length(n_capped) == 1 && is.finite(n_capped) && n_capped > 0)
      parts <- c(parts, paste0(n_capped, " feature(s) hidden by the |log2FC| cap — ",
                               "still present in the table and the exports"))
    if (length(picked) && !is.null(d) && nrow(d)) {
      key  <- if ("Gene" %in% names(d)) as.character(d$Gene) else rownames(d)
      miss <- setdiff(as.character(picked), key)
      if (length(miss))
        parts <- c(parts, paste0(
          length(miss), " picked feature(s) not labelled: ",
          paste(utils::head(miss, 5), collapse=", "),
          if (length(miss) > 5) paste0(", +", length(miss) - 5, " more") else "",
          " — removed by the |log2FC| cap or the cluster selection, not by significance"))
    }
    if (!length(parts)) NULL else paste(parts, collapse="\n")
  }

  # ── Volcano point / label styling ────────────────────────────────────
  # Outlined points: shape 21 takes a FILL for the category and a thin black
  # border, which separates overlapping points in the dense significant cloud
  # where same-coloured fills otherwise merge into one mass. Because shape 21 is
  # fill-driven, the Dir mapping moves from colour= to fill= wherever this is
  # used, and the matching scale becomes scale_fill_manual.
  .vol_pt <- function(size = 2, alpha = 0.75, stroke = 0.25) {
    ggplot2::geom_point(ggplot2::aes(fill = Dir), shape = 21, colour = "black",
                        stroke = stroke, size = size, alpha = alpha)
  }

  # ── Volcano label placement ───────────────────────────────────────
  # Deterministic, self-contained. NO ggrepel.
  #
  # Two earlier attempts here relied on ggrepel and both failed to draw a line:
  # ggrepel repels a label only from the points inside its OWN data and from
  # other labels, so a few well-separated labels give it nothing to solve, it
  # leaves each label on its point, and the segment it emits has zero length.
  # Seeding nudge_x/nudge_y did not reliably fix it either. Rather than keep
  # guessing at a library's internal placement rules, the offsets are computed
  # here and the segment is drawn explicitly, so a visible line from label to
  # point is guaranteed by construction.
  #
  # Returns one row per label: (px,py) the exact point, (lx,ly) the label
  # anchor, hj the text justification. Used by BOTH the static export and the
  # on-screen plotly version, so the two place labels identically.
  .vol_label_pos <- function(d, xcol, ycol, labcol) {
    if (is.null(d) || !nrow(d)) return(NULL)
    px <- suppressWarnings(as.numeric(d[[xcol]]))
    py <- suppressWarnings(as.numeric(d[[ycol]]))
    lb <- as.character(d[[labcol]])
    ok <- is.finite(px) & is.finite(py) & !is.na(lb) & nzchar(lb)
    px <- px[ok]; py <- py[ok]; lb <- lb[ok]
    n <- length(px); if (!n) return(NULL)

    # Offsets in DATA units, scaled to the spread so they are proportionate at
    # any axis range. A single labelled point has zero spread, hence the guard.
    xs <- diff(range(px)); if (!is.finite(xs) || xs == 0) xs <- max(abs(px), 1)
    ys <- diff(range(py)); if (!is.finite(ys) || ys == 0) ys <- max(abs(py), 1)

    sidex <- ifelse(px >= 0, 1, -1)          # fan outward from x = 0
    lx <- px + sidex * 0.055 * xs
    ly <- py + 0.025 * ys

    # Greedy top-down de-overlap, per side. Labels on the same side are forced
    # at least minsep apart vertically; the segment keeps each tied to its own
    # point however far it has been pushed.
    minsep <- 0.032 * ys
    for (sd in c(1, -1)) {
      idx <- which(sidex == sd)
      if (length(idx) < 2) next
      idx <- idx[order(-ly[idx])]
      for (k in seq_along(idx)[-1]) {
        pv <- idx[k - 1]; cu <- idx[k]
        if (ly[pv] - ly[cu] < minsep) ly[cu] <- ly[pv] - minsep
      }
    }
    data.frame(px = px, py = py, lx = lx, ly = ly, lab = lb,
               hj = ifelse(sidex > 0, 0, 1), stringsAsFactors = FALSE)
  }

  # Static (PDF / any device) leader lines + text, from the positions above.
  # Leader-line appearance, in one place so the static export and the on-screen
  # plotly annotations cannot drift apart. VOL_SEG_COL / VOL_SEG_LWD are the only
  # knobs; the plotly arrowwidth below is the same line expressed in px.
  VOL_SEG_COL <- "red"
  VOL_SEG_LWD <- 0.15

  .vol_repel <- function(d, xcol, ycol, labcol, fs, seg_col = VOL_SEG_COL) {
    pos <- .vol_label_pos(d, xcol, ycol, labcol)
    if (is.null(pos) || !nrow(pos)) return(NULL)
    list(
      ggplot2::geom_segment(
        data = pos, inherit.aes = FALSE,
        ggplot2::aes(x = px, y = py, xend = lx, yend = ly),
        colour = seg_col, linewidth = VOL_SEG_LWD),
      # Drawn after the segment, so the text sits on top of both the line and
      # the points.
      ggplot2::geom_text(
        data = pos, inherit.aes = FALSE,
        ggplot2::aes(x = lx, y = ly, label = lab, hjust = hj),
        size = fs/3.4, colour = "black", vjust = 0.35, show.legend = FALSE)
    )
  }

  # On-screen labels. ggrepel has no plotly translation at all, so these are
  # real plotly annotations. ax/ay are given in DATA coordinates via
  # axref/ayref, reusing the positions computed above — pixel offsets would not
  # match the static export.
  .vol_annotate <- function(pl, d, xcol, ycol, labcol = "Gene") {
    pos <- .vol_label_pos(d, xcol, ycol, labcol)
    if (is.null(pos) || !nrow(pos)) return(pl)
    out <- try(plotly::add_annotations(pl,
      x = pos$px, y = pos$py,                 # arrow head: the exact point
      ax = pos$lx, ay = pos$ly,               # tail + text position
      axref = "x", ayref = "y",
      text = pos$lab,
      showarrow = TRUE, arrowhead = 0, arrowsize = 0.8,
      arrowwidth = 0.6, arrowcolor = VOL_SEG_COL, standoff = 2,
      font = list(size = 11, color = "black"),
      bgcolor = "rgba(255,255,255,0.72)",
      bordercolor = "rgba(0,0,0,0.25)", borderwidth = 0.5, borderpad = 1,
      xanchor = ifelse(pos$hj > 0.5, "right", "left")), silent = TRUE)
    if (inherits(out, "try-error")) {
      # Reported rather than swallowed: a silent fallback here is what made the
      # earlier failures look like "nothing changed".
      s_log(paste0("Volcano label annotation failed: ",
                   conditionMessage(attr(out, "condition"))))
      return(pl)
    }
    out
  }

  # Force the marker outline onto the converted traces. ggplotly does not always
  # carry shape-21 borders across, so this guarantees the outline on screen
  # regardless of translation fidelity. Line traces ignore marker.line.
  .vol_outline <- function(pl) {
    tryCatch(plotly::style(pl, marker.line = list(color = "black", width = 0.6)),
             error = function(e) pl)
  }

  # Feature choices for the volcano pickers, taken from whatever is actually
  # plottable in the table so a pick can never reference a missing feature.
  .vol_pick_choices <- function(mk) {
    if (is.null(mk) || !nrow(mk)) return(character(0))
    g <- if ("gene" %in% names(mk)) as.character(mk$gene) else rownames(mk)
    sort(unique(g[!is.na(g) & nzchar(g)]))
  }

  # View-only x limits. coord_cartesian, never scale_x_continuous: scale limits
  # DROP out-of-range rows, which would silently change the Up/Down counts in
  # the title. Clipping the view leaves the data and the counts intact.
  .vol_xlim <- function(pfx) {
    lo <- .num(input[[paste0(pfx, "_xmin")]], NA_real_)
    hi <- .num(input[[paste0(pfx, "_xmax")]], NA_real_)
    if (!is.finite(lo) && !is.finite(hi)) return(NULL)
    if (is.finite(lo) && is.finite(hi) && lo >= hi) return(NULL)
    ggplot2::coord_cartesian(xlim=c(if (is.finite(lo)) lo else NA,
                                    if (is.finite(hi)) hi else NA))
  }

  .build_volcano_static <- function(mk, pfx, mode, comp, fs) {
    if (is.null(mk) || !nrow(mk)) return(NULL)
    gv <- function(k, d=NULL) input[[paste0(pfx, k)]] %||% d
    is_roc  <- .mk_is_roc(mk)
    fc_col  <- if("avg_log2FC" %in% names(mk)) "avg_log2FC" else if("avg_diff" %in% names(mk)) "avg_diff" else NA
    if (is.na(fc_col)) return(NULL)
    p_col   <- if (is_roc) "power" else if("p_val" %in% names(mk)) "p_val" else "p_val_adj"
    padj_col<- if (is_roc) "power" else if("p_val_adj" %in% names(mk)) "p_val_adj" else p_col
    mk$FC <- mk[[fc_col]]; mk$PADJ <- mk[[padj_col]]; mk$PVAL <- mk[[p_col]]
    mk$Gene <- if("gene" %in% names(mk)) mk$gene else rownames(mk)
    fc_t <- gv("_fc", 0.5); p_t <- if(is_roc) gv("_p",0.4) else gv("_p",0.05)
    sel  <- gv("_cluster","all")
    if (mode=="all" && !is.null(sel) && sel!="all" && "cluster" %in% names(mk)) {
      mk <- mk[as.character(mk$cluster)==sel, , drop=FALSE]
      grp_a <- paste0("Cluster ",sel); grp_b <- "all others"
    } else if (mode=="two") {
      parts <- strsplit(comp %||% "A  vs  B", "  vs  ")[[1]]
      grp_a <- if(length(parts)==2) trimws(parts[1]) else "Group A"
      grp_b <- if(length(parts)==2) trimws(parts[2]) else "Group B"
    } else { grp_a <- "cluster (positive)"; grp_b <- "all others" }
    # Display cap on |log2FC|, matching the panel. This was missing here, so a
    # capped on-screen volcano still exported with the runaway coefficients in
    # it and a completely different x range.
    fc_cap <- suppressWarnings(as.numeric(gv("_cap", 0)))
    n_capped <- 0L
    if (length(fc_cap) == 1 && is.finite(fc_cap) && fc_cap > 0) {
      n_capped <- sum(abs(mk$FC) > fc_cap, na.rm=TRUE)
      mk <- mk[is.na(mk$FC) | abs(mk$FC) <= fc_cap, , drop=FALSE]
    }
    if (!nrow(mk)) return(NULL)
    sig_ok <- if(is_roc) mk$PADJ >= p_t else mk$PADJ <= p_t
    mk$Dir <- ifelse(abs(mk$FC)>=fc_t & sig_ok & mk$FC>0, "Up",
              ifelse(abs(mk$FC)>=fc_t & sig_ok & mk$FC<0, "Down", "NS"))
    vh <- function(x,d) if(!is.null(x) && grepl("^#[0-9A-Fa-f]{6}$",x)) x else d
    up_col <- vh(gv("_up_col"), "#E74C3C"); down_col <- vh(gv("_down_col"), "#2E86C1")
    n_up <- sum(mk$Dir=="Up",na.rm=TRUE); n_dn <- sum(mk$Dir=="Down",na.rm=TRUE)
    mk$yval <- if(is_roc) mk$PADJ else .vol_nlp(mk)
    mk$do_label <- .vol_label_rows(mk, gv("_label_mode", "pval"),
                                   gv("_nlabel", 0), gv("_pick"))
    ttl <- if(mode=="two") paste0(grp_a," vs ",grp_b,"  |  ↑",n_up," up  ↓",n_dn," down")
           else if(!is.null(sel) && sel!="all") paste0("Cluster ",sel,"  |  ↑",n_up," ↓",n_dn)
           else paste0("All clusters  |  ",nrow(mk)," proteins")
    p <- ggplot(mk, aes(x=FC, y=yval)) +
      .vol_pt(size=.pdf_pt(1.8)) +
      scale_fill_manual(values=c("Up"=up_col,"Down"=down_col,"NS"="grey70")) +
      geom_vline(xintercept=c(-fc_t,fc_t), linetype="dashed", color="grey40") +
      geom_hline(yintercept=if(is_roc) p_t else -log10(p_t), linetype="dashed", color="grey40") +
      { .vol_xlim(pfx) } +
      theme_classic(base_size=fs) +
      labs(title=ttl, fill="",
           subtitle=.vol_subtitle(n_capped, gv("_pick"), mk),
           x=paste0(if(is_roc)"avg_diff" else "avg_log2FC","  (positive = higher in ",grp_a,")"),
           y=if(is_roc)"ROC power" else "-log10(p_val)")
    p <- p + .vol_repel(mk[mk$do_label, , drop=FALSE],
                        "FC", "yval", "Gene", fs)
    p
  }

  # Plot keys that are computed directly from the filtered matrix/metadata
  # and therefore must NOT require a Seurat object to exist.
  .s_pdf_no_seu_keys <- c("ev_heatmap_pdf", "ev_bar_pdf", "ev_feature_box_pdf")

  # The base pdf() device uses Type 1 fonts whose encoding lacks the glyphs this
  # app puts in titles and axis labels — the up/down arrows, the middle dot in
  # |2·AUC−1|, en/em dashes, superscript ². They silently render as "." or drop
  # out. cairo_pdf embeds a real font and renders them correctly, so prefer it
  # whenever the R build has cairo support.
  .pdf_dev <- function() {
    if (isTRUE(unname(capabilities("cairo")))) grDevices::cairo_pdf else "pdf"
  }
  # Same choice, for the base-graphics fallback paths. Kept separate because
  # cairo_pdf's first argument is `filename` while pdf()'s is `file`, so one
  # object cannot serve both ggsave(device=) and a direct device call.
  # Some exports cannot be returned as an object: Seurat::DimHeatmap draws
  # straight to the active device and (with fast=TRUE) returns NULL. The
  # dispatcher runs BEFORE the PDF device is opened, so "draw it and return
  # NULL" sent the drawing to a throwaway device and handed the handler a NULL,
  # which it correctly reported as "No plot produced".
  #
  # Wrapping the drawing in a closure defers it: the handler opens the real
  # device first, then calls fn(). Any future base-graphics export can use this.
  .pdf_base <- function(fn) structure(list(fn = fn), class = "pdf_basefn")

  .pdf_open <- function(file, w, h) {
    if (isTRUE(unname(capabilities("cairo"))))
      grDevices::cairo_pdf(filename = file, width = w, height = h, onefile = TRUE)
    else grDevices::pdf(file = file, width = w, height = h)
  }

  # ── Export point size / alpha ───────────────────────────────────────────────
  # Screen point sizes are tuned for a ~400px panel and are almost always wrong
  # for a 8x6in figure, so every UMAP / t-SNE / PCA / feature plot in the export
  # dispatcher reads its point size from here. 0 (the default) means "keep the
  # per-plot default", so an unchanged Export tab exports exactly as before.
  .pdf_pt <- function(default) {
    v <- .num(input$s_pdf_pt, 0)
    if (is.finite(v) && v > 0) v else default
  }

  s_render_plot_for_pdf <- function(plot_key, w, h, fs) {
    # Do not let a missing Seurat object abort plots that never use one.
    seu <- tryCatch(s_seu_with_ident(), error = function(e) NULL)
    if (is.null(seu) && !(plot_key %in% .s_pdf_no_seu_keys))
      stop("No Seurat object available yet. Build it in tab 5 and normalize ",
           "it in tab 6 before exporting this plot.", call. = FALSE)
    # NA-fill the data layer ONCE here (display-only), so every expression plot
    # below (umap_feat, mk_feat, mk_dot, umap/tsne_tech_grid, mk_vln, …) exports
    # faithfully. VSN/scp-median data layers carry NAs that make Seurat plot
    # functions blank or error ("missing value where TRUE/FALSE needed") on the
    # export device; .display_safe_seu returns the object unchanged for SCT/
    # LogNormalize, so this is a no-op there. Non-expression cases (elbow, PCA,
    # metadata DimPlots) don't read the data layer, so filling is harmless.
    if (!is.null(seu)) {
      .fill_assay <- if ("SCT" %in% names(seu@assays)) "SCT" else input$s_assay
      seu <- tryCatch(.display_safe_seu(seu, .fill_assay), error=function(e) seu)
    }
    pve      <- if(!is.null(s$seu) && "pca" %in% names(s$seu@reductions)) s_pve() else c(0,0)
    df_p     <- if(!is.null(s$seu) && "pca" %in% names(s$seu@reductions)) s_pca_df() else NULL
    assay_nm <- input$s_assay

    switch(plot_key,

      # ── SCTransform ────────────────────────────────────────────────────────
      # Was: VariableFeaturePlot(seu) + LabelPoints directly. That read the
      # GLOBAL object rather than the view-selected one, and errored outright on
      # VSN / scp-median / log2 (no HVFInfo metadata exists on those routes —
      # variable features are set directly), which is why this entry produced an
      # error page instead of a figure. Now shares one builder with the screen.
      "varfeat" = {
        p <- .build_varfeat_static(fs); req(!is.null(p)); p
      },

      "meansd_pdf" = .build_meansd(fs),
      "elbow" = {
        sd_v <- seu@reductions$pca@stdev
        ggplot(data.frame(PC=seq_along(sd_v),StdDev=sd_v),aes(x=PC,y=StdDev))+
          geom_point(size=3,color="#2980B9")+geom_line(color="#2980B9")+
          theme_classic(base_size=fs)+labs(title="Elbow Plot",x="PC",y="Std Dev")
      },
      # Both PCA covariate exports are rebuilt from s_pca_df() exactly as the
      # panels do, rather than via DimPlot. DimPlot was wrong twice over here:
      # it read the GLOBAL object instead of the ⑥ view-selected one, and it
      # cannot render a continuous covariate at all, so exporting a numeric
      # technical variable produced a meaningless discrete legend instead of the
      # viridis scale shown on screen.
      "pca_bio" = {
        req(input$s_pca_bio_col)
        obj <- s_sct_active(); req(obj, df_p)
        cc  <- input$s_pca_bio_col
        lbl <- input$s_sct_view %||% "_full_"
        d <- df_p
        d$Color <- if (cc %in% names(obj@meta.data))
                     .lvl_factor(obj@meta.data[d$Cell, cc], cc) else factor("All")
        ggplot(d, aes(x=PC1, y=PC2, color=Color)) +
          geom_point(size=.pdf_pt(3), alpha=0.8) +
          { .scale_col_for(cc, levels(d$Color), na.value="grey70") } +
          theme_classic(base_size=fs) +
          labs(title=paste0("[",lbl,"] PCA — ",cc), color=cc,
               x=paste0("PC1 (",pve[1],"%)"), y=paste0("PC2 (",pve[2],"%)"))
      },
      "pca_tech_single" = {
        req(input$s_pca_tech_col)
        obj <- s_sct_active(); req(obj, df_p)
        cc  <- input$s_pca_tech_col
        lbl <- input$s_sct_view %||% "_full_"
        raw <- if (cc %in% names(obj@meta.data)) obj@meta.data[df_p$Cell, cc] else "NA"
        is_cont <- is.numeric(raw) && length(unique(raw)) > 10
        d <- df_p
        d$Color <- if (is_cont) as.numeric(raw) else .lvl_factor(raw, cc)
        p <- ggplot(d, aes(x=PC1, y=PC2, color=Color)) +
          geom_point(size=.pdf_pt(3), alpha=0.8) +
          theme_classic(base_size=fs) +
          labs(title=paste0("[",lbl,"] PCA — ",cc), color=cc,
               x=paste0("PC1 (",pve[1],"%)"), y=paste0("PC2 (",pve[2],"%)"))
        if (is_cont) p <- p + viridis::scale_color_viridis(option="plasma", name=cc)
        else p <- p + { .scale_col_for(cc, levels(d$Color), na.value="grey70") }
        p
      },
      "pca_tech_facet" = {
        req(df_p, input$s_pca_tech_facet_vars)
        facet_vars <- input$s_pca_tech_facet_vars
        plot_list <- lapply(facet_vars, function(v) {
          vals <- seu@meta.data[df_p$Cell, v]
          is_cont <- is.numeric(vals) && length(unique(vals)) > 10
          df_v <- data.frame(PC1=df_p$PC1, PC2=df_p$PC2,
                             Color=if(is_cont) as.numeric(vals) else .lvl_factor(vals, v))
          p <- ggplot(df_v,aes(x=PC1,y=PC2,color=Color))+geom_point(size=.pdf_pt(2),alpha=0.8)+
            theme_classic(base_size=fs)+labs(title=v,x=paste0("PC1 (",pve[1],"%)"),y=paste0("PC2 (",pve[2],"%)"),color=v)
          if(is_cont) p <- p+viridis::scale_color_viridis(option="plasma",name=v)
          else p <- p + { .scale_col_for(v, levels(df_v$Color)) }
          p
        })
        patchwork::wrap_plots(plot_list, ncol=min(4,length(plot_list)))
      },
      "pc_heatmap" = {
        # s_sct_active(), not seu: the panel is view-aware and the export was
        # silently using the full object instead of the ⑥ view.
        obj <- s_sct_active(); req(obj, "pca" %in% names(obj@reductions))
        pcs <- seq(input$s_hm_pcs[1], input$s_hm_pcs[2])
        ncell <- min(ncol(obj), 100)
        .pdf_base(function() {
          g <- Seurat::DimHeatmap(obj, dims=pcs, cells=ncell, balanced=TRUE,
                                  fast=FALSE, raster=FALSE)
          # fast=FALSE returns a patchwork on current Seurat but drew directly on
          # older versions; print only when an object actually came back.
          if (inherits(g, c("ggplot","patchwork","gg"))) print(g)
          invisible(NULL)
        })
      },

      # ── Embeddings ─────────────────────────────────────────────────────────
      "umap_grp" = {
        req("umap" %in% names(seu@reductions))
        Seurat::DimPlot(seu, reduction="umap", group.by=input$s_emb_col,
                        pt.size=.pdf_pt(2), cols=.pal_seu(seu, input$s_emb_col)) +
          theme_classic(base_size=fs)
      },
      "umap_feat" = {
        req("umap" %in% names(seu@reductions), input$s_emb_feat)
        Seurat::FeaturePlot(seu, features=input$s_emb_feat, reduction="umap",
                            pt.size=.pdf_pt(2), cols=c("grey90","#8E44AD")) + theme_classic(base_size=fs)
      },
      "tsne_grp" = {
        req("tsne" %in% names(seu@reductions))
        Seurat::DimPlot(seu, reduction="tsne", group.by=input$s_emb_col,
                        pt.size=.pdf_pt(2), cols=.pal_seu(seu, input$s_emb_col)) +
          theme_classic(base_size=fs)
      },
      "tsne_feat" = {
        req("tsne" %in% names(seu@reductions), input$s_emb_feat)
        Seurat::FeaturePlot(seu, features=input$s_emb_feat, reduction="tsne",
                            pt.size=.pdf_pt(2), cols=c("grey90","#8E44AD")) + theme_classic(base_size=fs)
      },
      "umap_tech_grid" = {
        p <- .build_s_tech_grid("umap"); req(!is.null(p)); p
      },
      "tsne_tech_grid" = {
        p <- .build_s_tech_grid("tsne"); req(!is.null(p)); p
      },

      # ── QC ─────────────────────────────────────────────────────────────────
      "vln_qc" = {
        feats <- intersect(c(paste0("nFeature_",assay_nm), paste0("nCount_",assay_nm),
                             "percent.mt","nFeature_raw","log2_total_intensity","log2_median_intensity"),
                           names(seu@meta.data))
        Seurat::VlnPlot(seu, features=feats, group.by=input$s_vln_grp, pt.size=1, ncol=3,
                        cols=.pal_seu(seu, input$s_vln_grp))
      },
      "feat_scatter" = {
        req(input$s_feat_x, input$s_feat_y)
        gb <- if(!is.null(input$s_feat_grp) && input$s_feat_grp!="none") input$s_feat_grp else NULL
        p <- Seurat::FeatureScatter(seu, feature1=input$s_feat_x, feature2=input$s_feat_y,
                               group.by=gb, pt.size=.pdf_pt(2))
        # FeatureScatter has no cols=, so the palette goes on as a scale layer
        # (matching how output$s_feat_scatter does it on screen).
        pal_sc <- if (!is.null(gb)) .scale_col_for(gb, .pal_lv(seu, gb)) else NULL
        if (!is.null(pal_sc)) p <- p + pal_sc
        p
      },

      # ── Clustering ─────────────────────────────────────────────────────────
      "clust_umap_pdf" = {
        req("umap" %in% names(seu@reductions), "seurat_clusters" %in% names(seu@meta.data))
        Seurat::DimPlot(seu, reduction="umap", group.by="seurat_clusters",
                        pt.size=.pdf_pt(2), cols=.pal_seu(seu, "seurat_clusters")) +
          theme_classic(base_size=fs)
      },
      "clust_prop_pdf" = {
        req("seurat_clusters" %in% names(seu@meta.data))
        df_p2 <- as.data.frame(table(Cluster=seu$seurat_clusters))
        df_p2$Pct <- df_p2$Freq/sum(df_p2$Freq)*100
        ggplot(df_p2,aes(x=Cluster,y=Pct,fill=Cluster))+geom_bar(stat="identity")+
          scale_fill_manual(values=.cluster_cols(levels(df_p2$Cluster)))+
          theme_classic(base_size=fs)+labs(y="% cells",title="Cluster proportions")
      },

      # ── Markers ────────────────────────────────────────────────────────────
      # Delegates to the panel's own builder, so the layer selector, observed-only
      # mode, overlay, point size, ncol, significance brackets and source caption
      # all carry into the PDF.
      "mk_vln" = .build_mk_vln(fs),

      "cc_dimplot" = {
        req(s$cc_scored)
        red <- input$s_cc_dimred %||% "umap"
        if (!red %in% names(seu@reductions)) red <- names(seu@reductions)[1]
        req(red)
        Seurat::DimPlot(seu, reduction=red, group.by="Phase", pt.size=.pdf_pt(1),
                        cols=c("G1"="#95A5A6","S"="#3498DB","G2M"="#E74C3C")) +
          ggplot2::ggtitle(paste0("Cell Cycle Phase — ", toupper(red))) +
          ggplot2::theme_classic(base_size=fs)
      },

      "cc_ridge" = {
        req(s$cc_scored, input$s_cc_ridge_feats)
        assay_use <- if("SCT" %in% names(seu@assays)) "SCT" else assay_nm
        split_by  <- input$s_cc_ridge_splitby %||% "Phase"
        Seurat::RidgePlot(seu, features=input$s_cc_ridge_feats, ncol=2,
                          group.by=split_by, assay=assay_use) &
          ggplot2::theme_classic(base_size=fs)
      },

      # Delegates to the panel builder, so the jitter layer, point size and the
      # p-value brackets all carry into the exported figure.
      "cc_diff" = .build_cc_diff(fs),

      "cc_prop" = {
        req(s$cc_scored, input$s_cc_prop_grp)
        df  <- seu@meta.data
        grp <- input$s_cc_prop_grp
        req(grp %in% names(df), "Phase" %in% names(df))
        df_prop <- df %>%
          dplyr::group_by(.data[[grp]], Phase) %>%
          dplyr::summarise(n=dplyr::n(), .groups="drop") %>%
          dplyr::group_by(.data[[grp]]) %>%
          dplyr::mutate(pct=100*n/sum(n))
        ggplot2::ggplot(df_prop, ggplot2::aes(x=.data[[grp]], y=pct, fill=Phase)) +
          ggplot2::geom_bar(stat="identity", color="black", linewidth=0.3) +
          ggplot2::scale_fill_manual(values=c("G1"="#95A5A6","S"="#3498DB","G2M"="#E74C3C")) +
          ggplot2::labs(title="Phase Proportions", x=grp, y="% of cells") +
          ggplot2::theme_classic(base_size=fs)
      },

      # Delegates to the panel builder, so the data / scale.data selection and
      # its caption carry into the exported figure.
      "mk_feat" = .build_mk_feat(fs),
      "mk_dot" = {
        req(s$markers, input$s_dot_n)
        top <- .mk_top_per_cluster(s$markers, input$s_dot_n)
        top <- intersect(top, rownames(seu)); req(length(top)>0)
        assay_use <- if("SCT" %in% names(seu@assays))"SCT" else assay_nm
        Seurat::DotPlot(seu, features=top, assay=assay_use) +
          RotatedAxis() + theme(axis.text.x=element_text(angle=45,hjust=1,size=9))
      },

      # ── Integration ────────────────────────────────────────────────────────
      "int_umap_pdf" = {
        req(s$seu_int, "umap" %in% names(s$seu_int@reductions), input$s_int_color)
        cc <- input$s_int_color
        Seurat::DimPlot(s$seu_int, reduction="umap", group.by=cc, pt.size=.pdf_pt(2),
                        cols=.pal_seu(s$seu_int, cc)) +
          theme_classic(base_size=fs) + labs(title=paste0("Integrated UMAP — ",cc))
      },
      "int_compare" = {
        req("umap" %in% names(seu@reductions))
        cc <- if(!is.null(input$s_int_color) && input$s_int_color %in% names(seu@meta.data))
          input$s_int_color else names(seu@meta.data)[1]
        p1 <- Seurat::DimPlot(seu, reduction="umap", group.by=cc, pt.size=.pdf_pt(1.5),
                              cols=.pal_seu(seu, cc)) +
          ggtitle("Before") + theme_classic(base_size=fs)
        if(!is.null(s$seu_int) && "umap" %in% names(s$seu_int@reductions)) {
          p2 <- Seurat::DimPlot(s$seu_int, reduction="umap", group.by=cc, pt.size=.pdf_pt(1.5),
                                cols=.pal_seu(s$seu_int, cc)) +
            ggtitle("After") + theme_classic(base_size=fs)
          p1 + p2
        } else p1
      },

      # ── Integration (added views) ──────────────────────────────────────────
      "int_umap_grp_pdf" = {
        req(s$seu_int, "umap" %in% names(s$seu_int@reductions))
        cc <- if(!is.null(input$s_int_color2) && input$s_int_color2 %in% names(s$seu_int@meta.data))
          input$s_int_color2 else names(s$seu_int@meta.data)[1]
        Seurat::DimPlot(s$seu_int, reduction="umap", group.by=cc, pt.size=.pdf_pt(2),
                        cols=.pal_seu(s$seu_int, cc)) +
          theme_classic(base_size=fs) + labs(title=paste0("Integrated UMAP — ",cc))
      },
      "int_tech_grid_pdf" = {
        p <- .build_i_tech_grid(); req(!is.null(p)); p
      },
      # ── Clustering diagnostics ──────────────────────────────────
      # All six delegate to the panel builders, so each export is the figure on
      # screen at the current settings.
      "clust_meta_pdf"    = .build_clust_meta(s$seu, input$s_clust_meta_col,
                                              "Cluster × ", fs),
      "clustree_pdf"      = .build_clustree(s$clustree_seu, fs),
      "sil_pdf"           = .build_sil_bar(s$sil_result, "Silhouette by cluster", fs),
      "sil_grid_pdf"      = .build_sil_grid(s$sil_grid, "Mean silhouette", fs),
      "i_clust_meta_pdf"  = .build_clust_meta(s$seu_int, input$i_clust_meta_col,
                                              "Integrated cluster × ", fs),
      "int_clustree_pdf"  = .build_clustree(s$i_clustree_seu, fs),

      "int_sil_grid_pdf" = .build_sil_grid(s$i_sil_grid, "Integrated: mean silhouette", fs),
      "int_sil_pdf" = .build_sil_bar(s$i_sil_result,
                                     "Integrated silhouette by cluster", fs),

      # ── Integrated Markers ─────────────────────────────────────────────────
      "imk_vln" = .build_i_mk_vln(fs),
      "imk_dot" = {
        req(s$seu_int, s$int_markers, input$i_dot_n)
        su <- i_seu_with_ident()
        if (!is.null(input$i_mk_grpby) && input$i_mk_grpby %in% names(su@meta.data))
          Seurat::Idents(su) <- input$i_mk_grpby
        top <- .mk_top_per_cluster(s$int_markers, input$i_dot_n)
        top <- intersect(top, rownames(su)); req(length(top)>0)
        au <- if("SCT" %in% names(su@assays))"SCT" else input$s_assay
        su <- .display_safe_seu(su, au)   # NA-fill for plotting (VSN/scpmed)
        Seurat::DotPlot(su, features=top, assay=au) + RotatedAxis() +
          theme(axis.text.x=element_text(angle=45,hjust=1,size=9))
      },
      "imk_phist" = {
        req(s$int_markers)
        .build_phist(s$int_markers, "i_ph", "Integrated p-value distribution", fs)
      },
      "imk_volcano_pdf" = {
        req(s$int_markers)
        p <- .build_volcano_static(s$int_markers, "i_vol", input$i_mk_mode %||% "all",
                                   s$last_i_mk_comp, fs)
        req(!is.null(p)); p
      },

      # ── Marker p-value histogram (⑨) ───────────────────────────────────────
      "mk_phist" = {
        req(s$markers)
        .build_phist(s$markers, "s_ph", "P-value distribution", fs)
      },

      "mk_volcano_pdf" = {
        req(s$markers)
        p <- .build_volcano_static(s$markers, "s_vol", input$s_mk_mode %||% "all",
                                   s$last_mk_comp, fs)
        req(!is.null(p)); p
      },

      # UpSet is base graphics and cannot enter this ggplot-only pipeline, so
      # an UpSet selection exports as the barplots instead.
      "mk_overlap_pdf" = {
        req(s$markers)
        d <- s_overlap_data(); req(!is.null(d), length(d$sets) > 0)
        ty <- input$s_ov_type %||% "auto"
        if (ty %in% c("auto","upset")) ty <- if (length(d$sets) <= 4) "venn" else "excl"
        p <- .build_overlap_plot(d, ty, fs); req(!is.null(p)); p
      },

      # Manual heatmap / trajectory: delegate to the panel builders so the
      # protein selection, layer, scaling and column mode all carry across.
      "mk_heatmap_pdf"  = .build_mk_heatmap("s_mk", fs),
      "mk_traj_pdf"     = .build_mk_traj("s_mk", fs),
      "imk_heatmap_pdf" = .build_mk_heatmap("i_mk", fs),
      "imk_traj_pdf"    = .build_mk_traj("i_mk", fs),

      "imk_overlap_pdf" = {
        req(s$int_markers)
        d <- i_overlap_data(); req(!is.null(d), length(d$sets) > 0)
        ty <- input$i_ov_type %||% "auto"
        if (ty %in% c("auto","upset")) ty <- if (length(d$sets) <= 4) "venn" else "excl"
        p <- .build_overlap_plot(d, ty, fs); req(!is.null(p)); p
      },

      # ── Pathway (ORA / GSEA) ───────────────────────────────────────────────
      "pw_plot_pdf" = {
        req(s$pw_result, s$pw_meta)
        res <- s$pw_result; meta <- s$pw_meta
        # weighted set cover filter (ORA or GSEA) when enabled and computed
        if (isTRUE(input$pw_wsc) && "in_wsc" %in% names(res))
          res <- res[!is.na(res$in_wsc) & res$in_wsc, , drop=FALSE]
        nn <- min(.num(input$pw_plot_n, 15), nrow(res))
        dcol <- if ("description" %in% names(res)) "description" else "geneSet"
        metric <- input$pw_plot_metric %||% "er"
        if (metric=="nes" && "normalizedEnrichmentScore" %in% names(res)) {
          res <- res[order(-abs(res$normalizedEnrichmentScore)), ][seq_len(nn), ]
          ggplot(res, aes(x=reorder(.data[[dcol]], normalizedEnrichmentScore), y=normalizedEnrichmentScore)) +
            geom_col(fill="#8E44AD", width=0.8) + coord_flip() + theme_classic(base_size=fs) +
            labs(x=NULL, y="Normalized ES", title=paste0("GSEA — ", meta$cluster))
        } else if (metric=="fdr" && "FDR" %in% names(res)) {
          res <- res[order(res$FDR), ][seq_len(nn), ]
          ggplot(res, aes(x=reorder(.data[[dcol]], -FDR), y=-log10(FDR))) +
            geom_col(fill="#5DADE2", width=0.8) + coord_flip() + theme_classic(base_size=fs) +
            labs(x=NULL, y="-log10(FDR)", title=paste0(meta$method, " — ", meta$cluster))
        } else {
          erc <- if ("enrichmentRatio" %in% names(res)) "enrichmentRatio" else
                 if ("normalizedEnrichmentScore" %in% names(res)) "normalizedEnrichmentScore" else "FDR"
          res <- res[order(-res[[erc]]), ][seq_len(nn), ]
          ggplot(res, aes(x=reorder(.data[[dcol]], .data[[erc]]), y=.data[[erc]])) +
            geom_col(fill="#D3D3D3", width=0.8) + coord_flip() + theme_classic(base_size=fs) +
            labs(x=NULL, y=erc, title=paste0(meta$method, " — ", meta$cluster))
        }
      },

      # ── Annotation (CellMarker / reference) ────────────────────────────────
      "ann_fisher_hm_pdf" = {
        req(s$ann_fisher)
        r <- s$ann_fisher
        r$log2OR <- log2(pmax(r$odds_ratio, 0) + 1)
        r$sig <- ifelse(r$p_adj_BH < 0.001,"***", ifelse(r$p_adj_BH<0.01,"**", ifelse(r$p_adj_BH<0.05,"*","")))
        ggplot(r, aes(x=cluster, y=cell_type, fill=log2OR)) +
          geom_tile(color="white") + geom_text(aes(label=sig), size=4) +
          scale_fill_gradient(low="white", high="#C0392B", na.value="grey90", name="log2(OR+1)") +
          theme_classic(base_size=fs) + theme(axis.text.x=element_text(angle=45,hjust=1)) +
          labs(title=paste0("Fisher enrichment — ", (s$ann_ref_meta$source %||% "reference")),
               x="Cluster", y="Reference cell type")
      },
      "ann_score_hm_pdf" = {
        req(s$ann_scores)
        m <- s$ann_scores
        df <- as.data.frame(as.table(as.matrix(m))); names(df) <- c("cluster","cell_type","score")
        ggplot(df, aes(x=cluster, y=cell_type, fill=score)) +
          geom_tile(color="white") +
          scale_fill_gradient2(low="#2166AC", mid="white", high="#B2182B", midpoint=0, name="Mean\nmodule score") +
          theme_classic(base_size=fs) + theme(axis.text.x=element_text(angle=45,hjust=1)) +
          labs(title="Activity scores (mean per cluster)", x="Cluster", y="Reference cell type")
      },

      # ── Trajectory (Slingshot) ─────────────────────────────────────────────
      "traj_curve_pdf" = {
        req(s$traj_sds, s$traj_pt)
        sds <- s$traj_sds; rd <- slingshot::reducedDim(sds)
        df <- data.frame(D1=rd[,1], D2=rd[,2], pseudotime=rowMeans(s$traj_pt, na.rm=TRUE))
        p <- ggplot(df, aes(D1, D2, color=pseudotime)) + geom_point(size=.pdf_pt(2), alpha=0.85) +
          viridis::scale_color_viridis(option="C", na.value="grey80", name="Pseudotime") +
          theme_classic(base_size=fs) +
          labs(title=paste0("Slingshot trajectory — ", s$traj_meta$reduction))
        for (cu in slingshot::slingCurves(sds)) {
          cc <- as.data.frame(cu$s[cu$ord, 1:2, drop=FALSE]); names(cc) <- c("D1","D2")
          p <- p + geom_path(data=cc, aes(D1, D2), color="black", linewidth=1, inherit.aes=FALSE)
        }
        p
      },
      "traj_umap_pdf" = {
        req(s$traj_pt); seu <- traj_seu(); req(seu, "umap" %in% names(seu@reductions))
        um <- Seurat::Embeddings(seu, reduction="umap")
        avg_pt <- rowMeans(s$traj_pt, na.rm=TRUE)
        common <- intersect(rownames(um), names(avg_pt))
        df <- data.frame(UMAP1=um[common,1], UMAP2=um[common,2], pseudotime=avg_pt[common])
        ggplot(df, aes(UMAP1, UMAP2, color=pseudotime)) + geom_point(size=.pdf_pt(2), alpha=0.85) +
          viridis::scale_color_viridis(option="C", na.value="grey85", name="Pseudotime") +
          theme_classic(base_size=fs) + labs(title="Pseudotime on UMAP")
      },
      "traj_gene_pdf" = {
        req(s$traj_pt, input$traj_gene, input$traj_lineage)
        seu <- traj_seu(); req(seu, input$traj_gene %in% rownames(seu))
        assay_use <- if ("SCT" %in% names(seu@assays)) "SCT" else input$s_assay
        ex <- as.numeric(Seurat::GetAssayData(seu, assay=assay_use, layer="data")[input$traj_gene, ])
        names(ex) <- colnames(seu)
        pt <- s$traj_pt[, input$traj_lineage]
        common <- intersect(names(pt), names(ex))
        df <- data.frame(pseudotime=pt[common], expr=ex[common])
        df <- df[is.finite(df$pseudotime) & is.finite(df$expr), ]
        ggplot(df, aes(pseudotime, expr)) + geom_point(alpha=0.5, size=.pdf_pt(1.8), color="#5B8DB8") +
          geom_smooth(method="loess", se=TRUE, color="#C0392B", fill="#F5B7B1") +
          theme_classic(base_size=fs) +
          labs(title=paste0(input$traj_gene, " along ", input$traj_lineage),
               x="Pseudotime", y=paste0(input$traj_gene, " (", assay_use, ")"))
      },

      # ── Explained variation ────────────────────────────────────────────────
      "ev_feature_box_pdf" = {
        req(s_ev_feature_result())
        .build_ev_feature_box(fs)
      },

      "ev_heatmap_pdf" = {
        req(s_ev_result())
        r2  <- s_ev_result()
        df_h <- as.data.frame(r2) %>% tibble::rownames_to_column("Covariate") %>%
          tidyr::pivot_longer(-Covariate,names_to="PC",values_to="R2")
        df_h$PC <- factor(df_h$PC,levels=paste0("PC",seq_len(ncol(r2))))
        ggplot(df_h,aes(x=PC,y=Covariate,fill=R2))+geom_tile(color="white")+
          scale_fill_gradient2(low="white",mid="#3498DB",high="#E74C3C",midpoint=25,na.value="grey90",name="R² (%)")+
          theme_minimal(base_size=fs)+theme(axis.text.x=element_text(angle=45,hjust=1))+
          labs(title="Explained Variation — log₂ data",x="PC",y="")
      },
      "ev_bar_pdf" = {
        req(s_ev_result())
        r2 <- s_ev_result()
        # Mirror output$s_ev_bar exactly, including the Residual bar and the
        # weighted/unweighted axis label, so the PDF matches the screen.
        wts <- s$ev_pc_weights
        if (!is.null(wts) && length(wts) == ncol(r2) &&
            all(colnames(r2) %in% names(wts))) {
          wts  <- wts[colnames(r2)]
          tot  <- as.numeric(r2 %*% wts); names(tot) <- rownames(r2)
          xlab <- "Weighted average r² sum of total explained variance"
        } else {
          tot  <- rowSums(r2, na.rm=TRUE)
          xlab <- "Sum r² (%, unweighted — re-run for PVCA-weighted totals)"
        }
        resid <- max(0, 100 - sum(tot, na.rm=TRUE))
        tot   <- c(tot, "Residual" = resid)
        df_b  <- data.frame(Covariate=names(tot), Total_R2=tot) %>% arrange(desc(Total_R2))
        df_b$Covariate <- factor(df_b$Covariate, levels=rev(df_b$Covariate))
        ggplot(df_b, aes(x=Total_R2, y=Covariate, fill=Total_R2)) +
          geom_bar(stat="identity", alpha=0.85) +
          scale_fill_gradient(low="#85C1E9", high="#E74C3C", name="total r² (%)") +
          theme_classic(base_size=fs) +
          labs(x=xlab, y="", title="Total Explained Variation")
      },

      # Header entries and unknown keys
      { NULL }
    )
  }

  output$s_dl_pdf <- downloadHandler(
    filename = function() {
      safe_key <- gsub("[^a-zA-Z0-9_]","_", input$s_pdf_plot)
      paste0("scpviz_", safe_key, "_", Sys.Date(), ".pdf")
    },
    content = function(file) {
      w  <- max(2, min(30, .num(input$s_pdf_w,   8)))
      h  <- max(2, min(30, .num(input$s_pdf_h,   6)))
      fs <- max(8, min(24, .num(input$s_pdf_res, 12)))
      drew <- FALSE
      p <- tryCatch(s_render_plot_for_pdf(input$s_pdf_plot, w, h, fs),
                    error=function(e) structure(list(msg=conditionMessage(e)), class="pdf_err"))
      # Prefer ggsave for ggplot / patchwork objects — it renders reliably to a
      # fresh device, unlike print() on some combined/patchwork objects (which
      # was producing valid-but-blank PDFs). Fall back to a device+print for
      # base-graphics plots, and always draw SOMETHING so the PDF is never a
      # silent blank page.
      is_gg <- inherits(p, c("ggplot","patchwork","gg","ggassemble"))
      if (is_gg) {
        drew <- tryCatch({ ggplot2::ggsave(file, plot=p, width=w, height=h,
                                           device=.pdf_dev(), limitsize=FALSE); TRUE },
                         error=function(e) FALSE)
      }
      if (!drew) {
        .pdf_open(file, w, h)
        tryCatch({
          if (inherits(p, "pdf_basefn")) {
            # Base-graphics export: the device is open now, so draw into it.
            p$fn()
          } else if (inherits(p, "pdf_err")) {
            msg <- p$msg
            if (!nzchar(msg))
              msg <- paste0("A required input is missing.\nGenerate this plot on its own tab ",
                            "first,\nthen check the selections it depends on.")
            plot.new(); text(0.5,0.5, paste0("Plot error:\n", msg), col="red", cex=1)
          } else if (is.null(p)) {
            plot.new(); text(0.5,0.5,
              paste0("No plot produced for '", input$s_pdf_plot,
                     "'.\nRun the analysis that generates it first,\nor check the required selections."),
              col="grey30", cex=1)
          } else {
            print(p)   # base graphics or other printable object
          }
        }, error=function(e){ plot.new(); text(0.5,0.5, paste0("Render error:\n", conditionMessage(e)), col="red") })
        dev.off()
      }
      s_log(paste0("PDF exported: ", input$s_pdf_plot, " (", w, "×", h, " in",
                   ", base font ", fs, "pt",
                   if (.num(input$s_pdf_pt, 0) > 0)
                     paste0(", point size ", .num(input$s_pdf_pt, 0)) else "", ")",
                   if(is_gg && drew) " [ggsave]" else " [device]"))
    }
  )

  # ── ⑫ Matrix Inspector ──────────────────────────────────────────────────────

  output$s_inspect_assay_ui <- renderUI({
    req(s$seu)
    assays <- names(s$seu@assays)
    selectInput("s_inspect_assay","Assay:", choices=assays,
                selected=if(input$s_assay %in% assays) input$s_assay else assays[1])
  })

  output$s_inspect_layer_ui <- renderUI({
    req(s$seu, input$s_inspect_assay)
    assay_obj <- tryCatch(s$seu@assays[[input$s_inspect_assay]], error=function(e) NULL)
    req(assay_obj)
    layers <- tryCatch(names(assay_obj@layers), error=function(e) {
      # Seurat v4 fallback — report the classic slots
      slots_avail <- c()
      if (!is.null(tryCatch(assay_obj@counts, error=function(e) NULL)) &&
          length(assay_obj@counts) > 0) slots_avail <- c(slots_avail, "counts")
      if (!is.null(tryCatch(assay_obj@data,   error=function(e) NULL)) &&
          length(assay_obj@data)   > 0) slots_avail <- c(slots_avail, "data")
      if (!is.null(tryCatch(assay_obj@scale.data, error=function(e) NULL)) &&
          length(assay_obj@scale.data) > 0) slots_avail <- c(slots_avail, "scale.data")
      slots_avail
    })
    if (!length(layers)) layers <- "counts"
    # For VSN/scpmed the data layer already IS the NA-aware normalized matrix, so
    # only the NA→0 comparison view is synthetic. Keeping it makes the effect of
    # the substitution inspectable side by side with the real layer.
    method <- input$s_norm_method %||% "sct"
    if (method %in% .NA_AWARE && input$s_inspect_assay == input$s_assay) {
      layers <- c(layers, "data (NA→0)")
    }
    # Sensible default: prefer data > counts > scale.data
    def <- if ("data" %in% layers) "data" else
           if ("counts" %in% layers) "counts" else layers[1]
    selectInput("s_inspect_layer","Layer:", choices=layers, selected=def)
  })

  output$s_inspect_feat_ui <- renderUI({
    req(s$seu, input$s_inspect_assay)
    feats <- rownames(s$seu@assays[[input$s_inspect_assay]])
    n <- length(feats)
    tagList(
      tags$p(paste0(n, " features available"), style="font-size:11px;color:#888;margin:0;"),
      selectizeInput("s_inspect_feats","Features to show (up to 20):",
                     choices=feats, selected=head(feats, 6),
                     multiple=TRUE, options=list(maxItems=20,
                       placeholder="Select features..."))
    )
  })

  # Reactive: pull the selected layer matrix and melt to long format
  s_inspect_data <- eventReactive(input$s_inspect_btn, {
    req(s$seu, input$s_inspect_assay, input$s_inspect_layer, input$s_inspect_feats)
    assay_obj <- s$seu@assays[[input$s_inspect_assay]]
    feats     <- input$s_inspect_feats

    # Synthetic layers for VSN/scpmed: read the stashed normalized matrix
    # (NA-aware) or its NA→0 version, so the two can be compared directly.
    if (identical(input$s_inspect_layer, "data (NA→0)")) {
      mat <- .norm_mat(s$seu, input$s_inspect_assay)
      if (!is.null(mat)) mat[is.na(mat)] <- 0
    } else {
    # Try Seurat v5 LayerData first, fall back to v4 slot access
    mat <- tryCatch(
      SeuratObject::LayerData(assay_obj, layer=input$s_inspect_layer),
      error=function(e) tryCatch(
        switch(input$s_inspect_layer,
               "counts"     = assay_obj@counts,
               "data"       = assay_obj@data,
               "scale.data" = assay_obj@scale.data,
               stop("layer not found")),
        error=function(e2) NULL))
    }
    req(!is.null(mat), nrow(mat) > 0)

    # Subset to selected features (robust to sparse matrix)
    feats_ok <- intersect(feats, rownames(mat))
    req(length(feats_ok) > 0)
    sub <- as.matrix(mat[feats_ok, , drop=FALSE])

    if (isTRUE(input$s_inspect_log)) sub <- log1p(sub)

    # Attach condition metadata for violin coloring
    cond_col <- if ("Condition" %in% names(s$seu@meta.data)) "Condition" else
                names(s$seu@meta.data)[sapply(s$seu@meta.data,
                  function(x) (is.character(x)||is.factor(x)) &&
                               length(unique(x)) >= 2)][1]

    # Melt to long data frame: Feature × Cell × Value
    df <- as.data.frame(t(sub))
    df$Cell <- rownames(df)
    if (!is.na(cond_col) && cond_col %in% names(s$seu@meta.data))
      df$Condition <- s$seu@meta.data[df$Cell, cond_col]
    else
      df$Condition <- "all"
    df <- tidyr::pivot_longer(df, cols=all_of(feats_ok),
                               names_to="Feature", values_to="Value")
    list(df=df, feats=feats_ok, layer=input$s_inspect_layer,
         assay=input$s_inspect_assay, log=isTRUE(input$s_inspect_log),
         n_cells=ncol(mat))
  })

  output$s_inspect_summary_ui <- renderUI({
    d <- tryCatch(s_inspect_data(), error=function(e) NULL)
    req(d)
    df <- d$df
    val_lab <- if(d$log) "log1p(value)" else "value"
    stats <- df %>%
      dplyr::group_by(Feature) %>%
      dplyr::summarise(
        Min    = round(min(Value, na.rm=TRUE), 4),
        Median = round(median(Value, na.rm=TRUE), 4),
        Mean   = round(mean(Value, na.rm=TRUE), 4),
        Max    = round(max(Value, na.rm=TRUE), 4),
        `% NA`   = round(100 * mean(is.na(Value)), 1),
        `% zero` = round(100 * mean(Value == 0, na.rm=TRUE), 1),
        .groups="drop")
    div(style="background:#fff;border:1px solid #ddd;border-radius:4px;padding:8px;margin:8px 0;",
      tags$p(tags$b(paste0("Assay: ", d$assay, "  |  Layer: ", d$layer,
                           "  |  Cells: ", d$n_cells,
                           if(d$log) "  |  [log1p display]" else "")),
             style="font-size:12px;color:#333;margin-bottom:4px;"),
      tags$div(style="overflow-x:auto;",
        tags$table(class="table table-condensed table-bordered",
          style="font-size:12px;width:auto;margin:0;",
          tags$thead(tags$tr(lapply(c("Feature","Min","Median","Mean","Max","% NA","% zero"),
                                    function(h) tags$th(h)))),
          tags$tbody(apply(stats, 1, function(r)
            tags$tr(lapply(r, function(v) tags$td(v)))))
        )
      )
    )
  })

  output$s_inspect_hist <- renderPlot({
    d <- tryCatch(s_inspect_data(), error=function(e) NULL)
    req(d)
    y_lab <- if(d$log) "log1p(value)" else "value"
    ggplot2::ggplot(d$df, ggplot2::aes(x=Value, fill=Feature)) +
      ggplot2::geom_histogram(bins=50, alpha=0.65, position="identity") +
      ggplot2::facet_wrap(~Feature, scales="free", ncol=3) +
      ggplot2::labs(title=paste0(d$assay," / ",d$layer," — distribution"),
                    x=y_lab, y="cells") +
      ggplot2::theme_classic(base_size=11) +
      ggplot2::theme(legend.position="none",
                     strip.background=ggplot2::element_rect(fill="#eaf2ff"))
  })

  output$s_inspect_violin <- renderPlot({
    d <- tryCatch(s_inspect_data(), error=function(e) NULL)
    req(d)
    y_lab <- if(d$log) "log1p(value)" else "value"
    pal <- s$palette[["Condition"]]
    ggplot2::ggplot(d$df,
      ggplot2::aes(x=Condition, y=Value, fill=Condition)) +
      ggplot2::geom_violin(alpha=0.7, scale="width") +
      ggplot2::geom_boxplot(width=0.12, outlier.shape=NA,
                            fill="white", alpha=0.7, color="black") +
      ggplot2::facet_wrap(~Feature, scales="free_y", ncol=3) +
      { if(!is.null(pal)) ggplot2::scale_fill_manual(values=pal) } +
      ggplot2::labs(title=paste0(d$assay," / ",d$layer," — by condition"),
                    x=NULL, y=y_lab) +
      ggplot2::theme_classic(base_size=11) +
      ggplot2::theme(legend.position="none",
                     axis.text.x=ggplot2::element_text(angle=30,hjust=1),
                     strip.background=ggplot2::element_rect(fill="#eaf2ff"))
  })

  output$s_inspect_tbl <- DT::renderDT({
    d <- tryCatch(s_inspect_data(), error=function(e) NULL)
    req(d)
    # Wide table: features as columns, cells as rows
    wide <- d$df %>%
      dplyr::select(Cell, Condition, Feature, Value) %>%
      tidyr::pivot_wider(names_from=Feature, values_from=Value)
    DT::datatable(wide,
      options=list(pageLength=10, scrollX=TRUE, dom="tip"),
      rownames=FALSE) %>%
      DT::formatRound(d$feats, 4)
  })

  # ══ Save / restore session ═════════════════════════════════════════════════
  # Objects that are large, cheap to rebuild, or both. Dropped from the
  # "results only" scope so a session that still restores every RESULT fits in
  # a few MB instead of hundreds.
  .SESS_HEAVY <- c("seu", "seu_int", "int_obj_list", "int_anchors",
                   "int_data_snapshot", "clustree_seu", "i_clustree_seu",
                   "traj_sds", "sweep_plots", "js_result")

  # Inputs that must NOT be replayed on restore:
  #   action buttons  carry a click COUNTER, and writing it back would fire every
  #                   observeEvent watching it — re-running normalization,
  #                   integration and marker tests on load
  #   fileInput       values are a data.frame pointing at a temp upload path that
  #                   no longer exists in a later session
  #   plotly events   selection state, meaningless without the original figure
  .sess_input_ok <- function(nm, v) {
    if (is.null(v)) return(FALSE)
    if (inherits(v, "shinyActionButtonValue")) return(FALSE)
    if (is.data.frame(v)) return(FALSE)
    if (grepl("^plotly_|^\\.clientdata|_rows_|_columns_|_cell_|_search|_state$", nm)) return(FALSE)
    if (grepl("^s_up_|^s_dl_", nm)) return(FALSE)
    is.atomic(v) && length(v) >= 1
  }

  .sess_snapshot_inputs <- function() {
    il <- tryCatch(reactiveValuesToList(input), error=function(e) list())
    keep <- vapply(names(il), function(nm) .sess_input_ok(nm, il[[nm]]), logical(1))
    il[keep]
  }

  output$s_dl_session <- downloadHandler(
    filename = function()
      paste0("scpviz_session_",
             if (identical(input$s_sess_scope, "results")) "results_" else "full_",
             format(Sys.time(), "%Y%m%d_%H%M"), ".rds"),
    content = function(file) {
      sl <- tryCatch(reactiveValuesToList(s), error=function(e) list())
      full <- !identical(input$s_sess_scope, "results")
      if (!full) sl[intersect(.SESS_HEAVY, names(sl))] <- NULL
      blob <- list(
        scpviz_session = TRUE,
        schema         = 1L,
        saved_at       = Sys.time(),
        scope          = if (full) "all" else "results",
        state          = sl,
        inputs         = .sess_snapshot_inputs()
      )
      saveRDS(blob, file, compress = "xz")
      s_log(paste0("Session saved (", blob$scope, ", ",
                   length(blob$state), " state slots, ",
                   length(blob$inputs), " widget values)"))
    }
  )

  sess_msg <- reactiveVal(NULL)

  observeEvent(input$s_up_session, {
    f <- input$s_up_session; req(f)
    blob <- tryCatch(readRDS(f$datapath), error = function(e) e)
    if (inherits(blob, "error")) {
      sess_msg(list(ok=FALSE, txt=paste0("Could not read that file: ", conditionMessage(blob))))
      return(invisible(NULL))
    }
    if (!is.list(blob) || !isTRUE(blob$scpviz_session)) {
      sess_msg(list(ok=FALSE, txt=paste0(
        "That .rds is not an SCP-Viz session. A plain Seurat .rds cannot be ",
        "restored here \u2014 load it through ⑤ instead.")))
      return(invisible(NULL))
    }
    # Restore state first, so anything an input change triggers sees the new data.
    st <- blob$state %||% list()
    for (nm in names(st)) s[[nm]] <- st[[nm]]

    # Then replay widgets. sendInputMessage on a control that does not exist yet
    # (anything inside a renderUI) is a silent no-op, so dynamic selectors come
    # back only once their panel has rendered; they are reported as deferred
    # rather than failed.
    ins <- blob$inputs %||% list()
    n_sent <- 0L
    for (nm in names(ins)) {
      ok <- tryCatch({ session$sendInputMessage(nm, list(value = ins[[nm]])); TRUE },
                     error = function(e) FALSE)
      if (isTRUE(ok)) n_sent <- n_sent + 1L
    }
    sess_msg(list(ok=TRUE, scope=blob$scope %||% "?", saved=blob$saved_at,
                  n_state=length(st), n_inputs=n_sent,
                  no_objects=!("seu" %in% names(st))))
    s_log(paste0("Session restored (", blob$scope %||% "?", ", ",
                 length(st), " state slots, ", n_sent, " widget values)"))
  })

  output$s_sess_restore_msg <- renderUI({
    m <- sess_msg(); if (is.null(m)) return(NULL)
    if (!isTRUE(m$ok))
      return(tags$p(tags$b("Restore failed. "), m$txt,
                    style="color:#C0392B;font-size:12px;"))
    tagList(
      tags$p(tags$b("Session restored."), style="color:#1E8449;font-size:13px;margin-bottom:2px;"),
      tags$p(tags$small(paste0(
        "Saved ", format(m$saved, "%Y-%m-%d %H:%M"), " (", m$scope, "). ",
        m$n_state, " state slots and ", m$n_inputs, " widget values applied.")),
        style="color:#7f8c8d;margin:0;"),
      if (isTRUE(m$no_objects))
        tags$p(tags$small(paste0(
          "This was a results-only save, so there is no Seurat object. Tables and ",
          "result-driven panels work; anything that plots cells (UMAP, violins, ",
          "feature plots) needs the object rebuilt in ⑤–⑥.")),
          style="color:#B9770E;margin-top:4px;"),
      tags$p(tags$small(paste0(
        "Controls that live inside a dynamically rendered panel only take their ",
        "saved value once that panel has been opened, so visit the tabs you were ",
        "working in and check the key settings before re-running anything.")),
        style="color:#7f8c8d;margin-top:4px;")
    )
  })
  
    # file.copy rather than readBin/writeBin: it streams, so a large PDF is not
  # pulled into memory, and it preserves the bytes exactly.
  .serve_guide <- function(path, fallback_name) {
    downloadHandler(
      filename = function() if (is.null(path)) fallback_name else basename(path),
      content  = function(file) {
        if (is.null(path) || !file.exists(path))
          stop("Guide PDF not found on disk. Expected: ", fallback_name, call. = FALSE)
        ok <- file.copy(path, file, overwrite = TRUE)
        if (!isTRUE(ok)) stop("Could not read ", basename(path), call. = FALSE)
      },
      contentType = "application/pdf"
    )
  }

  output$dl_guide_short <- .serve_guide(.GUIDE_SHORT, GUIDE_SHORT_FILE)
  output$dl_guide_long  <- .serve_guide(.GUIDE_LONG,  GUIDE_LONG_FILE)

  output$s_dl_rds <- downloadHandler(
    filename=function()paste0("seurat_",input$s_exp_which,"_",Sys.Date(),".rds"),
    content=function(file){
      obj<-if(input$s_exp_which=="int"&&!is.null(s$seu_int))s$seu_int else s$seu
      req(obj); saveRDS(obj,file); s_log(paste0("Exported Seurat .rds (",input$s_exp_which,")"))
    }
  )
  output$s_dl_mat <- downloadHandler(
    filename=function()paste0("matrix_",input$s_exp_mat,"_",Sys.Date(),".csv"),
    content=function(file){
      req(s$seu)
      mat<-switch(input$s_exp_mat,
        "sct"    =if("SCT"%in%names(s$seu@assays))
                    as.matrix(Seurat::GetAssayData(s$seu, assay="SCT", layer="scale.data")) else NULL,
        "raw"    =as.matrix(Seurat::GetAssayData(s$seu,assay=input$s_assay,layer="counts")),
        "lognorm"=as.matrix(Seurat::GetAssayData(s$seu,assay=input$s_assay,layer="data")),
        # Both read the DATA LAYER, so the exported matrix is exactly what was
        # tested and plotted. All-NA rows (features the transform dropped) are
        # removed by .norm_mat().
        "norm_na"  =.norm_mat(s$seu),
        "norm_zero"={mm <- .norm_mat(s$seu); if (!is.null(mm)) mm[is.na(mm)] <- 0; mm}
      )
      validate(need(!is.null(mat),
        "Selected matrix not available — VSN/scp-median options require a completed run."))
      readr::write_csv(as.data.frame(mat)%>%tibble::rownames_to_column("protein"),file)
      s_log(paste0("Matrix exported (",input$s_exp_mat,")"))
    }
  )
  # VSN/scp-median variance-vs-mean table (the variable-features plot basis)
  output$s_dl_vsn_stats <- downloadHandler(
    filename=function()paste0("vsn_variance_mean_",Sys.Date(),".csv"),
    content=function(file){
      diag <- s$intensity_diag
      validate(need(!is.null(diag) && !is.null(diag$mat),
        "Run VSN or scp-median normalization first."))
      if (!is.null(diag$sel_stats)) {
        df <- diag$sel_stats
      } else {
        m <- diag$mat
        df <- data.frame(gene=rownames(m),
                         mean=rowMeans(m,na.rm=TRUE),
                         variance=apply(m,1,stats::var,na.rm=TRUE),
                         nobs=rowSums(!is.na(m)), stringsAsFactors=FALSE)
      }
      df$is_variable <- df$gene %in% (diag$vf %||% character(0))
      readr::write_csv(df, file)
      s_log("VSN/scp-median variance-vs-mean table exported")
    }
  )
  # Selected variable features (with rank)
  output$s_dl_vsn_vf <- downloadHandler(
    filename=function()paste0("vsn_variable_features_",Sys.Date(),".csv"),
    content=function(file){
      diag <- s$intensity_diag
      validate(need(!is.null(diag) && !is.null(diag$vf) && length(diag$vf)>0,
        "No variable features — run VSN or scp-median normalization first."))
      readr::write_csv(data.frame(rank=seq_along(diag$vf), gene=diag$vf,
                                  stringsAsFactors=FALSE), file)
      s_log("VSN/scp-median variable features exported")
    }
  )
  # Raw intensity matrix as captured at load (NA-aware, pre-ceiling)
  output$s_dl_raw_int <- downloadHandler(
    filename=function()paste0("raw_intensity_NAaware_",Sys.Date(),".csv"),
    content=function(file){
      validate(need(!is.null(s$prt_int_raw),
        "Raw intensity matrix not available — reload data so the raw copy is captured."))
      readr::write_csv(as.data.frame(as.matrix(s$prt_int_raw))%>%
                         tibble::rownames_to_column("protein"), file)
      s_log("Raw intensity matrix (NA-aware) exported")
    }
  )
  # Which object the embedding comes from follows the same toggle as the .rds
  # download. Previously both always read s$seu, so after integration the file did
  # not match what was on screen.
  .exp_obj <- function() {
    if (identical(input$s_exp_which %||% "unint", "int") && !is.null(s$seu_int)) s$seu_int else s$seu
  }
  .exp_tag <- function() if (identical(input$s_exp_which %||% "unint", "int") &&
                             !is.null(s$seu_int)) "integrated" else "unintegrated"

  output$s_dl_meta <- downloadHandler(
    filename=function() paste0("metadata_", .exp_tag(), "_", Sys.Date(), ".csv"),
    content=function(file){
      ob <- .exp_obj(); req(ob)
      readr::write_csv(ob@meta.data %>% tibble::rownames_to_column("Cell"), file)
      s_log(paste0("Metadata exported from the ", .exp_tag(), " object (",
                   ncol(ob), " cells, ", ncol(ob@meta.data), " columns)"))})
  # Marker results are two distinct tables, not one object's view, so this follows
  # the toggle too: ⑨ results live in s$markers and ⑫ results in s$int_markers.
  output$s_dl_mk   <- downloadHandler(
    filename=function() paste0("markers_",
      if (identical(input$s_exp_which %||% "unint", "int")) "integrated" else "unintegrated",
      "_", Sys.Date(), ".csv"),
    content=function(file){
      use_int <- identical(input$s_exp_which %||% "unint", "int")
      mk <- if (use_int) s$int_markers else s$markers
      validate(need(!is.null(mk) && nrow(mk) > 0,
                    if (use_int) "No integrated marker results yet \u2014 run \u246b."
                    else "No marker results yet \u2014 run \u2468."))
      readr::write_csv(mk, file)
      s_log(paste0("Markers exported: ", if (use_int) "\u246b integrated" else "\u2468",
                   " (", nrow(mk), " rows)"))})
  output$s_dl_pca  <- downloadHandler(
    filename=function() paste0("pca_emb_", .exp_tag(), "_", Sys.Date(), ".csv"),
    content=function(file){
      ob <- .exp_obj(); req(ob)
      # On the integrated object the clustering reduction may be integrated.cca
      # rather than pca; export whichever the tabs actually used.
      rd <- if (identical(.exp_tag(), "integrated") &&
                "integrated.cca" %in% names(ob@reductions)) "integrated.cca"
            else if ("pca" %in% names(ob@reductions)) "pca" else NULL
      validate(need(!is.null(rd), "No PCA reduction on the selected object."))
      readr::write_csv(as.data.frame(Seurat::Embeddings(ob, rd)) %>%
                         tibble::rownames_to_column("Cell"), file)
      s_log(paste0("Embeddings exported: ", rd, " from the ", .exp_tag(), " object"))})
  output$s_dl_umap <- downloadHandler(
    filename=function() paste0("umap_emb_", .exp_tag(), "_", Sys.Date(), ".csv"),
    content=function(file){
      ob <- .exp_obj(); req(ob)
      validate(need("umap" %in% names(ob@reductions),
                    "No UMAP on the selected object \u2014 run \u2466 (or \u246a Step 9)."))
      readr::write_csv(as.data.frame(Seurat::Embeddings(ob, "umap")) %>%
                         tibble::rownames_to_column("Cell"), file)
      s_log(paste0("UMAP exported from the ", .exp_tag(), " object"))})
  output$s_dl_ev   <- downloadHandler(filename=function()paste0("exp_var_",Sys.Date(),".csv"),  content=function(file){req(s$ev_mat);readr::write_csv(as.data.frame(s$ev_mat)%>%tibble::rownames_to_column("Covariate"),file);s_log("Explained variation exported")})
  # ── ⑬ Pathway Analysis (WebGestaltR ORA / GSEA) ─────────────────────────────
  pw_markers <- reactive({
    if ((input$pw_source %||% "markers") == "int_markers") s$int_markers else s$markers
  })

  output$pw_cluster_ui <- renderUI({
    mk <- pw_markers()
    if (is.null(mk) || !"cluster" %in% names(mk))
      return(tags$p("Run a marker analysis first (⑨ or ⑫).",
                    style="color:#E74C3C;font-size:12px;"))
    cls <- sort(unique(as.character(mk$cluster)))
    selectInput("pw_cluster","Cluster / contrast to test:", choices=cls, selected=cls[1])
  })

  # ── ID column selector: which prt.map column to map feature IDs to ──────────
  output$pw_idcol_ui <- renderUI({
    if (is.null(s$prt_map)) {
      return(tags$p(tags$small("No prt.map loaded — feature IDs (row names) are used as-is. ",
        "Set ID type above to match what those row names are."),
        style="color:grey;font-size:11px;"))
    }
    cols <- names(s$prt_map)
    # sensible default: a Genes/symbol column if present
    def <- intersect(c("Genes","gene","Gene","symbol","Symbol"), cols)
    def <- if (length(def)) def[1] else cols[1]
    tagList(
      selectInput("pw_idcol", "Map feature IDs to this prt.map column:",
                  choices=c("(use feature IDs / accessions as-is)"="__asis__",
                            setNames(cols, cols)),
                  selected=def),
      tags$p(tags$small("The chosen column supplies the IDs sent to WebGestalt for BOTH the ",
        "interest list and the background. Make sure 'ID type' above matches it (e.g. a ",
        "Genes column = Gene symbol; a UniProt column = UniProt accession)."),
        style="color:grey;font-size:11px;margin-top:2px;")
    )
  })

  pw_show_preview <- reactiveVal(FALSE)
  observeEvent(input$pw_preview_map, { pw_show_preview(!pw_show_preview()) })

  output$pw_map_preview <- renderUI({
    if (!isTRUE(pw_show_preview())) return(NULL)
    if (is.null(s$prt_map)) {
      return(div(style="background:#fdf6e3;border:1px solid #f0ad4e;border-radius:4px;padding:8px;margin:6px 0;",
        tags$small("prt.map not loaded — feature IDs (row names) are used as-is.")))
    }
    md_cols <- if (!is.null(s$seu)) names(s$seu@meta.data) else character(0)
    div(style="background:#fff;border:1px solid #ddd;border-radius:4px;padding:8px;margin:6px 0;",
      tags$p(tags$b("prt.map — first rows (row name = feature ID):"),
             style="font-size:11px;margin:0 0 4px 0;"),
      div(style="overflow-x:auto;", DTOutput("pw_map_dt")),
      tags$p(tags$small("Columns you can map to: ",
                        paste(names(s$prt_map), collapse=", ")),
             style="color:#555;font-size:10px;margin:6px 0 2px 0;"),
      tags$p(tags$b("meta.samples columns:"), style="font-size:11px;margin:6px 0 2px 0;"),
      tags$p(tags$small(if(length(md_cols)) paste(md_cols, collapse=", ") else "(no object built yet)"),
             style="color:#555;font-size:10px;margin:0;")
    )
  })

  output$pw_map_dt <- renderDT({
    req(pw_show_preview(), s$prt_map)
    pm <- utils::head(s$prt_map, 8)
    # Keep it readable: show row name + the ID-relevant columns first, truncate
    # long free-text columns (e.g. ProteinDescriptions) so the table stays legible.
    show_cols <- names(pm)
    df <- data.frame(feature_id = rownames(pm), pm[, show_cols, drop=FALSE],
                     check.names = FALSE, stringsAsFactors = FALSE)
    # truncate any long text cells for display
    df[] <- lapply(df, function(col) {
      col <- as.character(col)
      ifelse(nchar(col) > 40, paste0(substr(col, 1, 40), "…"), col)
    })
    datatable(df, rownames = FALSE,
              options = list(pageLength = 8, dom = "t", scrollX = TRUE,
                             ordering = FALSE),
              class = "compact stripe")
  })

  # ── Map feature IDs -> the WebGestalt ID space via the chosen prt.map column ──
  # Column-driven (not guessed): the user picks which prt.map column holds the IDs
  # matching their selected WebGestalt ID type. Falls back to feature IDs as-is.
  # Returns a data.frame(orig, id) so the interest list stays aligned to markers.
  .pw_map_ids <- function(ids) {
    orig <- sub(";.*", "", as.character(ids))          # leading token of query
    out  <- orig
    col  <- input$pw_idcol %||% "__asis__"
    if (!is.null(s$prt_map) && col != "__asis__" && col %in% names(s$prt_map)) {
      pm  <- s$prt_map
      lead <- function(x) sub(";.*", "", as.character(x))   # leading token helper
      tgt  <- lead(pm[[col]])                          # target IDs (leading only)

      # Candidate key spaces to match the query against: prt.map rownames plus
      # every column, each reduced to its LEADING token so that semicolon-joined
      # protein groups (e.g. 'P12345;Q67890' or 'Cyp2b9;Cyp2b10') still match a
      # single query ID. This is the fix for the Genes-vs-ProteinGroups mismatch.
      key_spaces <- c(list(lead(rownames(pm))),
                      lapply(names(pm), function(cn) lead(pm[[cn]])))
      mapped <- rep(NA_character_, length(orig))
      for (ks in key_spaces) {
        idx <- match(orig, ks)                         # position in prt.map rows
        take <- is.na(mapped) & !is.na(idx)
        if (any(take)) mapped[take] <- tgt[idx[take]]
        if (!anyNA(mapped)) break
      }
      out <- ifelse(is.na(mapped) | mapped=="", orig, mapped)
    }
    out <- sub(";.*", "", as.character(out))            # leading token of result
    out <- sub("[._][0-9]+$", "", out)                  # strip make.unique suffixes
    data.frame(orig=orig, id=out, stringsAsFactors=FALSE)
  }
  # Convenience: unique mapped IDs only (for background)
  .pw_ids_vec <- function(ids) {
    v <- .pw_map_ids(ids)$id
    unique(v[!is.na(v) & v != ""])
  }

  observeEvent(input$pw_run, {
    mk <- pw_markers()
    if (is.null(mk) || !nrow(mk)) {
      showNotification("No marker results — run ⑨ or ⑫ first.", type="error", duration=8); return() }
    if (!requireNamespace("WebGestaltR", quietly=TRUE)) {
      showNotification("WebGestaltR not installed: install.packages('WebGestaltR').",
                       type="error", duration=12); return() }
    req(input$pw_cluster)
    sub_mk <- mk[as.character(mk$cluster) == input$pw_cluster, , drop=FALSE]
    if (!nrow(sub_mk)) { showNotification("No rows for that cluster.", type="error", duration=8); return() }

    method <- input$pw_method %||% "ORA"
    db     <- input$pw_db
    proj   <- paste0("scpviz_", input$pw_cluster, "_", method, "_", Sys.Date())

    tryCatch({
      if (method == "ORA") {
        # ── Gene selection by cutoffs (ROC-aware) ──
        d <- sub_mk
        is_roc <- .mk_is_roc(d)
        eff    <- .mk_effect(d)   # avg_log2FC or avg_diff
        if ((.num(input$pw_lfc_cut, 0)) > 0 && !is.na(eff))
          d <- d[!is.na(d[[eff]]) & abs(d[[eff]]) >= input$pw_lfc_cut, , drop=FALSE]
        if (isTRUE(input$pw_pos_only) && !is.na(eff))
          d <- d[!is.na(d[[eff]]) & d[[eff]] > 0, , drop=FALSE]
        sig_type <- input$pw_sig_type %||% "padj"
        if (is_roc) {
          # ROC: significance = power >= cutoff; top-N by power. p-value modes map
          # onto the power cutoff since ROC has no p-value.
          if (sig_type == "topn") {
            d <- d[order(-d$power), , drop=FALSE][seq_len(min(.num(input$pw_topn, 50), nrow(d))), , drop=FALSE]
          } else if ("power" %in% names(d)) {
            d <- d[!is.na(d$power) & d$power >= input$pw_p_cut, , drop=FALSE]
          }
        } else {
          if (sig_type == "padj" && "p_val_adj" %in% names(d))
            d <- d[!is.na(d$p_val_adj) & d$p_val_adj <= input$pw_p_cut, , drop=FALSE]
          else if (sig_type == "pval" && "p_val" %in% names(d))
            d <- d[!is.na(d$p_val) & d$p_val <= input$pw_p_cut, , drop=FALSE]
          else if (sig_type == "topn") {
            ord <- if ("p_val_adj" %in% names(d)) order(d$p_val_adj) else seq_len(nrow(d))
            d <- d[ord, , drop=FALSE][seq_len(min(.num(input$pw_topn, 50), nrow(d))), , drop=FALSE]
          }
        }
        interest <- .pw_ids_vec(d$gene)
        if (length(interest) < 3) {
          showNotification(paste0("Only ", length(interest),
            " genes passed the cutoffs — loosen the thresholds (p / FDR / log2FC) or use Top N."),
            type="error", duration=12); return() }

        # ── Background (same ID mapping as interest) ──
        # ── Background ────────────────────────────────────────────────────────
        # ORA compares the significant set against the universe it was drawn from,
        # so the background determines the answer as much as the gene list does.
        #   all_filt   features present in the object = everything that COULD have
        #              been called. The defensible default.
        #   all_tested the rows the test returned. Note these already passed the
        #              min.pct / logFC pre-filters, so this universe is smaller
        #              and biased toward variable features; enrichment against it
        #              is conservative for abundance-related terms.
        #   all_raw    every feature in the ID map, including ones never quantified
        #              in this experiment. Those cannot be enriched, so they only
        #              inflate the background and make everything look more
        #              significant. Offered for comparison, not recommended.
        bg_mode <- input$pw_bg %||% "all_filt"
        bg <- switch(bg_mode,
          "all_raw"    = if (!is.null(s$prt_map)) .pw_ids_vec(rownames(s$prt_map))
                         else .pw_ids_vec(rownames(s$seu)),
          "all_filt"   = .pw_ids_vec(rownames(s$seu)),
          "all_tested" = .pw_ids_vec(mk$gene[as.character(mk$cluster)==input$pw_cluster]),
          .pw_ids_vec(rownames(s$seu)))
        if (identical(bg_mode, "all_raw"))
          showNotification(paste0("Background = all mapped features, including any never ",
                                  "quantified here. Those cannot be enriched, so p-values ",
                                  "will be optimistic. 'All features in the object' is the ",
                                  "defensible choice."), type="warning", duration=12)
        bg <- unique(c(bg, interest))   # ensure interest is a subset of background
        s_log(paste0("ORA: ", length(interest), " interest / ", length(bg),
                     " background genes (mode=", bg_mode, "), db=", db,
                     ", organism=", input$pw_organism %||% "mmusculus"))

        organism <- input$pw_organism %||% "mmusculus"
        idtype   <- input$pw_idtype   %||% "genesymbol"
        run_ora <- function(sig_method) WebGestaltR::WebGestaltR(
            organism=organism, enrichMethod="ORA",
            interestGene=interest, interestGeneType=idtype,
            referenceGene=bg, referenceGeneType=idtype,
            enrichDatabase=db, fdrMethod="BH",
            sigMethod=sig_method,
            fdrThr=.num(input$pw_fdr_thr, 0.05),
            topThr=20,
            minNum=.num(input$pw_minnum, 5), maxNum=.num(input$pw_maxnum, 500),
            isOutput=FALSE, projectName=proj)

        withProgress(message="WebGestaltR ORA (needs internet)...", value=0.4, {
          res <- run_ora("fdr")
          # If nothing passed the FDR threshold, retry with sigMethod="top" so the
          # user sees the strongest (non-significant) sets rather than a bare error.
          used_top <- FALSE
          if (is.null(res) || nrow(res) == 0) {
            res <- tryCatch(run_ora("top"), error=function(e) NULL)
            used_top <- !is.null(res) && nrow(res) > 0
          }
        })
        if (is.null(res) || nrow(res) == 0) {
          showNotification(paste0(
            "ORA ran but returned no sets at all. Interest genes: ", length(interest),
            " | background: ", length(bg), ". Check that IDs are gene symbols (prt.map mapping) ",
            "and that the database matches the organism."), type="warning", duration=15)
          s_log(paste0("ORA empty: ", length(interest), " interest / ", length(bg),
                       " background / ", db))
          return()
        }
        if (isTRUE(used_top))
          showNotification(paste0("No sets passed FDR ", .num(input$pw_fdr_thr, 0.05),
            " — showing the top strongest sets instead (not significant). ",
            length(interest), " genes vs ", length(bg), " background."),
            type="warning", duration=12)
        # Optional weighted set cover to reduce redundancy
        if (isTRUE(input$pw_wsc) && nrow(res) > 1 &&
            all(c("overlapId","geneSet","pValue") %in% names(res))) {
          wsc <- tryCatch({
            ids_in_set <- sapply(res$overlapId, strsplit, split=";")
            names(ids_in_set) <- res$geneSet
            mlp <- -log(res$pValue); mlp[!is.finite(mlp)] <- -log(.Machine$double.eps)
            WebGestaltR::weightedSetCover(idsInSet=ids_in_set, costs=1/mlp,
                                          topN=min(20, nrow(res)))
          }, error=function(e) NULL)
          if (!is.null(wsc) && length(wsc$topSets))
            res$in_wsc <- res$geneSet %in% wsc$topSets
        }
        s$pw_result <- res
        s$pw_meta <- list(method="ORA", db=db, cluster=input$pw_cluster,
                          n_interest=length(interest), n_bg=length(bg))
        s_log(paste0("ORA: ", input$pw_cluster, " | ", length(interest),
                     " genes vs ", length(bg), " background | ", db, " | ",
                     nrow(res), " sets"))

      } else {  # GSEA
        d <- sub_mk
        d$sym <- .pw_map_ids(d$gene)$id          # column-driven mapping (aligned)
        # rank score: signed significance. For p-value tests this is
        # sign(log2FC)·−log10(p); for ROC it is sign(avg_diff)·power. Handled by
        # the ROC-aware helper so GSEA works on either result type.
        d$score <- .mk_rank_score(d)
        d <- d[is.finite(d$score) & !is.na(d$sym) & d$sym!="", ]
        d <- d[!duplicated(d$sym), ]
        rank_df <- data.frame(gene=d$sym, score=d$score, stringsAsFactors=FALSE)
        if (nrow(rank_df) < 10) {
          showNotification(paste0("Only ", nrow(rank_df), " genes could be ranked \u2014 GSEA ",
                                  "needs at least 10. Check that feature IDs map to gene ",
                                  "symbols, and note the marker table is already filtered by ",
                                  "min.pct / logFC, which shrinks the ranked list."),
                           type="error", duration=12)
          s_log(paste0("GSEA aborted: only ", nrow(rank_df), " ranked genes."))
          return()
        }
        organism <- input$pw_organism %||% "mmusculus"
        idtype   <- input$pw_idtype   %||% "genesymbol"
        withProgress(message="WebGestaltR GSEA (needs internet)...", value=0.4, {
          res <- tryCatch(WebGestaltR::WebGestaltR(
            organism=organism, enrichMethod="GSEA",
            interestGene=rank_df, interestGeneType=idtype,
            enrichDatabase=db, fdrThr=.num(input$pw_fdr_thr, 0.05),
            minNum=.num(input$pw_minnum, 5), maxNum=.num(input$pw_maxnum, 500),
            isOutput=FALSE, projectName=proj), error=function(e) NULL)
        })
        if (is.null(res) || nrow(res) == 0) {
          showNotification(paste0(
            "GSEA returned no sets at all with ", nrow(rank_df), " ranked genes. ",
            "This usually means too few genes mapped to the database, or all scores were ties. ",
            "Check gene-symbol mapping and try a broader database (e.g. Reactome)."),
            type="warning", duration=15)
          s_log(paste0("GSEA empty: ", nrow(rank_df), " ranked genes / ", db))
          return()
        }
        # Optional weighted set cover to reduce redundancy among enriched sets.
        # GSEA reports the leading-edge genes per set (leadingEdgeId / userId);
        # use those as set membership and -log(pValue) as the weight, mirroring
        # the ORA path so redundant overlapping sets collapse to a minimal cover.
        if (isTRUE(input$pw_wsc) && nrow(res) > 1) {
          gene_col <- intersect(c("leadingEdgeId","userId","overlapId"), names(res))[1]
          p_col    <- intersect(c("pValue","pval","FDR"), names(res))[1]
          if (!is.na(gene_col) && !is.na(p_col)) {
            wsc <- tryCatch({
              ids_in_set <- sapply(res[[gene_col]], strsplit, split=";")
              names(ids_in_set) <- res$geneSet
              mlp <- -log(as.numeric(res[[p_col]])); mlp[!is.finite(mlp)] <- -log(.Machine$double.eps)
              WebGestaltR::weightedSetCover(idsInSet=ids_in_set, costs=1/mlp,
                                            topN=min(20, nrow(res)))
            }, error=function(e) NULL)
            if (!is.null(wsc) && length(wsc$topSets))
              res$in_wsc <- res$geneSet %in% wsc$topSets
          }
        }
        s$pw_result <- res
        s$pw_meta <- list(method="GSEA", db=db, cluster=input$pw_cluster,
                          n_interest=nrow(rank_df), n_bg=NA)
        s_log(paste0("GSEA: ", input$pw_cluster, " | ", nrow(rank_df),
                     " ranked genes | ", db, " | ", nrow(res), " sets"))
      }
      showNotification(paste0(method, " done: ", nrow(s$pw_result), " gene sets."),
                       type="message", duration=6)
    }, error=function(e) {
      showNotification(paste0("Pathway analysis error: ", conditionMessage(e)),
                       type="error", duration=15)
      s_log(paste0("Pathway analysis FAILED: ", conditionMessage(e)))
    })
  })

  output$pw_status <- renderUI({
    if (is.null(s$pw_result) || is.null(s$pw_meta)) return(NULL)
    m <- s$pw_meta
    tags$p(paste0("✓ ", m$method, " | ", m$cluster, " | ", nrow(s$pw_result), " sets",
                  if(!is.na(m$n_bg)) paste0(" | ", m$n_interest, " vs ", m$n_bg, " bg")
                  else paste0(" | ", m$n_interest, " ranked")),
           style="color:#27AE60;font-size:12px;font-weight:600;")
  })

  # Live preview: how many genes pass the current ORA cutoffs (before running)
  output$pw_gene_preview <- renderUI({
    if ((input$pw_method %||% "ORA") != "ORA") return(NULL)
    mk <- pw_markers(); req(mk, input$pw_cluster)
    d <- mk[as.character(mk$cluster) == input$pw_cluster, , drop=FALSE]
    n_start <- nrow(d)
    is_roc <- .mk_is_roc(d); eff <- .mk_effect(d)
    if ((.num(input$pw_lfc_cut, 0)) > 0 && !is.na(eff))
      d <- d[!is.na(d[[eff]]) & abs(d[[eff]]) >= input$pw_lfc_cut, , drop=FALSE]
    if (isTRUE(input$pw_pos_only) && !is.na(eff))
      d <- d[!is.na(d[[eff]]) & d[[eff]] > 0, , drop=FALSE]
    st <- input$pw_sig_type %||% "padj"
    if (is_roc) {
      if (st == "topn") d <- utils::head(d[order(-d$power), ], .num(input$pw_topn, 50))
      else if ("power" %in% names(d)) d <- d[!is.na(d$power) & d$power >= input$pw_p_cut, , drop=FALSE]
    } else if (st == "padj" && "p_val_adj" %in% names(d))
      d <- d[!is.na(d$p_val_adj) & d$p_val_adj <= input$pw_p_cut, , drop=FALSE]
    else if (st == "pval" && "p_val" %in% names(d))
      d <- d[!is.na(d$p_val) & d$p_val <= input$pw_p_cut, , drop=FALSE]
    else if (st == "topn")
      d <- utils::head(d[order(if("p_val_adj" %in% names(d)) d$p_val_adj else seq_len(nrow(d))), ],
                       .num(input$pw_topn, 50))
    n_genes <- length(unique(sub(";.*","",as.character(d$gene))))
    mapped_ids <- .pw_ids_vec(d$gene)
    col <- if (length(mapped_ids) < 5) "#E74C3C" else if (length(mapped_ids) < 15) "#F39C12" else "#27AE60"
    org <- input$pw_organism %||% "mmusculus"
    idt <- input$pw_idtype   %||% "genesymbol"
    tagList(
      tags$p(paste0(n_genes, " genes pass cutoffs (of ", n_start, " in this contrast); ",
                    length(mapped_ids), " mapped IDs sent to WebGestalt",
                    if (n_genes < 10) " — few genes rarely reach FDR significance" else ""),
             style=paste0("color:",col,";font-size:12px;font-weight:600;margin-bottom:2px;")),
      tags$p(paste0("Testing against organism = ", org, ", ID type = ", idt,
                    ". Confirm these match your data (mouse symbols → mmusculus + genesymbol)."),
             style="color:#7f8c8d;font-size:11px;margin:0;")
    )
  })

  output$pw_plot <- renderPlot({
    req(s$pw_result)
    res <- s$pw_result; meta <- s$pw_meta
    metric <- input$pw_plot_metric %||% "er"
    # weighted set cover (ORA or GSEA): restrict to the reduced set if present
    if (isTRUE(input$pw_wsc) && "in_wsc" %in% names(res))
      res <- res[!is.na(res$in_wsc) & res$in_wsc, , drop=FALSE]
    n <- min(.num(input$pw_plot_n, 15), nrow(res))
    desc_col <- if ("description" %in% names(res)) "description" else "geneSet"
    if (metric == "nes" && "normalizedEnrichmentScore" %in% names(res)) {
      res <- res[order(-abs(res$normalizedEnrichmentScore)), ][seq_len(n), ]
      ggplot(res, aes(x=reorder(.data[[desc_col]], normalizedEnrichmentScore),
                      y=normalizedEnrichmentScore)) +
        geom_col(fill="#8E44AD", width=0.8) + coord_flip() + theme_classic(base_size=13) +
        labs(x=NULL, y="Normalized ES", title=paste0("GSEA — ", meta$cluster))
    } else if (metric == "fdr" && "FDR" %in% names(res)) {
      res <- res[order(res$FDR), ][seq_len(n), ]
      ggplot(res, aes(x=reorder(.data[[desc_col]], -FDR), y=-log10(FDR))) +
        geom_col(fill="#5DADE2", width=0.8) + coord_flip() + theme_classic(base_size=13) +
        labs(x=NULL, y="-log10(FDR)", title=paste0(meta$method, " — ", meta$cluster))
    } else {
      erc <- if ("enrichmentRatio" %in% names(res)) "enrichmentRatio" else
             if ("normalizedEnrichmentScore" %in% names(res)) "normalizedEnrichmentScore" else "FDR"
      res <- res[order(-res[[erc]]), ][seq_len(n), ]
      ggplot(res, aes(x=reorder(.data[[desc_col]], .data[[erc]]), y=.data[[erc]])) +
        geom_col(fill="#D3D3D3", width=0.8) + coord_flip() + theme_classic(base_size=13) +
        labs(x=NULL, y=erc, title=paste0(meta$method, " — ", meta$cluster))
    }
  })

  output$pw_tbl <- renderDT({
    req(s$pw_result)
    res <- s$pw_result
    # Preferred column order (ORA fields the user asked for) + GSEA-specific
    # fields, then anything else the API returned, then in_wsc if present.
    preferred <- c("geneSet","description","link","size","overlap","expect",
                   "enrichmentRatio","normalizedEnrichmentScore","enrichmentScore",
                   "leadingEdgeNum","pValue","FDR","overlapId","userId","in_wsc")
    cols <- c(intersect(preferred, names(res)),
              setdiff(names(res), preferred))
    disp <- res[, cols, drop=FALSE]
    # Truncate the long gene-list / link columns for on-screen readability only;
    # the CSV download keeps the full, untruncated values.
    for (cn in intersect(c("overlapId","userId","link","description"), names(disp))) {
      disp[[cn]] <- ifelse(nchar(as.character(disp[[cn]])) > 60,
                           paste0(substr(as.character(disp[[cn]]), 1, 60), "…"),
                           as.character(disp[[cn]]))
    }
    datatable(disp, options=list(pageLength=15, scrollX=TRUE), rownames=FALSE) %>%
      formatRound(intersect(c("expect","enrichmentRatio","normalizedEnrichmentScore",
                              "enrichmentScore","pValue","FDR"), cols), 4)
  })

  output$pw_dl <- downloadHandler(
    filename=function() paste0("pathway_", s$pw_meta$method, "_", s$pw_meta$cluster, "_", Sys.Date(), ".csv"),
    content=function(file){ req(s$pw_result); readr::write_csv(s$pw_result, file) }
  )

  output$pw_set_ui <- renderUI({
    req(s$pw_result)
    desc_col <- if ("description" %in% names(s$pw_result)) "description" else "geneSet"
    selectInput("pw_set_sel","Gene set:", choices=s$pw_result[[desc_col]])
  })

  output$pw_genes <- renderText({
    req(s$pw_result, input$pw_set_sel)
    res <- s$pw_result
    desc_col <- if ("description" %in% names(res)) "description" else "geneSet"
    row <- res[res[[desc_col]] == input$pw_set_sel, , drop=FALSE]
    if (!nrow(row)) return("Set not found.")
    gcol <- intersect(c("userId","overlapId","geneID"), names(row))
    genes <- if (length(gcol)) gsub(";", ", ", row[[gcol[1]]][1]) else "(no gene list column)"
    paste0(input$pw_set_sel, "\n\nGenes: ", genes)
  })

  # ── ⑭ Cell-type Annotation (CellMarker 2.0 / custom reference) ──────────────
  # Reference file read into a data.frame stashed for column selection.
  ann_raw <- reactiveVal(NULL)
  observeEvent(input$ann_ref_file, {
    f <- input$ann_ref_file; req(f)
    ext <- tolower(tools::file_ext(f$name))
    df <- tryCatch({
      if (input$ann_ref_fmt == "gmt") {
        # parse GMT: name <tab> desc <tab> gene1 <tab> gene2 ...
        lines <- readLines(f$datapath, warn=FALSE)
        sets  <- lapply(strsplit(lines, "\t"), function(x) list(name=x[1], genes=x[-(1:2)]))
        data.frame(.gmt=TRUE)  # marker; actual sets built at load
        attr_sets <- setNames(lapply(sets, function(s) s$genes[s$genes!=""]),
                              vapply(sets, function(s) s$name, character(1)))
        ann_raw(list(gmt=attr_sets)); return(invisible())
      } else if (ext %in% c("xlsx","xls")) {
        as.data.frame(readxl::read_excel(f$datapath))
      } else {
        as.data.frame(data.table::fread(f$datapath, sep="auto", header=TRUE))
      }
    }, error=function(e){ showNotification(paste0("Read failed: ",e$message),type="error",duration=10); NULL })
    if (!is.null(df)) ann_raw(df)
  })

  output$ann_col_ui <- renderUI({
    r <- ann_raw()
    if (is.null(r) || is.list(r) && !is.null(r$gmt)) return(NULL)
    cols <- names(r)
    ct_def <- intersect(c("cell_name","cellName","cell_type","celltype","CellType"), cols)
    gn_def <- intersect(c("Symbol","marker","gene","Genes","GeneSymbol","official gene symbol","Cell marker"), cols)
    tagList(
      selectInput("ann_ct_col","Cell-type column:", choices=cols,
                  selected=if(length(ct_def)) ct_def[1] else cols[1]),
      selectInput("ann_gene_col","Gene-symbol column:", choices=cols,
                  selected=if(length(gn_def)) gn_def[1] else cols[min(2,length(cols))])
    )
  })

  # Header preview of the uploaded reference (first rows), so the user can see
  # every column and decide which to use / filter on.
  output$ann_head_ui <- renderUI({
    r <- ann_raw(); if (is.null(r) || !is.null(r$gmt)) return(
      if (!is.null(r) && !is.null(r$gmt))
        tags$p(tags$small(paste0("GMT loaded: ", length(r$gmt), " sets.")), style="color:#555;")
      else NULL)
    tagList(
      tags$p(tags$b("Uploaded reference — first rows:"), style="font-size:11px;margin:6px 0 2px 0;"),
      div(style="overflow-x:auto;", DTOutput("ann_head_dt")),
      tags$p(tags$small("Columns: ", paste(names(r), collapse=", ")),
             style="color:#555;font-size:10px;margin-top:4px;")
    )
  })
  output$ann_head_dt <- renderDT({
    r <- ann_raw(); req(!is.null(r), is.null(r$gmt))
    d <- utils::head(r, 8)
    d[] <- lapply(d, function(col){ col <- as.character(col)
      ifelse(nchar(col) > 45, paste0(substr(col,1,45),"…"), col) })
    datatable(d, rownames=FALSE, options=list(pageLength=8, dom="t", scrollX=TRUE, ordering=FALSE),
              class="compact stripe")
  })

  # Flexible filtering: up to 3 arbitrary columns, each with a value picker.
  # (Replaces the fixed species/tissue filter — works for any reference schema,
  #  including CellMarker's cell_name and other columns.)
  output$ann_filter_ui <- renderUI({
    r <- ann_raw(); if (is.null(r) || !is.null(r$gmt)) return(NULL)
    cols <- names(r)
    sp_guess <- intersect(c("species","Species"), cols)
    ts_guess <- intersect(c("tissue_type","tissue","Tissue","tissueType"), cols)
    tags$div(
      tags$p(tags$small("Optional filters — restrict the reference by any column ",
        "(e.g. species, tissue_type, cancer_type). Leave a filter's column at ",
        "'(none)' to skip it."), style="color:grey;font-size:11px;margin:4px 0;"),
      lapply(1:3, function(i){
        def_col <- if (i==1 && length(sp_guess)) sp_guess[1]
                   else if (i==2 && length(ts_guess)) ts_guess[1] else "(none)"
        tagList(
          selectInput(paste0("ann_filt_col",i), paste0("Filter ",i," column:"),
                      choices=c("(none)", cols), selected=def_col),
          uiOutput(paste0("ann_filt_val_ui",i))
        )
      })
    )
  })
  # value pickers react to the chosen column
  lapply(1:3, function(i){
    output[[paste0("ann_filt_val_ui",i)]] <- renderUI({
      r <- ann_raw(); col <- input[[paste0("ann_filt_col",i)]]
      if (is.null(r) || !is.null(r$gmt) || is.null(col) || col=="(none)" || !col %in% names(r)) return(NULL)
      vals <- sort(unique(as.character(r[[col]])))
      def <- if (grepl("species|Species", col)) grep("Mouse|mouse|Mm", vals, value=TRUE) else NULL
      selectizeInput(paste0("ann_filt_val",i), paste0("Keep ", col, " (blank = all):"),
                     choices=vals, selected=def, multiple=TRUE,
                     options=list(placeholder="all values"))
    })
  })

  # Reuse the pathway ID mapper for the cluster markers -> symbol space
  output$ann_idcol_ui2 <- renderUI({
    if (is.null(s$prt_map))
      return(tags$p(tags$small("No prt.map — cluster marker IDs used as-is."),
                    style="color:grey;font-size:11px;"))
    cols <- names(s$prt_map)
    def  <- intersect(c("mgi_symbol","Genes","gene","Gene","Symbol"), cols)
    selectInput("ann_idcol","Map cluster IDs to prt.map column:",
                choices=c("(use as-is)"="__asis__", setNames(cols,cols)),
                selected=if(length(def)) def[1] else "__asis__")
  })
  # Case normalization for gene-symbol matching. When enabled, UPPERCASE is
  # applied symmetrically to both reference and query symbols so mouse (Mertk)
  # and human (MERTK) casing match. Applied at every comparison point.
  .ann_case <- function(x) if (isTRUE(input$ann_ignore_case)) toupper(as.character(x)) else as.character(x)

  .ann_map <- function(ids) {
    orig <- sub(";.*","",as.character(ids)); out <- orig
    col <- input$ann_idcol %||% "__asis__"
    if (!is.null(s$prt_map) && col!="__asis__" && col %in% names(s$prt_map)) {
      pm <- s$prt_map; lead <- function(x) sub(";.*","",as.character(x))
      tgt <- lead(pm[[col]])
      ks <- c(list(lead(rownames(pm))), lapply(names(pm), function(cn) lead(pm[[cn]])))
      mp <- rep(NA_character_, length(orig))
      for (k in ks) { idx <- match(orig,k); tk <- is.na(mp)&!is.na(idx); if(any(tk)) mp[tk]<-tgt[idx[tk]]; if(!anyNA(mp)) break }
      out <- ifelse(is.na(mp)|mp=="", orig, mp)
    }
    .ann_case(sub("[._][0-9]+$","", sub(";.*","",out)))
  }

  observeEvent(input$ann_load_ref, {
    r <- ann_raw()
    if (is.null(r)) { showNotification("Upload a reference file first.", type="error", duration=8); return() }
    tryCatch({
      if (!is.null(r$gmt)) {
        sets <- lapply(r$gmt, .ann_case)
        src  <- "GMT"
      } else {
        req(input$ann_ct_col, input$ann_gene_col)
        d <- r
        # Apply up to 3 flexible column filters (any column, chosen values).
        for (i in 1:3) {
          fc <- input[[paste0("ann_filt_col",i)]]
          fv <- input[[paste0("ann_filt_val",i)]]
          if (!is.null(fc) && fc != "(none)" && fc %in% names(d) &&
              !is.null(fv) && length(fv)) {
            d <- d[as.character(d[[fc]]) %in% fv, , drop=FALSE]
          }
        }
        if (!nrow(d)) { showNotification("All rows removed by the filters — loosen them.", type="error", duration=10); return() }
        ct <- as.character(d[[input$ann_ct_col]])
        gn <- sub(";.*","", as.character(d[[input$ann_gene_col]]))
        # CellMarker sometimes stores a comma/space list of genes per row — split
        gn_split <- strsplit(gn, "[,; ]+")
        rows <- data.frame(cell_type=rep(ct, lengths(gn_split)),
                           gene=unlist(gn_split), stringsAsFactors=FALSE)
        rows <- rows[!is.na(rows$gene) & rows$gene!="" & !is.na(rows$cell_type), ]
        rows$gene <- .ann_case(rows$gene)              # symmetric case with .ann_map
        sets <- split(rows$gene, rows$cell_type)
        sets <- lapply(sets, function(g) unique(g[g!=""]))
        src  <- if (input$ann_ref_fmt=="cellmarker") "CellMarker 2.0" else "Custom"
      }
      sets <- sets[vapply(sets, length, integer(1)) >= 2]   # need >=2 genes
      if (!length(sets)) { showNotification("No usable cell-type sets after filtering.", type="error", duration=10); return() }
      s$ann_ref <- sets
      s$ann_ref_meta <- list(source=src, n_sets=length(sets),
                             median_size=stats::median(vapply(sets,length,integer(1))),
                             case=isTRUE(input$ann_ignore_case))
      showNotification(paste0("Loaded ", length(sets), " reference cell-type sets."),
                       type="message", duration=6)
      s_log(paste0("Annotation reference loaded: ", src, " — ", length(sets), " cell-type sets."))
    }, error=function(e) showNotification(paste0("Reference load error: ",e$message), type="error", duration=12))
  })

  output$ann_ref_status <- renderUI({
    if (is.null(s$ann_ref_meta)) return(NULL)
    m <- s$ann_ref_meta
    tags$p(paste0("✓ ", m$source, ": ", m$n_sets, " cell types (median ",
                  m$median_size, " genes/set)",
                  if (isTRUE(m$case)) " · UPPERCASE matching" else " · exact-case matching"),
           style="color:#27AE60;font-size:12px;font-weight:600;margin-top:4px;")
  })

  ann_markers <- reactive({ if((input$ann_src %||% "markers")=="int_markers") s$int_markers else s$markers })

  # ── Fisher's exact enrichment (mirrors the user's contingency-table workflow) ─
  observeEvent(input$ann_run_fisher, {
    mk <- ann_markers()
    if (is.null(mk) || !nrow(mk)) { showNotification("No cluster markers — run ⑨/⑫ first.", type="error", duration=8); return() }
    if (is.null(s$ann_ref)) { showNotification("Load a reference first.", type="error", duration=8); return() }
    seu <- s$seu; req(seu)
    tryCatch({
      # Universe: all tested features (mapped to symbol space), like the scripts.
      universe <- unique(.ann_map(rownames(seu)))
      ref <- s$ann_ref
      if ((input$ann_universe %||% "tested") == "refonly") {
        # RESTRICT to measured features that also appear somewhere in the
        # reference, i.e. test enrichment among annotatable proteins. Previously
        # this UNIONED the reference into the universe, adding genes that were
        # never measured — they land in the "neither" cell, inflate N and the odds
        # ratio, and shrink p. A protein that was never quantified cannot be a
        # marker of one of your clusters, so it does not belong in the denominator.
        universe <- intersect(universe, unique(unlist(ref)))
      }
      universe <- universe[!is.na(universe) & universe!=""]
      N <- length(universe)
      if (N < 50)
        showNotification(paste0("Universe is only ", N, " genes after mapping. Fisher ",
                                "p-values on a universe this small are unstable \u2014 check ",
                                "that feature IDs map to the reference's ID space."),
                         type="warning", duration=12)
      s_log(paste0("Annotation Fisher universe: ", N, " genes (mode=",
                   input$ann_universe %||% "tested", "), alternative=",
                   input$ann_alt %||% "greater"))

      # Cluster marker sets: significant, up-regulated (per the scripts' filter),
      # mapped to symbol space and restricted to the universe.
      d <- mk
      if (.mk_is_roc(d)) {
        # ROC: filter on power (higher = better) instead of a p-value.
        if ("power" %in% names(d))
          d <- d[!is.na(d$power) & d$power >= (.num(input$ann_p_cut, 0.4)), , drop=FALSE]
      } else {
        pcol <- input$ann_p_type %||% "p_val_adj"
        if (pcol %in% names(d)) d <- d[!is.na(d[[pcol]]) & d[[pcol]] <= (.num(input$ann_p_cut, 0.05)), , drop=FALSE]
      }
      eff <- .mk_effect(d)   # avg_log2FC or avg_diff (ROC)
      if (!is.na(eff) && !is.na(input$ann_lfc_cut))
        d <- d[!is.na(d[[eff]]) & d[[eff]] >= input$ann_lfc_cut, , drop=FALSE]
      d$sym <- .ann_map(d$gene)
      cl_sets <- split(d$sym, as.character(d$cluster))
      cl_sets <- lapply(cl_sets, function(g) intersect(unique(g[g!=""]), universe))
      cl_sets <- cl_sets[vapply(cl_sets, length, integer(1)) > 0]
      if (!length(cl_sets)) { showNotification("No markers pass cutoffs.", type="error", duration=8); return() }

      alt <- input$ann_alt %||% "greater"
      grid <- expand.grid(cluster=names(cl_sets), cell_type=names(ref), stringsAsFactors=FALSE)
      withProgress(message="Fisher enrichment (cluster × cell type)...", value=0, {
        res <- lapply(seq_len(nrow(grid)), function(i){
          incProgress(1/nrow(grid))
          mset <- cl_sets[[grid$cluster[i]]]
          rset <- intersect(ref[[grid$cell_type[i]]], universe)
          a <- length(intersect(mset, rset))           # marker AND ref
          b <- length(setdiff(mset, rset))              # marker, not ref
          cc<- length(setdiff(rset, mset))              # ref, not marker
          dd<- N - a - b - cc                            # neither
          ct <- matrix(c(a,b,cc,dd), nrow=2)
          ft <- tryCatch(stats::fisher.test(ct, alternative=alt), error=function(e) NULL)
          data.frame(cluster=grid$cluster[i], cell_type=grid$cell_type[i],
                     n_markers=length(mset), n_ref_in_univ=length(rset),
                     n_overlap=a, marker_not_ref=b, ref_not_marker=cc, neither=dd,
                     odds_ratio=if(!is.null(ft)) unname(ft$estimate) else NA_real_,
                     p_value=if(!is.null(ft)) ft$p.value else NA_real_,
                     stringsAsFactors=FALSE)
        })
        res <- do.call(rbind, res)
        res$p_adj_BH <- p.adjust(res$p_value, method="BH")
        res <- res[order(res$p_adj_BH, -res$odds_ratio), ]
        s$ann_fisher <- res
      })
      showNotification(paste0("Fisher done: ", nrow(grid), " cluster×cell-type tests | universe ", N, "."),
                       type="message", duration=6)
      s_log(paste0("Annotation Fisher: ", length(cl_sets), " clusters × ", length(ref),
                   " cell types | universe ", N))
    }, error=function(e) showNotification(paste0("Fisher error: ",e$message), type="error", duration=12))
  })

  # ── Activity scoring (AddModuleScore per reference signature) ────────────────
  observeEvent(input$ann_run_score, {
    if (is.null(s$ann_ref)) { showNotification("Load a reference first.", type="error", duration=8); return() }
    # Score the SAME object the marker source refers to, so the per-cluster
    # summary matches the Fisher comparison. Integrated Markers (⑫) → integrated
    # object with integrated clusters; otherwise the main object.
    use_int <- (input$ann_src %||% "markers") == "int_markers"
    if (use_int) {
      if (is.null(s$seu_int)) {
        showNotification("Integrated Markers selected, but no integrated object — run Integration (⑪) first, or switch the marker source to ⑨.",
                         type="error", duration=12); return() }
      seu <- i_seu_with_ident()
    } else {
      seu <- s_seu_with_ident()
    }
    req(seu)
    tryCatch({
      assay_use <- if ("SCT" %in% names(seu@assays)) "SCT" else input$s_assay
      Seurat::DefaultAssay(seu) <- assay_use
      feats <- rownames(seu)
      feat_sym <- .ann_map(feats)
      ref <- s$ann_ref
      # Map each reference signature to the object's feature IDs (>=2 present).
      sig_list <- lapply(ref, function(g) feats[feat_sym %in% g])
      sig_list <- sig_list[vapply(sig_list, length, integer(1)) >= 2]
      if (!length(sig_list)) {
        showNotification("No reference signatures have >=2 matching features. Check the ID-mapping column.",
                         type="error", duration=12); return() }

      # Build a DENSE, NA-free expression matrix for scoring. VSN/scpmed data
      # layers contain NAs, which break AddModuleScore's binning — fill NAs with
      # each protein's minimum observed value (display/scoring only; testing
      # untouched). This is the direct cause of the previous failure.
      dl <- tryCatch(as.matrix(SeuratObject::LayerData(seu@assays[[assay_use]], layer="data")),
                     error=function(e) as.matrix(Seurat::GetAssayData(seu, assay=assay_use, layer="data")))
      if (anyNA(dl)) {
        rmin <- suppressWarnings(apply(dl, 1, function(r){ mn <- min(r, na.rm=TRUE); if(is.finite(mn)) mn else 0 }))
        na_idx <- which(is.na(dl), arr.ind=TRUE)
        if (nrow(na_idx) > 0) dl[na_idx] <- rmin[na_idx[,1]]
      }
      # Cluster axis: use seurat_clusters so it matches the Fisher table (whose
      # marker `cluster` column is seurat_clusters), not whatever the global ident
      # happens to be (e.g. sex). Fall back to Idents if the column is absent.
      cl <- if ("seurat_clusters" %in% names(seu@meta.data))
              as.character(seu@meta.data[["seurat_clusters"]])
            else as.character(Seurat::Idents(seu))
      n_feat <- nrow(dl)

      # Direct module score per signature: mean of per-protein z-scores over the
      # signature genes, per cell. Robust, NA-free, and doesn't depend on
      # AddModuleScore's control-gene binning (which fails with few genes / NAs).
      zmat <- t(scale(t(dl)))                      # per-protein z across cells
      zmat[!is.finite(zmat)] <- 0
      withProgress(message="Scoring reference signatures...", value=0.3, {
        cell_scores <- sapply(sig_list, function(gset){
          g <- intersect(gset, rownames(zmat))
          if (length(g) < 2) return(rep(NA_real_, ncol(zmat)))
          colMeans(zmat[g, , drop=FALSE], na.rm=TRUE)
        })
        # cell_scores: cells x signatures. Summarize mean per cluster.
        cell_scores <- as.matrix(cell_scores)
        keep_sig <- colSums(!is.na(cell_scores)) > 0
        cell_scores <- cell_scores[, keep_sig, drop=FALSE]
        mat <- apply(cell_scores, 2, function(v) tapply(v, cl, mean, na.rm=TRUE))
        if (is.null(dim(mat))) mat <- matrix(mat, nrow=length(unique(cl)),
                                             dimnames=list(sort(unique(cl)), colnames(cell_scores)))
        s$ann_scores <- mat
      })
      showNotification(paste0("Activity scores computed for ", ncol(s$ann_scores),
                              " signatures (of ", length(sig_list), " mapped)."),
                       type="message", duration=6)
      s_log(paste0("Annotation activity scoring: ", ncol(s$ann_scores),
                   " signatures scored (direct z-score module, NA-safe)."))
    }, error=function(e) showNotification(paste0("Scoring error: ",conditionMessage(e)), type="error", duration=12))
  })

  output$ann_status <- renderUI({
    tagList(
      if (!is.null(s$ann_fisher)) tags$p(paste0("✓ Fisher: ", nrow(s$ann_fisher), " pairs"),
        style="color:#27AE60;font-size:12px;margin:4px 0 0 0;") else NULL,
      if (!is.null(s$ann_scores)) tags$p(paste0("✓ Activity: ", ncol(s$ann_scores), " signatures × ",
        nrow(s$ann_scores), " clusters"), style="color:#27AE60;font-size:12px;margin:2px 0 0 0;") else NULL
    )
  })

  output$ann_fisher_hm <- renderPlot({
    req(s$ann_fisher)
    r <- s$ann_fisher
    r$log2OR <- log2(pmax(r$odds_ratio, 0) + 1)
    r$sig <- ifelse(r$p_adj_BH < 0.001,"***", ifelse(r$p_adj_BH<0.01,"**", ifelse(r$p_adj_BH<0.05,"*","")))
    ggplot(r, aes(x=cluster, y=cell_type, fill=log2OR)) +
      geom_tile(color="white") +
      geom_text(aes(label=sig), size=4) +
      scale_fill_gradient(low="white", high="#C0392B", na.value="grey90", name="log2(OR+1)") +
      theme_classic(base_size=12) + theme(axis.text.x=element_text(angle=45,hjust=1)) +
      labs(title=paste0("Fisher enrichment — ", (s$ann_ref_meta$source %||% "reference")),
           x="Cluster", y="Reference cell type")
  })

  output$ann_fisher_tbl <- renderDT({
    req(s$ann_fisher)
    datatable(s$ann_fisher, options=list(pageLength=20, scrollX=TRUE), rownames=FALSE) %>%
      formatRound(c("odds_ratio","p_value","p_adj_BH"), 4)
  })
  output$ann_dl_fisher <- downloadHandler(
    filename=function() paste0("annotation_fisher_", Sys.Date(), ".csv"),
    content=function(file){ req(s$ann_fisher); readr::write_csv(s$ann_fisher, file) })

  output$ann_best_tbl <- renderDT({
    req(s$ann_fisher)
    best <- s$ann_fisher %>% group_by(cluster) %>%
      slice_min(order_by=p_adj_BH, n=1, with_ties=FALSE) %>% ungroup() %>%
      dplyr::select(cluster, best_cell_type=cell_type, n_overlap, odds_ratio, p_value, p_adj_BH)
    datatable(best, options=list(pageLength=20), rownames=FALSE) %>%
      formatRound(c("odds_ratio","p_value","p_adj_BH"), 4)
  })

  output$ann_score_hm <- renderPlot({
    req(s$ann_scores)
    m <- s$ann_scores
    df <- as.data.frame(as.table(as.matrix(m))); names(df) <- c("cluster","cell_type","score")
    ggplot(df, aes(x=cluster, y=cell_type, fill=score)) +
      geom_tile(color="white") +
      scale_fill_gradient2(low="#2166AC", mid="white", high="#B2182B", midpoint=0, name="Mean\nmodule score") +
      theme_classic(base_size=12) + theme(axis.text.x=element_text(angle=45,hjust=1)) +
      labs(title="Activity scores (AddModuleScore) — mean per cluster",
           x="Cluster", y="Reference cell type")
  })

  output$ann_ref_tbl <- renderDT({
    req(s$ann_ref)
    df <- data.frame(cell_type=names(s$ann_ref),
                     n_genes=vapply(s$ann_ref, length, integer(1)),
                     genes=vapply(s$ann_ref, function(g) {
                       gg <- paste(utils::head(g, 20), collapse=", ")
                       if (length(g) > 20) paste0(gg, ", …") else gg }, character(1)),
                     stringsAsFactors=FALSE)
    datatable(df, options=list(pageLength=15, scrollX=TRUE), rownames=FALSE)
  })

  # ══════════════════════════════════════════════════════════════════════════════
  # ⑯ CORRELATIONS
  # ══════════════════════════════════════════════════════════════════════════════
  # Purpose: test whether two things you are treating as separate really are.
  # Every per-cell summary and feature value is derived from ONE user-chosen
  # matrix, so the same pair can be compared before and after a transformation.
  # That makes this tab a direct check on the pipeline itself: correlate a
  # covariate against a summary of the matrix it was regressed out of, and a
  # coefficient near zero is evidence the regression did what it claimed.

  # Resolve the chosen matrix once, with an explicit record of its provenance.
  s_cor_matrix <- reactive({
    src <- input$s_cor_src %||% "norm_tested"
    assay_use <- if ("SCT" %in% names(s$seu@assays)) "SCT" else input$s_assay
    lay <- function(l) tryCatch(as.matrix(SeuratObject::LayerData(
             s$seu@assays[[assay_use]], layer=l)), error=function(e) NULL)
    out <- switch(src,
      "raw_na"      = list(m=s$prt_int_raw,        na_kept=TRUE,
                           lab="raw intensities, NAs intact (s$prt_int_raw)"),
      "raw_zero"    = list(m=s$prt_int,            na_kept=FALSE,
                           lab="raw intensities with NA\u21920 applied at load (s$prt_int)"),
      "counts"      = list(m=lay("counts"),        na_kept=FALSE,
                           lab="counts layer \u2014 ceiling'd integers, zeros for not-detected"),
      "norm_tested" = list(m=.norm_mat(s$seu), na_kept=TRUE,
                           lab="data layer \u2014 normalization output, NOT covariate-regressed; the matrix the tests read"),
      # Recomputed, not stored: regress_out_na at interpretable scale using the
      # settings the last run recorded. Same scale as the data layer, so a pair of
      # variables can be correlated before and after covariate removal with
      # nothing else differing.
      "norm_adj"    = {
        d0 <- s$intensity_diag
        m0 <- .norm_mat(s$seu)
        rv <- intersect(d0$rv_use %||% character(0), names(s$seu@meta.data))
        if (is.null(m0) || !length(rv))
          list(m=m0, na_kept=TRUE,
               lab=paste0("regressed \u2014 IDENTICAL to the data layer here, because no ",
                          "covariates were selected in the last \u2465 run"))
        else list(
          m = tryCatch(regress_out_na(m0, s$seu@meta.data, rv,
                                      spline_df = d0$spline_df %||% 1,
                                      standardize = FALSE,
                                      keep = d0$keep_var),
                       error=function(e) NULL),
          na_kept = TRUE,
          lab = paste0("regressed at interpretable scale (recomputed): ",
                       paste(rv, collapse=" + "), " removed",
                       if (!is.null(d0$keep_var))
                         paste0(", effect of ", paste(d0$keep_var, collapse=", "),
                                " added back") else "",
                       if ((d0$spline_df %||% 1) > 1)
                         paste0(", spline df=", d0$spline_df) else ""))
      },
      "scaled"      = list(m=lay("scale.data"),    na_kept=FALSE,
                           lab=paste0("scale.data \u2014 the SAME regression, then z-scored per ",
                                      "protein over observed values, not-detected filled with 0, ",
                                      "clipped \u00b110. Per-cell summaries of a z-scored matrix are ",
                                      "not abundances \u2014 use it for feature-vs-feature ",
                                      "correlations, not for log2_Total")),
      list(m=NULL, na_kept=NA, lab="unknown"))
    out$src <- src
    out
  })

  output$s_cor_src_note <- renderUI({
    cm <- s_cor_matrix()
    if (is.null(cm$m))
      return(tags$p("That matrix is not available yet \u2014 run the relevant step first.",
                    style="color:#E74C3C;font-size:11px;"))
    tags$p(tags$small(cm$lab, tags$br(),
      sprintf("%d features \u00d7 %d cells. ", nrow(cm$m), ncol(cm$m)),
      if (isTRUE(cm$na_kept))
        "Not-detected is NA, so summaries below exclude it rather than counting it as zero."
      else
        "Not-detected is 0 here, so \u201ctotal\u201d and \u201cmedian\u201d include those zeros as if measured."),
      style="color:grey;font-size:11px;")
  })

  # Per-cell summaries derived from the chosen matrix.
  s_cor_derived <- reactive({
    cm <- s_cor_matrix(); m <- cm$m
    req(!is.null(m))
    obs <- if (isTRUE(cm$na_kept)) !is.na(m) & m != 0 else m != 0
    data.frame(
      cell                 = colnames(m),
      Total                = suppressWarnings(colSums(m, na.rm=TRUE)),
      log2_Total           = round(log2(pmax(suppressWarnings(colSums(m, na.rm=TRUE)), 0) + 1), 4),
      Median_detected      = apply(m, 2, function(x){ x <- x[is.finite(x) & x != 0]
                                                      if (length(x)) stats::median(x) else NA_real_ }),
      Mean_detected        = apply(m, 2, function(x){ x <- x[is.finite(x) & x != 0]
                                                      if (length(x)) mean(x) else NA_real_ }),
      n_Detected           = colSums(obs, na.rm=TRUE),
      Missing_fraction     = round(1 - colSums(obs, na.rm=TRUE)/nrow(m), 4),
      SD_detected          = apply(m, 2, function(x){ x <- x[is.finite(x) & x != 0]
                                                      if (length(x) > 1) stats::sd(x) else NA_real_ }),
      stringsAsFactors = FALSE
    )
  })

  output$s_cor_meta_ui <- renderUI({
    req(s$seu)
    md <- s$seu@meta.data
    num_cols <- names(md)[vapply(md, function(x)
      is.numeric(x) && length(unique(x[!is.na(x)])) > 2, logical(1))]
    pre <- intersect(c("nFeature_raw","log2_total_intensity","log2_median_intensity",
                       "S.Score","G2M.Score"), num_cols)
    if (!length(pre)) pre <- head(num_cols, 3)
    selectizeInput("s_cor_meta", "Metadata variables (numeric):",
                   choices=num_cols, selected=pre, multiple=TRUE,
                   options=list(placeholder="Search metadata..."))
  })

  output$s_cor_derived_ui <- renderUI({
    ch <- c("log2_Total","Median_detected","Mean_detected","n_Detected",
            "Missing_fraction","SD_detected","Total")
    selectizeInput("s_cor_derived", "Per-cell summaries of the chosen matrix:",
                   choices=ch, selected=c("log2_Total","Median_detected","n_Detected"),
                   multiple=TRUE)
  })

  output$s_cor_feat_ui <- renderUI({
    cm <- s_cor_matrix()
    if (is.null(cm$m)) return(NULL)
    selectizeInput("s_cor_feats", "Individual features (optional):",
                   choices=.opt_clean(rownames(cm$m), "features"),
                   selected=NULL, multiple=TRUE,
                   options=list(maxItems=12, maxOptions=200,
                                placeholder="Search proteins/peptides..."))
  })

  output$s_cor_group_ui <- renderUI({
    req(s$seu)
    md <- s$seu@meta.data
    cat_cols <- names(md)[vapply(md, function(x)
      is.character(x) || is.factor(x) ||
      (is.numeric(x) && length(unique(x[!is.na(x)])) <= 10), logical(1))]
    selectInput("s_cor_group", "Group by:", choices=setdiff(cat_cols, "orig.ident"))
  })

  s_cor_result <- reactiveVal(NULL)

  observeEvent(input$s_run_cor, {
    cm <- s_cor_matrix()
    if (is.null(cm$m)) {
      showNotification("That matrix is not available. Run the relevant step first.",
                       type="error", duration=8); return()
    }
    md  <- s$seu@meta.data
    der <- s_cor_derived()
    rownames(der) <- der$cell

    cells <- intersect(rownames(md), der$cell)
    if (length(cells) < 5) {
      showNotification("Fewer than 5 cells shared between the matrix and the metadata.",
                       type="error", duration=8); return()
    }

    df <- data.frame(row.names=cells)
    for (cn in intersect(input$s_cor_meta %||% character(0), names(md)))
      df[[cn]] <- suppressWarnings(as.numeric(md[cells, cn]))
    for (cn in intersect(input$s_cor_derived %||% character(0), names(der)))
      df[[paste0(cn, "__mat")]] <- suppressWarnings(as.numeric(der[cells, cn]))
    for (g in intersect(input$s_cor_feats %||% character(0), rownames(cm$m)))
      df[[paste0(g, "__feat")]] <- suppressWarnings(as.numeric(cm$m[g, cells]))

    # Drop constant / all-NA columns: a correlation with them is undefined and
    # cor() would return NA for the whole row, which reads as "no relationship".
    keep <- vapply(df, function(x) sum(is.finite(x)) >= 5 &&
                                   stats::sd(x, na.rm=TRUE) > 0, logical(1))
    dropped <- names(df)[!keep]
    df <- df[, keep, drop=FALSE]
    if (ncol(df) < 2) {
      showNotification("Need at least two usable variables.", type="error", duration=8); return()
    }
    if (length(dropped))
      s_log(paste0("Correlations: dropped constant/empty variables: ",
                   paste(dropped, collapse=", ")))

    meth  <- input$s_cor_method %||% "spearman"
    grp   <- if (isTRUE(input$s_cor_group_split) &&
                 !is.null(input$s_cor_group) &&
                 input$s_cor_group %in% names(md)) as.character(md[cells, input$s_cor_group])
             else rep("__all__", length(cells))

    withProgress(message="Computing correlations...", value=0.2, {
      out <- list()
      for (lv in sort(unique(grp[!is.na(grp)]))) {
        sub <- df[grp == lv, , drop=FALSE]
        if (nrow(sub) < 5) next
        cm_mat <- suppressWarnings(stats::cor(sub, use="pairwise.complete.obs", method=meth))
        vn <- colnames(sub)
        rows <- list()
        for (a in seq_along(vn)) for (b in seq_along(vn)) if (b > a) {
          x <- sub[[vn[a]]]; y <- sub[[vn[b]]]
          ok <- is.finite(x) & is.finite(y)
          n  <- sum(ok)
          ct <- if (n >= 5) tryCatch(stats::cor.test(x[ok], y[ok], method=meth,
                                                     exact=FALSE), error=function(e) NULL) else NULL
          rows[[length(rows)+1]] <- data.frame(
            group = lv, var1 = vn[a], var2 = vn[b], n = n,
            estimate = if (!is.null(ct)) round(unname(ct$estimate), 4) else NA_real_,
            p_value  = if (!is.null(ct)) ct$p.value else NA_real_,
            stringsAsFactors = FALSE)
        }
        tb <- if (length(rows)) do.call(rbind, rows) else NULL
        if (!is.null(tb)) {
          tb$p_adj <- stats::p.adjust(tb$p_value, method="BH")
          tb <- tb[order(-abs(tb$estimate)), , drop=FALSE]
        }
        out[[lv]] <- list(cor=cm_mat, tbl=tb, n_cells=nrow(sub))
      }
      s_cor_result(list(res=out, method=meth, src=cm$src, lab=cm$lab,
                        na_kept=cm$na_kept, data=df, grp=grp, dropped=dropped))
    })
    s_log(paste0("Correlations (", meth, ") on ", ncol(df), " variables, matrix = ", cm$src))
  })

  output$s_cor_heatmap <- renderPlot({
    cr <- s_cor_result()
    validate(need(!is.null(cr), "Select variables and press \u25b6 Compute correlations."))
    dfs <- lapply(names(cr$res), function(lv){
      cmx <- cr$res[[lv]]$cor
      if (is.null(cmx)) return(NULL)
      d <- as.data.frame(as.table(cmx))
      names(d) <- c("var1","var2","r"); d$group <- lv; d
    })
    d <- do.call(rbind, dfs)
    validate(need(!is.null(d) && nrow(d) > 0, "No correlations to draw."))
    p <- ggplot(d, aes(var1, var2, fill=r)) +
      geom_tile(color="white") +
      geom_text(aes(label=ifelse(is.na(r), "", sprintf("%.2f", r))), size=3) +
      scale_fill_gradient2(low="#2980B9", mid="white", high="#C0392B",
                           midpoint=0, limits=c(-1,1), na.value="grey90") +
      theme_classic(base_size=12) +
      theme(axis.text.x=element_text(angle=45, hjust=1)) +
      labs(x=NULL, y=NULL,
           title=paste0(tools::toTitleCase(cr$method), " correlation"),
           subtitle=paste0("__mat = per-cell summary of the chosen matrix; __feat = single feature.  ",
                           "Matrix: ", cr$lab),
           caption="Pairwise complete observations; no imputation.")
    if (length(cr$res) > 1) p <- p + facet_wrap(~ group)
    p
  })

  output$s_cor_x_ui <- renderUI({
    cr <- s_cor_result(); req(!is.null(cr))
    selectInput("s_cor_x", "X:", choices=colnames(cr$data),
                selected=colnames(cr$data)[1])
  })
  output$s_cor_y_ui <- renderUI({
    cr <- s_cor_result(); req(!is.null(cr))
    selectInput("s_cor_y", "Y:", choices=colnames(cr$data),
                selected=colnames(cr$data)[min(2, ncol(cr$data))])
  })

  output$s_cor_scatter <- renderPlot({
    cr <- s_cor_result()
    validate(need(!is.null(cr), "Compute correlations first."))
    xv <- input$s_cor_x %||% colnames(cr$data)[1]
    yv <- input$s_cor_y %||% colnames(cr$data)[min(2, ncol(cr$data))]
    validate(need(xv %in% colnames(cr$data) && yv %in% colnames(cr$data),
                  "Pick two variables."))
    d <- data.frame(x=cr$data[[xv]], y=cr$data[[yv]], group=cr$grp)
    d <- d[is.finite(d$x) & is.finite(d$y), , drop=FALSE]
    validate(need(nrow(d) > 4, "Fewer than 5 complete pairs."))
    if (isTRUE(input$s_cor_logx)) {
      d <- d[d$x > 0, , drop=FALSE]
      validate(need(nrow(d) > 4, "Fewer than 5 positive X values for a log axis."))
    }
    # One coefficient per group. A single global value on a faceted plot describes
    # a pooled relationship that none of the panels actually shows — and pooling
    # across groups can invert the sign relative to every group individually
    # (Simpson's paradox), so the global number can contradict all the facets.
    ct <- tryCatch(stats::cor.test(d$x, d$y, method=cr$method, exact=FALSE),
                   error=function(e) NULL)
    lab <- if (!is.null(ct))
      sprintf("%s r = %.3f, p = %.3g, n = %d  (pooled)", cr$method,
              unname(ct$estimate), ct$p.value, nrow(d)) else "correlation unavailable"

    faceted <- length(unique(d$group)) > 1 && !identical(unique(d$group), "__all__")
    ann <- if (faceted) {
      do.call(rbind, lapply(split(d, d$group), function(z) {
        if (nrow(z) < 5) return(NULL)
        k <- tryCatch(stats::cor.test(z$x, z$y, method=cr$method, exact=FALSE),
                      error=function(e) NULL)
        if (is.null(k)) return(NULL)
        data.frame(group = z$group[1],
                   x = min(z$x, na.rm=TRUE),
                   y = max(z$y, na.rm=TRUE),
                   lab = sprintf("r = %.3f\np = %.3g\nn = %d",
                                 unname(k$estimate), k$p.value, nrow(z)),
                   stringsAsFactors = FALSE)
      }))
    } else NULL

    p <- ggplot(d, aes(x, y)) +
      geom_point(alpha=0.55, size=1.8, color="#5B8DB8") +
      geom_smooth(method="lm", formula=y ~ x, se=FALSE,
                  color="#2980B9", linetype="dashed", linewidth=0.8) +
      geom_smooth(method="loess", formula=y ~ x, se=FALSE,
                  color="#E67E22", linewidth=1) +
      theme_classic(base_size=13) +
      labs(x=xv, y=yv, title=lab,
           subtitle="Blue dashed = linear; orange = LOESS. Divergence means monotone but curved \u2014 a spline term would help.",
           caption=paste0("Matrix: ", cr$lab))
    if (isTRUE(input$s_cor_logx)) p <- p + scale_x_log10()
    if (faceted) {
      p <- p + facet_wrap(~ group)
      if (!is.null(ann) && nrow(ann))
        p <- p + geom_text(data=ann, aes(x=x, y=y, label=lab),
                           inherit.aes=FALSE, hjust=0, vjust=1,
                           size=3.2, color="#2C3E50")
    }
    p
  })

  output$s_cor_tbl <- renderDT({
    cr <- s_cor_result()
    validate(need(!is.null(cr), "Compute correlations first."))
    tb <- do.call(rbind, lapply(cr$res, function(z) z$tbl))
    validate(need(!is.null(tb) && nrow(tb) > 0, "No pairs to report."))
    tb$p_value <- signif(tb$p_value, 3); tb$p_adj <- signif(tb$p_adj, 3)
    datatable(tb, rownames=FALSE, options=list(pageLength=15, scrollX=TRUE))
  })

  output$s_cor_dl <- downloadHandler(
    filename=function() paste0("correlations_", input$s_cor_src %||% "matrix", "_",
                               input$s_cor_method %||% "spearman", ".csv"),
    content=function(file){
      cr <- s_cor_result()
      tb <- if (!is.null(cr)) do.call(rbind, lapply(cr$res, function(z) z$tbl)) else NULL
      if (is.null(tb)) tb <- data.frame(note="no results")
      else tb$matrix <- cr$lab
      utils::write.csv(tb, file, row.names=FALSE)
    })

  output$s_cor_notes <- renderUI({
    cr <- s_cor_result()
    div(style="padding:6px 2px;",
      tags$h5("What this tab is for, and how to read it"),
      tags$p(tags$b("Variable name suffixes."), " ",
        tags$code("__mat"), " = a per-cell summary computed from the matrix chosen on the left. ",
        tags$code("__feat"), " = one feature's values from that same matrix. Names without a ",
        "suffix are metadata columns, which do not change with the matrix selection.",
        style="font-size:12px;"),
      tags$p(tags$b("The circularity to watch for."), " If you correlate a covariate against a ",
        "summary of a matrix that the covariate was regressed out of, a coefficient near zero ",
        "is guaranteed by construction \u2014 it is not evidence of independence. Used deliberately ",
        "this is the point: choose ", tags$code("regressed, interpretable scale"),
        " and check that nFeature_raw now correlates near zero with ", tags$code("log2_Total__mat"),
        ", then switch to ", tags$code("data layer \u2014 normalized, un-regressed"),
        " and confirm it does not. That difference is your evidence the regression worked \u2014 ",
        "and the two matrices are on the same scale, so nothing else can account for it.",
        style="font-size:12px;"),
      tags$p(tags$b("Cell-cycle scores against depth."), " The scores are computed by ",
        "AddModuleScore on a copy where not-detected values were FILLED, so a cell that ",
        "detected few cycle proteins gets a score built largely from fill values. A strong ",
        "correlation between S.Score and n_Detected__mat or nFeature_raw means the score is ",
        "partly a depth readout, and regressing both removes the same effect twice.",
        style="font-size:12px;"),
      tags$p(tags$b("Two depth proxies at r > 0.9"), " are interchangeable; regress one, not ",
        "both, or the design becomes near-collinear and the coefficients unstable.",
        style="font-size:12px;"),
      tags$p(tags$b("Spearman vs Pearson."), " A high Spearman with a much lower Pearson means ",
        "the relationship is monotone but curved \u2014 exactly the case where a spline term in ",
        "the \u2465 regression and the \u2468 design earns its degrees of freedom. The Scatter tab ",
        "draws both fits so the curvature is visible.",
        style="font-size:12px;"),
      tags$p(tags$b("Missing values."), " Every coefficient uses complete pairs only. On an ",
        "NA-preserving matrix a sparse feature therefore contributes few cells, and its ",
        "coefficient is correspondingly unstable \u2014 read the n column, not just the estimate.",
        style="font-size:12px;"),
      if (!is.null(cr) && length(cr$dropped))
        tags$p(tags$b("Dropped this run: "), paste(cr$dropped, collapse=", "),
               " \u2014 constant or fewer than 5 finite values.",
               style="font-size:12px;color:#E67E22;")
      else NULL
    )
  })

  # ── ⑮ Trajectory / pseudotime (Slingshot) ───────────────────────────────────
  traj_seu <- reactive({
    if ((input$traj_obj %||% "main") == "int") s$seu_int else s$seu
  })

  output$traj_cluster_ui <- renderUI({
    seu <- traj_seu(); req(seu)
    cats <- names(seu@meta.data)[vapply(seu@meta.data, function(v)
      (is.factor(v) || is.character(v)) && length(unique(v[!is.na(v)])) >= 2 &&
      length(unique(v[!is.na(v)])) <= 50, logical(1))]
    sel <- if ("seurat_clusters" %in% cats) "seurat_clusters" else cats[1]
    selectInput("traj_cluster","Cluster label:", choices=cats, selected=sel)
  })
  traj_cluster_levels <- reactive({
    seu <- traj_seu(); req(seu, input$traj_cluster)
    sort(unique(as.character(seu@meta.data[[input$traj_cluster]])))
  })
  output$traj_start_ui <- renderUI({
    lv <- traj_cluster_levels(); req(lv)
    selectInput("traj_start","Start cluster (optional — roots the trajectory):",
                choices=c("(none / let Slingshot choose)"="__none__", lv), selected="__none__")
  })
  output$traj_end_ui <- renderUI({
    lv <- traj_cluster_levels(); req(lv)
    selectizeInput("traj_end","End cluster(s) (optional):", choices=lv, selected=NULL,
                   multiple=TRUE, options=list(placeholder="let Slingshot choose"))
  })

  observeEvent(input$traj_run, {
    # slingshot needs its dependency tree present at call time. Check the ones
    # that commonly fail to install so the error names the actual missing package.
    need <- c("slingshot","DelayedMatrixStats","sparseMatrixStats",
              "TrajectoryUtils","SingleCellExperiment","princurve")
    miss <- need[!vapply(need, requireNamespace, logical(1), quietly=TRUE)]
    if (length(miss)) {
      showNotification(paste0("Missing package(s): ", paste(miss, collapse=", "),
        ". Install with BiocManager::install(c(", paste(sprintf('\"%s\"', miss), collapse=", "),
        ")) and restart the app."), type="error", duration=15); return() }
    seu <- traj_seu()
    if (is.null(seu)) { showNotification("No object — run clustering (⑧) or integration (⑪) first.", type="error", duration=8); return() }
    reduc <- input$traj_reduc
    if (!reduc %in% names(seu@reductions)) {
      showNotification(paste0("Reduction '", reduc, "' not found on this object. Pick another embedding."),
                       type="error", duration=10); return() }
    clcol <- input$traj_cluster
    if (is.null(clcol) || !clcol %in% names(seu@meta.data)) { showNotification("Pick a cluster label.", type="error", duration=8); return() }
    tryCatch({
      emb <- Seurat::Embeddings(seu, reduction=reduc)
      if (reduc %in% c("pca","integrated.cca")) {
        nd <- min(.num(input$traj_dims, 10), ncol(emb))
        emb <- emb[, seq_len(nd), drop=FALSE]
      }
      cl <- as.character(seu@meta.data[[clcol]])
      names(cl) <- rownames(seu@meta.data)
      cl <- cl[rownames(emb)]
      ok <- !is.na(cl) & stats::complete.cases(emb)
      emb <- emb[ok, , drop=FALSE]; cl <- cl[ok]
      start <- if (!is.null(input$traj_start) && input$traj_start != "__none__") input$traj_start else NULL
      end   <- if (!is.null(input$traj_end) && length(input$traj_end)) input$traj_end else NULL
      withProgress(message="Fitting Slingshot trajectory...", value=0.4, {
        sds_raw <- slingshot::slingshot(data=emb, clusterLabels=cl,
                                        start.clus=start, end.clus=end)
        # Modern slingshot() on a matrix returns a PseudotimeOrdering, which has
        # no reducedDim()/slingCurves() methods. Convert to a SlingshotDataSet so
        # the plotting accessors (reducedDim, slingCurves, slingPseudotime) work.
        sds <- tryCatch(slingshot::SlingshotDataSet(sds_raw),
                        error=function(e) sds_raw)
        pt  <- slingshot::slingPseudotime(sds)   # cells x lineages
        s$traj_sds  <- sds
        s$traj_pt   <- pt
        s$traj_meta <- list(reduction=reduc, cluster=clcol,
                            start=if(is.null(start))"auto" else start,
                            n_lineages=ncol(pt), obj=input$traj_obj)
      })
      showNotification(paste0("Slingshot done: ", ncol(s$traj_pt), " lineage(s) over ",
                              length(unique(cl)), " clusters."), type="message", duration=6)
      s_log(paste0("Trajectory (Slingshot): reduction=", reduc, ", clusters=", clcol,
                   ", lineages=", ncol(s$traj_pt),
                   if(!is.null(start)) paste0(", start=", start) else "", "."))
    }, error=function(e) showNotification(paste0("Slingshot error: ", conditionMessage(e)),
                                          type="error", duration=12))
  })

  output$traj_status <- renderUI({
    if (is.null(s$traj_meta)) return(NULL)
    m <- s$traj_meta
    tags$p(paste0("✓ ", m$n_lineages, " lineage(s) | ", m$reduction, " | start: ", m$start),
           style="color:#27AE60;font-size:12px;font-weight:600;margin-top:4px;")
  })

  output$traj_gene_ui <- renderUI({
    seu <- traj_seu(); req(seu, s$traj_pt)
    selectizeInput("traj_gene","Protein / gene:", choices=NULL, multiple=FALSE,
                   options=list(placeholder="type to search"))
  })
  observe({
    seu <- traj_seu()
    if (!is.null(seu) && !is.null(s$traj_pt))
      updateSelectizeInput(session, "traj_gene", choices=rownames(seu), server=TRUE)
  })
  output$traj_lineage_ui <- renderUI({
    req(s$traj_pt)
    lin <- colnames(s$traj_pt); if (is.null(lin)) lin <- paste0("Lineage", seq_len(ncol(s$traj_pt)))
    selectInput("traj_lineage","Lineage (for gene plot):", choices=lin, selected=lin[1])
  })

  # color a 2-D layout of the fit reduction by pseudotime, with curves overlaid
  output$traj_curve_plot <- renderPlot({
    req(s$traj_sds, s$traj_pt)
    sds <- s$traj_sds
    rd  <- slingshot::reducedDim(sds)
    pt  <- s$traj_pt
    avg_pt <- rowMeans(pt, na.rm=TRUE)
    df <- data.frame(D1=rd[,1], D2=rd[,2], pseudotime=avg_pt)
    p <- ggplot(df, aes(D1, D2, color=pseudotime)) +
      geom_point(size=2, alpha=0.85) +
      viridis::scale_color_viridis(option="C", na.value="grey80", name="Pseudotime\n(mean)") +
      theme_classic(base_size=13) +
      labs(title=paste0("Slingshot trajectory — ", s$traj_meta$reduction),
           x=paste0(s$traj_meta$reduction, " 1"), y=paste0(s$traj_meta$reduction, " 2"))
    # overlay curves
    curves <- slingshot::slingCurves(sds)
    for (cu in curves) {
      cc <- as.data.frame(cu$s[cu$ord, 1:2, drop=FALSE]); names(cc) <- c("D1","D2")
      p <- p + geom_path(data=cc, aes(D1, D2), color="black", linewidth=1, inherit.aes=FALSE)
    }
    print(p)
  })

  # pseudotime overlaid on the object's UMAP (if present)
  output$traj_umap_pt <- renderPlot({
    req(s$traj_pt); seu <- traj_seu(); req(seu)
    if (!"umap" %in% names(seu@reductions)) {
      plot.new(); text(0.5,0.5,"No UMAP on this object — run Embeddings (⑦) first."); return() }
    um <- Seurat::Embeddings(seu, reduction="umap")
    pt <- s$traj_pt; avg_pt <- rowMeans(pt, na.rm=TRUE)
    common <- intersect(rownames(um), names(avg_pt))
    df <- data.frame(UMAP1=um[common,1], UMAP2=um[common,2], pseudotime=avg_pt[common])
    ggplot(df, aes(UMAP1, UMAP2, color=pseudotime)) +
      geom_point(size=2, alpha=0.85) +
      viridis::scale_color_viridis(option="C", na.value="grey85", name="Pseudotime\n(mean)") +
      theme_classic(base_size=13) +
      labs(title="Pseudotime on UMAP")
  })

  # a chosen protein's expression vs pseudotime for a chosen lineage
  output$traj_gene_plot <- renderPlot({
    req(s$traj_pt, input$traj_gene, input$traj_lineage)
    seu <- traj_seu(); req(seu)
    g <- input$traj_gene; req(g %in% rownames(seu))
    assay_use <- if ("SCT" %in% names(seu@assays)) "SCT" else input$s_assay
    ex <- tryCatch(as.numeric(Seurat::GetAssayData(seu, assay=assay_use, layer="data")[g, ]),
                   error=function(e) as.numeric(SeuratObject::LayerData(seu@assays[[assay_use]], layer="data")[g, ]))
    names(ex) <- colnames(seu)
    lin <- input$traj_lineage
    pt  <- s$traj_pt[, lin]
    common <- intersect(names(pt), names(ex))
    df <- data.frame(pseudotime=pt[common], expr=ex[common])
    df <- df[is.finite(df$pseudotime) & is.finite(df$expr), ]
    req(nrow(df) > 5)
    # Expression here is the data layer of the active assay: for VSN/scp-median
    # that is the covariate-ADJUSTED matrix (scplainer reconstruction), and cells
    # where the protein was not detected are dropped by the is.finite() filter
    # above rather than filled — so a sparse protein simply has fewer points.
    ggplot(df, aes(pseudotime, expr)) +
      geom_point(alpha=0.5, size=1.8, color="#5B8DB8") +
      geom_smooth(method="loess", se=TRUE, color="#C0392B", fill="#F5B7B1") +
      labs(caption = .disp_caption("data", "excluded")) +
      theme_classic(base_size=13) +
      labs(title=paste0(g, " along ", lin),
           x="Pseudotime", y=paste0(g, " (", assay_use, " data)"))
  })

  output$traj_tbl <- renderDT({
    req(s$traj_pt); seu <- traj_seu()
    pt <- as.data.frame(s$traj_pt)
    names(pt) <- if (is.null(colnames(s$traj_pt))) paste0("Lineage", seq_len(ncol(pt))) else colnames(s$traj_pt)
    pt$cell <- rownames(s$traj_pt)
    if (!is.null(seu) && s$traj_meta$cluster %in% names(seu@meta.data))
      pt$cluster <- as.character(seu@meta.data[rownames(s$traj_pt), s$traj_meta$cluster])
    pt <- pt[, c("cell", setdiff(names(pt), "cell"))]
    datatable(pt, options=list(pageLength=20, scrollX=TRUE), rownames=FALSE) %>%
      formatRound(setdiff(names(pt), c("cell","cluster")), 3)
  })
  output$traj_dl <- downloadHandler(
    filename=function() paste0("pseudotime_", Sys.Date(), ".csv"),
    content=function(file){ req(s$traj_pt); seu <- traj_seu()
      pt <- as.data.frame(s$traj_pt); pt$cell <- rownames(s$traj_pt)
      if (!is.null(seu) && s$traj_meta$cluster %in% names(seu@meta.data))
        pt$cluster <- as.character(seu@meta.data[rownames(s$traj_pt), s$traj_meta$cluster])
      readr::write_csv(pt, file) })

  output$s_log     <- renderText({ if(!length(s$log))"No activity yet." else paste(s$log,collapse="\n") })

  # ── proDA / NA-aware settings readout + downloads (⑫ Export) ────────────────
  # Live view of the same lines .log_proda_settings() writes at run time, so the
  # settings can be checked before committing to a long fit.
  output$s_proda_settings_txt <- renderText({
    if (!((input$s_norm_method %||% "sct") %in% .NA_AWARE))
      return(paste0("Not applicable \u2014 normalization is '",
                    input$s_norm_method %||% "sct",
                    "'.\nThe proDA / limma engines run on VSN, scp-median or log2 only."))
    paste(.proda_settings_lines("s_mk"), collapse="\n")
  })
  output$i_proda_settings_txt <- renderText({
    if (!((input$s_norm_method %||% "sct") %in% .NA_AWARE))
      return("Not applicable on this normalization route.")
    if (is.null(s$seu_int))
      return("No integrated object yet \u2014 run \u246a Integration first.")
    paste(.proda_settings_lines("i_mk"), collapse="\n")
  })

  output$s_dl_proda_settings <- downloadHandler(
    filename=function() paste0("scpviz_run_settings_", Sys.Date(), ".txt"),
    content=function(file){
      hdr <- c(paste0("SCP-Viz run settings  \u2014  ", format(Sys.time(), "%Y-%m-%d %H:%M:%S")),
               paste0("normalization: ", input$s_norm_method %||% "sct",
                      "  |  assay: ", input$s_assay %||% "(unset)"),
               "")
      body <- if ((input$s_norm_method %||% "sct") %in% .NA_AWARE) {
                c(.proda_settings_lines("s_mk"), "",
                  if (!is.null(s$seu_int)) .proda_settings_lines("i_mk") else
                    "\u246b integrated: no integrated object built.")
              } else {
                paste0("The proDA / limma engines are inactive on the '",
                       input$s_norm_method %||% "sct",
                       "' route \u2014 no NA-aware settings to report.")
              }
      writeLines(c(hdr, body), file)
      s_log("Run settings exported (.txt)")
    }
  )
  output$s_dl_log <- downloadHandler(
    filename=function() paste0("scpviz_activity_log_", Sys.Date(), ".txt"),
    content=function(file){
      validate(need(length(s$log) > 0, "No activity logged yet."))
      writeLines(s$log, file)
    }
  )
}

shinyApp(ui = ui, server = server)
